    CUSTOM_FRAME = "Other / custom"
    FRAME_MODELS: Dict[str, Dict[str, Any]] = {
        "6B": {"description": "Older heavy-duty frame. Exhaust ring, about 18 thermocouples.", "layout": "ring_tc", "exhaust_tc": 18},
        "7EA": {"description": "E-class frame. Exhaust ring, about 18 thermocouples.", "layout": "ring_tc", "exhaust_tc": 18},
        "7FA": {"description": "F-class frame. Exhaust ring with historian tags, about 27 thermocouples.", "layout": "ring_ttxd", "exhaust_tc": 27},
        "7HA": {"description": "H-class frame. Zone exhaust view, about 36 thermocouples on a full ring.", "layout": "zone_egt", "exhaust_tc": 36},
        "9E": {"description": "E-class frame. Exhaust ring, about 24 thermocouples.", "layout": "ring_tc", "exhaust_tc": 24},
        "9FA": {"description": "F-class frame. Exhaust ring with historian tags, about 31 thermocouples.", "layout": "ring_ttxd", "exhaust_tc": 31},
        "9HA": {"description": "H-class frame. Zone exhaust view with historian tags, about 48 thermocouples on a full ring.", "layout": "zone_named", "exhaust_tc": 48},
        CUSTOM_FRAME: {"description": "Pick a shipped tag layout, or type this unit's tags.", "layout": "", "exhaust_tc": None, "custom": True},
    }

    # Stored cases, labels, frames.json and the similarity index used to keep the layout id
    # in the frame field. Each old id loads as the frame model that uses that layout.
    # The order is 1:1, so a head trained on the old names still lights the same one-hot slot.
    # Conditioning (the one-hot, the similarity index and the novelty radius) keys on the
    # tag layout, not on the model id. See layout_of and conditioning_vocab. The alias
    # map below is only how an old stored id loads; it is not the conditioning key.
    FRAME_ALIASES: Dict[str, str] = {
        "ring_tc": "7EA",
        "ring_ttxd": "7FA",
        "zone_egt": "7HA",
        "zone_named": "9HA",
    }
    # Auto-detect and the synthetic dataset use the same pairing. Historian ring files are
    # labeled 7FA and historian zone files are labeled 9HA; the friendly-tag twins are 7EA and 7HA.
    DEFAULT_FRAME_FOR_LAYOUT: Dict[str, str] = dict(FRAME_ALIASES)
    _ALIAS_OF: Dict[str, str] = {v: k for k, v in FRAME_ALIASES.items()}


    def canonical_frame(name: Any) -> str:
        """Frame-model id for a stored or typed name.

        Old layout ids become the frame model in ``FRAME_ALIASES``. ``7fa`` matches ``7FA``.
        ``other`` and ``custom`` match ``Other / custom``. An empty name stays empty.
        A Teach-added id that is not in the table is returned unchanged.
        """
        raw = str(name or "").strip()
        if not raw or raw in ("auto", "None", "none"):
            return ""
        if raw in FRAME_ALIASES:
            return FRAME_ALIASES[raw]
        if raw in FRAME_MODELS:
            return raw
        low = raw.lower().replace("_", " ").replace("-", " ")
        low = " ".join(low.split())
        if low in ("other", "custom", "other / custom", "other custom"):
            return CUSTOM_FRAME
        for mid in FRAME_MODELS:
            if raw.lower() == mid.lower():
                return mid
        folded = raw.lower()
        for old, new in FRAME_ALIASES.items():
            if folded == old.lower():
                return new
        return raw


    def alias_of(frame: Any) -> str:
        """Old layout id for a frame model, or "" when this model was not one of the four stored ids."""
        return _ALIAS_OF.get(canonical_frame(frame) or str(frame or "").strip(), "")


    def migrate_frame_fields(rec: Dict[str, Any]) -> Dict[str, Any]:
        """Copy a record and map ``frame`` / ``frame_type`` onto the current frame-model ids.

        The file on disk is left as it was. Nothing is dropped: an unknown id stays, and a
        known old id is renamed in the copy only.
        """
        if not isinstance(rec, dict):
            return rec
        out = dict(rec)
        for key in ("frame", "frame_type"):
            if out.get(key):
                out[key] = canonical_frame(out[key]) or out[key]
        return out


    def migrate_frame_table(table: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        """Rename keys that are old layout ids. The first name for a frame wins; values are kept."""
        out: Dict[str, Any] = {}
        for name, value in (table or {}).items():
            key = canonical_frame(name) or str(name)
            if key not in out:
                out[key] = value
        return out


    def frames_file(data_dir: Path) -> Path:
        """Where Teach stores frames added on this machine (the CONFIG table stays the shipped default)."""
        return Path(data_dir) / "e2e" / "frames.json"


    def load_taught_frames(data_dir: Path) -> Dict[str, Dict[str, Any]]:
        """Frames added from Teach. An old layout id used as a key is renamed on load. Missing file means none."""
        path = frames_file(data_dir)
        if not path.is_file():
            return {}
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return {}
        if not isinstance(data, dict):
            return {}
        # A key that is already the new id wins over an aliased copy of the same frame.
        out: Dict[str, Dict[str, Any]] = {}
        for key, spec in data.items():
            fid = canonical_frame(key) or str(key)
            if fid not in out or str(key) == fid:
                out[fid] = spec if isinstance(spec, dict) else {}
        return out


    def _layout_spec(layout_id: str) -> Dict[str, Any]:
        """One LAYOUTS row, copied, with the layout id recorded on it."""
        spec = dict(LAYOUTS.get(layout_id) or {})
        if "roles" in spec:
            spec["roles"] = {k: list(v) for k, v in (spec.get("roles") or {}).items()}
        spec["layout"] = layout_id if layout_id in LAYOUTS else ""
        return spec


    def model_spec(model_id: str) -> Dict[str, Any]:
        """Tag spec for one shipped frame model: its layout's tags, plus the model metadata."""
        model = FRAME_MODELS.get(model_id) or {}
        layout = str(model.get("layout") or "")
        spec = _layout_spec(layout) if layout in LAYOUTS else {"roles": {}, "ring_prefix": "", "zone_prefix": "", "layout": ""}
        spec["description"] = model.get("description") or spec.get("description") or ""
        spec["layout"] = layout
        spec["exhaust_tc"] = model.get("exhaust_tc")
        spec["custom"] = bool(model.get("custom"))
        return spec


    def merged_frame_maps(data_dir: Optional[Path] = None) -> Dict[str, Dict[str, Any]]:
        """Shipped frame models plus any frame the engineer added. Taught names override a shipped id.

        Each value is a tag spec (prefixes, roles, optional explicit tag lists) so ``apply_frame``
        can map that frame's columns. A taught frame may name a ``layout`` instead of listing tags.
        """
        out = {fid: model_spec(fid) for fid in FRAME_MODELS}
        if data_dir is None:
            return out
        for fid, spec in load_taught_frames(data_dir).items():
            merged: Dict[str, Any] = {}
            layout = str((spec or {}).get("layout") or "")
            if layout in LAYOUTS:
                merged.update(_layout_spec(layout))
            merged.update(spec or {})
            out[fid] = merged
        return out


    def frame_maps_for(data_dir: Optional[Path], frame: Optional[str] = None, layout: Optional[str] = None,
                       spec: Optional[Dict[str, Any]] = None) -> Dict[str, Dict[str, Any]]:
        """Frame-id -> tag spec for one run.

        ``Other / custom`` with a layout id uses that layout's tags and still stores the custom
        frame id. ``spec`` is the tag spec a stored case was analyzed with (see ``custom_frame_spec``);
        it replaces that frame's row so a reload maps the same columns as the original run.
        Any other frame keeps the spec from ``merged_frame_maps``.
        """
        maps = merged_frame_maps(data_dir)
        fid = canonical_frame(frame) if frame else ""
        if fid and isinstance(spec, dict) and spec:
            maps[fid] = dict(spec)
            return maps
        lay = str(layout or "").strip()
        if fid == CUSTOM_FRAME and lay:
            if lay not in LAYOUTS:
                raise ValueError(f"unknown layout '{lay}'. Choices: {', '.join(LAYOUTS)}")
            spec = _layout_spec(lay)
            spec["description"] = FRAME_MODELS[CUSTOM_FRAME]["description"]
            spec["custom"] = True
            maps[CUSTOM_FRAME] = spec
        return maps


    def custom_frame_spec(maps: Optional[Dict[str, Any]], frame_type: str) -> Optional[Dict[str, Any]]:
        """Tag spec to store with a case analyzed as ``Other / custom``, or None.

        Typed tags and a layout picked for Other / custom exist only in that run's table, and the
        label stores just the frame id. Saving this spec on the report and the label lets a retrain,
        a re-embed or a plot reload map the same columns the case was analyzed with.
        """
        if frame_type != CUSTOM_FRAME:
            return None
        spec = (maps or {}).get(CUSTOM_FRAME) or {}
        if not any(spec.get(k) for k in ("ring", "zones", "roles", "ring_prefix", "zone_prefix")):
            return None
        return json.loads(json.dumps(spec, default=str))


    def layout_of(frame: Any = "", layout: Any = "", spec: Optional[Dict[str, Any]] = None,
                  data_dir: Optional[Path] = None) -> str:
        """Tag layout that conditions this frame (FRAME_MODELS[m]["layout"]).

        Several models share one layout: 6B, 7EA and 9E are ``ring_tc``; 7FA and 9FA
        are ``ring_ttxd``. They must share one one-hot column and one novelty radius,
        or a model with no training cases is pushed onto an empty slot and looks unfamiliar.
        Other / custom, and a taught frame, use the layout the engineer picked
        (``layout``, ``spec["layout"]``, or the taught row). A hint that names a
        different layout than a shipped model is ignored: that model already has a layout,
        and the hint would disagree with the tags the case was read with. An old layout
        id is already a layout. Empty means there is nothing to condition on (zero one-hot,
        shared novelty radius).
        """
        hinted = str(layout or "").strip()
        spec_lay = ""
        if isinstance(spec, dict):
            spec_lay = str(spec.get("layout") or "").strip()
        raw = str(frame or "").strip()
        if raw in ("auto", "None"):
            raw = ""
        if raw in LAYOUTS:
            return raw
        fid = canonical_frame(raw) if raw else ""
        model_lay = str((FRAME_MODELS.get(fid) or {}).get("layout") or "")
        if model_lay in LAYOUTS:
            return model_lay
        for candidate in (spec_lay, hinted):
            if candidate in LAYOUTS:
                return candidate
        if data_dir is not None and fid:
            taught = load_taught_frames(Path(data_dir)).get(fid) or {}
            taught_lay = str((taught or {}).get("layout") or "")
            if taught_lay in LAYOUTS:
                return taught_lay
        return ""


    def conditioning_vocab(data_dir: Optional[Path] = None) -> List[str]:
        """One-hot columns for a frame-conditioned head: tag layouts, not frame-model ids.

        Shipped layouts come first, in ``LAYOUTS`` order. A taught frame that names one
        of those layouts does not add a column, so it shares the slot. ``data_dir`` is
        accepted so a later taught layout can be appended without changing callers;
        shipped layouts are the whole vocabulary today.
        """
        names = list(LAYOUTS)
        if data_dir is not None:
            for spec in load_taught_frames(Path(data_dir)).values():
                lay = str((spec or {}).get("layout") or "")
                if lay in LAYOUTS and lay not in names:
                    names.append(lay)
        return names


    def frame_vocab(data_dir: Optional[Path] = None) -> List[str]:
        """Dropdown order: shipped frame models first, then taught names alphabetically.

        This is the list the engineer picks from. The one-hot uses ``conditioning_vocab``
        (layouts), not this list, so two models that share a layout do not each get a slot.
        """
        maps = merged_frame_maps(data_dir)
        names = [k for k in FRAME_MODELS if k in maps]
        names += sorted(k for k in maps if k not in FRAME_MODELS)
        return names


    def normalize_frame_arg(name: Optional[str], data_dir: Optional[Path] = None) -> Optional[str]:
        """CLI ``--frame`` value. Empty means detect. Unknown names raise, and the message lists the choices.

        A Teach-added frame is accepted. An old layout id is accepted and returned as its frame model.
        """
        raw = str(name or "").strip()
        if not raw or raw.lower() == "auto":
            return None
        fid = canonical_frame(raw)
        known = set(frame_vocab(data_dir))
        if fid not in known:
            raise ValueError(f"unknown frame '{raw}'. Choices: {', '.join(frame_vocab(data_dir))}")
        return fid


    def frame_of_row(row: Dict[str, Any]) -> str:
        """Frame model id for a manifest row or an engineer label.

        ``frame_type`` wins, then a ``frame`` value that is a shipped model or an old layout id.
        A free-text note that is not in the frame list does not select a model when the row also
        carries ``layout``; ``layout`` plus ``alt_tags`` then pick the synthetic frame
        (historian ring -> 7FA, historian zones -> 9HA, friendly twins -> 7EA and 7HA).
        """
        explicit = str(row.get("frame_type") or "").strip()
        if explicit and explicit not in ("auto", "None"):
            return canonical_frame(explicit) or explicit
        named = str(row.get("frame") or "").strip()
        if named and named not in ("auto", "None"):
            canon = canonical_frame(named)
            if canon in FRAME_MODELS or (canon and canon != named):
                return canon
            if not row.get("layout"):
                return named
        layout = str(row.get("layout") or "")
        alt = bool(row.get("alt_tags"))
        if layout == "zones":
            return FRAME_ALIASES["zone_named" if alt else "zone_egt"]
        if layout == "ring":
            return FRAME_ALIASES["ring_ttxd" if alt else "ring_tc"]
        return ""


    def _as_bool(value: Any) -> bool:
        """Function _as_bool."""
        if isinstance(value, bool):
            return value
        return str(value).strip().lower() in {"1", "true", "yes", "on"}


    def _default_threads() -> int:
        """Function _default_threads."""
        n = os.cpu_count() or 4
        # Physical cores are usually half the logical count; llama.cpp is fastest there.
        return max(1, min(8, n // 2 if n >= 4 else n))


    @dataclass
    class Settings:
        # The one LLM: Gemma 4 12B instruct Q4_K_M (default models/gemma-4-12b-it-Q4_K_M.gguf when unset)
        """Class Settings."""
        gguf_path: Optional[Path] = None
        llama_bin_dir: Optional[Path] = None  # legacy llama.cpp binaries (not needed with llama-cpp-python)
        tspulse_dir: Optional[Path] = None  # TS Pulse anomaly-detection snapshot (rule path)
        tspulse_clf_dir: Path = field(default_factory=lambda: ROOT / "models" / "tspulse" / "clf")
        e2e_model_dir: Path = field(default_factory=lambda: ROOT / "models" / "e2e")
        data_dir: Path = field(default_factory=lambda: ROOT / "data")
        # Process maps (knowledge/*.md, shipped) + engineer documents added from the UI (knowledge/user/*.md)
        knowledge_dir: Path = field(default_factory=lambda: KNOWLEDGE_DIR)
        use_llm: bool = True
        use_tspulse: bool = True
        # LLM runtime: device auto|gpu|cpu (GPU -> CPU fallback is automatic)
        device: str = "auto"
        n_gpu_layers: str = "auto"
        llm_threads: int = field(default_factory=_default_threads)
        llm_ctx: int = 6144
        llm_max_tokens: int = 900
        llm_timeout_s: int = 900
        # Learning loop: retrain the classifier head after every N new labels
        e2e_retrain_every: int = 5
        # Residual feed (second TS Pulse view): auto = TS Pulse reconstruction when the weights in
        # tspulse_dir load, else the robust-z fallback; robust_z = always the fallback
        residual_mode: str = "auto"
        # Learned path. "legacy" is the fixed 14-channel bundle. "peralert" keys the index,
        # head and novelty on one alert type. Stays "legacy" until acceptance passes.
        # A stored "profiles" value is loaded as "legacy".
        e2e_mode: str = "legacy"
        # tspulse_ci embeds each profile channel alone. stats is the 48-d fallback (and what
        # unit tests set via SENTINEL_EMBEDDER). legacy14 is the transitional comparison embedder.
        embedder: str = "tspulse_ci"
        # Site alert-type JSON. None means data_dir/e2e/profiles, filled in by load_settings
        # after data_dir is known, so a test's temp data dir does not read the plant folder.
        profiles_dir: Optional[Path] = None
        sources: Dict[str, str] = field(default_factory=dict)

        @property
        def cases_dir(self) -> Path:
            """Function cases_dir."""
            return self.data_dir / "cases"

        @property
        def feedback_file(self) -> Path:
            """Function feedback_file."""
            return self.data_dir / "feedback.jsonl"

        def llama_binary(self) -> Optional[Path]:
            """llama-completion is the non-interactive binary; llama-cli is the fallback."""
            if not self.llama_bin_dir:
                return None
            for name in ("llama-completion.exe", "llama-completion", "llama-cli.exe", "llama-cli"):
                p = self.llama_bin_dir / name
                if p.is_file():
                    return p
            return None

        def gguf_available(self) -> bool:
            """Function gguf_available."""
            return bool(self.gguf_path and self.gguf_path.is_file())

        def llm_ready(self) -> bool:
            """Function llm_ready."""
            from . import llm_runtime

            return llm_runtime.available(self)

        def describe(self) -> Dict[str, Any]:
            """Function describe."""
            return {
                "gguf_path": _rel(self.gguf_path),
                "gguf_found": self.gguf_available(),
                "llama_binary": _rel(self.llama_binary()),
                "tspulse_dir": _rel(self.tspulse_dir),
                "data_dir": _rel(self.data_dir),
                "knowledge_dir": _rel(self.knowledge_dir),
                "use_llm": self.use_llm,
                "use_tspulse": self.use_tspulse,
                "device": self.device,
                "n_gpu_layers": self.n_gpu_layers,
                "tspulse_clf_dir": _rel(self.tspulse_clf_dir),
                "e2e_model_dir": _rel(self.e2e_model_dir),
                "e2e_retrain_every": self.e2e_retrain_every,
                "residual_mode": self.residual_mode,
                "e2e_mode": self.e2e_mode,
                "embedder": self.embedder,
                "profiles_dir": _rel(self.profiles_dir),
                "llm_threads": self.llm_threads,
                "llm_ctx": self.llm_ctx,
                "llm_max_tokens": self.llm_max_tokens,
                "sources": dict(self.sources),
            }


    def _rel(p: Optional[Path]) -> Optional[str]:
        """Path relative to the app folder when inside it (portable reports and status output)."""
        if p is None:
            return None
        try:
            return Path(p).resolve().relative_to(ROOT).as_posix()
        except ValueError:
            return str(p)


    def _project_defaults() -> Dict[str, Any]:
        """Defaults that only point inside this project (models/). LLM GGUFs come from the profile."""
        models = ROOT / "models"
        out: Dict[str, Any] = {}
        if (models / "llama-cpp-bin").is_dir():
            out["llama_bin_dir"] = models / "llama-cpp-bin"
        if (models / "tspulse" / "ad").is_dir():
            out["tspulse_dir"] = models / "tspulse" / "ad"
        elif (models / "tspulse").is_dir():
            out["tspulse_dir"] = models / "tspulse"
        return out


    def load_settings(overrides: Optional[Dict[str, Any]] = None) -> Settings:
        """Function load_settings."""
        values: Dict[str, Any] = {}
        sources: Dict[str, str] = {}

        for key, val in _project_defaults().items():
            values[key] = val
            sources[key] = "default"

        if LOCAL_SETTINGS_FILE.is_file():
            try:
                local = json.loads(LOCAL_SETTINGS_FILE.read_text(encoding="utf-8"))
                for key, val in local.items():
                    if val is None or key.startswith("_"):
                        continue
                    values[key] = val
                    sources[key] = "settings.local.json"
            except (OSError, ValueError):
                pass

        for env, key in _ENV_MAP.items():
            val = os.environ.get(env)
            if val not in (None, ""):
                values[key] = val
                sources[key] = f"env:{env}"

        for key, val in (overrides or {}).items():
            if val is not None:
                values[key] = val
                sources[key] = "override"

        s = Settings()
        for key, val in values.items():
            if not hasattr(s, key) or key == "sources":
                continue
            if key in _BOOL_KEYS:
                val = _as_bool(val)
            elif key in _INT_KEYS:
                val = int(val)
            elif key in _PATH_KEYS:
                val = Path(val).expanduser()
                if not val.is_absolute():  # relative paths are relative to the app folder (portable)
                    val = ROOT / val
            elif key == "n_gpu_layers":
                val = str(val).strip().lower()
            elif key in _CHOICE_KEYS:
                val = str(val).strip().lower()
                if key == "e2e_mode" and val == "profiles":
                    # The retired mode name is the 14-channel path.
                    val = "legacy"
                allowed = _CHOICE_KEYS[key]
                if val not in allowed:
                    # An unknown choice keeps the dataclass default. doctor and the
                    # round-trip test can see the rejected value was not applied.
                    continue
            setattr(s, key, val)
        # A site that did not set profiles_dir keeps profiles next to the rest of data/e2e.
        if s.profiles_dir is None:
            s.profiles_dir = Path(s.data_dir) / "e2e" / "profiles"
        s.sources = sources
        return s
