if False:  # compiled by exec_section('sentinel.limits'); not executed as part of this module
    """All decision thresholds in one place (echoed into every report's audit trail).

    Values are generic engineering defaults for heavy-duty / aero units at baseload, not OEM
    limits. Sites should adjust them to their own frame-specific alarm/trip settings.
    """

    # @@future@@ from __future__ import annotations

    from typing import Any, Dict

    COLD_SPOT: Dict[str, Any] = {
        # TC deviation below its own baseline that counts as "cold" (deg C)
        "cold_excess_C": 8.0,
        # Minimum sustained duration for an event (minutes)
        "min_event_minutes": 60,
        # Neighbour TCs are part of the sector if colder than this fraction of the primary depth
        "sector_member_fraction": 0.30,
        # Onset faster than this (minutes from 10% to 90% depth) is treated as a step change
        "step_onset_minutes": 20,
        # Depth that makes a true cold sector "high" severity (deg C)
        "high_depth_C": 25.0,
        # Spread considered approaching protection (deg C) — HETS precursor
        "spread_alarm_C": 40.0,
        # Fuel-flow rise (fraction) that indicates control compensation
        "fuel_comp_fraction": 0.004,
    }

    COMBUSTION_DYNAMICS: Dict[str, Any] = {
        # Site dynamics limits (psi, broadband / dominant tone amplitude)
        "alert_psi": 1.0,
        "alarm_psi": 2.0,
        "high_psi": 3.0,
        # Event must stay above alert for at least this long (minutes, rolling-median envelope)
        "min_event_minutes": 30,
        # Rolling window for the envelope (minutes)
        "envelope_minutes": 10,
        # Correlation with EGT spread / vibration that counts as "coupled"
        "coupling_r": 0.4,
        # Hours above high limit that raise hardware (liner / transition) risk
        "hardware_risk_hours": 6.0,
    }

    HETS_TRIP: Dict[str, Any] = {
        # Load collapse that counts as a trip if no trip flag exists (fraction of pre-trip load)
        "load_collapse_fraction": 0.5,
        # Pre-trip look-back window (hours)
        "pretrip_hours": 6.0,
        # Spread increase over baseline that counts as a build-up (deg C)
        "spread_rise_C": 15.0,
        # A spread rise completed in <= this many minutes is a step (instrument suspicion)
        "step_rise_minutes": 20,
        # Zone deviation (deg C) that marks a zone as hot/cold at peak spread
        "zone_dev_C": 8.0,
        # Post-restart spread considered normal (multiple of baseline spread + margin)
        "restart_spread_margin_C": 10.0,
    }

    GENERAL: Dict[str, Any] = {
        # Robust z-score for anomaly scan
        "anomaly_z": 6.0,
        # Minimum rows for meaningful analysis
        "min_rows": 200,
        # Max fraction of missing values before a channel is "poor quality"
        "max_missing_fraction": 0.2,
        # Similarity above which an engineer's feedback is applied to a new case
        "feedback_apply_similarity": 0.80,
        # Similarity above which a case is shown as a "similar past case"
        "feedback_show_similarity": 0.55,
        # IGV / fuel vs load regression residual (robust z) that suggests an actuator issue
        "actuator_residual_z": 8.0,
    }


    def all_limits() -> Dict[str, Dict[str, Any]]:
        """Function all_limits."""
        return {
            "cold_spot": dict(COLD_SPOT),
            "combustion_dynamics": dict(COMBUSTION_DYNAMICS),
            "hets_trip": dict(HETS_TRIP),
            "general": dict(GENERAL),
        }
