# =============================================================================
# sentinel.notes
# Pull unit id, first-out text and free-text hints out of the engineer's notes.
# =============================================================================
# <<<<<<< SECTION sentinel.notes sentinel/notes.py
if False:  # compiled by exec_section('sentinel.notes'); not executed as part of this module
    """Light-weight interpretation of the engineer's free-text notes.

    Only a few facts that change decisions are extracted; the raw notes always go to the report
    and to the LLM. Everything extracted is listed in the audit trail.
    """

    # @@future@@ from __future__ import annotations

    import re
    from dataclasses import asdict, dataclass, field
    from typing import Any, Dict, List, Optional

    _FLAGS = {
        "tc_work": r"\b(tc|thermocouple)s?\s*-?\d*\b[^.]{0,40}(replac|repair|swap|rewir|work|harness)|harness|new (tc|thermocouple)",
        "recent_tuning": r"\b(re-?)?tun(ed|ing|e)\b",
        "borescope_done": r"bore?scope|\bbsi\b",
        "outage": r"\boutage\b|combustion inspection|\bci\b|hot gas path|\bhgp\b|major inspection",
        "fuel_nozzle_work": r"fuel nozzle|nozzle (work|replac|clean)",
        "restarted": r"\brestart(ed)?\b|back online|returned to service",
        "repeat": r"\brepeat|recurr|\bagain\b|second time|prior (event|case|alarm)|previous (event|alarm)",
        "probe_issue": r"(probe|transducer|cable|sensor)[^.]{0,30}(fault|issue|bad|fail|suspect|noisy)",
        "lvdt": r"\blvdt\b|position feedback|servo|valve position|calibrat",
        "fuel_quality": r"wobbe|fuel gas (temp|composition|quality)|\blng\b|fuel quality|fuel switch",
        "load_change": r"load (change|ramp|swing)|ramping|fuel transfer|load reject",
        "operator_reports_noise": r"\b(hum|humming|tone|rumble|noise|loud)\b",
    }

    _FRAME_RE = re.compile(
        r"\b(7F\.?0?[0-9]|7FA(?:\.0?[0-9])?|7HA\.?[0-9]*|9F\.?0?[0-9]|9FA|9HA\.?[0-9]*|6B|6F\.?0?[0-9]|"
        r"LM\s?[0-9]{4}\w*|frame\s*[0-9]\w*)\b",
        re.I,
    )
    _UNIT_RE = re.compile(r"\b(unit|gt|ct|u)\s*[-#]?\s*([0-9]{1,2}[a-z]?)\b", re.I)
    _TC_RE = re.compile(r"\bTC\s*[-#]?\s*([0-9]{1,2})\b", re.I)
    _FIRST_OUT_RE = re.compile(r"first[\s-]*out\s*(?:was|=|:|-|is)?\s*([a-z0-9 /_-]{3,40})", re.I)


    @dataclass
    class NotesInfo:
        """Class NotesInfo."""
        raw: str = ""
        unit: Optional[str] = None
        frame: Optional[str] = None
        tcs_mentioned: List[int] = field(default_factory=list)
        first_out: Optional[str] = None
        flags: Dict[str, bool] = field(default_factory=dict)

        def has(self, flag: str) -> bool:
            """Function has."""
            return bool(self.flags.get(flag))

        def interpreted(self) -> List[str]:
            """Function interpreted."""
            out = []
            if self.unit:
                out.append(f"unit = {self.unit}")
            if self.frame:
                out.append(f"frame = {self.frame}")
            if self.tcs_mentioned:
                out.append("TCs mentioned = " + ", ".join(f"TC{n}" for n in self.tcs_mentioned))
            if self.first_out:
                out.append(f"first-out = {self.first_out}")
            out += [f"flag: {k}" for k, v in sorted(self.flags.items()) if v]
            return out

        def to_dict(self) -> Dict[str, Any]:
            """Function to_dict."""
            return asdict(self)


    _NEGATION = re.compile(r"\b(no|not|without|never|nothing|none|neither|nor|denies|ruled out)\b")
    _CLAUSE_BREAK = re.compile(r"[.;!?\n]|\bbut\b|\bhowever\b|\balthough\b")


    def _affirmed(pattern: str, low: str) -> bool:
        """True if the pattern occurs at least once without a negation earlier in the same clause."""
        for m in re.finditer(pattern, low):
            before = low[max(0, m.start() - 40) : m.start()]
            cuts = list(_CLAUSE_BREAK.finditer(before))
            if cuts:
                before = before[cuts[-1].end() :]
            if not _NEGATION.search(before):
                return True
        return False


    def parse_notes(text: str) -> NotesInfo:
        """Function parse_notes."""
        text = (text or "").strip()
        info = NotesInfo(raw=text)
        if not text:
            return info
        m = _UNIT_RE.search(text)
        if m:
            prefix, num = m.group(1), m.group(2).upper()
            info.unit = f"Unit {num}" if prefix.lower() == "unit" else f"{prefix.upper()}{num}"
        f = _FRAME_RE.search(text)
        if f:
            info.frame = f.group(1).upper().replace(" ", "")
        info.tcs_mentioned = sorted({int(x) for x in _TC_RE.findall(text)})
        fo = _FIRST_OUT_RE.search(text)
        if fo and _affirmed(re.escape(fo.group(0).lower()), text.lower()):
            info.first_out = fo.group(1).strip(" .,;").lower()
        low = text.lower()
        info.flags = {k: _affirmed(p, low) for k, p in _FLAGS.items()}
        return info


    def first_out_is_spread(info: NotesInfo) -> Optional[bool]:
        """True if notes say first-out was exhaust spread/HETS, False if something else, None if unknown."""
        if not info.first_out:
            return None
        fo = info.first_out
        if re.search(r"spread|hets|exhaust|ttx|temp", fo):
            return True
        return False
# >>>>>>> END sentinel.notes

# =============================================================================
# sentinel.charts
# Evidence charts and the residual view. Altair keeps the heatmap contract; the UI plots use plotly (matplotlib, then Altair) with one local palette. No remote assets.
# =============================================================================
# <<<<<<< SECTION sentinel.charts sentinel/charts.py
if False:  # compiled by exec_section('sentinel.charts'); not executed as part of this module
    """Evidence chart: small multiples (one panel per channel, shared time axis) with the event shaded.

    One panel per channel because the channels have different units — never a dual axis.
    Colours: series slot 1 (validated), event window = warning status fill, always text-labelled.
    """

    # @@future@@ from __future__ import annotations

    from typing import Any, Dict, List, Optional

    import numpy as np
    import pandas as pd

    SERIES = "#2a78d6"
    EVENT_FILL = "#fab219"
    INK = "#0b0b0b"
    MUTED = "#898781"
    GRID = "#e1e0d9"
    AXIS = "#c3c2b7"
    MAX_POINTS = 1500


    def chart_frame(case_df: pd.DataFrame, channels: List[str], ts: Optional[pd.Series], focus: Optional[List[int]] = None) -> pd.DataFrame:
        """Function chart_frame."""
        df = case_df.copy()
        df["_t"] = ts.values if ts is not None else np.arange(len(df))
        if focus:
            df = df.iloc[max(0, focus[0]) : focus[1] + 1]
        df["_i"] = df.index
        step = max(1, int(np.ceil(len(df) / MAX_POINTS)))
        cols = [c for c in channels if c in df.columns]
        if step > 1:
            grp = np.arange(len(df)) // step
            agg = df.groupby(grp).agg({"_t": "first", "_i": "first", **{c: "mean" for c in cols}})
        else:
            agg = df[["_t", "_i"] + cols]
        long = agg.melt(id_vars=["_t", "_i"], value_vars=cols, var_name="channel", value_name="value")
        long.attrs["bucket"] = step
        return long


    def evidence_chart(case_df: pd.DataFrame, ts: Optional[pd.Series], chart: Dict[str, Any], width: int = 760) -> Optional[Any]:
        """Function evidence_chart."""
        import altair as alt

        channels = [c for c in (chart.get("channels") or []) if c in case_df.columns][:4]
        if not channels:
            return None
        data = chart_frame(case_df, channels, ts, chart.get("focus"))
        x_type = "T" if ts is not None else "Q"
        x_title = "Time" if ts is not None else "Sample"
        ev = chart.get("event")
        ev_df = None
        if ev:
            a, b = int(ev[0]), int(ev[1])
            t0 = ts.iloc[a] if ts is not None else a
            t1 = ts.iloc[min(b, len(case_df) - 1)] if ts is not None else b
            ev_df = pd.DataFrame({"start": [t0], "end": [t1]})

        panels = []
        for i, ch in enumerate(channels):
            d = data[data["channel"] == ch]
            hover = alt.selection_point(name=f"hover{i}", fields=["_t"], nearest=True, on="pointerover", empty=False, clear="pointerout")
            base = alt.Chart(d).encode(x=alt.X(f"_t:{x_type}", title=x_title if i == len(channels) - 1 else None, axis=alt.Axis(labels=i == len(channels) - 1)))
            line = base.mark_line(color=SERIES, strokeWidth=2).encode(y=alt.Y("value:Q", title=None, scale=alt.Scale(zero=False)))
            pts = base.mark_point(size=80, opacity=0).encode(
                y="value:Q",
                tooltip=[alt.Tooltip(f"_t:{x_type}", title=x_title), alt.Tooltip("value:Q", title=ch, format=".3f")],
            ).add_params(hover)
            rule = base.mark_rule(color=MUTED, strokeWidth=1).encode(opacity=alt.condition(hover, alt.value(1), alt.value(0)))
            dot = base.mark_circle(size=64, color=SERIES, stroke="#fcfcfb", strokeWidth=2).encode(y="value:Q", opacity=alt.condition(hover, alt.value(1), alt.value(0)))
            layers = []
            if ev_df is not None:
                band = alt.Chart(ev_df).mark_rect(color=EVENT_FILL, opacity=0.18).encode(x=f"start:{x_type}", x2="end")
                layers.append(band)
            layers += [line, rule, dot, pts]
            title = ch + (f"   (shaded = {chart.get('event_label', 'detected event window')})" if i == 0 and ev_df is not None else "")
            panels.append(alt.layer(*layers).properties(width=width, height=110, title=alt.TitleParams(title, anchor="start", color=INK, fontSize=12, fontWeight="normal")))
        return (
            alt.vconcat(*panels, spacing=8)
            .resolve_scale(x="shared")
            .configure_axis(gridColor=GRID, domainColor=AXIS, tickColor=AXIS, labelColor=MUTED, titleColor=MUTED)
            .configure_view(stroke=None)
        )


    # Residual heatmap: binned sequential = one hue light -> dark (blue ramp steps 250 / 400 / 550 / 700,
    # validated as an ordinal ramp: the lightest step clears 2:1 on the surface);
    # below the abnormal level the cell recedes to the surface tone.
    RESID_BINS = [6.0, 10.0, 20.0, 50.0]
    RESID_COLORS = ["#f0efec", "#86b6ef", "#3987e5", "#1c5cab", "#0d366b"]
    RESID_LABELS = ["< 6 (normal)", "6-10 (abnormal)", "10-20", "20-50", ">= 50"]


    def residual_chart(res: Dict[str, Any], width: int = 760) -> Optional[Any]:
        """Channels x time heatmap of the residual score (baseline sigmas) with onset markers (residual.py)."""
        import altair as alt

        prof = (res or {}).get("profile") or {}
        chans, times, M = prof.get("channels") or [], prof.get("times") or [], prof.get("matrix") or []
        if not chans or not times:
            return None
        t = pd.to_datetime(pd.Series(times), errors="coerce")
        if t.isna().all():
            t = pd.Series(np.arange(len(times)), dtype=float)
            x_type = "Q"
        else:
            x_type = "T"
        step = (t.iloc[1] - t.iloc[0]) if len(t) > 1 else (pd.Timedelta(minutes=1) if x_type == "T" else 1.0)
        events = {e["channel"]: e for e in (res.get("events") or [])}
        order = sorted(chans, key=lambda c: (events[c]["onset_idx"] if c in events else 10**9, chans.index(c)))
        rows = []
        for ci, ch in enumerate(chans):
            for ti in range(len(times)):
                v = float(M[ci][ti])
                b = int(np.searchsorted(RESID_BINS, v, side="right"))
                rows.append({"channel": ch, "t0": t.iloc[ti], "t1": t.iloc[ti] + step, "score": v, "level": RESID_LABELS[b]})
        cells = pd.DataFrame(rows)
        y = alt.Y("channel:N", sort=order, title=None, scale=alt.Scale(paddingInner=0.15))
        heat = alt.Chart(cells).mark_rect().encode(
            x=alt.X(f"t0:{x_type}", title="Time" if x_type == "T" else "Sample"),
            x2="t1",
            y=y,
            color=alt.Color("level:N", sort=RESID_LABELS, scale=alt.Scale(domain=RESID_LABELS, range=RESID_COLORS),
                            legend=alt.Legend(title="residual score (baseline σ)", orient="bottom", direction="horizontal", labelColor=MUTED, titleColor=MUTED)),
            tooltip=[alt.Tooltip("channel:N"), alt.Tooltip(f"t0:{x_type}", title="time"), alt.Tooltip("score:Q", format=".1f")],
        )
        layers = [heat]
        ev_rows = []
        for c in order:
            e = events.get(c)
            if e is None:
                continue
            ot = pd.to_datetime(e["onset"], errors="coerce") if x_type == "T" else e["onset_idx"]
            if x_type == "T" and pd.isna(ot):
                continue
            size = e["peak"] if e["shape"] in ("spikes", "oscillation") else e["delta"]
            ev_rows.append({"channel": c, "onset": ot, "what": f"{e['shape']} {e['direction']} {abs(size)} {e['unit']} from {e['onset']}",
                            "order": len(ev_rows) + 1})
        if ev_rows:
            ev = pd.DataFrame(ev_rows)
            layers.append(alt.Chart(ev).mark_point(shape="triangle-right", size=110, filled=True, color=INK, stroke="#fcfcfb", strokeWidth=2).encode(
                x=f"onset:{x_type}", y=y,
                tooltip=[alt.Tooltip("order:Q", title="onset #"), alt.Tooltip("channel:N"), alt.Tooltip("what:N", title="onset")]))
            layers.append(alt.Chart(ev).mark_text(align="left", dx=8, dy=-1, fontSize=11, color=INK).encode(
                x=f"onset:{x_type}", y=y, text=alt.Text("order:Q")))
        return (
            alt.layer(*layers)
            .properties(width=width, height=max(120, 22 * len(chans)),
                        title=alt.TitleParams("Residual view: score per channel over time (▶ = onset, numbered in order)", anchor="start", color=INK, fontSize=12, fontWeight="normal"))
            .configure_axis(gridColor=GRID, domainColor=AXIS, tickColor=AXIS, labelColor=MUTED, titleColor=MUTED)
            .configure_view(stroke=None)
        )


    # One palette for the four review plots. Hex only: nothing is fetched at draw time.
    # Order is the series order (exhaust, spread, onset, similar cases, then extras).
    PLOT_PALETTE = ["#2f6fed", "#14b8a6", "#f59e0b", "#ef4444", "#8b5cf6", "#0ea5e9", "#22c55e", "#f97316"]
    _HEAT_SCALE = [[0.0, "#f4f7fb"], [0.35, "#93c5fd"], [0.7, "#2f6fed"], [1.0, "#0d366b"]]


    def _plot_backend():
        """plotly when it imports, else matplotlib, else Altair. The UI never requires a CDN."""
        try:
            import plotly.graph_objects as go

            return "plotly", go
        except ImportError:
            pass
        try:
            import matplotlib

            matplotlib.use("Agg")
            import matplotlib.pyplot as plt

            return "mpl", plt
        except ImportError:
            return "altair", None


    def _finish_plotly(fig: Any, title: str) -> Any:
        """Shared layout. Streamlit's chart theme still adapts the paper to light or dark."""
        fig.update_layout(
            title=dict(text=title, font=dict(size=14, family="sans-serif")),
            font=dict(family="sans-serif", size=12),
            colorway=PLOT_PALETTE,
            margin=dict(l=48, r=16, t=48, b=36),
            legend=dict(orientation="h", yanchor="bottom", y=1.02, x=0),
        )
        fig.update_xaxes(showgrid=True, gridcolor="rgba(127,127,127,0.25)")
        fig.update_yaxes(showgrid=True, gridcolor="rgba(127,127,127,0.25)")
        return fig


    def show_figure(fig: Any, *, key: Optional[str] = None, alt: str = "Chart") -> None:
        """Draw whatever ``_plot_backend`` built. Plotly.js is the copy Streamlit ships, not a CDN."""
        if fig is None:
            return
        import streamlit as st

        name = type(fig).__module__
        if name.startswith("plotly"):
            st.plotly_chart(
                fig, width="stretch", theme="streamlit",
                config={"displayModeBar": False}, key=key, alt=alt or "Chart",
            )
            return
        if name.startswith("matplotlib"):
            st.pyplot(fig, width="stretch", alt=alt or "Chart")
            return
        st.altair_chart(fig, width="stretch")


    def exhaust_spread_figure(
        df: Optional[pd.DataFrame] = None,
        timestamps: Optional[pd.Series] = None,
        ring: Optional[List[str]] = None,
        spread_col: Optional[str] = None,
        residual: Optional[Dict[str, Any]] = None,
    ) -> Optional[Any]:
        """Exhaust temperature spread across the exhaust tags, or residual scores when none are in the file.

        ``ring`` is the ring thermocouples, or the zone tags on a zone frame (7HA, 9HA). The line is
        max - min across those tags at each sample. A spread tag, when the file has one, is a second
        line. With fewer than two exhaust tags, the bars are the exhaust / spread residual scores.
        """
        kind, lib = _plot_backend()
        cols = [c for c in (ring or []) if df is not None and c in df.columns]
        if df is not None and len(cols) >= 2:
            spread = (df[cols].max(axis=1) - df[cols].min(axis=1)).astype(float)
            x = list(timestamps) if timestamps is not None else list(range(len(spread)))
            extra = None
            if spread_col and spread_col in df.columns:
                extra = df[spread_col].astype(float)
            if kind == "plotly":
                fig = lib.Figure()
                fig.add_trace(lib.Scatter(x=x, y=spread, mode="lines", name="exhaust max − min", line=dict(color=PLOT_PALETTE[0], width=2)))
                if extra is not None:
                    fig.add_trace(lib.Scatter(x=x, y=extra, mode="lines", name=str(spread_col), line=dict(color=PLOT_PALETTE[1], width=2)))
                return _finish_plotly(fig, "Exhaust spread")
            if kind == "mpl":
                fig_m, ax = lib.subplots(figsize=(8, 3.2))
                ax.plot(range(len(spread)), spread, color=PLOT_PALETTE[0], label="exhaust max − min")
                if extra is not None:
                    ax.plot(range(len(extra)), extra, color=PLOT_PALETTE[1], label=str(spread_col))
                ax.set_title("Exhaust spread")
                ax.legend(frameon=False)
                fig_m.tight_layout()
                return fig_m
            import altair as alt

            rows = [{"i": i, "spread": float(v), "series": "exhaust max − min"} for i, v in enumerate(spread)]
            if extra is not None:
                rows += [{"i": i, "spread": float(v), "series": str(spread_col)} for i, v in enumerate(extra)]
            return alt.Chart(pd.DataFrame(rows)).mark_line().encode(
                x="i:Q", y="spread:Q", color=alt.Color("series:N", scale=alt.Scale(range=PLOT_PALETTE[:2])),
            ).properties(title="Exhaust spread", height=220)
        rows = [c for c in ((residual or {}).get("channels") or []) if c.get("group") in ("exhaust", "spread", "egt")]
        if not rows:
            return None
        labels = [str(c.get("channel")) for c in rows]
        scores = [float(c.get("score") or 0) for c in rows]
        colors = [PLOT_PALETTE[i % len(PLOT_PALETTE)] for i in range(len(rows))]
        if kind == "plotly":
            fig = lib.Figure(lib.Bar(x=labels, y=scores, marker_color=colors, name="residual score"))
            return _finish_plotly(fig, "Exhaust spread")
        if kind == "mpl":
            fig_m, ax = lib.subplots(figsize=(8, 3.2))
            ax.bar(labels, scores, color=colors)
            ax.set_title("Exhaust spread")
            fig_m.tight_layout()
            return fig_m
        import altair as alt

        data = pd.DataFrame({"channel": labels, "score": scores})
        return alt.Chart(data).mark_bar(color=PLOT_PALETTE[0]).encode(x="channel:N", y="score:Q").properties(title="Exhaust spread", height=220)


    def residual_heatmap_figure(res: Dict[str, Any]) -> Optional[Any]:
        """Channels × time residual score. ``residual_chart`` stays the Altair contract; this is the review plot."""
        prof = (res or {}).get("profile") or {}
        chans, times, matrix = prof.get("channels") or [], prof.get("times") or [], prof.get("matrix") or []
        if not chans or not times or not matrix:
            return None
        kind, lib = _plot_backend()
        if kind == "plotly":
            fig = lib.Figure(data=lib.Heatmap(
                z=matrix, x=[str(t) for t in times], y=list(chans), colorscale=_HEAT_SCALE,
                colorbar=dict(title="score"),
                hovertemplate="%{y}<br>%{x}<br>score %{z}<extra></extra>",
            ))
            return _finish_plotly(fig, "Residual heatmap")
        if kind == "mpl":
            fig_m, ax = lib.subplots(figsize=(8, max(2.4, 0.35 * len(chans))))
            im = ax.imshow(np.asarray(matrix, dtype=float), aspect="auto", cmap="Blues")
            ax.set_yticks(range(len(chans)))
            ax.set_yticklabels(list(chans))
            ax.set_title("Residual heatmap")
            fig_m.colorbar(im, ax=ax, fraction=0.04)
            fig_m.tight_layout()
            return fig_m
        # Altair last resort: same rect mark family as residual_chart, palette blue instead of the old ramp.
        import altair as alt

        rows = []
        for ci, ch in enumerate(chans):
            for ti, t in enumerate(times):
                rows.append({"channel": ch, "t": str(t), "score": float(matrix[ci][ti])})
        return alt.Chart(pd.DataFrame(rows)).mark_rect().encode(
            x="t:N", y="channel:N", color=alt.Color("score:Q", scale=alt.Scale(scheme="blues")),
        ).properties(title="Residual heatmap", height=max(120, 22 * len(chans)))


    def onset_order_figure(res: Dict[str, Any]) -> Optional[Any]:
        """Minutes after the first abnormal channel, one bar per event, in onset order."""
        events = [e for e in ((res or {}).get("events") or []) if e.get("channel")]
        if not events:
            return None
        events = sorted(events, key=lambda e: (e.get("onset_idx", 10**9), str(e.get("channel"))))
        labels = [str(e.get("channel")) for e in events]
        minutes = [float(e.get("minutes_after_first") or 0) for e in events]
        colors = [PLOT_PALETTE[i % len(PLOT_PALETTE)] for i in range(len(events))]
        kind, lib = _plot_backend()
        if kind == "plotly":
            fig = lib.Figure(lib.Bar(
                y=labels, x=minutes, orientation="h", marker_color=colors,
                hovertext=[f"{e.get('shape', '')} {e.get('direction', '')}".strip() for e in events],
                name="minutes after first",
            ))
            return _finish_plotly(fig, "Onset order")
        if kind == "mpl":
            fig_m, ax = lib.subplots(figsize=(8, max(2.2, 0.35 * len(labels))))
            ax.barh(labels, minutes, color=colors)
            ax.set_xlabel("minutes after first")
            ax.set_title("Onset order")
            fig_m.tight_layout()
            return fig_m
        import altair as alt

        data = pd.DataFrame({"channel": labels, "minutes": minutes, "i": list(range(len(labels)))})
        return alt.Chart(data).mark_bar().encode(
            y=alt.Y("channel:N", sort=labels), x="minutes:Q",
            color=alt.Color("i:O", scale=alt.Scale(range=PLOT_PALETTE), legend=None),
        ).properties(title="Onset order", height=max(120, 22 * len(labels)))


    def similar_cases_figure(similar: Optional[List[Dict[str, Any]]]) -> Optional[Any]:
        """Nearest cases. A ``distance`` field is plotted as-is (lower is closer); else ``similarity``."""
        rows = [r for r in (similar or []) if isinstance(r, dict)]
        if not rows:
            return None
        labels = [str(r.get("id") or r.get("case_id") or "?") for r in rows]
        if any("distance" in r for r in rows):
            vals = [float(r.get("distance") or 0) for r in rows]
            title, axis = "Similar cases", "distance"
        else:
            vals = [float(r.get("similarity") or 0) for r in rows]
            title, axis = "Similar cases", "similarity"
        colors = [PLOT_PALETTE[i % len(PLOT_PALETTE)] for i in range(len(rows))]
        kind, lib = _plot_backend()
        if kind == "plotly":
            fig = lib.Figure(lib.Bar(y=labels, x=vals, orientation="h", marker_color=colors, name=axis))
            return _finish_plotly(fig, title)
        if kind == "mpl":
            fig_m, ax = lib.subplots(figsize=(8, max(2.2, 0.35 * len(labels))))
            ax.barh(labels, vals, color=colors)
            ax.set_xlabel(axis)
            ax.set_title(title)
            fig_m.tight_layout()
            return fig_m
        import altair as alt

        data = pd.DataFrame({"case": labels, axis: vals})
        return alt.Chart(data).mark_bar(color=PLOT_PALETTE[0]).encode(
            y=alt.Y("case:N", sort=labels), x=f"{axis}:Q",
        ).properties(title=title, height=max(120, 22 * len(labels)))
