# =============================================================================
# sentinel.e2e.labels
# Engineer labels, metric log, and the version folder (v0000 is the shipped head).
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.labels sentinel/e2e/labels.py
if False:  # compiled by exec_section('sentinel.e2e.labels'); not executed as part of this module
    """Label-on-the-fly store, versioned classifier heads (rollback) and learning metrics.

    Layout (git-ignored, under ``data/e2e``):

        labels.jsonl              append-only engineer labels (latest label per case wins)
        emb/<case_id>.npy         TS Pulse embedding of every analyzed case (raw, before scaling)
        registry/vNNNN/           retrained heads: head.npz, head.json, meta.json (metrics, trigger)
        registry/current.json     active head version ("v0000" = shipped base head)
        metrics.jsonl             analysis / label / retrain events -> learning dashboard
        taxonomy.json             engineer-created signatures
    """

    # @@future@@ from __future__ import annotations

    import json
    import threading
    from datetime import datetime
    from pathlib import Path
    from typing import Any, Dict, List, Optional

    import numpy as np

    BASE_VERSION = "v0000"
    # The shipped channel-independent encoder. Later fine-tunes are e0001, e0002, ...
    ENCODER_BASE = "e0000"


    def _now() -> str:
        """Function _now."""
        return datetime.now().isoformat(timespec="seconds")


    def e2e_dir(settings: Any) -> Path:
        """Function e2e_dir."""
        return Path(settings.data_dir) / "e2e"


    def legacy_model_dir(model_dir: Any, kind: str) -> Path:
        """14-channel ``base`` or ``encoder``.

        After the bundle moves, those bytes live under ``legacy/`` and stay
        read-only. A checkout from before the move still has them at the top
        level, so the marker file decides. The encoder marker is ``classes.json``:
        the channel-independent encoder also has ``config.json``, and loading
        that file as the 14-channel model fails the embed.
        """
        model_dir = Path(model_dir)
        if kind == "base":
            legacy = model_dir / "legacy" / "base"
            if (legacy / "scaler.npz").is_file():
                return legacy
            return model_dir / "base"
        if kind != "encoder":
            raise ValueError(f"kind must be base or encoder, not {kind!r}")
        legacy = model_dir / "legacy" / "encoder"
        if (legacy / "classes.json").is_file():
            return legacy
        top = model_dir / "encoder"
        if (top / "classes.json").is_file():
            return top
        if (legacy / "config.json").is_file():
            return legacy
        return top


    def _append(path: Path, rec: Dict[str, Any]) -> None:
        """Function _append."""
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(rec, default=str) + "\n")


    def _read_jsonl(path: Path) -> List[Dict[str, Any]]:
        """Function _read_jsonl."""
        if not path.is_file():
            return []
        out = []
        for line in path.read_text(encoding="utf-8").splitlines():
            if line.strip():
                try:
                    out.append(json.loads(line))
                except ValueError:
                    continue
        return out


    class LabelStore:
        """Class LabelStore."""
        def __init__(self, settings: Any):
            """Function __init__."""
            self.root = e2e_dir(settings)
            self.file = self.root / "labels.jsonl"
            self.emb_dir = self.root / "emb"

        def save_embedding(self, case_id: str, emb: np.ndarray) -> Path:
            """Function save_embedding."""
            self.emb_dir.mkdir(parents=True, exist_ok=True)
            p = self.emb_dir / f"{case_id}.npy"
            np.save(p, np.asarray(emb, dtype=np.float32))
            return p

        def embedding(self, case_id: str) -> Optional[np.ndarray]:
            """Function embedding."""
            p = self.emb_dir / f"{case_id}.npy"
            return np.load(p) if p.is_file() else None

        def add(self, rec: Dict[str, Any]) -> Dict[str, Any]:
            """Function add."""
            rec = {"time": _now(), **rec}
            _append(self.file, rec)
            return rec

        def all(self) -> List[Dict[str, Any]]:
            """Every label line. Old layout ids load as frame-model ids, and a migrated case gains its profile.

            ``profile`` is filled on the copy. The label log on disk is not rewritten.
            """
            from ..config import migrate_frame_fields
            from .migrate import migrate_profile_fields

            return [migrate_profile_fields(migrate_frame_fields(r), root=self.root) for r in _read_jsonl(self.file)]

        def latest(self) -> Dict[str, Dict[str, Any]]:
            """Latest label per case; a ``deleted`` record (Teach the app -> Manage) removes the case."""
            out: Dict[str, Dict[str, Any]] = {}
            for r in self.all():
                if r.get("deleted"):
                    out.pop(r["case_id"], None)
                else:
                    out[r["case_id"]] = r
            return out

        def delete(self, case_id: str, by: str = "") -> Dict[str, Any]:
            """Function delete."""
            rec = {"time": _now(), "case_id": case_id, "deleted": True, "by": by}
            _append(self.file, rec)
            return rec

        def restore(self, rec: Dict[str, Any], by: str = "") -> Dict[str, Any]:
            """Re-append an earlier label record (rollback), keeping its content."""
            rec = {**rec, "restored_by": by, "restored_at": _now()}
            _append(self.file, rec)
            return rec


    def _resolved_key(resolved: Any) -> str:
        """Stable text for an alias resolution. Key order must not look like a change."""
        if isinstance(resolved, str):
            return resolved
        return json.dumps(resolved, sort_keys=True, default=str)


    class ProfileEmbeddings:
        """Both embedders for one case, keyed by alert type.

        ``emb2/<profile>/<case_id>.npz`` holds the channel-independent vector and the
        statistical vector. A case is embedded again only when the channels hash, the
        encoder id, or the alias resolution changed. An alias edit does not change the
        channels hash, so the resolution is part of the check on purpose.
        """

        def __init__(self, settings: Any):
            """Store under the site data directory."""
            self.root = e2e_dir(settings) / "emb2"

        def _path(self, profile_id: str, case_id: str) -> Path:
            """One file per case. The ids are single path segments."""
            for label, value in (("profile", profile_id), ("case", case_id)):
                text = str(value or "").strip()
                if not text or text in {".", ".."} or "/" in text or "\\" in text:
                    raise ValueError(f"{label} id is not a single name: {value!r}")
            return self.root / str(profile_id).strip() / f"{str(case_id).strip()}.npz"

        def save(
            self,
            profile_id: str,
            case_id: str,
            tspulse: np.ndarray,
            stats: np.ndarray,
            mask: np.ndarray,
            channel_ids: Sequence[str],
            channels_hash: str,
            encoder_id: str,
            resolved: Any,
        ) -> Path:
            """Write both vectors as float16. ``resolved`` is stored as canonical JSON."""
            path = self._path(profile_id, case_id)
            path.parent.mkdir(parents=True, exist_ok=True)
            np.savez_compressed(
                path,
                E_tspulse=np.asarray(tspulse, dtype=np.float16),
                E_stats=np.asarray(stats, dtype=np.float16),
                mask=np.asarray(mask, dtype=np.uint8),
                channel_ids=np.asarray(list(channel_ids), dtype="U"),
                channels_hash=np.asarray(str(channels_hash)),
                encoder_id=np.asarray(str(encoder_id)),
                resolved=np.asarray(_resolved_key(resolved)),
            )
            return path

        def load(self, profile_id: str, case_id: str) -> Optional[Dict[str, Any]]:
            """The stored row, or None when this case has not been embedded for this profile."""
            path = self._path(profile_id, case_id)
            if not path.is_file():
                return None
            blob = np.load(path, allow_pickle=False)
            return {
                "tspulse": blob["E_tspulse"].astype(np.float32),
                "stats": blob["E_stats"].astype(np.float32),
                "mask": blob["mask"].astype(bool),
                "channel_ids": [str(item) for item in blob["channel_ids"].tolist()],
                "channels_hash": str(blob["channels_hash"]),
                "encoder_id": str(blob["encoder_id"]),
                "resolved": str(blob["resolved"]),
            }

        def needs_embed(self, profile_id: str, case_id: str, channels_hash: str, encoder_id: str, resolved: Any) -> bool:
            """True when the file is missing or any of the three identity fields differ."""
            row = self.load(profile_id, case_id)
            if row is None:
                return True
            return not (
                row["channels_hash"] == str(channels_hash)
                and row["encoder_id"] == str(encoder_id)
                and row["resolved"] == _resolved_key(resolved)
            )


    class Metrics:
        """Class Metrics."""
        def __init__(self, settings: Any):
            """Function __init__."""
            self.file = e2e_dir(settings) / "metrics.jsonl"

        def log(self, kind: str, **fields: Any) -> None:
            """Function log."""
            _append(self.file, {"type": kind, "time": _now(), **fields})

        def events(self, kind: Optional[str] = None) -> List[Dict[str, Any]]:
            """Function events."""
            ev = _read_jsonl(self.file)
            return [e for e in ev if kind is None or e.get("type") == kind]


    class Registry:
        """Versioned classifier heads with rollback. v0000 is the shipped base head.

        A ``profile`` argument scopes current, folder, versions, register, activate
        and rollback to ``registry/profiles/<id>/``. The legacy ``version`` line and
        the shared ``encoder`` line stay in the same ``current.json`` and do not move
        when one profile is activated.
        """

        def __init__(self, settings: Any, profile: Optional[str] = None):
            """``profile`` selects one alert type. Omit it for the legacy 14-channel head."""
            self.settings = settings
            self.profile = str(profile).strip() if profile else None
            self.root = e2e_dir(settings) / "registry"
            self.base_dir = legacy_model_dir(settings.e2e_model_dir, "base")

        def _pid(self) -> str:
            """The profile id, checked so it cannot escape the profiles directory."""
            pid = str(self.profile or "").strip()
            if not pid or pid in {".", ".."} or "/" in pid or "\\" in pid:
                raise ValueError(f"profile id is not a single name: {pid!r}")
            return pid

        def _current_file(self) -> Path:
            """Function _current_file."""
            return self.root / "current.json"

        def _read_current(self) -> Dict[str, Any]:
            """The pointer file. Missing or broken reads as an empty map, not an error."""
            f = self._current_file()
            if not f.is_file():
                return {}
            try:
                data = json.loads(f.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                return {}
            return data if isinstance(data, dict) else {}

        def _write_current(self, data: Dict[str, Any]) -> None:
            """Rewrite the pointer file. Callers pass the whole map so other lines survive."""
            self.root.mkdir(parents=True, exist_ok=True)
            data = dict(data)
            data["time"] = _now()
            self._current_file().write_text(json.dumps(data, indent=2), encoding="utf-8")

        def current(self) -> str:
            """Active legacy version, or the active version of ``self.profile``."""
            data = self._read_current()
            if self.profile:
                pid = self._pid()
                chosen = str((data.get("profiles") or {}).get(pid) or "")
                if chosen == BASE_VERSION or (chosen and (self.root / "profiles" / pid / chosen).is_dir()):
                    return chosen or BASE_VERSION
                return BASE_VERSION
            try:
                v = data["version"]
            except KeyError:
                return BASE_VERSION
            if v == BASE_VERSION or (self.root / str(v) / "head.npz").is_file():
                return str(v)
            return BASE_VERSION

        def folder(self, version: str) -> Path:
            """Folder for a legacy version, or for this profile's version."""
            if self.profile:
                pid = self._pid()
                if version == BASE_VERSION:
                    return Path(self.settings.e2e_model_dir) / "profiles" / pid
                return self.root / "profiles" / pid / version
            return self.base_dir if version == BASE_VERSION else self.root / version

        def versions(self) -> List[Dict[str, Any]]:
            """Shipped v0000 plus site versions. A profile version may have no head yet."""
            out = [{"version": BASE_VERSION, **self._meta(BASE_VERSION)}]
            if self.profile:
                parent = self.root / "profiles" / self._pid()
                pattern = parent.glob("v[0-9][0-9][0-9][0-9]") if parent.is_dir() else []
                for d in sorted(pattern):
                    if (d / "meta.json").is_file() or (d / "head.npz").is_file():
                        out.append({"version": d.name, **self._meta(d.name)})
            elif self.root.is_dir():
                for d in sorted(self.root.glob("v[0-9][0-9][0-9][0-9]")):
                    if (d / "head.npz").is_file():
                        out.append({"version": d.name, **self._meta(d.name)})
            cur = self.current()
            for v in out:
                v["active"] = v["version"] == cur
            return out

        def _meta(self, version: str) -> Dict[str, Any]:
            """Version metadata. Held-out frame slices load under the current frame-model ids."""
            from ..config import migrate_frame_table

            f = self.folder(version) / "meta.json"
            if f.is_file():
                try:
                    data = json.loads(f.read_text(encoding="utf-8"))
                except ValueError:
                    data = None
                if isinstance(data, dict):
                    for key in ("heldout", "heldout_before"):
                        block = data.get(key)
                        if isinstance(block, dict) and isinstance(block.get("by_frame"), dict):
                            block = dict(block)
                            block["by_frame"] = migrate_frame_table(block["by_frame"])
                            data[key] = block
                    return data
            return {"created": None, "trigger": "shipped base model" if version == BASE_VERSION else "?"}

        def _next_version(self, parent: Path, prefix: str) -> str:
            """Next ``vNNNN`` or ``eNNNN`` inside one directory. Numbers are not shared across profiles."""
            nums = []
            if parent.is_dir():
                for d in parent.glob(f"{prefix}[0-9][0-9][0-9][0-9]"):
                    if d.is_dir() and d.name[1:].isdigit():
                        nums.append(int(d.name[1:]))
            return f"{prefix}{(max(nums) + 1) if nums else 1:04d}"

        def register(self, head: Any, meta: Dict[str, Any], activate: bool = True) -> str:
            """Save a new version and, by default, make it current.

            A profile version may omit the head (the kNN tier has an index and no head).
            The legacy line still requires a head, because that is all the old path loads.
            """
            if self.profile:
                parent = self.root / "profiles" / self._pid()
                parent.mkdir(parents=True, exist_ok=True)
                version = self._next_version(parent, "v")
                folder = parent / version
                folder.mkdir()
                if head is not None:
                    head.save(folder)
            else:
                if head is None:
                    raise ValueError("the legacy registry version needs a head")
                self.root.mkdir(parents=True, exist_ok=True)
                version = self._next_version(self.root, "v")
                folder = self.root / version
                head.save(folder)
            (folder / "meta.json").write_text(json.dumps({"created": _now(), **meta}, indent=2, default=str), encoding="utf-8")
            if activate:
                self.activate(version)
            return version

        def activate(self, version: str) -> None:
            """Point the legacy line, or this profile's line, at ``version``. Other lines stay."""
            data = self._read_current()
            if self.profile:
                pid = self._pid()
                if version != BASE_VERSION and not (self.root / "profiles" / pid / version).is_dir():
                    raise ValueError(f"unknown profile version {pid} {version}")
                profiles = dict(data.get("profiles") or {})
                profiles[pid] = version
                data["profiles"] = profiles
            else:
                if version != BASE_VERSION and not (self.root / version / "head.npz").is_file():
                    raise ValueError(f"unknown model version {version}")
                data["version"] = version
            self._write_current(data)

        def rollback(self) -> str:
            """Activate the version before the current one, for this profile or the legacy line."""
            vs = [v["version"] for v in self.versions()]
            cur = self.current()
            i = vs.index(cur) if cur in vs else 0
            target = vs[max(0, i - 1)]
            self.activate(target)
            return target

        def current_encoder(self) -> str:
            """The shared encoder the profiles path will load. Missing means the shipped ``e0000``."""
            chosen = str(self._read_current().get("encoder") or ENCODER_BASE)
            if chosen == ENCODER_BASE or (self.root / "encoders" / chosen / "meta.json").is_file():
                return chosen
            return ENCODER_BASE

        def encoder_folder(self, version: str) -> Path:
            """``e0000`` is the shipped encoder. Later ids live under ``registry/encoders``."""
            if version == ENCODER_BASE:
                return Path(self.settings.e2e_model_dir) / "encoder"
            return self.root / "encoders" / version

        def encoder_versions(self) -> List[Dict[str, Any]]:
            """Shipped encoder plus every site fine-tune that wrote a meta file."""
            out = [{"version": ENCODER_BASE}]
            parent = self.root / "encoders"
            if parent.is_dir():
                for d in sorted(parent.glob("e[0-9][0-9][0-9][0-9]")):
                    if not (d / "meta.json").is_file():
                        continue
                    try:
                        meta = json.loads((d / "meta.json").read_text(encoding="utf-8"))
                    except ValueError:
                        meta = {}
                    out.append({"version": d.name, **(meta if isinstance(meta, dict) else {})})
            cur = self.current_encoder()
            for row in out:
                row["active"] = row["version"] == cur
            return out

        def register_encoder(self, meta: Dict[str, Any], activate: bool = True) -> str:
            """Record a new shared encoder version. Weight files are copied in by the fine-tune step."""
            parent = self.root / "encoders"
            parent.mkdir(parents=True, exist_ok=True)
            version = self._next_version(parent, "e")
            folder = parent / version
            folder.mkdir()
            (folder / "meta.json").write_text(json.dumps({"created": _now(), **meta}, indent=2, default=str), encoding="utf-8")
            if activate:
                self.activate_encoder(version)
            return version

        def activate_encoder(self, version: str) -> None:
            """Point the encoder line at ``version``. Profile lines and the legacy head stay."""
            if version != ENCODER_BASE and not (self.root / "encoders" / version / "meta.json").is_file():
                raise ValueError(f"unknown encoder version {version}")
            data = self._read_current()
            data["encoder"] = version
            self._write_current(data)

        def rollback_encoder(self) -> str:
            """Activate the encoder version before the current one."""
            vs = [v["version"] for v in self.encoder_versions()]
            cur = self.current_encoder()
            i = vs.index(cur) if cur in vs else 0
            target = vs[max(0, i - 1)]
            self.activate_encoder(target)
            return target


    class RetrainWorker:
        """Runs one head retrain at a time in a background thread."""

        def __init__(self) -> None:
            """Function __init__."""
            self._thread: Optional[threading.Thread] = None
            self.last: Dict[str, Any] = {}
            self.error: str = ""

        @property
        def running(self) -> bool:
            """Function running."""
            return bool(self._thread and self._thread.is_alive())

        def start(self, fn: Any, *args: Any, **kw: Any) -> bool:
            """Function start."""
            if self.running:
                return False

            def run() -> None:
                """Function run."""
                try:
                    self.error = ""
                    self.last = fn(*args, **kw) or {}
                except Exception as exc:  # noqa: BLE001 — surfaced in the dashboard
                    self.error = f"{type(exc).__name__}: {exc}"

            self._thread = threading.Thread(target=run, name="sentinel-retrain", daemon=True)
            self._thread.start()
            return True

        def join(self, timeout: Optional[float] = None) -> None:
            """Function join."""
            if self._thread:
                self._thread.join(timeout)
