if False:  # compiled by exec_section('sentinel.e2e.evaluation'); not executed as part of this module
    """Shared helpers for training / evaluation: cached rule-path runs and metric tables."""

    # @@future@@ from __future__ import annotations

    import hashlib
    import json
    from pathlib import Path
    from typing import Any, Dict, List, Sequence

    import numpy as np


    def _rule_one(job: Dict[str, Any]) -> Dict[str, Any]:
        """Function _rule_one."""
        import sys

        root = Path(__file__).resolve().parents[2]
        if str(root) not in sys.path:
            sys.path.insert(0, str(root))
        from sentinel.config import load_settings
        from sentinel.pipeline import run_case

        s = load_settings({"use_llm": False, "use_tspulse": False, "data_dir": job["tmp"]})
        try:
            r = run_case(job["path"], job["analytic"], job["notes"], settings=s, save=False)
            d = r["decision"]
            return {"case_id": job["case_id"], "action": d["primary_action"], "cause": d["cause"], "confidence": d["confidence"],
                    "needs_human": d["needs_human"], "analytic": r["analytic"]["resolved"]}
        except Exception as exc:  # noqa: BLE001
            return {"case_id": job["case_id"], "action": "error", "error": f"{type(exc).__name__}: {exc}"}


    def rule_results(root: Path, rows: Sequence[Dict[str, Any]], cache_dir: Path, workers: int = 0) -> Dict[str, Dict[str, Any]]:
        """Rule-path decisions for manifest rows (parallel, cached)."""
        import multiprocessing as mp
        import tempfile

        key = hashlib.sha256("|".join(f"{r['file']}:{r['analytic']}:{r['notes']}" for r in rows).encode()).hexdigest()[:16]
        cache = Path(cache_dir) / f"rules_{key}.json"
        if cache.is_file():
            return json.loads(cache.read_text(encoding="utf-8"))
        tmp = tempfile.mkdtemp(prefix="sentinel_rules_")
        jobs = [{"case_id": r["case_id"], "path": str(Path(root) / r["file"]), "analytic": r["analytic"], "notes": r["notes"], "tmp": tmp} for r in rows]
        workers = workers or max(1, (mp.cpu_count() or 2) - 2)
        if workers > 1 and len(jobs) > 8:
            with mp.get_context("spawn").Pool(workers) as pool:
                res = pool.map(_rule_one, jobs, chunksize=4)
        else:
            res = [_rule_one(j) for j in jobs]
        out = {r["case_id"]: r for r in res}
        cache.parent.mkdir(parents=True, exist_ok=True)
        cache.write_text(json.dumps(out), encoding="utf-8")
        return out


    def confusion(truth: Sequence[str], pred: Sequence[str], labels: Sequence[str]) -> Dict[str, Any]:
        """Function confusion."""
        labels = list(labels)
        extra = sorted(set(pred) - set(labels))
        cols = labels + extra
        m = np.zeros((len(labels), len(cols)), dtype=int)
        for t, p in zip(truth, pred):
            if t in labels:
                m[labels.index(t), cols.index(p)] += 1
        return {"rows": labels, "cols": cols, "matrix": m.tolist()}


    def accuracy(truth: Sequence[Any], pred: Sequence[Any]) -> float:
        """Function accuracy."""
        t, p = list(truth), list(pred)
        return round(float(np.mean([a == b for a, b in zip(t, p)])) if t else 0.0, 4)


    def md_confusion(c: Dict[str, Any], short: Dict[str, str] | None = None) -> str:
        """Function md_confusion."""
        short = short or {}
        cols = [short.get(x, x) for x in c["cols"]]
        out = ["| truth \\ predicted | " + " | ".join(cols) + " |", "|---|" + "---|" * len(cols)]
        for name, row in zip(c["rows"], c["matrix"]):
            out.append(f"| {short.get(name, name)} | " + " | ".join(str(v) if v else "·" for v in row) + " |")
        return "\n".join(out)


    def per_class(truth: Sequence[str], pred: Sequence[str], labels: Sequence[str]) -> List[Dict[str, Any]]:
        """Function per_class."""
        out = []
        for c in labels:
            idx = [i for i, t in enumerate(truth) if t == c]
            if idx:
                out.append({"class": c, "n": len(idx), "acc": round(float(np.mean([pred[i] == c for i in idx])), 3)})
        return out
# >>>>>>> END sentinel.e2e.evaluation

# =============================================================================
# sentinel.e2e.dashboard
# Learning-dashboard series: held-out accuracy, rolling agreement, label counts.
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.dashboard sentinel/e2e/dashboard.py
if False:  # compiled by exec_section('sentinel.e2e.dashboard'); not executed as part of this module
    """Learning-dashboard series computed from data/e2e/metrics.jsonl (analysis / label / retrain events)."""

    # @@future@@ from __future__ import annotations

    from typing import Any, Dict, List, Optional

    import pandas as pd

    LEARNED, RULES = "Learned path", "Rules"
    COLORS = {LEARNED: "#2a78d6", RULES: "#eb6834", "Agreement": "#2a78d6", "Novelty": "#eb6834", "Accepted without edit": "#1baf7a"}
    WINDOW = 20


    def pct(x: Optional[float]) -> str:
        """Function pct."""
        return "—" if x is None else f"{100 * x:.0f} %"


    def _mean(xs: List[Any]) -> Optional[float]:
        """Function _mean."""
        xs = [bool(x) for x in xs if x is not None]
        return sum(xs) / len(xs) if xs else None


    def metrics(eng: Any) -> Dict[str, Any]:
        """Function metrics."""
        ev = eng.metrics.events()
        an = [e for e in ev if e["type"] == "analysis"]
        lab = [e for e in ev if e["type"] == "label"]
        latest = eng.labels.latest()
        return {
            "n_labels": len(latest),
            "n_signatures": len({r["signature"] for r in latest.values()}),
            "n_analyses": len(an),
            "agreement": _mean([e.get("agree") for e in an[-100:]]),
            "novelty": _mean([e.get("novel") for e in an[-100:]]),
            "accepted": _mean([e.get("accepted_without_edit") for e in lab[-100:]]),
        }


    def heldout_series(eng: Any) -> pd.DataFrame:
        """Function heldout_series."""
        rows = []
        for e in eng.metrics.events("retrain"):
            n = e.get("n_engineer", 0)
            if e.get("heldout_action_acc") is not None:
                rows.append({"labels": n, "accuracy": e["heldout_action_acc"], "series": LEARNED, "version": e.get("version")})
            if e.get("heldout_rules_action_acc") is not None:
                rows.append({"labels": n, "accuracy": e["heldout_rules_action_acc"], "series": RULES, "version": e.get("version")})
        if rows and eng.heldout is not None:
            base = eng.registry.versions()[0].get("heldout") or {}
            if base.get("action_acc") is not None:
                rows = [{"labels": 0, "accuracy": base["action_acc"], "series": LEARNED, "version": "v0000"},
                        {"labels": 0, "accuracy": base["rules_action_acc"], "series": RULES, "version": "v0000"}] + rows
        return pd.DataFrame(rows)


    def rolling_series(eng: Any) -> pd.DataFrame:
        """Function rolling_series."""
        lab = [e for e in eng.metrics.events("label") if e.get("learned_correct") is not None]
        if not lab:
            return pd.DataFrame()
        df = pd.DataFrame({"label #": range(1, len(lab) + 1),
                           LEARNED: [float(bool(e["learned_correct"])) for e in lab],
                           RULES: [None if e.get("rules_correct") is None else float(bool(e["rules_correct"])) for e in lab]})
        for c in (LEARNED, RULES):
            df[c] = df[c].astype(float).rolling(WINDOW, min_periods=1).mean()
        return df.melt(id_vars=["label #"], value_vars=[LEARNED, RULES], var_name="series", value_name="accuracy").dropna()


    def rate_series(eng: Any) -> pd.DataFrame:
        """Function rate_series."""
        an = eng.metrics.events("analysis")
        lab = eng.metrics.events("label")
        rows = []
        if an:
            s = pd.DataFrame({"event #": range(1, len(an) + 1), "agree": [float(bool(e.get("agree"))) for e in an], "novel": [float(bool(e.get("novel"))) for e in an]})
            for col, name in (("agree", "Agreement"), ("novel", "Novelty")):
                r = s[col].rolling(WINDOW, min_periods=1).mean()
                rows += [{"event #": int(i), "rate": float(v), "series": name} for i, v in zip(s["event #"], r)]
        if lab:
            acc = pd.Series([float(bool(e.get("accepted_without_edit"))) for e in lab]).rolling(WINDOW, min_periods=1).mean()
            rows += [{"event #": i + 1, "rate": float(v), "series": "Accepted without edit"} for i, v in enumerate(acc)]
        return pd.DataFrame(rows)


    def label_counts(eng: Any) -> pd.DataFrame:
        """Function label_counts."""
        latest = eng.labels.latest()
        c: Dict[str, int] = {}
        for r in latest.values():
            c[r["signature"]] = c.get(r["signature"], 0) + 1
        return pd.DataFrame([{"signature": k, "labels": v} for k, v in sorted(c.items(), key=lambda kv: -kv[1])])


    def line(df: pd.DataFrame, x: str, y: str, series: str, xtitle: str) -> Any:
        """Function line."""
        import altair as alt

        names = list(dict.fromkeys(df[series]))
        scale = alt.Scale(domain=names, range=[COLORS.get(n, "#2a78d6") for n in names])
        hover = alt.selection_point(fields=[x], nearest=True, on="pointerover", empty=False, clear="pointerout")
        base = alt.Chart(df).encode(x=alt.X(f"{x}:Q", title=xtitle))
        lines = base.mark_line(strokeWidth=2).encode(y=alt.Y(f"{y}:Q", title=None, scale=alt.Scale(domain=[0, 1]), axis=alt.Axis(format="%")),
                                                     color=alt.Color(f"{series}:N", scale=scale, legend=alt.Legend(orient="top", title=None)))
        pts = base.mark_point(size=90, opacity=0).encode(y=f"{y}:Q", tooltip=[alt.Tooltip(f"{x}:Q"), alt.Tooltip(f"{series}:N"), alt.Tooltip(f"{y}:Q", format=".1%")]).add_params(hover)
        rule = base.mark_rule(color="#898781").encode(opacity=alt.condition(hover, alt.value(1), alt.value(0)))
        dots = base.mark_circle(size=64, stroke="#fcfcfb", strokeWidth=2).encode(y=f"{y}:Q", color=alt.Color(f"{series}:N", scale=scale, legend=None),
                                                                                opacity=alt.condition(hover, alt.value(1), alt.value(0)))
        return alt.layer(lines, rule, dots, pts).properties(height=260).configure_axis(gridColor="#e1e0d9", domainColor="#c3c2b7", labelColor="#898781", titleColor="#898781").configure_view(stroke=None)
# >>>>>>> END sentinel.e2e.dashboard

# =============================================================================
# sentinel.data
# Read a historian CSV into canonical roles. Ring and zone tags sort by full sensor number; each frame model points at a tag layout.
# =============================================================================
# <<<<<<< SECTION sentinel.data sentinel/data.py
if False:  # compiled by exec_section('sentinel.data'); not executed as part of this module
    """CSV loading, channel-role mapping and data-quality checks."""

    # @@future@@ from __future__ import annotations

    import gzip
    import hashlib
    import io
    import re
    from dataclasses import dataclass, field
    from pathlib import Path
    from typing import Any, Dict, List, Optional, Tuple, Union

    import numpy as np
    import pandas as pd

    from .limits import GENERAL

    _TS_NAMES = {"timestamp", "time", "datetime", "date", "date_time", "ts"}

    # role -> regex on the lower-cased column name (first match wins, order matters)
    _ROLE_PATTERNS: List[Tuple[str, str]] = [
        ("trip", r"trip"),
        ("spread", r"spread|ttxsp"),
        ("egt_avg", r"^(egt|ttx|exh\w*)_?(avg|mean|m)\b|^egt_avg|^ttxm"),
        ("dynamics", r"dyn|pulsation|^cdm|humming"),
        ("load", r"^(load|dwatt|gross_?mw|mw|power)"),
        ("fuel", r"fuel|fqg|fsr"),
        ("igv", r"igv|csgv"),
        ("cdp", r"^cdp|^cpd|compressor_?discharge_?press"),
        ("cdt", r"^cdt|^ctd|compressor_?discharge_?temp"),
        ("vibration", r"^vib|vibration|^bb\d|^bv\d|^brg\d"),
        ("lube_oil", r"lube|^lto|oil"),
    ]
    # The prefix must not swallow a digit. An older pattern (`ttxd_?\d?_?`) let TTXD_10 match as
    # prefix "ttxd_" + digit "1" + group "0", and ring.sort() then ordered sensors by that last digit
    # (TTXD_10, TTXD_20, TTXD_1, ...), scrambling neighbours on about 30% of ring files.
    # A bank digit (TTXD_1_05, TTXD2_05) is still a ring tag, but only when a separator follows it,
    # so it can never take a digit from the sensor number. The sort key is _sensor_number either way.
    _RING_RE = re.compile(r"^(?:tc|ttxd(?:_?\d_)?|exh_?tc|egt_?tc)_?(\d+)$", re.I)
    _ZONE_RE = re.compile(r"^egt_?z(?:one)?_?(\d+)(?:_c)?$", re.I)


    @dataclass
    class CaseData:
        """Class CaseData."""
        df: pd.DataFrame
        source_name: str
        sha256: str
        timestamps: Optional[pd.Series]
        interval_minutes: Optional[float]
        roles: Dict[str, List[str]]
        ring: List[str]
        zones: List[str]
        quality: Dict[str, Any] = field(default_factory=dict)
        frame_type: str = ""  # frame model id (6B, 7FA, ...), a Teach-added frame, or "auto"

        @property
        def n(self) -> int:
            """Function n."""
            return len(self.df)

        @property
        def minutes_per_sample(self) -> float:
            """Function minutes_per_sample."""
            return self.interval_minutes or 1.0

        def samples(self, minutes: float) -> int:
            """Function samples."""
            return max(1, int(round(minutes / self.minutes_per_sample)))

        def first(self, role: str) -> Optional[str]:
            """Function first."""
            cols = self.roles.get(role) or []
            return cols[0] if cols else None

        def series(self, col: str) -> np.ndarray:
            """Function series."""
            return pd.to_numeric(self.df[col], errors="coerce").to_numpy(dtype=float)

        def time_at(self, i: int) -> str:
            """Function time_at."""
            if self.timestamps is not None and 0 <= i < self.n:
                ts = self.timestamps.iloc[i]
                if pd.notna(ts):
                    return pd.Timestamp(ts).strftime("%Y-%m-%d %H:%M")
            return f"sample {i}"

        def hours_between(self, i: int, j: int) -> float:
            """Function hours_between."""
            return (j - i) * self.minutes_per_sample / 60.0

        @property
        def numeric_columns(self) -> List[str]:
            """Function numeric_columns."""
            return [c for c in self.df.columns if pd.api.types.is_numeric_dtype(self.df[c])]


    def _role_of(col: str) -> Optional[str]:
        """Function _role_of."""
        low = col.strip().lower()
        for role, pat in _ROLE_PATTERNS:
            if re.search(pat, low):
                return role
        return None


    def _sensor_number(name: str) -> int:
        """Trailing sensor number: TTXD_17 -> 17, TC5 -> 5, EGT_Z3_C -> 3. Missing number sorts last."""
        m = re.search(r"(\d+)\D*$", str(name).strip())
        return int(m.group(1)) if m else 10**9


    def map_roles(columns: List[str]) -> Tuple[Dict[str, List[str]], List[str], List[str]]:
        """Assign columns to process roles, an exhaust ring and exhaust zones.

        Ring and zone tags are ordered by the full sensor number (natural sort), not by the
        last digit and not by the order they appeared in the file. Neighbours in the ring are
        then the physical neighbours the cold-spot features and the residual view both need.
        """
        roles: Dict[str, List[str]] = {}
        ring: List[Tuple[int, str]] = []
        zones: List[Tuple[int, str]] = []
        for c in columns:
            m = _RING_RE.match(c.strip())
            if m:
                ring.append((_sensor_number(c), c))
                continue
            z = _ZONE_RE.match(c.strip())
            if z:
                zones.append((_sensor_number(c), c))
                continue
            role = _role_of(c)
            if role:
                roles.setdefault(role, []).append(c)
        ring.sort()
        zones.sort()
        return roles, [c for _, c in ring], [c for _, c in zones]


    def _prefixed_tags(columns: List[str], prefix: str) -> List[str]:
        """Columns whose name is ``prefix`` plus a sensor number (optional underscore, optional ``_C``)."""
        if not prefix:
            return []
        p = prefix.lower()
        found = []
        for c in columns:
            low = c.strip().lower()
            if not low.startswith(p):
                continue
            rest = low[len(p):].lstrip("_")
            if rest.endswith("_c"):
                rest = rest[:-2]
            if rest.isdigit():
                found.append(c)
        found.sort(key=lambda c: (_sensor_number(c), c))
        return found


    def _tag_score(columns: List[str], spec: Dict[str, Any]) -> int:
        """How many of this spec's tags are actually in the file. Used to pick a layout."""
        colset = {c.strip().lower() for c in columns}
        n = 0
        for tags in (spec.get("roles") or {}).values():
            n += sum(1 for t in tags if str(t).lower() in colset)
        n += len(_prefixed_tags(columns, spec.get("ring_prefix") or ""))
        n += len(_prefixed_tags(columns, spec.get("zone_prefix") or ""))
        n += sum(1 for t in (spec.get("ring") or []) if str(t).lower() in colset)
        n += sum(1 for t in (spec.get("zones") or []) if str(t).lower() in colset)
        return n


    def detect_layout(columns: List[str]) -> str:
        """Tag layout whose tags cover the most columns. Empty when nothing matches."""
        from .config import LAYOUTS

        best, score = "", 0
        for name, spec in LAYOUTS.items():
            n = _tag_score(columns, spec)
            if n > score:
                best, score = name, n
        return best if score >= 3 else ""


    def detect_frame(columns: List[str], frame_maps: Optional[Dict[str, Any]] = None) -> str:
        """Frame model whose tags cover the most columns.

        Several shipped models share one layout, so a tie goes to the default model for the
        layout that actually matched (7FA for a historian ring, 9HA for historian zones).
        A Teach-added frame with its own tags wins when it matches more columns.
        """
        from .config import DEFAULT_FRAME_FOR_LAYOUT, merged_frame_maps

        maps = frame_maps or merged_frame_maps()
        best, score = "", 0
        tied: List[str] = []
        for name, spec in maps.items():
            n = _tag_score(columns, spec)
            if n > score:
                best, score, tied = name, n, [name]
            elif n == score and n > 0:
                tied.append(name)
        if score < 3:
            return ""
        if len(tied) == 1:
            return tied[0]
        layout = detect_layout(columns)
        preferred = DEFAULT_FRAME_FOR_LAYOUT.get(layout, "")
        if preferred in tied:
            return preferred
        return best


    def apply_frame(
        columns: List[str],
        frame: Optional[str] = None,
        frame_maps: Optional[Dict[str, Any]] = None,
    ) -> Tuple[Dict[str, List[str]], List[str], List[str], str]:
        """Map one frame model's tags onto the canonical roles, then fall back to auto-detect.

        Returns roles, ring, zones and the frame model id actually used (``auto`` when no map applied).
        An old layout id is accepted and mapped to its frame model. An explicit list in the frame
        table replaces the ring or the zones only when those tags are present, and it keeps the
        order written in the table. A prefix replaces them only when at least two tags match,
        ordered by sensor number.
        """
        from .config import canonical_frame, merged_frame_maps

        maps = frame_maps or merged_frame_maps()
        roles, ring, zones = map_roles(columns)
        requested = (frame or "").strip()
        if requested.lower() in ("", "auto"):
            requested = ""
        else:
            requested = canonical_frame(requested) or requested
        if requested not in maps:
            requested = detect_frame(columns, maps)
        if not requested:
            return roles, ring, zones, "auto"
        spec = maps[requested]
        colset = {c.strip().lower(): c for c in columns}
        for role, tags in (spec.get("roles") or {}).items():
            found = [colset[str(t).lower()] for t in tags if str(t).lower() in colset]
            if found:
                roles[role] = found
        listed = [colset[str(t).lower()] for t in (spec.get("ring") or []) if str(t).lower() in colset]
        if listed:
            ring = listed
        else:
            pref = _prefixed_tags(columns, spec.get("ring_prefix") or "")
            if len(pref) >= 2:
                ring = pref
        listed_z = [colset[str(t).lower()] for t in (spec.get("zones") or []) if str(t).lower() in colset]
        if listed_z:
            zones = listed_z
        else:
            pref = _prefixed_tags(columns, spec.get("zone_prefix") or "")
            if len(pref) >= 2:
                zones = pref
        return roles, ring, zones, requested


    def _read_frame(raw: bytes) -> pd.DataFrame:
        """Function _read_frame."""
        if raw[:2] == bytes((0x1F, 0x8B)):  # gzip-compressed CSV (.csv.gz)
            raw = gzip.decompress(raw)
        text = raw.decode("utf-8-sig", errors="replace")
        sep = ";" if text.count(";") > text.count(",") else ","
        return pd.read_csv(io.StringIO(text), sep=sep)


    def _parse_timestamps(df: pd.DataFrame) -> Tuple[Optional[str], Optional[pd.Series]]:
        """Function _parse_timestamps."""
        for c in df.columns:
            if str(c).strip().lower() in _TS_NAMES:
                col = df[c]
                if pd.api.types.is_numeric_dtype(col):
                    # Plain sample counter (0,1,2,...) — not a calendar time.
                    return str(c), None
                ts = pd.to_datetime(col, errors="coerce")
                if ts.notna().mean() > 0.9:
                    return str(c), ts
                return str(c), None
        return None, None


    def load_csv(
        source: Union[str, Path, bytes],
        name: Optional[str] = None,
        frame: Optional[str] = None,
        frame_maps: Optional[Dict[str, Any]] = None,
    ) -> CaseData:
        """Load a historian CSV from a path or raw bytes (UI upload).

        ``frame`` selects a frame model (CONFIG ``FRAME_MODELS`` or a frame added from Teach).
        Empty or ``auto`` detects one from the column names. Unknown tags still fall through
        to the role patterns, so a file that only partly matches a frame still loads.
        """
        if isinstance(source, (str, Path)):
            path = Path(source)
            raw = path.read_bytes()
            name = name or path.name
        else:
            raw = bytes(source)
            name = name or "uploaded.csv"
        sha = hashlib.sha256(raw).hexdigest()
        df = _read_frame(raw)
        df.columns = [str(c).strip() for c in df.columns]

        ts_col, ts = _parse_timestamps(df)
        issues: List[str] = []
        if ts is not None:
            order = np.argsort(ts.to_numpy(), kind="stable")
            if not np.all(order == np.arange(len(order))):
                df = df.iloc[order].reset_index(drop=True)
                ts = ts.iloc[order].reset_index(drop=True)
                issues.append("rows were not in time order; sorted by timestamp")
        elif ts_col is None:
            issues.append("no timestamp column; durations are expressed in samples (1 sample assumed = 1 min)")
        else:
            issues.append(f"timestamp column '{ts_col}' is not calendar time; 1 sample assumed = 1 min")

        # Coerce everything except the timestamp to numeric; drop all-text columns.
        dropped: List[str] = []
        for c in list(df.columns):
            if c == ts_col:
                continue
            conv = pd.to_numeric(df[c], errors="coerce")
            if conv.notna().sum() == 0 and df[c].notna().sum() > 0:
                dropped.append(c)
                df = df.drop(columns=[c])
                continue
            df[c] = conv
        if dropped:
            issues.append(f"non-numeric columns ignored: {', '.join(dropped)}")

        interval = None
        if ts is not None and len(ts) > 2:
            diffs = ts.diff().dropna().dt.total_seconds() / 60.0
            diffs = diffs[diffs > 0]
            if len(diffs):
                interval = float(np.median(diffs))

        data_cols = [c for c in df.columns if c != ts_col]
        roles, ring, zones, frame_type = apply_frame(data_cols, frame, frame_maps)
        case = CaseData(
            df=df,
            source_name=name,
            sha256=sha,
            timestamps=ts,
            interval_minutes=interval,
            roles=roles,
            ring=ring,
            zones=zones,
            frame_type=frame_type,
        )
        case.quality = assess_quality(case, ts_col, issues)
        return case


    def assess_quality(case: CaseData, ts_col: Optional[str], issues: List[str]) -> Dict[str, Any]:
        """Function assess_quality."""
        df = case.df
        cols = [c for c in case.numeric_columns if c != ts_col]
        missing = {c: float(df[c].isna().mean()) for c in cols}
        poor = [c for c, f in missing.items() if f > GENERAL["max_missing_fraction"]]
        flat = []
        for c in cols:
            s = df[c].dropna()
            if len(s) > 10 and s.nunique() <= 1 and c not in case.roles.get("trip", []):
                flat.append(c)
        if poor:
            issues.append(f"channels with >{int(GENERAL['max_missing_fraction'] * 100)}% missing: {', '.join(poor)}")
        if flat:
            issues.append(f"flatlined channels (single constant value): {', '.join(flat)}")
        if case.n < GENERAL["min_rows"]:
            issues.append(f"only {case.n} rows (< {GENERAL['min_rows']} needed for reliable baselines)")

        start = case.time_at(0)
        end = case.time_at(case.n - 1)
        duration_h = case.hours_between(0, case.n - 1)
        return {
            "rows": case.n,
            "columns": len(cols),
            "start": start,
            "end": end,
            "duration_hours": round(duration_h, 2),
            "interval_minutes": case.interval_minutes,
            "has_timestamps": case.timestamps is not None,
            "missing_fraction": {c: round(f, 4) for c, f in missing.items() if f > 0},
            "poor_channels": poor,
            "flatlined_channels": flat,
            "issues": issues,
        }
