# sentinel.profiles
# Tag profiles: schema, loader and validation. One JSON file per alert type. A bad file is skipped.
# =============================================================================
# <<<<<<< SECTION sentinel.profiles sentinel/profiles.py
if False:  # compiled by exec_section('sentinel.profiles'); not executed as part of this module
    # @@future@@ from __future__ import annotations

    import copy
    import hashlib
    import json
    import re
    from dataclasses import dataclass, field
    from pathlib import Path
    from typing import Any, Dict, List, Optional, Sequence, Tuple, Union

    from .config import KNN_VOTE_MIN, NOVELTY_QUANTILE, PROFILE_SCHEMA

    # Schema 2 is the alert-type file. Schema 1 still loads and is upgraded on read.
    ROLES = ("context", "process", "flag", "ring", "bank", "ignore")
    ANALYZERS = ("cold_spot", "combustion_dynamics", "hets_trip", "generic")
    SOURCES = ("builtin", "teach", "file", "migration", "import")
    RESERVED_IDS = frozenset({"_adhoc", "_legacy", "_unknown"})
    SLOT_ORDERS = ("numeric", "listed")
    _THRESHOLD_KEYS = ("novelty_quantile", "knn_vote_min", "residual")
    _KEYWORD_NOTE = "keywords no longer select an alert type; add the alert names you need as aliases"
    # Profile ids are at least two characters. Slot ids may be one (`x`) because a
    # site tag name the engineer slugs can be short. Both stay lowercase.
    ID_RE = re.compile(r"^[a-z][a-z0-9_]{1,47}$")
    SLOT_ID_RE = re.compile(r"^[a-z][a-z0-9_]{0,47}$")
    _ALIAS_FORMS = ("prefix", "regex", "tags", "pattern_role")
    # These are not legacy roles, so map_roles and the 14-channel path do not claim them.
    # The schema example names ambient. The built-ins also name shaft speed and inlet dp.
    _EXTRA_PATTERN_ROLES: Dict[str, str] = {
        "ambient": r"ambient|aftamb",
        "speed": r"(^|_)(tnh|tnr|speed|rpm)($|_)",
        "inlet_dp": r"inlet_?dp|afpap|filter.?house",
    }

    # What each built-in analyzer needs from the slot list. Step 7 copies the same
    # dict onto the analyzer module as REQUIRES. Validation reads the module when
    # that attribute exists, and this table until then, so the wizard and the
    # loader agree.
    FALLBACK_REQUIRES: Dict[str, Dict[str, Any]] = {
        "cold_spot": {"ring_or_zones": True, "load": True},
        "combustion_dynamics": {"legacy_any": ["dynamics"]},
        "hets_trip": {"ring_or_zones": True, "legacy_any": ["spread", "trip"]},
        "generic": {},
    }

    class SignatureSpec(str):
        """A signature id that also remembers the taxonomy action written in the file.

        It compares equal to the id string, so ``"normal" in profile.signatures`` and a
        report that JSON-encodes the list keep working. The action is checked, not chosen,
        by this class: the taxonomy stays the single source.
        """

        action: str

        def __new__(cls, sid: str, action: str) -> "SignatureSpec":
            obj = str.__new__(cls, str(sid))
            obj.action = str(action)
            return obj

        def to_dict(self) -> Dict[str, str]:
            return {"id": str(self), "action": self.action}

        def __deepcopy__(self, memo: Dict[int, Any]) -> "SignatureSpec":
            return SignatureSpec(str(self), self.action)

        def __reduce__(self) -> Tuple[Any, Tuple[str, str]]:
            return (SignatureSpec, (str(self), self.action))


    @dataclass
    class Slot:
        """One logical tag. Channel order is the slot order in the profile file.

        ``required`` stays on the object so coverage math is unchanged, and it is always
        true: schema 2 has no optional slots. ``order`` and ``members`` describe a ring
        or a bank. They are not part of the channels hash.
        """

        id: str
        role: str
        label: str = ""
        unit: str = ""
        required: bool = True
        weight: float = 1.0
        load_fit: bool = False
        health: bool = False
        aliases: Dict[str, Any] = field(default_factory=dict)
        legacy_role: str = ""
        order: str = ""
        members: Dict[str, int] = field(default_factory=dict)

        def to_dict(self) -> Dict[str, Any]:
            """JSON object. ``required`` is omitted because every slot is expected."""
            out: Dict[str, Any] = {
                "id": self.id,
                "role": self.role,
                "label": self.label,
                "unit": self.unit,
                "weight": self.weight,
            }
            if self.health or self.role == "ring":
                out["health"] = bool(self.health)
            if self.role == "ring":
                out["order"] = self.order or "numeric"
            if self.members and self.role in ("ring", "bank"):
                out["members"] = {str(k): int(v) for k, v in self.members.items()}
            if self.role == "process":
                out["load_fit"] = bool(self.load_fit)
            out["aliases"] = copy.deepcopy(self.aliases)
            if self.legacy_role:
                out["legacy_role"] = self.legacy_role
            return out


    def _default_thresholds() -> Dict[str, Any]:
        """The built-in defaults. A file may override them inside the allowed ranges."""
        return {
            "novelty_quantile": float(NOVELTY_QUANTILE),
            "knn_vote_min": float(KNN_VOTE_MIN),
            "residual": {},
        }


    @dataclass
    class Profile:
        """One alert type. A site file with the same id replaces the built-in.

        ``aliases`` are the other alert names that mean this type. ``match`` is kept
        only so the old name score still sees keywords until routing is removed:
        ``to_dict`` does not write it.
        """

        id: str
        name: str
        slots: List[Slot] = field(default_factory=list)
        schema: int = PROFILE_SCHEMA
        rev: int = 1
        description: str = ""
        aliases: List[str] = field(default_factory=list)
        match: Dict[str, List[str]] = field(default_factory=lambda: {"names": [], "keywords": []})
        include_other: bool = True
        couple: List[List[str]] = field(default_factory=list)
        signatures: List[Any] = field(default_factory=list)
        residual_expect: Dict[str, Dict[str, List[str]]] = field(default_factory=dict)
        thresholds: Dict[str, Any] = field(default_factory=_default_thresholds)
        analyzer: Optional[str] = "generic"
        docs: List[str] = field(default_factory=list)
        source: str = "file"
        created: str = ""
        updated: str = ""
        note: str = ""
        needs_review: bool = False

        def slot_ids(self) -> List[str]:
            return [s.id for s in self.slots]

        def alert_aliases(self) -> List[str]:
            """Names besides the canonical name. A profile built with only ``match.names`` still counts."""
            if self.aliases:
                return [str(a) for a in self.aliases if str(a).strip()]
            return [str(a) for a in (self.match.get("names") or []) if str(a).strip()]

        def to_dict(self, data_dir: Optional[Path] = None) -> Dict[str, Any]:
            """Schema 2 JSON. Keys stay in the order the design example uses.

            ``data_dir`` lets a site-added signature pick up its taxonomy action.
            """
            analyzer = self.analyzer if self.analyzer else "generic"
            thresholds = _default_thresholds()
            raw_thr = self.thresholds if isinstance(self.thresholds, dict) else {}
            if "novelty_quantile" in raw_thr:
                thresholds["novelty_quantile"] = float(raw_thr["novelty_quantile"])
            if "knn_vote_min" in raw_thr:
                thresholds["knn_vote_min"] = float(raw_thr["knn_vote_min"])
            residual = raw_thr.get("residual") if isinstance(raw_thr.get("residual"), dict) else {}
            thresholds["residual"] = {str(k): float(v) for k, v in residual.items()}
            out: Dict[str, Any] = {
                "schema": PROFILE_SCHEMA,
                "id": self.id,
                "name": self.name,
                "aliases": self.alert_aliases(),
                "rev": int(self.rev),
                "description": self.description or "",
                "slots": [s.to_dict() for s in self.slots],
                "include_other": bool(self.include_other),
                "couple": [list(pair) for pair in self.couple],
                "signatures": [_signature_dict(sig, data_dir) for sig in self.signatures],
                "residual_expect": copy.deepcopy(self.residual_expect),
                "thresholds": thresholds,
                "analyzer": analyzer,
                "docs": list(self.docs),
                "source": self.source,
            }
            if self.created:
                out["created"] = self.created
            if self.updated:
                out["updated"] = self.updated
            if self.note:
                out["note"] = self.note
            if self.needs_review:
                out["needs_review"] = True
            return out


    def _star(role: str, *extra: str) -> Dict[str, Any]:
        """``*`` alias: both tag dialects, then the role pattern, so today's CSVs still resolve."""
        from .config import _ROLES_FRIENDLY, _ROLES_HISTORIAN

        names: List[str] = []
        for tag in extra:
            if tag not in names:
                names.append(tag)
        for block in (_ROLES_FRIENDLY, _ROLES_HISTORIAN):
            for tag in block.get(role, []):
                if tag not in names:
                    names.append(tag)
        forms: List[Any] = []
        if names:
            forms.append(names)
        forms.append({"pattern_role": role})
        return {"*": forms}


    def _ring_alias() -> Dict[str, Any]:
        """Exhaust ring or zones. The first prefix with two or more columns wins."""
        return {
            "*": [
                {"prefix": ["TC", "TTXD", "EGT_Z", "EGT_ZONE"]},
                {"pattern_role": "ring"},
                {"pattern_role": "zones"},
            ]
        }


    def _pslot(
        sid: str,
        role: str,
        label: str,
        unit: str = "",
        required: bool = True,
        legacy: str = "",
        aliases: Optional[Dict[str, Any]] = None,
        health: Optional[bool] = None,
        load_fit: Optional[bool] = None,
    ) -> Dict[str, Any]:
        # ``required`` is accepted so older call sites still read clearly. Schema 2
        # has no optional slot, so the file always says true.
        del required
        row: Dict[str, Any] = {
            "id": sid,
            "role": role,
            "label": label,
            "unit": unit,
            "required": True,
            "aliases": aliases if aliases is not None else _star(legacy or sid),
        }
        if legacy:
            row["legacy_role"] = legacy
        if health is not None:
            row["health"] = bool(health)
        if load_fit is not None:
            row["load_fit"] = bool(load_fit)
        return row


    def _builtin(pid: str, name: str, description: str, aliases: Sequence[str],
                 slots: Sequence[Dict[str, Any]], signatures: Sequence[str], analyzer: str,
                 docs: Sequence[str], expect: Optional[Dict[str, Any]] = None,
                 couple: Optional[Sequence[Sequence[str]]] = None) -> Dict[str, Any]:
        """One built-in alert type as schema 2. Keywords are not stored: a name matches or it does not."""
        return {
            "schema": PROFILE_SCHEMA,
            "id": pid,
            "name": name,
            "aliases": list(aliases),
            "rev": 1,
            "description": description,
            "slots": copy.deepcopy(list(slots)),
            "include_other": True,
            "couple": [list(pair) for pair in (couple or [])],
            "signatures": list(signatures),
            "residual_expect": expect or {},
            "thresholds": {
                "novelty_quantile": NOVELTY_QUANTILE,
                "knn_vote_min": KNN_VOTE_MIN,
                "residual": {},
            },
            "analyzer": analyzer,
            "docs": list(docs),
            "source": "builtin",
        }


