# sentinel.knowledge
# Retrieve process-map sections for the prompt. Learned 'why' notes from Teach sit beside the shipped maps.
# =============================================================================
# <<<<<<< SECTION sentinel.knowledge sentinel/knowledge.py
if False:  # compiled by exec_section('sentinel.knowledge'); not executed as part of this module
    """Knowledge retrieval over knowledge/*.md (process maps) with a small BM25.

    Built-in process maps live in ``knowledge/*.md``. Engineers add their own process / technical
    background from the UI ("Teach the app"); those are saved as ``knowledge/user/*.md`` with a tag
    header (alert types / analytics, signatures) and take part in retrieval for both paths:

    * rule path (``retrieve``): the analytic's own process map; user documents tagged for the analytic
      come first; generic analytics use BM25 over everything.
    * learned path (``retrieve_learned``): user documents tagged for the predicted signature or the
      analytic, the decision-flow sections of the signature's / analytic's process maps, then BM25 on
      the analytic name + notes + signature — capped to a token budget. With a profile, that alert
      type's documents come first (decision-flow sections, then the rest), then engineer files tagged
      for the profile id or the signature, then BM25. Another alert type's process map is left out.
    """

    # @@future@@ from __future__ import annotations

    import json
    import math
    import re
    from collections import Counter
    from dataclasses import dataclass, field
    from pathlib import Path
    from typing import Any, Dict, List, Optional, Sequence

    from .config import KNOWLEDGE_DIR

    USER_SUBDIR = "user"
    _META = re.compile(r"^<!--\s*sentinel-doc:\s*(\{.*\})\s*-->\s*$")

    ANALYTIC_DOCS = {
        "cold_spot": "process_map_cold_spot.md",
        "combustion_dynamics": "process_map_combustion_dynamics.md",
        "hets_trip": "process_map_hets_trip.md",
    }

    # Related background for each analytic (deterministic, so the context is auditable)
    RELATED_DOCS = {
        "cold_spot": ["process_map_exhaust_spread.md"],
        "hets_trip": ["process_map_exhaust_spread.md"],
        "combustion_dynamics": [],
    }

    # Learned-path signatures -> the process maps that cover them (first = primary)
    SIGNATURE_DOCS = {
        "cold_spot_hardware": ["process_map_cold_spot.md", "process_map_exhaust_spread.md"],
        "tc_sensor_fault": ["process_map_exhaust_spread.md", "process_map_cold_spot.md"],
        "combustion_instability": ["process_map_combustion_dynamics.md"],
        "dynamics_probe_fault": ["process_map_combustion_dynamics.md"],
        "hets_trip_hardware": ["process_map_hets_trip.md", "process_map_exhaust_spread.md"],
        "igv_lvdt_drift": ["gt_overview.md"],
        "fuel_control_oscillation": ["gt_overview.md"],
        "novel_pattern": ["gt_overview.md", "process_map_vibration.md"],
    }
    CHARS_PER_TOKEN = 3.6  # measured on Gemma 4 for this English technical text (see eval/EVAL.md)

    _WORD = re.compile(r"[a-z0-9]+")


    @dataclass
    class Section:
        """Class Section."""
        doc: str
        heading: str
        text: str
        analytics: List[str] = field(default_factory=list)
        signatures: List[str] = field(default_factory=list)
        user: bool = False
        title: str = ""

        @property
        def ref(self) -> str:
            """Function ref."""
            return f"{'user/' if self.user else ''}{self.doc} § {self.heading}"


    def _tokens(text: str) -> List[str]:
        """Function _tokens."""
        return [t for t in _WORD.findall(text.lower()) if len(t) > 2]


    def read_meta(text: str) -> Dict[str, Any]:
        """Tag header of a user document (first line ``<!-- sentinel-doc: {...} -->``), or {}."""
        first = text.split("\n", 1)[0].strip()
        m = _META.match(first)
        if not m:
            return {}
        try:
            return json.loads(m.group(1))
        except ValueError:
            return {}


    def _norm_tag(t: str) -> str:
        """Function _norm_tag."""
        return re.sub(r"[^a-z0-9]+", "_", str(t).strip().lower()).strip("_")


    def _parse(p: Path, user: bool) -> List[Section]:
        """Function _parse."""
        text = p.read_text(encoding="utf-8")
        meta = read_meta(text) if user else {}
        if meta.get("deleted"):
            return []
        tags_a = [_norm_tag(t) for t in meta.get("analytics") or []]
        tags_s = [_norm_tag(t) for t in meta.get("signatures") or []]
        out: List[Section] = []
        heading, buf = (meta.get("title") or p.stem), []

        def flush() -> None:
            """Function flush."""
            if "".join(buf).strip():
                out.append(Section(p.name, heading, "\n".join(buf).strip(), tags_a, tags_s, user, meta.get("title") or p.stem))

        for line in text.splitlines():
            if _META.match(line.strip()):
                continue
            if line.startswith("## "):
                flush()
                heading, buf = line[3:].strip(), []
            elif line.startswith("# "):
                continue
            else:
                buf.append(line)
        flush()
        return out


    def load_sections(folder: Path = KNOWLEDGE_DIR) -> List[Section]:
        """Function load_sections."""
        out: List[Section] = []
        for p in sorted(Path(folder).glob("*.md")):
            out += _parse(p, user=False)
        udir = Path(folder) / USER_SUBDIR
        if udir.is_dir():
            for p in sorted(udir.glob("*.md")):
                out += _parse(p, user=True)
        return out


    class BM25:
        """Class BM25."""
        def __init__(self, docs: List[List[str]], k1: float = 1.4, b: float = 0.75) -> None:
            """Function __init__."""
            self.docs = docs
            self.k1, self.b = k1, b
            self.avg = sum(len(d) for d in docs) / max(1, len(docs))
            df: Counter = Counter()
            for d in docs:
                df.update(set(d))
            n = len(docs)
            self.idf = {t: math.log(1 + (n - f + 0.5) / (f + 0.5)) for t, f in df.items()}
            self.tf = [Counter(d) for d in docs]

        def score(self, query: List[str], i: int) -> float:
            """Function score."""
            tf, dl = self.tf[i], len(self.docs[i])
            s = 0.0
            for t in query:
                if t not in tf:
                    continue
                f = tf[t]
                s += self.idf.get(t, 0.0) * f * (self.k1 + 1) / (f + self.k1 * (1 - self.b + self.b * dl / max(self.avg, 1e-9)))
            return s


    def _item(s: Section, why: str) -> Dict[str, str]:
        """Function _item."""
        return {"ref": s.ref, "text": s.text, "why": why}


    def retrieve(analytic: str, query: str, k_extra: int = 2, folder: Path = KNOWLEDGE_DIR, alert_name: str = "") -> List[Dict[str, str]]:
        """Process-map sections for the rule-path narrative.

        ``alert_name`` is the analytic name as Tier 1 typed it. An alert type added from Teach has no
        built-in analyzer, so its engineer document is found by that name rather than by ``analytic``.
        """
        sections = load_sections(folder)
        if not sections:
            return []
        own_doc: Optional[str] = ANALYTIC_DOCS.get(analytic)
        tags = {t for t in (analytic, _norm_tag(alert_name)) if t}
        # engineer-added documents tagged for this analytic come first (the site's own process)
        picked: List[Section] = [s for s in sections if s.user and tags & set(s.analytics)][:2]
        if own_doc:
            picked += [s for s in sections if not s.user and s.doc == own_doc and re.search(r"decision flow|typical plant signatures|action", s.heading, re.I)]
            picked += [s for s in sections if not s.user and s.doc in RELATED_DOCS.get(analytic, []) and re.search(r"decision flow", s.heading, re.I)]
            return [{"ref": s.ref, "text": s.text} for s in picked]
        rest = [s for s in sections if s not in picked]
        bm = BM25([_tokens(s.heading + " " + s.text) for s in rest])
        q = _tokens(query)
        ranked = sorted(range(len(rest)), key=lambda i: bm.score(q, i), reverse=True)
        for i in ranked[:k_extra]:
            if bm.score(q, i) > 0:
                picked.append(rest[i])
        return [{"ref": s.ref, "text": s.text} for s in picked]


    def approx_tokens(text: str) -> int:
        """Function approx_tokens."""
        return int(math.ceil(len(text) / CHARS_PER_TOKEN))


    def _compact(text: str) -> str:
        """Function _compact."""
        return re.sub(r"[ \t]+", " ", re.sub(r"\n\s*\n+", "\n", text)).strip()


    def retrieve_learned(
        analytic_name: str,
        notes: str,
        signature: str,
        signature_title: str = "",
        token_cap: int = 700,
        extra_signatures: Sequence[str] = (),
        folder: Path = KNOWLEDGE_DIR,
        profile: Any = None,
    ) -> List[Dict[str, str]]:
        """Process / technical-background sections for the learned-path prompt, within ``token_cap``.

        Order: user documents tagged for the predicted signature (or a signature the residual check
        points to), user documents tagged for the analytic, the decision-flow sections of the
        signature's and the analytic's process maps, then BM25 on analytic + notes + signature.
        """
        from .analytics import resolve

        sections = load_sections(folder)
        if not sections or token_cap <= 0:
            return []
        if profile is not None:
            picked = _pick_profile_knowledge(sections, profile, analytic_name, notes, signature, signature_title, extra_signatures)
            return _cap_sections(picked, token_cap)
        res = resolve(analytic_name or "")
        analytic = res.analytic if res.known else ""
        # An alert type added from Teach has no built-in analyzer, so ``analytic`` is empty for it. Its
        # process document is tagged with the alert name itself; without this tag the generic fallback
        # only reached that document if BM25 happened to rank it above the shipped process maps.
        alert_tag = _norm_tag(analytic_name or "")
        sigs = [signature] + [s for s in extra_signatures if s and s != signature]
        picked: List[tuple] = []

        def add(s: Section, why: str) -> None:
            """Function add."""
            if all(s is not p[0] for p in picked):
                picked.append((s, why))

        for sg in sigs:
            for s in sections:
                if s.user and sg in s.signatures:
                    add(s, f"engineer document tagged for {sg}")
        for s in sections:
            if s.user and ((analytic and analytic in s.analytics) or (alert_tag and alert_tag in s.analytics)):
                add(s, f"engineer document tagged for {analytic or analytic_name}")
        docs: List[str] = []
        for sg in sigs:
            docs += [d for d in SIGNATURE_DOCS.get(sg, []) if d not in docs]
        if analytic and ANALYTIC_DOCS.get(analytic) and ANALYTIC_DOCS[analytic] not in docs:
            docs.append(ANALYTIC_DOCS[analytic])
        for d in docs:
            for s in sections:
                if not s.user and s.doc == d and re.search(r"decision flow|quick checks|alerts focus|common failure", s.heading, re.I):
                    add(s, f"process map for {sigs[0] if d in SIGNATURE_DOCS.get(sigs[0], []) else (analytic or 'the case')}")
        # BM25 extras: engineer documents and general background only — another signature's process map
        # (or its sample-file / data-capture notes) would mislead the report writer
        skip = re.compile(r"sample csvs|data to capture|purpose|preconditions", re.I)
        rest = [s for s in sections if all(s is not p[0] for p in picked) and not skip.search(s.heading)
                and (s.user or not s.doc.startswith("process_map_") or s.doc in docs)]
        if rest:
            bm = BM25([_tokens(s.heading + " " + s.text) for s in rest])
            q = _tokens(f"{analytic_name} {notes} {signature.replace('_', ' ')} {signature_title}")
            ranked = sorted(range(len(rest)), key=lambda i: bm.score(q, i), reverse=True)
            top = bm.score(q, ranked[0]) if ranked else 0.0
            for i in ranked[:2]:
                if bm.score(q, i) > max(1.0, 0.5 * top):
                    add(rest[i], "matches the analytic / notes")
        out: List[Dict[str, str]] = []
        budget = token_cap
        for s, why in picked:
            txt = _compact(s.text)
            head = approx_tokens(s.ref) + 4
            if budget - head < 40:
                break
            room = int((budget - head) * CHARS_PER_TOKEN)
            if len(txt) > room:
                cut = txt[:room]
                nl = cut.rfind("\n")
                txt = (cut[:nl] if nl > room // 2 else cut.rstrip()) + " …"
            out.append({"ref": s.ref, "text": txt, "why": why})
            budget -= head + approx_tokens(txt)
        return out


    def _cap_sections(picked: List[tuple], token_cap: int) -> List[Dict[str, str]]:
        """Trim picked sections to the token cap. The last section is cut rather than dropped when a little room remains."""
        out: List[Dict[str, str]] = []
        budget = token_cap
        for s, why in picked:
            txt = _compact(s.text)
            head = approx_tokens(s.ref) + 4
            if budget - head < 40:
                break
            room = int((budget - head) * CHARS_PER_TOKEN)
            if len(txt) > room:
                cut = txt[:room]
                nl = cut.rfind("\n")
                txt = (cut[:nl] if nl > room // 2 else cut.rstrip()) + " …"
            out.append({"ref": s.ref, "text": txt, "why": why})
            budget -= head + approx_tokens(txt)
        return out


    def _pick_profile_knowledge(sections: List[Section], profile: Any, analytic_name: str, notes: str, signature: str,
                                signature_title: str, extra_signatures: Sequence[str]) -> List[tuple]:
        """Profile documents first, then engineer files tagged for this alert type or signature, then BM25.

        Another alert type's process map is not retrieved. The legacy order is unchanged when no profile is passed.
        """
        if isinstance(profile, dict):
            pid = str(profile.get("id") or "")
            docs = [str(d) for d in (profile.get("docs") or [])]
        else:
            pid = str(getattr(profile, "id", "") or "")
            docs = [str(d) for d in (getattr(profile, "docs", None) or [])]
        picked: List[tuple] = []

        def add(s: Section, why: str) -> None:
            if all(s is not row[0] for row in picked):
                picked.append((s, why))

        decision = re.compile(r"decision flow|quick checks|alerts focus|common failure", re.I)
        for doc in docs:
            for s in sections:
                if not s.user and s.doc == doc and decision.search(s.heading):
                    add(s, f"process map for {pid or doc}")
        for doc in docs:
            for s in sections:
                if not s.user and s.doc == doc:
                    add(s, f"process map for {pid or doc}")
        sigs = [signature] + [s for s in extra_signatures if s and s != signature]
        for s in sections:
            if not s.user:
                continue
            if pid and (pid in s.analytics or pid in s.signatures):
                add(s, f"engineer document tagged for {pid}")
            elif any(sg in s.signatures for sg in sigs if sg):
                named = next(sg for sg in sigs if sg in s.signatures)
                add(s, f"engineer document tagged for {named}")
        skip = re.compile(r"sample csvs|data to capture|purpose|preconditions", re.I)
        rest = [s for s in sections if all(s is not row[0] for row in picked) and not skip.search(s.heading)
                and (s.user or not s.doc.startswith("process_map_") or s.doc in docs)]
        if rest:
            bm = BM25([_tokens(s.heading + " " + s.text) for s in rest])
            q = _tokens(f"{analytic_name} {notes} {signature.replace('_', ' ')} {signature_title}")
            ranked = sorted(range(len(rest)), key=lambda i: bm.score(q, i), reverse=True)
            top = bm.score(q, ranked[0]) if ranked else 0.0
            for i in ranked[:2]:
                if bm.score(q, i) > max(1.0, 0.5 * top):
                    add(rest[i], "matches the analytic / notes")
        return picked
# >>>>>>> END sentinel.knowledge

