# sentinel.llm_runtime
# The one LLM: Gemma 4 12B Q4_K_M. GPU offload when it loads, else CPU, else the template.
# =============================================================================
# <<<<<<< SECTION sentinel.llm_runtime sentinel/llm_runtime.py
if False:  # compiled by exec_section('sentinel.llm_runtime'); not executed as part of this module
    """Local LLM runtime: Gemma 4 12B instruct Q4_K_M (the one LLM) through llama-cpp-python, fully offline.

    * ``gguf_path``: where the Gemma GGUF lives (default ``models/gemma-4-12b-it-Q4_K_M.gguf``).
    * ``device``: ``auto`` (GPU offload if an NVIDIA GPU and a CUDA build of llama-cpp-python are
      present, else CPU), ``gpu`` or ``cpu``.
    * ``n_gpu_layers``: ``auto`` (from free VRAM and the model's per-layer size — about 25-30 of
      Gemma 4 12B's 48 layers on a 6 GB card) or an explicit number.
    * If GPU initialisation fails or runs out of memory, the runtime reloads on CPU and records why;
      the reason is shown in the report's audit section.
    * If the model is missing or fails on every device, callers fall back to the deterministic
      template report (no LLM).

    The chat template comes from the GGUF itself.
    """

    # @@future@@ from __future__ import annotations

    import os
    import shutil
    import struct
    import subprocess
    import threading
    import time
    from dataclasses import asdict, dataclass, field
    from pathlib import Path
    from typing import Any, Dict, List, Optional

    from .config import ROOT, Settings

    GEMMA: Dict[str, Any] = {
        "file": "models/gemma-4-12b-it-Q4_K_M.gguf",
        "label": "Gemma 4 12B instruct (Q4_K_M)",
        "repo": "unsloth/gemma-4-12b-it-GGUF",
        "url": "https://huggingface.co/unsloth/gemma-4-12b-it-GGUF/resolve/main/gemma-4-12b-it-Q4_K_M.gguf",
        "sha256": "0a270ec9fe6b34f4a0d33992b6135117b484ebc4766ab76b51d4ae8c457e4c42",
        "size": 7121861440,
    }
    VRAM_RESERVE_MB = 1300  # KV cache, compute buffers and the desktop
    _LOCK = threading.Lock()
    _LOADED: Dict[str, Any] = {}


    @dataclass
    class GpuInfo:
        """Class GpuInfo."""
        nvidia: bool = False
        name: str = ""
        vram_total_mb: int = 0
        vram_free_mb: int = 0
        driver: str = ""
        error: str = ""


    @dataclass
    class Plan:
        """Class Plan."""
        profile: str
        model_path: Optional[str]
        model_label: str
        model_found: bool
        requested_device: str
        device: str  # "gpu" | "cpu"
        n_gpu_layers: int
        n_layers: Optional[int]
        threads: int
        reason: str
        gpu: GpuInfo = field(default_factory=GpuInfo)
        llama_cpp_version: str = ""
        llama_gpu_offload: bool = False

        def to_dict(self) -> Dict[str, Any]:
            """Function to_dict."""
            return asdict(self)


    def detect_gpu() -> GpuInfo:
        """Function detect_gpu."""
        exe = shutil.which("nvidia-smi")
        if not exe:
            return GpuInfo(error="nvidia-smi not found (no NVIDIA driver)")
        try:
            p = subprocess.run(
                [exe, "--query-gpu=name,memory.total,memory.free,driver_version", "--format=csv,noheader,nounits"],
                capture_output=True, text=True, timeout=10, creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            line = (p.stdout or "").strip().splitlines()[0]
            name, total, free, drv = [x.strip() for x in line.split(",")]
            return GpuInfo(True, name, int(float(total)), int(float(free)), drv)
        except Exception as exc:  # noqa: BLE001
            return GpuInfo(error=f"nvidia-smi failed: {exc}")


    def _add_cuda_dll_dirs() -> None:
        """CUDA wheels of llama-cpp-python need cudart/cublas; install.ps1 gets them from the NVIDIA pip
        packages (site-packages/nvidia/*/bin). Make them loadable without a system CUDA toolkit."""
        if os.name != "nt" or getattr(_add_cuda_dll_dirs, "_done", False):
            return
        _add_cuda_dll_dirs._done = True  # type: ignore[attr-defined]
        import site

        for sp in site.getsitepackages():
            for b in Path(sp, "nvidia").glob("*/bin"):
                try:
                    os.add_dll_directory(str(b))
                    os.environ["PATH"] = str(b) + os.pathsep + os.environ.get("PATH", "")
                except OSError:
                    pass


    def llama_cpp_info() -> Dict[str, Any]:
        """Function llama_cpp_info."""
        _add_cuda_dll_dirs()
        try:
            import llama_cpp

            return {"installed": True, "version": llama_cpp.__version__, "gpu_offload": bool(llama_cpp.llama_supports_gpu_offload())}
        except Exception as exc:  # noqa: BLE001
            return {"installed": False, "version": "", "gpu_offload": False, "error": str(exc)}


    def gguf_block_count(path: Path) -> Optional[int]:
        """Read ``<arch>.block_count`` from a GGUF header (stops early; no full parse)."""
        try:
            with open(path, "rb") as f:
                if f.read(4) != b"GGUF":
                    return None
                f.read(4)
                f.read(8)
                nkv = struct.unpack("<Q", f.read(8))[0]
                sizes = {0: 1, 1: 1, 2: 2, 3: 2, 4: 4, 5: 4, 6: 4, 7: 1, 10: 8, 11: 8, 12: 8}

                def rstr() -> str:
                    """Function rstr."""
                    n = struct.unpack("<Q", f.read(8))[0]
                    return f.read(n).decode("utf-8", "replace")

                def skip(t: int) -> None:
                    """Function skip."""
                    if t == 8:
                        rstr()
                    elif t == 9:
                        at = struct.unpack("<I", f.read(4))[0]
                        n = struct.unpack("<Q", f.read(8))[0]
                        if at == 8:
                            for _ in range(n):
                                rstr()
                        else:
                            f.seek(n * sizes[at], 1)
                    else:
                        f.seek(sizes[t], 1)

                for _ in range(nkv):
                    key = rstr()
                    t = struct.unpack("<I", f.read(4))[0]
                    if key.endswith(".block_count") and t in (4, 5, 10):
                        return int(struct.unpack("<I" if t in (4, 5) else "<Q", f.read(4 if t in (4, 5) else 8))[0])
                    skip(t)
        except (OSError, struct.error, KeyError):
            return None
        return None


    def resolve_model(settings: Settings) -> Dict[str, Any]:
        """The Gemma GGUF: ``gguf_path`` if set, else models/gemma-4-12b-it-Q4_K_M.gguf."""
        path = Path(settings.gguf_path) if settings.gguf_path else ROOT / GEMMA["file"]
        if not path.is_absolute():
            path = ROOT / path
        return {"profile": "gemma", "path": path, "label": GEMMA["label"], "found": path.is_file(), "spec": GEMMA}


    def unused_ggufs(models_dir: Path, active: Optional[Path] = None) -> List[Path]:
        """GGUF files under models/ that are not the one LLM. Doctor lists these; nothing loads them."""
        root = Path(models_dir)
        if not root.is_dir():
            return []
        chosen = active.resolve() if active is not None and Path(active).is_file() else None
        found = []
        for path in sorted(root.rglob("*.gguf")):
            if chosen is not None and path.resolve() == chosen:
                continue
            found.append(path)
        return found


    def plan(settings: Settings, gpu: Optional[GpuInfo] = None) -> Plan:
        """Function plan."""
        m = resolve_model(settings)
        req = (settings.device or "auto").lower()
        if req not in ("auto", "gpu", "cpu"):
            req = "auto"
        li = llama_cpp_info()
        gpu = gpu if gpu is not None else (detect_gpu() if req != "cpu" else GpuInfo(error="not checked (device=cpu)"))
        n_layers = gguf_block_count(m["path"]) if m["found"] else None
        threads = settings.llm_threads
        device, layers, reason = "cpu", 0, ""
        if req == "cpu":
            reason = "device=cpu requested"
        elif not gpu.nvidia:
            reason = f"no NVIDIA GPU ({gpu.error or 'not found'})" + (" — device=gpu requested, falling back to CPU" if req == "gpu" else "")
        elif not li["gpu_offload"]:
            reason = "llama-cpp-python is a CPU build (no CUDA offload) — reinstall with install.ps1 on a GPU machine"
            if req == "gpu":
                reason += "; device=gpu requested, falling back to CPU"
        else:
            device = "gpu"
            cfg = str(settings.n_gpu_layers).strip().lower()
            if cfg not in ("", "auto", "none"):
                layers = int(cfg)
                reason = f"n_gpu_layers={layers} (configured)"
            elif n_layers and m["found"]:
                per_layer_mb = m["path"].stat().st_size / 1e6 / (n_layers + 2)
                layers = int(max(0, min(n_layers + 1, (gpu.vram_free_mb - VRAM_RESERVE_MB) // max(per_layer_mb, 1))))
                reason = f"auto: {gpu.vram_free_mb} MB free VRAM, ~{per_layer_mb:.0f} MB/layer, {VRAM_RESERVE_MB} MB reserve -> {layers}/{n_layers} layers"
            else:
                layers = 999
                reason = "auto: model size unknown, offloading all layers"
            if layers <= 0:
                device, reason = "cpu", reason + " — not enough free VRAM, using CPU"
        return Plan(
            profile=m["profile"], model_path=str(m["path"]), model_label=m["label"], model_found=m["found"],
            requested_device=req, device=device, n_gpu_layers=layers if device == "gpu" else 0, n_layers=n_layers,
            threads=threads, reason=reason, gpu=gpu, llama_cpp_version=li.get("version", ""), llama_gpu_offload=li["gpu_offload"],
        )


    def available(settings: Settings) -> bool:
        """Function available."""
        return bool(settings.use_llm and resolve_model(settings)["found"] and llama_cpp_info()["installed"])


    def _quiet_llama_logs() -> None:
        """Route llama.cpp's C-level log lines to nowhere (verbose=False does not cover all of them)."""
        if getattr(_quiet_llama_logs, "_done", False):
            return
        try:
            import ctypes

            import llama_cpp

            @llama_cpp.llama_log_callback
            def _noop(level, text, user_data):  # noqa: ANN001
                """Function _noop."""
                return None

            _quiet_llama_logs._cb = _noop  # type: ignore[attr-defined]  # keep a reference alive
            llama_cpp.llama_log_set(_noop, ctypes.c_void_p(0))
            _quiet_llama_logs._done = True  # type: ignore[attr-defined]
        except Exception:  # noqa: BLE001 — logging is cosmetic
            pass


    def _load(path: str, n_gpu_layers: int, ctx: int, threads: int) -> Any:
        """Function _load."""
        _add_cuda_dll_dirs()
        _quiet_llama_logs()
        from llama_cpp import Llama

        key = f"{path}|{n_gpu_layers}|{ctx}|{threads}"
        if key not in _LOADED:
            for k in list(_LOADED):  # keep one model resident (RAM / VRAM)
                _LOADED.pop(k, None)
            _LOADED[key] = Llama(model_path=path, n_ctx=ctx, n_threads=threads, n_threads_batch=threads, n_gpu_layers=n_gpu_layers, seed=42, verbose=False)
        return _LOADED[key]


    def unload() -> None:
        """Function unload."""
        with _LOCK:
            _LOADED.clear()


    def _is_gpu_error(exc: BaseException) -> bool:
        """Function _is_gpu_error."""
        s = str(exc).lower()
        return any(k in s for k in ("cuda", "out of memory", "oom", "cublas", "ggml_cuda", "failed to create llama_context", "failed to load model", "vram"))


    def check_schema(schema: Any) -> None:
        """Refuse schemas llama.cpp cannot turn into a grammar.

        String length bounds (minLength / maxLength) and large item counts expand into huge grammar
        repetitions; llama.cpp then prints "error parsing grammar" and the NULL grammar crashes the
        process natively (access violation) instead of raising. Fail early with a Python error instead.
        """
        if isinstance(schema, dict):
            for k, v in schema.items():
                if k in ("minLength", "maxLength") or (k in ("minItems", "maxItems") and isinstance(v, int) and v > 20):
                    raise ValueError(f"JSON schema uses '{k}', which llama.cpp grammars cannot handle reliably")
                check_schema(v)
        elif isinstance(schema, list):
            for v in schema:
                check_schema(v)


    def chat_json(settings: Settings, system: str, user: str, schema: Dict[str, Any], max_tokens: Optional[int] = None) -> Dict[str, Any]:
        """One schema-constrained chat completion. Returns text, timings and device audit."""
        _add_cuda_dll_dirs()
        check_schema(schema)
        p = plan(settings)
        if not p.model_found:
            raise FileNotFoundError(f"GGUF not found: {p.model_path}")
        messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]
        attempts = [(p.device, p.n_gpu_layers)]
        if p.device == "gpu":
            attempts.append(("cpu", 0))
        notes: List[str] = []
        if p.requested_device == "gpu" and p.device == "cpu":
            notes.append(f"GPU requested but not usable: {p.reason}")
        last: Optional[BaseException] = None
        for device, layers in attempts:
            t0 = time.monotonic()
            try:
                with _LOCK:
                    llm = _load(p.model_path or "", layers, settings.llm_ctx, p.threads)
                    t_load = time.monotonic() - t0
                    t1 = time.monotonic()
                    out = llm.create_chat_completion(
                        messages=messages,
                        response_format={"type": "json_object", "schema": schema},
                        temperature=0.0,
                        seed=42,
                        max_tokens=max_tokens or settings.llm_max_tokens,
                    )
                gen_s = time.monotonic() - t1
                usage = out.get("usage") or {}
                return {
                    "text": out["choices"][0]["message"]["content"] or "",
                    "finish_reason": out["choices"][0].get("finish_reason"),
                    "usage": usage,
                    "load_s": round(t_load, 1),
                    "gen_s": round(gen_s, 1),
                    "tok_per_s": round((usage.get("completion_tokens") or 0) / gen_s, 2) if gen_s > 0 else None,
                    "device": device,
                    "n_gpu_layers": layers,
                    "plan": p.to_dict(),
                    "fallback": "; ".join(notes),
                    "model_label": p.model_label,
                    "model_file": Path(p.model_path or "").name,
                }
            except Exception as exc:  # noqa: BLE001
                last = exc
                unload()
                if device == "gpu":  # any GPU failure (init, VRAM) -> retry on CPU, recorded for the audit
                    kind = "out of VRAM / GPU error" if _is_gpu_error(exc) else "GPU error"
                    notes.append(f"GPU ({layers} layers) failed ({kind}: {str(exc)[:160]}) — fell back to CPU")
                    continue
                raise
        raise RuntimeError(f"LLM failed on all devices: {last}")


    _VOCAB: Dict[str, Any] = {}


    def count_tokens(settings: Settings, *texts: str) -> Dict[str, Any]:
        """Prompt size in model tokens: the GGUF's own tokenizer (vocab only, no weights, ~1 s once) when the
        model file is present, else an estimate (characters / 3.6). Chat-template tokens are not included."""
        joined = "\n".join(texts)
        p = plan(settings)
        if p.model_found and llama_cpp_info().get("installed"):
            try:
                with _LOCK:
                    if p.model_path not in _VOCAB:
                        _quiet_llama_logs()
                        from llama_cpp import Llama

                        _VOCAB[p.model_path] = Llama(model_path=p.model_path, vocab_only=True, verbose=False)
                    tok = _VOCAB[p.model_path]
                return {"tokens": len(tok.tokenize(joined.encode("utf-8"), add_bos=False, special=False)), "method": f"{p.model_label} tokenizer"}
            except Exception as exc:  # noqa: BLE001 — fall back to the estimate
                return {"tokens": int(len(joined) / 3.6) + 1, "method": f"estimate (tokenizer failed: {type(exc).__name__})"}
        return {"tokens": int(len(joined) / 3.6) + 1, "method": "estimate (characters / 3.6)"}


    def describe(settings: Settings) -> str:
        """Function describe."""
        p = plan(settings)
        dev = f"GPU ({p.n_gpu_layers} layers offloaded)" if p.device == "gpu" else "CPU"
        return f"{p.model_label} on {dev}; {p.reason}"
