# sentinel.e2e.train_job
# Retrain in a subprocess so a Streamlit rerun does not kill it. Progress lives in data/e2e/jobs.
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.train_job sentinel/e2e/train_job.py
if False:  # compiled by exec_section('sentinel.e2e.train_job'); not executed as part of this module
    """Background TS Pulse retrain. The UI starts this as its own process.

    Streamlit reruns the script on every click. A thread kept only in memory is easy
    to lose track of, and a fine-tune shares the UI process's memory. A subprocess
    plus a status file under ``data/e2e/jobs/`` survives those reruns: the page reads
    the file, draws the bar, and the training process keeps going.

        python -m sentinel.e2e.train_job --mode quick|full --device auto|gpu|cpu [--force]
    """

    # @@future@@ from __future__ import annotations

    import argparse
    import json
    import os
    import subprocess
    import sys
    from datetime import datetime
    from pathlib import Path
    from typing import Any, Dict, Optional

    from ..config import ROOT, load_settings
    from .labels import e2e_dir


    def _now() -> str:
        """Function _now."""
        return datetime.now().isoformat(timespec="seconds")


    def job_dir(settings: Any) -> Path:
        """Function job_dir."""
        return e2e_dir(settings) / "jobs"


    def job_file(settings: Any) -> Path:
        """Function job_file."""
        return job_dir(settings) / "current.json"


    def log_file(settings: Any) -> Path:
        """Function log_file."""
        return job_dir(settings) / "train.log"


    def _write(path: Path, obj: Dict[str, Any]) -> None:
        """Function _write."""
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".tmp")
        tmp.write_text(json.dumps(obj, indent=2, default=str), encoding="utf-8")
        tmp.replace(path)


    def alive(pid: Optional[int]) -> bool:
        """True when ``pid`` is a running process. Windows has no ``kill(pid, 0)`` signal."""
        if not pid or int(pid) <= 0:
            return False
        pid = int(pid)
        if sys.platform == "win32":
            import ctypes

            # OpenProcess succeeds for a process that has already exited, until its PID is reused.
            # STILL_ACTIVE (259) is the only code that means it is still running.
            handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid)  # PROCESS_QUERY_LIMITED_INFORMATION
            if not handle:
                return False
            code = ctypes.c_ulong()
            ok = ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(code))
            ctypes.windll.kernel32.CloseHandle(handle)
            return bool(ok) and code.value == 259
        try:
            os.kill(pid, 0)
        except OSError:
            return False
        return True


    def read_job(settings: Any) -> Optional[Dict[str, Any]]:
        """The current job, or None. A status of ``running`` whose process has gone is rewritten as ``error``."""
        path = job_file(settings)
        if not path.is_file():
            return None
        try:
            job = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return None
        if job.get("status") == "running" and job.get("pid") and not alive(job.get("pid")):
            job["status"] = "error"
            job["message"] = "The training process stopped before it finished. The log is next to this file."
            job["updated"] = _now()
            _write(path, job)
        return job


    def tail(path: Optional[str], n: int = 40) -> str:
        """Function tail."""
        if not path:
            return ""
        p = Path(path)
        if not p.is_file():
            return ""
        lines = p.read_text(encoding="utf-8", errors="replace").splitlines()
        return "\n".join(lines[-n:])


    def start_job(settings: Any, mode: str, device: str = "auto", force: bool = False, epochs: int = 12) -> Dict[str, Any]:
        """Start a quick or full retrain in a subprocess. Returns the status dict.

        A second start while one is running does not launch another process.
        """
        if mode not in ("quick", "full"):
            raise ValueError("mode must be quick or full")
        cur = read_job(settings)
        if cur and cur.get("status") == "running":
            return cur
        root = job_dir(settings)
        root.mkdir(parents=True, exist_ok=True)
        log_path = log_file(settings)
        log_path.write_text("", encoding="utf-8")
        cmd = [
            sys.executable, "-m", "sentinel.e2e.train_job",
            "--mode", mode, "--device", device, "--epochs", str(int(epochs)),
        ]
        if force:
            cmd.append("--force")
        env = os.environ.copy()
        env["SENTINEL_DATA_DIR"] = str(settings.data_dir)
        env["SENTINEL_E2E_MODEL_DIR"] = str(settings.e2e_model_dir)
        env["SENTINEL_KNOWLEDGE_DIR"] = str(settings.knowledge_dir)
        env["PYTHONUNBUFFERED"] = "1"
        # Write the file before the child starts, so its progress updates merge into this record
        # instead of racing a later overwrite. pid is filled in once Popen returns.
        job = {
            "status": "running",
            "mode": mode,
            "device": device,
            "force": bool(force),
            "epochs": int(epochs),
            "pid": None,
            "frac": 0.0,
            "message": f"Starting {mode} retrain on {device}",
            "started": _now(),
            "updated": _now(),
            "log": str(log_path),
            "result": None,
        }
        path = job_file(settings)
        _write(path, job)
        # A new process group so a Streamlit rerun does not signal this child.
        flags = 0x00000200 if sys.platform == "win32" else 0  # CREATE_NEW_PROCESS_GROUP
        log_fh = log_path.open("a", encoding="utf-8")
        try:
            proc = subprocess.Popen(cmd, cwd=str(ROOT), env=env, stdout=log_fh, stderr=subprocess.STDOUT, creationflags=flags)
        finally:
            log_fh.close()
        current = json.loads(path.read_text(encoding="utf-8"))
        current["pid"] = proc.pid
        if current.get("status") != "done":
            current["status"] = "running"
        _write(path, current)
        return current


    def _update(settings: Any, **fields: Any) -> None:
        """Function _update."""
        job = {}
        path = job_file(settings)
        if path.is_file():
            try:
                job = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                job = {}
        job.update(fields, updated=_now(), pid=os.getpid())
        _write(path, job)


    def run_job(mode: str, device: str, force: bool, epochs: int) -> Dict[str, Any]:
        """The subprocess body. Writes progress into ``current.json`` as it goes."""
        settings = load_settings()
        from .engine import Engine

        _update(settings, status="running", mode=mode, device=device, force=force, frac=0.0, message="Loading the learned model", log=str(log_file(settings)))

        def progress(frac: float, message: str) -> None:
            """Function progress."""
            print(f"[{frac:6.1%}] {message}", flush=True)
            _update(settings, status="running", frac=round(float(frac), 4), message=message)

        try:
            eng = Engine(settings)
            result = eng.train(mode=mode, device=device, force=force, epochs=epochs, progress=progress, trigger=f"Teach page {mode} retrain")
        except Exception as exc:  # noqa: BLE001 — the UI shows this; the process must not die silently
            err = f"{type(exc).__name__}: {exc}"
            print(err, flush=True)
            _update(settings, status="error", frac=1.0, message=err, result=None)
            return {"status": "error", "message": err}
        promoted = "promoted" if result.get("promoted") else "saved, not promoted (held-out accuracy was worse; tick force to promote)"
        msg = f"{mode} retrain {result.get('version')} — {promoted}"
        print(msg, flush=True)
        _update(settings, status="done", frac=1.0, message=msg, result=result)
        return result


    def main(argv: Optional[list] = None) -> int:
        """Function main."""
        ap = argparse.ArgumentParser(description="Run one TS Pulse retrain (quick or full) and write progress to data/e2e/jobs")
        ap.add_argument("--mode", choices=["quick", "full"], required=True)
        ap.add_argument("--device", choices=["auto", "gpu", "cpu"], default="auto")
        ap.add_argument("--force", action="store_true")
        ap.add_argument("--epochs", type=int, default=12)
        a = ap.parse_args(argv)
        out = run_job(a.mode, a.device, a.force, a.epochs)
        return 1 if out.get("status") == "error" else 0


    if __name__ == "__main__":
        raise SystemExit(main())
# >>>>>>> END sentinel.e2e.train_job

