    def write_streamlit_config(root: Path) -> Path:
        """Create ``.streamlit/config.toml`` when it is absent. Returns its path either way.

        Like ``settings.local.json``, an existing file is kept, so a port, address or upload
        limit changed on this machine survives a re-run of setup.
        """
        dest = Path(root) / ".streamlit" / "config.toml"
        if not dest.exists():
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_text(STREAMLIT_CONFIG, encoding="utf-8")
        return dest


    def setup(args: object) -> int:
        """Run the bootstrap described in the module docstring. Returns a process exit code."""
        root = ROOT
        skip_pip = bool(getattr(args, "skip_pip", False))
        try:
            other = prepare_python(root, skip_pip=skip_pip, force_venv=bool(getattr(args, "venv", False)))
        except (OSError, subprocess.CalledProcessError, RuntimeError) as exc:
            _say(f"PIP FAILED: {exc}")
            _say("Fix: " + FIX_SETUP)
            return 1
        if other is not None:
            env = os.environ.copy()
            env["SENTINEL_SETUP_REEXEC"] = "1"
            _say(f"Continuing setup with {other}")
            return int(subprocess.call([str(other), *sys.argv], env=env))

        try:
            install_models(root, str(getattr(args, "models_from", "") or ""), bool(getattr(args, "no_download", False)))
        except (OSError, RuntimeError, urllib.error.URLError) as exc:
            _say(f"MODELS FAILED: {exc}")
            _say("Fix: " + FIX_SETUP + " --models-from <folder>")
            return 1

        written = write_knowledge(root)
        _say("Knowledge: " + (", ".join(written) if written else "kept existing files"))
        _say("settings.local.json " + write_settings(root))
        theme_state = "kept" if (root / ".streamlit" / "config.toml").exists() else "created"
        _say(f"theme {write_streamlit_config(root)} {theme_state}")

        encoder = root / "models" / "e2e" / "encoder" / "model.safetensors"
        if encoder.is_file():
            _say(f"Fine-tuned encoder present: {encoder}")
        else:
            _say("No fine-tuned encoder. The app can still draft with the rule path.")
            _say("To train TS Pulse on the built-in synthetic cases:")
            _say("  " + FIX_TRAIN)
        # --train fits the shipped alert-type bundles from both generators.
        # A safetensors file already at encoder/ is the channel-independent copy
        # (or the old 14-channel file before it moved) and must not skip this.
        # The 14-channel head is not retrained.
        if bool(getattr(args, "train", False)):
            dataset = root / "data" / "e2e" / "dataset_profiles"
            original = root / "data" / "e2e" / "dataset"
            if not (dataset / "manifest.jsonl").is_file():
                _say(f"Generating alert-type cases in {dataset}")
                _generate_dataset(dataset, profiles="shipped")
            if not (original / "manifest.jsonl").is_file():
                _say(f"Generating original-generator cases in {original}")
                _generate_dataset(original)
            from .config import load_settings
            from .e2e.train import train_alert_bundles

            device = getattr(args, "device", None) or "cpu"
            train_alert_bundles(
                load_settings(),
                original,
                dataset,
                root / "models" / "e2e",
                device=str(device),
            )

        _say("Next: python sentinel_gt_ai.py")
        _say("Check: python sentinel_gt_ai.py doctor")
        return 0
