    # --------------------------------------------------------------------------- helpers


    def runs(mask: np.ndarray, min_len: int = 1, max_gap: int = 0) -> List[Tuple[int, int]]:
        """Contiguous True runs as (start, end_inclusive); gaps <= max_gap are bridged."""
        mask = np.asarray(mask, dtype=bool)
        out: List[Tuple[int, int]] = []
        if not mask.any():
            return out
        idx = np.flatnonzero(mask)
        start = prev = int(idx[0])
        for i in idx[1:]:
            i = int(i)
            if i - prev - 1 <= max_gap:
                prev = i
                continue
            out.append((start, prev))
            start = prev = i
        out.append((start, prev))
        return [(a, b) for a, b in out if b - a + 1 >= min_len]


    def rolling_median(x: np.ndarray, window: int) -> np.ndarray:
        """Function rolling_median."""
        if window <= 1:
            return np.asarray(x, dtype=float)
        return (
            pd.Series(x).rolling(window, center=True, min_periods=max(1, window // 2)).median().to_numpy()
        )


    def rolling_mean(x: np.ndarray, window: int) -> np.ndarray:
        """Function rolling_mean."""
        if window <= 1:
            return np.asarray(x, dtype=float)
        return pd.Series(x).rolling(window, center=True, min_periods=max(1, window // 2)).mean().to_numpy()


    def robust_stats(x: np.ndarray) -> Tuple[float, float]:
        """Median and MAD-based sigma (1.4826 * MAD); sigma never zero."""
        v = np.asarray(x, dtype=float)
        v = v[np.isfinite(v)]
        if v.size == 0:
            return 0.0, 1.0
        med = float(np.median(v))
        mad = float(np.median(np.abs(v - med))) * 1.4826
        if mad < 1e-9:
            sd = float(np.std(v))
            mad = sd if sd > 1e-9 else 1e-6
        return med, mad


    def steady_mask(case: CaseData) -> np.ndarray:
        """Fired, loaded operation: no trip flag and load >= 50% of median load."""
        n = case.n
        mask = np.ones(n, dtype=bool)
        trip = case.first("trip")
        if trip:
            t = case.series(trip)
            mask &= ~(np.nan_to_num(t) > 0.5)
        load = case.first("load")
        if load:
            l = case.series(load)
            med = np.nanmedian(l)
            if np.isfinite(med) and med > 0:
                mask &= np.nan_to_num(l, nan=0.0) >= 0.5 * med
        return mask


    def fmt(x: Optional[float], nd: int = 1, unit: str = "") -> str:
        """Function fmt."""
        if x is None or (isinstance(x, float) and not np.isfinite(x)):
            return "n/a"
        s = f"{x:.{nd}f}"
        return f"{s} {unit}".strip()


    def signed(x: float, nd: int = 2) -> str:
        """Signed format without '-0.00'."""
        v = round(float(x), nd)
        return f"{(0.0 if v == 0 else v):+.{nd}f}"


    def hours_text(h: float) -> str:
        """Function hours_text."""
        if h < 1.0:
            return f"{h * 60:.0f} min"
        if h < 48:
            return f"{h:.1f} h"
        return f"{h / 24:.1f} days"


    def regression_residual_z(y: np.ndarray, x: np.ndarray, mask: np.ndarray) -> Optional[np.ndarray]:
        """Robust z of residual from a linear fit y~x on masked rows; None if not fittable."""
        ok = mask & np.isfinite(y) & np.isfinite(x)
        if ok.sum() < 50 or np.nanstd(x[ok]) < 1e-9:
            return None
        a, b = np.polyfit(x[ok], y[ok], 1)
        res = y - (a * x + b)
        med, sig = robust_stats(res[ok])
        return (res - med) / sig


    def actuator_check(case: CaseData, window: Optional[Tuple[int, int]] = None) -> Dict[str, Any]:
        """IGV-vs-load consistency. A sustained residual suggests IGV LVDT / schedule issue."""
        from ..limits import GENERAL

        igv, load = case.first("igv"), case.first("load")
        out: Dict[str, Any] = {"checked": False}
        if not igv or not load:
            return out
        mask = steady_mask(case)
        z = regression_residual_z(case.series(igv), case.series(load), mask)
        if z is None:
            return out
        out["checked"] = True
        zz = np.where(mask, np.abs(z), 0.0)
        if window is not None:
            a, b = window
            pad = case.samples(360)
            sel = np.zeros_like(zz, dtype=bool)
            sel[max(0, a - pad) : min(case.n, b + pad + 1)] = True
            zz = np.where(sel, zz, 0.0)
        flagged = runs(zz > GENERAL["actuator_residual_z"], min_len=case.samples(60), max_gap=case.samples(10))
        out["max_abs_z"] = float(np.nanmax(zz)) if zz.size else 0.0
        out["flagged_minutes"] = float(sum(b - a + 1 for a, b in flagged) * case.minutes_per_sample)
        out["abnormal"] = bool(flagged)
        if flagged:
            out["first"] = case.time_at(flagged[0][0])
        return out
