if False:  # compiled by exec_section('sentinel.e2e.features'); not executed as part of this module
    """Canonical channel representation for the learned path.

    Any historian CSV (TC ring or zone EGTs, any tag naming, any resolution, any length) becomes a
    fixed ``(512, C)`` array that TS Pulse can embed:

    * **Channels** (``CHANNELS``): role-mapped process signals plus rotation-invariant exhaust-ring
      order statistics (coldest / hottest deviation from the ring median, the coldest sensor's two
      ring neighbours, sensor-noise health). They are generic transforms — no diagnosis rules — so a
      cold sector at TC5 and one at TC23 look the same, on a 16-TC or a 36-TC ring.
    * **Scaling**: robust z against the record's own baseline (first 30 % of online rows), floored
      by a first-difference noise estimate, then signed-log compressed. Absolute magnitudes survive
      (TS Pulse runs without per-window normalisation) while different frames/units line up.
    * **Two views**, 256 points each: the whole record (signed-extreme pooling, so a 20-minute trip
      in 60 days still shows) and a 48 h zoom starting 16 h before the onset of the strongest
      excursion (fixed physical time scale, so 1-min and 10-min data look alike).

    Also returns physical-unit excursion statistics used as report evidence.
    """

    # @@future@@ from __future__ import annotations

    from dataclasses import dataclass, field
    from typing import Any, Dict, List, Optional, Tuple

    import numpy as np
    import pandas as pd

    from ..data import CaseData

    CHANNELS: List[str] = [
        "load",
        "egt_resid",
        "spread",
        "cold_dev",
        "cold_pair",
        "hot_dev",
        "ring_flat",
        "dyn",
        "dyn_flat",
        "vib",
        "fuel_resid",
        "igv_resid",
        "trip",
        "other",
    ]
    CHANNEL_LABELS: Dict[str, str] = {
        "load": "load",
        "egt_resid": "average exhaust temperature vs load (residual)",
        "spread": "exhaust spread",
        "cold_dev": "coldest exhaust sensor vs ring median",
        "cold_pair": "coldest pair of adjacent exhaust sensors (the warmer of the two)",
        "hot_dev": "hottest exhaust sensor vs ring median",
        "ring_flat": "exhaust sensor noise health (flat / frozen sensor)",
        "dyn": "combustion dynamics amplitude",
        "dyn_flat": "dynamics probe noise health",
        "vib": "vibration",
        "fuel_resid": "fuel flow vs load (residual)",
        "igv_resid": "IGV position vs load (residual)",
        "trip": "trip flag",
        "other": "other channels (largest load-independent deviation)",
    }
    VIEW_LEN = 256
    WINDOW = 2 * VIEW_LEN
    ZOOM_HOURS = 48.0
    ZOOM_LEAD_HOURS = 16.0
    _CLIP = 8.0
    # Masked (set neutral) while the unit is offline; load / EGT / trip keep their offline values.
    _ONLINE_ONLY = {"egt_resid", "spread", "cold_dev", "cold_pair", "hot_dev", "ring_flat", "dyn", "dyn_flat", "vib", "fuel_resid", "igv_resid", "other"}
    _FLOORS = {"spread": 0.3, "cold_dev": 0.3, "cold_pair": 0.3, "hot_dev": 0.3, "egt_resid": 0.3, "dyn": 0.02, "vib": 0.03, "igv_resid": 0.05, "load": 0.05}


    @dataclass
    class Features:
        """Class Features."""
        x: np.ndarray  # (WINDOW, C) float32, model input
        meta: Dict[str, Any] = field(default_factory=dict)
        excursions: List[Dict[str, Any]] = field(default_factory=list)
        # Profile windows only. canonical() leaves these empty; the 14-channel path has no mask.
        mask: Optional[np.ndarray] = None  # (C,) True where the channel was computed
        channel_ids: List[str] = field(default_factory=list)


    def _ffill(a: np.ndarray) -> np.ndarray:
        """Function _ffill."""
        df = pd.DataFrame(a)
        return df.ffill().bfill().to_numpy(dtype=float)


    def _noise_sigma(x: np.ndarray) -> float:
        """Function _noise_sigma."""
        d = np.diff(x[np.isfinite(x)])
        if d.size < 3:
            return 0.0
        return float(np.median(np.abs(d - np.median(d)))) * 1.4826 / np.sqrt(2.0)


    def _robust_z(x: np.ndarray, base: np.ndarray, floor: float) -> np.ndarray:
        """Function _robust_z."""
        ref = x[base & np.isfinite(x)]
        if ref.size < 10:
            ref = x[np.isfinite(x)]
        if ref.size == 0:
            return np.zeros_like(x)
        med = float(np.median(ref))
        mad = float(np.median(np.abs(ref - med))) * 1.4826
        sig = max(mad, _noise_sigma(ref), floor, 1e-3 * max(abs(med), 1.0))
        return np.nan_to_num((x - med) / sig)


    def _compress(z: np.ndarray) -> np.ndarray:
        """Function _compress."""
        return np.clip(np.sign(z) * np.log1p(np.abs(z)), -_CLIP, _CLIP)


    def _rolling_logstd(a: np.ndarray, w: int, base: np.ndarray) -> np.ndarray:
        """log(rolling std / baseline rolling std) per column; very negative = frozen sensor."""
        sd = pd.DataFrame(a).rolling(w, min_periods=2, center=True).std().to_numpy()
        ref = sd[base] if base.sum() > 10 else sd
        med = np.nanmedian(ref, axis=0)
        med = np.where(np.isfinite(med) & (med > 1e-9), med, 1e-3)
        return np.log(np.clip(sd / med, 1e-4, None))


    def _pool(x: np.ndarray, length: int) -> np.ndarray:
        """(n, C) -> (length, C): signed-extreme pooling when longer, linear interpolation when shorter."""
        n = x.shape[0]
        if n == 0:
            return np.zeros((length, x.shape[1]))
        if n <= length:
            src = np.linspace(0, n - 1, length)
            return np.stack([np.interp(src, np.arange(n), x[:, c]) for c in range(x.shape[1])], axis=1)
        edges = np.linspace(0, n, length + 1).astype(int)
        out = np.empty((length, x.shape[1]))
        for b in range(length):
            seg = x[edges[b] : max(edges[b + 1], edges[b] + 1)]
            i = np.argmax(np.abs(seg), axis=0)
            out[b] = seg[i, np.arange(x.shape[1])]
        return out


    def _load_residual(x: np.ndarray, load: Optional[np.ndarray], online: np.ndarray, base: np.ndarray) -> np.ndarray:
        """x minus its linear dependence on load (fitted on baseline online rows)."""
        ref = base if base.sum() > 20 else online
        if load is None or ref.sum() <= 20 or np.nanstd(load[ref]) < 1e-6:
            return x - np.nanmedian(x[ref] if ref.any() else x)
        ok = ref & np.isfinite(x) & np.isfinite(load)
        a, b = np.polyfit(load[ok], x[ok], 1)
        return x - (a * load + b)


    def _cols(case: CaseData, role: str) -> List[str]:
        """Function _cols."""
        return [c for c in case.roles.get(role, []) if c in case.df.columns]


    def _first_series(case: CaseData, role: str) -> Optional[np.ndarray]:
        """Function _first_series."""
        cols = _cols(case, role)
        return _ffill(case.series(cols[0])[:, None])[:, 0] if cols else None


    def canonical(case: CaseData) -> Features:
        """Function canonical."""
        n = case.n
        raw: Dict[str, np.ndarray] = {}
        phys: Dict[str, np.ndarray] = {}
        used: set = set()
        zeros = np.zeros(n)

        load = _first_series(case, "load")
        used.update(_cols(case, "load")[:1])
        if load is not None:
            p95 = np.nanpercentile(load, 95) if np.isfinite(load).any() else 0.0
            online = np.nan_to_num(load) >= 0.3 * p95 if p95 > 0 else np.ones(n, dtype=bool)
        else:
            online = np.ones(n, dtype=bool)
        first = np.zeros(n, dtype=bool)
        first[: max(10, int(0.3 * n))] = True
        base = online & first
        if base.sum() < 10:
            base = online.copy()

        # Exhaust ring (TCs) or zone EGTs
        ring_cols = [c for c in case.ring if c in case.df.columns]
        zone_cols = [c for c in case.zones if c in case.df.columns]
        tcols = ring_cols if len(ring_cols) >= 3 else (zone_cols if len(zone_cols) >= 2 else [])
        layout = "ring" if tcols is ring_cols and tcols else ("zones" if tcols else "none")
        used.update(tcols)
        if tcols:
            T = np.column_stack([case.series(c) for c in tcols])
            T = _ffill(T)
            m = T.shape[1]
            dev = T - np.nanmedian(T, axis=1)[:, None]
            off = np.nanmedian(dev[base], axis=0) if base.sum() > 10 else np.nanmedian(dev, axis=0)
            dev = np.nan_to_num(dev - off)
            dev[~online] = 0.0
            phys["cold_dev"] = dev.min(axis=1)
            # Coldest adjacent pair: min over ring pairs of the warmer sensor of the pair. A single bad
            # TC leaves it near normal; a cold sector (>= 2 adjacent sensors) pulls it down. Exactly
            # rotation-invariant and tie-free (no argmin).
            pair = np.maximum(dev, np.roll(dev, -1, axis=1))
            phys["cold_pair"] = pair.min(axis=1)
            phys["cold_sensor"] = np.argmin(dev, axis=1)
            phys["pair_sensor"] = np.argmin(pair, axis=1)
            phys["hot_dev"] = dev.max(axis=1)
            phys["hot_sensor"] = np.argmax(dev, axis=1)
            w = max(3, case.samples(60))
            raw["ring_flat"] = np.clip(np.nanmin(_rolling_logstd(T, w, base), axis=1), -6, 0)  # frozen side only
            tspread = T.max(axis=1) - T.min(axis=1)
            tavg = T.mean(axis=1)
        else:
            m = 0
            for k in ("cold_dev", "cold_pair", "hot_dev"):
                phys[k] = zeros
            raw["ring_flat"] = zeros
            tspread = tavg = None

        sp = _first_series(case, "spread")
        used.update(_cols(case, "spread")[:1])
        phys["spread"] = sp if sp is not None else (tspread if tspread is not None else zeros)
        ea = _first_series(case, "egt_avg")
        used.update(_cols(case, "egt_avg")[:1])
        egt = ea if ea is not None else (tavg if tavg is not None else zeros)
        phys["egt_avg"] = egt
        phys["egt_resid"] = _load_residual(egt, load, online, base)
        phys["load"] = load if load is not None else zeros

        dyn = _first_series(case, "dynamics")
        used.update(_cols(case, "dynamics")[:1])
        phys["dyn"] = dyn if dyn is not None else zeros
        if dyn is not None:
            raw["dyn_flat"] = np.clip(_rolling_logstd(dyn[:, None], max(3, case.samples(60)), base)[:, 0], -6, 3)
        else:
            raw["dyn_flat"] = zeros

        vcols = _cols(case, "vibration")
        used.update(vcols)
        if vcols:
            V = _ffill(np.column_stack([case.series(c) for c in vcols]))
            vz = np.column_stack([_robust_z(V[:, i], base, _FLOORS["vib"]) for i in range(V.shape[1])])
            k = np.argmax(np.abs(vz), axis=1)
            raw["vib_z"] = vz[np.arange(n), k]
            phys["vib"] = V.max(axis=1)
        else:
            raw["vib_z"] = zeros
            phys["vib"] = zeros

        fuel = _first_series(case, "fuel")
        used.update(_cols(case, "fuel")[:1])
        phys["fuel"] = fuel if fuel is not None else zeros
        phys["fuel_resid"] = _load_residual(fuel, load, online, base) if fuel is not None else zeros

        igv = _first_series(case, "igv")
        used.update(_cols(case, "igv")[:1])
        phys["igv_resid"] = _load_residual(igv, load, online, base) if igv is not None else zeros

        tcols_trip = _cols(case, "trip")
        used.update(tcols_trip)
        if tcols_trip:
            tr = np.nan_to_num(np.column_stack([case.series(c) for c in tcols_trip])).max(axis=1)
            phys["trip"] = (tr > 0.5).astype(float)
        else:
            phys["trip"] = zeros

        # Everything else: largest load-independent deviation (CDP, CDT, lube oil, ambient, unknown tags)
        others = [c for c in case.numeric_columns if c not in used and case.df[c].notna().sum() > 10]
        oz = []
        for c in others:
            x = _ffill(case.series(c)[:, None])[:, 0]
            if load is not None and online.sum() > 20 and np.nanstd(load[online]) > 1e-6 and np.nanstd(x[online]) > 1e-9:
                a, b = np.polyfit(load[online], x[online], 1)
                x = x - (a * load + b)
            oz.append(_robust_z(x, base, 1e-6))
        if oz:
            O = np.column_stack(oz)
            k = np.argmax(np.abs(O), axis=1)
            raw["other_z"] = O[np.arange(n), k]
            raw["other_name"] = np.array(others)[k]
        else:
            raw["other_z"] = zeros

        X = np.zeros((n, len(CHANNELS)))
        for ci, ch in enumerate(CHANNELS):
            if ch == "trip":
                X[:, ci] = 3.0 * phys["trip"]
                continue
            if ch in ("ring_flat", "dyn_flat"):
                v = raw[ch]
            elif ch == "vib":
                v = _compress(raw["vib_z"])
            elif ch == "other":
                v = _compress(raw["other_z"])
            else:
                v = _compress(_robust_z(phys[ch], base, _FLOORS.get(ch, 1e-6)))
            if ch in _ONLINE_ONLY:
                v = np.where(online, v, 0.0)
            X[:, ci] = np.nan_to_num(v)

        # Zoom anchor: onset of the strongest excursion (load / EGT level excluded: they swing with dispatch)
        energy_cols = [i for i, c in enumerate(CHANNELS) if c != "load"]
        e = np.abs(X[:, energy_cols]).sum(axis=1)
        e = pd.Series(e).rolling(max(1, case.samples(30)), center=True, min_periods=1).median().to_numpy()
        e0 = float(np.median(e))
        peak = int(np.argmax(e))
        above = np.flatnonzero(e - e0 >= 0.5 * (e[peak] - e0)) if e[peak] > e0 else np.array([peak])
        onset = int(above[0]) if above.size else peak
        lead, span = case.samples(ZOOM_LEAD_HOURS * 60), case.samples(ZOOM_HOURS * 60)
        z0 = max(0, min(onset - lead, n - span))
        z1 = min(n, z0 + span)

        x = np.concatenate([_pool(X, VIEW_LEN), _pool(X[z0:z1], VIEW_LEN)], axis=0).astype(np.float32)
        meta = {
            "rows": n,
            "layout": layout,
            "n_sensors": m,
            "online_fraction": round(float(online.mean()), 3),
            "zoom": [case.time_at(z0), case.time_at(max(z0, z1 - 1))],
            "zoom_idx": [int(z0), int(max(z0, z1 - 1))],
            "onset": case.time_at(onset),
            "onset_idx": int(onset),
            "missing_roles": [r for r, k in (("load", load), ("dynamics", dyn), ("igv", igv), ("fuel", fuel)) if k is None]
            + ([] if tcols else ["exhaust ring / zones"]),
        }
        return Features(x=x, meta=meta, excursions=_excursions(case, X, phys, raw, online, tcols))


    def _excursions(case: CaseData, X: np.ndarray, phys: Dict[str, np.ndarray], raw: Dict[str, Any], online: np.ndarray, tcols: List[str]) -> List[Dict[str, Any]]:
        """Largest excursion per canonical channel in physical units (report evidence)."""
        out: List[Dict[str, Any]] = []
        for ci, ch in enumerate(CHANNELS):
            col = X[:, ci]
            if not np.any(np.abs(col) > 1e-9):
                continue
            i = int(np.argmax(np.abs(col)))
            score = float(col[i])
            rec: Dict[str, Any] = {"channel": ch, "label": CHANNEL_LABELS[ch], "score": round(score, 2), "time": case.time_at(i)}
            if ch in phys:
                rec["value"] = round(float(phys[ch][i]), 3)
            if ch == "cold_dev" and tcols and "cold_sensor" in phys:
                rec["sensor"] = tcols[int(phys["cold_sensor"][i])]
            if ch == "cold_pair" and tcols and "pair_sensor" in phys:
                k = int(phys["pair_sensor"][i])
                rec["sensor"] = f"{tcols[k]} + {tcols[(k + 1) % len(tcols)]}"
            if ch == "hot_dev" and tcols and "hot_sensor" in phys:
                rec["sensor"] = tcols[int(phys["hot_sensor"][i])]
            if ch == "other" and "other_name" in raw:
                rec["sensor"] = str(raw["other_name"][i])
            if ch == "trip":
                on = np.flatnonzero(phys["trip"] > 0.5)
                if on.size:
                    rec["time"] = case.time_at(int(on[0]))
            out.append(rec)
        out.sort(key=lambda r: abs(r["score"]), reverse=True)
        return out


    def featurize_path(path: str) -> Features:
        """Function featurize_path."""
        from ..data import load_csv

        return canonical(load_csv(path))


    def _online_base(n: int, load: Optional[np.ndarray]) -> Tuple[np.ndarray, np.ndarray]:
        """Online rows, and the baseline: the first 30% of those rows."""
        if load is not None and np.isfinite(load).any():
            p95 = float(np.nanpercentile(load[np.isfinite(load)], 95))
            online = np.nan_to_num(load) >= 0.3 * p95 if p95 > 0 else np.ones(n, dtype=bool)
        else:
            online = np.ones(n, dtype=bool)
        first = np.zeros(n, dtype=bool)
        first[: max(10, int(0.3 * n))] = True
        base = online & first
        if int(base.sum()) < 10:
            base = online.copy()
        return online, base


    def _filled(case: CaseData, tags: Sequence[str]) -> Optional[np.ndarray]:
        """(n, m) of the tags that are actually in the file, forward-filled. None when none are."""
        cols = [tag for tag in tags if tag in case.df.columns]
        if not cols:
            return None
        return _ffill(np.column_stack([case.series(col) for col in cols]))


    def _level(values: np.ndarray, load: Optional[np.ndarray], online: np.ndarray, base: np.ndarray, fit: bool) -> np.ndarray:
        series = values if values.ndim == 1 else values.mean(axis=1)
        if fit:
            return _load_residual(series, load, online, base)
        return series


    def _ring_bundle(case: CaseData, tags: Sequence[str], load: Optional[np.ndarray], online: np.ndarray, base: np.ndarray) -> Dict[str, Tuple[np.ndarray, np.ndarray, Optional[np.ndarray]]]:
        """Ring channels. Each entry is (model series, physical series, per-row sensor index or None)."""
        n = case.n
        zeros = np.zeros(n)
        block = _filled(case, tags)
        if block is None or block.shape[1] < 3:
            empty = (zeros, zeros, None)
            return {name: empty for name in ("ring_cold", "ring_cold_pair", "ring_hot", "ring_spread", "ring_avg", "ring_flat")}
        dev = block - np.nanmedian(block, axis=1)[:, None]
        offset = np.nanmedian(dev[base], axis=0) if int(base.sum()) > 10 else np.nanmedian(dev, axis=0)
        dev = np.nan_to_num(dev - offset)
        dev[~online] = 0.0
        cold = dev.min(axis=1)
        pair = np.maximum(dev, np.roll(dev, -1, axis=1)).min(axis=1)
        hot = dev.max(axis=1)
        spread = block.max(axis=1) - block.min(axis=1)
        average = block.mean(axis=1)
        window = max(3, case.samples(60))
        flat = np.clip(np.nanmin(_rolling_logstd(block, window, base), axis=1), -6, 0)
        floor = 0.3

        def z(phys: np.ndarray) -> np.ndarray:
            return _compress(_robust_z(phys, base, floor))

        return {
            "ring_cold": (z(cold), cold, np.argmin(dev, axis=1)),
            "ring_cold_pair": (z(pair), pair, np.argmin(np.maximum(dev, np.roll(dev, -1, axis=1)), axis=1)),
            "ring_hot": (z(hot), hot, np.argmax(dev, axis=1)),
            "ring_spread": (z(spread), spread, None),
            "ring_avg": (z(_load_residual(average, load, online, base)), average, None),
            "ring_flat": (flat, flat, None),
        }


    def _bank_bundle(case: CaseData, tags: Sequence[str], online: np.ndarray, base: np.ndarray, floor: float) -> Dict[str, Tuple[np.ndarray, np.ndarray, Optional[np.ndarray]]]:
        """Bank channels from per-member robust z."""
        n = case.n
        zeros = np.zeros(n)
        block = _filled(case, tags)
        empty = (zeros, zeros, None)
        if block is None or block.shape[1] == 0:
            return {name: empty for name in ("bank_max", "bank_min", "bank_spread", "bank_flat", "robust_z", "flat")}
        scored = np.column_stack([_robust_z(block[:, i], base, floor) for i in range(block.shape[1])])
        scored[~online] = 0.0
        winner = np.argmax(np.abs(scored), axis=1)
        largest = scored[np.arange(n), winner]
        smallest = scored.min(axis=1)
        spread = scored.max(axis=1) - scored.min(axis=1)
        window = max(3, case.samples(60))
        flat = np.clip(np.nanmin(_rolling_logstd(block, window, base), axis=1), -6, 0)
        return {
            "bank_max": (_compress(largest), largest, winner),
            "bank_min": (_compress(smallest), smallest, np.argmin(scored, axis=1)),
            "bank_spread": (_compress(spread), spread, None),
            "bank_flat": (flat, flat, None),
            # A one-member bank is a process series. robust_z is that member.
            "robust_z": (_compress(scored[:, 0]), block[:, 0], None),
            "flat": (flat, flat, None),
        }


    def _scalar_series(case: CaseData, tags: Sequence[str], load: Optional[np.ndarray], online: np.ndarray, base: np.ndarray, fit: bool, floor: float) -> Tuple[np.ndarray, np.ndarray]:
        block = _filled(case, tags[:1])
        if block is None:
            return np.zeros(case.n), np.zeros(case.n)
        phys = _level(block[:, 0], load, online, base, fit)
        return _compress(_robust_z(phys, base, floor)), phys


    def _other_series(case: CaseData, used: set, load: Optional[np.ndarray], online: np.ndarray, base: np.ndarray) -> Tuple[np.ndarray, np.ndarray, Optional[np.ndarray]]:
        """Largest load-independent deviation among numeric columns the profile did not claim."""
        n = case.n
        others = [col for col in case.numeric_columns if col not in used and int(case.df[col].notna().sum()) > 10]
        if not others:
            return np.zeros(n), np.zeros(n), None
        scored = []
        for col in others:
            series = _ffill(case.series(col)[:, None])[:, 0]
            if load is not None:
                series = _load_residual(series, load, online, base)
            scored.append(_robust_z(series, base, 1e-6))
        block = np.column_stack(scored)
        winner = np.argmax(np.abs(block), axis=1)
        values = block[np.arange(n), winner]
        return _compress(values), values, np.array(others, dtype=object)[winner]


    def _couple_series(case: CaseData, left: np.ndarray, right: np.ndarray) -> np.ndarray:
        """Rolling Pearson correlation. A short record falls back to one correlation repeated.

        A correlation lives in [-1, 1]. A rolling window whose variance underflows can
        return a huge finite number; that is not a relationship, so it becomes 0.
        """
        window = max(3, case.samples(60))

        def _in_range(values: np.ndarray) -> np.ndarray:
            values = np.asarray(values, dtype=float)
            bad = ~np.isfinite(values) | (np.abs(values) > 1.0 + 1e-3)
            values = np.where(bad, 0.0, values)
            return np.clip(values, -1.0, 1.0)

        if left.size < window:
            both = np.isfinite(left) & np.isfinite(right)
            if int(both.sum()) < 3 or float(np.std(left[both])) < 1e-9 or float(np.std(right[both])) < 1e-9:
                return np.zeros(case.n)
            value = float(np.corrcoef(left[both], right[both])[0, 1])
            return np.full(case.n, float(_in_range(np.array([value]))[0]))
        corr = pd.Series(left).rolling(window, min_periods=max(3, window // 3)).corr(pd.Series(right))
        return _in_range(corr.to_numpy(dtype=float))


    def _slot_level(case: CaseData, role: str, tags: Sequence[str], load: Optional[np.ndarray], online: np.ndarray, base: np.ndarray) -> np.ndarray:
        """One physical series per slot, used by the couple channels."""
        block = _filled(case, tags)
        if block is None:
            return np.zeros(case.n)
        if role == "ring":
            return _load_residual(block.mean(axis=1), load, online, base)
        if role == "flag":
            flagged = np.nan_to_num(block) > 0.5
            return flagged.any(axis=1).astype(float)
        return _level(block.mean(axis=1), load, online, base, role == "process")


    def profile_windows(case: CaseData, profile: Any, resolved: Any) -> Features:
        """(512, C_p) window for one alert type.

        A missing or masked slot is zeros with ``mask`` 0. It is not a real flat
        signal: the embedder skips those channels. ``canonical()`` is unchanged
        and is still the 14-channel path.
        """
        from ..profiles import channels_hash, compile_channels

        specs = compile_channels(profile, resolved)
        n = case.n
        by_slot = {slot.id: slot for slot in profile.slots}
        tags_of: Dict[str, List[str]] = {}
        context_tag = None
        for slot in profile.slots:
            hit = resolved.by_id(slot.id)
            tags = list(hit.tags) if hit is not None and hit.status == "present" and hit.tags else []
            tags_of[slot.id] = tags
            if slot.role == "context" and tags and context_tag is None:
                context_tag = tags[0]
        load = None
        if context_tag and context_tag in case.df.columns:
            load = _ffill(case.series(context_tag)[:, None])[:, 0]
        online, base = _online_base(n, load)
        used = {tag for tags in tags_of.values() for tag in tags}
        levels = {
            slot.id: _slot_level(case, slot.role, tags_of.get(slot.id, []), load, online, base)
            for slot in profile.slots
        }
        ring_cache: Dict[str, Dict[str, Tuple]] = {}
        bank_cache: Dict[str, Dict[str, Tuple]] = {}
        columns: List[np.ndarray] = []
        mask = np.zeros(len(specs), dtype=bool)
        physical: Dict[str, np.ndarray] = {}
        sensors: Dict[str, Any] = {}

        def remember(spec_id: str, model: np.ndarray, phys: Optional[np.ndarray], sensor: Any, active: bool) -> None:
            if active:
                columns.append(np.nan_to_num(model).astype(float))
                mask[len(columns) - 1] = True
            else:
                columns.append(np.zeros(n))
            if phys is not None:
                physical[spec_id] = phys
            if sensor is not None:
                sensors[spec_id] = sensor

        for index, spec in enumerate(specs):
            slot = by_slot.get(spec.slot_id)
            tags = tags_of.get(spec.slot_id, [])
            active = not spec.masked
            if spec.transform == "other":
                model, phys, sensor = _other_series(case, used, load, online, base)
                if spec.online_only:
                    model = np.where(online, model, 0.0)
                remember(spec.id, model, phys, sensor, active and sensor is not None)
                continue
            if spec.transform == "couple":
                left_id, _, right_id = spec.id.partition("~")
                if not tags_of.get(left_id) or not tags_of.get(right_id):
                    remember(spec.id, np.zeros(n), None, None, False)
                    continue
                model = _couple_series(case, levels.get(left_id, np.zeros(n)), levels.get(right_id, np.zeros(n)))
                if spec.online_only:
                    model = np.where(online, model, 0.0)
                remember(spec.id, model, model, None, True)
                continue
            if not active or not tags:
                remember(spec.id, np.zeros(n), None, None, False)
                continue
            transform = spec.transform
            if transform.startswith("ring_"):
                if spec.slot_id not in ring_cache:
                    ring_cache[spec.slot_id] = _ring_bundle(case, tags, load, online, base)
                model, phys, sensor = ring_cache[spec.slot_id][transform]
            elif transform in ("bank_max", "bank_min", "bank_spread", "bank_flat") or (
                slot is not None and slot.role == "bank" and transform in ("robust_z", "flat")
            ):
                if spec.slot_id not in bank_cache:
                    bank_cache[spec.slot_id] = _bank_bundle(case, tags, online, base, spec.floor or 1e-6)
                model, phys, sensor = bank_cache[spec.slot_id][transform if transform in bank_cache[spec.slot_id] else "robust_z"]
            elif transform == "flag":
                block = _filled(case, tags)
                flagged = np.zeros(n) if block is None else (np.nan_to_num(block) > 0.5).any(axis=1).astype(float)
                model, phys, sensor = 3.0 * flagged, flagged, None
            elif transform == "flat":
                block = _filled(case, tags[:1])
                if block is None:
                    model, phys, sensor = np.zeros(n), np.zeros(n), None
                else:
                    flat = np.clip(_rolling_logstd(block, max(3, case.samples(60)), base)[:, 0], -6, 3)
                    model, phys, sensor = flat, flat, None
            else:
                fit = transform == "load_fit_z"
                model, phys = _scalar_series(case, tags, load, online, base, fit, spec.floor or 1e-6)
                sensor = None
            if spec.online_only:
                model = np.where(online, model, 0.0)
            remember(spec.id, model, phys, sensor, True)

        if columns:
            raw = np.column_stack(columns)
        else:
            raw = np.zeros((n, 0))
        context_ids = {slot.id for slot in profile.slots if slot.role == "context"}
        energy_at = [i for i, spec in enumerate(specs) if spec.slot_id not in context_ids and mask[i]]
        if energy_at and n:
            energy = np.abs(raw[:, energy_at]).sum(axis=1)
            energy = pd.Series(energy).rolling(max(1, case.samples(30)), center=True, min_periods=1).median().to_numpy()
            baseline_energy = float(np.median(energy))
            peak = int(np.argmax(energy))
            above = np.flatnonzero(energy - baseline_energy >= 0.5 * (energy[peak] - baseline_energy)) if energy[peak] > baseline_energy else np.array([peak])
            onset = int(above[0]) if above.size else peak
        else:
            onset = 0
        lead, span = case.samples(ZOOM_LEAD_HOURS * 60), case.samples(ZOOM_HOURS * 60)
        z0 = max(0, min(onset - lead, n - span)) if n else 0
        z1 = min(n, z0 + span) if n else 0
        if raw.shape[1] == 0:
            window = np.zeros((WINDOW, 0), dtype=np.float32)
        else:
            # A non-finite sample is not a measurement. Clip before the float32 cast so
            # one overflow cannot become inf and then NaN the whole embedding batch.
            pooled = np.concatenate([_pool(raw, VIEW_LEN), _pool(raw[z0:z1] if z1 > z0 else raw[:1], VIEW_LEN)], axis=0)
            pooled = np.where(np.isfinite(pooled), pooled, 0.0)
            window = np.clip(pooled, -1e3, 1e3).astype(np.float32)
        coverage = resolved.coverage()
        meta = {
            "rows": n,
            "online_fraction": round(float(online.mean()), 3) if n else 0.0,
            "zoom": [case.time_at(z0), case.time_at(max(z0, z1 - 1))] if n else ["", ""],
            "zoom_idx": [int(z0), int(max(z0, z1 - 1))] if n else [0, 0],
            "onset": case.time_at(onset) if n else "",
            "onset_idx": int(onset),
            "frame_key": resolved.frame_key,
            "coverage": {"required": list(coverage["required"]), "optional": list(coverage["optional"])},
            "slots": {hit.slot_id: list(hit.tags) for hit in resolved.slots},
            "profile": profile.id,
            "channels_hash": channels_hash(profile),
        }
        excursions: List[Dict[str, Any]] = []
        for index, spec in enumerate(specs):
            if not mask[index]:
                continue
            column = raw[:, index]
            if not np.any(np.abs(column) > 1e-9):
                continue
            at = int(np.argmax(np.abs(column)))
            rec: Dict[str, Any] = {
                "channel": spec.id,
                "label": spec.label,
                "score": round(float(column[at]), 2),
                "time": case.time_at(at),
            }
            sensor = sensors.get(spec.id)
            slot_tags = tags_of.get(spec.slot_id, [])
            if isinstance(sensor, np.ndarray) and sensor.dtype != object and slot_tags:
                rec["sensor"] = slot_tags[int(sensor[at]) % len(slot_tags)]
            elif isinstance(sensor, np.ndarray):
                rec["sensor"] = str(sensor[at])
            excursions.append(rec)
        excursions.sort(key=lambda row: abs(row["score"]), reverse=True)
        return Features(x=window, meta=meta, excursions=excursions, mask=mask, channel_ids=[spec.id for spec in specs])


    def profile_cache_key(case: CaseData, profile: Any, resolved: Any) -> str:
        """``features3_`` plus 16 hex chars. Alias resolution is part of the key, so an alias edit re-embeds only the cases it changes."""
        import hashlib
        import json

        from ..config import FEATURE_VERSION
        from ..profiles import channels_hash

        payload = "|".join(
            [
                f"v{FEATURE_VERSION}",
                str(getattr(case, "sha256", "")),
                str(profile.id),
                channels_hash(profile),
                json.dumps(resolved.to_dict(), sort_keys=True, default=str),
            ]
        )
        return "features3_" + hashlib.sha1(payload.encode("utf-8")).hexdigest()[:16]
# >>>>>>> END sentinel.e2e.features

# =============================================================================
# sentinel.analytics.cold_spot
# Rule-path cold-sector check: a contiguous arc of the exhaust ring, not one noisy thermocouple.
# =============================================================================
# <<<<<<< SECTION sentinel.analytics.cold_spot sentinel/analytics/cold_spot.py
if False:  # compiled by exec_section('sentinel.analytics.cold_spot'); not executed as part of this module
    """Exhaust cold spot analyzer (circumferential cold sector on the exhaust TC ring)."""

    # @@future@@ from __future__ import annotations

    from typing import List, Tuple

    import numpy as np

    from ..data import CaseData
    from ..limits import COLD_SPOT as L
    from ..notes import NotesInfo
    from .base import (
        Findings,
        Hypothesis,
        actuator_check,
        fmt,
        hours_text,
        rolling_median,
        runs,
        signed,
        steady_mask,
    )

    VERSION = "cold_spot/1.0"
    # What a profile must declare before this analyzer is allowed to run.
    REQUIRES = {"ring_or_zones": True, "load": True}


    def _ring_arcs(members: List[int], k: int) -> int:
        """Number of contiguous arcs formed by member indices on a ring of size k."""
        if not members:
            return 0
        s = set(members)
        if len(s) == k:
            return 1
        return sum(1 for m in s if (m - 1) % k not in s)


    def _tc_label(cols: List[str], idx: List[int]) -> str:
        """Function _tc_label."""
        names = [cols[i] for i in idx]
        return ", ".join(names)


    def _ramp_minutes(cold: np.ndarray, depth: float, a: int, b: int, case: CaseData) -> Tuple[float, float, int]:
        """Minutes from 10% to 90% of depth around the event start, max single-step jump, onset index."""
        lo = max(0, a - case.samples(12 * 60))
        hi = min(case.n, a + case.samples(36 * 60), b + 1)
        seg = cold[lo:hi]
        if seg.size < 3 or depth <= 0:
            return float("nan"), 0.0, a
        i90 = np.flatnonzero(seg >= 0.9 * depth)
        if i90.size == 0:
            return float("nan"), 0.0, a
        # Onset = last time before reaching 90% depth that the TC was still within 10% of normal
        below10 = np.flatnonzero(seg[: i90[0] + 1] < 0.1 * depth)
        i10 = int(below10[-1]) + 1 if below10.size else 0
        ramp = float((i90[0] - i10) * case.minutes_per_sample)
        jump = float(np.nanmax(np.abs(np.diff(seg[max(0, i10 - 2) : i90[0] + 2])))) if i90[0] + 2 - max(0, i10 - 2) > 1 else 0.0
        return ramp, jump, lo + i10


    def analyze(case: CaseData, notes: NotesInfo, probe: bool = False) -> Findings:
        """Function analyze."""
        f = Findings(analytic="cold_spot", analyzer_version=VERSION, detected=False, summary="")
        cols = case.ring if len(case.ring) >= 6 else case.zones
        ring_kind = "TC ring" if cols is case.ring else "exhaust zones"
        if len(cols) < 4:
            f.missing_channels.append("exhaust thermocouples (TC1..TCn or EGT zones)")
            f.summary = "No exhaust thermocouple ring in the data; cold spot cannot be evaluated."
            f.data_gaps.append("Export the individual exhaust TCs (TC1..TCn); spread alone cannot localise a cold sector.")
            return f
        if cols is not case.ring:
            f.data_gaps.append("Only zone-averaged EGTs available; sector localisation is coarse.")
        k = len(cols)
        spread_col = case.first("spread")
        f.explained_channels = list(cols) + [c for c in (spread_col, case.first("egt_avg")) if c]

        X = np.column_stack([case.series(c) for c in cols])
        steady = steady_mask(case)
        row_med = np.nanmedian(X, axis=1)
        dev = X - row_med[:, None]
        base_dev = np.nanmedian(dev[steady], axis=0) if steady.any() else np.nanmedian(dev, axis=0)
        excess = dev - base_dev[None, :]  # negative = colder than this TC's normal
        smooth_n = max(1, case.samples(30))
        cold = np.column_stack([-rolling_median(excess[:, j], smooth_n) for j in range(k)])
        cold = np.where(steady[:, None], cold, 0.0)
        row_cold = np.nanmax(cold, axis=1)

        ev_runs = runs(row_cold > L["cold_excess_C"], min_len=case.samples(L["min_event_minutes"]), max_gap=case.samples(30))
        spread = case.series(spread_col) if spread_col else (np.nanmax(X, axis=1) - np.nanmin(X, axis=1))
        base_spread = float(np.nanmedian(spread[steady])) if steady.any() else float(np.nanmedian(spread))
        f.signature["baseline_spread_C"] = round(base_spread, 1)

        if not ev_runs:
            peak_cold = float(np.nanmax(row_cold)) if row_cold.size else 0.0
            f.summary = (
                f"No sustained cold sector found: deepest TC deviation {peak_cold:.1f} C "
                f"(threshold {L['cold_excess_C']} C for >= {L['min_event_minutes']} min)."
            )
            f.signature.update({"detected": False, "peak_cold_C": round(peak_cold, 1)})
            f.add("Deepest TC cold deviation", fmt(peak_cold, 1, "C"), "CS-R1", "below event threshold")
            f.add("Baseline exhaust spread", fmt(base_spread, 1, "C"), "CS-R1")
            f.hypotheses.append(
                Hypothesis(
                    cause="not_confirmed",
                    title="Cold spot not present in the supplied data",
                    score=0.6,
                    action="monitor_only",
                    rules=["CS-R1"],
                    support=["no TC stayed below its normal by more than the threshold for the minimum duration"],
                    against=["the alert may have come from a window not covered by this export"],
                )
            )
            f.what_happened = f.summary
            f.why = "The data does not show a cold sector, so the analytic alert is not confirmed by this export."
            f.review_flags.append("Analytic alert not confirmed by the data — check the export window covers the alert time.")
            f.severity, f.urgency = "low", "routine"
            f.site_checks.append("Confirm the alert timestamp falls inside the exported data window.")
            f.chart = {"channels": [c for c in [spread_col] if c], "event": None}
            return f

        # Main event: the run with the largest integrated coldness
        a, b = max(ev_runs, key=lambda r: float(np.nansum(row_cold[r[0] : r[1] + 1])))
        f.detected = True
        seg = cold[a : b + 1]
        depth_tc = np.nanpercentile(seg, 90, axis=0)
        primary = int(np.nanargmax(depth_tc))
        depth = float(depth_tc[primary])
        member_thr = max(L["sector_member_fraction"] * depth, 0.5 * L["cold_excess_C"])
        members = sorted(int(j) for j in np.flatnonzero(depth_tc >= member_thr))
        arcs = _ring_arcs(members, k)
        adjacent = len(members) >= 2 and arcs == 1
        ramp_min, max_jump, onset_i = _ramp_minutes(cold[:, primary], depth, a, b, case)
        a = min(a, onset_i)
        step_onset = (np.isfinite(ramp_min) and ramp_min <= L["step_onset_minutes"]) or max_jump >= 0.6 * depth
        active_at_end = b >= case.n - 1 - case.samples(60)
        dur_h = case.hours_between(a, b)
        peak_i = a + int(np.nanargmax(row_cold[a : b + 1]))

        # Sensor-health checks on the primary TC inside the event
        raw = X[a : b + 1, primary]
        flat = bool(np.nanstd(raw) < 0.05)
        implausible = bool(np.any(raw < 0) or np.any(raw > 1100) or np.mean(~np.isfinite(raw)) > 0.2)
        noise_evt = float(np.nanstd(np.diff(raw))) if raw.size > 2 else 0.0
        out_rows = np.ones(case.n, dtype=bool)
        out_rows[a : b + 1] = False
        out_rows &= steady
        noise_base = float(np.nanstd(np.diff(X[out_rows, primary]))) if out_rows.sum() > 3 else noise_evt
        erratic = noise_base > 0 and noise_evt > 3.0 * noise_base

        in_evt = np.zeros(case.n, dtype=bool)
        in_evt[a : b + 1] = True
        in_evt &= steady
        peak_spread = float(np.nanpercentile(spread[in_evt], 95)) if in_evt.any() else float("nan")

        # Coupled process channels
        fuel_pct = load_delta = vib_delta = dyn_delta = None
        load_col, fuel_col = case.first("load"), case.first("fuel")
        if fuel_col and load_col:
            z_mask = steady & ~in_evt
            fuel, load = case.series(fuel_col), case.series(load_col)
            ok = z_mask & np.isfinite(fuel) & np.isfinite(load)
            if ok.sum() > 50 and in_evt.any():
                p = np.polyfit(load[ok], fuel[ok], 1)
                resid = fuel - np.polyval(p, load)
                fuel_pct = float(np.nanmean(resid[in_evt]) / np.nanmean(fuel[ok]) * 100.0)
        if load_col and in_evt.any():
            load = case.series(load_col)
            load_delta = float(np.nanmean(load[in_evt]) - np.nanmean(load[steady & ~in_evt]))
        vib_col = case.first("vibration")
        if vib_col and in_evt.any():
            v = case.series(vib_col)
            vib_delta = float(np.nanmean(v[in_evt]) - np.nanmean(v[steady & ~in_evt]))
        dyn_col = case.first("dynamics")
        if dyn_col and in_evt.any():
            d = case.series(dyn_col)
            dyn_delta = float(np.nanmean(d[in_evt]) - np.nanmean(d[steady & ~in_evt]))
        fuel_comp = fuel_pct is not None and fuel_pct >= L["fuel_comp_fraction"] * 100

        sector = _tc_label(cols, members)
        primary_name = cols[primary]
        f.events.append(
            {
                "start_i": a,
                "end_i": b,
                "peak_i": peak_i,
                "start": case.time_at(a),
                "end": case.time_at(b),
                "peak": case.time_at(peak_i),
                "duration_h": round(dur_h, 1),
                "active_at_end": active_at_end,
            }
        )
        f.signature.update(
            {
                "detected": True,
                "depth_C": round(depth, 1),
                "primary_tc": primary_name,
                "sector": [cols[m] for m in members],
                "sector_size": len(members),
                "adjacent": adjacent,
                "onset_ramp_min": None if not np.isfinite(ramp_min) else round(ramp_min, 0),
                "step_onset": bool(step_onset),
                "duration_h": round(dur_h, 1),
                "active_at_end": bool(active_at_end),
                "peak_spread_C": None if not np.isfinite(peak_spread) else round(peak_spread, 1),
                "fuel_residual_pct": None if fuel_pct is None else round(fuel_pct, 2),
                "load_delta_MW": None if load_delta is None else round(load_delta, 2),
                "vib_delta_mm_s": None if vib_delta is None else round(vib_delta, 2),
                "ring_size": k,
            }
        )

        # Evidence (each item names the rule that produced it)
        f.add("Cold sector", f"{sector} ({ring_kind}, {len(members)} of {k})", "CS-R2", "TCs >= 30% of primary depth")
        f.add("Primary cold TC / depth", f"{primary_name}, {depth:.1f} C below its normal", "CS-R2", "90th pct over event")
        f.add("Sector contiguity", "adjacent arc" if adjacent else ("single TC" if len(members) == 1 else f"{arcs} separate arcs"), "CS-R3")
        f.add(
            "Onset",
            f"{'step' if step_onset else 'gradual'} onset ramp: {fmt(ramp_min, 0, 'min')} ({hours_text(ramp_min / 60) if np.isfinite(ramp_min) else 'n/a'}) from 10% to 90% depth; max single-sample jump {max_jump:.1f} C",
            "CS-R4",
        )
        f.add("Event window", f"{case.time_at(a)} -> {case.time_at(b)} ({hours_text(dur_h)})", "CS-R1")
        f.add("Status at end of data", "still active" if active_at_end else "cleared before end of data", "CS-R1")
        f.add("Exhaust spread", f"baseline {base_spread:.1f} C -> {fmt(peak_spread, 1, 'C')} during event (95th pct)", "CS-R5")
        if fuel_pct is not None:
            f.add("Fuel flow vs load model", f"{signed(fuel_pct)}% during event", "CS-R6", "positive = control compensating for lost heat")
        if load_delta is not None:
            f.add("Load change during event", f"{signed(load_delta)} MW", "CS-R6")
        if vib_delta is not None:
            f.add("Vibration change during event", f"{signed(vib_delta)} mm/s ({vib_col})", "CS-R6")
        if dyn_delta is not None:
            f.add("Combustion dynamics change", f"{signed(dyn_delta)} psi ({dyn_col})", "CS-R6")
        health = []
        if flat:
            health.append("flatlined")
        if implausible:
            health.append("implausible values")
        if erratic:
            health.append(f"erratic (noise x{noise_evt / max(noise_base, 1e-9):.1f})")
        f.add(f"{primary_name} signal health", ", ".join(health) if health else "normal noise, plausible values", "CS-R7")

        # Hypotheses
        tc_nums = [int("".join(ch for ch in cols[m] if ch.isdigit()) or -1) for m in members]
        notes_tc = notes.has("tc_work") and (not notes.tcs_mentioned or set(notes.tcs_mentioned) & set(tc_nums))

        inst_score, inst_sup, inst_against = 0.15, [], []
        if len(members) == 1:
            inst_score += 0.35
            inst_sup.append(f"only {primary_name} is cold; its neighbours read normally")
        else:
            inst_against.append(f"{len(members)} TCs are cold together — one failed TC cannot do that")
        if step_onset:
            inst_score += 0.2
            inst_sup.append("step-change onset (typical of open/shorted TC or harness)")
        else:
            inst_against.append("gradual onset over hours, not a step")
        if flat or implausible or erratic:
            inst_score += 0.35
            inst_sup.append(f"{primary_name} signal is {', '.join(health)}")
        if notes_tc:
            inst_score += 0.15
            inst_sup.append("notes mention recent TC / harness work in this sector")
        if not arcs <= 1 and len(members) > 1:
            inst_score += 0.15
            inst_sup.append("cold TCs are not contiguous on the ring")

        hw_score, hw_sup, hw_against = 0.2, [], []
        if adjacent:
            hw_score += 0.3
            hw_sup.append(f"{len(members)} adjacent TCs cool together ({sector}) — a real cold gas sector")
        else:
            hw_against.append("cold TCs do not form one adjacent sector")
        if not step_onset:
            hw_score += 0.15
            hw_sup.append("gradual onset, consistent with progressive fuel-nozzle restriction / combustor change")
        if fuel_comp:
            hw_score += 0.1
            hw_sup.append(f"fuel flow {fuel_pct:+.2f}% above the load model — control compensating for lost heat release")
        if load_delta is not None and load_delta < -0.3:
            hw_score += 0.05
            hw_sup.append(f"load down {abs(load_delta):.2f} MW during the event")
        if vib_delta is not None and vib_delta > 0.2:
            hw_score += 0.05
            hw_sup.append(f"vibration up {vib_delta:.2f} mm/s during the event")
        if flat or implausible or erratic:
            hw_score -= 0.25
            hw_against.append(f"{primary_name} signal health is questionable")
        hw_score += min(0.1, max(0.0, (depth - L["cold_excess_C"]) / 100.0))

        sev = "high" if depth >= L["high_depth_C"] or (np.isfinite(peak_spread) and peak_spread >= L["spread_alarm_C"]) else "medium"
        hyp_hw = Hypothesis(
            cause="combustion_hardware",
            title=f"True cold sector from the combustor can(s) upstream of {sector} (fuel nozzle restriction / combustion hardware)",
            score=round(min(0.95, max(0.05, hw_score)), 2),
            action="borescope",
            secondary=[],
            rules=["CS-R2", "CS-R3", "CS-R4", "CS-R6"],
            support=hw_sup,
            against=hw_against,
        )
        hyp_inst = Hypothesis(
            cause="instrumentation",
            title=f"Thermocouple / harness fault on {primary_name}",
            score=round(min(0.95, max(0.05, inst_score)), 2),
            action="sensor_fix_replace",
            rules=["CS-R3", "CS-R4", "CS-R7"],
            support=inst_sup,
            against=inst_against,
        )
        f.hypotheses = sorted([hyp_hw, hyp_inst], key=lambda h: h.score, reverse=True)
        top = f.hypotheses[0]

        if notes.has("repeat") or notes.has("borescope_done"):
            hyp_hw.secondary.append("combustion_tuning")
        if dyn_delta is not None and dyn_delta > 0.3:
            hyp_hw.secondary.append("combustion_tuning")
            f.review_flags.append("Combustion dynamics rose with the cold spot — check for a coupled dynamics issue.")
        act = actuator_check(case, (a, b))
        if act.get("abnormal"):
            top.secondary.append("lvdt_calibration")
            f.add("IGV vs load residual", f"max |z| {act['max_abs_z']:.1f} for {act['flagged_minutes']:.0f} min", "GEN-ACT")
        hyp_hw.secondary = sorted(set(hyp_hw.secondary))

        if top.cause == "combustion_hardware":
            f.severity = sev
            f.urgency = "prompt" if (active_at_end and sev == "high") else "next_opportunity"
            f.escalate = bool(active_at_end and np.isfinite(peak_spread) and peak_spread >= L["spread_alarm_C"])
            f.site_checks += [
                f"Verify {sector} readings in the controller (and spare/redundant TCs if fitted) before opening the unit.",
                f"Apply the unit swirl chart to map {sector} back to the upstream combustor can(s); inspect those fuel nozzles, liners and transition pieces.",
                "Check fuel-nozzle passages, purge and manifold pressures for that can (restriction / coking).",
            ]
            if active_at_end:
                f.operating_guidance.append("Trend exhaust spread every shift; reduce load per site procedure if spread approaches the HETS limit.")
            else:
                f.operating_guidance.append("Event cleared on its own — trend spread and the sector TCs for recurrence; recurrence brings the inspection forward.")
        else:
            f.severity = "medium" if len(members) == 1 else sev
            f.urgency = "prompt"
            f.site_checks += [
                f"Check {primary_name} loop: junction box, harness, connector, compensating cable; megger / loop-resistance test.",
                f"Compare {primary_name} with neighbouring TCs at the same load; replace the element if it fails the check.",
            ]
            f.operating_guidance.append("Spread protection may be biased by a bad TC — confirm the controller's TC rejection logic.")

        f.timeline = [
            (case.time_at(a), f"{primary_name} begins to run cold; sector {sector} follows"),
            (case.time_at(peak_i), f"Deepest point: {primary_name} {depth:.1f} C below normal, spread ~{fmt(peak_spread, 0, 'C')}"),
            (case.time_at(b), "Event still active at end of data" if active_at_end else f"Sector back to normal (event duration {hours_text(dur_h)})"),
        ]
        f.summary = (
            f"Cold sector {sector} ({len(members)} TC{'s' if len(members) > 1 else ''}, "
            f"{'adjacent' if adjacent else 'non-adjacent' if len(members) > 1 else 'single'}), "
            f"{primary_name} {depth:.1f} C below normal, {'step' if step_onset else 'gradual'} onset at {case.time_at(a)}, "
            f"{hours_text(dur_h)}, {'still active' if active_at_end else 'cleared'}; spread {base_spread:.1f} -> {fmt(peak_spread, 1, 'C')}."
        )
        f.what_happened = (
            f"From {case.time_at(a)} the exhaust {ring_kind} developed a cold sector at {sector}. "
            f"{primary_name} ran {depth:.1f} C below its normal position in the ring and exhaust spread rose from "
            f"{base_spread:.1f} C to about {fmt(peak_spread, 1, 'C')}. The onset was {'a step change' if step_onset else 'gradual'} "
            f"({fmt(ramp_min, 0, 'min')} from 10% to 90% depth) and the event lasted {hours_text(dur_h)} in total, "
            f"{'and was still active at the end of the data' if active_at_end else f'clearing at {case.time_at(b)}'}."
            + (f" Fuel flow ran {fuel_pct:+.2f}% above the load model during the event." if fuel_pct is not None else "")
        )
        f.why = (
            f"Most likely cause: {top.title} (rule support {top.score:.2f}). "
            + ("; ".join(top.support) + ". " if top.support else "")
            + (f"Alternative considered: {f.hypotheses[1].title} ({f.hypotheses[1].score:.2f}) — " + "; ".join(f.hypotheses[1].against) + "." if len(f.hypotheses) > 1 and f.hypotheses[1].against else "")
        )
        f.strength = top.score
        f.chart = {
            "channels": [c for c in [spread_col] if c] + [cols[m] for m in members[:3]] + ([fuel_col] if fuel_col else []),
            "event": [a, b],
        }
        if probe:
            f.review_flags = []
        return f
# >>>>>>> END sentinel.analytics.cold_spot

# =============================================================================
# sentinel.analytics.combustion_dynamics
# Rule-path dynamics check: pulsation that is real versus a dead probe.
# =============================================================================
# <<<<<<< SECTION sentinel.analytics.combustion_dynamics sentinel/analytics/combustion_dynamics.py
if False:  # compiled by exec_section('sentinel.analytics.combustion_dynamics'); not executed as part of this module
    """Combustion dynamics (pulsation) analyzer."""

    # @@future@@ from __future__ import annotations

    from typing import Optional

    import numpy as np

    from ..data import CaseData
    from ..limits import COMBUSTION_DYNAMICS as L
    from ..notes import NotesInfo
    from .base import (
        Findings,
        Hypothesis,
        actuator_check,
        fmt,
        hours_text,
        robust_stats,
        rolling_median,
        runs,
        signed,
        steady_mask,
    )

    VERSION = "combustion_dynamics/1.0"
    # A dynamics slot, by legacy role or by slot id.
    REQUIRES = {"legacy_any": ["dynamics"]}


    def _corr(a: np.ndarray, b: np.ndarray) -> Optional[float]:
        """Function _corr."""
        ok = np.isfinite(a) & np.isfinite(b)
        if ok.sum() < 20 or np.std(a[ok]) < 1e-9 or np.std(b[ok]) < 1e-9:
            return None
        return float(np.corrcoef(a[ok], b[ok])[0, 1])


    def _modulation_period_min(x: np.ndarray, mps: float) -> Optional[float]:
        """Dominant envelope modulation period (minutes) from the autocorrelation, 2..60 min."""
        v = x[np.isfinite(x)]
        if v.size < 60:
            return None
        v = v - np.mean(v)
        max_lag = int(min(len(v) // 3, max(3, 60 / mps)))
        min_lag = max(2, int(np.ceil(2 / mps)))
        if max_lag <= min_lag + 1:
            return None
        denom = float(np.dot(v, v)) or 1.0
        ac = np.array([np.dot(v[:-lag], v[lag:]) / denom for lag in range(1, max_lag + 1)])
        best = None
        for lag in range(min_lag, max_lag - 1):
            if ac[lag - 1] > ac[lag - 2] and ac[lag - 1] >= ac[lag] and ac[lag - 1] > 0.2:
                best = lag
                break
        return None if best is None else best * mps


    def analyze(case: CaseData, notes: NotesInfo, probe: bool = False) -> Findings:
        """Function analyze."""
        f = Findings(analytic="combustion_dynamics", analyzer_version=VERSION, detected=False, summary="")
        dyn_cols = case.roles.get("dynamics") or []
        if not dyn_cols:
            f.missing_channels.append("combustion dynamics channel (e.g. comb_dyn_psi)")
            f.summary = "No combustion dynamics channel in the data; dynamics cannot be evaluated."
            f.data_gaps.append("Export the combustion dynamics amplitude channel(s) for the alert window.")
            return f

        steady = steady_mask(case)
        env_n = case.samples(L["envelope_minutes"])
        # Choose the dynamics channel with the largest elevation above its own baseline
        best = None
        for c in dyn_cols:
            x = case.series(c)
            base, sig = robust_stats(x[steady] if steady.any() else x)
            env = rolling_median(x, env_n)
            score = float(np.nanmax(np.where(steady, env, np.nan)) - base) if np.isfinite(env).any() else 0.0
            if best is None or score > best[0]:
                best = (score, c, x, base, sig, env)
        _, col, x, base, sig, env = best
        f.explained_channels = list(dyn_cols) + list(case.zones) + [
            c for c in (case.first("spread"), case.first("egt_avg"), case.first("fuel")) if c
        ] + list(case.roles.get("vibration", []))

        env_s = np.where(steady, env, np.nan)
        if case.interval_minutes and case.interval_minutes > 5:
            f.data_gaps.append(
                f"Data resolution is {case.interval_minutes:.0f} min; dynamics bursts shorter than that are invisible — 1 min or faster preferred."
            )
        f.data_gaps.append("Historian amplitude only: the acoustic tone frequency (Hz) needs the high-speed dynamics monitor spectrum.")

        rel_thr = base + 6.0 * sig
        elevated = np.nan_to_num(env_s, nan=-1) > rel_thr
        candidates = runs(elevated, min_len=case.samples(L["min_event_minutes"]), max_gap=case.samples(15))
        raw_alert = np.nan_to_num(x, nan=-1) > L["alert_psi"]
        ev_runs, sub_runs = [], []
        for r in candidates:
            mins = float(np.sum(raw_alert[r[0] : r[1] + 1]) * case.minutes_per_sample)
            (ev_runs if mins >= L["min_event_minutes"] else sub_runs).append(r)
        f.signature["baseline_psi"] = round(base, 3)
        f.add("Dynamics baseline", f"{base:.2f} psi (robust sigma {sig:.3f}) on {col}", "CD-R1")

        # Probe-health checks over the whole record
        vals = x[np.isfinite(x)]
        flat_run = runs(np.abs(np.diff(x, prepend=x[0])) < 1e-9, min_len=case.samples(120))
        vmax = float(np.nanmax(vals)) if vals.size else 0.0
        saturated = vals.size > 0 and np.mean(vals >= vmax - 1e-9) > 0.02 and vmax > L["alert_psi"]
        negative = bool(np.any(vals < 0))

        if not ev_runs:
            peak_env = float(np.nanmax(env_s)) if np.isfinite(env_s).any() else 0.0
            if sub_runs:
                a, b = max(sub_runs, key=lambda r: r[1] - r[0])
                f.events.append({"start_i": a, "end_i": b, "peak_i": a, "start": case.time_at(a), "end": case.time_at(b), "peak": case.time_at(a), "duration_h": round(case.hours_between(a, b), 1), "active_at_end": b >= case.n - 1 - case.samples(30)})
                f.detected = True
                f.summary = f"Dynamics elevated above baseline but below the {L['alert_psi']} psi alert limit (peak envelope {peak_env:.2f} psi)."
                f.severity, f.urgency = "low", "routine"
                f.hypotheses.append(Hypothesis("combustion_instability", "Sub-alert dynamics elevation", 0.6, "monitor_only", rules=["CD-R2"], support=["envelope below the alert limit"]))
            else:
                f.summary = f"No dynamics event: peak envelope {peak_env:.2f} psi vs alert limit {L['alert_psi']} psi."
                f.severity, f.urgency = "low", "routine"
                f.hypotheses.append(Hypothesis("not_confirmed", "Combustion dynamics alert not present in the supplied data", 0.6, "monitor_only", rules=["CD-R1"], support=["envelope never sustained above the alert limit"]))
                f.review_flags.append("Analytic alert not confirmed by the data — check the export window and probe.")
            f.add("Peak dynamics envelope", fmt(peak_env, 2, "psi"), "CD-R1", f"{L['envelope_minutes']} min rolling median")
            f.signature.update({"detected": f.detected, "peak_psi": round(peak_env, 2)})
            f.what_happened = f.summary
            f.why = "Dynamics stayed below the site alert limit, so no tuning or hardware action is justified by this data."
            f.chart = {"channels": [col], "event": None}
            f.strength = 0.3 if f.detected else 0.0
            return f

        a, b = max(ev_runs, key=lambda r: float(np.nansum(env_s[r[0] : r[1] + 1] - base)))
        f.detected = True
        seg = x[a : b + 1]
        seg_env = env[a : b + 1]
        peak = float(np.nanpercentile(seg, 99))
        mean_amp = float(np.nanmean(seg))
        mps = case.minutes_per_sample
        min_alert = float(np.sum(seg > L["alert_psi"]) * mps)
        min_alarm = float(np.sum(seg > L["alarm_psi"]) * mps)
        min_high = float(np.sum(seg > L["high_psi"]) * mps)
        dur_h = case.hours_between(a, b)
        active_at_end = b >= case.n - 1 - case.samples(30)
        thirds = max(1, len(seg_env) // 3)
        trend = float(np.nanmean(seg_env[-thirds:]) - np.nanmean(seg_env[:thirds]))
        rising = trend > 0.15 * max(mean_amp - base, 1e-6) and active_at_end
        period = _modulation_period_min(seg, mps)
        peak_i = a + int(np.nanargmax(seg_env))

        # Coupling with exhaust spread and vibration
        spread_col = case.first("spread")
        vib_cols = case.roles.get("vibration", [])
        r_spread = _corr(seg, case.series(spread_col)[a : b + 1]) if spread_col else None
        r_vib = None
        vib_col = None
        for vc in vib_cols:
            r = _corr(seg, case.series(vc)[a : b + 1])
            if r is not None and (r_vib is None or r > r_vib):
                r_vib, vib_col = r, vc
        outside = steady.copy()
        outside[max(0, a - case.samples(60)) : min(case.n, b + case.samples(60) + 1)] = False
        spread_delta = vib_delta = None
        if spread_col and outside.any():
            s = case.series(spread_col)
            spread_delta = float(np.nanmean(s[a : b + 1]) - np.nanmean(s[outside]))
        if vib_col and outside.any():
            v = case.series(vib_col)
            vib_delta = float(np.nanmean(v[a : b + 1]) - np.nanmean(v[outside]))
        coupled = (r_spread is not None and r_spread >= L["coupling_r"]) or (r_vib is not None and r_vib >= L["coupling_r"])

        # Operating point at onset (load / IGV / fuel movement in the hour before)
        load_col = case.first("load")
        load_step = None
        if load_col:
            l = case.series(load_col)
            pre = l[max(0, a - case.samples(60)) : a + 1]
            if pre.size > 2 and np.nanmean(l[outside]) > 0:
                load_step = float((np.nanmax(pre) - np.nanmin(pre)) / np.nanmean(l[outside]) * 100)
        trigger = load_step is not None and load_step > 5.0

        probe_flat = any(r[0] <= b and r[1] >= a for r in flat_run)
        uncoupled_spiky = (not coupled) and dur_h < 2.0 and peak > 3 * max(mean_amp, 1e-6)
        probe_bad = probe_flat or saturated or negative or uncoupled_spiky

        f.events.append(
            {
                "start_i": a,
                "end_i": b,
                "peak_i": peak_i,
                "start": case.time_at(a),
                "end": case.time_at(b),
                "peak": case.time_at(peak_i),
                "duration_h": round(dur_h, 1),
                "active_at_end": active_at_end,
            }
        )
        f.signature.update(
            {
                "detected": True,
                "channel": col,
                "peak_psi": round(peak, 2),
                "mean_psi": round(mean_amp, 2),
                "minutes_above_alert": round(min_alert),
                "minutes_above_alarm": round(min_alarm),
                "minutes_above_high": round(min_high),
                "duration_h": round(dur_h, 1),
                "modulation_period_min": None if period is None else round(period, 1),
                "r_spread": None if r_spread is None else round(r_spread, 2),
                "r_vib": None if r_vib is None else round(r_vib, 2),
                "coupled": bool(coupled),
                "spread_delta_C": None if spread_delta is None else round(spread_delta, 1),
                "vib_delta_mm_s": None if vib_delta is None else round(vib_delta, 2),
                "active_at_end": bool(active_at_end),
                "rising": bool(rising),
                "load_step_pct": None if load_step is None else round(load_step, 1),
                "probe_suspect": bool(probe_bad),
            }
        )

        f.add("Event window", f"{case.time_at(a)} -> {case.time_at(b)} ({hours_text(dur_h)})", "CD-R2")
        f.add("Peak / mean amplitude", f"{peak:.2f} / {mean_amp:.2f} psi (baseline {base:.2f})", "CD-R2", "99th pct / mean of raw samples")
        f.add(
            "Time above limits",
            f"alert {L['alert_psi']} psi: {min_alert:.0f} min; alarm {L['alarm_psi']} psi: {min_alarm:.0f} min; high {L['high_psi']} psi: {min_high:.0f} min",
            "CD-R3",
            "raw historian samples above each limit",
        )
        if period is not None:
            f.add("Envelope modulation period", f"~{period:.0f} min", "CD-R4", "amplitude beating, not the acoustic tone")
        f.add(
            "Coupling",
            f"r(dyn, spread) = {fmt(r_spread, 2)}; r(dyn, vibration) = {fmt(r_vib, 2)}",
            "CD-R5",
            f"coupled if r >= {L['coupling_r']}",
        )
        if spread_delta is not None:
            f.add("Exhaust spread during event", f"{spread_delta:+.1f} C vs normal", "CD-R5")
        if vib_delta is not None:
            f.add("Vibration during event", f"{signed(vib_delta)} mm/s ({vib_col})", "CD-R5")
        if load_step is not None:
            f.add("Load movement in hour before onset", f"{load_step:.1f}% of normal load", "CD-R6")
        f.add("Trend inside event", "rising at end of data" if rising else ("still active" if active_at_end else "decayed / ended"), "CD-R2")
        health = [s for s, on in (("flatline", probe_flat), ("saturated", saturated), ("negative values", negative), ("short uncoupled spikes", uncoupled_spiky)) if on]
        f.add(f"{col} probe health", ", ".join(health) if health else "plausible, varies with process", "CD-R7")

        # Severity by amplitude
        alarm_sustained = min_alarm >= L["min_event_minutes"]
        if peak >= L["high_psi"] or alarm_sustained:
            sev = "high"
        else:
            sev = "medium"
        hardware_risk = min_high >= L["hardware_risk_hours"] * 60 or (vib_delta is not None and vib_delta > 1.5)
        if hardware_risk or (rising and peak >= L["alarm_psi"]):
            sev = "critical"

        inst_score, inst_sup, inst_against = 0.1, [], []
        if probe_bad:
            inst_score += 0.55
            inst_sup.append(f"{col} shows {', '.join(health)}")
        if not coupled:
            inst_score += 0.15
            inst_sup.append("no coupling with exhaust spread or vibration")
        else:
            inst_against.append("amplitude is mirrored by exhaust spread / vibration — the combustion is really pulsing")
        if notes.has("probe_issue"):
            inst_score += 0.15
            inst_sup.append("notes report a probe / cable concern")

        cmb_score, cmb_sup, cmb_against = 0.35, [], []
        if coupled:
            cmb_score += 0.3
            cmb_sup.append(
                f"dynamics track exhaust spread (r={fmt(r_spread, 2)}) and vibration (r={fmt(r_vib, 2)}) — real pressure oscillation in the flame"
            )
        else:
            cmb_against.append("no coupling with spread / vibration")
        if dur_h >= 1.0:
            cmb_score += 0.1
            cmb_sup.append(f"sustained for {hours_text(dur_h)} above the alert limit")
        if probe_bad:
            cmb_score -= 0.3
            cmb_against.append("probe health is questionable")
        if notes.has("operator_reports_noise"):
            cmb_score += 0.05
            cmb_sup.append("operators report an audible tone / noise")
        cmb_score += min(0.1, (peak - L["alert_psi"]) / 20.0)

        secondary = []
        if hardware_risk:
            secondary.append("borescope")
        if trigger:
            secondary.append("control_adjustment")
        if alarm_sustained or (notes.has("recent_tuning") and notes.has("repeat")):
            secondary.append("escalate")
        act = actuator_check(case, (a, b))
        if act.get("abnormal") or notes.has("lvdt"):
            secondary.append("lvdt_calibration")
            if act.get("abnormal"):
                f.add("IGV vs load residual", f"max |z| {act['max_abs_z']:.1f} for {act['flagged_minutes']:.0f} min", "GEN-ACT")

        hyp_cmb = Hypothesis(
            cause="combustion_instability",
            title="Combustion instability — insufficient dynamics margin at this operating point (fuel splits / DLN schedule)",
            score=round(min(0.95, max(0.05, cmb_score)), 2),
            action="combustion_tuning",
            secondary=sorted(set(secondary)),
            rules=["CD-R2", "CD-R3", "CD-R5"],
            support=cmb_sup,
            against=cmb_against,
        )
        hyp_inst = Hypothesis(
            cause="instrumentation",
            title=f"Dynamics probe / cable fault on {col}",
            score=round(min(0.95, max(0.05, inst_score)), 2),
            action="sensor_fix_replace",
            rules=["CD-R5", "CD-R7"],
            support=inst_sup,
            against=inst_against,
        )
        f.hypotheses = sorted([hyp_cmb, hyp_inst], key=lambda h: h.score, reverse=True)
        top = f.hypotheses[0]

        if top.cause == "combustion_instability":
            f.severity = sev
            f.escalate = "escalate" in top.secondary or sev == "critical"
            f.urgency = "immediate" if sev == "critical" or (active_at_end and peak >= L["alarm_psi"]) else "prompt"
            if notes.has("recent_tuning"):
                f.review_flags.append("Notes say the unit was recently tuned — dynamics returned; tuning margin or hardware change needs SME review.")
                if "escalate" not in top.secondary:
                    top.secondary.append("escalate")
                f.escalate = True
            f.site_checks += [
                "Pull the high-speed dynamics monitor spectrum for the event: identify the tone (Hz) and which cans lead.",
                "Review fuel splits, fuel gas temperature and composition (Wobbe) at onset against the tuning baseline.",
                "Confirm the dynamics probe is healthy (compare redundant probes / cans) before tuning.",
            ]
            if alarm_sustained:
                f.operating_guidance.append(f"Dynamics exceeded the {L['alarm_psi']} psi alarm level for {min_alarm:.0f} min: if it recurs, reduce load / change mode per site procedure and notify the combustion SME.")
            f.operating_guidance.append("Avoid fast load ramps and fuel transfers in this load band until tuned.")
            if hardware_risk:
                f.operating_guidance.append(f"{min_high / 60:.1f} h above {L['high_psi']} psi: liner / transition piece damage is possible — borescope before extended operation.")
        else:
            f.severity = "medium"
            f.urgency = "prompt"
            f.site_checks += [
                f"Check {col} transducer, cable and charge amplifier; compare with redundant probes.",
                "Do not tune on a suspect probe signal.",
            ]

        f.timeline = [
            (case.time_at(a), "Dynamics rise above baseline and cross the alert limit"),
            (case.time_at(peak_i), f"Highest {L['envelope_minutes']}-min median amplitude {float(np.nanmax(seg_env)):.2f} psi (raw 99th pct {peak:.2f} psi)"),
            (case.time_at(b), "Still elevated at end of data" if active_at_end else "Dynamics return below alert"),
        ]
        f.summary = (
            f"Dynamics event on {col}: peak {peak:.2f} psi, mean {mean_amp:.2f} psi (baseline {base:.2f}), "
            f"{hours_text(dur_h)} from {case.time_at(a)}; {min_alarm:.0f} min above alarm; "
            f"{'coupled' if coupled else 'NOT coupled'} with spread/vibration; {'still active' if active_at_end else 'ended'}."
        )
        f.what_happened = (
            f"Starting {case.time_at(a)}, combustion dynamics on {col} rose from a baseline of {base:.2f} psi to a mean of "
            f"{mean_amp:.2f} psi with peaks of {peak:.2f} psi, for {hours_text(dur_h)}. The envelope was above the "
            f"{L['alert_psi']} psi alert for {min_alert:.0f} min, above the {L['alarm_psi']} psi alarm for {min_alarm:.0f} min "
            f"and above {L['high_psi']} psi for {min_high:.0f} min."
            + (f" The amplitude beat with a ~{period:.0f} min period." if period else "")
            + (f" Exhaust spread rose {spread_delta:+.1f} C and {vib_col} {signed(vib_delta)} mm/s during the event." if spread_delta is not None and vib_delta is not None else "")
            + (" The event was still active at the end of the data." if active_at_end else f" It ended at {case.time_at(b)}.")
        )
        f.why = (
            f"Most likely cause: {top.title} (rule support {top.score:.2f}). "
            + ("; ".join(top.support) + ". " if top.support else "")
            + (f"Alternative considered: {f.hypotheses[1].title} ({f.hypotheses[1].score:.2f}) — " + "; ".join(f.hypotheses[1].against) + "." if len(f.hypotheses) > 1 and f.hypotheses[1].against else "")
        )
        f.strength = top.score
        f.chart = {"channels": [col] + ([spread_col] if spread_col else []) + ([vib_col] if vib_col else []), "event": [a, b]}
        if probe:
            f.review_flags = []
        return f
# >>>>>>> END sentinel.analytics.combustion_dynamics

# =============================================================================
# sentinel.analytics.hets_trip
# Rule-path trip check: first-out spread trip versus a sensor step that only looks like one.
# =============================================================================
# <<<<<<< SECTION sentinel.analytics.hets_trip sentinel/analytics/hets_trip.py
if False:  # compiled by exec_section('sentinel.analytics.hets_trip'); not executed as part of this module
    """HETS (high exhaust temperature spread) trip analyzer."""

    # @@future@@ from __future__ import annotations

    from typing import List, Optional, Tuple

    import numpy as np

    from ..data import CaseData
    from ..limits import HETS_TRIP as L
    from ..notes import NotesInfo, first_out_is_spread
    from .base import Findings, Hypothesis, fmt, hours_text, rolling_median, runs

    VERSION = "hets_trip/1.0"
    # An exhaust ring or zones, plus a spread or a trip slot.
    REQUIRES = {"ring_or_zones": True, "legacy_any": ["spread", "trip"]}


    def find_trips(case: CaseData) -> Tuple[List[Tuple[int, int]], str]:
        """Trip windows as (start, end) sample indices, and how they were found."""
        trip = case.first("trip")
        if trip:
            t = np.nan_to_num(case.series(trip)) > 0.5
            r = runs(t, min_len=1, max_gap=case.samples(10))
            if r:
                return r, f"trip flag '{trip}'"
        load = case.first("load")
        if load:
            l = case.series(load)
            ref = rolling_median(l, case.samples(6 * 60))
            ref = np.concatenate([[ref[0]] * case.samples(30), ref[: -case.samples(30)]]) if len(ref) > case.samples(30) else ref
            low = np.nan_to_num(l, nan=np.inf) < L["load_collapse_fraction"] * np.nan_to_num(ref)
            med = np.nanmedian(l)
            low &= np.nan_to_num(ref) > 0.5 * med
            r = runs(low, min_len=1, max_gap=case.samples(10))
            if r:
                return r, f"load collapse on '{load}' (no trip flag in data)"
        return [], "none"


    def analyze(case: CaseData, notes: NotesInfo, probe: bool = False) -> Findings:
        """Function analyze."""
        f = Findings(analytic="hets_trip", analyzer_version=VERSION, detected=False, summary="")
        zones = case.zones if case.zones else case.ring
        spread_col = case.first("spread")
        load_col = case.first("load")
        f.explained_channels = [c for c in case.numeric_columns]  # a trip moves every process channel
        if len(zones) < 3 and not spread_col:
            f.missing_channels.append("exhaust spread and zone / TC temperatures")
        if not load_col and not case.first("trip"):
            f.missing_channels.append("trip flag or load")

        trips, how = find_trips(case)
        if not trips:
            f.summary = "No trip found in the supplied data (no trip flag edge, no load collapse)."
            f.hypotheses.append(
                Hypothesis("not_confirmed", "HETS trip not present in the supplied data", 0.6, "monitor_only", rules=["HT-R1"], support=["no trip flag and no load collapse"])
            )
            f.review_flags.append("Trip not found — the export window probably does not cover the event.")
            f.data_gaps.append("Re-export historian data covering at least 6 h before through 24 h after the trip.")
            f.what_happened = f.summary
            f.why = "Without the trip in the data the HETS sequence cannot be reconstructed."
            f.add("Trip detection", "no trip found", "HT-R1", how)
            f.chart = {"channels": [c for c in (spread_col, load_col) if c], "event": None}
            return f
        if not spread_col and len(zones) < 3:
            f.summary = f"Trip found ({how}) but no exhaust spread / zone data to test the HETS signature."
            f.hypotheses.append(Hypothesis("unknown", "Trip cause cannot be assessed without exhaust data", 0.3, "escalate", rules=["HT-R1"]))
            f.what_happened = f.summary
            f.why = f.summary
            f.severity, f.urgency, f.escalate = "high", "before_restart", True
            return f

        Z = np.column_stack([case.series(c) for c in zones]) if len(zones) >= 3 else None
        spread = case.series(spread_col) if spread_col else (np.nanmax(Z, axis=1) - np.nanmin(Z, axis=1))
        pre_n = case.samples(L["pretrip_hours"] * 60)

        # Analyse the trip with the highest pre-trip spread
        def pre_peak(tr: Tuple[int, int]) -> float:
            """Function pre_peak."""
            s, _ = tr
            w = spread[max(0, s - pre_n) : s + 1]
            return float(np.nanmax(w)) if w.size else 0.0

        ts, te = max(trips, key=pre_peak)
        f.detected = True
        w0 = max(0, ts - pre_n)
        base_lo = max(0, w0 - case.samples(7 * 24 * 60))
        base_seg = spread[base_lo:w0] if w0 - base_lo > 10 else spread[: max(10, w0)]
        base_spread = float(np.nanmedian(base_seg))
        pre = spread[w0 : ts + 1]
        peak_rel = int(np.nanargmax(pre))
        peak_i = w0 + peak_rel
        peak_spread = float(pre[peak_rel])
        rise = peak_spread - base_spread
        # Rise start: last sample before the peak still within 20% of the rise
        thr20 = base_spread + 0.2 * rise
        below = np.flatnonzero(pre[: peak_rel + 1] <= thr20)
        rise_start = w0 + (int(below[-1]) if below.size else 0)
        # Rise time = rise start until 90% of the rise is reached; a single huge jump also counts as a step
        rel = rise_start - w0
        hit90 = np.flatnonzero(pre[rel : peak_rel + 1] >= base_spread + 0.9 * rise)
        i90 = rise_start + (int(hit90[0]) if hit90.size else peak_rel - rel)
        rise_min = max(case.minutes_per_sample, (i90 - rise_start) * case.minutes_per_sample)
        seg_rise = pre[rel : peak_rel + 1]
        max_jump = float(np.nanmax(np.diff(seg_rise))) if seg_rise.size > 1 else rise
        rate = rise / max(rise_min / 60.0, 1e-6)
        built_up = rise >= L["spread_rise_C"]
        step = built_up and (rise_min <= L["step_rise_minutes"] or max_jump >= 0.6 * rise)

        # Zone pattern at peak (median reference so one bad zone cannot shift the others)
        hot, cold, zone_devs = [], [], {}
        single_zone = opposing = False
        if Z is not None:
            zb = Z[base_lo:w0] if w0 - base_lo > 10 else Z[: max(10, w0)]
            base_off = np.nanmedian(zb - np.nanmedian(zb, axis=1, keepdims=True), axis=0)
            row = Z[peak_i] - np.nanmedian(Z[peak_i]) - base_off
            zone_devs = {zones[j]: round(float(row[j]), 1) for j in range(len(zones))}
            hot = [zones[j] for j in range(len(zones)) if row[j] >= L["zone_dev_C"]]
            cold = [zones[j] for j in range(len(zones)) if row[j] <= -L["zone_dev_C"]]
            opposing = bool(hot) and bool(cold)
            single_zone = len(hot) + len(cold) == 1

        # Process context before the rise (load / IGV movement => transient trigger)
        load_move = None
        if load_col:
            l = case.series(load_col)
            seg = l[max(0, rise_start - case.samples(60)) : ts]  # exclude the trip itself
            ref = np.nanmedian(l[base_lo:w0]) if w0 > base_lo else np.nanmedian(l)
            if seg.size > 2 and ref > 0:
                load_move = float((np.nanmax(seg) - np.nanmin(seg)) / ref * 100)
        transient = load_move is not None and load_move > 10.0

        # Concurrent channels: precursor (before trip) vs consequence (at trip)
        vib_col, dyn_col = case.first("vibration"), case.first("dynamics")
        vib_pre = vib_trip = dyn_pre = dyn_trip = vib_base = dyn_base = None
        if vib_col:
            v = case.series(vib_col)
            vib_base = float(np.nanmedian(v[base_lo:w0])) if w0 > base_lo else float(np.nanmedian(v))
            vib_pre = float(np.nanmax(v[rise_start : ts])) if ts > rise_start else vib_base
            vib_trip = float(np.nanmax(v[ts : te + 1]))
        if dyn_col:
            d = case.series(dyn_col)
            dyn_base = float(np.nanmedian(d[base_lo:w0])) if w0 > base_lo else float(np.nanmedian(d))
            dyn_pre = float(np.nanmax(d[rise_start : ts])) if ts > rise_start else dyn_base
            dyn_trip = float(np.nanmax(d[ts : te + 1]))
        precursor_mech = vib_pre is not None and vib_base is not None and vib_pre > vib_base * 1.5

        # Post-trip: restart and spread after restart
        restart_i = None
        post_spread = None
        fast_return = False
        if load_col:
            l = case.series(load_col)
            ref = np.nanmedian(l[base_lo:w0]) if w0 > base_lo else np.nanmedian(l)
            back = np.flatnonzero(np.nan_to_num(l[te + 1 :]) >= 0.8 * ref)
            if back.size:
                restart_i = te + 1 + int(back[0])
                ps = spread[restart_i : restart_i + case.samples(6 * 60)]
                post_spread = float(np.nanmedian(ps)) if ps.size else None
                fast_return = (restart_i - te) * case.minutes_per_sample <= 30
        repeat_after_restart = post_spread is not None and post_spread > base_spread + L["restart_spread_margin_C"]
        fo = first_out_is_spread(notes)

        f.events.append(
            {
                "start_i": rise_start,
                "end_i": te,
                "peak_i": peak_i,
                "start": case.time_at(rise_start),
                "end": case.time_at(te),
                "peak": case.time_at(peak_i),
                "trip_i": ts,
                "trip": case.time_at(ts),
                "duration_h": round(case.hours_between(rise_start, te), 1),
                "active_at_end": restart_i is None,
            }
        )
        f.signature.update(
            {
                "detected": True,
                "trip_count": len(trips),
                "trip_time": case.time_at(ts),
                "trip_source": how,
                "baseline_spread_C": round(base_spread, 1),
                "peak_spread_C": round(peak_spread, 1),
                "rise_C": round(rise, 1),
                "rise_minutes": round(rise_min),
                "rise_rate_C_per_h": round(rate, 1),
                "step_rise": bool(step),
                "hot_zones": hot,
                "cold_zones": cold,
                "opposing_hot_cold": bool(opposing),
                "single_zone": bool(single_zone),
                "load_move_pct": None if load_move is None else round(load_move, 1),
                "restarted": restart_i is not None,
                "post_restart_spread_C": None if post_spread is None else round(post_spread, 1),
                "repeat_after_restart": bool(repeat_after_restart),
            }
        )

        f.add("Trip", f"{case.time_at(ts)} ({how}); {len(trips)} trip(s) in file", "HT-R1")
        if fo is True:
            f.add("First-out (notes)", notes.first_out, "HT-R1", "confirms exhaust spread protection")
        elif fo is False:
            f.add("First-out (notes)", notes.first_out, "HT-R1", "NOT an exhaust spread first-out")
            f.review_flags.append(f"Notes give first-out '{notes.first_out}', not HETS — confirm the trip cause in the SOE.")
        f.add("Spread build-up (to trip)", f"{base_spread:.1f} C -> {peak_spread:.1f} C over {hours_text(rise_min / 60)} ({rate:.1f} C/h)", "HT-R2")
        f.add("Rise character", "step change" if step else ("gradual build-up" if built_up else "no significant pre-trip rise"), "HT-R2", f"step if <= {L['step_rise_minutes']} min")
        if zone_devs:
            f.add("Zone deviations at peak", ", ".join(f"{k} {v:+.1f}" for k, v in zone_devs.items()) + " C", "HT-R3", "vs median of zones, baseline offsets removed")
            f.add("Pattern", "opposing hot and cold zones (true circumferential imbalance)" if opposing else ("single zone deviating alone" if single_zone else "no clear zone pattern"), "HT-R3")
        if load_move is not None:
            f.add("Load movement before/during rise", f"{load_move:.1f}% of normal", "HT-R4")
        if vib_col:
            f.add("Vibration", f"baseline {fmt(vib_base, 2)}, pre-trip max {fmt(vib_pre, 2)}, at trip {fmt(vib_trip, 2)} mm/s ({vib_col})", "HT-R5")
        if dyn_col:
            f.add("Dynamics", f"baseline {fmt(dyn_base, 2)}, pre-trip max {fmt(dyn_pre, 2)}, at trip {fmt(dyn_trip, 2)} psi ({dyn_col})", "HT-R5")
        if restart_i is not None:
            f.add("Restart", f"back to >=80% load at {case.time_at(restart_i)} ({hours_text(case.hours_between(te, restart_i))} after trip)", "HT-R6")
            f.add("Spread after restart", f"{fmt(post_spread, 1, 'C')} (first 6 h at load)", "HT-R6")
        else:
            f.add("Restart", "unit not back at load by end of data", "HT-R6")
        if fast_return:
            f.review_flags.append("Load is back within 30 min of the trip flag — confirm whether this was a full trip, a runback, or a data gap.")

        # Hypotheses
        hw_score, hw_sup, hw_against = 0.25, [], []
        if opposing:
            hw_score += 0.3
            hw_sup.append(f"hot ({', '.join(hot)}) and cold ({', '.join(cold)}) zones diverge together — real circumferential combustion imbalance")
        if built_up and not step:
            hw_score += 0.2
            hw_sup.append(f"spread built up over {hours_text(rise_min / 60)} at {rate:.1f} C/h before protection acted")
        if step:
            hw_score -= 0.2
            hw_against.append("spread rose as a step change")
        if single_zone:
            hw_score -= 0.15
            hw_against.append("only one zone moved")
        if not transient:
            hw_score += 0.05
        if repeat_after_restart:
            hw_score += 0.1
            hw_sup.append("spread came back high after restart")
        if fo is True:
            hw_score += 0.05

        inst_score, inst_sup, inst_against = 0.1, [], []
        if single_zone:
            inst_score += 0.35
            inst_sup.append("a single zone deviates while the others stay at the ring median")
        if step:
            inst_score += 0.3
            inst_sup.append("step-change spread rise (open / shorted TC can fool spread logic)")
        if opposing:
            inst_against.append("hot and cold zones moved in opposite directions — a single bad TC cannot do that")
        if built_up and not step:
            inst_against.append("gradual multi-hour build-up")
        if notes.has("tc_work"):
            inst_score += 0.15
            inst_sup.append("notes mention recent TC / harness work")

        tr_score, tr_sup = 0.1, []
        if transient:
            tr_score += 0.4
            tr_sup.append(f"load moved {load_move:.0f}% just before/during the spread rise")
        if notes.has("load_change") or notes.has("fuel_quality"):
            tr_score += 0.15
            tr_sup.append("notes mention a load change / fuel transfer / fuel quality event")

        hyp_hw = Hypothesis(
            cause="combustion_hardware",
            title="Combustion hardware / fuel nozzle fault causing circumferential imbalance (hot and cold sectors)",
            score=round(min(0.95, max(0.05, hw_score)), 2),
            action="borescope",
            secondary=["escalate"],
            rules=["HT-R2", "HT-R3", "HT-R6"],
            support=hw_sup,
            against=hw_against,
        )
        hyp_inst = Hypothesis(
            cause="instrumentation",
            title="Exhaust thermocouple / harness fault fooling the spread protection",
            score=round(min(0.95, max(0.05, inst_score)), 2),
            action="sensor_fix_replace",
            rules=["HT-R2", "HT-R3"],
            support=inst_sup,
            against=inst_against,
        )
        hyp_tr = Hypothesis(
            cause="process_transient",
            title="Operational transient (load swing / fuel transfer) driving the spread",
            score=round(min(0.95, max(0.05, tr_score)), 2),
            action="control_adjustment",
            secondary=["combustion_tuning"],
            rules=["HT-R4"],
            support=tr_sup,
            against=[] if transient else ["no load or IGV movement before the rise"],
        )
        f.hypotheses = sorted([hyp_hw, hyp_inst, hyp_tr], key=lambda h: h.score, reverse=True)
        top = f.hypotheses[0]
        if precursor_mech:
            f.review_flags.append("Vibration rose before the trip — check for a mechanical contribution.")

        f.severity = "critical" if repeat_after_restart else "high"
        if top.cause == "combustion_hardware":
            f.escalate = True
            f.urgency = "before_restart" if restart_i is None else ("immediate" if repeat_after_restart else "prompt")
            f.site_checks += [
                "Confirm the first-out and SOE: HETS / exhaust spread protection, not flameout, overspeed or vibration.",
                "Prove the exhaust TCs in the hot and cold zones (loop check) so the imbalance is not instrumentation.",
                "Map the hot/cold zones through the swirl chart to the combustor cans; borescope those cans (fuel nozzles, liners, transition pieces, crossfire tubes).",
                "Review fuel nozzle / manifold pressures and gas valve positions for the pre-trip hours.",
            ]
            if restart_i is None:
                f.operating_guidance.append("Engineering hold: restart only after the borescope result and SME agreement; then a monitored restart with a tightened spread watch.")
            else:
                f.operating_guidance.append(
                    f"Unit was restarted at {case.time_at(restart_i)}; spread after restart {fmt(post_spread, 1, 'C')}. "
                    + ("Spread is back high — reduce load / remove from service per procedure." if repeat_after_restart else "Keep a tight spread watch and schedule the borescope at the earliest opportunity.")
                )
                f.operating_guidance.append(
                    "The restart was made before any inspection: the combustion SME should confirm that continued operation "
                    "is acceptable until the borescope, and set a spread limit at which the unit is removed from service."
                )
        elif top.cause == "instrumentation":
            f.urgency = "before_restart" if restart_i is None else "prompt"
            f.site_checks += [
                "Loop-check the deviating zone TCs (resistance, insulation, junction box); replace failed elements.",
                "Confirm the controller TC rejection logic handled the bad TC as designed.",
            ]
            f.operating_guidance.append("Restart after the TC is proven/replaced; monitored restart with spread watch.")
        else:
            f.urgency = "prompt"
            f.site_checks += ["Review the load / fuel transfer sequence and control response before the trip."]

        f.timeline = [
            (case.time_at(base_lo), f"Normal spread ~{base_spread:.1f} C"),
            (case.time_at(rise_start), "Spread starts to build"),
            (case.time_at(peak_i), f"Peak spread {peak_spread:.1f} C{' (at the trip)' if peak_i == ts else ''}" + (f"; hot {', '.join(hot)} / cold {', '.join(cold)}" if hot or cold else "")),
            (case.time_at(ts), f"Trip ({how}); load and fuel collapse"),
        ]
        if restart_i is not None:
            f.timeline.append((case.time_at(restart_i), f"Back at load; spread {fmt(post_spread, 1, 'C')}"))

        pattern = "opposing hot/cold zones" if opposing else ("single-zone deviation" if single_zone else "no clear zone pattern")
        f.summary = (
            f"Trip at {case.time_at(ts)} after spread built from {base_spread:.1f} to {peak_spread:.1f} C over "
            f"{hours_text(rise_min / 60)} ({'step' if step else 'gradual'}), {pattern}; "
            + (f"restarted {case.time_at(restart_i)}, post-restart spread {fmt(post_spread, 1, 'C')}." if restart_i is not None else "not restarted in data.")
        )
        f.what_happened = (
            f"The unit tripped at {case.time_at(ts)} ({how}). Over the preceding {hours_text(rise_min / 60)} the exhaust "
            f"spread rose from a normal {base_spread:.1f} C to {peak_spread:.1f} C ({rate:.1f} C/h) while load stayed "
            f"{'steady' if not transient else 'unsteady'}"
            + (f"; at the peak {', '.join(hot)} ran hot and {', '.join(cold)} ran cold" if hot and cold else "")
            + ". Load, fuel and IGV collapsed at the trip"
            + (f", with vibration {fmt(vib_trip, 1)} mm/s and dynamics {fmt(dyn_trip, 2)} psi as a consequence of the trip transient" if vib_col and dyn_col else "")
            + ". "
            + (f"The unit was back at load at {case.time_at(restart_i)} with spread {fmt(post_spread, 1, 'C')}." if restart_i is not None else "The unit had not returned to load by the end of the data.")
        )
        f.why = (
            f"Most likely cause: {top.title} (rule support {top.score:.2f}). "
            + ("; ".join(top.support) + ". " if top.support else "")
            + (f"Alternative considered: {f.hypotheses[1].title} ({f.hypotheses[1].score:.2f}) — " + "; ".join(f.hypotheses[1].against) + "." if f.hypotheses[1].against else "")
        )
        f.strength = top.score
        f.chart = {"channels": [c for c in [spread_col] if c] + (hot[:1] + cold[:1] if hot or cold else list(zones[:2])) + ([load_col] if load_col else []), "event": [rise_start, te], "focus": [max(0, rise_start - case.samples(12 * 60)), min(case.n - 1, te + case.samples(30 * 60))]}
        if probe:
            f.review_flags = []
        return f
