# sentinel.analytics.generic
# Fallback when the analytic name matches no dedicated rule set. It still reports evidence and asks for a human.
# =============================================================================
# <<<<<<< SECTION sentinel.analytics.generic sentinel/analytics/generic.py
if False:  # compiled by exec_section('sentinel.analytics.generic'); not executed as part of this module
    """Generic analysis for analytics Sentinel does not know.

    Runs the anomaly scan and every known signature probe. A tentative action is offered only if a
    known signature is clearly present; the case is always flagged for human review.
    """

    # @@future@@ from __future__ import annotations

    from typing import Any, Dict, Optional

    from ..data import CaseData
    from ..notes import NotesInfo
    from .base import Findings, Hypothesis

    VERSION = "generic/1.0"


    def analyze(
        case: CaseData,
        notes: NotesInfo,
        entered: str = "",
        anomaly: Optional[Dict[str, Any]] = None,
        best: Optional[Findings] = None,
    ) -> Findings:
        """Function analyze."""
        f = Findings(analytic="generic", analyzer_version=VERSION, detected=False, summary="")
        f.review_flags.append(f"Analytic '{entered}' is not one Sentinel has rules for — generic analysis only; engineer must confirm.")
        z = (anomaly or {}).get("zscore", {}).get("channels", [])
        top = z[:6]
        for d in top:
            f.add(f"Anomalous channel {d['channel']}", f"max |z| {d['max_z']} for {d['minutes']} min ({d['first']} -> {d['last']})", "GEN-Z")
        if best is not None:
            # Borrow the matching signature's findings, but keep it tentative
            f.detected = True
            f.events = best.events
            f.signature = dict(best.signature, matched_signature=best.analytic)
            f.evidence = best.evidence + f.evidence
            f.timeline = best.timeline
            f.explained_channels = best.explained_channels
            f.site_checks = best.site_checks
            f.operating_guidance = best.operating_guidance
            f.chart = best.chart
            f.severity, f.urgency, f.escalate = best.severity, best.urgency, best.escalate
            tops = best.hypotheses
            f.hypotheses = [
                Hypothesis(
                    cause=h.cause,
                    title=h.title,
                    score=round(h.score * 0.6, 2),
                    action=h.action,
                    secondary=h.secondary,
                    rules=["GEN-P"] + h.rules,
                    support=[f"data matches the '{best.analytic}' signature"] + h.support,
                    against=h.against + ["analytic name not recognised — signature match is indirect"],
                )
                for h in tops
            ]
            f.summary = f"Unrecognised analytic '{entered}'. Data matches the {best.analytic} signature: {best.summary}"
            f.what_happened = best.what_happened
            f.why = (
                f"The analytic name '{entered}' is not in Sentinel's rule set, so the {best.analytic} rules were applied "
                f"because the data matches that signature. {best.why}"
            )
            f.strength = best.strength * 0.6
            return f

        if top:
            f.detected = True
            names = ", ".join(d["channel"] for d in top[:4])
            f.summary = f"Unrecognised analytic '{entered}'. No known signature matched; anomalies in {names}."
            f.hypotheses.append(
                Hypothesis(
                    cause="unknown",
                    title="Unrecognised pattern — needs engineering review",
                    score=0.4,
                    action="escalate",
                    rules=["GEN-Z"],
                    support=[f"sustained anomalies (|z| > threshold) in {names}"],
                    against=["no rule set for this analytic"],
                )
            )
            f.what_happened = (
                "Sentinel has no rules for this analytic. The anomaly scan found sustained deviations in "
                + "; ".join(f"{d['channel']} (|z| up to {d['max_z']}, {d['minutes']} min from {d['first']})" for d in top[:4])
                + "."
            )
            f.why = "The cause cannot be attributed with the available rules; the pattern is escalated for engineering review."
            f.severity, f.urgency, f.escalate = "medium", "prompt", True
            f.chart = {"channels": [d["channel"] for d in top[:3]], "event": top[0]["windows"][0] if top[0]["windows"] else None}
            f.strength = 0.3
            return f

        f.summary = f"Unrecognised analytic '{entered}'. No known signature and no sustained anomalies in the data."
        f.hypotheses.append(
            Hypothesis(
                cause="not_confirmed",
                title="No abnormal behaviour found in the supplied data",
                score=0.35,
                action="monitor_only",
                rules=["GEN-Z"],
                support=["no channel exceeded the anomaly threshold for 30 min"],
                against=["analytic is unknown; the relevant signal may be missing from the export"],
            )
        )
        f.what_happened = f.summary
        f.why = "Nothing abnormal was found, but without rules for this analytic the absence of evidence is weak."
        f.severity, f.urgency = "low", "routine"
        f.chart = {"channels": [], "event": None}
        return f
