# =============================================================================
# sentinel.anomaly
# Rule-path anomaly scan: robust z always, TS Pulse reconstruction when that snapshot loads.
# =============================================================================
# <<<<<<< SECTION sentinel.anomaly sentinel/anomaly.py
if False:  # compiled by exec_section('sentinel.anomaly'); not executed as part of this module
    """Generic anomaly scan: robust z-score (always) + TS Pulse reconstruction error (optional).

    This layer never decides the action. It (1) corroborates the analyzer's event window and
    (2) finds anomalies in channels the analytic does not explain (novel pattern -> review).
    """

    # @@future@@ from __future__ import annotations

    import logging
    import os
    from pathlib import Path
    from typing import Any, Dict, List, Optional, Sequence

    import numpy as np

    from .analytics.base import robust_stats, rolling_median, runs, steady_mask
    from .data import CaseData
    from .limits import GENERAL

    log = logging.getLogger(__name__)

    _TSPULSE_CACHE: Dict[str, Any] = {}
    TSPULSE_CONTEXT = 512
    TSPULSE_STRIDE = 64
    TSPULSE_MAX_CHANNELS = 10


    def zscore_scan(case: CaseData) -> Dict[str, Any]:
        """Function zscore_scan."""
        steady = steady_mask(case)
        skip = set(case.roles.get("trip", []))
        sustain = case.samples(30)
        out: List[Dict[str, Any]] = []
        for col in case.numeric_columns:
            if col in skip:
                continue
            x = case.series(col)
            ref = x[steady] if steady.sum() > 20 else x
            if np.sum(np.isfinite(ref)) < 20:
                continue
            med, sig = robust_stats(ref)
            z = (x - med) / sig
            zs = np.where(steady, rolling_median(np.abs(z), sustain), 0.0)
            flagged = runs(np.nan_to_num(zs) > GENERAL["anomaly_z"], min_len=sustain, max_gap=case.samples(15))
            if not flagged:
                continue
            out.append(
                {
                    "channel": col,
                    "max_z": round(float(np.nanmax(zs)), 1),
                    "minutes": round(sum(b - a + 1 for a, b in flagged) * case.minutes_per_sample),
                    "first": case.time_at(flagged[0][0]),
                    "last": case.time_at(flagged[-1][1]),
                    "windows": [[int(a), int(b)] for a, b in flagged[:20]],
                }
            )
        out.sort(key=lambda d: d["max_z"], reverse=True)
        return {"engine": "robust_zscore", "threshold_z": GENERAL["anomaly_z"], "channels": out}


    # --------------------------------------------------------------------------- TS Pulse


    def _find_tspulse_dir(root: Optional[Path]) -> Optional[Path]:
        """Function _find_tspulse_dir."""
        if not root or not Path(root).exists():
            return None
        root = Path(root)
        cands = [p.parent for p in root.rglob("config.json") if (p.parent / "model.safetensors").is_file()]
        if not cands:
            return None
        # Prefer the anomaly-detection snapshot (main = hybrid-allhead) over the classifier one
        cands.sort(key=lambda p: (0 if "ad" in p.name.lower() or "main" in p.name.lower() else 1, str(p)))
        return cands[0]


    def load_tspulse(root: Optional[Path]) -> Optional[Any]:
        """Load TS Pulse from a local folder only (offline). Returns None if unavailable."""
        path = _find_tspulse_dir(root)
        if path is None:
            return None
        key = str(path)
        if key in _TSPULSE_CACHE:
            return _TSPULSE_CACHE[key]
        try:
            os.environ.setdefault("HF_HUB_OFFLINE", "1")
            os.environ.setdefault("TRANSFORMERS_OFFLINE", "1")
            os.environ.setdefault("HF_HUB_DISABLE_PROGRESS_BARS", "1")
            import torch  # noqa: F401
            from tsfm_public.models.tspulse import TSPulseForReconstruction
            import transformers

            transformers.logging.set_verbosity_error()
            transformers.logging.disable_progress_bar()
            model = TSPulseForReconstruction.from_pretrained(str(path), num_input_channels=1, mask_type="user")
            model.eval()
            model._sentinel_path = key  # type: ignore[attr-defined]
            _TSPULSE_CACHE[key] = model
            return model
        except Exception as exc:  # noqa: BLE001
            log.warning("TS Pulse unavailable: %s", exc)
            _TSPULSE_CACHE[key] = None
            return None


    def _tspulse_point_scores(model: Any, x: np.ndarray) -> np.ndarray:
        """Pointwise masked-reconstruction error for one standardized series (NaN where unscored)."""
        import torch
        from tsfm_public.models.tspulse.utils.helpers import patchwise_stitched_reconstruction

        n = len(x)
        L, S = TSPULSE_CONTEXT, TSPULSE_STRIDE
        starts = list(range(0, n - L + 1, S))
        if starts and starts[-1] != n - L:
            starts.append(n - L)
        scores = np.full(n, np.nan)
        patch = int(model.config.patch_length)
        batch = 32
        with torch.no_grad():
            for i in range(0, len(starts), batch):
                chunk = starts[i : i + batch]
                xb = torch.tensor(np.stack([x[s : s + L] for s in chunk]), dtype=torch.float32).unsqueeze(-1)
                res = patchwise_stitched_reconstruction(
                    model=model,
                    past_values=xb,
                    patch_size=patch,
                    keys_to_stitch=["reconstruction_outputs", "reconstructed_ts_from_fft"],
                    keys_to_aggregate=[],
                    reconstruct_start=L - S,
                    reconstruct_end=L,
                )
                if isinstance(res, tuple):
                    res = res[0]
                e_t = (res["reconstruction_outputs"] - xb) ** 2
                e_f = (res["reconstructed_ts_from_fft"] - xb) ** 2
                err = torch.maximum(e_t, e_f)[:, L - S :, 0].numpy()
                for s, e in zip(chunk, err):
                    scores[s + L - S : s + L] = e
        return scores


    def tspulse_scan(case: CaseData, model: Any, channels: Sequence[str]) -> Dict[str, Any]:
        """Function tspulse_scan."""
        import torch

        torch.manual_seed(0)
        torch.set_num_threads(max(1, min(8, (os.cpu_count() or 4) // 2)))
        steady = steady_mask(case)
        out: List[Dict[str, Any]] = []
        for col in list(channels)[:TSPULSE_MAX_CHANNELS]:
            x = case.series(col)
            if np.sum(np.isfinite(x)) < TSPULSE_CONTEXT * 2:
                continue
            x = np.where(np.isfinite(x), x, np.nanmedian(x))
            sd = float(np.std(x)) or 1.0
            xs = (x - float(np.mean(x))) / sd
            s = _tspulse_point_scores(model, xs)
            s = rolling_median(s, 8)
            logs = np.log10(np.where(np.isfinite(s), s, np.nan) + 1e-6)
            med, sig = robust_stats(logs[np.isfinite(logs)])
            z = (logs - med) / sig
            flagged = runs(np.nan_to_num(z) > 5.0, min_len=3, max_gap=case.samples(30))
            flagged = [(a, b) for a, b in flagged if steady[a : b + 1].any()]
            if not flagged:
                continue
            out.append(
                {
                    "channel": col,
                    "max_z": round(float(np.nanmax(z)), 1),
                    "windows": [[int(a), int(b)] for a, b in flagged[:20]],
                    "first": case.time_at(flagged[0][0]),
                    "last": case.time_at(flagged[-1][1]),
                }
            )
        out.sort(key=lambda d: d["max_z"], reverse=True)
        return {
            "engine": "TS Pulse (ibm-granite/granite-timeseries-tspulse-r1, zero-shot masked reconstruction)",
            "model_path": getattr(model, "_sentinel_path", ""),
            "channels": out,
            "scored_channels": list(channels)[:TSPULSE_MAX_CHANNELS],
        }


    def key_channels(case: CaseData) -> List[str]:
        """Function key_channels."""
        order = ["spread", "dynamics", "egt_avg", "load", "fuel", "igv", "vibration", "cdp", "cdt", "lube_oil"]
        out: List[str] = []
        for role in order:
            for c in case.roles.get(role, [])[:2]:
                if c not in out:
                    out.append(c)
        return out


    def scan(case: CaseData, tspulse_root: Optional[Path] = None, use_tspulse: bool = True) -> Dict[str, Any]:
        """Function scan."""
        result: Dict[str, Any] = {"zscore": zscore_scan(case), "tspulse": None, "tspulse_status": "disabled"}
        if not use_tspulse:
            return result
        if case.n < TSPULSE_CONTEXT * 2:
            result["tspulse_status"] = f"skipped: {case.n} rows < {TSPULSE_CONTEXT * 2} needed"
            return result
        model = load_tspulse(tspulse_root)
        if model is None:
            result["tspulse_status"] = "unavailable (torch / granite-tsfm / local weights not found) — z-score only"
            return result
        try:
            result["tspulse"] = tspulse_scan(case, model, key_channels(case))
            result["tspulse_status"] = "ok"
        except Exception as exc:  # noqa: BLE001
            log.warning("TS Pulse scan failed: %s", exc)
            result["tspulse_status"] = f"failed: {exc} — z-score only"
        return result


    def overlaps(windows: List[List[int]], a: int, b: int, pad: int) -> bool:
        """Function overlaps."""
        return any(w[0] <= b + pad and w[1] >= a - pad for w in windows)
# >>>>>>> END sentinel.anomaly

