    """Report assembly (JSON) and rendering (Markdown site report)."""

    # @@future@@ from __future__ import annotations

    from typing import Any, Dict, List

    from . import APP_NAME, __version__
    from .analytics.base import ACTIONS, URGENCY
    from .rules import RULES

    DISCLAIMER = (
        "Engineering decision support generated locally by Sentinel GT AI. Not an OEM-certified procedure "
        "or a protection system. Site procedures and OEM limits take precedence. Draft until reviewed by a "
        "Tier 2 engineer."
    )


    def template_narrative(findings: Dict[str, Any], decision: Dict[str, Any]) -> Dict[str, Any]:
        """Deterministic narrative built only from findings and decision (offline path)."""
        top = (findings.get("hypotheses") or [{}])[0]
        support = top.get("support") or []
        action = ACTIONS.get(decision["primary_action"], decision["primary_action"])
        rationale = f"{action} is recommended because " + (
            "; ".join(support[:3]) if support else "the rules found no stronger alternative"
        ) + "."
        if decision.get("rule_action") != decision["primary_action"]:
            rationale += (
                f" The rules alone would recommend {ACTIONS.get(decision['rule_action'], decision['rule_action'])}; "
                "the action follows engineer feedback on a similar reviewed case."
            )
        if decision.get("secondary_actions"):
            rationale += " Supporting actions: " + ", ".join(ACTIONS[a].split(" (")[0] for a in decision["secondary_actions"]) + "."
        return {
            "engine": "template",
            "what_happened": findings.get("what_happened") or findings.get("summary", ""),
            "why": findings.get("why", ""),
            "action_rationale": rationale,
            "site_instructions": list(findings.get("site_checks") or []),
            "supports_action": None,
            "concerns": "",
            "checks": {},
        }


    def bottom_line(report: Dict[str, Any]) -> str:
        """Function bottom_line."""
        d = report["decision"]
        f = report["findings"]
        act = ACTIONS.get(d["primary_action"], d["primary_action"]).split(" (")[0]
        esc = " Escalate to engineering." if d["escalate"] and d["primary_action"] != "escalate" else ""
        return (
            f"{f['summary']} Recommended: {act} — {URGENCY.get(d['urgency'], d['urgency']).split(' — ')[0].lower()}."
            f"{esc} Confidence {d['confidence']:.2f} ({d['confidence_label']})."
        )


    def _status_banner(review: Dict[str, Any]) -> str:
        """Function _status_banner."""
        st = review.get("status", "DRAFT")
        fb = review.get("feedback") or {}
        if st == "APPROVED":
            return f"> **APPROVED** by {fb.get('reviewer')} on {fb.get('time')} — engineer marked this report Good."
        if st == "REJECTED":
            corr = fb.get("corrected_action")
            corr_txt = f" Engineer's corrected action: **{ACTIONS.get(corr, corr)}**." if corr else ""
            return f"> **REJECTED** by {fb.get('reviewer')} on {fb.get('time')} — engineer marked this report Not good.{corr_txt}"
        return "> **DRAFT — pending Tier 2 engineer review.** Not for release to site until marked Good."


    def _yn(b: bool) -> str:
        """Function _yn."""
        return "Yes" if b else "No"


    def _esc(s: Any) -> str:
        """Function _esc."""
        return str(s).replace("|", "/").replace("\n", " ")


    def render_markdown(r: Dict[str, Any]) -> str:
        """Function render_markdown."""
        d, f, n, inp = r["decision"], r["findings"], r["narrative"], r["input"]
        out: List[str] = []
        w = out.append
        w(f"# Tier 2 Site Report — {r['analytic']['title']}")
        w("")
        w(_status_banner(r["review"]))
        w("")
        w("| Case | Unit | Analytic (entered → resolved) | Data window | Generated |")
        w("|---|---|---|---|---|")
        w(
            f"| {r['case_id']} | {_esc(r['case'].get('unit') or 'not stated')} | {_esc(r['analytic']['entered'])} → "
            f"`{r['analytic']['resolved']}` | {inp['start']} → {inp['end']} ({inp['rows']} rows, "
            f"{inp['interval_minutes'] or '?'} min) | {r['created']} |"
        )
        w("")
        w("## 1. Summary")
        w("")
        w(f"**Bottom line:** {r['bottom_line']}")
        w("")
        w(f"- **Recommended action:** {ACTIONS.get(d['primary_action'], d['primary_action'])}")
        w(f"- **Urgency:** {URGENCY.get(d['urgency'], d['urgency'])}")
        w(f"- **Severity:** {d['severity'].capitalize()} · **Confidence:** {d['confidence']:.2f} ({d['confidence_label']}) · "
          f"**Escalate:** {_yn(d['escalate'])} · **Needs extra human scrutiny:** {_yn(d['needs_human'])}")
        w(f"- **Most likely cause:** {d['hypothesis']} *({d['cause_title']})*")
        w("")
        w("## 2. Recommended corrective action")
        w("")
        w(f"**Primary:** {ACTIONS.get(d['primary_action'], d['primary_action'])} — {URGENCY.get(d['urgency'], d['urgency'])}.")
        w("")
        if d["secondary_actions"]:
            w("**Secondary / supporting:** " + "; ".join(ACTIONS.get(a, a) for a in d["secondary_actions"]) + ".")
            w("")
        w(f"**Rationale:** {n.get('action_rationale', '')}")
        w("")
        instr = n.get("site_instructions") or f.get("site_checks") or []
        if instr:
            w("**Site instructions:**")
            w("")
            for i, s in enumerate(instr, 1):
                w(f"{i}. {s}")
            w("")
        if f.get("operating_guidance"):
            w("**Operating guidance:**")
            w("")
            for s in f["operating_guidance"]:
                w(f"- {s}")
            w("")
        w(f"**Escalation:** {'Yes — notify the combustion / engineering SME with this report.' if d['escalate'] else 'Not required on current evidence.'}")
        w("")
        w("## 3. What happened")
        w("")
        w(n.get("what_happened", ""))
        w("")
        if f.get("timeline"):
            w("| Time | Event |")
            w("|---|---|")
            for t, e in f["timeline"]:
                w(f"| {t} | {_esc(e)} |")
            w("")
        w("## 4. Why — engineering assessment")
        w("")
        w(n.get("why", ""))
        w("")
        if d.get("alternatives"):
            w("**Alternatives considered:**")
            w("")
            for a in d["alternatives"]:
                w(f"- {a['title']} → {ACTIONS.get(a['action'], a['action']).split(' (')[0]} (rule support {a['score']:.2f}). Not preferred: {a['why_not']}.")
            w("")
        w("## 5. Evidence")
        w("")
        w("| # | Finding | Value | Source |")
        w("|---|---|---|---|")
        for i, e in enumerate(f.get("evidence", []), 1):
            detail = f" ({e['detail']})" if e.get("detail") else ""
            w(f"| {i} | {_esc(e['label'])} | {_esc(e['value'])}{_esc(detail)} | {e['source']} |")
        an = r["anomaly"]
        zch = an["zscore"]["channels"][:5]
        if zch:
            w(f"| {len(f.get('evidence', [])) + 1} | Anomaly scan (robust z) | " + _esc("; ".join(f"{c['channel']} |z|≤{c['max_z']} {c['minutes']} min" for c in zch)) + " | GEN-Z |")
        tsp = (an.get("tspulse") or {}).get("channels", [])[:4]
        if tsp:
            w(f"| {len(f.get('evidence', [])) + 2} | TS Pulse reconstruction anomalies | " + _esc("; ".join(f"{c['channel']} {c['first']}→{c['last']}" for c in tsp)) + " | AN-TSP |")
        w("")
        w("## 6. Confidence and uncertainty")
        w("")
        w(f"**Confidence {d['confidence']:.2f} ({d['confidence_label']}).** Itemised:")
        w("")
        w("| Factor | Effect |")
        w("|---|---|")
        for i, (txt, val) in enumerate(d["confidence_factors"]):
            w(f"| {_esc(txt)} | {'base ' if i == 0 else ''}{val:+.2f} |")
        w("")
        if d["review_flags"]:
            w("**Review flags (why extra scrutiny is needed):**")
            w("")
            for fl in d["review_flags"]:
                w(f"- ⚠ {fl}")
            w("")
        gaps = list(f.get("data_gaps") or []) + list(inp["quality"].get("issues") or [])
        if gaps:
            w("**Data gaps / limitations:**")
            w("")
            for g in gaps:
                w(f"- {g}")
            w("")
        if n.get("concerns"):
            label = "LLM disagreement" if n.get("supports_action") is False else "LLM note"
            w(f"**{label}:** {n['concerns']}")
            w("")
        w("## 7. Similar past cases (engineer feedback)")
        w("")
        sims = r.get("similar_cases") or []
        if not sims:
            w("No reviewed similar cases yet. Feedback on this report will be used for future cases.")
        else:
            w("| Case | Similarity | Verdict | Action in report | Engineer correction | Reason |")
            w("|---|---|---|---|---|---|")
            for s in sims:
                w(f"| {s['case_id']} | {s['similarity']:.2f} | {s['verdict']} | {s.get('primary_action')} | {s.get('corrected_action') or '—'} | {_esc(s.get('reason') or '—')} |")
            for e in d.get("feedback_effects", []):
                w(f"\n*Applied:* {e['effect']} (case {e['case_id']}, similarity {e['similarity']:.2f}).")
        w("")
        w("## 8. Audit trail")
        w("")
        au = r["audit"]
        # The rule path does not run the learned model; its generic fallback is the generic analyzer
        # plus process knowledge. Only the learned-path report may name the learned model.
        path = au.get("analyzer_path") or (
            "built-in analyzer" if r["analytic"].get("known") else
            "generic fallback (no built-in analyzer; generic analyzer + process knowledge)"
        )
        w(f"- **Analyzer:** `{f['analyzer_version']}` — analytic resolved by: {r['analytic']['reason']}. Path: **{path}**.")
        w(f"- **Frame:** `{r['case'].get('frame_type') or 'auto'}`.")
        w("- **Rules fired:** " + "; ".join(f"`{rid}` {RULES.get(rid, '')}" for rid in d["rules_fired"]))
        w(f"- **Thresholds:** `{au['thresholds']}`")
        w(f"- **Anomaly engines:** robust z-score (|z| > {an['zscore']['threshold_z']}, ≥ 30 min); TS Pulse: {an['tspulse_status']}.")
        w(f"- **Narrative:** {au['narrative_engine']}")
        if n.get("checks"):
            w("- **LLM output checks:** " + "; ".join(f"{k}: {v}" for k, v in n["checks"].items()))
        if r.get("knowledge"):
            w("- **Knowledge used:** " + "; ".join(k["ref"] for k in r["knowledge"]))
        w(f"- **Input:** `{inp['source_name']}` SHA-256 `{inp['sha256'][:16]}…`, {inp['rows']} rows × {inp['columns']} channels.")
        w(f"- **Notes interpreted:** {', '.join(r['case'].get('notes_interpreted') or []) or 'none'}")
        if r.get("cross_check"):
            w("- **Other signatures probed:** " + "; ".join(f"{k}: {v}" for k, v in r["cross_check"].items()))
        w(f"- **App:** {APP_NAME} {__version__}; fully local, no network calls; elapsed {au.get('elapsed_s', '?')} s.")
        w("")
        w("## 9. Engineer review")
        w("")
        fb = r["review"].get("feedback")
        if not fb:
            w(f"Status: **{r['review']['status']}**. Mark Good / Not good in the UI, or "
              f"`python app.py feedback --case {r['case_id']} --verdict good|not_good [--reason ...] [--corrected-action ...]`.")
        else:
            w(f"- Status: **{r['review']['status']}**")
            w(f"- Verdict: **{fb['verdict'].replace('_', ' ')}** by {fb['reviewer']} at {fb['time']}")
            if fb.get("reason"):
                w(f"- Reason: {fb['reason']}")
            if fb.get("corrected_action"):
                w(f"- Corrected action: **{ACTIONS.get(fb['corrected_action'], fb['corrected_action'])}**")
        if r["case"].get("notes"):
            w("")
            w("**Notes supplied with the case:**")
            w("")
            w("> " + r["case"]["notes"].replace("\n", "\n> "))
        w("")
        w("---")
        w(f"*{DISCLAIMER}*")
        w("")
        return "\n".join(out)
