# =============================================================================
# sentinel.e2e.encoder
# TS Pulse fine-tune and embed. device auto|gpu|cpu, and a CPU retry when the GPU runs out of memory.
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.encoder sentinel/e2e/encoder.py
if False:  # compiled by exec_section('sentinel.e2e.encoder'); not executed as part of this module
    """TS Pulse encoder for the learned path.

    Base weights: IBM ``granite-timeseries-tspulse-r1`` revision ``tspulse-block-dualhead-512-p16-r1``
    (the variant IBM recommends for classification), loaded from ``models/tspulse/clf`` (offline).
    ``finetune`` trains the whole model (backbone + mix-channel decoder + classification head) on the
    canonical windows; the fine-tuned model is saved to ``models/e2e/encoder``.

    Embedding = the decoder's semantic register tokens (TS Pulse's summary tokens), averaged and
    concatenated over channels. The same vector feeds the light classifier head and the similarity
    index, so one-shot retrieval and the classifier see the same representation.
    """

    # @@future@@ from __future__ import annotations

    import json
    import logging
    import os
    import time
    from pathlib import Path
    from typing import Any, Callable, Dict, List, Optional, Sequence

    import numpy as np

    from .features import CHANNELS, WINDOW

    log = logging.getLogger(__name__)
    _CACHE: Dict[str, "Encoder"] = {}
    # One loaded channel-independent encoder per weight folder. A failed load is not cached.
    _CI_CACHE: Dict[str, Any] = {}
    # Last measured channel-window rate. doctor prints it; a run with no embed leaves this empty.
    LAST_EMBED_RATE: Dict[str, Any] = {}


    def _offline_env() -> None:
        """Function _offline_env."""
        os.environ.setdefault("HF_HUB_OFFLINE", "1")
        os.environ.setdefault("TRANSFORMERS_OFFLINE", "1")
        os.environ.setdefault("HF_HUB_DISABLE_PROGRESS_BARS", "1")
        os.environ.setdefault("HF_HUB_DISABLE_TELEMETRY", "1")


    def _threads() -> int:
        """Function _threads."""
        return max(1, min(8, (os.cpu_count() or 4) // 2))


    def model_kwargs(n_channels: int, n_targets: int) -> Dict[str, Any]:
        """Function model_kwargs."""
        return {
            "num_input_channels": n_channels,
            "num_targets": n_targets,
            "loss": "cross_entropy",
            "ignore_mismatched_sizes": True,
            "decoder_mode": "mix_channel",
            "head_reduce_d_model": 1,
            "head_attention": True,
            "head_gated_attention_activation": "softmax",
            "channel_mix_init": "identity",
            "disable_mask_in_classification_eval": True,
            "mask_ratio": 0.3,
            "fft_time_consistent_masking": True,
            "fuse_fft": True,
            # Inputs are already robust-z scaled per record (features.py); per-window normalisation
            # would erase the magnitudes that separate a 3 C wobble from a 30 C cold sector.
            "scaling": None,
        }


    def _quiet_transformers() -> None:
        """Function _quiet_transformers."""
        import transformers

        transformers.logging.set_verbosity_error()
        transformers.logging.disable_progress_bar()


    class Encoder:
        """Loaded TS Pulse classification model; embeds canonical windows."""

        def __init__(self, path: Path, n_targets: Optional[int] = None):
            """Function __init__."""
            _offline_env()
            import torch
            from tsfm_public.models.tspulse import TSPulseForClassification

            _quiet_transformers()
            torch.set_num_threads(_threads())
            self.path = Path(path)
            cfg = json.loads((self.path / "config.json").read_text(encoding="utf-8"))
            self.fine_tuned = cfg.get("num_input_channels") == len(CHANNELS) and (self.path / "classes.json").is_file()
            if self.fine_tuned:
                self.model = TSPulseForClassification.from_pretrained(str(self.path))
                self.classes: List[str] = json.loads((self.path / "classes.json").read_text(encoding="utf-8"))
            else:  # zero-shot base weights with an untrained head (embeddings only)
                self.model = TSPulseForClassification.from_pretrained(str(self.path), **model_kwargs(len(CHANNELS), n_targets or 2))
                self.classes = []
            self.model.eval()
            self.d_model = int(self.model.config.decoder_d_model)
            self.n_reg = int(self.model.config.patch_register_tokens or 0)

        @property
        def description(self) -> str:
            """Function description."""
            kind = "fine-tuned on labeled GT cases" if self.fine_tuned else "zero-shot base weights"
            return f"TS Pulse r1 block-dualhead-512-p16 ({kind}), {sum(p.numel() for p in self.model.parameters()) / 1e6:.2f} M params"

        def _forward(self, X: np.ndarray, batch: int = 64) -> Dict[str, np.ndarray]:
            """Function _forward."""
            import torch

            embs, logits = [], []
            with torch.no_grad():
                for i in range(0, len(X), batch):
                    xb = torch.tensor(np.asarray(X[i : i + batch], dtype=np.float32))
                    out = self.model(xb, return_loss=False)
                    h = out.decoder_hidden_state  # (B, C, P * D)
                    B, C, PD = h.shape
                    h = h.reshape(B, C, PD // self.d_model, self.d_model)
                    reg = h[:, :, -self.n_reg :, :].mean(dim=2) if self.n_reg else h.mean(dim=2)
                    embs.append(reg.reshape(B, -1).numpy())
                    logits.append(out.prediction_outputs.numpy())
            return {"emb": np.concatenate(embs) if embs else np.zeros((0, 1)), "logits": np.concatenate(logits) if logits else np.zeros((0, 1))}

        def embed(self, X: np.ndarray, batch: int = 64) -> np.ndarray:
            """Function embed."""
            return self._forward(X, batch)["emb"].astype(np.float32)

        def logits(self, X: np.ndarray, batch: int = 64) -> np.ndarray:
            """Function logits."""
            return self._forward(X, batch)["logits"]


    def load_encoder(path: Path) -> Encoder:
        """Function load_encoder."""
        key = str(Path(path).resolve())
        if key not in _CACHE:
            _CACHE[key] = Encoder(Path(path))
        return _CACHE[key]


    def resolve_train_device(prefer: str = "cpu") -> Dict[str, str]:
        """Choose ``cuda`` or ``cpu`` for a TS Pulse fine-tune.

        ``auto`` uses the GPU when CUDA actually works and the CPU otherwise.
        ``gpu`` asks for the GPU, but a machine without CUDA (or a GPU that fails
        its first allocation) still trains: the fine-tune falls back to CPU. A
        later out-of-memory error is handled by ``finetune``, which retries on CPU.
        The returned ``device`` is the torch name (``cuda`` / ``cpu``).
        """
        prefer = (prefer or "cpu").lower()
        if prefer not in ("auto", "gpu", "cpu"):
            raise ValueError(f"device must be auto, gpu or cpu (got {prefer!r})")
        if prefer == "cpu":
            return {"device": "cpu", "requested": "cpu", "reason": "CPU requested"}
        import torch

        if not torch.cuda.is_available():
            why = "CUDA is not available"
            why += "; GPU was requested, falling back to CPU" if prefer == "gpu" else "; using CPU"
            return {"device": "cpu", "requested": prefer, "reason": why}
        try:
            torch.zeros(1, device="cuda")
            name = torch.cuda.get_device_name(0)
        except Exception as exc:  # noqa: BLE001 — a dead GPU must not block training
            return {"device": "cpu", "requested": prefer, "reason": f"GPU probe failed ({type(exc).__name__}: {exc}); falling back to CPU"}
        return {"device": "cuda", "requested": prefer, "reason": f"CUDA GPU ({name})"}


    def _gpu_oom(exc: BaseException) -> bool:
        """True when a CUDA run died because the card ran out of memory."""
        msg = str(exc).lower()
        return "out of memory" in msg or ("cuda" in msg and "memory" in msg)


    def _release_cuda() -> None:
        """Drop cached GPU blocks after an out-of-memory error. A CPU-only build has nothing to drop."""
        try:
            import torch
        except Exception:  # noqa: BLE001 — torch missing is the statistical-fallback case
            return
        if getattr(torch, "cuda", None) is not None and torch.cuda.is_available():
            torch.cuda.empty_cache()


    def _call_or_cpu(device: str, model: Any, run: Callable[[str], Any]) -> tuple:
        """Call ``run(device)``. On a CUDA out-of-memory error, move ``model`` to CPU and call once more.

        ``run`` receives the device it must use, so the retry does not put another tensor on the card.
        """
        try:
            return run(device), device, ""
        except RuntimeError as exc:
            if device == "cuda" and _gpu_oom(exc):
                _release_cuda()
                model.to("cpu")
                reason = f"GPU ran out of memory ({exc}); fell back to CPU"
                return run("cpu"), "cpu", reason
            raise


    def finetune(
        base_dir: Path,
        X_tr: np.ndarray,
        y_tr: np.ndarray,
        X_va: np.ndarray,
        y_va: np.ndarray,
        classes: Sequence[str],
        out_dir: Path,
        epochs: int = 12,
        lr: float = 5e-4,
        batch: int = 32,
        seed: int = 0,
        log_fn: Callable[[str], None] = print,
        device: str = "cpu",
        progress: Optional[Callable[[float, str], None]] = None,
    ) -> Dict[str, Any]:
        """Fine-tune TS Pulse (all weights) for signature classification; keep the best val epoch.

        ``device`` is ``auto``, ``gpu`` or ``cpu`` (default CPU, which is what the
        original training script does). ``gpu`` and ``auto`` use CUDA when it works.
        If the GPU runs out of memory the run starts over on CPU — a 6 GB card often
        cannot hold this fine-tune, and the engineer should still get a model.
        ``progress(frac, message)`` is optional; ``frac`` runs from 0 to 1 over the
        attempt that finishes (a CPU retry starts the bar again near 0).
        """
        choice = resolve_train_device(device)
        plan = [choice["device"]]
        if choice["device"] == "cuda":
            plan.append("cpu")
        reason = choice["reason"]
        log_fn(f"  device: {reason}")
        if progress:
            progress(0.0, reason)
        last: Optional[BaseException] = None
        for i, dev in enumerate(plan):
            try:
                info = _finetune_on_device(
                    dev, base_dir, X_tr, y_tr, X_va, y_va, classes, out_dir,
                    epochs=epochs, lr=lr, batch=batch, seed=seed, log_fn=log_fn, progress=progress,
                )
            except RuntimeError as exc:
                last = exc
                if dev == "cuda" and i < len(plan) - 1 and _gpu_oom(exc):
                    reason = f"GPU ran out of memory ({exc}); fell back to CPU"
                    log_fn("  " + reason)
                    if progress:
                        progress(0.0, reason)
                    import torch

                    torch.cuda.empty_cache()
                    continue
                raise
            info["device"] = "gpu" if dev == "cuda" else "cpu"
            info["device_reason"] = reason
            (out_dir / "training.json").write_text(json.dumps(info, indent=2), encoding="utf-8")
            return info
        raise RuntimeError(f"fine-tune failed: {last}")


    def _finetune_on_device(
        dev: str,
        base_dir: Path,
        X_tr: np.ndarray,
        y_tr: np.ndarray,
        X_va: np.ndarray,
        y_va: np.ndarray,
        classes: Sequence[str],
        out_dir: Path,
        epochs: int,
        lr: float,
        batch: int,
        seed: int,
        log_fn: Callable[[str], None],
        progress: Optional[Callable[[float, str], None]],
    ) -> Dict[str, Any]:
        """One fine-tune attempt on ``dev`` (``cpu`` or ``cuda``). Windows stay on CPU and move per batch.

        Keeping the whole training set on the GPU is what blows a 6 GB card; the model
        is the only thing that has to live there. The best epoch is copied back to CPU
        before it is saved, so the file is usable on a machine without a GPU.
        """
        _offline_env()
        import torch
        from tsfm_public.models.tspulse import TSPulseForClassification

        _quiet_transformers()
        torch.manual_seed(seed)
        np.random.seed(seed)
        torch.set_num_threads(_threads())
        model = TSPulseForClassification.from_pretrained(str(base_dir), **model_kwargs(X_tr.shape[2], len(classes)))
        model.to(dev)
        opt = torch.optim.AdamW(model.parameters(), lr=lr, weight_decay=0.01)
        n_batches = max(1, int(np.ceil(len(X_tr) / batch)))
        steps = epochs * n_batches
        sched = torch.optim.lr_scheduler.OneCycleLR(opt, max_lr=lr, total_steps=steps, pct_start=0.15)
        Xt, yt = torch.tensor(X_tr, dtype=torch.float32), torch.tensor(y_tr, dtype=torch.long)
        Xv = torch.tensor(X_va, dtype=torch.float32)
        best: Dict[str, Any] = {"val_acc": -1.0, "epoch": -1}
        best_state = None
        history: List[Dict[str, float]] = []
        rng = np.random.default_rng(seed)
        t0 = time.monotonic()
        for ep in range(epochs):
            model.train()
            perm = rng.permutation(len(Xt))
            tot = 0.0
            for bi, i in enumerate(range(0, len(perm), batch)):
                idx = perm[i : i + batch]
                xb, yb = Xt[idx].to(dev), yt[idx].to(dev)
                out = model(xb, target_values=yb)
                opt.zero_grad()
                out.loss.backward()
                torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
                opt.step()
                sched.step()
                tot += float(out.loss.detach()) * len(idx)
                if progress and (bi % 5 == 0 or bi + 1 == n_batches):
                    frac = (ep + (bi + 1) / n_batches) / epochs
                    progress(frac, f"epoch {ep + 1}/{epochs}, batch {bi + 1}/{n_batches} on {dev}")
            model.eval()
            with torch.no_grad():
                pred = np.concatenate([
                    model(Xv[i : i + 64].to(dev), return_loss=False).prediction_outputs.argmax(-1).detach().cpu().numpy()
                    for i in range(0, len(Xv), 64)
                ])
            acc = float((pred == y_va).mean()) if len(y_va) else 0.0
            history.append({"epoch": ep + 1, "train_loss": round(tot / max(1, len(perm)), 4), "val_acc": round(acc, 4), "minutes": round((time.monotonic() - t0) / 60, 1)})
            line = f"  epoch {ep + 1}/{epochs}: train loss {tot / max(1, len(perm)):.3f}  val acc {acc:.3f}  ({(time.monotonic() - t0) / 60:.1f} min, {dev})"
            log_fn(line)
            if progress:
                progress((ep + 1) / epochs, line.strip())
            if acc > best["val_acc"]:
                best = {"val_acc": acc, "epoch": ep + 1}
                best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
        if best_state is not None:
            model.to("cpu")
            model.load_state_dict(best_state)
        out_dir = Path(out_dir)
        out_dir.mkdir(parents=True, exist_ok=True)
        model.save_pretrained(str(out_dir))
        (out_dir / "classes.json").write_text(json.dumps(list(classes)), encoding="utf-8")
        info = {"best": best, "history": history, "classes": list(classes), "channels": CHANNELS, "window": WINDOW, "base": str(base_dir)}
        _CACHE.pop(str(out_dir.resolve()), None)
        return info


    def _view_stats(view: np.ndarray) -> np.ndarray:
        """24 numbers for one view of one channel.

        The design lists 23. The 24th is the root-mean-square, so two views are 48
        and the vector lines up with a TS Pulse register embedding.
        """
        x = np.nan_to_num(np.asarray(view, dtype=float).reshape(-1))
        if x.size == 0:
            return np.zeros(24, dtype=np.float64)
        n = float(x.size)
        quantiles = np.quantile(x, [0.1, 0.25, 0.5, 0.75, 0.9])
        diff = np.diff(x) if x.size > 1 else np.array([0.0])
        longest = run = 0
        for flag in x > 2.0:
            run = run + 1 if flag else 0
            if run > longest:
                longest = run
        signs = np.sign(x)
        signs = signs[signs != 0]
        zero_cross = float(np.mean(signs[1:] * signs[:-1] < 0)) if signs.size > 1 else 0.0
        if x.size > 2 and float(np.std(x)) > 1e-12:
            lag1 = float(np.corrcoef(x[:-1], x[1:])[0, 1])
            lag1 = 0.0 if not np.isfinite(lag1) else lag1
        else:
            lag1 = 0.0
        slope = float(np.polyfit(np.linspace(0.0, 1.0, x.size), x, 1)[0]) if x.size > 1 else 0.0
        spectrum = np.abs(np.fft.rfft(x - float(np.mean(x))))
        spectrum = spectrum[1:] if spectrum.size > 1 else spectrum
        bands = list(np.array_split(spectrum, 6)) if spectrum.size else []
        while len(bands) < 6:
            bands.append(np.zeros(1))
        fft = np.array([float(np.mean(band)) if len(band) else 0.0 for band in bands[:6]], dtype=np.float64) / n
        out = np.array(
            [
                float(np.mean(x)),
                float(np.std(x)),
                *[float(q) for q in quantiles],
                float(x[-1] - x[0]),
                float(np.max(np.abs(diff))),
                float(np.argmax(x) / n),
                float(np.argmin(x) / n),
                float(np.mean(x > 2.0)),
                float(np.mean(x > 4.0)),
                float(longest / n),
                zero_cross,
                lag1,
                slope,
                float(np.sqrt(np.mean(x * x))),
                *[float(v) for v in fft],
            ],
            dtype=np.float64,
        )
        return np.nan_to_num(out)


    class StatsEmbedder:
        """48-d per channel from the two views. No torch, no weights, same layout as the channel-independent encoder."""

        name = "stats"
        dim = 48
        fallback = False
        fallback_reason = ""

        def embed_channels(self, x: np.ndarray, mask: Optional[np.ndarray] = None) -> np.ndarray:
            """``(512, C)`` -> ``(C, 48)``, or ``(N, 512, C)`` -> ``(N, C, 48)``.

            A masked channel is zeros. It is not the portrait of a flat measured tag.
            """
            arr = np.asarray(x, dtype=np.float32)
            single = arr.ndim == 2
            if single:
                arr = arr[None, ...]
            if arr.ndim != 3:
                raise ValueError(f"expected (512, C) or (N, 512, C), got {getattr(x, 'shape', None)}")
            rows, length, channels = arr.shape
            if mask is None:
                use = np.ones((rows, channels), dtype=bool)
            else:
                use = np.asarray(mask, dtype=bool)
                if use.ndim == 1:
                    use = np.broadcast_to(use, (rows, channels))
            out = np.zeros((rows, channels, self.dim), dtype=np.float32)
            half = max(1, length // 2)
            for row in range(rows):
                for channel in range(channels):
                    if not use[row, channel]:
                        continue
                    whole = _view_stats(arr[row, :half, channel])
                    zoom = _view_stats(arr[row, half:, channel])
                    out[row, channel] = np.concatenate([whole, zoom])
            return out[0] if single else out


    def ci_model_kwargs() -> Dict[str, Any]:
        """Load the base TS Pulse as one channel, with no channel mixing and no second scaler.

        ``model_kwargs`` stays ``mix_channel`` for the 14-channel fine-tune. This load is the
        other one: the checkpoint in ``models/tspulse/clf`` is already ``common_channel`` and
        one input channel, so the same weights score a profile of 4 channels or of 40.
        ``scaling`` is off because ``profile_windows`` already robust-z scales each record.
        Eval masking is off so two embeds of the same window match.
        """
        return {
            "num_input_channels": 1,
            "mode": "common_channel",
            "decoder_mode": "common_channel",
            "scaling": None,
            # A size mismatch is re-initialised unless the loading-info check below refuses it.
            # The check is what keeps a backbone key from being silently replaced with random weights.
            "ignore_mismatched_sizes": True,
            "disable_mask_in_classification_eval": True,
        }


    def _embedding_key(name: str) -> bool:
        """True for a backbone or decoder weight on the 48-d path.

        The vector is the decoder register mean. The classification head (``.head.``) is not
        on that path, and a channel mixer does not exist in the 1-channel model, so neither
        one can refuse a load by itself.
        """
        text = str(name)
        if ".head." in text or "channel_feature_mixer" in text:
            return False
        if text.startswith("backbone."):
            return True
        return ".decoder." in text


    def _key_name(item: Any) -> str:
        """The parameter name from a loading-info entry. A mismatch is ``(name, checkpoint, model)``."""
        if isinstance(item, (list, tuple)) and item:
            return str(item[0])
        return str(item)


    def _load_problems(info: Dict[str, Any]) -> List[str]:
        """Used keys that did not load. ``ignore_mismatched_sizes`` would otherwise hide them."""
        bad: List[str] = []
        for key in sorted(str(k) for k in (info.get("missing_keys") or [])):
            if _embedding_key(key):
                bad.append(f"missing {key}")
        mismatched = info.get("mismatched_keys") or []
        for item in sorted(mismatched, key=_key_name):
            key = _key_name(item)
            if _embedding_key(key):
                bad.append(f"size mismatch {key}")
        return bad


    def _head_notes(info: Dict[str, Any]) -> List[str]:
        """Head keys that were re-initialised. They are recorded and do not refuse the embedding."""
        notes: List[str] = []
        for key in sorted(str(k) for k in (info.get("missing_keys") or [])):
            if not _embedding_key(key):
                notes.append(f"missing {key}")
        mismatched = info.get("mismatched_keys") or []
        for item in sorted(mismatched, key=_key_name):
            key = _key_name(item)
            if not _embedding_key(key):
                notes.append(f"size mismatch {key}")
        return notes


    def _dropped_channel_mixers(info: Dict[str, Any]) -> tuple:
        """Split unexpected keys. A fine-tune may drop only its channel-mixing layers."""
        skipped: List[str] = []
        problems: List[str] = []
        for key in sorted(str(k) for k in (info.get("unexpected_keys") or [])):
            if "channel_feature_mixer" in key:
                skipped.append(key)
            else:
                problems.append(f"unexpected {key}")
        return skipped, problems


    def _log_loading_info(info: Dict[str, Any], where: Path) -> None:
        """Log every missing, unexpected and size-mismatched key. The refusal is separate."""
        missing = sorted(str(k) for k in (info.get("missing_keys") or []))
        unexpected = sorted(str(k) for k in (info.get("unexpected_keys") or []))
        mismatched = sorted(_key_name(item) for item in (info.get("mismatched_keys") or []))
        if missing:
            log.info("TS Pulse %s missing keys: %s", where, ", ".join(missing))
        if unexpected:
            log.info("TS Pulse %s unexpected keys: %s", where, ", ".join(unexpected))
        if mismatched:
            log.info("TS Pulse %s size-mismatched keys: %s", where, ", ".join(mismatched))
        for msg in info.get("error_msgs") or []:
            log.info("TS Pulse %s load note: %s", where, msg)


    def _unpack_pretrained(loaded: Any) -> tuple:
        """``(model, loading_info)``. A bare model would hide which keys were re-initialised."""
        if isinstance(loaded, tuple) and len(loaded) == 2 and isinstance(loaded[1], dict):
            return loaded[0], loaded[1]
        raise RuntimeError("TS Pulse load did not report which weights were used")


    def _source_label(src: Path) -> str:
        """A repo-relative source path. A folder outside the repo is recorded by its name only."""
        from ..config import ROOT

        try:
            return Path(src).resolve().relative_to(Path(ROOT).resolve()).as_posix()
        except ValueError:
            return Path(src).name


    def _active_encoder_dir(settings: Any) -> Optional[Path]:
        """The current encoder folder when it actually holds weights.

        ``e0000`` is ``e2e_model_dir/encoder``. A later id is ``data/e2e/registry/encoders/eNNNN``.
        A missing registry, or a folder with no ``model.safetensors``, is not a candidate.
        """
        if settings is None:
            return None
        folder: Optional[Path] = None
        try:
            from .labels import Registry

            reg = Registry(settings)
            folder = Path(reg.encoder_folder(reg.current_encoder()))
        except Exception as exc:  # noqa: BLE001 — no registry yet still has the shipped folder
            log.debug("active encoder folder unavailable (%s)", type(exc).__name__)
            model_dir = getattr(settings, "e2e_model_dir", None)
            if model_dir:
                folder = Path(model_dir) / "encoder"
        if folder is not None and (folder / "model.safetensors").is_file():
            return folder
        return None


    def ci_weight_folder(path: Optional[Path] = None, settings: Any = None) -> Path:
        """The folder ``CIEncoder`` loads.

        An explicit path wins, including one that has no weights yet (the caller reports that).
        Otherwise the active encoder, then ``settings.tspulse_clf_dir`` when the active folder
        has no weights, then the shipped classification snapshot.
        """
        if path is not None:
            return Path(path)
        active = _active_encoder_dir(settings)
        if active is not None:
            return active
        clf: Optional[Path] = None
        if settings is not None:
            raw = getattr(settings, "tspulse_clf_dir", None)
            if raw:
                clf = Path(raw)
                if (clf / "model.safetensors").is_file():
                    return clf
        from ..config import ROOT

        shipped = Path(ROOT) / "models" / "tspulse" / "clf"
        if (shipped / "model.safetensors").is_file() or clf is None:
            return shipped
        return clf


    def ci_from_finetuned(src: Any, dest: Any) -> Dict[str, Any]:
        """Load a 14-channel fine-tune into the 1-channel model.

        Channel-mixing layers are not in that model, so those keys are skipped. Any other
        key that does not load makes the candidate unavailable and no weights are written.
        A head size mismatch is re-initialised and recorded: the 48-d vector does not use the head.
        The result is always written to ``dest/training.json``, including when the candidate is unavailable.
        """
        import json

        src = Path(src)
        dest = Path(dest)
        label = _source_label(src)
        report: Dict[str, Any] = {
            "embedder": "tspulse_ci",
            "candidate": "finetuned",
            "source": label,
            "available": False,
            "skipped": [],
            "head_reinitialized": [],
            "reason": "",
            "num_input_channels": 1,
        }
        try:
            dest.mkdir(parents=True, exist_ok=True)
            if not (src / "model.safetensors").is_file():
                report["reason"] = f"fine-tuned weights not found in {label}"
            else:
                _offline_env()
                import torch
                from tsfm_public.models.tspulse import TSPulseForClassification

                _quiet_transformers()
                torch.set_num_threads(_threads())
                loaded = TSPulseForClassification.from_pretrained(
                    str(src),
                    output_loading_info=True,
                    local_files_only=True,
                    **ci_model_kwargs(),
                )
                model, info = _unpack_pretrained(loaded)
                _log_loading_info(info, src)
                skipped, dropped = _dropped_channel_mixers(info)
                problems = list(dropped) + _load_problems(info)
                notes = _head_notes(info)
                report["skipped"] = skipped
                report["head_reinitialized"] = notes
                if problems:
                    report["reason"] = "; ".join(problems[:12])
                    if len(problems) > 12:
                        report["reason"] += f"; and {len(problems) - 12} more"
                else:
                    model.save_pretrained(str(dest))
                    report["available"] = True
        except Exception as exc:  # noqa: BLE001 — an unavailable candidate is a record, not a crash
            home = str(Path.home())
            text = f"{type(exc).__name__}: {exc}"
            if home and home in text:
                text = text.replace(home, "~")
            report["available"] = False
            report["reason"] = text
        note = dest / "training.json"
        try:
            dest.mkdir(parents=True, exist_ok=True)
            note.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
        except OSError as exc:
            report["reason"] = report["reason"] or f"could not record the candidate ({type(exc).__name__})"
        return report


    def _register_matrix(hidden: Any, d_model: int, n_reg: int) -> Any:
        """Mean of the decoder's register tokens. ``hidden`` is ``(B, C, patches * d_model)``."""
        batch, channels, width = hidden.shape
        tokens = hidden.reshape(batch, channels, width // d_model, d_model)
        pooled = tokens[:, :, -n_reg:, :].mean(dim=2) if n_reg else tokens.mean(dim=2)
        return pooled.reshape(batch, -1)


    class CIEncoder:
        """Channel-independent TS Pulse. One 48-d vector per present channel, any channel count.

        Masked channels are not passed in, so a missing tag cannot look like a flat measured tag.
        Windows from every profile share one batch of ``EMBED_BATCH_WINDOWS``. Device is
        ``auto``, ``gpu`` or ``cpu``. A GPU out-of-memory error retries that batch on CPU.
        """

        name = "tspulse_ci"
        dim = 48
        fallback = False
        fallback_reason = ""

        def __init__(self, path: Optional[Path] = None, device: str = "auto", settings: Any = None):
            """Load the active encoder. An explicit ``path`` still wins.

            Falls back to ``tspulse_clf_dir`` when the active folder has no weights.
            A backbone or decoder key that did not load raises. A head mismatch is logged
            and kept, because that head is not the 48-d vector.
            """
            _offline_env()
            import torch
            from tsfm_public.models.tspulse import TSPulseForClassification

            _quiet_transformers()
            torch.set_num_threads(_threads())
            self.path = Path(ci_weight_folder(path, settings))
            if not (self.path / "model.safetensors").is_file():
                raise FileNotFoundError(f"TS Pulse weights not found in {self.path}")
            loaded = TSPulseForClassification.from_pretrained(
                str(self.path),
                output_loading_info=True,
                local_files_only=True,
                **ci_model_kwargs(),
            )
            self.model, info = _unpack_pretrained(loaded)
            _log_loading_info(info, self.path)
            problems = _load_problems(info)
            if problems:
                raise RuntimeError(
                    f"TS Pulse weights in {self.path} did not load a used layer: " + "; ".join(problems)
                )
            self.model.eval()
            self.d_model = int(self.model.config.decoder_d_model)
            self.n_reg = int(self.model.config.patch_register_tokens or 0)
            choice = resolve_train_device(device or "auto")
            self._device = choice["device"]
            self.device_reason = choice["reason"]
            try:
                self.model.to(self._device)
            except RuntimeError as exc:
                if self._device != "cuda" or not _gpu_oom(exc):
                    raise
                self.model.to("cpu")
                self._device = "cpu"
                self.device_reason = f"GPU ran out of memory ({exc}); fell back to CPU"
            self.embed_rate = 0.0

        def _forward_chunk(self, windows: np.ndarray, device: str) -> np.ndarray:
            """``(K, 512, 1)`` on ``device`` -> ``(K, 48)`` on CPU."""
            import torch

            with torch.no_grad():
                xb = torch.tensor(np.asarray(windows, dtype=np.float32), device=device)
                hidden = self.model(xb, return_loss=False).decoder_hidden_state
                pooled = _register_matrix(hidden, self.d_model, self.n_reg)
                return pooled.detach().cpu().numpy().astype(np.float32)

        def _embed_packed(self, windows: np.ndarray) -> np.ndarray:
            """``(K, 512, 1)`` -> ``(K, 48)``, in batches, with a CPU retry after a GPU OOM."""
            from ..config import EMBED_BATCH_WINDOWS

            batch = max(1, int(EMBED_BATCH_WINDOWS))
            parts: List[np.ndarray] = []
            started = time.monotonic()
            done = 0
            for start in range(0, len(windows), batch):
                chunk = windows[start : start + batch]

                def run(dev: str, chunk: np.ndarray = chunk) -> np.ndarray:
                    return self._forward_chunk(chunk, dev)

                vectors, device, reason = _call_or_cpu(self._device, self.model, run)
                if device != self._device:
                    self._device = device
                    self.device_reason = reason
                    log.info(reason)
                parts.append(vectors)
                done += len(chunk)
            elapsed = max(1e-6, time.monotonic() - started)
            self.embed_rate = done / elapsed
            LAST_EMBED_RATE.clear()
            LAST_EMBED_RATE.update(
                {
                    "windows_per_s": round(self.embed_rate, 2),
                    "device": "gpu" if self._device == "cuda" else "cpu",
                    "windows": done,
                    "embedder": self.name,
                }
            )
            return np.concatenate(parts, axis=0) if parts else np.zeros((0, self.dim), dtype=np.float32)

        def embed_channels(self, x: np.ndarray, mask: Optional[np.ndarray] = None) -> np.ndarray:
            """``(512, C)`` -> ``(C, 48)``, or ``(N, 512, C)`` -> ``(N, C, 48)``.

            Only channels with ``mask`` true are run. The others stay zeros.
            """
            arr = np.asarray(x, dtype=np.float32)
            single = arr.ndim == 2
            if single:
                arr = arr[None, ...]
            if arr.ndim != 3:
                raise ValueError(f"expected (512, C) or (N, 512, C), got {getattr(x, 'shape', None)}")
            rows, _length, channels = arr.shape
            if mask is None:
                use = np.ones((rows, channels), dtype=bool)
            else:
                use = np.asarray(mask, dtype=bool)
                if use.ndim == 1:
                    use = np.broadcast_to(use, (rows, channels)).copy()
                else:
                    use = use.reshape(rows, channels)
            out = np.zeros((rows, channels, self.dim), dtype=np.float32)
            packed = [arr[row, :, channel] for row in range(rows) for channel in range(channels) if use[row, channel]]
            if packed:
                vectors = self._embed_packed(np.stack(packed, axis=0)[..., None])
                cursor = 0
                for row in range(rows):
                    for channel in range(channels):
                        if not use[row, channel]:
                            continue
                        out[row, channel] = vectors[cursor]
                        cursor += 1
            return out[0] if single else out


    class _NamedEmbedder:
        """A registry entry that is not the statistical fallback. Calling it before its loader exists is an error."""

        def __init__(self, name: str, reason: str):
            self.name = name
            self.dim = 48
            self.fallback = False
            self.fallback_reason = reason

        def embed_channels(self, x: np.ndarray, mask: Optional[np.ndarray] = None) -> np.ndarray:
            raise RuntimeError(self.fallback_reason)


    def get_embedder(name: Optional[str] = None, settings: Any = None):
        """The embedder from the argument, else ``settings.embedder``, else ``stats``.

        ``tspulse_ci`` uses the channel-independent encoder once that class is loaded.
        The cache key is the resolved weight folder, so a site encoder is not reused for
        the classification snapshot. If the class is missing, or it fails to construct,
        the statistical embedder is returned with ``fallback`` set. A failed load is not
        cached. ``legacy14`` stays a separate entry so its vectors are never mixed into
        a per-channel index.
        """
        if name is None and settings is not None:
            name = getattr(settings, "embedder", None)
        chosen = (name or "stats").strip()
        if chosen == "stats":
            return StatsEmbedder()
        if chosen == "tspulse_ci":
            cls = globals().get("CIEncoder")
            if cls is not None:
                try:
                    key = str(ci_weight_folder(settings=settings))
                    cached = _CI_CACHE.get(key)
                    if cached is not None and cached.__class__ is cls:
                        return cached
                    made = cls(settings=settings)
                    made.fallback = False
                except Exception as exc:  # noqa: BLE001 — missing weights must not break a run
                    stats = StatsEmbedder()
                    stats.fallback = True
                    stats.fallback_reason = f"TS Pulse unavailable ({type(exc).__name__})"
                    return stats
                _CI_CACHE[key] = made
                return made
            stats = StatsEmbedder()
            stats.fallback = True
            stats.fallback_reason = "TS Pulse channel-independent encoder is not loaded"
            return stats
        if chosen == "legacy14":
            return _NamedEmbedder("legacy14", "legacy14 embeds canonical 14-channel windows with the shipped encoder")
        stats = StatsEmbedder()
        stats.fallback = True
        stats.fallback_reason = f"unknown embedder {chosen!r}; using the statistical fallback"
        return stats
