# <<<<<<< SECTION sentinel.e2e.residual sentinel/e2e/residual.py
if False:  # compiled by exec_section('sentinel.e2e.residual'); not executed as part of this module
    """Second TS Pulse view of a case: reconstruction residuals per sensor — *how* the data is abnormal.

    The first view (features.py → encoder.py) gives one embedding: what the case looks like as a whole.
    This view works sensor by sensor, in physical units, so the report writer can check the classifier:

    * **Residual channels** — the canonical channels at sensor resolution, with the same role mapping,
      online mask and baseline (first 30 % of online rows) as features.py: every exhaust TC / zone as
      its deviation from the ring median; EGT average, fuel, IGV and other process values as their
      deviation from a load fit; spread, dynamics and vibration against their own baseline; load as
      context.
    * **Scores** — per channel, in units of the channel's own baseline sigma (so channels compare):

      - *transient*: TS Pulse r1 zero-shot masked reconstruction (``TSPulseForReconstruction`` with the
        anomaly-detection weights in ``models/tspulse/ad``, local files only, CPU by default, GPU when
        available). Two passes with complementary alternating patch masks reconstruct every 8-sample
        patch from its neighbours; measured − reconstructed is large where the shape is unexpected
        (steps, spikes, dropouts, oscillation onsets). Without the model: deviation from a rolling median
        (robust-z residual fallback) — same outputs, ``mode = "robust_z"``.
      - *level*: robust z against the baseline (drifts and sustained offsets, which a reconstruction
        model absorbs once they persist).
      - *frozen*: online stretches without sensor noise (flatline).

    * **Outputs** — per-channel score, a per-time profile (UI heatmap), a time-ordered onset sequence
      (which channels deviated first, when, by how much, direction, ramp, duration), neighbour coherence
      for TCs / zones (did the adjacent sensors follow?), co-movement of load / IGV / fuel, a compact
      engineering description for the LLM prompt and a deterministic cross-check of the residual pattern
      against the predicted signature (``cross_check``).

    Passing a profile uses that alert type's slots instead of the fixed roles. ``legacy_role`` keeps
    today's group names, so the built-in rules still run. A slot without one uses the role-default
    threshold, and ``cross_check`` follows ``residual_expect``. A signature with no expected pattern
    is inconclusive, never a contradiction.
    """

    # @@future@@ from __future__ import annotations

    import logging
    import math
    import os
    import re
    from typing import Any, Dict, List, Optional, Sequence, Tuple

    import numpy as np
    import pandas as pd

    from ..data import CaseData
    from .features import _cols, _ffill, _first_series, _noise_sigma

    log = logging.getLogger(__name__)

    VERSION = "residual/3"
    CONTEXT = 512
    PATCH = 8
    ABNORMAL = 6.0  # channel score above which a channel counts as abnormal (base level)
    # Per-group thresholds = max(6, 1.1 x q99 of the scores of channel groups the true signature does not
    # touch, on the validation split (calibrate_thresholds). Load-fitted channels are noisier than direct
    # measurements. Shipped in models/e2e/base/calibration.json; these are the defaults.
    THRESHOLDS: Dict[str, float] = {"exhaust": 6.0, "spread": 6.0, "egt": 6.0, "dynamics": 6.0, "vibration": 7.1, "fuel": 7.4, "igv": 9.8, "other": 9.8}
    STRONG = 2.0  # "clearly abnormal": score >= STRONG x the group threshold
    FROZEN_SCORE = 8.0
    MAX_EVENTS = 6
    MAX_CHANNELS_PROFILE = 12
    PROFILE_BINS = 160
    GROUP_LABEL = {
        "exhaust": "exhaust TC / zone (vs ring median)",
        "spread": "exhaust spread",
        "egt": "average exhaust temperature (vs load fit)",
        "dynamics": "combustion dynamics",
        "vibration": "vibration",
        "fuel": "fuel flow (vs load fit)",
        "igv": "IGV position (vs load schedule)",
        "load": "load",
        "other": "other process value (vs load fit)",
    }
    _FLOOR = {"exhaust": 0.3, "spread": 0.3, "egt": 0.3, "dynamics": 0.02, "vibration": 0.03, "igv": 0.05, "load": 0.05}
    _DECIMALS = {"C": 1, "MW": 1, "psi": 2, "mm/s": 2, "deg": 2, "bar": 2, "kg/s": 3}
    _TAG_UNITS = {"dwatt": "MW", "cpd": "bar", "ctd": "C", "ttxm": "C", "ttxsp1": "C", "fqg": "kg/s", "csgv": "deg", "bb1": "mm/s",
                  "bb2": "mm/s", "ltot": "C", "cdm_amp": "psi"}
    _MODEL_CACHE: Dict[str, Any] = {}


    # ----------------------------------------------------------------------------------- model


    def _threads() -> int:
        """Function _threads."""
        return max(1, min(8, (os.cpu_count() or 4) // 2))


    def _want_device(settings: Any) -> str:
        """Function _want_device."""
        want = str(getattr(settings, "device", "auto") or "auto").lower()
        if want == "cpu":
            return "cpu"
        try:
            import torch

            return "cuda" if torch.cuda.is_available() else "cpu"
        except Exception:  # noqa: BLE001
            return "cpu"


    def model_dir(settings: Any) -> Optional[str]:
        """Function model_dir."""
        d = getattr(settings, "tspulse_dir", None)
        if d and os.path.isfile(os.path.join(str(d), "config.json")) and os.path.isfile(os.path.join(str(d), "model.safetensors")):
            return str(d)
        return None


    class ReconModel:
        """TS Pulse r1 anomaly-detection weights as a single-channel masked reconstructor."""

        def __init__(self, path: str, device: str = "cpu"):
            """Function __init__."""
            os.environ.setdefault("HF_HUB_OFFLINE", "1")
            os.environ.setdefault("TRANSFORMERS_OFFLINE", "1")
            os.environ.setdefault("HF_HUB_DISABLE_PROGRESS_BARS", "1")
            os.environ.setdefault("HF_HUB_DISABLE_TELEMETRY", "1")
            import torch
            import transformers
            from tsfm_public.models.tspulse import TSPulseForReconstruction

            transformers.logging.set_verbosity_error()
            transformers.logging.disable_progress_bar()
            if device == "cpu":
                torch.set_num_threads(_threads())
            self.path, self.device = path, device
            self.model = TSPulseForReconstruction.from_pretrained(path, num_input_channels=1, mask_type="user", local_files_only=True)
            self.model.eval().to(device)
            if int(self.model.config.context_length) != CONTEXT or int(self.model.config.patch_length) != PATCH:
                raise ValueError(f"unexpected TS Pulse geometry {self.model.config.context_length}/{self.model.config.patch_length}")

        @property
        def description(self) -> str:
            """Function description."""
            name = os.path.basename(os.path.normpath(self.path))
            return f"TS Pulse r1 zero-shot masked reconstruction (models/tspulse/{name}, {self.device.upper()})"

        def reconstruct(self, Z: np.ndarray, batch: int = 128) -> np.ndarray:
            """(n, C) -> (n, C): every patch reconstructed from its neighbours (two alternating-mask passes)."""
            import torch

            n, C = Z.shape
            if n < CONTEXT:
                Zp = np.vstack([np.repeat(Z[:1], CONTEXT - n, axis=0), Z])
            else:
                Zp = Z
            m = Zp.shape[0]
            starts = list(range(0, m - CONTEXT + 1, CONTEXT))
            if starts[-1] != m - CONTEXT:
                starts.append(m - CONTEXT)
            seqs = np.stack([Zp[s : s + CONTEXT, c] for s in starts for c in range(C)]).astype(np.float32)[:, :, None]
            out = np.zeros_like(seqs)
            par = (np.arange(CONTEXT) // PATCH) % 2
            with torch.no_grad():
                for i in range(0, len(seqs), batch):
                    xb = torch.tensor(seqs[i : i + batch], device=self.device)
                    for p in (0, 1):
                        sel = torch.tensor(par == p, device=self.device)
                        mask = torch.ones_like(xb, dtype=torch.bool)
                        mask[:, sel, :] = False
                        rec = self.model(past_values=xb, past_observed_mask=mask).reconstruction_outputs
                        out[i : i + batch][:, par == p, :] = rec[:, sel, :].float().cpu().numpy()
            R = np.zeros_like(Zp)
            k = 0
            for s in starts:
                for c in range(C):
                    R[s : s + CONTEXT, c] = out[k, :, 0]
                    k += 1
            return R[-n:] if n < CONTEXT else R


    def load_model(settings: Any) -> Tuple[Optional[ReconModel], str]:
        """(model or None, reason). Never downloads; any failure means the robust-z fallback."""
        mode = str(getattr(settings, "residual_mode", "auto") or "auto").lower()
        if mode in ("robust_z", "off", "fallback"):
            return None, "robust-z residual (TS Pulse residual model disabled in settings: residual_mode)"
        path = model_dir(settings)
        if not path:
            return None, f"robust-z residual fallback (TS Pulse anomaly weights not found in {getattr(settings, 'tspulse_dir', None)})"
        device = _want_device(settings)
        key = f"{os.path.abspath(path)}|{device}"
        if key not in _MODEL_CACHE:
            try:
                _MODEL_CACHE[key] = ReconModel(path, device)
            except Exception as exc:  # noqa: BLE001
                if device != "cpu":
                    try:
                        _MODEL_CACHE[key] = ReconModel(path, "cpu")
                    except Exception as exc2:  # noqa: BLE001
                        _MODEL_CACHE[key] = f"{type(exc2).__name__}: {exc2}"
                else:
                    _MODEL_CACHE[key] = f"{type(exc).__name__}: {exc}"
        m = _MODEL_CACHE[key]
        if isinstance(m, str):
            return None, f"robust-z residual fallback (TS Pulse residual model failed to load: {m[:160]})"
        return m, m.description


    def status(settings: Any) -> Dict[str, str]:
        """Which residual mode is active (for `app.py doctor` and the report audit)."""
        m, why = load_model(settings)
        return {"mode": "tspulse" if m is not None else "robust_z", "detail": why}


    # ----------------------------------------------------------------------------------- channels


    def _unit(col: str, group: str) -> str:
        """Function _unit."""
        if group in ("exhaust", "spread", "egt"):
            return "C"
        fixed = {"dynamics": "psi", "vibration": "mm/s", "igv": "deg", "load": "MW"}
        if group in fixed:
            return fixed[group]
        c = col.lower()
        if c in _TAG_UNITS:
            return _TAG_UNITS[c]
        for suf, u in (("_kg_s", "kg/s"), ("_c", "C"), ("_bar", "bar"), ("_psi", "psi"), ("_mw", "MW"), ("_deg", "deg"), ("_mm_s", "mm/s"), ("_pct", "%")):
            if c.endswith(suf):
                return u
        return ""


    def _sigma(x: np.ndarray, base: np.ndarray, floor: float) -> float:
        """Function _sigma."""
        ref = x[base & np.isfinite(x)]
        if ref.size < 10:
            ref = x[np.isfinite(x)]
        if ref.size == 0:
            return 1.0
        med = float(np.median(ref))
        mad = float(np.median(np.abs(ref - med))) * 1.4826
        return max(mad, _noise_sigma(ref), floor, 1e-3 * max(abs(med), 1.0))


    def _ring_order(cols: List[str]) -> List[str]:
        """Physical ring order by the trailing sensor number (TTXD_17 -> 17, TC5 -> 5, EGT_Z3_C -> 3).

        map_roles uses the same natural order. This second sort stays so a column the ring regex
        did not claim still lines up with its neighbours inside the residual view.
        """
        def key(c: str) -> Tuple[int, str]:
            """Function key."""
            m = re.search(r"(\d+)\D*$", c)
            return (int(m.group(1)) if m else 10**6, c)

        return sorted(cols, key=key)


    def _load_fit(x: np.ndarray, load: Optional[np.ndarray], online: np.ndarray, base: np.ndarray, gate: bool = False) -> Tuple[np.ndarray, np.ndarray]:
        """(x minus its dependence on load, rows where that reference is valid).

        Monotone (isotonic) fit of x against load on the baseline online rows — follows nonlinear
        schedules such as IGV saturation and load plateaus. Rows whose load lies outside the baseline's
        load range have no reference and are marked invalid (their residuals are not trusted).
        ``gate``: fit only if x correlates with load at all (ambient does not); else baseline median.
        """
        n = len(x)
        valid = np.ones(n, dtype=bool)
        ref = base if base.sum() > 30 else online
        ok = ref & np.isfinite(x) & (np.isfinite(load) if load is not None else True)
        if load is None or ok.sum() <= 30:
            good = x[ok] if ok.any() else x[np.isfinite(x)]
            return x - (float(np.median(good)) if good.size else 0.0), valid
        lo_, hi_ = float(np.min(load[ok])), float(np.max(load[ok]))
        span = max(abs(hi_), 1.0)
        r = np.corrcoef(load[ok], x[ok])[0, 1] if np.std(x[ok]) > 1e-12 and np.std(load[ok]) > 1e-12 else 0.0
        if hi_ - lo_ < 0.02 * span:  # one load level in the baseline: no reference at other loads
            lf = np.nan_to_num(load, nan=lo_)
            return x - float(np.median(x[ok])), (lf >= lo_ - 0.02 * span) & (lf <= hi_ + 0.02 * span)
        if gate and abs(r) < 0.3:
            return x - float(np.median(x[ok])), valid
        from sklearn.isotonic import IsotonicRegression

        iso = IsotonicRegression(increasing=bool(r >= 0), out_of_bounds="clip")
        iso.fit(load[ok], x[ok])
        lf = np.nan_to_num(load, nan=lo_)
        valid = (lf >= lo_ - 0.02 * span) & (lf <= hi_ + 0.02 * span)
        return x - iso.predict(lf), valid


    # legacy_role -> the group name the built-in rules and THRESHOLDS already use.
    # load is context, not a scored group. A slot with no entry here is its own group.
    _LEGACY_GROUP = {
        "ring": "exhaust", "zones": "exhaust", "spread": "spread", "egt_avg": "egt", "egt": "egt",
        "dynamics": "dynamics", "vibration": "vibration", "fuel": "fuel", "igv": "igv", "load": "load",
    }
    # Role defaults when the slot does not inherit a THRESHOLDS group. Same numbers as today's table:
    # ring matches exhaust, bank matches vibration, process matches fuel, other matches other.
    _ROLE_DEFAULT = {"ring": 6.0, "bank": 7.1, "process": 7.4, "other": 9.8}


    def _group_for_slot(slot: Any) -> str:
        """Scoring group for one slot. A mapped legacy role keeps today's name; anything else is the slot id."""
        legacy = getattr(slot, "legacy_role", "") or ""
        mapped = _LEGACY_GROUP.get(legacy)
        if mapped and mapped != "load":
            return mapped
        return str(getattr(slot, "id", "") or "other")


    def _role_default(slot: Any) -> float:
        """Threshold before calibration. Built-in slots keep today's THRESHOLDS value through legacy_role."""
        mapped = _LEGACY_GROUP.get(getattr(slot, "legacy_role", "") or "")
        if mapped in THRESHOLDS:
            return float(THRESHOLDS[mapped])
        return float(_ROLE_DEFAULT.get(getattr(slot, "role", "") or "", THRESHOLDS["other"]))


    def _legacy_groups(profile: Any) -> set:
        """Residual groups this alert type actually maps, so a rule runs only when its sensors exist."""
        found = set()
        for slot in getattr(profile, "slots", []) or []:
            mapped = _LEGACY_GROUP.get(getattr(slot, "legacy_role", "") or "")
            if mapped and mapped != "load":
                found.add(mapped)
        return found


    def _legacy_rules_apply(profile: Any, signature: str) -> bool:
        """Today's bespoke cross-check, and only when this profile maps every group that rule names.

        ``normal`` has no primary group. It still uses the bespoke rule when the profile has any
        legacy role, and stays on the generic path when it does not, so a new alert type is never
        contradicted just because a channel moved.
        """
        if profile is None or signature not in EXPECTED:
            return False
        primary = EXPECTED[signature][0]
        present = _legacy_groups(profile)
        if not primary:
            return bool(present)
        return all(group in present for group in primary)


    def _slot_label(profile: Any, slot_id: str) -> str:
        """Engineer-facing name. The slot id is the fallback when the profile has no label."""
        for slot in getattr(profile, "slots", []) or []:
            if slot.id == slot_id:
                return slot.label or slot.id
        return "other tags" if slot_id == "_other" else str(slot_id)


    def _expect_sentence(profile: Any, signature: str) -> str:
        """residual_expect in slot labels, for the report line that used to be PATTERN_TEXT."""
        entry = (getattr(profile, "residual_expect", None) or {}).get(signature)
        if not entry:
            return "not defined"

        def names(ids: Sequence[str]) -> str:
            return ", ".join(_slot_label(profile, sid) for sid in ids) or "none"

        return f"primary {names(entry.get('primary') or [])}; allowed {names(entry.get('allowed') or [])}"


    def _slot_score_map(res: Dict[str, Any]) -> Tuple[Dict[str, float], Dict[str, str]]:
        """Highest score per slot, and the group that score was judged against. Load is not a fault."""
        scores: Dict[str, float] = {}
        groups: Dict[str, str] = {}
        for channel in res.get("channels") or []:
            slot_id = channel.get("slot")
            if not slot_id or channel.get("group") == "load" or channel.get("kind") in ("context", "flag"):
                continue
            score = float(channel.get("score") or 0.0)
            if score >= scores.get(slot_id, -1.0):
                scores[slot_id] = score
                groups[slot_id] = str(channel.get("group") or slot_id)
        return scores, groups


    def _points_to_signature(profile: Any, slot_id: str, current: str) -> Optional[str]:
        """Another signature on this alert type whose primary slot is the one that moved."""
        expect_map = getattr(profile, "residual_expect", None) or {}
        order = list(getattr(profile, "signatures", []) or [])
        for sig in order + [name for name in expect_map if name not in order]:
            if sig == current:
                continue
            if slot_id in ((expect_map.get(sig) or {}).get("primary") or []):
                return sig
        return None


    def _expect_check(signature: str, res: Dict[str, Any], profile: Any) -> Dict[str, Any]:
        """Generic cross-check. No residual_expect entry is inconclusive, never a contradiction."""
        entry = (getattr(profile, "residual_expect", None) or {}).get(signature)
        if not entry:
            return {"verdict": "inconclusive", "reason": "no expected residual pattern defined for this signature",
                    "points_to": None, "expected": "not defined"}
        primary = list(entry.get("primary") or [])
        allowed = set(entry.get("allowed") or []) | set(primary)
        scores, groups = _slot_score_map(res)
        thr = res.get("thresholds") or THRESHOLDS
        abnormal = {sid for sid in (res.get("slots_abnormal") or []) if sid in scores or sid in primary}
        if not abnormal:
            for sid, score in scores.items():
                limit = float(thr.get(sid, thr.get(groups.get(sid, ""), ABNORMAL)))
                if score >= limit:
                    abnormal.add(sid)
        strong = []
        for sid, score in scores.items():
            limit = float(thr.get(sid, thr.get(groups.get(sid, ""), ABNORMAL)))
            if score >= STRONG * limit and sid not in allowed:
                strong.append(sid)
        top = (res.get("pattern") or {}).get("top_slot")
        if not top and scores:
            top = max(scores, key=lambda sid: scores[sid])
        expected = _expect_sentence(profile, signature)
        if any(sid in abnormal for sid in primary) and top in allowed:
            return {"verdict": "supports",
                    "reason": f"{_slot_label(profile, top)} is abnormal and is allowed for this signature",
                    "points_to": None, "expected": expected}
        if strong:
            outsider = max(strong, key=lambda sid: scores.get(sid, 0.0))
            return {"verdict": "contradicts",
                    "reason": f"{_slot_label(profile, outsider)} is strongly abnormal and outside the allowed slots",
                    "points_to": _points_to_signature(profile, outsider, signature), "expected": expected}
        return {"verdict": "inconclusive", "reason": "residual pattern is not decisive for this signature",
                "points_to": None, "expected": expected}


    def _thresholds_for_profile(thr: Dict[str, float], profile: Any, explicit: Optional[Dict[str, float]]) -> Dict[str, float]:
        """Group thresholds, plus one key per slot.

        A legacy group keeps the value ``thresholds_for`` already resolved (the shipped calibration
        can raise it). A slot with no legacy group uses the role default unless the caller passed
        that slot id, which is how a per-profile calibration overrides one alert type.
        """
        if profile is None:
            return thr
        given = {str(k): float(v) for k, v in (explicit or {}).items()}
        out = dict(thr)
        for slot in getattr(profile, "slots", []) or []:
            if slot.role in ("flag", "context", "ignore"):
                continue
            group = _group_for_slot(slot)
            if slot.id in given:
                out[group] = given[slot.id]
                out[slot.id] = given[slot.id]
            elif group in THRESHOLDS:
                out[slot.id] = float(out.get(group, THRESHOLDS[group]))
            else:
                default = _role_default(slot)
                out[group] = default
                out[slot.id] = default
        return out


    def _case_baseline(case: CaseData, load: Optional[np.ndarray]) -> Tuple[float, np.ndarray, np.ndarray, np.ndarray]:
        """Online mask, baseline (first 30 % of online rows) and load-moving mask. Same rule as the role builder."""
        n = case.n
        if load is not None:
            p95 = float(np.nanpercentile(load, 95)) if np.isfinite(load).any() else 0.0
            online = np.nan_to_num(load) >= 0.3 * p95 if p95 > 0 else np.ones(n, dtype=bool)
        else:
            p95, online = 0.0, np.ones(n, dtype=bool)
        first = np.zeros(n, dtype=bool)
        first[: max(10, int(0.3 * n))] = True
        base = online & first
        if int(base.sum()) < 10:
            base = online.copy()
        moving = np.zeros(n, dtype=bool)
        if load is not None and p95 > 0:
            filled = _ffill(np.asarray(load, dtype=float)[:, None])[:, 0]
            width = max(3, case.samples(60))
            ref = pd.Series(filled).rolling(width, min_periods=1).median().to_numpy()
            moving = np.abs(filled - ref) > 0.05 * p95
            moving = pd.Series(moving.astype(float)).rolling(2 * width + 1, center=True, min_periods=1).max().to_numpy() > 0
        return float(p95), online, base, moving


    def _profile_channels(case: CaseData, profile: Any, resolved: Any) -> Dict[str, Any]:
        """Residual channels for one alert type, at sensor resolution.

        Ring: each member's deviation from the row median, minus its baseline offset, with the
        position kept so neighbour coherence stays inside that ring. Bank: each member against
        its own baseline. Process: a load fit when the slot asks for one, otherwise the baseline
        deviation. Flag and context are not scored; load drives the online mask, and a trip flag
        sets the trip mask. Unlisted numeric columns become ``_other`` when the profile includes
        them, with the same gated load fit the role builder uses for unclaimed tags.
        """
        if resolved is None:
            from ..profiles import resolve_tags

            resolved = resolve_tags(profile, case)
        n = case.n

        def tags_of(slot_id: str) -> List[str]:
            hit = resolved.by_id(slot_id) if hasattr(resolved, "by_id") else None
            if hit is None or getattr(hit, "status", "") != "present":
                return []
            return [tag for tag in hit.tags if tag in case.df.columns]

        def one_series(cols: Sequence[str]) -> Optional[np.ndarray]:
            if not cols:
                return None
            return _ffill(case.series(cols[0])[:, None])[:, 0]

        def series_for(legacy_name: str, slot_id: str) -> Optional[np.ndarray]:
            for slot in profile.slots:
                if slot.legacy_role == legacy_name or slot.id == slot_id:
                    found = tags_of(slot.id)
                    if found:
                        return one_series(found)
            return None

        load = series_for("load", "load")
        if load is None:
            for slot in profile.slots:
                if slot.role == "context":
                    load = one_series(tags_of(slot.id))
                    if load is not None:
                        break
        p95, online, base, moving = _case_baseline(case, load)
        igv = series_for("igv", "igv")
        fuel = series_for("fuel", "fuel")
        trip = np.zeros(n, dtype=bool)
        for slot in profile.slots:
            if slot.role == "flag" and (slot.legacy_role == "trip" or slot.id == "trip"):
                cols = tags_of(slot.id)
                if cols:
                    trip = np.nan_to_num(np.column_stack([case.series(c) for c in cols])).max(axis=1) > 0.5
                    break

        names: List[str] = []
        groups: List[str] = []
        units: List[str] = []
        slots: List[str] = []
        kinds: List[str] = []
        fit_flags: List[bool] = []
        health_flags: List[bool] = []
        cols_out: List[np.ndarray] = []
        raw: List[Optional[np.ndarray]] = []
        ring_pos: List[Optional[int]] = []
        valid_masks: List[np.ndarray] = []
        slot_labels: Dict[str, str] = {}
        used: set = set()
        ring_n = 0
        zone_n = 0

        def add(name: str, group: str, values: np.ndarray, *, slot: str, kind: str, unit: str = "",
                 raw_values: Optional[np.ndarray] = None, pos: Optional[int] = None,
                 valid: Optional[np.ndarray] = None, fitted: bool = False, health: bool = False, label: str = "") -> None:
            values = np.where(online, np.nan_to_num(np.asarray(values, dtype=float)), 0.0)
            names.append(name)
            groups.append(group)
            units.append(unit or _unit(name, group))
            slots.append(slot)
            kinds.append(kind)
            fit_flags.append(bool(fitted))
            health_flags.append(bool(health))
            cols_out.append(values)
            raw.append(None if raw_values is None else np.asarray(raw_values, dtype=float))
            ring_pos.append(pos)
            valid_masks.append(np.ones(n, dtype=bool) if valid is None else valid)
            if label:
                slot_labels.setdefault(slot, label)
            used.add(name)

        for slot in profile.slots:
            if slot.role in ("flag", "context", "ignore"):
                used.update(tags_of(slot.id))
                continue
            tags = tags_of(slot.id)
            if not tags:
                continue
            label = slot.label or slot.id
            group = _group_for_slot(slot)
            if slot.role == "ring":
                ordered = _ring_order(tags)
                if slot.legacy_role == "zones":
                    zone_n = max(zone_n, len(ordered))
                else:
                    ring_n = max(ring_n, len(ordered))
                block = _ffill(np.column_stack([case.series(c) for c in ordered]))
                dev = block - np.nanmedian(block, axis=1)[:, None]
                offset = np.nanmedian(dev[base], axis=0) if int(base.sum()) > 10 else np.nanmedian(dev, axis=0)
                dev = dev - offset
                for i, tag in enumerate(ordered):
                    add(tag, group, dev[:, i], slot=slot.id, kind="ring", unit=slot.unit, raw_values=case.series(tag),
                        pos=i, health=bool(slot.health), label=label)
            elif slot.role == "bank":
                for tag in _ring_order(tags):
                    values = _ffill(case.series(tag)[:, None])[:, 0]
                    level = float(np.nanmedian(values[base])) if base.any() else 0.0
                    add(tag, group, values - level, slot=slot.id, kind="bank", unit=slot.unit, raw_values=case.series(tag),
                        health=bool(slot.health), label=label)
            else:
                for tag in tags:
                    values = _ffill(case.series(tag)[:, None])[:, 0]
                    raw_values = case.series(tag) if slot.health else None
                    if slot.load_fit:
                        fitted, valid = _load_fit(values, load, online, base)
                        add(tag, group, fitted, slot=slot.id, kind="process", unit=slot.unit, raw_values=raw_values,
                            valid=valid, fitted=True, health=bool(slot.health), label=label)
                    else:
                        level = float(np.nanmedian(values[base])) if base.any() else 0.0
                        add(tag, group, values - level, slot=slot.id, kind="process", unit=slot.unit, raw_values=raw_values,
                            health=bool(slot.health), label=label)
        if getattr(profile, "include_other", True):
            slot_labels.setdefault("_other", "other tags")
            for column in case.numeric_columns:
                if column in used or int(case.df[column].notna().sum()) <= 10:
                    continue
                values = _ffill(case.series(column)[:, None])[:, 0]
                if float(np.nanstd(values)) < 1e-9:
                    continue
                fitted, valid = _load_fit(values, load, online, base, gate=True)
                add(column, "other", fitted, slot="_other", kind="other", valid=valid, fitted=True, label="other tags")
        layout = "ring" if ring_n >= 3 else ("zones" if zone_n >= 2 else "none")
        n_ring = ring_n if ring_n >= 3 else zone_n
        matrix = np.column_stack(cols_out) if cols_out else np.zeros((n, 0))
        sigma = np.array([_sigma(matrix[:, i], base, _FLOOR.get(group, 1e-6)) for i, group in enumerate(groups)]) if groups else np.zeros(0)
        return {
            "names": names, "groups": groups, "units": units, "R": matrix, "sigma": sigma, "raw": raw,
            "ring_pos": ring_pos, "layout": layout, "n_ring": int(n_ring), "online": online, "base": base,
            "trip": trip, "load_moving": moving, "valid": valid_masks, "load": load, "igv": igv, "fuel": fuel,
            "load_p95": float(p95), "slots": slots, "kinds": kinds, "load_fit": fit_flags, "health": health_flags,
            "slot_labels": slot_labels,
        }


    def _ring_phrase(ch: Dict[str, Any], slot_id: str, events: Sequence[Dict[str, Any]], top: Dict[str, Any]) -> str:
        """sector when neighbours followed or two adjacent members moved; otherwise one sensor."""
        member_count = sum(1 for slot, kind in zip(ch.get("slots") or [], ch.get("kinds") or []) if slot == slot_id and kind == "ring")
        summary = (top.get("neighbours") or {}).get("summary", "")
        followed = summary.startswith("neighbours followed") or summary.startswith("neighbours partially")
        occupied = {event["ring_pos"] for event in events if event.get("ring_pos") is not None and event.get("direction") == top.get("direction")}
        adjacent = 0
        origin = top.get("ring_pos")
        if origin is not None and member_count:
            adjacent = 1
            for step in (1, -1):
                pos = (origin + step) % member_count
                while pos in occupied and adjacent < member_count:
                    adjacent += 1
                    pos = (pos + step) % member_count
        if adjacent >= 2 or followed:
            return "sector"
        return "single_sensor"


    def _profile_patterns(ch: Dict[str, Any], events: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
        """Generic patterns. Empty unless the channel dict came from a profile."""
        labels = ch.get("slot_labels") or {}
        by_slot: Dict[str, List[Dict[str, Any]]] = {}
        for event in events:
            slot_id = event.get("slot")
            if not slot_id or event.get("group") == "load" or event.get("kind") in ("context", "flag"):
                continue
            by_slot.setdefault(slot_id, []).append(event)
        patterns: Dict[str, Dict[str, Any]] = {}
        for slot_id, group_events in by_slot.items():
            top = max(group_events, key=lambda event: event["score"])
            kind = top.get("kind") or ""
            if kind == "ring":
                phrase = _ring_phrase(ch, slot_id, group_events, top)
            elif kind == "bank":
                phrase = "several" if len(group_events) >= 2 else "one_member"
            elif top.get("health") and top.get("shape") in ("flatline", "spikes", "saturated"):
                phrase = str(top.get("shape"))
            else:
                continue
            patterns[slot_id] = {
                "pattern": phrase,
                "shape": top.get("shape"),
                "top_channel": top.get("channel"),
                "label": top.get("slot_label") or labels.get(slot_id, slot_id),
            }
        top_slot = None
        coupled: List[str] = []
        if events:
            top_event = max(events, key=lambda event: event["score"])
            top_slot = top_event.get("slot")
            near = max(2 * PATCH, int(ch["R"].shape[0] // 50) if ch.get("R") is not None else 2 * PATCH)
            for slot_id, group_events in by_slot.items():
                if any(abs(event["onset_idx"] - top_event["onset_idx"]) <= near for event in group_events):
                    coupled.append(slot_id)
        return {"slot_patterns": patterns, "coupled_slots": coupled, "top_slot": top_slot}


    def channels(case: CaseData, profile: Any = None, resolved: Any = None) -> Dict[str, Any]:
        """Residual channels in physical units: names, groups, units, (n, C) residual, sigmas, masks, context.

        No profile: the fixed role builder. With a profile: one channel per resolved tag
        (``_profile_channels``). Callers that omit the profile keep today's output.
        """
        if profile is not None:
            return _profile_channels(case, profile, resolved)
        n = case.n
        load = _first_series(case, "load")
        if load is not None:
            p95 = np.nanpercentile(load, 95) if np.isfinite(load).any() else 0.0
            online = np.nan_to_num(load) >= 0.3 * p95 if p95 > 0 else np.ones(n, dtype=bool)
        else:
            p95, online = 0.0, np.ones(n, dtype=bool)
        first = np.zeros(n, dtype=bool)
        first[: max(10, int(0.3 * n))] = True
        base = online & first
        if base.sum() < 10:
            base = online.copy()
        names: List[str] = []
        groups: List[str] = []
        cols: List[np.ndarray] = []
        raw: List[Optional[np.ndarray]] = []
        ring_pos: List[Optional[int]] = []
        valid_masks: List[np.ndarray] = []
        used: set = set()

        def add(name: str, group: str, x: np.ndarray, r: Optional[np.ndarray] = None, pos: Optional[int] = None, online_only: bool = True,
                valid: Optional[np.ndarray] = None) -> None:
            """Function add."""
            x = np.nan_to_num(np.asarray(x, dtype=float))
            valid_masks.append(np.ones(n, dtype=bool) if valid is None else valid)
            if online_only:
                x = np.where(online, x, 0.0)
            names.append(name)
            groups.append(group)
            cols.append(x)
            raw.append(r)
            ring_pos.append(pos)

        ring_cols = _ring_order([c for c in case.ring if c in case.df.columns])
        zone_cols = _ring_order([c for c in case.zones if c in case.df.columns])
        tcols = ring_cols if len(ring_cols) >= 3 else (zone_cols if len(zone_cols) >= 2 else [])
        layout = "ring" if tcols and tcols is ring_cols else ("zones" if tcols else "none")
        used.update(tcols)
        if tcols:
            T = _ffill(np.column_stack([case.series(c) for c in tcols]))
            dev = T - np.nanmedian(T, axis=1)[:, None]
            off = np.nanmedian(dev[base], axis=0) if base.sum() > 10 else np.nanmedian(dev, axis=0)
            dev = dev - off
            for i, c in enumerate(tcols):
                add(c, "exhaust", dev[:, i], case.series(c), pos=i)
        sp = _first_series(case, "spread")
        if sp is not None:
            used.update(_cols(case, "spread")[:1])
            add(_cols(case, "spread")[0], "spread", sp - np.nanmedian(sp[base]) if base.any() else sp)
        ea = _first_series(case, "egt_avg")
        if ea is not None:
            used.update(_cols(case, "egt_avg")[:1])
            r_, v_ = _load_fit(ea, load, online, base)
            add(_cols(case, "egt_avg")[0], "egt", r_, valid=v_)
        dyn = _first_series(case, "dynamics")
        if dyn is not None:
            used.update(_cols(case, "dynamics")[:1])
            add(_cols(case, "dynamics")[0], "dynamics", dyn - np.nanmedian(dyn[base]) if base.any() else dyn, case.series(_cols(case, "dynamics")[0]))
        for c in _cols(case, "vibration"):
            used.add(c)
            v = _ffill(case.series(c)[:, None])[:, 0]
            add(c, "vibration", v - np.nanmedian(v[base]) if base.any() else v, case.series(c))
        fuel = _first_series(case, "fuel")
        if fuel is not None:
            used.update(_cols(case, "fuel")[:1])
            r_, v_ = _load_fit(fuel, load, online, base)
            add(_cols(case, "fuel")[0], "fuel", r_, valid=v_)
        igv = _first_series(case, "igv")
        if igv is not None:
            used.update(_cols(case, "igv")[:1])
            r_, v_ = _load_fit(igv, load, online, base)
            add(_cols(case, "igv")[0], "igv", r_, valid=v_)
        trip_cols = _cols(case, "trip")
        used.update(trip_cols)
        if load is not None:
            used.update(_cols(case, "load")[:1])
        for c in case.numeric_columns:
            if c in used or case.df[c].notna().sum() <= 10:
                continue
            x = _ffill(case.series(c)[:, None])[:, 0]
            if np.nanstd(x) < 1e-9:
                continue
            r_, v_ = _load_fit(x, load, online, base, gate=True)
            add(c, "other", r_, valid=v_)
        if load is not None:
            add(_cols(case, "load")[0], "load", load - np.nanmedian(load[base]) if base.any() else load, load, online_only=False)
        # Load transients: a static load fit cannot follow ramps (lags), so residuals of load-dependent
        # channels are not trusted while the load is moving by more than 5 % of its 95th percentile.
        moving = np.zeros(n, dtype=bool)
        if load is not None and p95 > 0:
            lf = _ffill(load[:, None])[:, 0]
            w = max(3, case.samples(60))
            ref = pd.Series(lf).rolling(w, min_periods=1).median().to_numpy()
            moving = np.abs(lf - ref) > 0.05 * p95
            moving = pd.Series(moving.astype(float)).rolling(2 * w + 1, center=True, min_periods=1).max().to_numpy() > 0
        trip = np.zeros(n, dtype=bool)
        if trip_cols:
            trip = np.nan_to_num(np.column_stack([case.series(c) for c in trip_cols])).max(axis=1) > 0.5
        R = np.column_stack(cols) if cols else np.zeros((n, 0))
        sig = np.array([_sigma(R[:, i], base, _FLOOR.get(g, 1e-6)) for i, g in enumerate(groups)])
        return {
            "names": names, "groups": groups, "units": [_unit(c, g) for c, g in zip(names, groups)], "R": R, "sigma": sig, "raw": raw,
            "ring_pos": ring_pos, "layout": layout, "n_ring": len(tcols), "online": online, "base": base, "trip": trip, "load_moving": moving, "valid": valid_masks,
            "load": load, "igv": igv, "fuel": fuel, "load_p95": float(p95),
        }


    # ----------------------------------------------------------------------------------- scoring


    def _rolling_median(x: np.ndarray, w: int) -> np.ndarray:
        """Function _rolling_median."""
        return pd.DataFrame(x).rolling(w, center=True, min_periods=1).median().to_numpy()


    def _frozen(raw: Optional[np.ndarray], online: np.ndarray, base: np.ndarray, w: int, min_len: int) -> np.ndarray:
        """Online stretches where the sensor shows no noise at all (flatline / frozen value). ``raw`` keeps
        historian gaps as NaN, so a forward-filled gap is not mistaken for a frozen sensor."""
        out = np.zeros(len(online), dtype=bool)
        if raw is None:
            return out
        sd = pd.Series(raw).rolling(w, min_periods=w, center=True).std().to_numpy()
        ref = sd[base & np.isfinite(sd)]
        if ref.size < 10:
            return out
        typ = float(np.median(ref))
        if typ <= 1e-9:
            return out
        flat = np.nan_to_num(sd, nan=typ) < 0.05 * typ
        flat &= online
        for a, b in _runs(flat, 1):
            if b - a + 1 >= min_len:
                out[a : b + 1] = True
        return out


    def _runs(mask: np.ndarray, max_gap: int) -> List[Tuple[int, int]]:
        """Function _runs."""
        idx = np.flatnonzero(mask)
        if idx.size == 0:
            return []
        out = []
        a = p = int(idx[0])
        for i in idx[1:]:
            i = int(i)
            if i - p > max_gap:
                out.append((a, p))
                a = i
            p = i
        out.append((a, p))
        return out


    def thresholds_for(t: Optional[Dict[str, float]] = None) -> Dict[str, float]:
        """Function thresholds_for."""
        out = dict(THRESHOLDS)
        out.update({k: float(v) for k, v in (t or {}).items()})
        return out


    def score(case: CaseData, settings: Any = None, thresholds: Optional[Dict[str, float]] = None, model: Any = "auto",
              profile: Any = None, resolved: Any = None) -> Dict[str, Any]:
        """Full residual analysis of one case (see module docstring). ``model``: ReconModel, None or "auto";
        ``thresholds``: per-group abnormal levels (default THRESHOLDS, calibrated: calibration.json).

        ``profile`` selects the per-slot residual. Omit it and the role builder runs, which is what
        every existing caller does.
        """
        thr = _thresholds_for_profile(thresholds_for(thresholds), profile, thresholds)
        abnormal = ABNORMAL
        ch = channels(case, profile, resolved)
        n, C = ch["R"].shape
        why = ""
        if isinstance(model, str):
            model, why = load_model(settings) if settings is not None else (None, "robust-z residual (no settings given)")
        elif model is not None:
            why = model.description
        else:
            why = why or "robust-z residual fallback"
        res: Dict[str, Any] = {"version": VERSION, "mode": "tspulse" if model is not None else "robust_z", "engine": why, "n_channels": C,
                               "layout": ch["layout"], "abnormal_threshold": abnormal, "thresholds": thr}
        if C == 0 or n < 20:
            res.update(channels=[], events=[], profile=None, pattern={"ring": "none"}, description="Residuals: not enough data.", max_score=0.0)
            return res
        R, sig, online, base = ch["R"], ch["sigma"], ch["online"], ch["base"]
        Zl = np.clip(R / sig[None, :], -1000, 1000)
        Zc = np.clip(Zl, -50, 50)
        if model is not None:
            try:
                Zt = Zc - model.reconstruct(Zc)
            except Exception as exc:  # noqa: BLE001 — degrade, never break the report
                log.warning("TS Pulse residual failed: %s", exc)
                res.update(mode="robust_z", engine=f"robust-z residual fallback (TS Pulse residual failed: {type(exc).__name__})")
                Zt = Zc - _rolling_median(Zc, 2 * PATCH + 1)
        else:
            Zt = Zc - _rolling_median(Zc, 2 * PATCH + 1)
        ref = Zt[base] if base.sum() > 20 else Zt
        tscale = np.maximum(1.4826 * np.median(np.abs(ref - np.median(ref, axis=0)), axis=0), 0.25)
        T = Zt / tscale[None, :]
        S = np.maximum(np.abs(T), np.abs(Zl))
        w, min_len = max(6, case.samples(60)), max(6, case.samples(120))
        frozen = np.zeros_like(S, dtype=bool)
        kinds = ch.get("kinds")
        health = ch.get("health")
        fits = ch.get("load_fit")
        for i, g in enumerate(ch["groups"]):
            # The role builder freezes exhaust, dynamics and vibration. A profile slot with health set
            # does the same for a ring, a bank or a process tag that is not one of those groups.
            if g in ("exhaust", "dynamics", "vibration") or (
                kinds is not None and health is not None and health[i] and kinds[i] in ("ring", "bank", "process")
            ):
                frozen[:, i] = _frozen(ch["raw"][i], online, base, w, min_len)
        S = np.where(frozen, np.maximum(S, FROZEN_SCORE), S)
        for i, g in enumerate(ch["groups"]):
            if g != "load":
                S[~online, i] = 0.0
            if g in ("igv", "fuel", "egt", "other") or (fits is not None and fits[i]):
                bad = ch["load_moving"] | ~ch["valid"][i]
                S[bad, i] = np.minimum(S[bad, i], 2.0)
        k = max(3, int(math.ceil(0.002 * n)))
        part = np.sort(S, axis=0)[-k] if n >= k else S.max(axis=0)
        chans: List[Dict[str, Any]] = []
        for i, name in enumerate(ch["names"]):
            row = {"channel": name, "group": ch["groups"][i], "unit": ch["units"][i], "score": round(float(part[i]), 1),
                   "abnormal": bool(ch["groups"][i] != "load" and part[i] >= thr.get(ch["groups"][i], abnormal)),
                   "sigma": _round(float(sig[i]), ch["units"][i]), "transient_peak": round(float(np.max(np.abs(T[:, i]))), 1),
                   "level_peak": round(float(np.max(np.abs(Zl[:, i]))), 1), "frozen": bool(frozen[:, i].any())}
            if ch.get("slots") is not None:
                row["slot"] = ch["slots"][i]
                row["kind"] = ch["kinds"][i]
            chans.append(row)
        events = []
        for i in np.argsort(-part):
            g = ch["groups"][i]
            if g == "load" or part[i] < thr.get(g, abnormal):
                continue
            ev = _event(case, ch, i, S[:, i], thr.get(g, abnormal), frozen[:, i])
            if ev:
                events.append(ev)
        events.sort(key=lambda e: (e["onset_idx"], -e["score"]))
        t0 = events[0]["onset_idx"] if events else 0
        for e in events:
            e["minutes_after_first"] = round((e["onset_idx"] - t0) * case.minutes_per_sample)
        for e in events:
            if e["group"] == "exhaust" or e.get("kind") == "ring":
                e["neighbours"] = _neighbours(case, ch, e)
        ctx = _context(case, ch, events)
        pattern = _pattern(ch, events, chans)
        ordered = sorted(chans, key=lambda c: -c["score"])
        if ch.get("slots") is not None:
            seen: List[str] = []
            for channel in ordered:
                slot_id = channel.get("slot")
                if channel.get("abnormal") and slot_id and slot_id not in seen and channel.get("group") != "load" and channel.get("kind") not in ("context", "flag"):
                    seen.append(slot_id)
            res["slots_abnormal"] = seen
            res["slot_labels"] = dict(ch.get("slot_labels") or {})
        res.update(
            channels=ordered,
            events=events[: 2 * MAX_EVENTS],
            context=ctx,
            pattern=pattern,
            max_score=round(float(max([c["score"] for c in chans if c["group"] != "load"], default=0.0)), 1),
            groups_abnormal=_group_max(chans, thr),
            profile=_profile(case, ch, S, chans),
        )
        res["description"] = describe(res)
        return res


    def _round(v: float, unit: str) -> float:
        """Function _round."""
        return round(float(v), _DECIMALS.get(unit, 3))


    def _group_max(chans: List[Dict[str, Any]], thr: Dict[str, float]) -> Dict[str, float]:
        """Function _group_max."""
        out: Dict[str, float] = {}
        for c in chans:
            if c["group"] != "load" and c["score"] >= thr.get(c["group"], ABNORMAL):
                out[c["group"]] = max(out.get(c["group"], 0.0), c["score"])
        return out


    def signed_guess(delta: float, peak: float) -> float:
        """Function signed_guess."""
        return delta if abs(delta) >= 0.3 * abs(peak) else peak


    def _event(case: CaseData, ch: Dict[str, Any], i: int, s: np.ndarray, abnormal: float, frozen: np.ndarray) -> Optional[Dict[str, Any]]:
        """First abnormal episode of channel i: onset (refined on the physical signal), size, shape, duration."""
        on_thr = max(3.0, 0.5 * abnormal)
        gap = max(2, case.samples(30))
        # contiguous runs first: a lone noise blip (one sample, below the abnormal level) is not an onset
        keep = np.zeros(len(s), dtype=bool)
        for a, b in _runs(s >= on_thr, 1):
            if b > a or s[a] >= abnormal:
                keep[a : b + 1] = True
        runs = [(a, b) for a, b in _runs(keep, gap) if s[a : b + 1].max() >= abnormal]
        if not runs:
            return None
        long_gap = max(gap, case.samples(12 * 60))
        a, b = runs[0]
        bursts = 1
        for a2, b2 in runs[1:]:
            if a2 - b > long_gap:
                break
            b = b2
            bursts += 1
        r = ch["R"][:, i]
        unit = ch["units"][i]
        sg = float(ch["sigma"][i])
        W = max(6, case.samples(120))
        # The masked reconstruction smears a step over the neighbouring patch: take the reference level
        # before that, then find the onset on the physical residual itself.
        pre_end = max(0, a - PATCH)
        pre = r[max(0, pre_end - W) : pre_end]
        pre_med = float(np.median(pre)) if pre.size else 0.0
        seg = r[a : b + 1] - pre_med
        delta = float(np.median(seg)) if seg.size else 0.0
        j = int(np.argmax(np.abs(seg))) if seg.size else 0
        peak = float(seg[j]) if seg.size else 0.0
        size = abs(delta) if abs(delta) >= 0.3 * abs(peak) else abs(peak)
        thr = max(3 * sg, 0.25 * size)
        lo = max(0, a - 2 * PATCH)
        dev = np.abs(r[lo : b + 1] - pre_med)
        if abs(delta) >= 0.3 * abs(peak):  # sustained change: ignore single noisy samples
            dev = _rolling_median(dev[:, None], 3)[:, 0]
        hit = np.flatnonzero(dev >= thr)
        if hit.size:
            a = lo + int(hit[0])
            seg = r[a : b + 1] - pre_med
            if abs(delta) >= 0.3 * abs(peak):
                delta = float(np.median(seg))
        if abs(delta) >= 0.3 * abs(peak) and abs(delta) >= 3 * sg and abs(r[a] - pre_med) < 0.5 * abs(delta):
            # slow drift (still far from its final size at the detected onset): the threshold is crossed
            # late; walk back on a trailing median to where it left its baseline band
            base_lvl = float(np.median(r[ch["base"]])) if ch["base"].any() else 0.0
            sm = pd.Series(np.abs(r - base_lvl)).rolling(max(3, case.samples(60)), min_periods=1).median().to_numpy()
            k, lim = a, max(0, a - case.samples(7 * 24 * 60))
            while k > lim and sm[k - 1] > 1.5 * sg and np.sign(r[k - 1] - base_lvl) == np.sign(delta):
                k -= 1
            if k < a - 2:
                a = k
                pre = r[max(0, a - W) : a]
                pre_med = float(np.median(pre)) if pre.size else base_lvl
                seg = r[a : b + 1] - pre_med
                delta = float(np.median(seg[len(seg) // 2 :])) if seg.size > 1 else delta
                j = int(np.argmax(np.abs(seg))) if seg.size else 0
                peak = float(seg[j]) if seg.size else peak
        ramp_n = None
        if abs(delta) >= 3 * sg:
            h = np.flatnonzero(np.abs(seg) >= 0.8 * abs(delta))
            ramp_n = int(h[0]) + 1 if h.size else None
        seg_rel = seg - np.median(seg) if seg.size else seg
        big = np.abs(seg_rel) > 3 * sg
        frac = float(big.mean()) if seg.size else 0.0
        crossings = int(np.sum(np.diff(np.sign(seg_rel[big])) != 0)) if big.sum() > 2 else 0
        rw = ch["raw"][i]
        sat = False
        kind_i = ch["kinds"][i] if ch.get("kinds") is not None else ""
        health_i = bool(ch["health"][i]) if ch.get("health") is not None else False
        # Health on a profile slot gets the same flatline / spike / saturation test the exhaust ring has.
        sensor_health = ch["groups"][i] in ("exhaust", "dynamics", "vibration") or (health_i and kind_i in ("ring", "bank", "process"))
        if rw is not None and b > a + 3 and sensor_health:
            seg_raw = rw[a : b + 1]
            before = rw[max(0, a - W) : a]
            if np.isfinite(seg_raw).sum() > 3 and np.isfinite(before).any():
                ext = np.nanmax(seg_raw) if signed_guess(delta, peak) >= 0 else np.nanmin(seg_raw)
                sat = bool(np.mean(np.isclose(seg_raw, ext, atol=1e-9)) > 0.2) and abs(ext - float(np.nanmedian(before))) > 6 * sg
        if frozen[a : b + 1].any() and abs(delta) < 0.5 * abs(peak) + 3 * sg:
            shape = "flatline"
        elif sat:
            shape = "saturated"
        elif crossings >= 6 and frac > 0.3 and abs(delta) < 0.5 * abs(peak):
            shape = "oscillation"
        elif abs(delta) < 0.3 * abs(peak) or (bursts >= 3 and abs(delta) < 0.5 * abs(peak)):
            shape = "spikes"
        elif ramp_n is not None and ramp_n <= 2:
            shape = "step"
        elif ramp_n is not None:
            shape = "ramp"
        else:
            shape = "excursion"
        signed = delta if (shape not in ("spikes", "oscillation") or abs(delta) > 0.3 * abs(peak)) else peak
        direction = "up" if signed > 0 else "down"
        ongoing = b >= case.n - 1 - gap
        out = {
            "channel": ch["names"][i],
            "group": ch["groups"][i],
            "unit": unit,
            "ring_pos": ch["ring_pos"][i],
            "score": round(float(s.max()), 1),
            "onset_idx": int(a),
            "onset": case.time_at(int(a)),
            "end": case.time_at(int(b)),
            "duration_min": round((b - a + 1) * case.minutes_per_sample),
            "ongoing": bool(ongoing),
            "direction": direction,
            "delta": _round(delta, unit),
            "peak": _round(peak, unit),
            "ramp_min": round(ramp_n * case.minutes_per_sample) if ramp_n else None,
            "shape": shape,
            "bursts": bursts,
        }
        if ch.get("slots") is not None:
            out["slot"] = ch["slots"][i]
            out["kind"] = ch["kinds"][i]
            out["health"] = bool(ch["health"][i]) if ch.get("health") is not None else False
            label = (ch.get("slot_labels") or {}).get(out["slot"])
            if label:
                out["slot_label"] = label
        return out


    def _neighbours(case: CaseData, ch: Dict[str, Any], e: Dict[str, Any]) -> Dict[str, Any]:
        """Did the adjacent TCs / zones move with this one over the same window? (ratio of their change to its change)"""
        # No profile: one ring, positions compared as before. A profile keeps each ring's own positions,
        # so two rings that both number from zero do not become each other's neighbours.
        if ch.get("slots") is None:
            pos = [p for p in ch["ring_pos"] if p is not None]
        else:
            slot0 = ch["slots"][ch["names"].index(e["channel"])]
            pos = [p for p, slot in zip(ch["ring_pos"], ch["slots"]) if p is not None and slot == slot0]
        m = len(pos)
        i0 = ch["names"].index(e["channel"])
        p0 = ch["ring_pos"][i0]
        if p0 is None or m < 3:
            return {}
        if ch.get("slots") is None:
            by_pos = {p: k for k, p in enumerate(ch["ring_pos"]) if p is not None}
        else:
            by_pos = {p: k for k, (p, slot) in enumerate(zip(ch["ring_pos"], ch["slots"])) if p is not None and slot == slot0}
        a = e["onset_idx"]
        b = a + max(1, int(round(e["duration_min"] / case.minutes_per_sample))) - 1
        W = max(6, case.samples(120))
        R = ch["R"]

        def change(k: int) -> float:
            """Function change."""
            pre = R[max(0, a - W) : a, k]
            seg = R[a : b + 1, k]
            if not seg.size:
                return 0.0
            base = float(np.median(pre)) if pre.size else 0.0
            if e["shape"] in ("spikes", "oscillation"):
                j = int(np.argmax(np.abs(R[a : b + 1, i0] - base)))
                return float(seg[j] - base)
            return float(np.median(seg) - base)

        own = change(i0)
        ref = own if abs(own) >= 0.3 * abs(e["peak"]) else e["peak"]
        out: Dict[str, Any] = {}
        for side, q in (("left", (p0 - 1) % m), ("right", (p0 + 1) % m)):
            k = by_pos.get(q)
            if k is None or k == i0:
                continue
            d = change(k)
            ratio = d / ref if abs(ref) > 1e-9 else 0.0
            if abs(d) < 2 * ch["sigma"][k] or abs(ratio) < 0.2:
                label = "flat"
            elif ratio >= 0.5:
                label = "followed"
            elif ratio >= 0.2:
                label = "partially followed"
            else:
                label = "moved opposite"
            unit = "C" if ch.get("slots") is None else (e.get("unit") or "C")
            out[side] = {"channel": ch["names"][k], "change": _round(d, unit), "ratio": round(ratio, 2), "label": label}
        labels = [v["label"] for v in out.values()]
        if labels and all(x == "flat" for x in labels):
            out["summary"] = "neighbours did not follow (single sensor)"
        elif any(x == "followed" for x in labels):
            out["summary"] = "neighbours followed (sector)"
        elif any(x == "partially followed" for x in labels):
            out["summary"] = "neighbours partially followed"
        else:
            out["summary"] = "neighbours moved opposite"
        return out


    def _context(case: CaseData, ch: Dict[str, Any], events: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Load / IGV / fuel around the first main event, trip timing."""
        out: Dict[str, Any] = {}
        trip = np.flatnonzero(ch["trip"])
        if trip.size:
            out["trip"] = case.time_at(int(trip[0]))
            out["trip_idx"] = int(trip[0])
        main = max((e for e in events if e["group"] != "load"), key=lambda e: e["score"], default=None)
        if main is None:
            return out
        out["main"] = main["channel"]
        out["main_onset"] = main["onset"]
        a = main["onset_idx"]
        b = min(case.n - 1, a + max(1, int(round(main["duration_min"] / case.minutes_per_sample))) - 1)
        if trip.size and trip[0] > a:
            b = min(b, int(trip[0]) - 1)  # before the trip; the trip itself drops everything
            out["minutes_onset_to_trip"] = round((int(trip[0]) - a) * case.minutes_per_sample)
        W = max(6, case.samples(120))
        for key, unit, rel in (("load", "MW", True), ("igv", "deg", False), ("fuel", "", True)):
            x = ch.get(key)
            if x is None:
                continue
            pre = x[max(0, a - W) : a]
            seg = x[a : b + 1]
            if not pre.size or not seg.size:
                continue
            p, q = float(np.nanmedian(pre)), float(np.nanmedian(seg))
            d = q - p
            if key == "fuel":
                pct = 100.0 * d / p if abs(p) > 1e-9 else 0.0
                out["fuel"] = {"change_pct": round(pct, 1), "steady": abs(pct) < 3.0}
            elif key == "load":
                scale = max(1.0, 0.03 * ch["load_p95"])
                out["load"] = {"at_onset": round(p, 1), "change": round(d, 1), "steady": abs(d) < scale}
            else:
                out["igv"] = {"at_onset": round(p, 1), "change": round(d, 2), "steady": abs(d) < 1.0}
        if out.get("load") and ch["load"] is not None and main["group"] == "exhaust":
            x = ch["R"][a : b + 1, ch["names"].index(main["channel"])]
            y = ch["load"][a : b + 1]
            if x.size > 5 and np.nanstd(y) > 1e-6 and np.nanstd(x) > 1e-9:
                out["load"]["corr_with_main"] = round(float(np.corrcoef(x, y)[0, 1]), 2)
        if "spread" not in [e["group"] for e in events[:1]]:
            sp = next((e for e in events if e["group"] == "spread"), None)
            if sp is not None:
                out["spread_after_first_min"] = sp["minutes_after_first"]
        return out


    def _pattern(ch: Dict[str, Any], events: List[Dict[str, Any]], chans: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Function _pattern."""
        exh = [e for e in events if e["group"] == "exhaust"]
        pat: Dict[str, Any] = {"ring": "none", "abnormal_groups": sorted({e["group"] for e in events})}
        if exh:
            top = max(exh, key=lambda e: e["score"])
            nb = top.get("neighbours") or {}
            pos = sorted(e["ring_pos"] for e in exh if e["ring_pos"] is not None)
            m = ch["n_ring"]
            same_dir = [e for e in exh if e["direction"] == top["direction"]]
            adjacent = 0
            if top["ring_pos"] is not None and m:
                occupied = {e["ring_pos"] for e in same_dir}
                p = top["ring_pos"]
                adjacent = 1
                for step in (1, -1):
                    q = (p + step) % m
                    while q in occupied and adjacent < m:
                        adjacent += 1
                        q = (q + step) % m
            followed = nb.get("summary", "").startswith("neighbours followed") or nb.get("summary", "").startswith("neighbours partially")
            # >= 100 C from the ring median on one TC is implausible for combustion (cold sectors are tens of C)
            sensor_like = top["shape"] in ("flatline", "spikes", "saturated") or abs(top["peak"]) >= 100
            near = max(2 * PATCH, ch["R"].shape[0] // 50)

            def ring_dist(e: Dict[str, Any]) -> int:
                """Function ring_dist."""
                if top["ring_pos"] is None or e["ring_pos"] is None or not m:
                    return 99
                return min((e["ring_pos"] - top["ring_pos"]) % m, (top["ring_pos"] - e["ring_pos"]) % m)

            concurrent = [e for e in exh if e is not top and abs(e["onset_idx"] - top["onset_idx"]) <= near and ring_dist(e) > 1]
            hot_cold = any(e["direction"] != top["direction"] for e in exh if abs(e["onset_idx"] - top["onset_idx"]) <= near)
            if adjacent >= 2 or followed:
                ring = "sector"
            elif concurrent:
                ring = "multiple"
            else:
                ring = "single_sensor"
            pat.update(ring=ring, top_sensor=top["channel"], top_shape=top["shape"], top_direction=top["direction"], top_delta=top["delta"], top_peak=top["peak"], hot_cold=bool(hot_cold),
                       adjacent_abnormal=adjacent, sensor_like=bool(sensor_like), n_exhaust_abnormal=len(exh),
                       isolated_others=len([p_ for p_ in pos if top["ring_pos"] is not None and min((p_ - top["ring_pos"]) % m, (top["ring_pos"] - p_) % m) > max(1, adjacent)]))
        dyn = [e for e in events if e["group"] == "dynamics"]
        if dyn:
            d0 = dyn[0]
            others = [e for e in events if e["group"] in ("exhaust", "vibration", "fuel", "spread", "egt") and abs(e["onset_idx"] - d0["onset_idx"]) <= max(3, ch["R"].shape[0] // 50)]
            pat["dynamics"] = "coupled" if others else "alone"
            pat["dynamics_shape"] = d0["shape"]
        if ch.get("kinds"):
            pat.update(_profile_patterns(ch, events))
        return pat


    def _profile(case: CaseData, ch: Dict[str, Any], S: np.ndarray, chans: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Per-time residual profile of the highest-scoring channels (binned, for the UI heatmap)."""
        n = S.shape[0]
        order = [ch["names"].index(c["channel"]) for c in chans if c["group"] != "load"][:MAX_CHANNELS_PROFILE]
        bins = min(PROFILE_BINS, n)
        edges = np.linspace(0, n, bins + 1).astype(int)
        M = np.zeros((len(order), bins))
        for b in range(bins):
            seg = S[edges[b] : max(edges[b + 1], edges[b] + 1)]
            M[:, b] = seg[:, order].max(axis=0) if len(order) else 0.0
        overall = S[:, [i for i, g in enumerate(ch["groups"]) if g != "load"]].max(axis=1) if S.shape[1] else np.zeros(n)
        ov = [float(overall[edges[b] : max(edges[b + 1], edges[b] + 1)].max()) for b in range(bins)]
        return {"channels": [ch["names"][i] for i in order], "times": [case.time_at(int(edges[b])) for b in range(bins)],
                "matrix": np.round(np.clip(M, 0, 99), 1).tolist(), "overall": [round(min(v, 99.0), 1) for v in ov]}


    # ----------------------------------------------------------------------------------- text


    def _dur(minutes: Optional[float]) -> str:
        """Function _dur."""
        if minutes is None:
            return "?"
        m = float(minutes)
        if m < 120:
            return f"{m:.0f} min"
        if m < 72 * 60:
            return f"{m / 60:.1f} h"
        return f"{m / 1440:.1f} d"


    def _num(v: float, unit: str) -> str:
        """Function _num."""
        d = _DECIMALS.get(unit, 3)
        return f"{abs(v):.{d}f}{(' ' + unit) if unit else ''}"


    def event_text(e: Dict[str, Any]) -> str:
        """Function event_text."""
        verb = {"step": "stepped", "ramp": "ramped", "excursion": "moved", "spikes": "spiked", "flatline": "froze (flatline)", "oscillation": "oscillated",
                "saturated": "saturated (pinned at one value)"}[e["shape"]]
        if e.get("slot_label"):
            label = f"{e['slot_label']} {e['channel']}"
        else:
            label = e["channel"] if e["group"] in ("exhaust", "vibration", "other") else f"{e['channel']} ({e['group']})"
        if e["shape"] in ("spikes", "oscillation"):
            size = f" peak {'+' if e['peak'] > 0 else '-'}{_num(e['peak'], e['unit'])}"
        elif e["shape"] == "flatline":
            size = ""
        elif e["shape"] == "saturated":
            size = f" {'+' if e['peak'] > 0 else '-'}{_num(e['peak'], e['unit'])} above its earlier level" if e["peak"] > 0 else f" {_num(e['peak'], e['unit'])} below its earlier level"
        else:
            size = f" {e['direction']} {_num(e['delta'], e['unit'])}"
        ramp = f" over {_dur(e['ramp_min'])}" if e.get("ramp_min") and e["shape"] in ("step", "ramp") else ""
        dur = "ongoing at end of record" if e["ongoing"] else f"lasted {_dur(e['duration_min'])}"
        s = f"{label} {verb}{size}{ramp} from {e['onset']} ({dur})"
        nb = e.get("neighbours") or {}
        if nb.get("summary"):
            parts = [f"{v['channel']} {v['label']} ({v['ratio']:+.2f})" for k, v in nb.items() if k in ("left", "right")]
            s += f"; neighbours {', '.join(parts)}: {nb['summary'].split('(')[-1].rstrip(')') if '(' in nb['summary'] else nb['summary']}"
        return s


    def describe(res: Dict[str, Any], n_events: int = 4) -> str:
        """Compact engineering description for the LLM prompt (bounded: top events only)."""
        ev = res.get("events") or []
        eng = "TS Pulse reconstruction" if res.get("mode") == "tspulse" else "robust-z (TS Pulse residual model unavailable)"
        if not ev:
            return f"Residuals ({eng}, {res.get('n_channels', 0)} channels): no channel abnormal (highest score {res.get('max_score', 0):.1f}; abnormal from {ABNORMAL:.1f})."
        t = res.get("thresholds") or THRESHOLDS
        hi = ", ".join(f"{g} {v:.1f}" for g, v in t.items() if v > ABNORMAL)
        lines = [f"Residuals ({eng}, {res.get('n_channels', 0)} channels; score = robust peak in baseline sigmas, abnormal >= {ABNORMAL:.1f}"
                 + (f"; {hi}" if hi else "") + "). Onset order:"]
        for k, e in enumerate(ev[:n_events], 1):
            lag = f" [+{_dur(e['minutes_after_first'])}]" if k > 1 and e.get("minutes_after_first") else (" [same time]" if k > 1 else "")
            lines.append(f"{k}. {event_text(e)}{lag}; score {e['score']:.1f}.")
        if len(ev) > n_events:
            lines.append(f"(+{len(ev) - n_events} more abnormal channels: {', '.join(e['channel'] for e in ev[n_events:n_events + 4])})")
        c = res.get("context") or {}
        ctx = []
        if c.get("load"):
            L = c["load"]
            ctx.append(f"load steady at {L['at_onset']:.1f} MW (change {L['change']:+.1f} MW)" if L["steady"] else f"load changed {L['change']:+.1f} MW from {L['at_onset']:.1f} MW")
        if c.get("igv"):
            ctx.append("IGV steady" if c["igv"]["steady"] else f"IGV changed {c['igv']['change']:+.2f} deg")
        if c.get("fuel"):
            ctx.append("fuel steady" if c["fuel"]["steady"] else f"fuel changed {c['fuel']['change_pct']:+.1f} %")
        if c.get("trip"):
            ctx.append(f"trip at {c['trip']}" + (f", {_dur(c['minutes_onset_to_trip'])} after that onset" if c.get("minutes_onset_to_trip") is not None else ""))
        else:
            ctx.append("no trip")
        lines.append(f"Around the strongest onset ({c.get('main', '?')} at {c.get('main_onset', '?')}): " + "; ".join(ctx) + ".")
        p = res.get("pattern") or {}
        if p.get("ring") and p["ring"] != "none":
            lines.append(f"Exhaust pattern: {p['ring'].replace('_', ' ')} ({p.get('adjacent_abnormal', 0)} adjacent sensor(s) abnormal, top {p.get('top_sensor')} {p.get('top_shape')}).")
        if p.get("dynamics"):
            lines.append(f"Dynamics: {p['dynamics']} ({p.get('dynamics_shape')}).")
        slot_patterns = p.get("slot_patterns") or {}
        if slot_patterns:
            bits = [f"{info.get('label', sid)} {info.get('top_channel')} {str(info.get('pattern', '')).replace('_', ' ')}" for sid, info in slot_patterns.items()]
            lines.append("Slot patterns: " + "; ".join(bits) + ".")
        coupled = p.get("coupled_slots") or []
        if len(coupled) >= 2:
            labels = res.get("slot_labels") or {}
            lines.append("Slots that moved together: " + ", ".join(labels.get(sid, sid) for sid in coupled) + ".")
        return "\n".join(lines)


    # ----------------------------------------------------------------------------------- cross-check

    # What each signature should look like in the residuals: (primary groups that must be abnormal,
    # groups it can explain). Engineer-created signatures are not constrained.
    EXPECTED: Dict[str, Tuple[Sequence[str], Sequence[str]]] = {
        "normal": ((), ()),
        "cold_spot_hardware": (("exhaust",), ("exhaust", "spread", "egt", "fuel")),
        "tc_sensor_fault": (("exhaust",), ("exhaust", "spread", "egt")),
        "combustion_instability": (("dynamics",), ("dynamics", "exhaust", "spread", "egt", "vibration", "fuel")),
        "dynamics_probe_fault": (("dynamics",), ("dynamics",)),
        "hets_trip_hardware": (("exhaust", "spread"), ("exhaust", "spread", "egt", "vibration", "fuel", "igv", "other", "dynamics")),
        "igv_lvdt_drift": (("igv",), ("igv", "egt", "other")),
        "fuel_control_oscillation": (("fuel", "egt", "exhaust", "spread"), ("fuel", "egt", "exhaust", "spread", "dynamics", "other")),
    }
    PATTERN_TEXT: Dict[str, str] = {
        "normal": "no channel clearly abnormal",
        "cold_spot_hardware": "two or more adjacent exhaust TCs / zones cool together (sector), spread rises",
        "tc_sensor_fault": "one exhaust TC / zone moves alone (neighbours flat), or freezes, spikes or reads implausibly",
        "combustion_instability": "dynamics rise together with coupled exhaust / vibration / fuel movement",
        "dynamics_probe_fault": "the dynamics channel is abnormal alone (flatline, saturation, spikes), nothing coupled",
        "hets_trip_hardware": "a hot and a cold exhaust sector build up, then the unit trips",
        "igv_lvdt_drift": "IGV position departs from its load schedule; other channels steady",
        "fuel_control_oscillation": "fuel and load / exhaust oscillate together",
        "novel_pattern": "unlike any labeled case",
    }


    def _strong(res: Dict[str, Any]) -> Dict[str, float]:
        """Function _strong."""
        t = res.get("thresholds") or THRESHOLDS
        return {g: v for g, v in (res.get("groups_abnormal") or {}).items() if v >= STRONG * t.get(g, ABNORMAL)}


    def explained(signature: str, res: Dict[str, Any]) -> bool:
        """Is the residual pattern explained by the signature (its primary channels abnormal, top channel in its groups)?"""
        if signature not in EXPECTED:
            return True
        t = res.get("thresholds") or THRESHOLDS
        ga = {g: v / t.get(g, ABNORMAL) for g, v in (res.get("groups_abnormal") or {}).items() if g != "load"}
        primary, allowed = EXPECTED[signature]
        if not ga:
            return True
        if not primary:  # normal: nothing should be abnormal
            return False
        top = max(ga, key=ga.get)
        return any(g in ga for g in primary) and top in allowed


    def cross_check(signature: str, res: Dict[str, Any], profile: Any = None) -> Dict[str, Any]:
        """Deterministic residual cross-check of the predicted signature: supports | contradicts | inconclusive.

        With a profile, built-in rules run only when ``legacy_role`` maps every group they need.
        Otherwise ``residual_expect`` decides, and a signature with no entry is never contradicted.
        """
        if profile is not None and not _legacy_rules_apply(profile, signature):
            return _expect_check(signature, res, profile)
        p = res.get("pattern") or {}
        ga = res.get("groups_abnormal") or {}
        sg = _strong(res)
        strong = bool(sg)
        ring, dyn = p.get("ring", "none"), p.get("dynamics")
        v, why, points = "inconclusive", "", None
        zones_single = res.get("layout") == "zones" and ring == "single_sensor" and not p.get("sensor_like")
        if zones_single and signature in ("cold_spot_hardware", "tc_sensor_fault"):
            why = "zone layout: one zone averages a whole sector, so one cold zone cannot separate a sensor fault from a cold sector"
        elif signature == "cold_spot_hardware":
            if ring == "sector" and p.get("top_direction") == "down" and not p.get("sensor_like"):
                v, why = "supports", f"{p.get('adjacent_abnormal')} adjacent exhaust sensors cooled together ({p.get('top_sensor')} first)"
            elif ring == "single_sensor" and p.get("top_direction") == "down":
                v, why, points = "contradicts", f"{p.get('top_sensor')} cooled alone ({p.get('top_shape')}) while its neighbours stayed flat — a single-sensor pattern, not a cold sector", "tc_sensor_fault"
            elif ring != "none" and p.get("sensor_like"):
                more = f" and {p.get('adjacent_abnormal', 1) - 1} adjacent sensor(s)" if p.get("adjacent_abnormal", 1) > 1 else ""
                v, why, points = "contradicts", (f"{p.get('top_sensor')}{more} show a sensor-like signal ({p.get('top_shape')}, peak {p.get('top_peak')} C "
                                                 f"from the ring median): instrumentation (sensor / harness), not a combustion cold sector"), "tc_sensor_fault"
            else:
                why = "no clear cold exhaust sector in the residuals"
        elif signature == "tc_sensor_fault":
            if ring != "none" and p.get("sensor_like"):
                v, why = "supports", f"{p.get('top_sensor')} shows a sensor-like signal ({p.get('top_shape')}, peak {p.get('top_peak')} C from the ring median)"
            elif ring == "single_sensor":
                v, why = "supports", f"{p.get('top_sensor')} moved alone ({p.get('top_shape')}); neighbours did not follow"
            elif ring == "sector" and p.get("adjacent_abnormal", 0) >= 3 and not p.get("sensor_like"):
                v, why, points = "contradicts", f"{p.get('adjacent_abnormal')} adjacent exhaust sensors moved together (sector), not one sensor", "cold_spot_hardware"
            else:
                why = "exhaust residual pattern does not isolate one sensor clearly"
        elif signature == "combustion_instability":
            if dyn == "coupled":
                v, why = "supports", "dynamics rose together with coupled exhaust / vibration / fuel movement"
            elif dyn == "alone" and p.get("dynamics_shape") in ("flatline", "spikes", "saturated"):
                v, why, points = "contradicts", f"the dynamics channel is abnormal alone ({p.get('dynamics_shape')}) with nothing coupled — probe-like", "dynamics_probe_fault"
            elif not dyn and strong:
                v, why = "contradicts", "dynamics are not abnormal in the residuals although other channels are"
            else:
                why = "dynamics residual pattern is not decisive"
        elif signature == "dynamics_probe_fault":
            if dyn == "alone":
                v, why = "supports", f"dynamics abnormal alone ({p.get('dynamics_shape')}), nothing coupled"
            elif dyn == "coupled" and p.get("dynamics_shape") not in ("flatline", "spikes", "saturated"):
                v, why, points = "contradicts", "dynamics moved together with exhaust / vibration / fuel — a real combustion response, not a probe fault", "combustion_instability"
            else:
                why = "dynamics residual pattern is not decisive"
        elif signature == "hets_trip_hardware":
            trip = (res.get("context") or {}).get("trip")
            if trip and (ring == "sector" or p.get("hot_cold")):
                v, why = "supports", f"exhaust {'hot / cold split' if p.get('hot_cold') else 'sector'} pattern before the trip at {trip}"
            elif trip and ring == "single_sensor" and p.get("sensor_like"):
                v, why, points = "contradicts", f"only {p.get('top_sensor')} deviated before the trip, with a sensor-like signal", "tc_sensor_fault"
            else:
                why = "trip / sector evidence in the residuals is not decisive"
        elif signature == "igv_lvdt_drift":
            if "igv" in ga:
                v, why = "supports", "IGV position departs from its load schedule"
            elif strong:
                v, why = "contradicts", "IGV residual is normal while other channels are clearly abnormal"
            else:
                why = "IGV residual is not decisive"
        elif signature == "fuel_control_oscillation":
            if "fuel" in ga or any(e["shape"] == "oscillation" for e in (res.get("events") or [])):
                v, why = "supports", "fuel / load residuals oscillate"
            else:
                why = "no fuel / load oscillation in the residuals"
        elif signature == "normal":
            if not ga:
                v, why = "supports", "no channel is clearly abnormal in the residuals"
            elif strong:
                top = next((e for e in res.get("events") or []), None)
                top = max((e for e in res.get("events") or [] if e["group"] in sg), key=lambda e: e["score"], default=top)
                v, why = "contradicts", f"residuals are clearly abnormal ({top['channel'] if top else '?'} score {top['score'] if top else res.get('max_score', 0):.1f})"
            else:
                why = "only mildly abnormal residuals"
        else:
            why = "no expected residual pattern defined for this signature"
        return {"verdict": v, "reason": why, "points_to": points, "expected": PATTERN_TEXT.get(signature, "not defined")}


    def summary(res: Dict[str, Any]) -> Dict[str, Any]:
        """Small dict for novelty / storage (no profile)."""
        return {k: res.get(k) for k in ("mode", "max_score", "groups_abnormal", "pattern", "thresholds")}


    def calibrate_thresholds(results: Sequence[Dict[str, Any]], truths: Sequence[str], q: float = 0.99, margin: float = 1.1) -> Dict[str, Any]:
        """Per-group abnormal thresholds from held-out cases: for every case, the channel groups its true
        signature does not touch are a sample of 'normal' scores; threshold = max(ABNORMAL, margin x q-quantile)."""
        null: Dict[str, List[float]] = {}
        for res, sig in zip(results, truths):
            allowed = set(EXPECTED.get(sig, ((), ()))[1]) if sig in EXPECTED else None
            if allowed is None:
                continue
            per: Dict[str, float] = {}
            for c in res.get("channels") or []:
                per[c["group"]] = max(per.get(c["group"], 0.0), c["score"])
            for g, v in per.items():
                if g not in allowed and g != "load":
                    null.setdefault(g, []).append(v)
        thr = {g: round(max(ABNORMAL, margin * float(np.quantile(v, q))), 1) for g, v in null.items() if len(v) >= 10}
        return {"thresholds": {**THRESHOLDS, **thr}, "n": {g: len(v) for g, v in null.items()}, "q": q, "margin": margin}


    def calibrate_profile_thresholds(results: Sequence[Dict[str, Any]], profile: Any, q: float = 0.99, margin: float = 1.1) -> Dict[str, Any]:
        """Per-slot abnormal levels from normal cases of one alert type.

        Fewer than 20 normal results keeps the role default (or today's THRESHOLDS value when
        ``legacy_role`` maps the slot). At 20 or more, the level is the greater of that default
        and ``margin`` times the q quantile of the slot's channel scores.
        """
        slots = [slot for slot in (getattr(profile, "slots", []) or []) if slot.role not in ("flag", "context", "ignore")]
        defaults = {slot.id: _role_default(slot) for slot in slots}
        rows = list(results)
        if len(rows) < 20:
            return {"thresholds": defaults, "source": "role_default", "n": len(rows), "q": q, "margin": margin}
        samples: Dict[str, List[float]] = {slot_id: [] for slot_id in defaults}
        for res in rows:
            per: Dict[str, float] = {}
            for channel in res.get("channels") or []:
                slot_id = channel.get("slot")
                if slot_id in samples:
                    per[slot_id] = max(per.get(slot_id, 0.0), float(channel.get("score") or 0.0))
            for slot_id, score in per.items():
                samples[slot_id].append(score)
        thr: Dict[str, float] = {}
        for slot_id, base in defaults.items():
            vals = samples[slot_id]
            if len(vals) >= 20:
                thr[slot_id] = round(max(base, ABNORMAL, margin * float(np.quantile(vals, q))), 1)
            else:
                thr[slot_id] = base
        return {"thresholds": thr, "source": "calibrated", "n": len(rows), "q": q, "margin": margin}
# >>>>>>> END sentinel.e2e.residual

