# sentinel.analytics
# Resolve the free-text analytic name Tier 1 typed to one analyzer.
# =============================================================================
# <<<<<<< SECTION sentinel.analytics sentinel/analytics/__init__.py
if False:  # compiled by exec_section('sentinel.analytics'); not executed as part of this module
    """Analytic registry: resolve the free-text analytic name to an analyzer."""

    # @@future@@ from __future__ import annotations

    import copy
    import re
    from dataclasses import dataclass
    from typing import Any, Callable, Dict, List, Optional, Tuple

    from ..data import CaseData
    from ..notes import NotesInfo
    from . import cold_spot, combustion_dynamics, generic, hets_trip
    from .base import Findings

    ANALYZERS: Dict[str, Callable[..., Findings]] = {
        "cold_spot": cold_spot.analyze,
        "combustion_dynamics": combustion_dynamics.analyze,
        "hets_trip": hets_trip.analyze,
    }

    TITLES = {
        "cold_spot": "Exhaust cold spot",
        "combustion_dynamics": "Combustion dynamics",
        "hets_trip": "HETS trip (high exhaust temperature spread)",
        "generic": "Unrecognised analytic (generic analysis)",
    }

    # (analytic, regex on normalised name, reason). Order matters: trips before spread/cold.
    _ALIASES: List[Tuple[str, str, str]] = [
        ("hets_trip", r"\bhets\b|high exh\w* (temp\w* )?spread|spread trip|exh\w* spread.*trip|trip.*spread|hets trip", "HETS / spread-trip keywords"),
        ("cold_spot", r"cold ?spot|cold sector|cold zone|cold tc|cold can", "cold spot keywords"),
        ("combustion_dynamics", r"dynamic|pulsation|\bcdm\b|humming|combustion (instab|osc)|\bdyn\b|comb dyn", "dynamics keywords"),
    ]


    @dataclass
    class Resolution:
        """Class Resolution."""
        analytic: str  # canonical id or "generic"
        entered: str
        reason: str
        known: bool

        @property
        def title(self) -> str:
            """Function title."""
            return TITLES.get(self.analytic, self.analytic)


    def normalise(name: str) -> str:
        """Function normalise."""
        s = (name or "").lower()
        s = re.sub(r"[_\-./]+", " ", s)
        s = re.sub(r"[^a-z0-9 ]+", "", s)
        return re.sub(r"\s+", " ", s).strip()


    def resolve(
        name: str,
        columns: Any = None,
        frame: Optional[str] = None,
        explicit: Optional[str] = None,
    ) -> Resolution:
        """Map an alert name to an analyzer.

        With no header and no explicit alert type, this is the keyword table, so a
        name-only call stays what it was. With a header or an explicit id, the
        alert name selects the alert type and this returns that type's analyzer.
        An unknown name is not guessed from the tags: it falls through to the
        keyword table, so the rule shadow still runs. An unknown explicit id raises.
        """
        if columns is not None or explicit:
            from ..profiles import resolve_alert_type

            choice = resolve_alert_type(name or "", explicit=explicit)
            if choice.profile is not None:
                analytic = choice.profile.analyzer or "generic"
                why = f"alert type {choice.profile.id} ({choice.how})"
                return Resolution(analytic, name, why, analytic in ANALYZERS)
        norm = normalise(name)
        if norm.replace(" ", "_") in ANALYZERS:
            return Resolution(norm.replace(" ", "_"), name, "exact analytic id", True)
        for analytic, pat, why in _ALIASES:
            if re.search(pat, norm):
                return Resolution(analytic, name, f"matched {why}", True)
        return Resolution("generic", name, "no known analytic matched; generic analysis", False)


    def _case_with_legacy(case: CaseData, legacy: Optional[Dict[str, Any]]) -> CaseData:
        """A shallow copy whose roles, ring and zones come from a profile resolution.

        The caller's case is left alone. A cached case is shared across tests and runs.
        """
        if not legacy:
            return case
        twin = copy.copy(case)
        roles = legacy.get("roles")
        if isinstance(roles, dict):
            twin.roles = {str(key): list(value) for key, value in roles.items()}
        if "ring" in legacy:
            twin.ring = list(legacy.get("ring") or [])
        if "zones" in legacy:
            twin.zones = list(legacy.get("zones") or [])
        return twin


    def run_analyzer(
        res: Resolution,
        case: CaseData,
        notes: NotesInfo,
        anomaly: Optional[Dict] = None,
        probes: Optional[Dict[str, Findings]] = None,
        legacy: Optional[Dict[str, Any]] = None,
    ) -> Findings:
        """Run the resolved analyzer. ``legacy`` is ``Resolved.legacy`` from the profile."""
        case = _case_with_legacy(case, legacy)
        if res.analytic in ANALYZERS:
            return ANALYZERS[res.analytic](case, notes)
        best = best_probe(probes if probes is not None else probe_all(case, notes, legacy=legacy))
        return generic.analyze(case, notes, entered=res.entered, anomaly=anomaly, best=best)


    def probe_all(
        case: CaseData,
        notes: NotesInfo,
        skip: Optional[str] = None,
        legacy: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Findings]:
        """Run every known analyzer in probe mode (used for cross-checks and unknown analytics)."""
        case = _case_with_legacy(case, legacy)
        out: Dict[str, Findings] = {}
        for key, fn in ANALYZERS.items():
            if key == skip:
                continue
            try:
                out[key] = fn(case, notes, probe=True)
            except Exception:  # noqa: BLE001 — a probe must never break the main analysis
                continue
        return out


    def best_probe(probes: Dict[str, Findings]) -> Optional[Findings]:
        """Strongest detected signature. A trip outranks a cold spot / dynamics seen around it."""
        detected = [f for f in probes.values() if f.detected and f.top is not None and f.top.cause != "not_confirmed"]
        if not detected:
            return None
        trips = [f for f in detected if f.analytic == "hets_trip"]
        if trips:
            return trips[0]
        return max(detected, key=lambda f: f.strength)
# >>>>>>> END sentinel.analytics

# =============================================================================
# sentinel.e2e.model
# Light head, similarity index and novelty calibration on frozen embeddings.
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.model sentinel/e2e/model.py
if False:  # compiled by exec_section('sentinel.e2e.model'); not executed as part of this module
    """Learned decision layer on TS Pulse embeddings: head + similarity index + novelty.

    * **Scaler** — fixed standardisation from the synthetic training split, then L2-normalisation.
      Shared by the head and the index so distances stay comparable across retrains.
    * **Head** — multinomial logistic regression (softmax) on normalised embeddings. Retrains in
      seconds on CPU, so it can follow the engineer's labels live. Stored as plain numpy (no pickle).
    * **SimilarityIndex** — every labeled case (synthetic + engineer-labeled). Cosine distance.
      Returns the top-k cases with signature, action and distance for citation.
    * **Calibration** — novelty threshold = high quantile of held-out (validation) nearest-neighbour
      distances; match threshold = typical same-signature distance. Calibrated once on synthetic
      validation data and stored with the base model.

    Decision (``decide``):
    1. nearest labeled case farther than the novelty threshold → ``novel_pattern`` (no class forced);
    2. else, an engineer-labeled case is within the match threshold, about as close as the nearest case,
       and disagrees with the head → follow it (one-shot: a single labeled example of a new variant /
       signature takes effect immediately, before any retrain);
    3. else the head's class. Confidence is the head probability (or similarity for one-shot).
    4. residual novelty (V2, optional): the second TS Pulse view (reconstruction residuals, residual.py)
       shows clearly abnormal channels the chosen signature does not explain, and the case is only
       borderline-known (nearest distance above ``novelty_border`` or head confidence below
       ``novelty_conf``) -> ``novel_pattern``. Thresholds calibrated on the validation split.
    """

    # @@future@@ from __future__ import annotations

    import json
    from dataclasses import asdict, dataclass, field
    from pathlib import Path
    from typing import Any, Dict, List, Optional, Sequence, Tuple

    import numpy as np

    from ..config import (
        FRAME_COND_WEIGHT,
        FRAME_DIST_PENALTY,
        FRAME_NOVELTY_MIN,
        HEAD_MIN_LABELS,
        HEAD_MIN_PER_CLASS,
        KNN_VOTE_MIN,
        MASK_PENALTY,
        MISSING_TAG_CONFIDENCE_CAP,
        NOVELTY_QUANTILE,
        PROFILE_NOVELTY_MIN,
        ROOT,
    )
    from .taxonomy import NOVEL


    @dataclass
    class Scaler:
        """Class Scaler."""
        mean: np.ndarray
        std: np.ndarray

        @classmethod
        def fit(cls, E: np.ndarray) -> "Scaler":
            """Function fit."""
            return cls(E.mean(axis=0), E.std(axis=0) + 1e-6)

        def __call__(self, E: np.ndarray) -> np.ndarray:
            """Function __call__."""
            Z = (np.atleast_2d(E) - self.mean) / self.std
            return (Z / (np.linalg.norm(Z, axis=1, keepdims=True) + 1e-9)).astype(np.float32)

        def save(self, path: Path) -> None:
            """Function save."""
            np.savez(path, mean=self.mean, std=self.std)

        @classmethod
        def load(cls, path: Path) -> "Scaler":
            """Function load."""
            d = np.load(path)
            return cls(d["mean"], d["std"])


    @dataclass
    class Head:
        """Class Head."""
        classes: List[str]
        W: np.ndarray  # (K, D)
        b: np.ndarray  # (K,)
        meta: Dict[str, Any] = field(default_factory=dict)

        def proba(self, Z: np.ndarray) -> np.ndarray:
            """Function proba."""
            if len(self.classes) == 1:
                return np.ones((len(np.atleast_2d(Z)), 1))
            s = np.atleast_2d(Z) @ self.W.T + self.b
            s -= s.max(axis=1, keepdims=True)
            p = np.exp(s)
            return p / p.sum(axis=1, keepdims=True)

        def predict(self, Z: np.ndarray) -> List[str]:
            """Function predict."""
            return [self.classes[i] for i in self.proba(Z).argmax(axis=1)]

        def save(self, folder: Path) -> None:
            """Function save."""
            folder = Path(folder)
            folder.mkdir(parents=True, exist_ok=True)
            np.savez(folder / "head.npz", W=self.W, b=self.b)
            (folder / "head.json").write_text(json.dumps({"classes": self.classes, "meta": self.meta}, indent=2, default=str), encoding="utf-8")

        @classmethod
        def load(cls, folder: Path) -> "Head":
            """Load a head. Old layout ids in ``meta.frames`` become frame-model ids, same order.

            The weight columns stay aligned because each old id maps to exactly one model.
            The file on disk is not rewritten here. A head trained on tag layouts sets
            ``meta.frame_key`` to ``layout`` and the names stay layout ids, so 6B and 7EA
            keep sharing the ``ring_tc`` column after a reload.
            """
            from ..config import canonical_frame

            folder = Path(folder)
            d = np.load(folder / "head.npz")
            j = json.loads((folder / "head.json").read_text(encoding="utf-8"))
            meta = dict(j.get("meta") or {})
            if meta.get("frames") and meta.get("frame_key") != "layout":
                meta["frames"] = [canonical_frame(f) or f for f in meta["frames"]]
            return cls(j["classes"], d["W"], d["b"], meta)


    def train_head(Z: np.ndarray, labels: Sequence[str], weights: Optional[np.ndarray] = None, C: float = 2.0) -> Head:
        """Softmax regression on normalised embeddings (class-balanced)."""
        from sklearn.linear_model import LogisticRegression

        labels = list(labels)
        classes = sorted(set(labels))
        if len(classes) == 1:
            return Head(classes, np.zeros((1, Z.shape[1])), np.zeros(1), {"n": len(labels)})
        y = np.array([classes.index(s) for s in labels])
        counts = np.bincount(y, minlength=len(classes)).astype(float)
        w = (len(y) / (len(classes) * counts))[y]
        if weights is not None:
            w = w * np.asarray(weights, dtype=float)
        clf = LogisticRegression(C=C, max_iter=3000, tol=1e-5)
        clf.fit(Z, y, sample_weight=w)
        W, b = clf.coef_, clf.intercept_
        if len(classes) == 2:  # sklearn binary: one row -> two-class softmax
            W, b = np.vstack([-W[0] / 2, W[0] / 2]), np.array([-b[0] / 2, b[0] / 2])
        return Head(classes, W.astype(np.float32), b.astype(np.float32), {"n": len(labels), "per_class": {c: int(n) for c, n in zip(classes, counts)}})


    class SimilarityIndex:
        """Class SimilarityIndex."""
        def __init__(self, Z: Optional[np.ndarray] = None, records: Optional[List[Dict[str, Any]]] = None, dim: int = 0):
            """Function __init__."""
            self.Z = np.asarray(Z, dtype=np.float32) if Z is not None else np.zeros((0, dim), np.float32)
            self.records: List[Dict[str, Any]] = list(records or [])

        def __len__(self) -> int:
            """Function __len__."""
            return len(self.records)

        def add(self, z: np.ndarray, rec: Dict[str, Any]) -> None:
            """Add or replace (same id) a labeled case; effective immediately."""
            z = np.asarray(z, dtype=np.float32).reshape(1, -1)
            for i, r in enumerate(self.records):
                if r["id"] == rec["id"]:
                    self.Z[i] = z[0]
                    self.records[i] = rec
                    return
            self.Z = z if self.Z.size == 0 else np.vstack([self.Z, z])
            self.records.append(rec)

        def remove(self, rid: str) -> None:
            """Function remove."""
            keep = [i for i, r in enumerate(self.records) if r["id"] != rid]
            self.Z, self.records = self.Z[keep], [self.records[i] for i in keep]

        def distances(self, z: np.ndarray) -> np.ndarray:
            """Function distances."""
            if not len(self):
                return np.zeros(0)
            return 1.0 - (self.Z @ np.asarray(z, dtype=np.float32).reshape(-1))

        def query(self, z: np.ndarray, k: int = 5, exclude: Sequence[str] = ()) -> List[Dict[str, Any]]:
            """Function query."""
            d = self.distances(z)
            out = []
            for i in np.argsort(d):
                r = self.records[int(i)]
                if r["id"] in exclude:
                    continue
                out.append({**r, "distance": round(float(d[i]), 4)})
                if len(out) >= k:
                    break
            return out

        def save(self, folder: Path, name: str) -> None:
            """Function save."""
            folder = Path(folder)
            folder.mkdir(parents=True, exist_ok=True)
            np.savez_compressed(folder / f"{name}.npz", Z=self.Z.astype(np.float16))
            (folder / f"{name}.jsonl").write_text("".join(json.dumps(r, default=str) + "\n" for r in self.records), encoding="utf-8")

        @classmethod
        def load(cls, folder: Path, name: str) -> "SimilarityIndex":
            """Function load."""
            folder = Path(folder)
            if not (folder / f"{name}.npz").is_file():
                return cls()
            from ..config import migrate_frame_fields
            from .migrate import migrate_profile_fields

            Z = np.load(folder / f"{name}.npz")["Z"].astype(np.float32)
            recs = [
                migrate_profile_fields(migrate_frame_fields(json.loads(x)), root=folder)
                for x in (folder / f"{name}.jsonl").read_text(encoding="utf-8").splitlines()
                if x.strip()
            ]
            return cls(Z, recs)

        def merged(self, other: "SimilarityIndex") -> "SimilarityIndex":
            """Function merged."""
            if not len(other):
                return SimilarityIndex(self.Z.copy(), list(self.records))
            if not len(self):
                return SimilarityIndex(other.Z.copy(), list(other.records))
            return SimilarityIndex(np.vstack([self.Z, other.Z]), self.records + other.records)


    @dataclass
    class Calibration:
        """Class Calibration."""
        novelty_threshold: float
        match_threshold: float
        low_confidence: float = 0.6
        novelty_quantile: float = NOVELTY_QUANTILE
        k: int = 5
        notes: str = ""
        # V2 residual novelty (absent in V1 calibration files -> disabled)
        residual_novelty: bool = False
        novelty_border: float = 9.0
        novelty_conf: float = 0.0
        residual_thresholds: Dict[str, float] = field(default_factory=dict)
        residual_notes: str = ""
        # Per-frame novelty radii. Absent, or a frame with too few validation cases, uses novelty_threshold.
        frame_thresholds: Dict[str, float] = field(default_factory=dict)

        def save(self, path: Path) -> None:
            """Function save."""
            Path(path).write_text(json.dumps(asdict(self), indent=2), encoding="utf-8")

        @classmethod
        def load(cls, path: Path) -> "Calibration":
            """Load calibration. Threshold keys are kept as written.

            A layout id (``ring_tc``) is that layout's radius. A frame-model id (``7EA``)
            is that model's own radius, written only when the model had enough labeled
            cases. ``novelty_limit`` resolves both, including a file that stored only the
            layout id. Collapsing layout ids onto the default model would drop a layout
            radius that differs from that model's own radius.
            """
            d = json.loads(Path(path).read_text(encoding="utf-8"))
            known = set(cls.__dataclass_fields__)
            fields = {k: v for k, v in d.items() if k in known}
            if isinstance(fields.get("frame_thresholds"), dict):
                fields["frame_thresholds"] = {str(k): float(v) for k, v in fields["frame_thresholds"].items()}
            return cls(**fields)


    def calibrate(index: SimilarityIndex, Zval: np.ndarray, yval: Sequence[str], quantile: float = NOVELTY_QUANTILE) -> Calibration:
        """Thresholds from held-out (validation) cases against the training index."""
        nn_d, same_d = [], []
        for z, y in zip(Zval, yval):
            d = index.distances(z)
            nn_d.append(float(d.min()))
            sig = np.array([r["signature"] == y for r in index.records])
            if sig.any():
                same_d.append(float(d[sig].min()))
        nov = float(np.quantile(nn_d, quantile))
        match = float(np.quantile(same_d, 0.5)) if same_d else nov / 2
        return Calibration(
            novelty_threshold=round(nov, 4),
            match_threshold=round(min(match, nov * 0.8), 4),
            novelty_quantile=quantile,
            notes=f"from {len(nn_d)} validation cases: NN distance median {np.median(nn_d):.3f}, q{int(quantile * 100)} {nov:.3f}",
        )


    def _frame_slot(frame: str, frames: Sequence[str], layout: Optional[str] = None) -> int:
        """Index of this frame's layout column, or -1 when the head has no such column.

        The column is the tag layout (``FRAME_MODELS[m]["layout"]``), so 6B, 7EA and 9E
        share ``ring_tc`` and 7FA and 9FA share ``ring_ttxd``. Other / custom shares the
        layout the engineer picked (``layout``). A head saved before layout conditioning
        lists either the layout ids or, after ``Head.load``, the default model for each
        layout; both names are the same column. An empty dedicated column for 6B / 9E /
        9FA is not used: the layout's column is.

        No layout (or ``auto``) is -1, the zero vector. The case stays on the shared
        radius and is not pulled toward a layout the model has not been shown.
        """
        from ..config import DEFAULT_FRAME_FOR_LAYOUT, alias_of, canonical_frame, layout_of

        names = list(frames)
        if not names:
            return -1
        lay = layout_of(frame, layout)
        if lay:
            if lay in names:
                return names.index(lay)
            # Older head: Head.load renamed the layout id to the default model, same column.
            default = DEFAULT_FRAME_FOR_LAYOUT.get(lay, "")
            if default and default in names:
                return names.index(default)
            for i, name in enumerate(names):
                if name == lay or layout_of(name) == lay:
                    return i
            return -1
        raw = str(frame or "").strip()
        if not raw or raw in ("auto", "None"):
            return -1
        if raw in names:
            return names.index(raw)
        canon = canonical_frame(raw)
        if canon and canon in names:
            return names.index(canon)
        old = alias_of(canon or raw)
        if old and old in names:
            return names.index(old)
        return -1


    def condition_vector(z: np.ndarray, frame: str, frames: Sequence[str], weight: Optional[float] = None,
                         layout: Optional[str] = None) -> np.ndarray:
        """Append the layout one-hot and re-normalise so cosine distance feels the layout.

        Models that share a layout light the same column, so a model with no training
        cases is not pushed off its neighbours. An unknown frame, or Other / custom with
        no layout, is the zero vector.
        """
        from ..config import FRAME_COND_WEIGHT

        vec = np.asarray(z, dtype=np.float32).reshape(-1)
        names = list(frames)
        oh = np.zeros(len(names), np.float32)
        slot = _frame_slot(frame, names, layout=layout)
        if slot >= 0:
            oh[slot] = float(FRAME_COND_WEIGHT if weight is None else weight)
        out = np.concatenate([vec, oh])
        return (out / (np.linalg.norm(out) + 1e-9)).astype(np.float32)


    def project_embedding(z: np.ndarray, frame: str, head: "Head", layout: Optional[str] = None) -> np.ndarray:
        """Match a scaled embedding to this head.

        A shipped head has no ``uses_frame`` flag and is left at 672 dimensions, so older versions
        and the label-loop tests keep working. A frame-conditioned head (meta set at train time)
        appends the layout one-hot when the vector is still the bare embedding. A vector that is already
        the head width is returned as-is, so scoring a saved held-out matrix does not double-condition.
        ``layout`` is the tag layout for Other / custom; a shipped model uses its own layout.
        """
        vec = np.asarray(z, dtype=np.float32).reshape(-1)
        meta = head.meta or {}
        frames = list(meta.get("frames") or [])
        if not meta.get("uses_frame") or not frames:
            return vec
        width = int(head.W.shape[1])
        if vec.shape[0] == width:
            return vec
        base = width - len(frames)
        if base > 0 and vec.shape[0] == base:
            return condition_vector(vec, frame or "", frames, layout=layout)
        if vec.shape[0] > width:
            return vec[:width].astype(np.float32)
        out = np.zeros(width, np.float32)
        out[: vec.shape[0]] = vec
        return out


    def novelty_basis(cal: Calibration, frame: Optional[str] = None, layout: Optional[str] = None) -> Tuple[float, str]:
        """Radius and which table it came from: ``frame``, ``layout`` or ``shared``.

        A frame model uses its own radius only when that key was stored, which
        ``per_frame_thresholds`` does only after ``FRAME_NOVELTY_MIN`` labeled cases.
        Otherwise the tag layout's radius is used, so 6B / 9E / 9FA / Other-custom
        are not judged on a threshold nobody estimated. With no layout radius either,
        the shared radius.

        Old files stored the layout radius under the layout id, or (after an earlier
        loader) under the default model for that layout. A sibling of that model
        still finds it. A query that is itself a layout id returns the layout radius,
        not a per-frame override stored under the default model.
        """
        from ..config import DEFAULT_FRAME_FOR_LAYOUT, LAYOUTS, canonical_frame, layout_of, migrate_frame_table

        raw = {str(k): float(v) for k, v in dict(cal.frame_thresholds or {}).items()}
        shared = float(cal.novelty_threshold)
        raw_name = str(frame or "").strip()
        lay = layout_of(raw_name, layout)

        def layout_radius() -> Optional[float]:
            if lay and lay in raw:
                return float(raw[lay])
            default = DEFAULT_FRAME_FOR_LAYOUT.get(lay or "", "")
            if not default:
                return None
            # The layout id was renamed to the default model, and no separate layout key remains.
            if default in raw and lay not in raw:
                return float(raw[default])
            table = migrate_frame_table(raw)
            if default in table and default not in raw:
                return float(table[default])
            return None

        if raw_name in LAYOUTS:
            got = layout_radius()
            if got is not None:
                return got, "layout"
            return shared, "shared"
        key = canonical_frame(raw_name) if raw_name else ""
        if key and key not in ("", "auto") and key in raw and key not in LAYOUTS:
            return float(raw[key]), "frame"
        got = layout_radius()
        if got is not None:
            return got, "layout"
        if frame and frame in raw:
            return float(raw[frame]), "frame"
        return shared, "shared"


    def novelty_limit(cal: Calibration, frame: Optional[str] = None, layout: Optional[str] = None) -> float:
        """Radius for this case. See ``novelty_basis`` for the frame, then layout, then shared order."""
        return novelty_basis(cal, frame, layout)[0]


    def residual_unexplained(signature: str, residual: Optional[Dict[str, Any]], cal: Calibration) -> bool:
        """Function residual_unexplained."""
        if not residual or signature == NOVEL:
            return False
        from .residual import explained

        return bool(residual.get("groups_abnormal")) and not explained(signature, residual)


    def decide(z: np.ndarray, head: Head, index: SimilarityIndex, cal: Calibration, exclude: Sequence[str] = (),
               residual: Optional[Dict[str, Any]] = None, frame: Optional[str] = None,
               layout: Optional[str] = None) -> Dict[str, Any]:
        """Learned decision for one normalised embedding (``residual``: residual.summary() of the case, optional).

        ``frame`` selects a per-frame novelty radius when that model has one, else the layout's
        radius. ``layout`` is the tag layout for Other / custom. The caller passes a vector that
        already matches the head (see ``project_embedding``).
        """
        out = _decide(z, head, index, cal, exclude, frame=frame, layout=layout)
        out["residual_unexplained"] = residual_unexplained(out["signature"], residual, cal)
        if cal.residual_novelty and out["residual_unexplained"] and not out["novel"] and (
            (out["nearest_distance"] or 0.0) > cal.novelty_border or out["head_confidence"] < cal.novelty_conf
        ):
            prev = out["signature"]
            out.update(signature=NOVEL, novel=True, basis="residual_novelty", one_shot=False,
                       confidence=round(max(0.0, 1.0 - (out["nearest_distance"] or 0.0)), 4), residual_novelty_from=prev)
        return out


    def _decide(z: np.ndarray, head: Head, index: SimilarityIndex, cal: Calibration, exclude: Sequence[str] = (),
                frame: Optional[str] = None, layout: Optional[str] = None) -> Dict[str, Any]:
        """Function _decide."""
        p = head.proba(z)[0]
        order = np.argsort(p)[::-1]
        head_sig, head_conf = head.classes[int(order[0])], float(p[order[0]])
        probs = {head.classes[int(i)]: round(float(p[i]), 4) for i in order[:5]}
        sims = index.query(z, k=cal.k, exclude=exclude)
        nn = sims[0] if sims else None
        nn_d = nn["distance"] if nn else float("inf")
        from ..config import canonical_frame, layout_of

        thr, scope = novelty_basis(cal, frame, layout)
        shown = (canonical_frame(frame) or frame or "") if frame else ""
        res: Dict[str, Any] = {
            "head_signature": head_sig,
            "head_confidence": round(head_conf, 4),
            "head_probs": probs,
            "similar": sims,
            "nearest_distance": round(nn_d, 4) if nn else None,
            "novelty_threshold": thr,
            "novelty_threshold_scope": scope,
            "frame_type": shown,
            "frame_layout": layout_of(frame, layout),
            "match_threshold": cal.match_threshold,
            "novel": False,
            "one_shot": False,
        }
        if nn is None or nn_d > thr:
            res.update(signature=NOVEL, confidence=round(max(0.0, 1.0 - nn_d) if nn else 0.0, 4), basis="novelty", novel=True)
            return res
        # One-shot: an engineer-labeled case (not a synthetic training case, which the head already
        # represents) that is about as close as anything else and within the match threshold wins.
        eng = [s for s in sims if s.get("source") != "synthetic" and s["distance"] <= cal.match_threshold and s["distance"] <= 1.15 * nn_d + 1e-9]
        if eng and eng[0]["signature"] != head_sig:
            e0 = eng[0]
            votes = [s for s in sims if s["distance"] <= cal.match_threshold]
            same = [s for s in votes if s["signature"] == e0["signature"]]
            conf = min(0.95, 0.5 + 0.5 * (1 - e0["distance"] / max(cal.match_threshold, 1e-6)) * len(same) / max(1, len(votes)))
            res.update(signature=e0["signature"], confidence=round(conf, 4), basis="one_shot", one_shot=True, one_shot_case=e0["id"])
            return res
        res.update(signature=head_sig, confidence=round(head_conf, 4), basis="classifier")
        return res


    def calibrate_residual(cal: Calibration, decisions: List[Dict[str, Any]], residuals: List[Dict[str, Any]], truth: Sequence[str],
                           max_extra_false_novelty: float = 0.01) -> Dict[str, Any]:
        """Pick the residual-novelty thresholds on held-out (validation) cases.

        ``decisions``: decide() results without residual novelty. Grid over the nearest-distance border
        (quantiles of the validation nearest distances) and the head-confidence floor. Constraint: at most
        ``max_extra_false_novelty`` of the validation cases that are classified correctly may become NOVEL.
        Among the settings that meet it, the one that flags the most misclassified validation cases wins
        (ties: the most conservative, i.e. highest border and lowest confidence floor). Sets the fields on
        ``cal`` and returns the grid summary.
        """
        nn = np.array([d["nearest_distance"] or 0.0 for d in decisions])
        conf = np.array([d["head_confidence"] for d in decisions])
        unexp = np.array([residual_unexplained(d["signature"], r, cal) for d, r in zip(decisions, residuals)])
        novel0 = np.array([d["novel"] for d in decisions])
        correct = np.array([d["signature"] == t for d, t in zip(decisions, truth)])
        n = len(decisions)
        best: Optional[Dict[str, Any]] = None
        grid = []
        for q in (0.5, 0.6, 0.7, 0.75, 0.8, 0.85, 0.9, 0.95, 0.98):
            border = float(np.quantile(nn, q))
            for cf in (0.0, 0.5, 0.6, 0.7, 0.8, 0.9, 0.95, 0.99):
                flag = unexp & ~novel0 & ((nn > border) | (conf < cf))
                fp = int((flag & correct).sum())
                tp = int((flag & ~correct).sum())
                row = {"border_q": q, "border": round(border, 4), "conf": cf, "flag_correct": fp, "flag_wrong": tp, "flag_total": int(flag.sum())}
                grid.append(row)
                if fp <= max_extra_false_novelty * n:
                    key = (tp, q, -cf)
                    if best is None or key > best["_key"]:
                        best = {**row, "_key": key}
        if best is None:
            cal.residual_novelty = False
            cal.residual_notes = "no setting met the false-novelty budget on validation data"
            return {"chosen": None, "grid": grid}
        cal.residual_novelty = True
        cal.novelty_border = best["border"]
        cal.novelty_conf = best["conf"]
        cal.residual_notes = (f"from {n} validation cases: residual-unexplained {int(unexp.sum())} (correctly classified {int((unexp & correct).sum())}); "
                              f"border q{int(100 * best['border_q'])} = {best['border']}, confidence floor {best['conf']}: flags {best['flag_wrong']} misclassified "
                              f"and {best['flag_correct']} correct validation cases (budget {max_extra_false_novelty:.0%})")
        best.pop("_key", None)
        return {"chosen": best, "grid": grid}


    def _as_blocks(u: np.ndarray) -> Tuple[np.ndarray, bool]:
        """``(C, 48)`` -> ``(1, C, 48)``. ``(N, C, 48)`` stays a batch. Returns ``(array, was_single)``."""
        arr = np.asarray(u, dtype=np.float32)
        if arr.ndim == 2:
            return arr[None, ...], True
        if arr.ndim != 3:
            raise ValueError(f"expected (C, 48) or (N, C, 48), got {arr.shape}")
        return arr, False


    def _as_mask(mask: Optional[np.ndarray], shape: Tuple[int, ...]) -> np.ndarray:
        """Broadcast a ``(C,)`` mask across a batch. Missing mask means every channel is present."""
        rows, channels = shape
        if mask is None:
            return np.ones((rows, channels), dtype=bool)
        use = np.asarray(mask, dtype=bool)
        if use.ndim == 1:
            use = np.broadcast_to(use, (rows, channels))
        return np.asarray(use, dtype=bool).reshape(rows, channels)


    @dataclass
    class ChannelScaler:
        """48-d mean and std shared by every profile. Masked channels stay zeros, not a scaled flat line.

        Fitted on the present channel vectors of the built-in training split. A new profile
        reuses it, so three labeled cases do not have to estimate their own. The file is
        ``channel_scaler.npz`` next to the encoder.
        """

        mean: np.ndarray
        std: np.ndarray

        @classmethod
        def fit(cls, E: np.ndarray, mask: Optional[np.ndarray] = None) -> "ChannelScaler":
            """Fit on ``(N, 48)`` or on the present rows of ``(N, C, 48)``."""
            arr = np.asarray(E, dtype=np.float64)
            if arr.ndim == 2:
                rows = arr
            elif arr.ndim == 3:
                use = _as_mask(mask, arr.shape[:2])
                rows = arr[use]
            else:
                raise ValueError(f"expected (N, 48) or (N, C, 48), got {arr.shape}")
            dim = int(arr.shape[-1])
            if len(rows) == 0:
                return cls(np.zeros(dim, dtype=np.float64), np.ones(dim, dtype=np.float64))
            return cls(rows.mean(axis=0), rows.std(axis=0) + 1e-6)

        def transform(self, E: np.ndarray, mask: Optional[np.ndarray] = None) -> np.ndarray:
            """Standardise, L2-normalise each present channel, and zero the masked ones."""
            arr, single = _as_blocks(E)
            use = _as_mask(mask, arr.shape[:2])
            scaled = (arr - self.mean.astype(np.float32)) / self.std.astype(np.float32)
            scaled = np.where(use[..., None], scaled, 0.0)
            norms = np.linalg.norm(scaled, axis=-1, keepdims=True)
            out = np.where(use[..., None], scaled / (norms + 1e-9), 0.0).astype(np.float32)
            return out[0] if single else out

        def __call__(self, E: np.ndarray, mask: Optional[np.ndarray] = None) -> np.ndarray:
            """Same as ``transform``."""
            return self.transform(E, mask)

        def save(self, path: Path) -> None:
            """Write ``channel_scaler.npz``."""
            np.savez(path, mean=self.mean, std=self.std)

        @classmethod
        def load(cls, path: Path) -> "ChannelScaler":
            """Read the scaler saved with the encoder."""
            d = np.load(path)
            return cls(d["mean"], d["std"])


    def set_pool(u: np.ndarray, mask: Optional[np.ndarray] = None) -> np.ndarray:
        """96-d set pool: L2 of the mean of present blocks, then L2 of their elementwise max.

        The pool does not depend on channel order. It is the cross-profile hint, not a
        within-profile distance. No present channel yields zeros.
        """
        arr, single = _as_blocks(u)
        use = _as_mask(mask, arr.shape[:2]).astype(np.float32)
        count = use.sum(axis=1, keepdims=True)
        mean = (arr * use[..., None]).sum(axis=1) / np.maximum(count, 1.0)
        mean = np.where(count > 0, mean, 0.0)
        filled = np.where(use[..., None] > 0, arr, -np.inf)
        mx = np.max(filled, axis=1)
        mx = np.where(np.isfinite(mx), mx, 0.0)

        def _l2(v: np.ndarray) -> np.ndarray:
            return v / (np.linalg.norm(v, axis=-1, keepdims=True) + 1e-9)

        pool = np.concatenate([_l2(mean), _l2(mx)], axis=1).astype(np.float32)
        return pool[0] if single else pool


    def _frame_known(frame: Any) -> bool:
        """A frame key the distance penalty can see. Blank and ``auto`` are not known."""
        raw = str(frame or "").strip()
        return bool(raw) and raw.lower() not in {"auto", "none"}


    def _frame_comparable(frame: Any) -> bool:
        """A known frame key that is not ``*``. ``*`` is the generic alias key, so the frame is unknown."""
        return _frame_known(frame) and str(frame).strip() != "*"


    def head_input(
        u: np.ndarray,
        mask: Optional[np.ndarray],
        pool: np.ndarray,
        frame: Any = "",
        frames: Sequence[str] = (),
    ) -> np.ndarray:
        """Head vector ``48·C + 96 + C + F``. Masked blocks are zeros. The mask itself is stored at 0.5.

        ``frames`` is this profile's frame-key list, in a fixed order, so the one-hot width
        stays put for one channels hash. An unknown frame is the zero one-hot.
        """
        arr, single = _as_blocks(u)
        use = _as_mask(mask, arr.shape[:2])
        flat = (arr * use[..., None]).reshape(arr.shape[0], -1)
        pooled = np.asarray(pool, dtype=np.float32)
        if pooled.ndim == 1:
            pooled = np.broadcast_to(pooled, (arr.shape[0], pooled.shape[0])).copy()
        mask_feat = (0.5 * use.astype(np.float32))
        names = [str(item) for item in frames]
        oh = np.zeros((arr.shape[0], len(names)), dtype=np.float32)
        if single or isinstance(frame, str) or frame is None:
            incoming = [frame or ""] * arr.shape[0]
        else:
            incoming = list(frame)
        for i, name in enumerate(incoming):
            key = str(name or "")
            if key in names:
                oh[i, names.index(key)] = float(FRAME_COND_WEIGHT)
        out = np.concatenate([flat, pooled, mask_feat, oh], axis=1).astype(np.float32)
        return out[0] if single else out


    def head_vector(
        u: np.ndarray,
        mask: Optional[np.ndarray],
        frame: Any = "",
        frames: Sequence[str] = (),
        stats: Optional[np.ndarray] = None,
        *,
        stats_view: bool = False,
    ) -> np.ndarray:
        """The vector a profile head reads: ``head_input`` of the blocks, then, with ``stats_view``,
        ``head_input`` of the same channels' statistical blocks.

        TS Pulse blocks are L2-normalised per channel, so a level or spread change on one
        tag (a dynamics probe that drifts or flatlines) barely moves them. The statistical
        view keeps it. Only the head reads the second view; the kNN distance, the novelty
        radius and the one-shot match stay on ``u``. One case or a batch, like ``head_input``.
        """
        primary = head_input(u, mask, set_pool(u, mask), frame, frames)
        if not stats_view:
            return primary
        if stats is None:
            raise ValueError("this head also reads the statistical view; pass the case's stats blocks")
        second = head_input(stats, mask, set_pool(stats, mask), frame, frames)
        return np.concatenate([primary, second], axis=-1).astype(np.float32)


    def channel_weights(profile: Any, channels: Sequence[Any]) -> np.ndarray:
        """One weight per compiled channel, copied from its slot. A couple or ``_other`` with no slot is 1."""
        by_id: Dict[str, float] = {}
        for slot in getattr(profile, "slots", None) or []:
            if isinstance(slot, dict):
                sid = str(slot.get("id") or "")
                weight = slot.get("weight", 1.0)
            else:
                sid = str(getattr(slot, "id", "") or "")
                weight = getattr(slot, "weight", 1.0)
            if sid:
                by_id[sid] = float(weight)
        out = [by_id.get(str(getattr(spec, "slot_id", "") or ""), 1.0) for spec in channels]
        return np.asarray(out, dtype=np.float32)


    def block_distances(
        u: np.ndarray,
        mask: np.ndarray,
        frame: Any,
        U: np.ndarray,
        masks: np.ndarray,
        frames: Sequence[Any],
        weights: Optional[np.ndarray] = None,
    ) -> np.ndarray:
        """Masked block cosine from one case to each indexed case.

        ``1 - weighted mean of per-channel dots`` on the channels present in both,
        plus ``MASK_PENALTY`` for the channels present in only one, plus
        ``FRAME_DIST_PENALTY`` when both frame keys are known and they differ (``*`` is not a frame).
        No channel in common makes the cosine term 1. No channel in either makes
        the mask term 0.
        """
        query = np.asarray(u, dtype=np.float64).reshape(-1, u.shape[-1] if np.ndim(u) else 1)
        rows = np.asarray(U, dtype=np.float64)
        if rows.size == 0:
            return np.zeros(0, dtype=np.float64)
        if rows.ndim != 3:
            raise ValueError(f"index blocks must be (N, C, 48), got {rows.shape}")
        n, channels, _dim = rows.shape
        if query.shape != (channels, rows.shape[-1]):
            raise ValueError(f"query blocks are {query.shape}, index channels are {channels}")
        qmask = np.asarray(mask, dtype=bool).reshape(channels)
        imask = np.asarray(masks, dtype=bool).reshape(n, channels)
        w = np.ones(channels, dtype=np.float64) if weights is None else np.asarray(weights, dtype=np.float64).reshape(channels)
        dots = np.einsum("ncd,cd->nc", rows, query)
        common = imask & qmask[None, :]
        union = imask | qmask[None, :]
        weighted = common * w[None, :]
        denom = weighted.sum(axis=1)
        numer = (weighted * dots).sum(axis=1)
        sim = np.divide(numer, denom, out=np.zeros(n, dtype=np.float64), where=denom > 0)
        n_common = common.sum(axis=1).astype(np.float64)
        n_union = union.sum(axis=1).astype(np.float64)
        overlap = np.divide(n_common, n_union, out=np.ones(n, dtype=np.float64), where=n_union > 0)
        penalty = np.where(n_union > 0, float(MASK_PENALTY) * (1.0 - overlap), 0.0)
        frame_pen = np.zeros(n, dtype=np.float64)
        if _frame_comparable(frame):
            wanted = str(frame).strip()
            for i, other in enumerate(frames):
                if _frame_comparable(other) and str(other).strip() != wanted:
                    frame_pen[i] = float(FRAME_DIST_PENALTY)
        return (1.0 - sim) + penalty + frame_pen


    class MaskedIndex:
        """Per-profile similarity index. One row is the unit blocks of one labeled case, not one flat vector.

        Saved as float16 blocks plus a jsonl of records. ``query`` returns the distance and how
        many channels the two cases actually shared, so a report can say which tags were compared.
        """

        def __init__(
            self,
            U: Optional[np.ndarray] = None,
            mask: Optional[np.ndarray] = None,
            frames: Optional[Sequence[Any]] = None,
            records: Optional[List[Dict[str, Any]]] = None,
            weights: Optional[np.ndarray] = None,
            channels: int = 0,
            S: Optional[np.ndarray] = None,
        ):
            """``U`` is ``(N, C, 48)``. ``weights`` is ``(C,)`` from the profile slots.

            ``S`` is the same rows' statistical blocks, kept only so a refit can train a
            head that reads both views. It is never part of a distance. It exists only
            while every row has one: adding a row without it drops it.
            """
            self.records: List[Dict[str, Any]] = list(records or [])
            if weights is not None and not channels and (U is None or np.asarray(U).size == 0):
                channels = int(np.asarray(weights).reshape(-1).shape[0])
            if U is None or np.asarray(U).size == 0:
                width = int(channels)
                self.U = np.zeros((0, width, 48), dtype=np.float32)
                self.mask = np.zeros((0, width), dtype=bool)
            else:
                self.U = np.asarray(U, dtype=np.float32)
                if self.U.ndim != 3:
                    raise ValueError(f"U must be (N, C, 48), got {self.U.shape}")
                width = int(self.U.shape[1])
                self.mask = _as_mask(mask, self.U.shape[:2]) if mask is not None else np.ones(self.U.shape[:2], dtype=bool)
            self.weights = np.ones(width, dtype=np.float32) if weights is None else np.asarray(weights, dtype=np.float32).reshape(width)
            stored = list(frames) if frames is not None else [r.get("frame", "") for r in self.records]
            if len(stored) < len(self.records):
                stored.extend([""] * (len(self.records) - len(stored)))
            self.frames: List[str] = ["" if not _frame_known(item) and str(item or "").strip().lower() in {"", "auto", "none"} else str(item or "") for item in stored[: len(self.records)]]
            self.S: Optional[np.ndarray] = None
            if S is not None and self.U.shape[0]:
                stats_blocks = np.asarray(S, dtype=np.float32)
                if stats_blocks.shape != self.U.shape:
                    raise ValueError(f"S must match U {self.U.shape}, got {stats_blocks.shape}")
                self.S = stats_blocks

        def __len__(self) -> int:
            """Number of labeled cases."""
            return len(self.records)

        @property
        def channels(self) -> int:
            """Profile channel count. It does not change when a tag is missing on one case."""
            return int(self.U.shape[1])

        def distances(self, u: np.ndarray, mask: np.ndarray, frame: Any = "") -> np.ndarray:
            """Distance from one case to every row.

            A query frame that no row of this index carries is passed as blank.
            Charging ``FRAME_DIST_PENALTY`` against every row would shift the
            nearest distance by 0.05 for a frame the calibration never saw.
            ``block_distances`` itself is unchanged: two known, different frames
            still pay the penalty when the query frame is actually in the index.
            """
            if not len(self):
                return np.zeros(0, dtype=np.float64)
            query = frame
            if _frame_comparable(frame):
                wanted = str(frame).strip()
                seen = any(_frame_comparable(other) and str(other).strip() == wanted for other in self.frames)
                if not seen:
                    query = ""
            return block_distances(u, mask, query, self.U, self.mask, self.frames, self.weights)

        def add(self, u: np.ndarray, mask: np.ndarray, frame: Any, rec: Dict[str, Any], stats: Optional[np.ndarray] = None) -> None:
            """Insert a labeled case, or replace the row with the same id. Takes effect immediately.

            ``stats`` is the case's statistical blocks. Without them the index stops
            carrying ``S``, and a refit trains a head on ``u`` alone.
            """
            block = np.asarray(u, dtype=np.float32).reshape(1, self.channels if self.U.shape[1] else int(np.asarray(u).shape[0]), -1)
            if self.U.shape[1] and block.shape[1] != self.U.shape[1]:
                raise ValueError(f"expected {self.U.shape[1]} channels, got {block.shape[1]}")
            use = np.asarray(mask, dtype=bool).reshape(1, block.shape[1])
            extra = None if stats is None else np.asarray(stats, dtype=np.float32).reshape(block.shape)
            row = dict(rec)
            row["frame"] = "" if not _frame_known(frame) else str(frame).strip()
            for i, existing in enumerate(self.records):
                if existing.get("id") == row.get("id"):
                    self.U[i] = block[0]
                    self.mask[i] = use[0]
                    self.frames[i] = row["frame"]
                    self.records[i] = row
                    if self.S is not None:
                        if extra is None:
                            self.S = None
                        else:
                            self.S[i] = extra[0]
                    return
            if self.U.size == 0:
                self.U = block
                self.mask = use
                self.S = extra
                if self.weights.shape[0] != block.shape[1]:
                    self.weights = np.ones(block.shape[1], dtype=np.float32)
            else:
                self.U = np.concatenate([self.U, block], axis=0)
                self.mask = np.concatenate([self.mask, use], axis=0)
                self.S = None if self.S is None or extra is None else np.concatenate([self.S, extra], axis=0)
            self.frames.append(row["frame"])
            self.records.append(row)

        def query(self, u: np.ndarray, mask: np.ndarray, frame: Any = "", k: int = 5, exclude: Sequence[str] = ()) -> List[Dict[str, Any]]:
            """Top ``k`` neighbors with distance and the common-channel count."""
            d = self.distances(u, mask, frame)
            if d.size == 0:
                return []
            qmask = np.asarray(mask, dtype=bool).reshape(-1)
            out = []
            skipped = set(exclude)
            for i in np.argsort(d, kind="mergesort"):
                rec = self.records[int(i)]
                if rec.get("id") in skipped:
                    continue
                common = int(np.count_nonzero(self.mask[int(i)] & qmask))
                out.append({**rec, "distance": round(float(d[i]), 4), "common": common, "channels": self.channels})
                if len(out) >= k:
                    break
            return out

        def save(self, folder: Path, name: str = "index") -> None:
            """Float16 blocks. The records, including the frame key, stay in the jsonl."""
            folder = Path(folder)
            folder.mkdir(parents=True, exist_ok=True)
            arrays = {
                "U": self.U.astype(np.float16),
                "mask": self.mask.astype(np.uint8),
                "weights": self.weights.astype(np.float32),
            }
            if self.S is not None and self.S.shape == self.U.shape:
                arrays["S"] = self.S.astype(np.float16)
            np.savez_compressed(folder / f"{name}.npz", **arrays)
            lines = []
            for rec, frame in zip(self.records, self.frames):
                row = dict(rec)
                row["frame"] = frame
                lines.append(json.dumps(row, default=str))
            (folder / f"{name}.jsonl").write_text("".join(line + "\n" for line in lines), encoding="utf-8")

        @classmethod
        def load(cls, folder: Path, name: str = "index") -> "MaskedIndex":
            """Load a profile index. A legacy flat ``Z`` file is not this index."""
            folder = Path(folder)
            path = folder / f"{name}.npz"
            if not path.is_file():
                return cls()
            blob = np.load(path)
            if "U" not in blob.files:
                raise ValueError(f"{path} has no channel blocks")
            from ..config import migrate_frame_fields
            from .migrate import migrate_profile_fields

            text = (folder / f"{name}.jsonl").read_text(encoding="utf-8") if (folder / f"{name}.jsonl").is_file() else ""
            recs = []
            frames = []
            for line in text.splitlines():
                if not line.strip():
                    continue
                raw = json.loads(line)
                # The distance key is the string that was saved. A layout id such as
                # ring_tc is also a frame key; renaming it on load would add the frame
                # penalty the next time the same key is queried.
                frames.append(str(raw.get("frame") or ""))
                recs.append(migrate_profile_fields(migrate_frame_fields(raw), root=folder))
            weights = blob["weights"] if "weights" in blob.files else None
            stats_blocks = blob["S"].astype(np.float32) if "S" in blob.files else None
            return cls(blob["U"].astype(np.float32), blob["mask"].astype(bool), frames, recs, weights, S=stats_blocks)


    class ProfileCache:
        """Least-recently-used profile models. The engine keeps this so idle alert types do not stay in memory."""

        def __init__(self, limit: int = 16):
            """``limit`` is how many profiles stay loaded. The oldest is dropped past that."""
            self.limit = max(1, int(limit))
            self._items: Dict[str, Any] = {}
            self._order: List[str] = []

        def get(self, key: str) -> Any:
            """Return a cached model and mark it as just used. Missing is None."""
            if key not in self._items:
                return None
            self._order.remove(key)
            self._order.append(key)
            return self._items[key]

        def put(self, key: str, model: Any) -> None:
            """Store a model. A new key past the limit drops the one used least recently."""
            if key in self._order:
                self._order.remove(key)
            elif len(self._order) >= self.limit:
                self._items.pop(self._order.pop(0), None)
            self._order.append(key)
            self._items[key] = model

        def __contains__(self, key: str) -> bool:
            """True when the key is loaded."""
            return key in self._items

        def __len__(self) -> int:
            """How many profiles are loaded."""
            return len(self._items)


    def read_novelty_prior(path: Optional[Path] = None) -> Dict[str, Any]:
        """The shared prior in ``encoder/novelty_prior.json``.

        A missing, unreadable or incomplete file keeps radius 0.5 and match 0.4,
        the numbers a cold model used before this file existed. Pass ``path`` for
        a chosen encoder folder. The default is the shipped encoder.
        """
        fallback = {"n": 0, "radius": 0.5, "match": 0.4}
        chosen = Path(path) if path is not None else (ROOT / "models" / "e2e" / "encoder" / "novelty_prior.json")
        if not chosen.is_file():
            return dict(fallback)
        try:
            raw = json.loads(chosen.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return dict(fallback)
        if not isinstance(raw, dict) or raw.get("radius") is None:
            return dict(fallback)
        try:
            radius = float(raw["radius"])
            match = float(raw["match"]) if raw.get("match") is not None else min(radius * 0.8, radius)
            count = int(raw.get("n") or 0)
        except (TypeError, ValueError):
            return dict(fallback)
        return {"n": count, "radius": radius, "match": match}


    def is_synthetic_source(source: Any) -> bool:
        """A shipped training row, not an engineer label.

        The legacy index and the step-20 bundles tag their rows ``synthetic``. The
        per-alert bundles tag them ``synthetic_original`` and ``synthetic_profile``
        (one per generator). Comparing with ``== "synthetic"`` alone treated every
        per-alert bundle row as an engineer label, so the one-shot override
        replaced the head with the nearest synthetic neighbour.
        """
        return str(source or "").startswith("synthetic")


    def capped_match(same: Sequence[float], radius: float) -> float:
        """Median distance to the same signature, never above 0.8 times ``radius``.

        No same-signature neighbour leaves the median undefined, so the cap
        itself is the match. A non-positive radius does not cap.
        """
        cap = 0.8 * float(radius)
        if not same:
            return cap if radius > 0 else 0.0
        median = float(np.median(np.asarray(list(same), dtype=np.float64)))
        if radius > 0:
            return min(median, cap)
        return median


    class ProfileModel:
        """One alert type: its block index, optional head, and the tier that decides a case.

        Counts are the labeled rows in the index, held-out rows excluded. ``_adhoc`` is always
        the cold tier. The radius is the frame key's, then the profile's, then the shared prior.
        """

        def __init__(
            self,
            profile_id: str,
            index: MaskedIndex,
            head: Optional[Head] = None,
            calibration: Optional[Dict[str, Any]] = None,
            frames: Sequence[str] = (),
            head_passed: bool = False,
        ):
            """``calibration`` holds ``frame``, ``profile`` and ``prior`` blocks with ``n``, ``radius`` and ``match``."""
            self.profile_id = str(profile_id or "")
            self.index = index
            self.head = head
            self.calibration = dict(calibration or {})
            self.frames = list(frames)
            self.head_passed = bool(head_passed)

        @classmethod
        def empty(cls, profile_id: str, channels: int = 0, prior_path: Optional[Path] = None) -> "ProfileModel":
            """A profile with no labels yet. It decides as a cold start.

            The radius is ``novelty_prior.json`` when that file is present, not a
            hard-coded 0.5. ``prior_path`` points at one encoder folder's file.
            """
            return cls(profile_id, MaskedIndex(channels=channels), calibration={"prior": read_novelty_prior(prior_path)})

        def counts(self) -> Tuple[int, int, Dict[str, int]]:
            """``(labels, signatures that meet the head minimum, per-signature counts)``."""
            per: Dict[str, int] = {}
            n = 0
            for rec in self.index.records:
                if rec.get("held_out"):
                    continue
                n += 1
                sig = str(rec.get("signature") or "")
                if sig and sig != NOVEL:
                    per[sig] = per.get(sig, 0) + 1
            ready = sum(1 for count in per.values() if count >= HEAD_MIN_PER_CLASS)
            return n, ready, per

        def tier(self) -> str:
            """``cold``, ``knn`` or ``head``. A head that has not passed the gate stays at kNN."""
            if self.profile_id == "_adhoc":
                return "cold"
            n, ready, _per = self.counts()
            if n == 0:
                return "cold"
            if n < HEAD_MIN_LABELS or ready < 2 or self.head is None or not self.head_passed:
                return "knn"
            return "head"

        def confidence_floor(self) -> Optional[float]:
            """Head confidence below which a case beyond the radius is novel.

            Calibrated with the radius, on the same out-of-sample cases and at
            the same level. None (no head, or a bundle calibrated before the
            floor existed): the distance alone decides, as it used to.
            """
            if self.head is None:
                return None
            value = (self.calibration.get("profile") or {}).get("confidence")
            return None if value is None else float(value)

        def radius_for(self, frame: Any = "") -> Tuple[float, float, str]:
            """``(radius, match_threshold, scope)``. Scope is ``frame``, ``profile`` or ``prior``."""
            key = str(frame or "").strip()
            frame_cal = (self.calibration.get("frame") or {}).get(key) or {}
            if key and int(frame_cal.get("n") or 0) >= FRAME_NOVELTY_MIN:
                radius = float(frame_cal["radius"])
                return radius, float(frame_cal.get("match", min(radius * 0.8, radius))), "frame"
            prof = self.calibration.get("profile") or {}
            if int(prof.get("n") or 0) >= PROFILE_NOVELTY_MIN:
                radius = float(prof["radius"])
                return radius, float(prof.get("match", min(radius * 0.8, radius))), "profile"
            prior = self.calibration.get("prior") or {}
            radius = float(prior.get("radius", 0.5))
            return radius, float(prior.get("match", min(radius * 0.8, radius))), "prior"

        def decide_profile(
            self,
            u: np.ndarray,
            mask: np.ndarray,
            frame: Any = "",
            *,
            missing_required: bool = False,
            rule_action: Optional[str] = None,
            fallback: bool = False,
            exclude: Sequence[str] = (),
            stats: Optional[np.ndarray] = None,
        ) -> Dict[str, Any]:
            """Decide one case. ``rule_action`` is used only in the cold tier, when the rule analyzer fired.

            ``stats`` is the case's statistical blocks, scaled like the bundle's. Only a
            head that reads both views uses them.
            """
            kind = self.tier()
            if kind == "cold":
                result = self._cold(rule_action)
            elif kind == "knn":
                result = self._knn(u, mask, frame, exclude)
            else:
                result = self._head(u, mask, frame, exclude, stats)
            return self._finish(result, missing_required=missing_required, fallback=fallback)

        def _cold(self, rule_action: Optional[str]) -> Dict[str, Any]:
            """No labels yet. The rule analyzer is the primary evidence."""
            return {
                "tier": "cold",
                "signature": NOVEL,
                "basis": "cold_start",
                "needs_human": True,
                "novel": True,
                "one_shot": False,
                "confidence": 0.0,
                "primary_action": rule_action or "escalate",
                "rules_primary": True,
                "note": "No labeled cases for this alert type yet; label this case to teach it.",
                "similar": [],
                "nearest_distance": None,
            }

        def _neighbors(self, u: np.ndarray, mask: np.ndarray, frame: Any, exclude: Sequence[str]) -> List[Dict[str, Any]]:
            """Up to five nearest labeled cases."""
            k = min(5, len(self.index))
            if k <= 0:
                return []
            return self.index.query(u, mask, frame, k=k, exclude=exclude)

        def _knn(self, u: np.ndarray, mask: np.ndarray, frame: Any, exclude: Sequence[str]) -> Dict[str, Any]:
            """Novelty, then a distance-weighted vote inside the match radius."""
            radius, match, scope = self.radius_for(frame)
            hits = self._neighbors(u, mask, frame, exclude)
            nearest = hits[0]["distance"] if hits else None
            result: Dict[str, Any] = {
                "tier": "knn",
                "similar": hits,
                "nearest_distance": nearest,
                "novelty_threshold": radius,
                "novelty_threshold_scope": scope,
                "match_threshold": match,
                "one_shot": False,
                "novel": False,
                "rules_primary": False,
            }
            if not hits or float(nearest) > radius:
                result.update(signature=NOVEL, basis="novelty", novel=True, needs_human=True, confidence=0.0)
                return result
            voting = [hit for hit in hits if hit["distance"] <= match] or hits[:1]
            tally: Dict[str, float] = {}
            for hit in voting:
                tally[hit["signature"]] = tally.get(hit["signature"], 0.0) + 1.0 / (float(hit["distance"]) + 1e-3)
            winner = max(tally, key=tally.get)
            share = tally[winner] / sum(tally.values())
            confidence = max(0.0, share * (1.0 - float(nearest) / max(radius, 1e-6)))
            chosen = next(hit for hit in voting if hit["signature"] == winner)
            result.update(
                signature=winner,
                basis="knn",
                confidence=confidence,
                vote_share=round(share, 4),
                needs_human=share < KNN_VOTE_MIN,
                one_shot=not is_synthetic_source(chosen.get("source")),
                primary_action=chosen.get("action") or "",
            )
            return result

        def _head(self, u: np.ndarray, mask: np.ndarray, frame: Any, exclude: Sequence[str], stats: Optional[np.ndarray] = None) -> Dict[str, Any]:
            """Novelty, then an engineer one-shot, then the head. Same order as the legacy decider.

            Novel needs both pieces of evidence: the nearest labeled case is
            beyond the radius and the head is less sure than ``confidence_floor``.
            Beyond the radius with a confident head keeps the head's answer and
            asks a person (``beyond_radius``). Without a floor the distance
            alone decides.
            """
            radius, match, scope = self.radius_for(frame)
            hits = self._neighbors(u, mask, frame, exclude)
            nearest = hits[0]["distance"] if hits else None
            vector = head_vector(u, mask, frame, self.frames, stats, stats_view=bool((self.head.meta or {}).get("stats_view")))
            probs = self.head.proba(vector)[0]
            order = np.argsort(probs)[::-1]
            head_sig = self.head.classes[int(order[0])]
            head_conf = float(probs[int(order[0])])
            # Top classes, same shape as the legacy decider. A novel case still
            # carries them so the report is not an empty probability line.
            head_probs = {self.head.classes[int(i)]: round(float(probs[i]), 4) for i in order[:5]}
            result: Dict[str, Any] = {
                "tier": "head",
                "similar": hits,
                "nearest_distance": nearest,
                "novelty_threshold": radius,
                "novelty_threshold_scope": scope,
                "match_threshold": match,
                "head_signature": head_sig,
                "head_confidence": round(head_conf, 4),
                "head_probs": head_probs,
                "novel": False,
                "one_shot": False,
                "rules_primary": False,
            }
            floor = self.confidence_floor()
            result["confidence_floor"] = floor
            far = not hits or float(nearest) > radius
            unsure = floor is None or head_conf < floor
            if far and unsure:
                result.update(signature=NOVEL, basis="novelty", novel=True, needs_human=True, confidence=0.0)
                return result
            if far:
                result["beyond_radius"] = True
            if not hits:
                result.update(signature=head_sig, basis="classifier", confidence=head_conf, needs_human=True)
                return result
            nn = float(nearest)
            engineers = [
                hit for hit in hits
                if not is_synthetic_source(hit.get("source"))
                and hit["distance"] <= match
                and hit["distance"] <= 1.15 * nn + 1e-9
            ]
            if engineers and engineers[0]["signature"] != head_sig:
                chosen = engineers[0]
                result.update(
                    signature=chosen["signature"],
                    basis="one_shot",
                    one_shot=True,
                    one_shot_case=chosen.get("id"),
                    confidence=min(0.95, 0.5 + 0.5 * (1.0 - chosen["distance"] / max(match, 1e-6))),
                    needs_human=False,
                    primary_action=chosen.get("action") or "",
                )
                return result
            result.update(signature=head_sig, basis="classifier", confidence=head_conf, needs_human=bool(far))
            return result

        def _finish(self, result: Dict[str, Any], *, missing_required: bool, fallback: bool) -> Dict[str, Any]:
            """Shared caps: novel, a prior radius while the embedder fell back, and a missing required slot."""
            n, _ready, _per = self.counts()
            result["tier"] = result.get("tier") or self.tier()
            result["profile"] = self.profile_id
            result["audit"] = f"tier {result['tier']} ({n} labels, head at {HEAD_MIN_LABELS})"
            result.setdefault("needs_human", False)
            if result.get("novel"):
                result["needs_human"] = True
            if fallback and result.get("novelty_threshold_scope") == "prior":
                result["needs_human"] = True
                result["embedder_fallback"] = True
            if missing_required:
                result["needs_human"] = True
                result["missing_required"] = True
                result["confidence"] = min(float(result.get("confidence") or 0.0), MISSING_TAG_CONFIDENCE_CAP)
            result["confidence"] = round(float(result.get("confidence") or 0.0), 4)
            return result
