# <<<<<<< SECTION sentinel.e2e.dataset sentinel/e2e/dataset.py
if False:  # compiled by exec_section('sentinel.e2e.dataset'); not executed as part of this module
    """Labeled datasets for the learned path: synthetic manifest, feature cache, real-case import/export.

    Folder format for real labeled cases (drop-in for historical Tier 2 cases)::

        <folder>/labels.csv          file, signature, action, analytic, notes  (action/analytic/notes optional)
        <folder>/<file>.csv[.gz]     the historian export for each case

    ``export_labeled`` writes every engineer-labeled case (UI labels + reviewed rule-path cases in
    ``data/cases``) in this format; ``scripts/train_e2e.py --extra <folder>`` trains on it.
    """

    # @@future@@ from __future__ import annotations

    import csv
    import hashlib
    import json
    import shutil
    from pathlib import Path
    from typing import Any, Dict, List, Optional, Sequence, Tuple

    import numpy as np

    from .features import CHANNELS, WINDOW, canonical
    from .taxonomy import BASE_SIGNATURES, slug


    def load_manifest(root: Path) -> List[Dict[str, Any]]:
        """Function load_manifest."""
        path = Path(root) / "manifest.jsonl"
        return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


    def _featurize_one(path: str) -> Tuple[np.ndarray, Dict[str, Any]]:
        """Function _featurize_one."""
        from ..data import load_csv

        f = canonical(load_csv(path))
        return f.x, {"meta": f.meta, "excursions": f.excursions[:6]}


    def featurize_files(paths: Sequence[str], workers: int = 0) -> Tuple[np.ndarray, List[Dict[str, Any]]]:
        """Function featurize_files."""
        import multiprocessing as mp

        workers = workers or max(1, (mp.cpu_count() or 2) - 2)
        if workers > 1 and len(paths) > 16:
            with mp.get_context("spawn").Pool(workers) as pool:
                res = pool.map(_featurize_one, list(paths), chunksize=8)
        else:
            res = [_featurize_one(p) for p in paths]
        X = np.stack([r[0] for r in res]).astype(np.float32) if res else np.zeros((0, WINDOW, len(CHANNELS)), np.float32)
        return X, [r[1] for r in res]


    def cached_features(root: Path, rows: List[Dict[str, Any]], cache_dir: Path, workers: int = 0) -> np.ndarray:
        """Features for manifest rows, cached by (file list, channel set)."""
        from ..config import LEGACY_FEATURE_VERSION

        # The 14-channel cache stays on LEGACY_FEATURE_VERSION. Profile windows use FEATURE_VERSION 3.
        key = hashlib.sha256((f"v{LEGACY_FEATURE_VERSION}|" + "|".join(r["file"] for r in rows) + "|" + ",".join(CHANNELS)).encode()).hexdigest()[:16]
        cache = Path(cache_dir) / f"features_{key}.npz"
        if cache.is_file():
            return np.load(cache)["X"]
        X, _ = featurize_files([str(Path(root) / r["file"]) for r in rows], workers=workers)
        cache.parent.mkdir(parents=True, exist_ok=True)
        np.savez_compressed(cache, X=X)
        return X


    # --------------------------------------------------------------------------- real labeled cases

    # Reviewed rule-path cases carry an analytic + final action, not a signature; map them.
    _RULE_TO_SIGNATURE = {
        ("cold_spot", "borescope"): "cold_spot_hardware",
        ("cold_spot", "sensor_fix_replace"): "tc_sensor_fault",
        ("hets_trip", "borescope"): "hets_trip_hardware",
        ("hets_trip", "sensor_fix_replace"): "tc_sensor_fault",
        ("combustion_dynamics", "combustion_tuning"): "combustion_instability",
        ("combustion_dynamics", "sensor_fix_replace"): "dynamics_probe_fault",
    }
    _ACTION_TO_SIGNATURE = {"monitor_only": "normal", "lvdt_calibration": "igv_lvdt_drift", "control_adjustment": "fuel_control_oscillation"}


    def signature_from_review(analytic: str, final_action: Optional[str]) -> Optional[str]:
        """Function signature_from_review."""
        if not final_action:
            return None
        return _RULE_TO_SIGNATURE.get((analytic, final_action)) or _ACTION_TO_SIGNATURE.get(final_action)


    def read_labeled_folder(folder: Path) -> List[Dict[str, Any]]:
        """Function read_labeled_folder."""
        folder = Path(folder)
        out: List[Dict[str, Any]] = []
        with (folder / "labels.csv").open(encoding="utf-8-sig", newline="") as fh:
            for row in csv.DictReader(fh):
                f = (row.get("file") or "").strip()
                sig = slug(row.get("signature") or "")
                if not f or not sig or not (folder / f).is_file():
                    continue
                out.append(
                    {
                        "file": f,
                        "path": str(folder / f),
                        "signature": sig,
                        "action": (row.get("action") or "").strip() or (BASE_SIGNATURES.get(sig) or {}).get("action"),
                        "analytic": (row.get("analytic") or "").strip(),
                        "notes": (row.get("notes") or "").strip(),
                    }
                )
        return out


    def export_labeled(settings: Any, out: Path) -> int:
        """Write all engineer-labeled cases (UI labels + reviewed rule-path cases) as a labeled folder."""
        from .. import store
        from .labels import LabelStore

        out = Path(out)
        out.mkdir(parents=True, exist_ok=True)
        rows: List[Dict[str, str]] = []
        seen: set = set()
        for lab in LabelStore(settings).latest().values():
            src = Path(lab.get("csv_path") or "")
            if not src.is_file():
                continue
            name = f"{lab['case_id']}{''.join(src.suffixes[-2:]) if src.name.endswith('.gz') else '.csv'}"
            shutil.copy(src, out / name)
            rows.append({"file": name, "signature": lab["signature"], "action": lab["action"], "analytic": lab.get("analytic", ""), "notes": lab.get("notes", "")})
            seen.add(lab["case_id"])
        for rec in store.list_cases(settings):
            fb = rec.get("feedback") or {}
            if rec["case_id"] in seen or not fb:
                continue
            sig = signature_from_review(rec.get("analytic", ""), fb.get("final_action") or fb.get("corrected_action"))
            src = store.case_dir(settings, rec["case_id"]) / "input.csv"
            if not sig or not src.is_file():
                continue
            name = f"{rec['case_id']}.csv"
            shutil.copy(src, out / name)
            rows.append({"file": name, "signature": sig, "action": fb.get("final_action") or "", "analytic": rec.get("analytic_entered", ""), "notes": ""})
        with (out / "labels.csv").open("w", encoding="utf-8", newline="") as fh:
            w = csv.DictWriter(fh, fieldnames=["file", "signature", "action", "analytic", "notes"])
            w.writeheader()
            w.writerows(rows)
        return len(rows)


    # The five generator names that are not alert names. Rule B assigns them.
    # Any other unknown name stops the side-car build.
    GENERIC_ALERT_NAMES = (
        "GT alarm review",
        "Tier 1 escalation",
        "Exhaust temperature deviation advisory",
        "Unit advisory",
        "Performance deviation",
    )


    def decompressed_csv(path: Path) -> bytes:
        """File bytes with a gzip wrapper removed. The hash is of this text, not the gzip container."""
        import gzip

        raw = Path(path).read_bytes()
        if raw[:2] == b"\x1f\x8b":
            return gzip.decompress(raw)
        return raw


    def _csv_header(blob: bytes) -> List[str]:
        """Column names from the first line of a decompressed CSV."""
        import io

        line = blob.splitlines()[0].decode("utf-8-sig")
        return next(csv.reader(io.StringIO(line)))


    def _manifest_frame(row: Dict[str, Any]) -> str:
        """The frame the original generator stored for this layout. The manifest itself has no frame field."""
        layout = str(row.get("layout") or "")
        alt = bool(row.get("alt_tags"))
        if layout == "zones":
            return "9HA" if alt else "7HA"
        if layout == "ring":
            return "7FA" if alt else "7EA"
        return str(row.get("frame") or "")


    def original_alert_type(row: Dict[str, Any], columns: Sequence[str], book: Dict[str, Any]) -> Dict[str, str]:
        """Alert type and alert name for one original-generator case.

        Rule A: the analytic is an alert name. The alert type must list the truth
        signature, or this raises (no silent reassignment). Rule B: one of the five
        generic names. One alert type that lists the truth and has every slot in
        the file is B-owned. Several are broken by a sha1 of the case id, B-hash.
        The alert name then becomes that alert type's canonical name.
        """
        import hashlib

        from ..profiles import alert_type_for_name, resolve_tags

        analytic = str(row.get("analytic") or "")
        truth = str(row.get("signature") or "")
        case_id = str(row.get("case_id") or "")
        prof = alert_type_for_name(analytic, book)
        if prof is not None:
            listed = {str(sig) for sig in (prof.signatures or [])}
            if truth not in listed:
                raise ValueError(f"{case_id}: alert type {prof.id} does not list truth {truth}")
            return {"alert_type": prof.id, "alert_name": analytic, "rule": "A", "original_analytic": analytic}
        if analytic not in GENERIC_ALERT_NAMES:
            raise ValueError(f"{case_id}: {analytic!r} is not an alert name and is not one of the five generic names")
        candidates = []
        for item in book.values():
            if str(item.id).startswith("_"):
                continue
            listed = {str(sig) for sig in (item.signatures or [])}
            if truth not in listed:
                continue
            resolved = resolve_tags(item, list(columns))
            slots = [hit for hit in resolved.slots if hit.role != "ignore"]
            if slots and all(hit.status != "missing" for hit in slots):
                candidates.append(item)
        candidates.sort(key=lambda item: item.id)
        if not candidates:
            raise ValueError(f"{case_id}: no alert type lists {truth} and has every slot in the file")
        if len(candidates) == 1:
            chosen, rule = candidates[0], "B-owned"
        else:
            digest = hashlib.sha1(case_id.encode("utf-8")).hexdigest()
            chosen, rule = candidates[int(digest, 16) % len(candidates)], "B-hash"
        return {
            "alert_type": chosen.id,
            "alert_name": chosen.name,
            "rule": rule,
            "original_analytic": analytic,
        }


    def acceptance_sidecar_rows(dataset: Path) -> List[Dict[str, str]]:
        """One side-car row per test-split case, in manifest order.

        Built-ins only: a site file must not move a held-out case to another alert type.
        """
        import hashlib

        from ..profiles import load_profiles

        root = Path(dataset)
        book = load_profiles()
        out: List[Dict[str, str]] = []
        for row in load_manifest(root):
            if str(row.get("split") or "") != "test":
                continue
            blob = decompressed_csv(root / str(row["file"]))
            picked = original_alert_type(row, _csv_header(blob), book)
            out.append(
                {
                    "case_id": str(row["case_id"]),
                    "file": str(row["file"]),
                    "csv_sha256": hashlib.sha256(blob).hexdigest(),
                    "truth": str(row["signature"]),
                    "frame": _manifest_frame(row),
                    "original_analytic": picked["original_analytic"],
                    "alert_type": picked["alert_type"],
                    "alert_name": picked["alert_name"],
                    "rule": picked["rule"],
                }
            )
        return out


    # --------------------------------------------------------------------------- residual feed (V2)


    def _residual_one(path: str, settings: Any, model: Any, thresholds: Optional[Dict[str, float]] = None) -> Dict[str, Any]:
        """Function _residual_one."""
        from ..data import load_csv
        from . import residual

        res = residual.score(load_csv(path), settings, thresholds=thresholds, model=model)
        res.pop("profile", None)
        res["channels"] = (res.get("channels") or [])[:10]
        return res


    def cached_residuals(root: Path, rows: List[Dict[str, Any]], cache_dir: Path, settings: Any, log: Any = None,
                         thresholds: Optional[Dict[str, float]] = None) -> Dict[str, Dict[str, Any]]:
        """Residual analysis (residual.score, without the per-time profile) for manifest rows, cached."""
        from . import residual

        model, why = residual.load_model(settings)
        mode = "tspulse" if model is not None else "robust_z"
        thr = residual.thresholds_for(thresholds)
        key = hashlib.sha256(("|".join(r["file"] for r in rows) + f"|{residual.VERSION}|{sorted(thr.items())}|{mode}").encode()).hexdigest()[:16]
        cache = Path(cache_dir) / f"residual_{key}.json"
        if cache.is_file():
            return json.loads(cache.read_text(encoding="utf-8"))
        out: Dict[str, Dict[str, Any]] = {}
        for k, r in enumerate(rows):
            out[r["case_id"]] = _residual_one(str(Path(root) / r["file"]), settings, model, thr)
            if log and (k + 1) % 100 == 0:
                log(f"  residuals {k + 1}/{len(rows)}")
        cache.parent.mkdir(parents=True, exist_ok=True)
        cache.write_text(json.dumps(out, default=str), encoding="utf-8")
        return out
