        if st == "APPROVED":
            w(f"> **APPROVED** by {fb.get('reviewer')} on {fb.get('time')} — engineer marked this report Good.")
        elif st == "REJECTED":
            w(f"> **REJECTED** by {fb.get('reviewer')} on {fb.get('time')} — engineer's label: **{fb.get('signature')} → {ACTIONS.get(fb.get('action'), fb.get('action'))}**.")
        else:
            w("> **DRAFT — pending Tier 2 engineer review.** Not for release to site until marked Good.")
        w("")
        w("| Case | Unit | Analytic | Data window | Generated |")
        w("|---|---|---|---|---|")
        w(f"| {r['case_id']} | {_esc(r['case'].get('unit') or 'not stated')} | {_esc(r['analytic']['entered'])} | {inp['start']} → {inp['end']} "
          f"({inp['rows']} rows, {inp['interval_minutes'] or '?'} min) | {r['created']} |")
        w("")
        prof = r.get("profile") or {}
        if prof.get("slots"):
            w(f"**Alert type:** {_esc(prof.get('name') or prof.get('id'))} (`{prof.get('id')}` rev {prof.get('rev')}, "
              f"frame `{prof.get('frame_key') or 'auto'}`, tier {prof.get('tier')}).")
            w("")
            w("| Slot | Role | Unit | Tags | Status |")
            w("|---|---|---|---|---|")
            for slot in prof["slots"]:
                tags = ", ".join(slot.get("tags") or []) or "—"
                w(f"| {slot.get('slot')} | {slot.get('role')} | {slot.get('unit') or ''} | {_esc(tags)} | {slot.get('status')} |")
            if prof.get("other_tags"):
                w("")
                w("Other numeric tags (not in the alert type): " + ", ".join(str(tag) for tag in prof["other_tags"]) + ".")
            w("")
        w("## 1. Summary")
        w("")
        w(f"**Bottom line:** {r['bottom_line']}")
