        w(f"- **Canonical view:** layout {L['features'].get('layout')}, {L['features'].get('n_sensors')} exhaust sensors, zoom {L['features'].get('zoom')}, "
          f"missing roles: {', '.join(L['features'].get('missing_roles') or []) or 'none'}.")
        if au.get("residual_engine"):
            w(f"- **Residual view:** {au['residual_engine']} (mode `{au.get('residual_mode')}`).")
        if au.get("knowledge"):
            w(f"- **Process knowledge in the LLM prompt:** {', '.join(au['knowledge'])}.")
