    def _utf8() -> None:
        """Function _utf8."""
        for s in (sys.stdout, sys.stderr):
            try:
                s.reconfigure(encoding="utf-8")  # type: ignore[attr-defined]
            except (AttributeError, ValueError):
                pass


    def _settings(a: argparse.Namespace, **extra):
        """Settings honouring --data-dir / --device wherever they were given."""
        ov = {"data_dir": getattr(a, "data_dir", None), "device": getattr(a, "device", None), **extra}
        return load_settings({k: v for k, v in ov.items() if v is not None})


    def _progress(msg: str, frac: float) -> None:
        """Function _progress."""
        print(f"[{frac:4.0%}] {msg}", file=sys.stderr, flush=True)


    _FRAME_HELP = (
        "frame model: 6B, 7EA, 7FA, 7HA, 9E, 9FA, 9HA, Other / custom, or a frame added from Teach. "
        "An older layout id is accepted and mapped. Empty detects the model from the column names"
    )
    _LAYOUT_HELP = (
        "tag layout when --frame is Other / custom: ring_tc, ring_ttxd, zone_egt, zone_named. "
        "A layout that conflicts with another frame's layout is ignored, and a warning is printed"
    )


    def _frame_choice(a: argparse.Namespace, settings):
        """Validate ``--frame`` / ``--layout``. Returns (frame or None, layout or None, exit code).

        Exit code 2 means the name is not a shipped model, an alias, or a Teach-added frame.
        ``--layout`` is applied only for Other / custom. On any other frame it is ignored.
        A layout that is not that frame's own layout prints a warning; a matching layout
        is dropped quietly because the frame already uses it.
        """
        from .config import CUSTOM_FRAME, LAYOUTS, layout_of, normalize_frame_arg

        try:
            frame = normalize_frame_arg(getattr(a, "frame", ""), settings.data_dir)
        except ValueError as exc:
            print(exc)
            return None, None, 2
        layout = str(getattr(a, "layout", "") or "").strip()
        if layout and layout not in LAYOUTS:
            print(f"unknown layout '{layout}'. Choices: {', '.join(LAYOUTS)}")
            return None, None, 2
        if layout and frame != CUSTOM_FRAME:
            expected = layout_of(frame) if frame else ""
            if frame and expected and layout == expected:
                layout = ""
            else:
                owned = expected or "its own tags"
                whose = frame or "auto-detect"
                print(
                    f"warning: --layout {layout} ignored; {whose} uses {owned}. "
                    f"--layout applies only when --frame is Other / custom.",
                    file=sys.stderr,
                )
                layout = ""
        return frame, (layout or None), 0


    def cmd_run(a: argparse.Namespace) -> int:
        """Function cmd_run."""
        from .pipeline import run_case

        settings = _settings(a)
        notes = a.notes or ""
        if a.notes_file:
            notes = Path(a.notes_file).read_text(encoding="utf-8")
        frame, layout, code = _frame_choice(a, settings)
        if code:
            return code
        r = run_case(a.csv, a.analytic, notes, settings=settings, use_llm=not a.no_llm, progress=_progress, frame=frame, layout=layout)
        d = r["decision"]
        case_path = Path(r["_path"])
        if a.out:
            out = Path(a.out)
            out.mkdir(parents=True, exist_ok=True)
            stem = a.out_name or f"{r['analytic']['resolved']}_{Path(a.csv).stem}"
            shutil.copy(case_path / "report.md", out / f"{stem}.md")
            shutil.copy(case_path / "report.json", out / f"{stem}.json")
            print(f"COPIED\t{out / (stem + '.md')}")
        if a.json:
            print(json.dumps({k: v for k, v in r.items() if k != "anomaly"}, indent=2, default=str))
            return 0
        print(f"CASE\t{r['case_id']}")
        print(f"STATUS\t{r['review']['status']}")
        print(f"ANALYTIC\t{r['analytic']['entered']} -> {r['analytic']['resolved']}")
        print(f"FRAME\t{r['case'].get('frame_type', '')}")
        print(f"PATH\t{r['audit'].get('analyzer_path', '')}")
        print(f"ACTION\t{d['primary_action']}\t{ACTIONS[d['primary_action']]}")
        print(f"SECONDARY\t{','.join(d['secondary_actions']) or '-'}")
        print(f"URGENCY\t{d['urgency']}\tSEVERITY\t{d['severity']}\tESCALATE\t{d['escalate']}")
        print(f"CONFIDENCE\t{d['confidence']:.2f}\t{d['confidence_label']}\tNEEDS_HUMAN\t{d['needs_human']}")
        print(f"NARRATIVE\t{r['audit']['narrative_engine']}")
        print(f"REPORT\t{case_path / 'report.md'}")
        if a.print:
            print("--- REPORT ---")
            print((case_path / "report.md").read_text(encoding="utf-8"))
        return 0


