    def _size(p: Path) -> str:
        """Function _size."""
        n = p.stat().st_size
        return f"{n / 1e9:.2f} GB" if n > 5e8 else f"{n / 1e6:.1f} MB"


    def _sha256(p: Path) -> str:
        """Function _sha256."""
        import hashlib

        h = hashlib.sha256()
        with p.open("rb") as fh:
            for chunk in iter(lambda: fh.read(1 << 22), b""):
                h.update(chunk)
        return h.hexdigest()


    def cmd_doctor(a: argparse.Namespace) -> int:
        """Check this machine: GPU, VRAM, llama-cpp-python build, model files, offload plan, quick generate.

        Every failed check prints the exact command that repairs it. A ready machine prints the same
        ACTIVE / RESULT lines as before, with no fix lines mixed in.
        """
        from . import llm_runtime

        s = _settings(a)
        ok = True
        # These are the commands a new machine runs. setup fetches the one LLM and TS Pulse;
        # train --full builds the learned encoder when it was not copied in with the models.
        fix_setup = "python sentinel_gt_ai.py setup"
        fix_train = "python sentinel_gt_ai.py train --full --device auto"

        def line(tag: str, msg: str) -> None:
            """Function line."""
            print(f"[{tag:^4}] {msg}", flush=True)

        def fail(msg: str, fix: str) -> None:
            """Function fail."""
            nonlocal ok
            ok = False
            line("FAIL", msg)
            line("fix", fix)

        print(f"{APP_NAME} {__version__} doctor — {platform.system()} {platform.release()}, Python {platform.python_version()}, "
              f"{os.cpu_count()} logical CPUs, app folder {ROOT}")
        gpu = llm_runtime.detect_gpu()
        if gpu.nvidia:
            line("ok", f"GPU: {gpu.name} — {gpu.vram_total_mb} MB VRAM ({gpu.vram_free_mb} MB free), driver {gpu.driver}")
        else:
            line("info", f"GPU: none usable ({gpu.error}) — CPU mode")
        li = llm_runtime.llama_cpp_info()
        if li["installed"]:
            line("ok", f"llama-cpp-python {li['version']} — {'CUDA build (GPU offload supported)' if li['gpu_offload'] else 'CPU build'}")
            if gpu.nvidia and not li["gpu_offload"]:
                line("warn", "NVIDIA GPU present but llama-cpp-python is a CPU build — re-run install.ps1 to get the CUDA wheel")
        else:
            fail(f"llama-cpp-python not installed ({li.get('error')})", fix_setup)
        plan = llm_runtime.plan(s, gpu=gpu)
        line("ok", f"settings: device={s.device}, n_gpu_layers={s.n_gpu_layers}")
        act = f"ACTIVE: {plan.model_label} on {plan.device.upper()}"
        if plan.device == "gpu":
            act += f" with {plan.n_gpu_layers}/{plan.n_layers} layers offloaded"
        line("ok" if (plan.device == "gpu" or s.device != "gpu") else "warn", f"{act} — {plan.reason}")
        path = Path(llm_runtime.resolve_model(s)["path"])
        if path.is_file():
            sha = ""
            if a.verify:
                sha = " sha256 " + ("OK" if _sha256(path) == llm_runtime.GEMMA["sha256"] else "MISMATCH")
                if "OK" not in sha:
                    ok = False
                    line("fix", fix_setup)
            line("ok" if "MISMATCH" not in sha else "FAIL", f"LLM model: {path.relative_to(ROOT) if path.is_relative_to(ROOT) else path} ({_size(path)}){sha}")
        else:
            fail(f"LLM model missing: {path} (reports fall back to the deterministic template without it)", fix_setup)
        # Gemma 4 12B Q4_K_M is the only LLM. Any other GGUF under models/ is ignored.
        for extra in llm_runtime.unused_ggufs(ROOT / "models", path if path.is_file() else None):
            rel = extra.relative_to(ROOT) if extra.is_relative_to(ROOT) else extra
            line("info", f"unused GGUF (ignored; Gemma 4 12B Q4_K_M is the only LLM): {rel}")
        from .e2e.labels import legacy_model_dir

        # The 14-channel probe below needs the moved bundle, not the channel-independent
        # encoder that now lives at models/e2e/encoder.
        legacy_enc = legacy_model_dir(s.e2e_model_dir, "encoder")
        legacy_base = legacy_model_dir(s.e2e_model_dir, "base")
        checks = (
            ("TS Pulse base (classification variant)", s.tspulse_clf_dir, ("config.json", "model.safetensors")),
            ("TS Pulse anomaly model (rule path)", s.tspulse_dir, ("config.json", "model.safetensors")),
            ("learned model: TS Pulse encoder", legacy_enc, ("config.json", "model.safetensors", "classes.json")),
            ("learned model: head / index / calibration", legacy_base, ("scaler.npz", "head.npz", "index.npz", "calibration.json")),
        )
        for label, d, need in checks:
            miss = [n for n in need if not (Path(d) / n).is_file()] if d else list(need)
            rel = Path(d).relative_to(ROOT) if d and Path(d).is_relative_to(ROOT) else d
            if miss:
                # The encoder is produced by fine-tuning, not by the model download. Everything else
                # (Gemma, both TS Pulse snapshots, the shipped head) comes from setup or --models-from.
                fix = fix_train if "encoder" in label else fix_setup
                fail(f"{label}: {rel} — missing {', '.join(miss)}", fix)
            else:
                line("ok", f"{label}: {rel}")
        # The folders above are the shipped bundle. A promoted retrain runs from data/e2e/registry instead,
        # so name the version (and the encoder it uses) that the learned path will actually load.
        try:
            from .e2e.labels import Registry

            reg = Registry(s)
            cur = reg.current()
            from .config import canonical_frame

            head_meta = json.loads((reg.folder(cur) / "head.json").read_text(encoding="utf-8")).get("meta") or {}
            enc = (reg._meta(cur) or {}).get("encoder_from") or "shipped"
            # A layout-keyed head lists tag layouts. An older file lists layout ids that load as models.
            if head_meta.get("frame_key") == "layout":
                shown = [str(x) for x in (head_meta.get("frames") or [])]
            else:
                shown = [canonical_frame(x) or str(x) for x in (head_meta.get("frames") or [])]
            line("ok", f"ACTIVE learned model: {cur} (encoder {enc}"
                       f"{', frame-conditioned on ' + ', '.join(shown) if head_meta.get('uses_frame') else ''})")
        except Exception as exc:  # noqa: BLE001 — informational; the checks above already cover missing files
            line("info", f"active learned model: unknown ({type(exc).__name__}: {exc})")
        try:
            import numpy as np
            import torch

            from .e2e.encoder import Encoder
            from .e2e.features import CHANNELS, WINDOW

            enc = Encoder(legacy_model_dir(s.e2e_model_dir, "encoder"))
            x = np.zeros((8, WINDOW, len(CHANNELS)), dtype=np.float32)
            t0 = time.monotonic()
            enc.embed(x)
            line("ok", f"torch {torch.__version__}; TS Pulse embed {(time.monotonic() - t0) / 8 * 1000:.0f} ms/case on CPU — learned path + rules ≈ 1-2 s per CSV")
        except Exception as exc:  # noqa: BLE001
            fail(f"TS Pulse / learned model: {exc}", fix_train)
        try:
            import numpy as np

            from .e2e.encoder import CIEncoder
            from .e2e.features import WINDOW as _window

            ci = CIEncoder(path=Path(s.tspulse_clf_dir), device="cpu")
            ci.embed_channels(np.zeros((1, _window, 4), dtype=np.float32))
            line("ok", f"channel-independent embedder: {ci.embed_rate:.0f} windows/s on CPU, {ci.dim}-d per channel")
        except Exception as exc:  # noqa: BLE001 — a missing weight file uses the statistical fallback
            line("info", f"channel-independent embedder unavailable ({type(exc).__name__}: {exc}); statistical fallback")
        if not a.no_generate and plan.model_found and li["installed"]:
            try:
                sch = {"type": "object", "properties": {"reply": {"type": "string"}}, "required": ["reply"]}
                user = "In about 40 words, explain what a borescope inspection of a gas turbine combustor looks for. Put it in the field 'reply'."
                res = llm_runtime.chat_json(s, "You are a concise gas turbine engineer. Reply in JSON.", user, sch, max_tokens=80)
                u = res.get("usage") or {}
                gen_s = res.get("gen_s") or 0
                ntok = u.get("completion_tokens") or 0
                # gen_s also contains prompt processing (~2.5x faster per token than generation on CPU)
                tps = ntok / max(0.1, gen_s - (u.get("prompt_tokens") or 0) / (2.5 * max(0.5, ntok / max(gen_s, 0.1)))) if ntok else 0
                line("ok", f"quick generate on {res['device'].upper()}: load {res['load_s']} s, {u.get('prompt_tokens')} prompt + {ntok} generated tokens "
                     f"in {gen_s} s (~{tps:.1f} tok/s generation)" + (f" — FALLBACK: {res['fallback']}" if res.get("fallback") else ""))
                if tps:
                    est = 400 / tps + 1400 / (tps * 2.5) + (res.get("load_s") or 0)
                    line("info", f"expected: ~{est / 60:.1f} min per LLM site report (typical ~1400 prompt + ~400 generated tokens, first load "
                         f"included) on {res['device'].upper()}; measured on the build laptop's CPU: 3.6 min mean over 10 reports")
            except Exception as exc:  # noqa: BLE001
                fail(f"quick generate failed: {exc}", fix_setup)
        else:
            exp = "~10-20 tok/s with partial GPU offload" if plan.device == "gpu" else "~3-5 tok/s for Gemma 4 12B on an 8-core laptop CPU"
            line("info", f"expected speed: {exp} (run without --no-generate to measure)")
        try:
            from .e2e.labels import Registry
            from .e2e.teach import check_alert_types

            report = check_alert_types(s)
            rows = report.get("alert_types") or []
            line("ok", f"alert types: {len(rows)}")
            refused = report.get("refused") or []
            conflicts = report.get("conflicts") or []
            if refused:
                line("warn", f"refused profile files: {len(refused)}")
            else:
                line("ok", "refused profile files: none")
            if conflicts:
                line("warn", f"name conflicts: {len(conflicts)}")
            else:
                line("ok", "name conflicts: none")
            tiers = ", ".join(f"{row['id']}={row['tier']}" for row in rows)
            line("info", f"alert type tiers: {tiers}")
            reg = Registry(s)
            enc = reg.current_encoder()
            folder = Path(reg.encoder_folder(enc))
            source = "no weights"
            note = folder / "training.json"
            if note.is_file():
                try:
                    meta = json.loads(note.read_text(encoding="utf-8"))
                except ValueError:
                    meta = {}
                source = str(meta.get("chosen") or meta.get("source") or meta.get("candidate") or "training.json")
            elif (folder / "model.safetensors").is_file():
                source = "weights present"
            shown = folder.name
            try:
                shown = str(folder.resolve().relative_to(ROOT.resolve()))
            except ValueError:
                shown = folder.name
            line("ok", f"active encoder: {enc} from {shown} ({source})")
        except Exception as exc:  # noqa: BLE001 — listing alert types must not hide a model failure already printed
            line("info", f"alert types: {type(exc).__name__}")
        print("RESULT:", "READY" if ok else "NOT READY — see FAIL lines")
        return 0 if ok else 1


