    def cmd_e2e(a: argparse.Namespace) -> int:
        """Function cmd_e2e."""
        from .e2e import pipeline as ep

        s = _settings(a)
        sub = a.e2e_cmd
        if sub == "run":
            files: List[Path] = [Path(c) for c in (a.csv or [])]
            if a.folder:
                files += sorted(p for p in Path(a.folder).glob("*.csv*") if p.name.lower() != "labels.csv")
            if not files:
                print("give --csv and/or --folder")
                return 2
            notes = Path(a.notes_file).read_text(encoding="utf-8") if a.notes_file else (a.notes or "")
            frame, layout, code = _frame_choice(a, s)
            if code:
                return code
            explicit = str(getattr(a, "alert_type", "") or "").strip() or None
            for f in files:
                try:
                    r = ep.analyze_case(f, a.analytic or "Tier 2 review", notes, settings=s, use_llm=a.llm, run_rules=not a.no_rules,
                                        progress=_progress if a.llm else (lambda m, x: None), frame=frame, layout=layout,
                                        alert_type=explicit)
                except ValueError as exc:
                    print(exc)
                    return 2
                if str(getattr(s, "e2e_mode", "") or "") == "peralert" and (r.get("learned") or {}).get("basis") == "unknown_alert_type":
                    shown = a.analytic or "Tier 2 review"
                    print(f"UNKNOWN ALERT TYPE '{shown}'")
                    print(f"python sentinel_gt_ai.py alert-types add-alias --type <id> --name \"{shown}\"")
                    print(f"python sentinel_gt_ai.py alert-types new --name \"{shown}\" --sample {f}")
                d, L, sh = r["decision"], r["learned"], r["shadow"]
                s0 = (L.get("similar") or [{}])[0]
                print(f"CASE\t{r['case_id']}\t{f.name}\tLEARNED\t{L['signature']}\t{d['primary_action']}\tconf {d['confidence']:.2f}\t"
                      f"RULES\t{sh['rules'].get('primary_action')}\tAGREE\t{sh['agree']}\tNOVEL\t{L['novel']}\tNEEDS_HUMAN\t{d['needs_human']}\t"
                      f"SIMILAR\t{s0.get('id')}->{s0.get('action')} d={s0.get('distance')}")
                print(f"FRAME\t{r['case'].get('frame_type', '')}")
                print(f"PATH\t{r['audit'].get('analyzer_path', '')}")
                if a.llm:
                    print(f"NARRATIVE\t{r['audit']['narrative_engine']}")
                if a.print:
                    print((Path(r["_path"]) / "report.md").read_text(encoding="utf-8"))
            return 0
        if sub == "label":
            explicit = str(getattr(a, "alert_type", "") or "").strip() or None
            res = ep.label_case(s, a.case, a.signature, a.action, verdict=a.verdict, note=a.note or "", reviewer=a.reviewer or "", new_signature_title=a.new_title or "", alert_type=explicit)
            print(f"LABEL\t{a.case}\t{res['label']['signature']}\t{res['label']['action']}\t{res['feedback']['verdict']}\t"
                  f"labels since retrain {res['labels_since_retrain']}\t{'RETRAIN STARTED' if res['retrain_started'] else ''}")
            eng = ep.get_engine(s)
            eng.worker.join()
            if eng.worker.last:
                print(f"RETRAINED\t{eng.worker.last.get('version')}\theld-out {eng.worker.last.get('heldout')}")
            return 0
        if sub == "write":
            r = ep.write_report(s, a.case)
            print(f"NARRATIVE\t{r['audit']['narrative_engine']}")
            print(f"ACTION\t{r['decision']['primary_action']}\tNEEDS_HUMAN\t{r['decision']['needs_human']}")
            return 0
        eng = ep.get_engine(s)
        if sub == "retrain":
            out = eng.retrain(trigger="manual (CLI)")
            print(f"RETRAINED\t{out['version']}\t{out['heldout']}")
        elif sub == "rollback":
            print(f"ACTIVE\t{eng.rollback()}")
        elif sub == "activate":
            eng.activate(a.version)
            print(f"ACTIVE\t{a.version}")
        elif sub == "versions":
            for v in eng.registry.versions():
                print(f"{v['version']}\t{'*' if v.get('active') else ' '}\t{v.get('created')}\t{v.get('trigger')}\t{v.get('heldout') or ''}")
        elif sub == "status":
            from .e2e import dashboard

            info = {**eng.describe(), **dashboard.metrics(eng), "labels_since_retrain": eng.labels_since_retrain(), "heldout": eng.heldout_eval()}
            print(json.dumps(info, indent=2, default=str))
        elif sub == "export-dataset":
            from .e2e.dataset import export_labeled

            print(f"EXPORTED\t{export_labeled(s, Path(a.out))}\t{a.out}")
        elif sub == "import":
            from .e2e.dataset import read_labeled_folder

            n = 0
            for lab in read_labeled_folder(Path(a.folder)):
                r = ep.analyze_case(lab["path"], lab.get("analytic") or "Tier 2 review", lab.get("notes", ""), settings=s, engine=eng)
                ep.label_case(s, r["case_id"], lab["signature"], lab.get("action"), note="imported", reviewer="import", engine=eng, auto_retrain=False)
                n += 1
            out = eng.retrain(trigger=f"import of {n} labeled cases") if n else {}
            print(f"IMPORTED\t{n}\t{out.get('version', '')}")
        return 0


    def cmd_train(a: argparse.Namespace) -> int:
        """Quick head/index/novelty update, or a full TS Pulse fine-tune. Foreground, with a progress line."""
        from .e2e.pipeline import get_engine
        from .e2e.train import profile_ids_with_labels, retrain_profile

        mode = "full" if a.full else "quick"
        device = getattr(a, "device", None) or "auto"
        s = _settings(a)
        named = str(getattr(a, "alert_type", "") or "").strip()
        legacy_name = str(getattr(a, "profile", "") or "").strip()
        if named and legacy_name and named != legacy_name:
            print("Pass one alert type. --profile is an alias of --alert-type.")
            return 2
        profile = named or legacy_name
        all_profiles = bool(getattr(a, "all_profiles", False))
        if profile or all_profiles:
            if mode == "full":
                print("train --profile and train --all retrain one alert type. Use them with --quick. train --full is the shared encoder.")
                return 2
            ids = [profile] if profile else profile_ids_with_labels(s)
            if profile and all_profiles:
                print("Pass either --profile or --all, not both.")
                return 2
            if not ids:
                print("No alert type has labels to retrain.")
                return 0
            for pid in ids:
                out = retrain_profile(s, pid, force=bool(a.force), trigger=f"CLI train --quick --profile {pid}")
                gate = out.get("gate") or {}
                print(
                    f"{'PROMOTED' if out.get('promoted') else 'KEPT'}\t{pid}\t{out.get('version')}\t{gate.get('status')}\t"
                    + "; ".join(gate.get("reasons") or [])
                )
            return 0
        eng = get_engine(s)

        def progress(frac: float, message: str) -> None:
            """Function progress."""
            print(f"[{frac:6.1%}] {message}", flush=True)

        out = eng.train(mode=mode, device=device, force=bool(a.force), epochs=a.epochs, progress=progress, trigger=f"CLI train --{mode}")
        after = out.get("after") or {}
        before = out.get("before") or {}
        print(
            f"{'PROMOTED' if out.get('promoted') else 'KEPT'}\t{out.get('version')}\t{mode}\t"
            f"action {before.get('action_acc')} -> {after.get('action_acc')}\t"
            f"signature {before.get('signature_acc')} -> {after.get('signature_acc')}\t"
            f"novelty_rate {before.get('novelty_rate')} -> {after.get('novelty_rate')}\t"
            f"one_shot {before.get('one_shot_n')}/{before.get('one_shot_acc')} -> {after.get('one_shot_n')}/{after.get('one_shot_acc')}"
        )
        if not out.get("promoted"):
            print("Held-out accuracy was worse, so the previous model stays active. Re-run with --force to promote this version.")
        return 0


    def cmd_migrate_profiles(a: argparse.Namespace) -> int:
        """Assign stored labels and cases to alert-type profiles. ``--dry-run`` writes nothing."""
