    def cmd_alert_types(a: argparse.Namespace) -> int:
        """List, check, name and create alert types. Each save is one Teach version.

        ``new`` drafts the tag list from a sample CSV, or from a stored case when
        ``--sample`` is omitted. The command itself ticks "no document yet": the
        process document is optional on the command line and required in the UI
        only when that box is left empty. Labels are a later step, not this save.
        """
        from .e2e.teach import (
            add_alias,
            check_alert_types,
            export_alert_type,
            import_alert_type,
            remove_alias,
            save_alert_type,
        )
        from .profiles import load_profiles

        s = _settings(a)
        sub = a.alert_cmd
        if sub == "list":
            report = check_alert_types(s)
            for row in report["alert_types"]:
                aliases = ", ".join(row["aliases"])
                print(f"{row['id']}\t{row['name']}\t{row['tier']}\t{aliases}")
            return 0
        if sub == "show":
            book = load_profiles(s)
            prof = book.get(a.id)
            if prof is None:
                print(f"unknown alert type {a.id!r}")
                return 2
            print(json.dumps(prof.to_dict(data_dir=s.data_dir), indent=2))
            return 0
        if sub == "check":
            print(json.dumps(check_alert_types(s), indent=2, default=str))
            return 0
        if sub == "add-alias":
            try:
                version = add_alias(s, a.type, a.name)
            except ValueError as exc:
                print(exc)
                return 2
            print(f"ALIAS\t{a.type}\t{a.name}\t{version}")
            return 0
        if sub == "remove-alias":
            try:
                version = remove_alias(s, a.type, a.name)
            except ValueError as exc:
                print(exc)
                return 2
            print(f"ALIAS REMOVED\t{a.type}\t{a.name}\t{version}")
            return 0
        if sub == "new":
            sample = str(getattr(a, "sample", "") or "").strip()
            from_case = str(getattr(a, "from_case", "") or "").strip()
            if sample:
                path = Path(sample)
                if not path.is_file():
                    print(f"sample CSV not found: {path}")
                    return 2
                csv_bytes = path.read_bytes()
            elif from_case:
                # The stored upload, not a second copy the engineer has to find.
                path = store.case_dir(s, from_case) / "input.csv"
                if not path.is_file():
                    print(f"case {from_case} has no stored input.csv; pass --sample")
                    return 2
                csv_bytes = path.read_bytes()
            else:
                print("give --sample or --from-case")
                return 2
            signatures = [part.strip() for part in str(getattr(a, "signatures", "") or "").split(",") if part.strip()]
            aliases = [str(item).strip() for item in (getattr(a, "alias", None) or []) if str(item).strip()]
            try:
                out = save_alert_type(
                    s,
                    a.name,
                    aliases=aliases,
                    csv_bytes=csv_bytes,
                    frame=str(getattr(a, "frame", "") or ""),
                    signatures=signatures,
                    no_document=True,
                )
            except ValueError as exc:
                print(exc)
                return 2
            print(f"ALERT TYPE\t{out['id']}\t{out['version']}\t{out['tier']}")
            return 0
        if sub == "export":
            try:
                dest = export_alert_type(s, a.id, Path(a.out))
            except ValueError as exc:
                print(exc)
                return 2
            print(f"EXPORTED\t{a.id}\t{dest}")
            return 0
        if sub == "import":
            try:
                out = import_alert_type(s, Path(a.path))
            except (OSError, ValueError) as exc:
                print(exc)
                return 2
            print(f"IMPORTED\t{out['id']}\t{out['version']}\t{out['path']}")
            return 0
        print("give a subcommand: list, show, check, add-alias, remove-alias, new, export, import")
        return 2


    def cmd_setup(a: argparse.Namespace) -> int:
        """Create the environment, models, starter knowledge and config. See bootstrap.setup."""
        from .bootstrap import setup

        return setup(a)


    def cmd_ui(a: argparse.Namespace) -> int:
        """Open the local NiceGUI dashboard in this process.

        The UI section stays unloaded for doctor, train and setup. ``--native`` is a desktop
        window (optional pywebview). ``--headless`` does not open a browser.
        """
        loader = None
        for name in ("sentinel_gt_ai", "__main__"):
            mod = sys.modules.get(name)
            if mod is not None and hasattr(mod, "exec_section"):
                loader = mod
                break
        if loader is None:
            import sentinel_gt_ai as loader  # type: ignore
        ui_mod = sys.modules.get("sentinel.ui")
        if ui_mod is None or not hasattr(ui_mod, "serve"):
            loader.exec_section("sentinel.ui")
            ui_mod = sys.modules["sentinel.ui"]
        show = not bool(getattr(a, "headless", False))
        native = bool(getattr(a, "native", False))
        port = int(getattr(a, "port", 8501) or 8501)
        return int(ui_mod.serve(port=port, native=native, show=show) or 0)


    def build_parser() -> argparse.ArgumentParser:
        """Function build_parser."""
        common = argparse.ArgumentParser(add_help=False)
