        es.add_parser("status", parents=[common], help="learned model + learning metrics")
        ex = es.add_parser("export-dataset", parents=[common], help="export engineer-labeled cases (labels.csv + CSVs) for training")
        ex.add_argument("--out", default=str(ROOT / "data" / "e2e" / "export"))
        ei = es.add_parser("import", parents=[common], help="import a labeled folder (labels.csv + CSVs) of real historical cases")
