        nw.add_argument("--frame", default="", help="frame key for the drafted tag aliases")
        nw.add_argument("--alias", action="append", default=[], help="extra alert name (repeatable)")
        nw.set_defaults(fn=cmd_alert_types)
        ax = ats.add_parser("export", parents=[common], help="write one alert type as schema 2 JSON")
        ax.add_argument("id")
        ax.add_argument("--out", required=True)
        ax.set_defaults(fn=cmd_alert_types)
        ai = ats.add_parser("import", parents=[common], help="load one alert-type JSON as a site file")
        ai.add_argument("path")
        ai.set_defaults(fn=cmd_alert_types)
        at.set_defaults(fn=cmd_alert_types)

        mg = sub.add_parser("migrate-profiles", parents=[common], help="assign stored labels and cases to alert-type profiles")
        mg.add_argument("--dry-run", action="store_true", help="print the plan and write nothing")
        mg.set_defaults(fn=cmd_migrate_profiles)

        su = sub.add_parser("setup", parents=[common], help="bootstrap: venv, pinned packages, models, starter knowledge")
        su.add_argument("--models-from", default="", help="hardlink or copy a models folder (USB) instead of downloading")
        su.add_argument("--skip-pip", action="store_true", help="do not create a venv and do not pip install")
        su.add_argument("--venv", action="store_true", help="always create .venv and install into it")
        su.add_argument("--train", action="store_true", help="if the fine-tuned encoder is missing, generate synthetic data and train --full")
        su.add_argument("--no-download", action="store_true", help="do not download models (use with --models-from, or when models are already there)")
        su.set_defaults(fn=cmd_setup)

        # The same UI flags sit on the main parser so `python sentinel_gt_ai.py --native`
        # works: with no command, main() appends `ui` and parses again.
        p.add_argument("--port", type=int, default=8501, help="dashboard port (default 8501)")
        p.add_argument("--headless", action="store_true", help="do not open a browser")
        p.add_argument("--native", action="store_true", help="open a desktop window (optional pywebview package)")

        u = sub.add_parser("ui", parents=[common], help="launch the local NiceGUI dashboard (default)")
        u.add_argument("--port", type=int, default=8501)
