# <<<<<<< SECTION sentinel.generator scripts/generate_scenario_csvs.py
if False:  # compiled by exec_section('sentinel.generator'); not executed as part of this module
    #!/usr/bin/env python3
    """
    Generate synthetic gas-turbine historian CSVs.

    1. Scenario samples (default, unchanged — the rule-path test ground truth):
       - 10× combustion cold spot   — 2 months, 10-minute resolution
       - 5×  HETS trips             — 2 months, 10-minute resolution
       - 10× combustion dynamics    — 10 days, 1-minute resolution

    2. Labeled training/evaluation dataset for the end-to-end learned path (``--dataset``):
       8 signatures (normal, cold spot hardware, TC sensor fault, combustion instability,
       dynamics probe fault, HETS trip, IGV LVDT drift, fuel control oscillation) with varied
       frames, resolutions, record lengths, tag naming, operating profiles, missing data,
       ambiguous cases and noisy notes; splits train / val / test (iid held-out), variant
       (shifted can, load, magnitude) and unseen (a fault type never used in training).
       See ``generate_dataset``.

           python scripts/generate_scenario_csvs.py                       # scenario samples
           python scripts/generate_scenario_csvs.py --dataset data/e2e/dataset [--scale 1.0]

    Timestamps use real calendar dates (timezone-naive local plant time).
    """

    # @@future@@ from __future__ import annotations

    from pathlib import Path

    import numpy as np
    import pandas as pd

    ROOT = Path(__file__).resolve().parents[1]
    SAMPLES = ROOT / "samples"
    OUT_COLD = SAMPLES / "cold_spot"
    OUT_HETS = SAMPLES / "hets_trip"
    OUT_DYN = SAMPLES / "combustion_dynamics"

    # Exhaust TC ring size for cold-spot cases (plant-style circumferential array)
    N_EXHAUST_TC = 27
    TC_COLS = [f"TC{i}" for i in range(1, N_EXHAUST_TC + 1)]

    # Column set for HETS / dynamics (4 zone summary + process)
    COLUMNS = [
        "timestamp",
        "load_MW",
        "CDP_bar",
        "CDT_C",
        "EGT_avg_C",
        "EGT_spread_C",
        "EGT_Z1_C",
        "EGT_Z2_C",
        "EGT_Z3_C",
        "EGT_Z4_C",
        "fuel_flow_kg_s",
        "IGV_deg",
        "vib_DE_mm_s",
        "vib_NDE_mm_s",
        "lube_oil_C",
        "comb_dyn_psi",
        "trip_active",
    ]

    # Cold-spot columns: process + full TC1..TC27 ring (no EGT_Z*)
    COLUMNS_COLD = (
        [
            "timestamp",
            "load_MW",
            "CDP_bar",
            "CDT_C",
            "EGT_avg_C",
            "EGT_spread_C",
        ]
        + TC_COLS
        + [
            "fuel_flow_kg_s",
            "IGV_deg",
            "vib_DE_mm_s",
            "vib_NDE_mm_s",
            "lube_oil_C",
            "comb_dyn_psi",
            "trip_active",
        ]
    )


    def _baseload_core(
        index: pd.DatetimeIndex, rng: np.random.Generator
    ) -> tuple[pd.DataFrame, np.ndarray, np.ndarray]:
        """Shared process signals; returns (partial_df_without_TCs, load, egt_mean)."""
        n = len(index)
        hour = np.asarray(index.hour, dtype=float) + np.asarray(index.minute, dtype=float) / 60.0
        load = 48.0 + 1.2 * np.sin(2 * np.pi * (hour - 8) / 24.0) + rng.normal(0, 0.15, n)
        load = np.asarray(np.clip(load, 35.0, 55.0), dtype=float)

        cdp = 11.1 + 0.04 * (load - 48) + rng.normal(0, 0.03, n)
        cdt = 345.0 + 0.8 * (load - 48) + rng.normal(0, 0.25, n)
        egt_mean = np.asarray(
            540.0 + 1.1 * (load - 48) + rng.normal(0, 0.4, n), dtype=float
        )

        fuel = 2.85 + 0.035 * (load - 48) + rng.normal(0, 0.01, n)
        igv = 62.0 + 0.25 * (load - 48) + rng.normal(0, 0.15, n)
        vib_de = 3.05 + rng.normal(0, 0.08, n)
        vib_nde = 2.95 + rng.normal(0, 0.08, n)
        lube = 58.0 + 0.05 * (load - 48) + rng.normal(0, 0.12, n)
        dyn = np.clip(0.35 + rng.normal(0, 0.05, n), 0.05, 1.2)

        base = pd.DataFrame(
            {
                "timestamp": index,
                "load_MW": np.round(load, 3),
                "CDP_bar": np.round(cdp, 3),
                "CDT_C": np.round(cdt, 3),
                "fuel_flow_kg_s": np.round(fuel, 4),
                "IGV_deg": np.round(igv, 3),
                "vib_DE_mm_s": np.round(vib_de, 3),
                "vib_NDE_mm_s": np.round(vib_nde, 3),
                "lube_oil_C": np.round(lube, 3),
                "comb_dyn_psi": np.round(dyn, 3),
                "trip_active": 0,
            }
        )
        return base, load, egt_mean


    def _baseload_frame(index: pd.DatetimeIndex, rng: np.random.Generator) -> pd.DataFrame:
        """Healthy baseload with 4 zone EGTs (HETS / dynamics samples)."""
        base, load, egt_mean = _baseload_core(index, rng)
        n = len(index)
        z = np.column_stack([egt_mean + rng.normal(0, 1.2, n) for _ in range(4)])
        base["EGT_avg_C"] = np.round(z.mean(axis=1), 3)
        base["EGT_spread_C"] = np.round(z.max(axis=1) - z.min(axis=1), 3)
        for i in range(4):
            base[f"EGT_Z{i + 1}_C"] = np.round(z[:, i], 3)
        return base[COLUMNS]


    def _baseload_frame_cold(
        index: pd.DatetimeIndex, rng: np.random.Generator
    ) -> pd.DataFrame:
        """Healthy baseload with full exhaust TC ring TC1..TC27."""
        base, _load, egt_mean = _baseload_core(index, rng)
        n = len(index)
        # Circumferential pattern: small spatial sine + independent noise
        angles = 2 * np.pi * np.arange(N_EXHAUST_TC) / N_EXHAUST_TC
        spatial = 1.5 * np.sin(angles)[None, :]  # mild fixed pattern
        tc = egt_mean[:, None] + spatial + rng.normal(0, 1.0, (n, N_EXHAUST_TC))
        for i, col in enumerate(TC_COLS):
            base[col] = np.round(tc[:, i], 3)
        base["EGT_avg_C"] = np.round(tc.mean(axis=1), 3)
        base["EGT_spread_C"] = np.round(tc.max(axis=1) - tc.min(axis=1), 3)
        return base[COLUMNS_COLD]


    def _inject_cold_spot(
        df: pd.DataFrame,
        rng: np.random.Generator,
        *,
        cold_tc: int,
        onset_frac: float,
        depth_C: float,
        duration_frac: float,
        load_dip: bool,
        sector_width: int = 3,
    ) -> pd.DataFrame:
        """
        Inject a circumferential cold sector on the TC1..TC27 ring.

        cold_tc : 1..27 primary cold thermocouple (neighbors also cool slightly).
        sector_width : odd-ish count of adjacent TCs in the cold sector (wraps ring).
        """
        out = df.copy()
        n = len(out)
        start = int(n * onset_frac)
        end = min(n, start + max(12, int(n * duration_frac)))
        width = max(1, int(sector_width))
        # Adjacent indices on a 27-point ring (0-based)
        center = (int(cold_tc) - 1) % N_EXHAUST_TC
        half = width // 2
        sector = [((center + k) % N_EXHAUST_TC) for k in range(-half, half + 1)]
        # Center deepest; neighbors 40–70% of depth
        weights = []
        for idx in sector:
            dist = min((idx - center) % N_EXHAUST_TC, (center - idx) % N_EXHAUST_TC)
            weights.append(1.0 if dist == 0 else max(0.35, 1.0 - 0.28 * dist))

        ramp_n = min(36, end - start)
        ramp = np.linspace(0, 1.0, ramp_n)
        hold = np.ones(max(0, end - start - ramp_n))
        envelope = np.concatenate([ramp, hold])[: end - start]

        tc = out[TC_COLS].to_numpy(copy=True)
        for w, idx in zip(weights, sector):
            bias = depth_C * w * envelope + rng.normal(0, 0.35, len(envelope))
            tc[start:end, idx] = tc[start:end, idx] - bias

        for i, col in enumerate(TC_COLS):
            out[col] = np.round(tc[:, i], 3)
        out["EGT_avg_C"] = np.round(tc.mean(axis=1), 3)
        out["EGT_spread_C"] = np.round(tc.max(axis=1) - tc.min(axis=1), 3)

        # Mild fuel / performance coupling
        out.loc[out.index[start:end], "fuel_flow_kg_s"] = np.round(
            out.loc[out.index[start:end], "fuel_flow_kg_s"].to_numpy()
            + 0.02
            + rng.normal(0, 0.005, end - start),
            4,
        )
        if load_dip:
            out.loc[out.index[start:end], "load_MW"] = np.round(
                out.loc[out.index[start:end], "load_MW"].to_numpy() - 0.4 - rng.uniform(0, 0.6),
                3,
            )
        if depth_C >= 28:
            out.loc[out.index[start:end], "vib_DE_mm_s"] = np.round(
                out.loc[out.index[start:end], "vib_DE_mm_s"].to_numpy() + 0.4, 3
            )
        return out


    def _inject_hets_trip(
        df: pd.DataFrame,
        rng: np.random.Generator,
        *,
        trip_frac: float,
        peak_spread_C: float,
        recovery: bool,
    ) -> pd.DataFrame:
        """
        High Exhaust Temperature Spread (HETS) trip signature:
        rapid spread rise → protection trip → load collapse → optional recovery.
        """
        out = df.copy()
        n = len(out)
        trip_i = int(n * trip_frac)
        pre = max(0, trip_i - 18)  # ~3 hours at 10-min (18*10m)
        # Build-up: sectors diverge
        build = np.linspace(0, 1.0, trip_i - pre)
        z = out[[f"EGT_Z{i}_C" for i in range(1, 5)]].to_numpy(copy=True)
        # Make Z1 hot, Z3 cold for true spread (not single TC)
        for j, idx in enumerate(range(pre, trip_i)):
            f = build[j]
            z[idx, 0] += f * (peak_spread_C * 0.55) + rng.normal(0, 0.5)
            z[idx, 2] -= f * (peak_spread_C * 0.45) + rng.normal(0, 0.5)
            z[idx, 1] += f * 2.0
            z[idx, 3] -= f * 1.5

        # Trip window: ~40 minutes
        trip_end = min(n, trip_i + 4)
        for idx in range(trip_i, trip_end):
            z[idx, 0] += peak_spread_C * 0.6 + rng.normal(0, 1.0)
            z[idx, 2] -= peak_spread_C * 0.5 + rng.normal(0, 1.0)
            out.loc[out.index[idx], "trip_active"] = 1
            out.loc[out.index[idx], "load_MW"] = max(0.0, float(out.loc[out.index[idx], "load_MW"]) * 0.15)
            out.loc[out.index[idx], "fuel_flow_kg_s"] = max(
                0.2, float(out.loc[out.index[idx], "fuel_flow_kg_s"]) * 0.2
            )
            out.loc[out.index[idx], "IGV_deg"] = 25.0 + rng.normal(0, 1.0)
            out.loc[out.index[idx], "vib_DE_mm_s"] = 6.5 + rng.normal(0, 0.3)
            out.loc[out.index[idx], "vib_NDE_mm_s"] = 5.8 + rng.normal(0, 0.3)
            out.loc[out.index[idx], "comb_dyn_psi"] = 1.8 + rng.normal(0, 0.2)

        if recovery and trip_end < n:
            # Coast / restart to baseload over ~1 day
            rec_end = min(n, trip_end + 144)  # 144*10min = 24h
            for k, idx in enumerate(range(trip_end, rec_end)):
                f = min(1.0, k / max(1, rec_end - trip_end - 1))
                # zones re-blend toward mean
                mean = z[idx].mean()
                z[idx] = mean + (z[idx] - mean) * (1.0 - 0.85 * f)
                out.loc[out.index[idx], "load_MW"] = 20.0 + f * 28.0 + rng.normal(0, 0.2)
                out.loc[out.index[idx], "trip_active"] = 0

        out[[f"EGT_Z{i}_C" for i in range(1, 5)]] = np.round(z, 3)
        out["EGT_avg_C"] = np.round(z.mean(axis=1), 3)
        out["EGT_spread_C"] = np.round(z.max(axis=1) - z.min(axis=1), 3)
        # Clip physical-ish bounds
        out["load_MW"] = np.clip(out["load_MW"], 0, 60)
        out["vib_DE_mm_s"] = np.round(np.clip(out["vib_DE_mm_s"], 0.5, 15), 3)
        out["vib_NDE_mm_s"] = np.round(np.clip(out["vib_NDE_mm_s"], 0.5, 15), 3)
        out["comb_dyn_psi"] = np.round(np.clip(out["comb_dyn_psi"], 0.05, 8), 3)
        return out


    def _inject_combustion_dynamics(
        df: pd.DataFrame,
        rng: np.random.Generator,
        *,
        onset_frac: float,
        severity: float,
        tone_period_min: float,
    ) -> pd.DataFrame:
        """
        Combustion dynamics (pulsation) burst at 1-minute resolution.
        severity: 0.5 mild → 3.0 severe (psi peak)
        """
        out = df.copy()
        n = len(out)
        start = int(n * onset_frac)
        # Event lasts 6–18 hours
        dur = int(rng.integers(6 * 60, 18 * 60))
        end = min(n, start + dur)
        t = np.arange(end - start, dtype=float)
        period = max(2.0, tone_period_min)
        osc = severity * (0.55 + 0.45 * np.sin(2 * np.pi * t / period))
        osc += 0.15 * severity * np.sin(2 * np.pi * t / (period * 0.37))
        osc += rng.normal(0, 0.08 * severity, len(t))
        osc = np.clip(osc, 0.1, 8.0)

        base = out.loc[out.index[start:end], "comb_dyn_psi"].to_numpy()
        out.loc[out.index[start:end], "comb_dyn_psi"] = np.round(base + osc, 3)

        # Couple to EGT spread flutter and mild vib
        zcols = [f"EGT_Z{i}_C" for i in range(1, 5)]
        z = out.loc[out.index[start:end], zcols].to_numpy(copy=True)
        flutter = (osc / max(severity, 1e-6)) * rng.uniform(3.0, 8.0)
        z[:, 0] += flutter * 0.6
        z[:, 2] -= flutter * 0.5
        out.loc[out.index[start:end], zcols] = np.round(z, 3)
        out.loc[out.index[start:end], "EGT_avg_C"] = np.round(z.mean(axis=1), 3)
        out.loc[out.index[start:end], "EGT_spread_C"] = np.round(z.max(axis=1) - z.min(axis=1), 3)
        out.loc[out.index[start:end], "vib_DE_mm_s"] = np.round(
            out.loc[out.index[start:end], "vib_DE_mm_s"].to_numpy() + 0.25 * osc, 3
        )
        out.loc[out.index[start:end], "fuel_flow_kg_s"] = np.round(
            out.loc[out.index[start:end], "fuel_flow_kg_s"].to_numpy()
            + 0.01 * (osc / max(severity, 1e-6)),
            4,
        )
        return out


    def _write(df: pd.DataFrame, path: Path, meta: str) -> None:
        """Function _write."""
        path.parent.mkdir(parents=True, exist_ok=True)
        # ISO-8601 timestamps without timezone (plant local)
        out = df.copy()
        out["timestamp"] = pd.to_datetime(out["timestamp"]).dt.strftime("%Y-%m-%d %H:%M:%S")
        out.to_csv(path, index=False)
        print(f"  wrote {path.relative_to(ROOT)}  rows={len(out)}  {meta}")


    def generate_all() -> None:
        """Function generate_all."""
        OUT_COLD.mkdir(parents=True, exist_ok=True)
        OUT_HETS.mkdir(parents=True, exist_ok=True)
        OUT_DYN.mkdir(parents=True, exist_ok=True)

        # --- Cold spots: 2 months @ 10 min, staggered start dates, TC1..TC27 ---
        print("Combustion cold spots (10 files, ~2 months @ 10 min, TC1–TC27)…")
        cold_starts = [
            "2025-11-01",
            "2025-12-01",
            "2026-01-05",
            "2026-02-01",
            "2026-03-01",
            "2026-04-01",
            "2026-05-01",
            "2026-06-01",
            "2025-09-15",
            "2025-10-10",
        ]
        for i, start in enumerate(cold_starts, start=1):
            rng = np.random.default_rng(1000 + i)
            idx = pd.date_range(start=start, periods=60 * 24 * 6, freq="10min")  # 60 days
            df = _baseload_frame_cold(idx, rng)
            # Spread cold centers around the 27-TC ring
            cold_tc = 1 + ((i - 1) * 3) % N_EXHAUST_TC  # TC1,4,7,..., then wrap
            depth = 18 + (i % 5) * 4  # 18..34 C center depth
            onset = 0.35 + 0.03 * (i % 4)
            dur = 0.08 + 0.02 * (i % 3)  # multi-day event
            sector_w = 3 if i % 3 else 5  # 3- or 5-TC cold sector
            df = _inject_cold_spot(
                df,
                rng,
                cold_tc=cold_tc,
                onset_frac=onset,
                depth_C=float(depth),
                duration_frac=dur,
                load_dip=(i % 2 == 0),
                sector_width=sector_w,
            )
            _write(
                df,
                OUT_COLD / f"cold_spot_{i:02d}.csv",
                f"cold_center=TC{cold_tc} sector={sector_w} depth≈{depth}C start={start}",
            )

        # --- HETS trips: 2 months @ 10 min ---
        print("HETS trips (5 files, ~2 months @ 10 min)…")
        hets_starts = [
            "2025-08-01",
            "2025-11-15",
            "2026-01-10",
            "2026-03-20",
            "2026-05-12",
        ]
        for i, start in enumerate(hets_starts, start=1):
            rng = np.random.default_rng(2000 + i)
            idx = pd.date_range(start=start, periods=60 * 24 * 6, freq="10min")
            df = _baseload_frame(idx, rng)
            peak = 48 + i * 4  # trip-class spreads
            trip_frac = 0.55 + 0.02 * i
            df = _inject_hets_trip(
                df,
                rng,
                trip_frac=trip_frac,
                peak_spread_C=float(peak),
                recovery=(i != 3),  # one case leaves unit offline-ish longer
            )
            _write(
                df,
                OUT_HETS / f"hets_trip_{i:02d}.csv",
                f"peak_spread≈{peak}C trip≈{trip_frac:.2f} start={start}",
            )

        # --- Combustion dynamics: 10 days @ 1 min ---
        print("Combustion dynamics (10 files, 10 days @ 1 min)…")
        dyn_starts = [
            "2026-01-08",
            "2026-01-22",
            "2026-02-05",
            "2026-02-18",
            "2026-03-03",
            "2026-03-17",
            "2026-04-02",
            "2026-04-20",
            "2026-05-06",
            "2026-05-25",
        ]
        for i, start in enumerate(dyn_starts, start=1):
            rng = np.random.default_rng(3000 + i)
            idx = pd.date_range(start=start, periods=10 * 24 * 60, freq="1min")
            df = _baseload_frame(idx, rng)
            severity = 0.8 + 0.25 * i  # psi-class peaks
            period = 3.0 + (i % 5)  # minutes between pulsation peaks in envelope
            onset = 0.25 + 0.04 * (i % 5)
            df = _inject_combustion_dynamics(
                df,
                rng,
                onset_frac=onset,
                severity=float(severity),
                tone_period_min=float(period),
            )
            _write(
                df,
                OUT_DYN / f"comb_dyn_{i:02d}.csv",
                f"severity≈{severity:.2f}psi period≈{period}min start={start}",
            )

        # Manifest
        manifest = SAMPLES / "SCENARIO_README.md"
        manifest.write_text(
            """# Scenario sample CSVs

    Generated by `scripts/generate_scenario_csvs.py`.

    | Folder | Cases | Duration | Resolution | Signature |
    |--------|------:|----------|------------|-----------|
    | `cold_spot/` | 10 | ~60 days | 10 min | Cold sector on **TC1–TC27** ring → elevated `EGT_spread_C` |
    | `hets_trip/` | 5 | ~60 days | 10 min | Rapid spread rise, `trip_active=1`, load/fuel collapse |
    | `combustion_dynamics/` | 10 | 10 days | 1 min | Elevated `comb_dyn_psi` with EGT flutter / mild vib |

    ## Columns
    **Cold spot:** `timestamp, load_MW, CDP_bar, CDT_C, EGT_avg_C, EGT_spread_C, TC1..TC27,
    fuel_flow_kg_s, IGV_deg, vib_DE_mm_s, vib_NDE_mm_s, lube_oil_C, comb_dyn_psi, trip_active`

    **HETS / dynamics:** same process channels with `EGT_Z1_C..EGT_Z4_C` instead of TC1–TC27

    Timestamps are real calendar datetimes (`YYYY-MM-DD HH:MM:SS`).

    ## Process maps (RAG)
    See `knowledge/process_map_cold_spot.md`, `process_map_hets_trip.md`,
    `process_map_combustion_dynamics.md`.

    ## Suggested TUI tests
    1. **Cold spot** — `samples/cold_spot/cold_spot_01.csv`, mode **Alerts**, paste cold-spot process map notes.
    2. **HETS** — `samples/hets_trip/hets_trip_01.csv`, mode **Trips/Event**, note trip first-out HETS.
    3. **Dynamics** — `samples/combustion_dynamics/comb_dyn_01.csv`, mode **Alerts** or **Trips/Event**.

    Regenerate:
    ```bash
    python scripts/generate_scenario_csvs.py
    ```
    """,
            encoding="utf-8",
        )
        print(f"  wrote {manifest.relative_to(ROOT)}")
        print("Done.")


    # =========================================================================== labeled dataset
    # Larger, varied, labeled synthetic set for the end-to-end learned path (``--dataset``).

    import argparse  # noqa: E402
    import hashlib  # noqa: E402
    import json  # noqa: E402
    import sys  # noqa: E402
    from typing import Any, Dict, List, Optional, Tuple  # noqa: E402

    if str(ROOT) not in sys.path:
        sys.path.insert(0, str(ROOT))

    from sentinel.e2e.taxonomy import BASE_SIGNATURES, UNSEEN_SIGNATURES  # noqa: E402

    # The shipped training set stays these eight. The newer taxonomy ids are real
    # signatures; the generator learns to write them in a later step. Counting
    # them here would change the dataset size the current bundle was trained on.
    _ORIGINAL_SEEN = (
        "normal",
        "cold_spot_hardware",
        "tc_sensor_fault",
        "combustion_instability",
        "dynamics_probe_fault",
        "hets_trip_hardware",
        "igv_lvdt_drift",
        "fuel_control_oscillation",
    )
    SEEN = [s for s in _ORIGINAL_SEEN if s in BASE_SIGNATURES]
    UNSEEN = list(UNSEEN_SIGNATURES)
    SPLIT_COUNTS = {"train": 150, "val": 25, "test": 40}  # per seen signature (scale=1)
    VARIANT_CLASSES = ["cold_spot_hardware", "tc_sensor_fault", "combustion_instability", "hets_trip_hardware", "igv_lvdt_drift"]
    VARIANT_KINDS = ["shifted", "load", "magnitude"]
    VARIANT_COUNT = 8  # per (class, variant kind)
    UNSEEN_COUNT = 40
    # Held-out sensor-fault set (V2): one TC steps down by a cold-spot-sized amount, alone, on a ring,
    # raised as a cold spot. Truth: tc_sensor_fault (sensor repair). Tests the residual cross-check.
    SENSOR_FAULT_COUNT = 40

    # OEM-style historian tags, used for ~30 % of files (exercises channel-role mapping)
    ALT_TAGS = {
        "load_MW": "DWATT", "CDP_bar": "CPD", "CDT_C": "CTD", "EGT_avg_C": "TTXM", "EGT_spread_C": "TTXSP1",
        "fuel_flow_kg_s": "FQG", "IGV_deg": "CSGV", "vib_DE_mm_s": "BB1", "vib_NDE_mm_s": "BB2",
        "lube_oil_C": "LTOT", "comb_dyn_psi": "CDM_AMP", "trip_active": "TRIP_FLAG",
    }

    ANALYTIC_NAMES = {
        "normal": ["Exhaust Cold Spot", "Combustion Dynamics High", "High exhaust spread advisory", "Exhaust TC deviation",
                   "Performance deviation", "comb dyn high", "IGV position deviation", "Load hunting"],
        "cold_spot_hardware": ["Exhaust Cold Spot", "Exhaust temperature cold spot", "Cold spot TC ring", "TTXD cold spot", "exh cold spot alarm"],
        "tc_sensor_fault": ["Exhaust Cold Spot", "Exhaust TC deviation", "High exhaust spread advisory", "TC failure advisory"],
        "combustion_instability": ["Combustion Dynamics High", "comb dyn high", "CDM pulsation alarm", "Combustion humming"],
        "dynamics_probe_fault": ["Combustion Dynamics High", "comb dyn high", "CDM channel alarm"],
        "hets_trip_hardware": ["HETS Trip", "High exhaust spread trip", "Unit trip - exhaust spread"],
        "igv_lvdt_drift": ["IGV position deviation", "IGV LVDT mismatch", "Compressor IGV advisory"],
        "fuel_control_oscillation": ["Fuel control oscillation", "Load hunting", "Fuel valve oscillation advisory"],
        "bearing_vibration": ["Bearing vibration high", "Vibration advisory BB1", "High vibration alarm"],
        "tc_harness_fault": ["Exhaust Cold Spot", "High exhaust spread advisory", "TTXD cold spot", "Exhaust TC deviation"],
    }
    GENERIC_ANALYTICS = ["GT alarm review", "Tier 1 escalation", "Exhaust temperature deviation advisory", "Unit advisory"]

    HINTS = {
        "normal": ["Alert cleared on its own after a few hours.", "No operator complaints.", "Alert may be a false positive."],
        "cold_spot_hardware": ["Operator noticed exhaust spread creeping up over a few days.", "Fuel nozzle work done at last CI.",
                               "Spread has been trending up since last week."],
        "tc_sensor_fault": ["TC{tc} has been erratic before.", "I&C replaced the harness near TC{tc} last outage.",
                            "Reading on TC{tc} looks odd to the operator."],
        "combustion_instability": ["Operator reports humming from the combustor area.", "Unit was re-tuned last month.",
                                   "Dynamics alarms after the load change this morning."],
        "dynamics_probe_fault": ["Dynamics probe cable was disturbed during maintenance.", "CDM channel shows strange values.",
                                 "No humming heard on site."],
        "hets_trip_hardware": ["Unit tripped, first-out: high exhaust spread.", "Trip on HETS, unit restarted after checks.",
                               "Control room reports exhaust spread trip."],
        "igv_lvdt_drift": ["IGV calibration last done two years ago.", "Operator noticed IGV indication differs from local gauge.",
                           "Servo work done recently on IGV actuator."],
        "fuel_control_oscillation": ["Control room reports load hunting.", "Fuel valve was replaced last outage.",
                                     "Megawatts swinging slightly at baseload."],
        "bearing_vibration": ["Operator reports noise near bearing 1.", "Lube oil temperature alarm came in later.",
                              "Vibration trending up for days."],
        "tc_harness_fault": ["I&C was working in the turbine compartment last week.", "Several TCs on one side dropped out briefly.",
                             "Harness junction box was opened during the outage."],
    }
    FILLER = ["Please review asap.", "Ambient about 35 C today.", "Tier 1: alert auto-generated.", "Unit on AGC.",
              "Customer asked for a quick answer.", "Night shift, no further info.", "See attached data.", ""]


    def _seed(*parts: Any) -> int:
        """Function _seed."""
        return int(hashlib.sha256("|".join(map(str, parts)).encode()).hexdigest()[:8], 16)


    def _noisy(text: str, rng: np.random.Generator) -> str:
        """Typos, lower case and dropped punctuation, as in real hand-typed notes."""
        if rng.random() < 0.3:
            text = text.lower()
        if rng.random() < 0.3:
            text = text.replace(".", "").replace(",", "")
        chars = list(text)
        for _ in range(int(rng.integers(0, 3))):
            if len(chars) > 4:
                i = int(rng.integers(1, len(chars) - 1))
                chars[i], chars[i - 1] = chars[i - 1], chars[i]
        return "".join(chars)


    def _notes(sig: str, rng: np.random.Generator, tc: Optional[int]) -> Tuple[str, Dict[str, Any]]:
        """Function _notes."""
        parts: List[str] = []
        meta: Dict[str, Any] = {"hint": "none"}
        if rng.random() < 0.8:
            unit = str(rng.choice([f"Unit {rng.integers(1, 7)}", f"GT{rng.integers(1, 7)}", f"CT-{rng.integers(1, 5)}"]))
            parts.append(unit + "," + str(rng.choice([" 7FA.03", " 7F.05", " 9FA", " 6B", " 7HA.02", ""])) + ".")
        r = rng.random()
        if r < 0.45:  # helpful hint
            book = HINTS.get(sig) or HINTS["normal"]
            parts.append(str(rng.choice(book)).format(tc=tc or int(rng.integers(1, 25))))
            meta["hint"] = "helpful"
        elif r < 0.55:  # misleading hint from another signature
            other = str(rng.choice([s for s in SEEN if s != sig]))
            parts.append(str(rng.choice(HINTS[other])).format(tc=int(rng.integers(1, 25))))
            meta["hint"] = f"misleading:{other}"
        parts.append(str(rng.choice(FILLER)))
        text = " ".join(p for p in parts if p).strip()
        if rng.random() < 0.25:
            text = _noisy(text, rng)
        return text, meta


    def _frame_params(rng: np.random.Generator, load_variant: bool) -> Dict[str, float]:
        """Function _frame_params."""
        if load_variant:  # a much larger frame: different absolute levels and noise
            return {"rated": rng.uniform(150, 260), "egt0": rng.uniform(590, 640), "cdp0": rng.uniform(15, 20),
                    "cdt0": rng.uniform(390, 430), "fuel0": rng.uniform(8, 14), "dyn0": rng.uniform(0.6, 0.9),
                    "vib0": rng.uniform(2.0, 4.5), "spatial": rng.uniform(1.0, 4.0), "tc_noise": rng.uniform(1.0, 2.2)}
        return {"rated": rng.uniform(40, 60), "egt0": rng.uniform(525, 560), "cdp0": rng.uniform(10.5, 12),
                "cdt0": rng.uniform(335, 355), "fuel0": rng.uniform(2.5, 3.2), "dyn0": rng.uniform(0.25, 0.45),
                "vib0": rng.uniform(2.5, 3.5), "spatial": rng.uniform(0.5, 2.5), "tc_noise": rng.uniform(0.6, 1.4)}


    def _load_profile(rng: np.random.Generator, n: int, freq: float, kind: str) -> np.ndarray:
        """Function _load_profile."""
        hours = np.arange(n) * freq / 60.0
        f = 0.95 + 0.02 * np.sin(2 * np.pi * (hours - rng.uniform(0, 24)) / 24.0) + rng.normal(0, 0.003, n)
        if kind == "steps":
            level = np.empty(n)
            i = 0
            while i < n:
                seg = int(rng.uniform(6, 48) * 60 / freq)
                level[i : i + seg] = rng.uniform(0.65, 1.0)
                i += seg
            ramp = max(1, int(30 / freq))
            level = pd.Series(level).rolling(ramp, min_periods=1).mean().to_numpy()
            f = f - 0.95 + level
        elif kind == "cycling":
            day = (hours // 24).astype(int)
            hod = hours % 24
            off_days = [d for d in range(int(day.max()) + 1) if rng.random() < 0.6]
            off_start, off_len = rng.uniform(21, 24), rng.uniform(5, 9)
            rel = (hod - off_start) % 24
            off = np.isin(day, off_days) & (rel < off_len)
            ramp = max(1, int(45 / freq))
            avail = pd.Series((~off).astype(float)).rolling(ramp, min_periods=1).mean().to_numpy()
            f = f * avail
        return np.clip(f, 0.0, 1.02)


    def _base_arrays(rng: np.random.Generator, n: int, freq: float, layout: str, n_tc: int, fp: Dict[str, float], profile: str) -> Dict[str, Any]:
        """Function _base_arrays."""
        f = _load_profile(rng, n, freq, profile)
        online = f > 0.2
        k = fp["rated"] / 48.0
        load = np.where(online, fp["rated"] * f + rng.normal(0, 0.15 * k, n), np.clip(fp["rated"] * f, 0, None))
        egt = np.where(online, fp["egt0"] - 25 * (1 - f) + rng.normal(0, 0.4, n), 140 + 30 * f + rng.normal(0, 1.0, n))
        dyn_noise = 0.05 * max(1.0, fp["dyn0"] / 0.35)
        a: Dict[str, Any] = {
            "f": f,
            "online": online,
            "load_MW": load,
            "CDP_bar": fp["cdp0"] * (0.55 + 0.45 * f) + rng.normal(0, 0.03, n),
            "CDT_C": fp["cdt0"] * (0.8 + 0.2 * f) + rng.normal(0, 0.25, n),
            "fuel_flow_kg_s": np.where(online, fp["fuel0"] * f, 0.0) + rng.normal(0, 0.004 * fp["fuel0"], n) * online,
            "IGV_deg": np.where(online, 30 + 32 * np.clip((f - 0.3) / 0.6, 0, 1), 28.0) + rng.normal(0, 0.15, n),
            "vib_DE_mm_s": np.where(online, fp["vib0"], 0.6) + rng.normal(0, 0.08, n),
            "vib_NDE_mm_s": np.where(online, fp["vib0"] * 0.95, 0.55) + rng.normal(0, 0.08, n),
            "lube_oil_C": 56 + 2.5 * f + rng.normal(0, 0.12, n),
            "comb_dyn_psi": np.where(online, fp["dyn0"] + np.abs(rng.normal(0, dyn_noise, n)), 0.05),
            "trip_active": np.zeros(n),
        }
        m = n_tc if layout == "ring" else 4
        angles = 2 * np.pi * np.arange(m) / m
        spatial = fp["spatial"] * np.sin(angles + rng.uniform(0, 2 * np.pi)) + rng.normal(0, 0.6, m)
        noise = fp["tc_noise"] if layout == "ring" else fp["tc_noise"] * 1.2
        a["temps"] = egt[:, None] + np.where(online[:, None], spatial[None, :], 0.0) + rng.normal(0, noise, (n, m))
        a["egt_mean"] = egt
        return a


    def _event_window(rng: np.random.Generator, n: int, freq: float, dur_h: Tuple[float, float], ambiguous: bool) -> Tuple[int, int]:
        # Tier 2 exports put most of the record before the alert: onset at 50-85 % of the record
        """Function _event_window."""
        min_base = int(24 * 60 / freq)
        lo = max(min_base, int(0.5 * n))
        if ambiguous and rng.random() < 0.5:
            s = int(n * rng.uniform(0.9, 0.96))  # event only just starting at the end of the record
        else:
            s = int(rng.uniform(lo, max(lo + 1, 0.85 * n)))
        s = min(max(s, min_base), n - 2)
        e = min(n, s + max(2, int(rng.uniform(*dur_h) * 60 / freq)))
        return s, e


    def _ramp_env(n: int, s: int, e: int, ramp: int, persist: bool) -> np.ndarray:
        """Function _ramp_env."""
        env = np.zeros(n)
        ramp = max(1, min(ramp, e - s))
        env[s : s + ramp] = np.linspace(0, 1, ramp)
        env[s + ramp : e] = 1.0
        if persist:
            env[e:] = 1.0
        elif e < n:
            r2 = min(ramp, n - e)
            env[e : e + r2] = np.linspace(1, 0, r2)
        return env


    def _inj_cold_spot(a, rng, p, layout, freq, variant, ambiguous):
        """Function _inj_cold_spot."""
        n, m = a["temps"].shape
        depth = rng.uniform(12, 35)
        if variant == "magnitude":
            depth = rng.uniform(5, 9) if rng.random() < 0.5 else rng.uniform(40, 60)
        elif ambiguous:
            depth = rng.uniform(7, 12)
        s, e = _event_window(rng, n, freq, (24, 24 * 8), ambiguous)
        env = _ramp_env(n, s, e, int(rng.uniform(2, 12) * 60 / freq), persist=rng.random() < 0.7) * a["online"]
        if layout == "ring":
            width = int(rng.choice([2, 3, 4, 5])) if not ambiguous else 2
            center = int(rng.integers(0, m))
            if variant == "shifted":
                center = int(rng.choice([0, m - 1]))  # sector straddles the ring wrap-around (TCn | TC1)
            members = [(center + d) % m for d in range(-(width // 2), width - width // 2)]
            for idx in members:
                dist = min((idx - center) % m, (center - idx) % m)
                w = 1.0 if dist == 0 else rng.uniform(0.45, 0.75) / dist
                a["temps"][:, idx] -= depth * w * env + rng.normal(0, 0.3, n) * (env > 0)
            p.update(center_tc=center + 1, sector_width=width)
        else:
            z = int(rng.integers(0, 4))
            a["temps"][:, z] -= 0.55 * depth * env
            a["temps"][:, (z + 1) % 4] -= 0.15 * depth * env
            p.update(cold_zone=z + 1)
        a["fuel_flow_kg_s"] *= 1 + rng.uniform(0.004, 0.01) * env
        if depth > 28:
            a["vib_DE_mm_s"] += 0.3 * env
        p.update(depth_C=round(float(depth), 1))
        return s, e


    def _inj_tc_sensor(a, rng, p, layout, freq, variant, ambiguous):
        """Function _inj_tc_sensor."""
        n, m = a["temps"].shape
        j = int(rng.integers(0, m))
        if variant == "shifted":
            j = int(rng.choice([0, m - 1]))
        mode = str(rng.choice(["step", "open", "flatline", "erratic", "drift"]))
        if ambiguous:
            mode = "drift"
        s, e = _event_window(rng, n, freq, (12, 24 * 10), ambiguous)
        x = a["temps"][:, j]
        big = variant == "magnitude"
        if mode == "step":
            off = rng.uniform(15, 80) * (1 if rng.random() < 0.25 else -1)
            if big:
                off = float(rng.choice([-1, 1])) * (rng.uniform(8, 12) if rng.random() < 0.5 else rng.uniform(150, 300))
            x[s:] += off
        elif mode == "open":
            x[s:] = (rng.uniform(-20, 5) if rng.random() < 0.6 else rng.uniform(1200, 1370)) + rng.normal(0, 0.5, n - s)
        elif mode == "flatline":
            x[s:] = round(float(x[s]), 1)
        elif mode == "erratic":
            k = max(3, int((n - s) * rng.uniform(0.02, 0.08)))
            idx = rng.integers(s, n, k)
            x[idx] += rng.choice([-1, 1], k) * rng.uniform(30, 150, k) * (2.0 if big else 1.0)
        else:  # drift
            d = rng.uniform(10, 30) if not big else rng.uniform(40, 70)
            if ambiguous:
                d = rng.uniform(8, 14)
            ramp = int(rng.uniform(24, 24 * 5) * 60 / freq)
            x[:] -= d * _ramp_env(n, s, n, ramp, persist=True)
        a["temps"][:, j] = x
        p.update(sensor_index=j + 1, mode=mode)
        return s, n


    def _inj_instability(a, rng, p, layout, freq, variant, ambiguous):
        """Function _inj_instability."""
        n = len(a["f"])
        sev = rng.uniform(1.0, 3.5)
        if variant == "magnitude":
            sev = rng.uniform(0.6, 0.9) if rng.random() < 0.5 else rng.uniform(4.5, 7.0)
        elif ambiguous:
            sev = rng.uniform(0.8, 1.1)
        period = rng.uniform(2, 8) if variant != "shifted" else rng.uniform(12, 30)
        s, e = _event_window(rng, n, freq, (3, 18), ambiguous)
        t = np.arange(e - s) * freq
        osc = sev * (0.55 + 0.45 * np.sin(2 * np.pi * t / period)) + 0.15 * sev * np.sin(2 * np.pi * t / (period * 0.37))
        osc = np.clip(osc + rng.normal(0, 0.08 * sev, e - s), 0.1, 12.0) * a["online"][s:e]
        scale = max(1.0, float(a["comb_dyn_psi"][:s].mean()) / 0.35) if s else 1.0
        a["comb_dyn_psi"][s:e] += osc * scale
        flutter = osc / sev * rng.uniform(3.0, 8.0)
        m = a["temps"].shape[1]
        hot = int(rng.integers(0, m))
        a["temps"][s:e, hot] += flutter * 0.6
        a["temps"][s:e, (hot + m // 2) % m] -= flutter * 0.5
        a["vib_DE_mm_s"][s:e] += 0.25 * osc
        a["fuel_flow_kg_s"][s:e] *= 1 + 0.003 * osc / sev
        p.update(severity_psi=round(float(sev), 2), period_min=round(float(period), 1))
        return s, e


    def _inj_probe(a, rng, p, layout, freq, variant, ambiguous):
        """Function _inj_probe."""
        n = len(a["f"])
        mode = str(rng.choice(["flatline", "saturation", "spikes", "noisy"]))
        s, e = _event_window(rng, n, freq, (6, 24 * 4), ambiguous)
        d = a["comb_dyn_psi"]
        if mode == "flatline":
            d[s:e] = float(rng.choice([0.0, round(float(d[s]), 2)]))
        elif mode == "saturation":
            on = rng.random(e - s) < rng.uniform(0.3, 1.0)
            d[s:e] = np.where(on, float(rng.choice([9.99, 15.0, 20.0])), d[s:e])
        elif mode == "spikes":
            k = max(4, int((e - s) * rng.uniform(0.01, 0.05)))
            d[rng.integers(s, e, k)] = rng.uniform(2, 9, k)
        else:
            d[s:e] = d[s:e] + rng.normal(0, rng.uniform(0.5, 1.5), e - s)
        p.update(mode=mode)
        return s, e


    def _go_offline(a, rng, s: int, e: int) -> None:
        """Unit offline (trip / coast-down): no load, no fuel, exhaust cools."""
        n = len(a["f"])
        e = min(e, n)
        a["online"][s:e] = False
        a["f"][s:e] = 0.0
        a["load_MW"][s:e] = np.abs(rng.normal(0, 0.1, e - s))
        a["fuel_flow_kg_s"][s:e] = 0.0
        a["IGV_deg"][s:e] = 28.0 + rng.normal(0, 0.1, e - s)
        a["comb_dyn_psi"][s:e] = 0.05
        cool = 150 + (a["egt_mean"][s] - 150) * np.exp(-np.arange(e - s) / max(1.0, 0.1 * (e - s)))
        a["temps"][s:e] = cool[:, None] + rng.normal(0, 1.0, (e - s, a["temps"].shape[1]))
        a["CDP_bar"][s:e] = 1.0 + rng.normal(0, 0.01, e - s)


    def _inj_hets(a, rng, p, layout, freq, variant, ambiguous):
        """Function _inj_hets."""
        n, m = a["temps"].shape
        peak = rng.uniform(45, 80)
        if variant == "magnitude":
            peak = rng.uniform(25, 38) if rng.random() < 0.5 else rng.uniform(90, 130)
        build = max(2, int(rng.uniform(1, 6) * 60 / freq))
        min_base = int(24 * 60 / freq) + build
        if ambiguous:
            t = int(n * rng.uniform(0.9, 0.97))
        else:
            t = int(rng.uniform(max(min_base, 0.5 * n), 0.85 * n))
        t = min(max(t, min_base), n - 2)
        hot = int(rng.integers(0, m))
        cold = (hot + m // 2) % m
        ramp = np.linspace(0, 1, build)
        a["temps"][t - build : t, hot] += 0.55 * peak * ramp
        a["temps"][t - build : t, cold] -= 0.45 * peak * ramp
        if layout == "ring":
            for d in (-1, 1):
                a["temps"][t - build : t, (hot + d) % m] += 0.3 * peak * ramp
                a["temps"][t - build : t, (cold + d) % m] -= 0.25 * peak * ramp
        trip_len = max(2, int(rng.uniform(20, 60) / freq))
        a["trip_active"][t : t + trip_len] = 1
        off_end = min(n, t + int(rng.uniform(4, 72) * 60 / freq))
        pre_load = float(a["load_MW"][:t].mean())
        _go_offline(a, rng, t, off_end)
        k = min(n - t, max(1, int(30 / freq)))
        a["vib_DE_mm_s"][t : t + k] = 6.5 + rng.normal(0, 0.3, k)
        if off_end < n:  # restart: ramp back to load
            r = min(n - off_end, int(2 * 60 / freq))
            a["load_MW"][off_end : off_end + r] = np.linspace(0, pre_load, r)
        p.update(peak_spread_C=round(float(peak), 1), build_h=round(build * freq / 60, 1), restarted=bool(off_end < n))
        return t - build, t + trip_len


    def _inj_igv(a, rng, p, layout, freq, variant, ambiguous):
        """Function _inj_igv."""
        n = len(a["f"])
        delta = rng.uniform(2.5, 8) * float(rng.choice([-1, 1]))
        if variant == "magnitude":
            delta = np.sign(delta) * (rng.uniform(1.2, 2.2) if rng.random() < 0.5 else rng.uniform(10, 15))
        s, _ = _event_window(rng, n, freq, (24, 48), ambiguous)
        step = rng.random() < 0.3
        ramp = 1 if step else int(rng.uniform(24, 24 * 5) * 60 / freq)
        a["IGV_deg"] += delta * _ramp_env(n, s, n, ramp, persist=True) * a["online"]
        p.update(offset_deg=round(float(delta), 2), step=bool(step))
        return s, n


    def _inj_fuel_osc(a, rng, p, layout, freq, variant, ambiguous):
        """Function _inj_fuel_osc."""
        n = len(a["f"])
        period = rng.uniform(2, 10) if freq <= 1 else rng.uniform(40, 120)
        s, e = _event_window(rng, n, freq, (4, 72), ambiguous)
        t = np.arange(e - s) * freq
        grow = np.clip(t / max(1.0, t[-1] * 0.3), 0, 1)
        wave = np.sin(2 * np.pi * t / period) * grow * a["online"][s:e]
        af, al, ae = rng.uniform(0.02, 0.06), rng.uniform(0.008, 0.025), rng.uniform(3, 8)
        a["fuel_flow_kg_s"][s:e] *= 1 + af * wave
        a["load_MW"][s:e] += al * a["load_MW"][s:e] * np.roll(wave, 1)
        a["temps"][s:e] += (ae * wave)[:, None]
        a["comb_dyn_psi"][s:e] += 0.05 * np.abs(wave)
        p.update(period_min=round(float(period), 1), fuel_amp_pct=round(100 * float(af), 1))
        return s, e


    def _inj_harness(a, rng, p, layout, freq, variant, ambiguous):
        """Damaged harness / connector: a group of adjacent TCs drops out together, intermittently, in steps."""
        n, m = a["temps"].shape
        width = int(rng.integers(3, 7)) if m > 6 else 2
        first = int(rng.integers(0, m))
        members = [(first + k) % m for k in range(width)]
        s, _ = _event_window(rng, n, freq, (24, 48), ambiguous)
        on = np.zeros(n, dtype=bool)
        i = s
        while i < n:
            dur = max(1, int(rng.uniform(0.5, 6) * 60 / freq))
            on[i : i + dur] = True
            i += dur + max(1, int(rng.uniform(0.5, 12) * 60 / freq))
        on &= a["online"]
        drop = rng.uniform(60, 300)
        for idx in members:
            a["temps"][on, idx] -= drop * rng.uniform(0.85, 1.0) + rng.normal(0, 3, int(on.sum()))
        p.update(first_tc=first + 1, width=width, drop_C=round(float(drop), 1))
        return s, n


    def _inj_tc_step_lookalike(a, rng, p, layout, freq, variant, ambiguous):
        """One exhaust TC steps down 12-40 C (cold-spot sized) within minutes and stays there; neighbours unchanged."""
        n, m = a["temps"].shape
        j = int(rng.integers(0, m))
        s, _ = _event_window(rng, n, freq, (24, 48), False)
        off = rng.uniform(12, 40)
        ramp = 1 if rng.random() < 0.6 else max(1, int(rng.uniform(10, 40) / freq))
        a["temps"][:, j] -= off * _ramp_env(n, s, n, ramp, persist=True)
        p.update(sensor_index=j + 1, mode="step_lookalike", step_C=round(float(-off), 1))
        return s, n


    def _inj_bearing(a, rng, p, layout, freq, variant, ambiguous):
        """Function _inj_bearing."""
        n = len(a["f"])
        s, _ = _event_window(rng, n, freq, (24, 48), ambiguous)
        rise = rng.uniform(3, 9)
        ramp = int(rng.uniform(24, 24 * 5) * 60 / freq)
        env = _ramp_env(n, s, n, ramp, persist=True) ** 2 * a["online"]
        a["vib_DE_mm_s"] += rise * env + rng.normal(0, 0.15, n) * env
        a["vib_NDE_mm_s"] += 0.3 * rise * env
        a["lube_oil_C"] += rng.uniform(2, 6) * env
        p.update(vib_rise_mm_s=round(float(rise), 2))
        return s, n


    INJECTORS = {
        "normal": None,
        "cold_spot_hardware": _inj_cold_spot,
        "tc_sensor_fault": _inj_tc_sensor,
        "combustion_instability": _inj_instability,
        "dynamics_probe_fault": _inj_probe,
        "hets_trip_hardware": _inj_hets,
        "igv_lvdt_drift": _inj_igv,
        "fuel_control_oscillation": _inj_fuel_osc,
        "bearing_vibration": _inj_bearing,
        "tc_harness_fault": _inj_harness,
    }

    FREQ_CHOICES = {
        "combustion_instability": ([1, 5, 10], [0.7, 0.2, 0.1]),
        "dynamics_probe_fault": ([1, 5, 10], [0.6, 0.25, 0.15]),
        "fuel_control_oscillation": ([1, 5, 10], [0.6, 0.2, 0.2]),
    }
    ZONE_SHARE = {"hets_trip_hardware": 0.65, "combustion_instability": 0.65, "dynamics_probe_fault": 0.65,
                  "fuel_control_oscillation": 0.65, "igv_lvdt_drift": 0.65, "bearing_vibration": 0.65,
                  "normal": 0.4, "tc_sensor_fault": 0.25, "cold_spot_hardware": 0.2, "tc_harness_fault": 0.0}


    def make_case(spec: Dict[str, Any]) -> Tuple[pd.DataFrame, Dict[str, Any]]:
        """Build one labeled case from a spec {split, signature, variant, index, ambiguous}."""
        sig, split, variant, i = spec["signature"], spec["split"], spec.get("variant"), spec["index"]
        rng = np.random.default_rng(_seed(split, sig, variant, i))
        ambiguous = bool(spec.get("ambiguous"))
        freqs, probs = FREQ_CHOICES.get(sig, ([10, 5, 1], [0.55, 0.25, 0.2]))
        freq = float(rng.choice(freqs, p=probs))
        days = {1.0: (2, 5), 5.0: (5, 14), 10.0: (10, 30)}[freq]
        n = int(rng.uniform(*days) * 24 * 60 / freq)
        layout = "zones" if rng.random() < ZONE_SHARE.get(sig, 0.3) else "ring"
        if variant == "step_lookalike":
            layout = "ring"
        n_tc = int(rng.choice([24, 27, 30]))
        if variant == "shifted":
            n_tc = int(rng.choice([16, 36]))
            if sig in ("hets_trip_hardware", "cold_spot_hardware", "tc_sensor_fault"):
                layout = "ring"
        profile = str(rng.choice(["baseload", "steps", "cycling"], p=[0.55, 0.3, 0.15]))
        if sig == "hets_trip_hardware":
            profile = str(rng.choice(["baseload", "steps"], p=[0.7, 0.3]))
        fp = _frame_params(rng, variant == "load")
        a = _base_arrays(rng, n, freq, layout, n_tc, fp, profile)
        params: Dict[str, Any] = {}
        ev: Optional[Tuple[int, int]] = None
        # A signature with no injector yet is written as a healthy case. The alert-type
        # path below has its own injectors; this eight-signature path stays put.
        inj = _inj_tc_step_lookalike if variant == "step_lookalike" else INJECTORS.get(sig)
        if inj is not None:
            ev = inj(a, rng, params, layout, freq, variant, ambiguous)

        temps = a["temps"]
        egt_avg = temps.mean(axis=1)
        spread = temps.max(axis=1) - temps.min(axis=1)
        start = pd.Timestamp("2024-01-01") + pd.Timedelta(days=int(rng.integers(0, 900)), hours=int(rng.integers(0, 24)))
        idx = pd.date_range(start=start, periods=n, freq=f"{int(freq)}min")
        alt = rng.random() < 0.3
        cols: Dict[str, Any] = {"timestamp": idx.strftime("%Y-%m-%d %H:%M:%S")}

        def put(name: str, x: np.ndarray, nd: int) -> None:
            """Function put."""
            cols[ALT_TAGS.get(name, name) if alt else name] = np.round(x, nd)

        put("load_MW", np.clip(a["load_MW"], 0, None), 2)
        put("CDP_bar", a["CDP_bar"], 3)
        put("CDT_C", a["CDT_C"], 2)
        put("EGT_avg_C", egt_avg, 2)
        put("EGT_spread_C", spread, 2)
        if layout == "ring":
            for j in range(temps.shape[1]):
                cols[(f"TTXD_{j + 1}" if alt else f"TC{j + 1}")] = np.round(temps[:, j], 1)
        else:
            for j in range(4):
                cols[(f"EGT_ZONE{j + 1}" if alt else f"EGT_Z{j + 1}_C")] = np.round(temps[:, j], 2)
        put("fuel_flow_kg_s", np.clip(a["fuel_flow_kg_s"], 0, None), 4)
        put("IGV_deg", a["IGV_deg"], 2)
        put("vib_DE_mm_s", np.clip(a["vib_DE_mm_s"], 0.1, None), 3)
        put("vib_NDE_mm_s", np.clip(a["vib_NDE_mm_s"], 0.1, None), 3)
        put("lube_oil_C", a["lube_oil_C"], 2)
        put("comb_dyn_psi", a["comb_dyn_psi"], 3)
        cols[ALT_TAGS["trip_active"] if alt else "trip_active"] = a["trip_active"].astype(int)
        if rng.random() < 0.3:
            hours = np.arange(n) * freq / 60
            cols["ambient_C"] = np.round(22 + 8 * np.sin(2 * np.pi * (hours - 9) / 24) + rng.normal(0, 0.3, n), 2)
        df = pd.DataFrame(cols)
        data_cols = [c for c in df.columns if c != "timestamp" and "trip" not in c.lower()]
        if rng.random() < 0.08:  # historian gaps
            for c in rng.choice(data_cols, size=int(rng.integers(1, 4)), replace=False):
                g0 = int(rng.integers(0, n - 10))
                df.loc[g0 : g0 + int(rng.uniform(1, 6) * 60 / freq), c] = np.nan
        if sig == "normal" and rng.random() < 0.15:  # single-sample historian glitches
            for c in rng.choice(data_cols, size=2, replace=False):
                j = int(rng.integers(0, n))
                if pd.notna(df.loc[j, c]):
                    df.loc[j, c] = float(df.loc[j, c]) * rng.uniform(1.5, 3.0)

        tc_hint = params.get("sensor_index") or params.get("center_tc")
        notes, note_meta = _notes(sig, rng, tc_hint if layout == "ring" else None)
        name_choices = ANALYTIC_NAMES.get(sig) or GENERIC_ANALYTICS
        analytic = str(rng.choice(GENERIC_ANALYTICS)) if rng.random() < 0.1 else str(rng.choice(name_choices))
        if variant == "step_lookalike":  # raised as a cold spot; half the notes point at combustion hardware
            analytic = str(rng.choice(ANALYTIC_NAMES["cold_spot_hardware"]))
            if rng.random() < 0.5:
                notes = (notes + " " + str(rng.choice(HINTS["cold_spot_hardware"]))).strip()
                note_meta = {"hint": "misleading:cold_spot_hardware"}
        info = BASE_SIGNATURES.get(sig) or UNSEEN_SIGNATURES[sig]
        meta = {
            "case_id": f"{split}-{sig}-{variant or 'base'}-{i:03d}",
            "split": split,
            "signature": sig,
            "action": info["action"],
            "cause": info["cause"],
            "escalate": info["escalate"],
            "variant": variant,
            "ambiguous": ambiguous,
            "analytic": analytic,
            "notes": notes,
            "notes_hint": note_meta["hint"],
            "layout": layout,
            "n_sensors": int(temps.shape[1]),
            "freq_min": freq,
            "rows": n,
            "profile": profile,
            "frame_rated_MW": round(float(fp["rated"]), 1),
            "alt_tags": bool(alt),
            # Frame model the trainer conditions on. Historian tags are 7FA (ring) and 9HA (zones);
            # the friendly-tag twins are 7EA and 7HA. Older manifests omit this and derive it from layout + alt_tags.
            "frame": ("9HA" if alt else "7HA") if layout == "zones" else ("7FA" if alt else "7EA"),
            "event_start": idx[ev[0]].strftime("%Y-%m-%d %H:%M") if ev else None,
            "event_end": idx[min(ev[1], n - 1)].strftime("%Y-%m-%d %H:%M") if ev else None,
            "params": params,
        }
        return df, meta


    def dataset_specs(scale: float = 1.0) -> List[Dict[str, Any]]:
        """Function dataset_specs."""
        specs: List[Dict[str, Any]] = []
        for split, count in SPLIT_COUNTS.items():
            k = max(1, int(round(count * scale)))
            for sig in SEEN:
                for i in range(k):
                    specs.append({"split": split, "signature": sig, "variant": None, "index": i, "ambiguous": i % 10 == 9})
        kv = max(1, int(round(VARIANT_COUNT * scale)))
        for sig in VARIANT_CLASSES:
            for kind in VARIANT_KINDS:
                for i in range(kv):
                    specs.append({"split": "variant", "signature": sig, "variant": kind, "index": i})
        for i in range(kv):
            specs.append({"split": "variant", "signature": "normal", "variant": "load", "index": i})
        for sig in UNSEEN:
            for i in range(max(1, int(round(UNSEEN_COUNT * scale)))):
                specs.append({"split": "unseen", "signature": sig, "variant": None, "index": i})
        specs += sensor_fault_specs(scale)
        return specs


    def sensor_fault_specs(scale: float = 1.0) -> List[Dict[str, Any]]:
        """Function sensor_fault_specs."""
        return [{"split": "sensorfault", "signature": "tc_sensor_fault", "variant": "step_lookalike", "index": i}
                for i in range(max(1, int(round(SENSOR_FAULT_COUNT * scale))))]


    def _write_one(job: Tuple[Dict[str, Any], str]) -> Dict[str, Any]:
        """Function _write_one."""
        spec, out = job
        df, meta = make_case(spec)
        path = Path(out) / meta["split"] / f"{meta['case_id']}.csv.gz"
        path.parent.mkdir(parents=True, exist_ok=True)
        df.to_csv(path, index=False, compression="gzip")
        meta["file"] = f"{meta['split']}/{path.name}"
        return meta


    def generate_dataset(out: Path, scale: float = 1.0, workers: int = 0, only_split: Optional[str] = None,
                          profiles: Optional[List[str]] = None) -> List[Dict[str, Any]]:
        """Write the labeled dataset (gzip CSVs) and manifest.jsonl; returns the manifest rows.

        ``only_split``: (re)write just that split and merge it into an existing manifest.jsonl.
        ``profiles``: alert-type ids, or ``ALL_SYNTH_PROFILES``. Omit it to keep today's
        eight-signature dataset (no profile subdirectory, same counts).
        """
        if profiles is not None:
            return _generate_profile_dataset(out, scale, workers, only_split, profiles)
        import multiprocessing as mp

        out = Path(out)
        out.mkdir(parents=True, exist_ok=True)
        specs = dataset_specs(scale)
        keep: List[Dict[str, Any]] = []
        if only_split:
            specs = [s for s in specs if s["split"] == only_split]
            mf = out / "manifest.jsonl"
            if mf.is_file():
                keep = [r for r in (json.loads(x) for x in mf.read_text(encoding="utf-8").splitlines() if x.strip()) if r["split"] != only_split]
        jobs = [(s, str(out)) for s in specs]
        workers = workers or max(1, (mp.cpu_count() or 2) - 2)
        if workers > 1 and len(jobs) > 8:
            with mp.get_context("spawn").Pool(workers) as pool:
                rows = pool.map(_write_one, jobs, chunksize=4)
        else:
            rows = [_write_one(j) for j in jobs]
        rows = keep + rows
        with (out / "manifest.jsonl").open("w", encoding="utf-8") as fh:
            for r in rows:
                fh.write(json.dumps(r) + "\n")
        counts: Dict[str, int] = {}
        for r in rows:
            counts[r["split"]] = counts.get(r["split"], 0) + 1
        print(f"Dataset: {len(rows)} cases in {out}  " + "  ".join(f"{k}={v}" for k, v in counts.items()))
        return rows


    # --- alert-type profiles (kept out of the original eight-signature dataset)
    # The original SEEN list stays eight names so dataset_specs(1.0) is still
    # 1200/200/320/128/80/40. These profiles are a second manifest: pass
    # profiles=ALL_SYNTH_PROFILES. fuel_gas_heater is the coldstart split only.

    # One slot other than the context slot (load) is left out of this fraction of files.
    # That is the mask the scorer has to handle. There is no optional-slot list.
    MISSING_TAG_P = 0.05
    # An alert-type case carries its real name. The trainer reads the alert type from the folder.
    GENERIC_NAME_P = 0
    EXTRA_TAG_MAX = 4
    # scale 0.1 -> 6 cases per signature. The original split counts are not reused.
    PROFILE_SPLIT_COUNTS = {"train": 60, "val": 10, "test": 20}
    PROFILE_VARIANT_COUNT = 4
    PROFILE_UNSEEN_COUNT = 10
    COLDSTART_PER_SIGNATURE = 20  # two signatures -> 40 cases at scale 1

    ALL_SYNTH_PROFILES = (
        "exhaust_cold_spot",
        "combustion_dynamics",
        "exhaust_spread_trip",
        "igv_fuel_control",
        "bearing_vibration",
        "inlet_filter_dp",
        "lube_oil_system",
        "fuel_gas_heater",
    )
    # Shipped bundles are the seven built-ins. The heater split is never one of them.
    SHIPPED_SYNTH_PROFILES = tuple(p for p in ALL_SYNTH_PROFILES if p != "fuel_gas_heater")

    PROFILE_SIGNATURES = {
        "exhaust_cold_spot": ["normal", "cold_spot_hardware", "tc_sensor_fault"],
        "combustion_dynamics": ["normal", "combustion_instability", "dynamics_probe_fault"],
        "exhaust_spread_trip": ["normal", "hets_trip_hardware", "tc_sensor_fault"],
        "igv_fuel_control": ["normal", "igv_lvdt_drift", "fuel_control_oscillation"],
        "bearing_vibration": ["normal", "bearing_wear_trend", "vibration_probe_fault"],
        "inlet_filter_dp": ["normal", "inlet_filter_fouling", "dp_transmitter_fault"],
        "lube_oil_system": ["normal", "lube_cooler_fouling", "drain_tc_fault"],
        "fuel_gas_heater": ["normal", "heater_fault"],
    }
    PROFILE_UNSEEN = {"exhaust_cold_spot": ["tc_harness_fault"]}
    PROFILE_NAMES = {
        "exhaust_cold_spot": ["Exhaust Cold Spot", "Exhaust temperature cold spot", "TTXD cold spot"],
        "combustion_dynamics": ["Combustion Dynamics High", "comb dyn high", "CDM pulsation alarm"],
        "exhaust_spread_trip": ["HETS Trip", "High exhaust spread trip", "Unit trip - exhaust spread"],
        "igv_fuel_control": ["IGV position deviation", "Fuel control oscillation", "Load hunting"],
        "bearing_vibration": ["Bearing vibration high", "Vibration advisory", "High vibration alarm"],
        "inlet_filter_dp": ["Inlet filter high dp", "Inlet dp high", "Filter house dp advisory"],
        "lube_oil_system": ["Lube oil temperature high", "Lube cooler advisory", "Drain temperature alarm"],
        "fuel_gas_heater": ["Fuel gas heater outlet low", "Heater performance advisory"],
    }
    # The built-in tag list, in file order. A case writes every one of these, minus at most
    # one non-context slot. igv_ref is not here: it is an extra column, not a slot.
    PROFILE_SLOTS = {
        "exhaust_cold_spot": ["load", "exh_tc", "spread", "egt_avg", "fuel", "igv"],
        "combustion_dynamics": ["load", "dyn", "vib", "fuel", "exh_tc"],
        "exhaust_spread_trip": ["load", "exh_tc", "spread", "trip", "egt_avg", "fuel", "igv"],
        "igv_fuel_control": ["load", "igv", "fuel", "egt_avg", "cdp", "exh_tc"],
        "bearing_vibration": ["load", "speed", "brg_vib", "lube_supply"],
        "inlet_filter_dp": ["load", "inlet_dp", "ambient_t", "cdp"],
        "lube_oil_system": ["load", "ambient_t", "oil_hdr_p", "oil_supply_t", "drain_t"],
        "fuel_gas_heater": ["load", "heater_out", "fuel_gas", "fuel"],
    }
    _EXTRA_POOL = (
        "seal_air_bar", "wheelspace_C", "cooling_flow_kg_s", "exhaust_duct_dp_mbar",
        "comp_bleed_pct", "flame_int_pct", "nacelle_temp_C", "pad_temp_C",
    )
    _RING_SIZES = (16, 18, 24, 27, 31, 36)


    def _scaled_count(count: int, scale: float) -> int:
        """At least one case. scale 0.1 of 60 is 6."""
        return max(1, int(round(count * scale)))


    def profile_specs(scale: float = 1.0, profiles: Optional[List[str]] = None) -> List[Dict[str, Any]]:
        """One spec per synthetic case. The heater profile is the coldstart split only."""
        wanted = list(profiles) if profiles is not None else list(ALL_SYNTH_PROFILES)
        unknown = [p for p in wanted if p not in PROFILE_SIGNATURES]
        if unknown:
            raise ValueError(f"unknown synthetic profile: {unknown[0]}")
        specs: List[Dict[str, Any]] = []
        for pid in wanted:
            if pid == "fuel_gas_heater":
                for sig in PROFILE_SIGNATURES[pid]:
                    for i in range(_scaled_count(COLDSTART_PER_SIGNATURE, scale)):
                        specs.append({"split": "coldstart", "profile": pid, "signature": sig, "variant": None, "index": i})
                continue
            for split, count in PROFILE_SPLIT_COUNTS.items():
                for sig in PROFILE_SIGNATURES[pid]:
                    for i in range(_scaled_count(count, scale)):
                        specs.append({
                            "split": split, "profile": pid, "signature": sig, "variant": None, "index": i,
                            "ambiguous": i % 10 == 9,
                        })
            kv = _scaled_count(PROFILE_VARIANT_COUNT, scale)
            for sig in PROFILE_SIGNATURES[pid]:
                if sig == "normal":
                    continue
                for i in range(kv):
                    specs.append({"split": "variant", "profile": pid, "signature": sig, "variant": "magnitude", "index": i})
            for sig in PROFILE_UNSEEN.get(pid, []):
                for i in range(_scaled_count(PROFILE_UNSEEN_COUNT, scale)):
                    specs.append({"split": "unseen", "profile": pid, "signature": sig, "variant": None, "index": i})
        return specs


    def _dialect_name(dialect: str, friendly: str, historian: str, site: str) -> str:
        return {"friendly": friendly, "historian": historian, "site": site}[dialect]


    def _ring_names(dialect: str, n: int) -> List[str]:
        if dialect == "historian":
            return [f"TTXD_{j}" for j in range(1, n + 1)]
        if dialect == "site":
            return [f"exh_tc_{j}" for j in range(1, n + 1)]
        return [f"TC{j}" for j in range(1, n + 1)]


    def _zone_names(dialect: str) -> List[str]:
        if dialect == "historian":
            return [f"EGT_ZONE{j}" for j in range(1, 5)]
        if dialect == "site":
            return [f"egt_z{j}" for j in range(1, 5)]
        return [f"EGT_Z{j}_C" for j in range(1, 5)]


    def _profile_signals(a: Dict[str, Any], rng: np.random.Generator, freq: float, n_brg: int, n_drain: int) -> None:
        """Columns the new profiles read. Built on top of ``_base_arrays``."""
        n = len(a["f"])
        f = a["f"]
        online = a["online"]
        hours = np.arange(n) * freq / 60.0
        a["ambient"] = 22 + 8 * np.sin(2 * np.pi * (hours - 9) / 24) + rng.normal(0, 0.3, n)
        a["speed_rpm"] = np.where(online, 3000 + 8 * (f - 0.9) + rng.normal(0, 1.5, n), rng.normal(0, 0.2, n))
        a["inlet_dp"] = np.where(online, 2.4 + 1.4 * f + rng.normal(0, 0.05, n), 0.3)
        a["oil_hdr"] = np.where(online, 2.3 - 0.2 * f + rng.normal(0, 0.02, n), 0.4)
        a["igv_ref"] = a["IGV_deg"] + rng.normal(0, 0.08, n)
        a["heater_out"] = np.where(online, 70 + 45 * f + rng.normal(0, 0.4, n), a["ambient"])
        a["fuel_gas"] = a["heater_out"] - rng.uniform(12, 20) + rng.normal(0, 0.3, n)
        base_vib = np.where(online, 2.8 + 0.4 * f, 0.5)
        a["brg"] = base_vib[:, None] + rng.normal(0, 0.08, (n, n_brg))
        a["drains"] = (a["lube_oil_C"] + 6)[:, None] + rng.normal(0, 0.3, (n, n_drain))


    def _inj_inlet_fouling(a, rng, p, freq):
        n = len(a["f"])
        s, e = _event_window(rng, n, freq, (24, 72), False)
        rise = rng.uniform(3.0, 7.0)
        env = _ramp_env(n, s, n, int(rng.uniform(12, 48) * 60 / freq), persist=True)
        a["inlet_dp"] = a["inlet_dp"] + rise * env
        p.update(dp_rise_mbar=round(float(rise), 2))
        return s, e


    def _inj_dp_transmitter(a, rng, p, freq):
        n = len(a["f"])
        s, _ = _event_window(rng, n, freq, (6, 24), False)
        if rng.random() < 0.5:
            a["inlet_dp"][s:] = a["inlet_dp"][s] + rng.normal(0, 0.01, n - s)
            p["mode"] = "stuck"
        else:
            a["inlet_dp"][s:] += rng.choice([-1.0, 1.0]) * rng.uniform(4, 8)
            p["mode"] = "step"
        return s, n


    def _inj_lube_fouling(a, rng, p, freq):
        n = len(a["f"])
        s, e = _event_window(rng, n, freq, (24, 72), False)
        rise = rng.uniform(6, 14)
        env = _ramp_env(n, s, n, int(rng.uniform(12, 36) * 60 / freq), persist=True)
        a["lube_oil_C"] = a["lube_oil_C"] + rise * env
        a["drains"] = a["drains"] + (0.6 * rise * env)[:, None]
        p.update(supply_rise_C=round(float(rise), 1))
        return s, e


    def _inj_drain_tc(a, rng, p, freq):
        n, m = a["drains"].shape
        j = int(rng.integers(0, m))
        s, _ = _event_window(rng, n, freq, (2, 12), False)
        step = rng.uniform(25, 60)
        a["drains"][s:, j] += step
        p.update(drain_index=j + 1, step_C=round(float(step), 1))
        return s, n


    def _inj_bearing_wear(a, rng, p, freq):
        n = len(a["f"])
        s, _ = _event_window(rng, n, freq, (24, 72), False)
        rise = rng.uniform(2.5, 6.0)
        env = _ramp_env(n, s, n, int(rng.uniform(24, 96) * 60 / freq), persist=True)
        a["brg"][:, 0] += rise * env
        if a["brg"].shape[1] > 1:
            a["brg"][:, 1] += 0.35 * rise * env
        a["lube_oil_C"] = a["lube_oil_C"] + rng.uniform(2, 5) * env
        p.update(vib_rise_mm_s=round(float(rise), 2))
        return s, n


    def _inj_vib_probe(a, rng, p, freq):
        n, m = a["brg"].shape
        j = int(rng.integers(0, m))
        s, _ = _event_window(rng, n, freq, (2, 12), False)
        if rng.random() < 0.5:
            a["brg"][s:, j] = 0.05
            p["mode"] = "flat"
        else:
            a["brg"][s:, j] += rng.uniform(6, 12)
            p["mode"] = "step"
        p["probe"] = j + 1
        return s, n


    def _inj_heater(a, rng, p, freq):
        n = len(a["f"])
        s, _ = _event_window(rng, n, freq, (6, 36), False)
        # Outlet falls toward the fuel-gas temperature. Flow and load stay put.
        gap = a["heater_out"] - a["fuel_gas"]
        env = _ramp_env(n, s, n, max(1, int(rng.uniform(1, 6) * 60 / freq)), persist=True)
        a["heater_out"] = a["heater_out"] - gap * rng.uniform(0.7, 1.0) * env
        p.update(outlet_drop_C=round(float(np.nanmax(gap) * 0.85), 1))
        return s, n


    _PROFILE_INJECTORS = {
        "inlet_filter_fouling": _inj_inlet_fouling,
        "dp_transmitter_fault": _inj_dp_transmitter,
        "lube_cooler_fouling": _inj_lube_fouling,
        "drain_tc_fault": _inj_drain_tc,
        "bearing_wear_trend": _inj_bearing_wear,
        "vibration_probe_fault": _inj_vib_probe,
        "heater_fault": _inj_heater,
    }


    def _apply_profile_fault(a, rng, params, sig, layout, freq, variant, ambiguous):
        """Existing combustion injectors, then the alert types that have their own."""
        if sig in _PROFILE_INJECTORS:
            return _PROFILE_INJECTORS[sig](a, rng, params, freq)
        inj = INJECTORS.get(sig)
        if inj is None:
            return None
        return inj(a, rng, params, layout, freq, variant, ambiguous)


    def make_profile_case(spec: Dict[str, Any]) -> Tuple[pd.DataFrame, Dict[str, Any]]:
        """One labeled case for an alert type. Tag dialect and slot count vary; the seed does not."""
        pid, sig = spec["profile"], spec["signature"]
        split, variant, i = spec["split"], spec.get("variant"), spec["index"]
        rng = np.random.default_rng(_seed("profile", pid, split, sig, variant, i))
        freq = float(rng.choice([10, 5, 1], p=[0.6, 0.25, 0.15]))
        days = {1.0: (2, 4), 5.0: (5, 10), 10.0: (8, 20)}[freq]
        n = int(rng.uniform(*days) * 24 * 60 / freq)
        dialect = str(rng.choice(["friendly", "historian", "site"]))
        n_tc = int(rng.choice(_RING_SIZES))
        n_probe = int(rng.integers(1, 4))
        n_brg = int(rng.integers(2, 9))
        n_drain = int(rng.integers(3, 7))
        # Cold spot and combustion dynamics write the exhaust slot as a ring, or as four
        # zones on a quarter of cases. The slot id stays exh_tc either way.
        use_zones = pid in ("exhaust_cold_spot", "combustion_dynamics") and rng.random() < 0.25
        layout = "zones" if use_zones else "ring"
        op = str(rng.choice(["baseload", "steps", "cycling"], p=[0.6, 0.25, 0.15]))
        fp = _frame_params(rng, variant == "load")
        a = _base_arrays(rng, n, freq, layout, n_tc if layout == "ring" else 4, fp, op)
        _profile_signals(a, rng, freq, n_brg, n_drain)
        params: Dict[str, Any] = {}
        ev = _apply_profile_fault(a, rng, params, sig, layout, freq, variant, bool(spec.get("ambiguous")))

        # Full tag list. The context slot stays. At most one other slot is left out.
        slots = list(PROFILE_SLOTS[pid])
        missing: List[str] = []
        droppable = [s for s in slots if s != "load"]
        if droppable and rng.random() < MISSING_TAG_P:
            drop = str(rng.choice(droppable))
            slots = [s for s in slots if s != drop]
            missing.append(drop)

        temps = a["temps"]
        egt_avg = temps.mean(axis=1)
        spread = temps.max(axis=1) - temps.min(axis=1)
        start = pd.Timestamp("2024-01-01") + pd.Timedelta(days=int(rng.integers(0, 900)))
        idx = pd.date_range(start=start, periods=n, freq=f"{int(freq)}min")
        cols: Dict[str, Any] = {"timestamp": idx.strftime("%Y-%m-%d %H:%M:%S")}

        def put(name: str, values: np.ndarray, nd: int) -> None:
            cols[name] = np.round(np.asarray(values, dtype=float), nd)

        if "load" in slots:
            put(_dialect_name(dialect, "load_MW", "DWATT", "power_MW"), np.clip(a["load_MW"], 0, None), 2)
        if "fuel" in slots:
            put(_dialect_name(dialect, "fuel_flow_kg_s", "FQG", "fuel_kg_s"), np.clip(a["fuel_flow_kg_s"], 0, None), 4)
        if "cdp" in slots:
            put(_dialect_name(dialect, "CDP_bar", "CPD", "CDP"), a["CDP_bar"], 3)
        if "exh_tc" in slots and use_zones:
            for j, name in enumerate(_zone_names(dialect)):
                cols[name] = np.round(temps[:, j], 2)
        elif "exh_tc" in slots:
            for j, name in enumerate(_ring_names(dialect, temps.shape[1])):
                cols[name] = np.round(temps[:, j], 1)
        if "spread" in slots:
            put(_dialect_name(dialect, "EGT_spread_C", "TTXSP1", "exh_spread_C"), spread, 2)
        if "egt_avg" in slots:
            put(_dialect_name(dialect, "EGT_avg_C", "TTXM", "exh_avg_C"), egt_avg, 2)
        if "trip" in slots:
            cols[_dialect_name(dialect, "trip_active", "TRIP_FLAG", "trip_flag")] = a["trip_active"].astype(int)
        if "dyn" in slots:
            for j in range(n_probe):
                name = _dialect_name(dialect, f"comb_dyn_{j + 1}_psi", f"CDM_AMP_{j + 1}", f"dyn_probe_{j + 1}")
                wave = a["comb_dyn_psi"] + rng.normal(0, 0.02, n)
                cols[name] = np.round(wave, 3)
        if "vib" in slots:
            put(_dialect_name(dialect, "vib_DE_mm_s", "BB1", "vib_de"), np.clip(a["vib_DE_mm_s"], 0.05, None), 3)
            put(_dialect_name(dialect, "vib_NDE_mm_s", "BB2", "vib_nde"), np.clip(a["vib_NDE_mm_s"], 0.05, None), 3)
        if "igv" in slots:
            put(_dialect_name(dialect, "IGV_deg", "CSGV", "IGV"), a["IGV_deg"], 2)
        if "speed" in slots:
            put(_dialect_name(dialect, "speed_rpm", "TNH", "shaft_rpm"), a["speed_rpm"], 1)
        if "brg_vib" in slots:
            for j in range(n_brg):
                name = _dialect_name(dialect, f"BRG{j + 1}_VIB_mm_s", f"BV{j + 1}", f"vib_brg_{j + 1}")
                cols[name] = np.round(np.clip(a["brg"][:, j], 0.05, None), 3)
        if "lube_supply" in slots or "oil_supply_t" in slots:
            put(_dialect_name(dialect, "lube_oil_C", "LTOT", "oil_supply_C"), a["lube_oil_C"], 2)
        if "oil_hdr_p" in slots:
            put(_dialect_name(dialect, "oil_hdr_bar", "lube_hdr_pressure", "oil_hdr_bar"), a["oil_hdr"], 3)
        if "ambient_t" in slots:
            put(_dialect_name(dialect, "ambient_C", "AFTAMB", "ambient_temp"), a["ambient"], 2)
        if "inlet_dp" in slots:
            put(_dialect_name(dialect, "inlet_dp_mbar", "AFPAP", "filter_house_dp"), a["inlet_dp"], 3)
        if "drain_t" in slots:
            for j in range(n_drain):
                name = _dialect_name(dialect, f"drain_T{j + 1}_C", f"LTB{j + 1}D", f"drain_t_{j + 1}")
                cols[name] = np.round(a["drains"][:, j], 2)
        if "heater_out" in slots:
            put("heater_out_C", a["heater_out"], 2)
        if "fuel_gas" in slots:
            put("fuel_gas_C", a["fuel_gas"], 2)

        # igv_ref is not a slot of igv_fuel_control. Writing it as an extra tag puts it in _other.
        extra_tags: List[str] = []
        if pid == "igv_fuel_control":
            ref_name = _dialect_name(dialect, "IGV_ref_deg", "CSRGV", "IGV_REF")
            put(ref_name, a["igv_ref"], 2)
            extra_tags.append(ref_name)
        n_extra = int(rng.integers(0, EXTRA_TAG_MAX + 1))
        if n_extra:
            pool = [name for name in _EXTRA_POOL if name not in cols]
            pick = rng.choice(pool, size=min(n_extra, len(pool)), replace=False)
            for k, name in enumerate(np.atleast_1d(pick)):
                cols[str(name)] = np.round(rng.normal(10 + k, 0.4, n), 3)
                extra_tags.append(str(name))
        df = pd.DataFrame(cols)
        if rng.random() < GENERIC_NAME_P:
            analytic = str(rng.choice(GENERIC_ANALYTICS))
        else:
            analytic = str(rng.choice(PROFILE_NAMES[pid]))
        notes, note_meta = _notes(sig, rng, params.get("sensor_index") or params.get("center_tc"))
        info = BASE_SIGNATURES.get(sig) or UNSEEN_SIGNATURES.get(sig) or {}
        meta = {
            "case_id": f"{split}-{pid}-{sig}-{variant or 'base'}-{i:03d}",
            "split": split,
            "profile": pid,
            "signature": sig,
            "action": info.get("action", "escalate"),
            "cause": info.get("cause", "unknown"),
            "escalate": bool(info.get("escalate", False)),
            "variant": variant,
            "ambiguous": bool(spec.get("ambiguous")),
            "analytic": analytic,
            "notes": notes,
            "notes_hint": note_meta["hint"],
            "dialect": dialect,
            "slots_present": slots,
            "missing_tags": missing,
            "extra_tags": extra_tags,
            "layout": ("zones" if use_zones else "ring") if "exh_tc" in slots else "none",
            "n_sensors": int(temps.shape[1]) if "exh_tc" in slots else 0,
            "freq_min": freq,
            "rows": n,
            "operating_profile": op,
            "frame_rated_MW": round(float(fp["rated"]), 1),
            "event_start": idx[ev[0]].strftime("%Y-%m-%d %H:%M") if ev else None,
            "event_end": idx[min(ev[1], n - 1)].strftime("%Y-%m-%d %H:%M") if ev else None,
            "params": params,
        }
        return df, meta


    def _write_profile_one(job: Tuple[Dict[str, Any], str]) -> Dict[str, Any]:
        """Write ``split/profile/case.csv.gz`` and return the manifest row."""
        spec, out = job
        df, meta = make_profile_case(spec)
        path = Path(out) / meta["split"] / meta["profile"] / f"{meta['case_id']}.csv.gz"
        path.parent.mkdir(parents=True, exist_ok=True)
        df.to_csv(path, index=False, compression="gzip")
        meta["file"] = f"{meta['split']}/{meta['profile']}/{path.name}"
        return meta


    def _generate_profile_dataset(out: Path, scale: float, workers: int, only_split: Optional[str],
                                  profiles: List[str]) -> List[Dict[str, Any]]:
        """Alert-type dataset. The coldstart profile is not in train and is not a shipped id."""
        import multiprocessing as mp

        out = Path(out)
        out.mkdir(parents=True, exist_ok=True)
        specs = profile_specs(scale, list(profiles))
        keep: List[Dict[str, Any]] = []
        if only_split:
            specs = [s for s in specs if s["split"] == only_split]
            mf = out / "manifest.jsonl"
            if mf.is_file():
                keep = [r for r in (json.loads(x) for x in mf.read_text(encoding="utf-8").splitlines() if x.strip())
                        if r.get("split") != only_split]
        jobs = [(s, str(out)) for s in specs]
        workers = workers or max(1, (mp.cpu_count() or 2) - 2)
        if workers > 1 and len(jobs) > 8:
            with mp.get_context("spawn").Pool(workers) as pool:
                rows = pool.map(_write_profile_one, jobs, chunksize=4)
        else:
            rows = [_write_profile_one(j) for j in jobs]
        rows = keep + rows
        rows.sort(key=lambda r: (r.get("split", ""), r.get("profile", ""), r.get("case_id", "")))
        with (out / "manifest.jsonl").open("w", encoding="utf-8") as fh:
            for r in rows:
                fh.write(json.dumps(r) + "\n")
        counts: Dict[str, int] = {}
        for r in rows:
            counts[r["split"]] = counts.get(r["split"], 0) + 1
        print(f"Profile dataset: {len(rows)} cases in {out}  " + "  ".join(f"{k}={v}" for k, v in counts.items()))
        return rows


    # --- end alert-type profiles
    def main(argv: Optional[List[str]] = None) -> None:
        """Function main."""
        ap = argparse.ArgumentParser(description="Generate synthetic gas-turbine historian CSVs (samples or labeled e2e dataset).")
        ap.add_argument("--dataset", help="write the labeled e2e dataset into this folder (e.g. data/e2e/dataset)")
        ap.add_argument("--scale", type=float, default=1.0, help="dataset size multiplier (1.0 = ~1900 cases)")
        ap.add_argument("--workers", type=int, default=0)
        ap.add_argument("--only-split", help="write only this split (e.g. sensorfault) and merge it into the existing manifest")
        ap.add_argument("--profiles", action="store_true", help="write the seven alert-type profiles plus the coldstart heater split")
        a = ap.parse_args(argv)
        if a.dataset:
            chosen = list(ALL_SYNTH_PROFILES) if a.profiles else None
            generate_dataset(Path(a.dataset), scale=a.scale, workers=a.workers, only_split=a.only_split, profiles=chosen)
        else:
            generate_all()


    if __name__ == "__main__":
        main()
# >>>>>>> END sentinel.generator

# =============================================================================
# sentinel.triage
# Turn analyzer findings into one action, an urgency and the reasons a human must look.
# =============================================================================
# <<<<<<< SECTION sentinel.triage sentinel/triage.py
if False:  # compiled by exec_section('sentinel.triage'); not executed as part of this module
    """Decision layer: severity, cause, action, urgency, confidence, needs_human — all by rule.

    The LLM never changes what is decided here. Every adjustment is recorded as a factor or rule
    so the report can show exactly why the decision came out the way it did.
    """

    # @@future@@ from __future__ import annotations

    from dataclasses import asdict, dataclass, field
    from typing import Any, Dict, List, Optional, Tuple

    from .analytics import Resolution, best_probe
    from .analytics.base import ACTIONS, CAUSES, SEVERITY_ORDER, Findings
    from .anomaly import overlaps
    from .data import CaseData
    from .limits import GENERAL


    @dataclass
    class Decision:
        """Class Decision."""
        analytic: str
        cause: str
        cause_title: str
        hypothesis: str
        primary_action: str
        secondary_actions: List[str]
        urgency: str
        severity: str
        escalate: bool
        needs_human: bool
        review_flags: List[str]
        confidence: float
        confidence_label: str
        confidence_factors: List[Tuple[str, float]]
        rules_fired: List[str]
        alternatives: List[Dict[str, Any]]
        rule_action: str
        feedback_effects: List[Dict[str, Any]] = field(default_factory=list)

        def to_dict(self) -> Dict[str, Any]:
            """Function to_dict."""
            return asdict(self)

        @property
        def action_label(self) -> str:
            """Function action_label."""
            return ACTIONS.get(self.primary_action, self.primary_action)


    def _label(c: float) -> str:
        """Function _label."""
        return "High" if c >= 0.75 else ("Medium" if c >= 0.5 else "Low")


    def _endorsed_action(sim: Dict[str, Any]) -> Optional[str]:
        """Function _endorsed_action."""
        if sim.get("verdict") == "good":
            return sim.get("final_action") or sim.get("primary_action")
        if sim.get("verdict") == "not_good" and sim.get("corrected_action"):
            return sim["corrected_action"]
        return None


    def decide(
        res: Resolution,
        case: CaseData,
        findings: Findings,
        anomaly: Dict[str, Any],
        probes: Dict[str, Findings],
        similar: List[Dict[str, Any]],
    ) -> Decision:
        """Function decide."""
        factors: List[Tuple[str, float]] = []
        flags: List[str] = list(findings.review_flags)
        rules: List[str] = []
        needs_human = False

        top = findings.top
        if top is None:
            cause, action, secondary, title, score = "unknown", "escalate", [], "No hypothesis could be formed", 0.0
        else:
            cause, action, secondary, title, score = top.cause, top.action, list(top.secondary), top.title, top.score
            rules += top.rules
        severity, urgency, escalate = findings.severity, findings.urgency, findings.escalate

        # Insufficient data for the analytic: cannot conclude -> escalate for manual review
        if findings.missing_channels and not findings.detected:
            cause, action, title = "unknown", "escalate", "Required channels missing — cannot evaluate this analytic"
            severity, urgency = "medium", "prompt"
            flags.append("Required channels missing: " + "; ".join(findings.missing_channels))
            rules.append("TR-DATA")

        conf = 0.35 + 0.5 * score
        factors.append((f"rule support for '{cause}' hypothesis = {score:.2f}", round(conf, 2)))

        if len(findings.hypotheses) > 1:
            margin = findings.hypotheses[0].score - findings.hypotheses[1].score
            if margin < 0.15:
                factors.append((f"competing hypothesis within {margin:.2f}: {findings.hypotheses[1].title}", -0.15))
                flags.append(f"Two causes are close: {findings.hypotheses[0].cause} vs {findings.hypotheses[1].cause}.")
            elif margin >= 0.5:
                factors.append((f"clear margin over the alternative ({margin:.2f})", 0.05))

        # Data sufficiency
        q = case.quality
        if findings.missing_channels:
            factors.append(("required channels missing", -0.3))
        if q.get("rows", 0) < GENERAL["min_rows"]:
            factors.append((f"only {q.get('rows')} rows", -0.2))
            flags.append("Very short data record — baselines are unreliable.")
        if not q.get("has_timestamps"):
            factors.append(("no calendar timestamps", -0.05))
        if findings.events:
            ev = findings.events[0]
            if ev["start_i"] < case.samples(24 * 60):
                factors.append(("less than 24 h of data before the event (weak baseline)", -0.1))
                flags.append("Less than 24 h of normal data before the event.")
        poor = set(q.get("poor_channels", [])) | set(q.get("flatlined_channels", []))
        if poor & set(findings.explained_channels):
            factors.append(("poor-quality channels used by the analysis: " + ", ".join(sorted(poor & set(findings.explained_channels))), -0.1))

        # Corroboration from the anomaly scan (never decides, only supports)
        if findings.events:
            a, b = findings.events[0]["start_i"], findings.events[0]["end_i"]
            pad = case.samples(6 * 60)
            tsp = anomaly.get("tspulse") or {}
            if any(overlaps(d["windows"], a, b, pad) for d in tsp.get("channels", [])):
                factors.append(("TS Pulse independently flags the event window", 0.05))
                rules.append("AN-TSP")
            if any(overlaps(d["windows"], a, b, pad) for d in anomaly.get("zscore", {}).get("channels", [])):
                factors.append(("robust z-score scan flags the event window", 0.03))
                rules.append("AN-Z")

        # Novel anomalies: strong, sustained deviations in channels the analytic does not explain
        explained = set(findings.explained_channels)
        novel = [d for d in anomaly.get("zscore", {}).get("channels", []) if d["channel"] not in explained and res.known]
        if novel:
            names = ", ".join(f"{d['channel']} (|z| {d['max_z']})" for d in novel[:4])
            factors.append((f"unexplained anomalies: {names}", -0.1))
            flags.append(f"Novel pattern: anomalies not explained by the {res.analytic} analysis — {names}.")
            rules.append("AN-NOVEL")

        # Cross-check: analytic not confirmed but another signature is present
        if res.known and (not findings.detected or cause == "not_confirmed"):
            other = best_probe(probes)
            if other is not None:
                flags.append(f"Data does not show the {res.analytic} signature but matches {other.analytic}: {other.summary}")
                factors.append((f"data matches a different analytic ({other.analytic})", -0.1))
                rules.append("TR-XCHK")

        for fl in findings.review_flags:
            factors.append((f"analyzer review flag: {fl[:70]}", -0.05))

        # Engineer feedback on similar cases
        rule_action = action
        effects: List[Dict[str, Any]] = []
        applicable = [s for s in similar if s["similarity"] >= GENERAL["feedback_apply_similarity"]]
        votes: Dict[str, float] = {}
        for s in applicable:
            ea = _endorsed_action(s)
            if ea:
                votes[ea] = votes.get(ea, 0.0) + s["similarity"]
        if votes:
            endorsed = max(votes.items(), key=lambda kv: kv[1])[0]
            support = [s for s in applicable if _endorsed_action(s) == endorsed]
            best = max(support, key=lambda s: s["similarity"])
            if endorsed != action and endorsed in ACTIONS:
                effects.append({"case_id": best["case_id"], "similarity": best["similarity"], "effect": f"primary action changed {action} -> {endorsed}", "reason": best.get("reason", "")})
                if action not in secondary and action != "monitor_only":
                    secondary.insert(0, action)
                action = endorsed
                secondary = [x for x in secondary if x != endorsed]
                rules.append("FB-OVERRIDE")
                flags.append(
                    f"Primary action changed from {rule_action} to {endorsed} based on engineer feedback on similar case "
                    f"{best['case_id']} (similarity {best['similarity']:.2f}) — confirm it applies here."
                )
                factors.append((f"action follows engineer correction on {best['case_id']}", 0.0))
            else:
                n = len(support)
                bonus = min(0.1, 0.05 * n)
                effects.append({"case_id": best["case_id"], "similarity": best["similarity"], "effect": f"action confirmed by {n} similar reviewed case(s)", "reason": best.get("reason", "")})
                factors.append((f"same action endorsed by engineers on {n} similar case(s)", bonus))
                rules.append("FB-CONFIRM")
        for s in applicable:
            if s.get("verdict") == "not_good" and not s.get("corrected_action") and s.get("primary_action") == action:
                factors.append((f"similar case {s['case_id']} with this action was marked Not good", -0.1))
                flags.append(f"Similar case {s['case_id']} with the same action was rejected: {s.get('reason') or 'no reason given'}.")
                effects.append({"case_id": s["case_id"], "similarity": s["similarity"], "effect": "confidence reduced (rejected, no correction)", "reason": s.get("reason", "")})
                rules.append("FB-REJECT")

        conf += sum(d for _, d in factors[1:])
        if not res.known:
            if conf > 0.4:
                factors.append(("unrecognised analytic: confidence capped at 0.40", round(0.4 - conf, 2)))
            conf = min(conf, 0.4)
        conf = round(max(0.05, min(0.95, conf)), 2)

        if action == "escalate":
            escalate = True
        if "escalate" in secondary:
            escalate = True
            secondary = [s for s in secondary if s != "escalate"]
        if severity == "critical":
            escalate = True

        needs_human = bool(
            not res.known
            or conf < 0.5
            or flags
            or findings.missing_channels
            or not findings.detected
            or cause in ("unknown", "not_confirmed")
        )
        alternatives = [
            {"cause": h.cause, "title": h.title, "action": h.action, "score": h.score, "why_not": "; ".join(h.against) or "lower rule support"}
            for h in findings.hypotheses[1:]
        ]
        if severity not in SEVERITY_ORDER:
            severity = "medium"
        return Decision(
            analytic=res.analytic,
            cause=cause,
            cause_title=CAUSES.get(cause, cause),
            hypothesis=title,
            primary_action=action,
            secondary_actions=sorted(set(s for s in secondary if s in ACTIONS and s != action)),
            urgency=urgency,
            severity=severity,
            escalate=escalate,
            needs_human=needs_human,
            review_flags=list(dict.fromkeys(flags)),
            confidence=conf,
            confidence_label=_label(conf),
            confidence_factors=factors,
            rules_fired=list(dict.fromkeys(rules)),
            alternatives=alternatives,
            rule_action=rule_action,
            feedback_effects=effects,
        )
# >>>>>>> END sentinel.triage

# =============================================================================
# sentinel.e2e.train
# Quick-update pieces: refit the head, recalibrate novelty, score held-out, promote only when not worse.
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.train sentinel/e2e/train.py
if False:  # compiled by exec_section('sentinel.e2e.train'); not executed as part of this module
    """Quick and full TS Pulse retrains: promote only when held-out accuracy does not drop.

    Quick update (seconds, once validation embeddings are cached): refit the classifier
    head on every labeled case (synthetic training split + engineer labels), rebuild the
    similarity index from those same cases, and recalibrate the novelty / one-shot
    thresholds. The encoder does not move, so embeddings stay valid.

    Full retrain (about 15-20 min on CPU): fine-tune TS Pulse on the same cases, then
    do the quick steps with the new embeddings. Device is ``auto``, ``gpu`` or ``cpu``;
    the GPU is used when CUDA works and the run falls back to CPU when it does not or
    when the card runs out of memory (see ``encoder.finetune``).

    A result is always saved as a new model version. It becomes the active model only
    when held-out action accuracy and signature accuracy are not worse than the active
    model, unless the engineer forces it. Rollback restores an earlier version,
    including its encoder when that version fine-tuned one.

    ``retrain_profile`` is the same idea for one alert type. A site alert type with
    under 10 labels only rebuilds the block index and the calibration. A built-in
    keeps its shipped rows, so five new labels still face the held-out gate and
    cannot replace the shipped head with a five-row index. From 10 site labels the
    candidate must hold action and signature accuracy. The active side is the
    served version, not a refit on the candidate's rows. From 50 labels the site
    held-out split is frozen and the gate also watches false novelty and the frame
    and signature slices. One profile's version does not move another profile.
    """

    # @@future@@ from __future__ import annotations

    from pathlib import Path
    from typing import Any, Dict, List, Optional, Sequence

    import numpy as np

    from .model import Calibration, Head, SimilarityIndex, calibrate, decide, project_embedding
    from .taxonomy import NOVEL


    def _metrics_hold(before: Optional[Dict[str, Any]], after: Optional[Dict[str, Any]]) -> bool:
        """Action and signature accuracy both hold or improve. A tie is not worse."""
        if not before or before.get("action_acc") is None or before.get("signature_acc") is None:
            return bool(after) and after.get("action_acc") is not None and after.get("signature_acc") is not None
        if not after or after.get("action_acc") is None or after.get("signature_acc") is None:
            return False
        return after["action_acc"] + 1e-9 >= before["action_acc"] and after["signature_acc"] + 1e-9 >= before["signature_acc"]


    def not_worse(before: Optional[Dict[str, Any]], after: Optional[Dict[str, Any]]) -> bool:
        """True when the new model should replace the active one.

        The overall gate is the shipped held-out test split: action accuracy and signature
        accuracy must both hold or improve. A tie is not worse. With no before
        numbers (no held-out file) there is nothing to protect, so the new model
        is promoted. With no after numbers it is not.

        A frame slice or an alert slice with at least ``SLICE_MIN_CASES`` on both sides
        blocks promotion on its own when either accuracy drops. A slice that is missing
        on one side, or that is too small to trust, does not block. ``--force`` is the
        override, and the caller logs it.
        """
        if not _metrics_hold(before, after):
            return False
        from ..config import SLICE_MIN_CASES, migrate_frame_table

        for key in ("by_frame", "by_alert"):
            bmap = (before or {}).get(key) or {}
            amap = (after or {}).get(key) or {}
            if key == "by_frame":
                # A stored "before" may still say ring_tc while the new score says 7EA.
                bmap = migrate_frame_table(bmap if isinstance(bmap, dict) else {})
                amap = migrate_frame_table(amap if isinstance(amap, dict) else {})
            if not isinstance(bmap, dict) or not isinstance(amap, dict):
                continue
            for name, brow in bmap.items():
                if not isinstance(brow, dict) or int(brow.get("n") or 0) < SLICE_MIN_CASES:
                    continue
                arow = amap.get(name)
                if not isinstance(arow, dict) or int(arow.get("n") or 0) < SLICE_MIN_CASES:
                    continue
                if not _metrics_hold(brow, arow):
                    return False
        return True


    def preserve_residual(old: Calibration, fresh: Calibration) -> Calibration:
        """Keep the residual-novelty rule when the distance thresholds are recalibrated.

        Quick and full refits recompute the nearest-neighbour novelty threshold from
        the current index. The residual rule (which channels count as abnormal, and
        when that plus a borderline match means NOVEL) was calibrated on the
        validation split against the residual feed and does not depend on the head,
        so wiping it on every retrain would silently disable the second TS Pulse view.
        """
        fresh.residual_novelty = old.residual_novelty
        fresh.novelty_border = old.novelty_border
        fresh.novelty_conf = old.novelty_conf
        fresh.residual_thresholds = dict(old.residual_thresholds)
        fresh.residual_notes = old.residual_notes
        fresh.low_confidence = old.low_confidence
        return fresh


    def loo_calibration(index: SimilarityIndex, quantile: float = 0.98) -> Calibration:
        """Novelty thresholds from leave-one-out distances inside the index.

        Used only when the synthetic validation split is not on disk. Each labeled
        case's distance to the nearest *other* labeled case is an in-distribution
        radius; the high quantile is the novelty threshold. It is a bit tighter than
        a true held-out calibration (siblings of the same signature sit in the index)
        but it still moves when the engineer adds cases, which is the point of a
        quick update.
        """
        if len(index) < 2:
            return Calibration(novelty_threshold=0.5, match_threshold=0.25, novelty_quantile=quantile, notes="too few labeled cases to calibrate")
        sim = np.clip(index.Z @ index.Z.T, -1.0, 1.0)
        np.fill_diagonal(sim, -np.inf)
        nn = 1.0 - sim.max(axis=1)
        nov = float(np.quantile(nn, quantile))
        # Same-signature distances, when a signature has at least two cases.
        same = []
        sigs = np.array([r["signature"] for r in index.records])
        for i, s in enumerate(sigs):
            m = sigs == s
            m[i] = False
            if m.any():
                same.append(float((1.0 - sim[i, m]).min()))
        match = float(np.quantile(same, 0.5)) if same else nov / 2
        return Calibration(
            novelty_threshold=round(nov, 4),
            match_threshold=round(min(match, nov * 0.8), 4),
            novelty_quantile=quantile,
            notes=f"leave-one-out on {len(index)} labeled cases: NN median {float(np.median(nn)):.3f}, q{int(quantile * 100)} {nov:.3f}",
        )


    def per_frame_thresholds(index: SimilarityIndex, Zval: np.ndarray, frames: Sequence[str], quantile: float) -> Dict[str, float]:
        """Layout radii, plus a frame-model radius only when that model has enough cases.

        ``frames`` are frame-model ids (or old layout ids). Distances are pooled by tag
        layout. A layout with at least ``FRAME_NOVELTY_MIN`` labeled calibration cases
        gets a key equal to the layout id. A frame model with at least that many of its
        own cases also gets a key equal to the model id. A model with fewer cases is
        left out, and ``novelty_limit`` uses the layout radius, so 6B / 9E / 9FA are
        not given a radius estimated from an empty bucket. A layout under the minimum
        is left out too, and the shared radius is used.
        """
        from ..config import FRAME_NOVELTY_MIN, LAYOUTS, canonical_frame, layout_of

        by_frame: Dict[str, List[float]] = {}
        by_layout: Dict[str, List[float]] = {}
        for z, frame in zip(Zval, frames):
            if not frame or frame == "auto":
                continue
            d = index.distances(z)
            if d.size == 0:
                continue
            dist = float(d.min())
            name = str(frame)
            lay = layout_of(name)
            if lay:
                by_layout.setdefault(lay, []).append(dist)
            # An old layout id is the layout, not a model that should grow its own key.
            if name not in LAYOUTS:
                fid = canonical_frame(name) or name
                if fid and fid not in LAYOUTS:
                    by_frame.setdefault(fid, []).append(dist)
        out: Dict[str, float] = {}
        for lay, dists in by_layout.items():
            if len(dists) >= FRAME_NOVELTY_MIN:
                out[lay] = round(float(np.quantile(dists, quantile)), 4)
        for fid, dists in by_frame.items():
            if len(dists) >= FRAME_NOVELTY_MIN:
                out[fid] = round(float(np.quantile(dists, quantile)), 4)
        return out


    def recalibrate(old: Calibration, index: SimilarityIndex, Zval: Optional[np.ndarray], yval: Optional[Sequence[str]],
                    frames: Optional[Sequence[str]] = None) -> Calibration:
        """Validation-split calibration when those embeddings exist, else leave-one-out."""
        if Zval is not None and yval is not None and len(Zval):
            fresh = calibrate(index, Zval, list(yval), quantile=old.novelty_quantile or 0.98)
        else:
            fresh = loo_calibration(index, quantile=old.novelty_quantile or 0.98)
        fresh = preserve_residual(old, fresh)
        if Zval is not None and frames is not None and len(frames) == len(Zval) and len(Zval):
            fresh.frame_thresholds = per_frame_thresholds(index, Zval, frames, fresh.novelty_quantile or 0.98)
        else:
            fresh.frame_thresholds = dict(old.frame_thresholds or {})
        return fresh


    def _slice_scores(keys: Sequence[str], signature: np.ndarray, decisions: Sequence[Dict[str, Any]], tax: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        """Accuracy for each non-empty key (a frame id or an alert signature)."""
        grouped: Dict[str, List[int]] = {}
        for i, key in enumerate(keys):
            if not key:
                continue
            grouped.setdefault(str(key), []).append(i)
        out: Dict[str, Dict[str, Any]] = {}
        for key, idx in grouped.items():
            ok_sig = ok_act = 0
            for i in idx:
                d = decisions[i]
                s = str(signature[i])
                ok_sig += d["signature"] == s
                got = tax.get(d["signature"], {}).get("action") if d["signature"] != NOVEL else "escalate"
                ok_act += got == tax.get(s, {}).get("action")
            n = len(idx)
            out[key] = {"n": n, "signature_acc": round(ok_sig / n, 4), "action_acc": round(ok_act / n, 4)}
        return out


    def score_heldout(Z: np.ndarray, signature: np.ndarray, rules_action: np.ndarray, head: Head, index: SimilarityIndex,
                      cal: Calibration, tax: Dict[str, Dict[str, Any]], frames: Optional[Sequence[str]] = None) -> Dict[str, Any]:
        """Held-out accuracy plus novelty and one-shot counts, and the same numbers per frame and per alert.

        The shipped test split is all known signatures, so ``novelty_rate`` here is
        the false-novelty rate (known cases called NOVEL). ``one_shot_acc`` is the
        signature accuracy of the cases the index overrode; it is null when one-shot
        did not fire. Action accuracy uses the taxonomy, and NOVEL counts as escalate.
        ``frames`` empty means the slice tables stay empty (the shipped head has no frame column).
        """
        n = len(signature)
        if n == 0:
            return {}
        frame_l = [str(f) if f else "" for f in frames] if frames is not None else [""] * n
        if len(frame_l) != n:
            frame_l = [""] * n
        ok_sig = ok_act = novel = oneshot = oneshot_ok = 0
        decisions: List[Dict[str, Any]] = []
        for z, s, frame in zip(Z, signature, frame_l):
            zz = project_embedding(z, frame, head)
            d = decide(zz, head, index, cal, frame=frame or None)
            decisions.append(d)
            ok_sig += d["signature"] == s
            got = tax.get(d["signature"], {}).get("action") if d["signature"] != NOVEL else "escalate"
            ok_act += got == tax.get(str(s), {}).get("action")
            novel += bool(d["novel"])
            if d["one_shot"]:
                oneshot += 1
                oneshot_ok += d["signature"] == s
        truth_act = np.array([tax.get(str(s), {}).get("action") for s in signature])
        return {
            "n": int(n),
            "signature_acc": round(ok_sig / n, 4),
            "action_acc": round(ok_act / n, 4),
            "rules_action_acc": round(float((rules_action == truth_act).mean()), 4),
            "novelty_rate": round(novel / n, 4),
            "one_shot_n": int(oneshot),
            "one_shot_acc": round(oneshot_ok / oneshot, 4) if oneshot else None,
            "by_frame": _slice_scores(frame_l, signature, decisions, tax),
            "by_alert": _slice_scores([str(s) for s in signature], signature, decisions, tax),
        }


    def _profile_id(profile_id: str) -> str:
        """A profile id that can be one directory name. ``_adhoc`` is not trained."""
        pid = str(profile_id or "").strip()
        if not pid or pid in {".", "..", "_adhoc"} or "/" in pid or "\\" in pid:
            raise ValueError(f"profile id is not a trainable alert type: {profile_id!r}")
        return pid


    def held_out_case(case_id: str) -> bool:
        """True when this case belongs on the site held-out split.

        The test is one fifth of case ids (``sha1 % 5 == 0``). It does not depend on
        arrival order, so the same case is held out on every machine.
        """
        import hashlib

        digest = hashlib.sha1(str(case_id).encode("utf-8")).hexdigest()
        return int(digest, 16) % 5 == 0


    def fold_of_case(case_id: str) -> int:
        """Hash fold for the quick gate. The same id always lands in the same fold."""
        import hashlib

        from ..config import CV_FOLDS

        digest = hashlib.sha1(str(case_id).encode("utf-8")).hexdigest()
        return int(digest, 16) % int(CV_FOLDS)


    def assign_heldout(settings: Any, profile_id: str, case_ids: Sequence[str]) -> set:
        """Frozen site held-out ids for one alert type.

        Below 50 labels nothing is held out: a small alert type needs every label,
        and its gate is cross-validation. At 50 the hash split is written to
        ``heldout/<pid>.json``. An id that was written stays written.
        """
        import json

        from ..config import HELDOUT_MIN_LABELS
        from .labels import e2e_dir

        pid = _profile_id(profile_id)
        path = e2e_dir(settings) / "heldout" / f"{pid}.json"
        frozen: set = set()
        if path.is_file():
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                data = {}
            frozen = {str(item) for item in (data.get("ids") or [])}
        ids = [str(item) for item in case_ids]
        if len(ids) < HELDOUT_MIN_LABELS and not frozen:
            return set()
        chosen = set(frozen)
        if len(ids) >= HELDOUT_MIN_LABELS:
            chosen.update(item for item in ids if held_out_case(item))
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps({"profile": pid, "ids": sorted(chosen)}, indent=2), encoding="utf-8")
        return {item for item in ids if item in chosen}


    def profile_labels_since_retrain(settings: Any, profile_id: str) -> int:
        """Labels for this alert type since its own last retrain or rollback.

        A legacy retrain does not reset this counter, and a profile retrain does
        not reset the legacy one. The two loops count different label lines.
        """
        from .labels import Metrics

        pid = str(profile_id or "")
        events = Metrics(settings).events()
        last = max(
            (i for i, event in enumerate(events) if event.get("type") in ("retrain", "rollback") and event.get("profile") == pid),
            default=-1,
        )
        return sum(1 for event in events[last + 1 :] if event.get("type") == "label" and event.get("profile") == pid)


    def profile_ids_with_labels(settings: Any) -> List[str]:
        """Alert types that have at least one latest label, in first-seen order."""
        from .labels import LabelStore

        seen: List[str] = []
        for rec in LabelStore(settings).latest().values():
            pid = str(rec.get("profile") or "")
            if pid and pid != "_adhoc" and pid not in seen and rec.get("signature") not in (None, "", NOVEL):
                seen.append(pid)
        return seen


    def profile_gate_reasons(before: Optional[Dict[str, Any]], after: Optional[Dict[str, Any]]) -> List[str]:
        """Why a held-out candidate must not replace the active profile model.

        Overall action and signature accuracy use the legacy rule (a tie is not
        worse, and a slice blocks only with at least 8 cases on both sides).
        False novelty may rise by at most ``NOVELTY_GATE_TOL``.
        """
        from ..config import NOVELTY_GATE_TOL

        reasons: List[str] = []
        if not _metrics_hold(before, after):
            reasons.append("overall action or signature accuracy dropped")
        elif not not_worse(before, after):
            reasons.append("a frame or signature slice with at least 8 cases on both sides dropped")
        before_rate = None if not before else before.get("false_novelty")
        after_rate = None if not after else after.get("false_novelty")
        if before_rate is not None and after_rate is not None and float(after_rate) > float(before_rate) + float(NOVELTY_GATE_TOL) + 1e-12:
            reasons.append(f"false novelty rose from {before_rate} to {after_rate}")
        return reasons


    def _cv_reasons(before: Optional[Dict[str, Any]], after: Optional[Dict[str, Any]]) -> List[str]:
        """The 10–49 label gate: mean fold accuracy must hold for action and signature."""
        reasons: List[str] = []
        for key, label in (("action_acc", "action"), ("signature_acc", "signature")):
            old = None if not before else before.get(key)
            new = None if not after else after.get(key)
            if old is None or new is None or float(new) + 1e-9 < float(old):
                reasons.append(f"cross-validation {label} accuracy {new} is below the active {old}")
        return reasons


    def _mean_metrics(parts: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
        """Unweighted mean of the folds that actually had a test case."""
        usable = [part for part in parts if part.get("action_acc") is not None]
        if not usable:
            return {"n": 0, "action_acc": None, "signature_acc": None, "false_novelty": None}
        return {
            "n": int(sum(int(part.get("n") or 0) for part in usable)),
            "action_acc": round(sum(float(part["action_acc"]) for part in usable) / len(usable), 4),
            "signature_acc": round(sum(float(part["signature_acc"]) for part in usable) / len(usable), 4),
            "false_novelty": round(sum(float(part.get("false_novelty") or 0.0) for part in usable) / len(usable), 4),
        }


    def _action_of(signature: str, tax: Dict[str, Dict[str, Any]]) -> str:
        """Taxonomy action. A novel call counts as escalate, matching the legacy score."""
        if signature == NOVEL:
            return "escalate"
        return str((tax.get(signature) or {}).get("action") or "")


    STATS_SCALER_FILE = "stats_scaler.npz"


    def stats_scaler(settings: Any):
        """Scaler of the statistical view, ``stats_scaler.npz`` next to the active encoder.

        The trainer fits it on the present statistical blocks of every built-in's
        train rows, the way ``channel_scaler.npz`` is fit on TS Pulse blocks, and
        every statistical bundle is built on rows it scaled. Serving those
        bundles with the identity scaler compared a standardised index with raw
        query blocks. A folder without the file (an older install, a test model
        dir) keeps the identity, which still L2-normalises a present channel.
        """
        from pathlib import Path

        from .labels import Registry
        from .model import ChannelScaler

        reg = Registry(settings)
        path = Path(reg.encoder_folder(reg.current_encoder())) / STATS_SCALER_FILE
        if path.is_file():
            return ChannelScaler.load(path)
        return ChannelScaler(np.zeros(48, dtype=np.float64), np.ones(48, dtype=np.float64))


    def _scale_profile_vector(settings: Any, vec: np.ndarray, mask: np.ndarray) -> np.ndarray:
        """The scaler of the space this vector is in.

        ``channel_scaler.npz`` is fit on channel-independent TS Pulse blocks. A
        stats vector is a different space: shifting it by that mean would move the
        two classes the tests plant on separate axes. It gets ``stats_scaler``,
        fit on statistical blocks, or the identity when that file is absent.
        A missing file must not look like a fitted zero-variance scaler.
        """
        from pathlib import Path

        from .labels import Registry
        from .model import ChannelScaler

        identity = ChannelScaler(np.zeros(48, dtype=np.float64), np.ones(48, dtype=np.float64))
        if getattr(settings, "embedder", "stats") != "tspulse_ci":
            return stats_scaler(settings).transform(vec, mask)
        reg = Registry(settings)
        path = Path(reg.encoder_folder(reg.current_encoder())) / "channel_scaler.npz"
        scaler = ChannelScaler.load(path) if path.is_file() else identity
        return scaler.transform(vec, mask)


    def _stored_profile_vector(stored: Dict[str, Any], embedder: str) -> np.ndarray:
        """The vector the index was built with. An empty TS Pulse row means the stats fallback."""
        name = embedder or "stats"
        if name == "stats":
            return np.asarray(stored["stats"], dtype=np.float32)
        vec = np.asarray(stored["tspulse"], dtype=np.float32)
        if not np.any(vec):
            return np.asarray(stored["stats"], dtype=np.float32)
        return vec


    def collect_profile_rows(settings: Any, profile_id: str) -> List[Dict[str, Any]]:
        """Latest labels for this alert type that have an ``emb2`` row of one channel count.

        A label with no embedding cannot enter the index. A row whose channel count
        differs from the first row is skipped: those blocks are not comparable.
        """
        from .labels import LabelStore, ProfileEmbeddings

        pid = _profile_id(profile_id)
        store = ProfileEmbeddings(settings)
        rows: List[Dict[str, Any]] = []
        width: Optional[int] = None
        # A TS Pulse index also keeps each label's statistical blocks for the head's second view.
        second = stats_scaler(settings) if getattr(settings, "embedder", "stats") == "tspulse_ci" else None
        for case_id, lab in LabelStore(settings).latest().items():
            if str(lab.get("profile") or "") != pid:
                continue
            signature = str(lab.get("signature") or "")
            if not signature or signature == NOVEL:
                continue
            stored = store.load(pid, case_id)
            if stored is None:
                continue
            mask = np.asarray(stored["mask"], dtype=bool).reshape(-1)
            raw = _stored_profile_vector(stored, getattr(settings, "embedder", "stats"))
            vec = _scale_profile_vector(settings, raw, mask)
            channels = int(np.asarray(vec).shape[0])
            if width is None:
                width = channels
            if channels != width:
                continue
            row = {
                "id": str(case_id),
                "signature": signature,
                "action": str(lab.get("action") or ""),
                "frame": str(lab.get("frame_key") or ""),
                "u": np.asarray(vec, dtype=np.float32),
                "mask": mask,
                "source": "engineer",
            }
            if second is not None and stored.get("stats") is not None:
                row["s"] = np.asarray(second.transform(np.asarray(stored["stats"], dtype=np.float32), mask), dtype=np.float32)
            rows.append(row)
        return rows


    def _index_from_rows(rows: Sequence[Dict[str, Any]], weights: Optional[np.ndarray] = None):
        """Block index of these rows. Held-out rows are simply not passed in."""
        from .model import MaskedIndex

        if not rows:
            return MaskedIndex()
        channels = int(np.asarray(rows[0]["u"]).shape[0])
        index = MaskedIndex(channels=channels, weights=weights)
        for row in rows:
            index.add(
                row["u"],
                row["mask"],
                row.get("frame") or "",
                {
                    "id": row["id"],
                    "signature": row["signature"],
                    "action": row.get("action") or "",
                    "source": row.get("source") or "engineer",
                    "frame": row.get("frame") or "",
                },
                stats=row.get("s"),
            )
        return index


    def _tier_allows_head(rows: Sequence[Dict[str, Any]]) -> bool:
        """20 labels and two signatures with at least three cases each."""
        from ..config import HEAD_MIN_LABELS, HEAD_MIN_PER_CLASS

        counts: Dict[str, int] = {}
        for row in rows:
            counts[row["signature"]] = counts.get(row["signature"], 0) + 1
        ready = sum(1 for count in counts.values() if count >= HEAD_MIN_PER_CLASS)
        return len(rows) >= HEAD_MIN_LABELS and ready >= 2


    def _fit_profile_head(rows: Sequence[Dict[str, Any]], frames: Sequence[str]):
        """Head on the signatures that have enough cases. Rare signatures stay one-shot only.

        When every row carries its statistical blocks (``s``) the head reads both views
        (``head_vector``, ``meta["stats_view"]``). Cross-validated on the shipped train
        rows, both views beat TS Pulse alone on every built-in (combustion dynamics
        0.927 to 0.956, IGV / fuel 0.896 to 0.943). A row without them, such as an
        older index, keeps the head on TS Pulse alone.
        """
        from ..config import HEAD_MIN_PER_CLASS
        from .model import head_vector, train_head

        counts: Dict[str, int] = {}
        for row in rows:
            counts[row["signature"]] = counts.get(row["signature"], 0) + 1
        keep = {name for name, count in counts.items() if count >= HEAD_MIN_PER_CLASS}
        if len(keep) < 2:
            return None
        kept = [row for row in rows if row["signature"] in keep]
        stats_view = all(row.get("s") is not None for row in kept)
        vectors = [
            head_vector(row["u"], row["mask"], row.get("frame") or "", frames, row.get("s"), stats_view=stats_view)
            for row in kept
        ]
        head = train_head(np.vstack(vectors), [row["signature"] for row in kept])
        head.meta["frames"] = list(frames)
        head.meta["frame_key"] = "profile"
        head.meta["stats_view"] = bool(stats_view)
        return head


    def _profile_calibration(index: Any, prior_path: Optional[Any] = None) -> Dict[str, Any]:
        """Leave-one-out radius on the index. The training path does not call this.

        A built-in bundle uses ``calibrate_alert_type`` (each validation row
        against the train index). A site alert type uses ``calibrate_site``
        (cross-fitted folds). This function stays so the frame-match rule is
        pinned on a fixed index: median same-signature distance, capped at
        0.8 times the radius. Small counts stay on the prior file.
        """
        from ..config import FRAME_NOVELTY_MIN, PROFILE_NOVELTY_MIN
        from .model import capped_match, read_novelty_prior

        prior = read_novelty_prior(prior_path)
        n = len(index)
        if n < 2:
            return {"prior": prior}
        dists: List[float] = []
        same: List[float] = []
        by_frame: Dict[str, List[float]] = {}
        by_frame_same: Dict[str, List[float]] = {}
        signatures = [str(rec.get("signature") or "") for rec in index.records]
        for i in range(n):
            dist = np.asarray(index.distances(index.U[i], index.mask[i], index.frames[i]), dtype=np.float64).copy()
            dist[i] = np.inf
            nearest = float(np.min(dist))
            dists.append(nearest)
            frame = index.frames[i]
            if frame:
                by_frame.setdefault(frame, []).append(nearest)
                frame_mates = [
                    j for j, signature in enumerate(signatures)
                    if signature == signatures[i] and j != i and index.frames[j] == frame
                ]
                if frame_mates:
                    by_frame_same.setdefault(frame, []).append(float(np.min(dist[frame_mates])))
            mates = [j for j, signature in enumerate(signatures) if signature == signatures[i] and j != i]
            if mates:
                same.append(float(np.min(dist[mates])))
        nov = float(np.quantile(dists, 0.98))
        match = float(np.quantile(same, 0.5)) if same else nov * 0.5
        if nov > 0:
            match = min(match, nov * 0.8)
        out: Dict[str, Any] = {"prior": prior}
        if n >= PROFILE_NOVELTY_MIN:
            out["profile"] = {"n": n, "radius": round(nov, 4), "match": round(match, 4)}
        frames: Dict[str, Dict[str, Any]] = {}
        for frame, vals in by_frame.items():
            if len(vals) < FRAME_NOVELTY_MIN:
                continue
            radius = float(np.quantile(vals, 0.98))
            frames[frame] = {"n": len(vals), "radius": round(radius, 4), "match": round(capped_match(by_frame_same.get(frame) or [], radius), 4)}
        if frames:
            out["frame"] = frames
        return out


    def _head_confidences(head: Any, rows: Sequence[Dict[str, Any]], frames: Sequence[str]) -> List[float]:
        """The head's top probability on each row, built the way ``ProfileModel._head`` builds it."""
        from .model import head_vector

        if head is None or not rows:
            return []
        stats_view = bool((head.meta or {}).get("stats_view"))
        vectors = np.vstack(
            [head_vector(row["u"], row["mask"], row.get("frame") or "", frames, row.get("s"), stats_view=stats_view) for row in rows]
        )
        return [float(np.max(probs)) for probs in head.proba(vectors)]


    def _val_records(
        index: Any,
        val_rows: Sequence[Dict[str, Any]],
        head: Any = None,
        frames: Sequence[str] = (),
    ) -> List[Dict[str, Any]]:
        """Nearest train-index distance for each validation row.

        Every signature is kept (decision D3). A validation row is not a
        neighbour of another validation row. ``same`` is the nearest train
        row of the same signature, or None when the index has none. With a
        ``head`` (fitted on the train rows, never on these) each record also
        carries that head's top probability as ``confidence``.
        """
        confidences = _head_confidences(head, list(val_rows), frames) if head is not None else []
        records: List[Dict[str, Any]] = []
        for position, row in enumerate(val_rows):
            dist = np.asarray(index.distances(row["u"], row["mask"], row.get("frame") or ""), dtype=np.float64)
            if dist.size == 0 or not np.isfinite(dist).any():
                continue
            signature = str(row.get("signature") or "")
            mates = [i for i, rec in enumerate(index.records) if str(rec.get("signature") or "") == signature]
            records.append(
                {
                    "nearest": float(np.min(dist)),
                    "same": float(np.min(dist[mates])) if mates else None,
                    "frame": str(row.get("frame") or ""),
                    "signature": signature,
                    "confidence": confidences[position] if confidences else None,
                }
            )
        return records


    def _fold_confidences(index: Any, rows: Sequence[Dict[str, Any]], frames: Sequence[str], folds: Sequence[int]) -> Dict[int, float]:
        """Top probability of each index row under a head fitted on the other folds.

        The head recipe is the shipped one (``_fit_profile_head`` when the tier
        allows a head). A fold whose other folds cannot fit a head gives no
        confidence. ``rows`` are matched to the index by id.
        """
        by_id = {str(row["id"]): row for row in rows}
        aligned = [by_id.get(str(rec.get("id") or "")) for rec in index.records]
        if not aligned or any(row is None for row in aligned):
            return {}
        out: Dict[int, float] = {}
        for fold in sorted(set(folds)):
            fit = [row for row, other in zip(aligned, folds) if other != fold]
            held = [i for i, other in enumerate(folds) if other == fold]
            head = _fit_profile_head(fit, frames) if _tier_allows_head(fit) else None
            if head is None:
                continue
            for i, value in zip(held, _head_confidences(head, [aligned[i] for i in held], frames)):
                out[i] = value
        return out


    def _cross_fit_records(index: Any, rows: Optional[Sequence[Dict[str, Any]]] = None, frames: Sequence[str] = ()) -> List[Dict[str, Any]]:
        """Nearest distance to a row in a different hash fold.

        The row's own fold is excluded, not only the row itself. That is the
        site radius. Leave-one-out would let two labels that landed in the
        same fold set the radius to zero. With the index's ``rows`` each record
        also carries ``confidence``: a head fitted on the other folds, scored
        on this row, so the confidence is out of sample like the distance.
        """
        folds = [fold_of_case(str(rec.get("id") or "")) for rec in index.records]
        confidence = _fold_confidences(index, rows, frames, folds) if rows is not None else {}
        records: List[Dict[str, Any]] = []
        for i, rec in enumerate(index.records):
            dist = np.asarray(index.distances(index.U[i], index.mask[i], index.frames[i]), dtype=np.float64).copy()
            for j, fold in enumerate(folds):
                if fold == folds[i]:
                    dist[j] = np.inf
            if dist.size == 0 or not np.isfinite(dist).any():
                continue
            signature = str(rec.get("signature") or "")
            mates = [
                j for j, other in enumerate(index.records)
                if folds[j] != folds[i] and str(other.get("signature") or "") == signature
            ]
            records.append(
                {
                    "nearest": float(np.min(dist)),
                    "same": float(np.min(dist[mates])) if mates else None,
                    "frame": str(index.frames[i] or ""),
                    "signature": signature,
                    "confidence": confidence.get(i),
                }
            )
        return records


    def conformal_upper(values: Sequence[float], quantile: float) -> Optional[float]:
        """Split-conformal radius: the ``k``-th smallest value, ``k = ceil((n + 1) * quantile)``.

        A new case from the same distribution is above it with probability at
        most ``1 - quantile``, for any n. ``np.quantile`` interpolates below
        that order statistic and is the near-maximum of a small sample, so it
        flagged more than its nominal share. When ``k > n`` no order
        statistic carries the guarantee and the largest value is used: never
        tighter than the old quantile, and the coverage is ``n / (n + 1)``.
        Empty input is None.
        """
        import math

        vals = np.sort(np.asarray([float(v) for v in values if np.isfinite(v)], dtype=np.float64))
        n = int(vals.shape[0])
        if n == 0:
            return None
        k = int(math.ceil((n + 1) * float(quantile) - 1e-9))
        return float(vals[min(max(k, 1), n) - 1])


    def conformal_lower(values: Sequence[float], quantile: float) -> Optional[float]:
        """The mirror of ``conformal_upper``: the ``j``-th smallest, ``j = floor((n + 1) * (1 - quantile))``.

        A new case from the same distribution is below it with probability at
        most ``1 - quantile``. Under ``j = 1`` the smallest value is used.
        Empty input is None.
        """
        import math

        vals = np.sort(np.asarray([float(v) for v in values if np.isfinite(v)], dtype=np.float64))
        n = int(vals.shape[0])
        if n == 0:
            return None
        j = int(math.floor((n + 1) * (1.0 - float(quantile)) + 1e-9))
        return float(vals[min(max(j, 1), n) - 1])


    def _calibration_from_records(records: Sequence[Dict[str, Any]], quantile: float, prior: Dict[str, Any], *, min_n: int) -> Dict[str, Any]:
        """One radius per alert type, the conformal order statistic of these nearest distances.

        No frame bucket is written. Buckets of 20-36 validation rows ran at
        4.6-6.6 % false novelty for a nominal 2 %, and even at 150 rows a
        frame's 0.98 order statistic is its third-largest distance. The frame
        still reaches the decision through the distance penalty and the head's
        frame column. A bundle written with buckets still loads and uses them.
        """
        from .model import capped_match

        finite = [row for row in records if np.isfinite(row["nearest"])]
        out: Dict[str, Any] = {"prior": dict(prior)}
        if len(finite) < int(min_n):
            return out
        radius = float(conformal_upper([float(row["nearest"]) for row in finite], quantile))
        same = [float(row["same"]) for row in finite if row.get("same") is not None and np.isfinite(row["same"])]
        out["profile"] = {"n": len(finite), "radius": round(radius, 4), "match": round(capped_match(same, radius), 4)}
        # The head's own evidence, at the same level: a known case is below this
        # floor with probability at most 1 - quantile. The decider calls a case
        # novel only when it is beyond the radius and below the floor.
        confident = [float(row["confidence"]) for row in finite if row.get("confidence") is not None]
        floor = conformal_lower(confident, quantile)
        if floor is not None:
            out["profile"]["confidence"] = round(floor, 4)
            out["profile"]["confidence_n"] = len(confident)
        return out


    def calibrate_alert_type(
        index: Any,
        val_rows: Sequence[Dict[str, Any]],
        quantile: float,
        prior_path: Optional[Any] = None,
        *,
        head: Any = None,
        rows: Optional[Sequence[Dict[str, Any]]] = None,
        frames: Sequence[str] = (),
    ) -> Dict[str, Any]:
        """Built-in radius from every known case the index was not fitted on.

        Two kinds of distance are pooled: each validation row against the train
        index, and each train row against the train rows of the other four hash
        folds (``_cross_fit_records``). On the shipped data the two have the
        same median; the cross-fitted ones run slightly longer because the
        index is a fifth smaller, which errs toward fewer novel calls. That is
        about 470-610 cases per combustion alert type instead of 67-88
        validation rows. Every listed signature counts, not only ``normal``
        (decision D3). The quantile is the alert type's
        ``thresholds.novelty_quantile``. The decider applies the radius from
        ``PROFILE_NOVELTY_MIN`` cases upward.

        With the served ``head`` and the index's train ``rows`` the same cases
        also give the confidence floor: the served head on the validation rows,
        and a head fitted on the other four folds for each train row.
        """
        from .model import read_novelty_prior

        records = _val_records(index, val_rows, head=head, frames=frames) + _cross_fit_records(
            index, rows if head is not None else None, frames
        )
        return _calibration_from_records(records, float(quantile), read_novelty_prior(prior_path), min_n=1)


    def calibrate_site(
        index: Any,
        quantile: float,
        prior_path: Optional[Any] = None,
        *,
        rows: Optional[Sequence[Dict[str, Any]]] = None,
        frames: Sequence[str] = (),
    ) -> Dict[str, Any]:
        """Site radius from cross-fitted folds. Under 20 labels, the prior.

        There is no validation split. Leave-one-out on the train rows is not
        used. Held-out rows must not be in ``index``; they only gate. With the
        index's ``rows`` (a model that has a head) the folds also give the
        confidence floor.
        """
        from ..config import PROFILE_NOVELTY_MIN
        from .model import read_novelty_prior

        records = _cross_fit_records(index, rows, frames)
        return _calibration_from_records(records, float(quantile), read_novelty_prior(prior_path), min_n=PROFILE_NOVELTY_MIN)


    def pooled_prior(groups: Sequence[Sequence[float]], quantile: float, embedder: str = "tspulse_ci") -> Dict[str, Any]:
        """Conformal radius of every built-in's calibration distances, pooled.

        This is not the median of the per-alert radii. The distances are the
        ones each alert type's own radius came from (validation and
        cross-fitted train cases). An empty pool keeps the cold-start radius
        0.5 and match 0.4.
        """
        flat = [float(value) for group in groups for value in group if np.isfinite(value)]
        if not flat:
            return {"n": 0, "radius": 0.5, "match": 0.4, "embedder": embedder}
        radius = float(conformal_upper(flat, quantile))
        match = min(radius * 0.8, radius) if radius > 0 else 0.0
        return {"n": len(flat), "radius": round(radius, 4), "match": round(match, 4), "embedder": embedder}


    def _frame_names(rows: Sequence[Dict[str, Any]]) -> List[str]:
        """Sorted frame keys so the head's one-hot width does not depend on label order."""
        return sorted({str(row.get("frame") or "") for row in rows if str(row.get("frame") or "")})


    def _model_from_rows(
        profile_id: str,
        rows: Sequence[Dict[str, Any]],
        *,
        use_head: bool,
        weights: Optional[np.ndarray] = None,
        val_rows: Optional[Sequence[Dict[str, Any]]] = None,
        quantile: Optional[float] = None,
        prior_path: Optional[Any] = None,
    ):
        """Index plus a head only when the caller asked and the tier allows one.

        ``val_rows`` selects the built-in calibration (validation against this
        index, pooled with the cross-fitted train rows). Without them the
        radius is the site cross-fit. ``val_nearest`` is the distances the
        pooled prior consumes, and it is not saved.
        """
        from ..config import NOVELTY_QUANTILE
        from .model import ProfileModel, read_novelty_prior

        chosen = float(NOVELTY_QUANTILE if quantile is None else quantile)
        frames = _frame_names(rows)
        index = _index_from_rows(rows, weights)
        head = _fit_profile_head(rows, frames) if use_head and _tier_allows_head(rows) else None
        # The confidence floor needs a head; a kNN-tier model has distance only.
        fit_rows = list(rows) if head is not None else None
        if val_rows is not None:
            records = _val_records(index, val_rows, head=head, frames=frames) + _cross_fit_records(index, fit_rows, frames)
            calibration = _calibration_from_records(records, chosen, read_novelty_prior(prior_path), min_n=1)
            nearest = [float(row["nearest"]) for row in records]
        else:
            calibration = calibrate_site(index, chosen, prior_path=prior_path, rows=fit_rows, frames=frames)
            nearest = []
        model = ProfileModel(profile_id, index, head=head, calibration=calibration, frames=frames, head_passed=head is not None)
        model.val_nearest = nearest
        return model


    def _score_profile_rows(model: Any, rows: Sequence[Dict[str, Any]], tax: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
        """Action, signature, false novelty, and the frame and signature slices."""
        n = len(rows)
        if n == 0:
            return {"n": 0, "action_acc": None, "signature_acc": None, "false_novelty": None, "by_frame": {}, "by_alert": {}}
        decisions = [
            model.decide_profile(row["u"], row["mask"], row.get("frame") or "", exclude=[row["id"]], stats=row.get("s"))
            for row in rows
        ]
        ok_sig = ok_act = novel = 0
        for row, decision in zip(rows, decisions):
            ok_sig += decision.get("signature") == row["signature"]
            ok_act += _action_of(str(decision.get("signature") or ""), tax) == _action_of(row["signature"], tax)
            novel += bool(decision.get("novel"))
        by_frame = _profile_slices([str(row.get("frame") or "") for row in rows], rows, decisions, tax)
        by_alert = _profile_slices([row["signature"] for row in rows], rows, decisions, tax)
        return {
            "n": n,
            "signature_acc": round(ok_sig / n, 4),
            "action_acc": round(ok_act / n, 4),
            "false_novelty": round(novel / n, 4),
            "by_frame": by_frame,
            "by_alert": by_alert,
        }


    def _profile_slices(keys: Sequence[str], rows: Sequence[Dict[str, Any]], decisions: Sequence[Dict[str, Any]], tax: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        """Per-key accuracy. Empty keys are skipped, same as the legacy slice table."""
        grouped: Dict[str, List[int]] = {}
        for i, key in enumerate(keys):
            if key:
                grouped.setdefault(str(key), []).append(i)
        out: Dict[str, Dict[str, Any]] = {}
        for key, idx in grouped.items():
            ok_sig = ok_act = 0
            for i in idx:
                decision = decisions[i]
                truth = rows[i]["signature"]
                ok_sig += decision.get("signature") == truth
                ok_act += _action_of(str(decision.get("signature") or ""), tax) == _action_of(truth, tax)
            count = len(idx)
            out[key] = {"n": count, "signature_acc": round(ok_sig / count, 4), "action_acc": round(ok_act / count, 4)}
        return out


    def _weights_for(settings: Any, profile_id: str, rows: Sequence[Dict[str, Any]], engine: Any) -> np.ndarray:
        """Keep the in-memory slot weights when the channel count still matches.

        Without a cached model (a CLI retrain has no engine) the alert type's
        declared slot weights, so a retrain keeps the weights its shipped index
        carries. Uniform weights only for an unknown alert type or rows embedded
        on another channel list.
        """
        from ..profiles import load_profiles

        channels = int(np.asarray(rows[0]["u"]).shape[0])
        if engine is not None:
            cached = engine.profile_cache.get(profile_id)
            if cached is not None and int(cached.index.channels) == channels and cached.index.weights.shape[0] == channels:
                return np.asarray(cached.index.weights, dtype=np.float32)
        profile = load_profiles(settings).get(str(profile_id))
        if profile is not None:
            declared = _slot_weights(profile, rows)
            if declared is not None:
                return np.asarray(declared, dtype=np.float32)
        return np.ones(channels, dtype=np.float32)


    def cv_accuracies(
        rows: Sequence[Dict[str, Any]],
        tax: Dict[str, Dict[str, Any]],
        *,
        profile_id: str,
        active_head: bool,
        weights: Optional[np.ndarray] = None,
        active_ids: Optional[Sequence[str]] = None,
    ) -> tuple:
        """Mean accuracy of the served recipe and of the candidate, on the same hash folds.

        The candidate is fit on the current train rows outside the fold. The active
        side is fit on the served version's index ids outside that fold, and it uses
        a head only when that version already passed with one. With no new labels
        the two id sets match, so the fold scores tie. An empty served index scores
        0, and the first head can pass. Omit ``active_ids`` to fit both sides on
        the same rows (the comparison a direct caller already pinned).
        """
        from ..config import CV_FOLDS

        active_set = None if active_ids is None else {str(item) for item in active_ids}
        active_parts: List[Dict[str, Any]] = []
        candidate_parts: List[Dict[str, Any]] = []
        for fold in range(int(CV_FOLDS)):
            test = [row for row in rows if fold_of_case(row["id"]) == fold]
            candidate_train = [row for row in rows if fold_of_case(row["id"]) != fold]
            if not test or not candidate_train:
                continue
            if active_set is None:
                active_train = candidate_train
            else:
                active_train = [row for row in rows if row["id"] in active_set and fold_of_case(row["id"]) != fold]
            if active_train:
                active = _model_from_rows(profile_id, active_train, use_head=active_head, weights=weights)
                active_parts.append(_score_profile_rows(active, test, tax))
            else:
                # A cold served model has no correct calls. A candidate above zero passes.
                active_parts.append(
                    {"n": len(test), "action_acc": 0.0, "signature_acc": 0.0, "false_novelty": 0.0, "by_frame": {}, "by_alert": {}}
                )
            candidate = _model_from_rows(profile_id, candidate_train, use_head=True, weights=weights)
            candidate_parts.append(_score_profile_rows(candidate, test, tax))
        return _mean_metrics(active_parts), _mean_metrics(candidate_parts)


    def heldout_scores(
        train_rows: Sequence[Dict[str, Any]],
        held_rows: Sequence[Dict[str, Any]],
        tax: Dict[str, Dict[str, Any]],
        *,
        profile_id: str,
        active_head: bool,
        weights: Optional[np.ndarray] = None,
        active_model: Any = None,
        active_ids: Optional[Sequence[str]] = None,
    ) -> tuple:
        """Score the served model and the candidate on rows the served index did not fit.

        The active side is ``active_model`` as it is loaded for a case. It is not
        refit on the candidate's train rows: that refit made the two sides the
        same model, so a worse candidate tied and was promoted. Rows whose id is
        in the served index are left out. With no served model the before-numbers
        stay empty and a candidate that can score is allowed through.
        """
        del active_head  # The served model already knows whether its head passed.
        skip = {str(item) for item in (active_ids or [])}
        scored = [row for row in held_rows if str(row.get("id") or "") not in skip]
        if active_model is None:
            before = {"n": len(scored), "action_acc": None, "signature_acc": None, "false_novelty": None, "by_frame": {}, "by_alert": {}}
        else:
            before = _score_profile_rows(active_model, scored, tax)
        candidate = _model_from_rows(profile_id, train_rows, use_head=True, weights=weights)
        return before, _score_profile_rows(candidate, scored, tax)


    def load_profile_model(settings: Any, profile_id: str, channels: Optional[int] = None, embedder: Optional[str] = None):
        """The active bundle for this alert type, or None when it has no index yet.

        A bundle whose channel count does not match the case in hand is ignored.
        Those blocks were embedded on a different slot list. A bundle recorded
        with a different embedder is ignored too: ``tspulse_ci`` and ``stats``
        are both 48-d, and they are not the same space (design 2.5).

        ``v0000``'s folder is the channel-independent bundle. A stats query uses
        the shipped ``stats`` sub-bundle instead. Treating that served model as
        missing let a worse candidate promote, because an empty before-score
        is not a comparison.
        """
        import json
        from pathlib import Path

        from .labels import Registry
        from .model import Head, MaskedIndex, ProfileModel

        try:
            pid = _profile_id(profile_id)
        except ValueError:
            return None
        reg = Registry(settings, pid)
        version = reg.current()
        folder = Path(reg.folder(version))
        meta = reg._meta(version)
        recorded = str(meta.get("embedder") or "")
        active = embedder if embedder is not None else str(getattr(settings, "embedder", "") or "")
        if version == "v0000" and recorded and active and recorded != active:
            alt = _shipped_bundle_dir(settings, pid)
            if alt is not None:
                folder = Path(alt)
                meta_path = folder / "meta.json"
                try:
                    loaded_meta = json.loads(meta_path.read_text(encoding="utf-8")) if meta_path.is_file() else {}
                except (OSError, ValueError):
                    loaded_meta = {}
                meta = loaded_meta if isinstance(loaded_meta, dict) else {}
                recorded = str(meta.get("embedder") or "")
        if not (folder / "index.npz").is_file():
            return None
        index = MaskedIndex.load(folder)
        if channels is not None and int(index.channels) != int(channels):
            return None
        head = Head.load(folder) if (folder / "head.npz").is_file() else None
        calibration: Dict[str, Any] = {}
        cal_path = folder / "calibration.json"
        if cal_path.is_file():
            try:
                loaded = json.loads(cal_path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                loaded = {}
            if isinstance(loaded, dict):
                if "prior" in loaded or "profile" in loaded or "frame" in loaded:
                    calibration = loaded
                elif loaded.get("novelty_threshold") is not None:
                    calibration = {"prior": {"n": 0, "radius": float(loaded["novelty_threshold"]), "match": float(loaded.get("match_threshold") or 0.4)}}
        # No recorded embedder (an older index) still loads. A recorded one that
        # is not the space this query was embedded in does not.
        if recorded and active and recorded != active:
            return None
        status = str((meta.get("gate") or {}).get("status") or "")
        frames = list((head.meta or {}).get("frames") or []) if head is not None else list(meta.get("frames") or [])
        model = ProfileModel(pid, index, head=head, calibration=calibration, frames=frames, head_passed=bool(head) and status in {"pass", "forced"})
        model.embedder = recorded or active
        return model


    def _npz_text(blob: Any, key: str, n: int, default: str) -> List[str]:
        """One string per held-out row. A bundle written before ``frame`` existed stays readable."""
        if key not in getattr(blob, "files", []):
            return [default] * n
        out: List[str] = []
        for item in blob[key]:
            if isinstance(item, bytes):
                out.append(item.decode("utf-8"))
            else:
                out.append(str(item))
        if len(out) < n:
            out.extend([default] * (n - len(out)))
        return out[:n]


    def _shipped_bundle_dir(settings: Any, profile_id: str) -> Optional[Path]:
        """Folder of the shipped bundle in this embedder's space.

        ``stats`` prefers ``profiles/<id>/stats`` when that index exists, otherwise
        the main folder when its meta names ``stats``. A ``tspulse_ci`` bundle is
        not readable as stats: the two spaces are not mixed. A site alert type has
        no shipped folder, so this returns None.
        """
        import json

        pid = _profile_id(profile_id)
        root = Path(getattr(settings, "e2e_model_dir", "")) / "profiles" / pid
        embedder = str(getattr(settings, "embedder", "") or "stats")
        folders = [root / "stats", root] if embedder == "stats" else [root]
        for folder in folders:
            if not (folder / "index.npz").is_file():
                continue
            recorded = ""
            meta_path = folder / "meta.json"
            if not meta_path.is_file() and folder.name == "stats":
                meta_path = root / "meta.json"
            if meta_path.is_file():
                try:
                    loaded = json.loads(meta_path.read_text(encoding="utf-8"))
                except (OSError, ValueError):
                    loaded = {}
                if isinstance(loaded, dict):
                    recorded = str(loaded.get("embedder") or "")
            if folder.name == "stats" and not recorded:
                return folder
            if recorded == embedder or not recorded:
                return folder
        return None


    def shipped_rows(settings: Any, profile_id: str) -> List[Dict[str, Any]]:
        """Shipped index rows for a built-in, in the active embedder's space.

        A site alert type, a missing bundle, and a bundle recorded for the other
        embedder are an empty list. The source stays ``synthetic`` when the index
        did not record one.
        """
        from .model import MaskedIndex

        folder = _shipped_bundle_dir(settings, profile_id)
        if folder is None:
            return []
        index = MaskedIndex.load(folder)
        rows: List[Dict[str, Any]] = []
        for i, (block, mask, frame, rec) in enumerate(zip(index.U, index.mask, index.frames, index.records)):
            row = {
                "id": str(rec.get("id") or ""),
                "signature": str(rec.get("signature") or ""),
                "action": str(rec.get("action") or ""),
                "frame": str(frame or rec.get("frame") or ""),
                "u": np.asarray(block, dtype=np.float32),
                "mask": np.asarray(mask, dtype=bool),
                "source": str(rec.get("source") or "synthetic"),
            }
            if index.S is not None:
                row["s"] = np.asarray(index.S[i], dtype=np.float32)
            rows.append(row)
        return rows


    def shipped_heldout(settings: Any, profile_id: str) -> List[Dict[str, Any]]:
        """Rows in the shipped ``heldout.npz``, including frame and source when stored."""
        folder = _shipped_bundle_dir(settings, profile_id)
        if folder is None:
            return []
        path = folder / "heldout.npz"
        if not path.is_file():
            return []
        blob = np.load(path)
        if "U" not in blob.files or "case_id" not in blob.files:
            return []
        blocks = np.asarray(blob["U"], dtype=np.float32)
        n = int(blocks.shape[0])
        mask = np.asarray(blob["mask"], dtype=bool) if "mask" in blob.files else np.ones(blocks.shape[:2], dtype=bool)
        signature = _npz_text(blob, "signature", n, "")
        action = _npz_text(blob, "action", n, "")
        frame = _npz_text(blob, "frame", n, "")
        source = _npz_text(blob, "source", n, "synthetic")
        ids = _npz_text(blob, "case_id", n, "")
        stats_blocks = np.asarray(blob["S"], dtype=np.float32) if "S" in blob.files else None
        rows: List[Dict[str, Any]] = []
        for i in range(n):
            row = {
                "id": ids[i],
                "signature": signature[i],
                "action": action[i],
                "frame": frame[i],
                "u": np.asarray(blocks[i], dtype=np.float32),
                "mask": np.asarray(mask[i], dtype=bool),
                "source": source[i] or "synthetic",
            }
            if stats_blocks is not None:
                row["s"] = stats_blocks[i]
            rows.append(row)
        return rows


    def _source_counts(rows: Sequence[Dict[str, Any]]) -> Dict[str, int]:
        """How many gate rows came from each generator or from an engineer."""
        counts: Dict[str, int] = {}
        for row in rows:
            key = str(row.get("source") or "")
            counts[key] = counts.get(key, 0) + 1
        return counts


    def retrain_profile(settings: Any, profile_id: str, *, force: bool = False, trigger: str = "manual", engine: Any = None) -> Dict[str, Any]:
        """Rebuild one alert type's index, head and calibration, and promote only when the gate passes.

        Train rows are the shipped index plus site labels that are not held out.
        A built-in therefore keeps its head tier when an engineer adds a handful
        of labels. The held-out gate scores the served model, not a refit of it.
        The version is always written. A failed gate leaves it inactive. ``force``
        promotes it and logs ``force_promote`` with this profile id. Another
        profile's pointer is not written.
        """
        import json

        from ..config import CV_MIN_LABELS, HELDOUT_MIN_LABELS
        from .labels import Metrics, Registry
        from .taxonomy import load_taxonomy

        pid = _profile_id(profile_id)
        site_rows = collect_profile_rows(settings, pid)
        shipped = shipped_rows(settings, pid)
        if shipped:
            width = int(np.asarray(shipped[0]["u"]).shape[0])
            # A label embedded in the other space cannot share this index.
            site_rows = [row for row in site_rows if int(np.asarray(row["u"]).shape[0]) == width]
        if not site_rows and not shipped:
            return {"profile": pid, "version": None, "promoted": False, "gate": {"status": "fail", "reasons": ["no labeled embeddings for this alert type"]}, "n_labels": 0}
        held_ids = assign_heldout(settings, pid, [row["id"] for row in site_rows])
        site_train = [row for row in site_rows if row["id"] not in held_ids]
        site_held = [row for row in site_rows if row["id"] in held_ids]
        if not site_train and not shipped:
            site_train = list(site_rows)
            site_held = []
            held_ids = set()
        # An engineer label of a shipped id replaces that shipped row.
        replaced = {row["id"] for row in site_train}
        train_rows = [row for row in shipped if row["id"] not in replaced] + site_train
        heldout_shipped = [row for row in shipped_heldout(settings, pid) if row["id"] not in {item["id"] for item in site_held}]
        gate_rows = list(site_held) + heldout_shipped
        tax = load_taxonomy(getattr(settings, "data_dir", None))
        weights = _weights_for(settings, pid, train_rows, engine)
        width = int(np.asarray(train_rows[0]["u"]).shape[0])
        current = load_profile_model(settings, pid, channels=width)
        active_head = bool(current is not None and current.head_passed)
        active_ids = [str(rec.get("id") or "") for rec in current.index.records] if current is not None else []
        n_labels = len(train_rows) + len(site_held)
        before: Dict[str, Any] = {}
        after: Dict[str, Any] = {}
        reasons: List[str] = []
        scored_rows: List[Dict[str, Any]] = list(train_rows)
        # The under-10 branch is only a site alert type. A built-in already has its shipped rows.
        if not shipped and len(site_rows) < CV_MIN_LABELS:
            status = "none"
            reasons = ["under 10 labels: index and calibration only, no gate"]
            ok = True
            after = _score_profile_rows(_model_from_rows(pid, train_rows, use_head=False, weights=weights), train_rows, tax)
            after["loo_note"] = "index update only; leave-one-out is not a gate below 10 labels"
        elif heldout_shipped or (len(site_rows) >= HELDOUT_MIN_LABELS and site_held):
            skip = set(active_ids)
            scored_rows = [row for row in gate_rows if row["id"] not in skip]
            # A small held-out split is still the held-out gate. CV replaces it only
            # when the served index already holds enough of those rows to leave
            # fewer than 10 that it did not fit.
            if len(scored_rows) < CV_MIN_LABELS and len(gate_rows) >= CV_MIN_LABELS:
                reasons = [f"held-out gate has {len(scored_rows)} rows; cross-validation used"]
                before, after = cv_accuracies(
                    train_rows, tax, profile_id=pid, active_head=active_head, weights=weights, active_ids=active_ids,
                )
                reasons.extend(_cv_reasons(before, after))
                ok = not _cv_reasons(before, after)
                status = "pass" if ok else "fail"
                scored_rows = list(train_rows)
            else:
                before, after = heldout_scores(
                    train_rows, scored_rows, tax,
                    profile_id=pid, active_head=active_head, weights=weights,
                    active_model=current, active_ids=active_ids,
                )
                reasons = profile_gate_reasons(before, after)
                ok = not reasons
                status = "pass" if ok else "fail"
        elif len(site_rows) >= HELDOUT_MIN_LABELS and not site_held and not heldout_shipped:
            status = "pass"
            reasons = ["held-out split is empty"]
            ok = True
        else:
            before, after = cv_accuracies(
                train_rows, tax, profile_id=pid, active_head=active_head, weights=weights, active_ids=active_ids,
            )
            reasons = _cv_reasons(before, after)
            ok = not reasons
            status = "pass" if ok else "fail"
        forced = bool(force) and not ok
        promote = bool(ok or forced)
        if forced:
            status = "forced"
        model = _model_from_rows(pid, train_rows, use_head=True, weights=weights)
        reg = Registry(settings, pid)
        meta = {
            "profile": pid,
            "trigger": trigger,
            "kind": "profile",
            "encoder": reg.current_encoder(),
            "embedder": getattr(settings, "embedder", "stats"),
            "tier": model.tier(),
            "classes": list(model.head.classes) if model.head is not None else [],
            "frames": list(model.frames),
            "n_labels": n_labels,
            "n_train": len(train_rows),
            "n_heldout": len(gate_rows),
            "index_ids": [row["id"] for row in train_rows],
            "gate_rows": {"n": len(scored_rows), "sources": _source_counts(scored_rows)},
            "metrics": {"before": before, "after": after},
            "gate": {"status": status, "reasons": reasons},
            "promoted_by": "",
        }
        version = reg.register(model.head, meta, activate=False)
        folder = reg.folder(version)
        model.index.save(folder)
        (folder / "calibration.json").write_text(json.dumps(model.calibration, indent=2), encoding="utf-8")
        if promote:
            reg.activate(version)
            if engine is not None:
                engine.profile_cache.put(pid, model)
        metrics = Metrics(settings)
        metrics.log("retrain", profile=pid, version=version, trigger=trigger, promoted=promote, gate=status, n_labels=n_labels)
        force_reason = "; ".join(reasons) if forced else ""
        if forced:
            metrics.log("force_promote", profile=pid, version=version, trigger=trigger, reason=force_reason, force_reason=force_reason)
        return {
            "profile": pid,
            "version": version,
            "promoted": promote,
            "gate": {"status": status, "reasons": reasons},
            "before": before,
            "after": after,
            "n_labels": n_labels,
            "n_train": len(train_rows),
            "n_heldout": len(gate_rows),
            "tier": model.tier(),
            "force_reason": force_reason,
        }


    def _ensure_ci_encoder(settings: Any, out: Path) -> Path:
        """Copy the channel-independent weights into ``out/encoder`` when that folder is empty.

        Refuses to overwrite a 14-channel encoder: that folder still has ``classes.json``.
        Move it to ``legacy/encoder`` first. The copy is the classification snapshot,
        one input channel, not a fine-tune.
        """
        import json
        import shutil
        from pathlib import Path

        dest = Path(out) / "encoder"
        dest.mkdir(parents=True, exist_ok=True)
        if (dest / "classes.json").is_file():
            raise RuntimeError(
                f"{dest} is still the 14-channel encoder (classes.json is there). "
                "Move it to legacy/encoder before fitting profile bundles."
            )
        src = Path(getattr(settings, "tspulse_clf_dir", "") or "")
        if not (src / "model.safetensors").is_file():
            raise FileNotFoundError(f"channel-independent weights not found in {src}")
        for name in ("config.json", "model.safetensors"):
            target = dest / name
            if not target.is_file():
                shutil.copy2(src / name, target)
        note = dest / "training.json"
        if not note.is_file():
            note.write_text(
                json.dumps(
                    {
                        "embedder": "tspulse_ci",
                        "source": "models/tspulse/clf",
                        "num_input_channels": 1,
                        "note": "Channel-independent copy of the classification snapshot. Not fine-tuned.",
                    },
                    indent=2,
                ),
                encoding="utf-8",
            )
        return dest


    # Original-generator rows join only these four. Bearing, inlet and lube learn from
    # the alert-type generator alone; the original set has no cases of those alert types
    # that the acceptance table keeps.
    COMBUSTION_ALERTS = (
        "exhaust_cold_spot",
        "combustion_dynamics",
        "exhaust_spread_trip",
        "igv_fuel_control",
    )


    def acceptance_blocklist(path: Optional[Path] = None) -> Dict[str, set]:
        """Case ids and decompressed-CSV sha256 values from the acceptance side-car.

        A missing file is an empty block. The bundle trainer refuses to start in that
        case; this reader only supplies the ids and hashes to drop.
        """
        import json

        from ..config import ROOT

        file = Path(path) if path is not None else Path(ROOT) / "eval" / "acceptance_peralert.jsonl"
        ids: set = set()
        hashes: set = set()
        if not file.is_file():
            return {"ids": ids, "hashes": hashes}
        for line in file.read_text(encoding="utf-8").splitlines():
            if not line.strip():
                continue
            row = json.loads(line)
            if row.get("case_id"):
                ids.add(str(row["case_id"]))
            if row.get("csv_sha256"):
                hashes.add(str(row["csv_sha256"]))
        return {"ids": ids, "hashes": hashes}


    def _blocked_case(case_id: str, digest: str, block: Dict[str, set]) -> bool:
        """True when this file is one of the 320 acceptance rows, by id or by content."""
        return str(case_id) in block["ids"] or (bool(digest) and digest in block["hashes"])


    def _original_role(split: str) -> Optional[str]:
        """Where an original-generator split goes. ``test`` and ``unseen`` go nowhere."""
        if split == "train":
            return "train"
        if split == "val":
            return "val"
        if split in {"variant", "sensorfault"}:
            return "heldout"
        return None


    def _profile_role(split: str) -> Optional[str]:
        """Where an alert-type-generator split goes. ``unseen`` and ``variant`` go nowhere."""
        if split == "train":
            return "train"
        if split == "val":
            return "val"
        if split == "test":
            return "heldout"
        return None


    def _file_digest(path: Path) -> str:
        import hashlib

        from .dataset import decompressed_csv

        return hashlib.sha256(decompressed_csv(path)).hexdigest()


    def _manifest_rows(root: Path) -> List[Dict[str, Any]]:
        from .dataset import load_manifest

        path = Path(root) / "manifest.jsonl"
        if not path.is_file():
            return []
        return list(load_manifest(path.parent))


    def _window_one(path: Path, profile: Any) -> Optional[Dict[str, Any]]:
        """One case's window and mask. A channel-count mismatch is the caller's problem."""
        from ..data import load_csv
        from ..profiles import resolve_tags
        from .features import profile_windows

        case = load_csv(path)
        resolved = resolve_tags(profile, case.df.columns, frame=getattr(case, "frame_type", None) or None)
        feats = profile_windows(case, profile, resolved)
        mask = np.asarray(
            feats.mask if feats.mask is not None else np.ones(feats.x.shape[1], dtype=bool),
            dtype=bool,
        )
        return {
            "x": np.asarray(feats.x, dtype=np.float32),
            "mask": mask,
            "frame": str((feats.meta or {}).get("frame_key") or ""),
        }


    def alert_training_rows(
        settings: Any,
        original_root: Any,
        profile_root: Any,
        pid: str,
        embedder: Any,
    ) -> Dict[str, Any]:
        """Train, validation and held-out rows for one alert type, from both generators.

        Original-generator rows are assigned with ``original_alert_type`` and kept only
        for the four combustion alert types. The alert-type generator contributes its
        own train, val and test. Original ``test`` and every ``unseen`` split are left
        out. Any row whose id or decompressed CSV matches the acceptance side-car is
        left out of every role. The returned scaler is fit on the present training
        channels of every built-in, from both generators, and the rows are already scaled.
        """
        return alert_training_packs(settings, original_root, profile_root, [pid], embedder)[str(pid)]


    def alert_training_packs(
        settings: Any,
        original_root: Any,
        profile_root: Any,
        pids: Sequence[str],
        embedder: Any,
    ) -> Dict[str, Dict[str, Any]]:
        """``alert_training_rows`` for several alert types, embedding each file once.

        The scaler needs every built-in's train rows, so one alert type already
        embeds both generators in full. Calling ``alert_training_rows`` once per
        alert type repeated that work seven times per encoder candidate. The packs
        are the same rows, in the same order, as the one-at-a-time calls.
        """
        from pathlib import Path

        from ..profiles import load_profiles
        from .dataset import _csv_header, decompressed_csv, original_alert_type
        from .model import ChannelScaler

        wanted = [str(pid) for pid in pids]
        block = acceptance_blocklist()
        book = load_profiles()
        out: Dict[str, Dict[str, Any]] = {}
        for pid in wanted:
            if pid in book:
                continue
            wider = load_profiles(settings)
            if wider.get(pid) is None:
                raise ValueError(f"unknown alert type {pid}")
            # A site alert type has no synthetic rows. Retrain adds the engineer labels.
            out[pid] = {"train": [], "val": [], "heldout": [], "scaler": ChannelScaler.fit(np.zeros((0, 48)))}
        if all(pid in out for pid in wanted):
            return out

        original_root = Path(original_root)
        profile_root = Path(profile_root)
        pending: List[Dict[str, Any]] = []

        for row in _manifest_rows(original_root):
            case_id = str(row.get("case_id") or "")
            rel = str(row.get("file") or "")
            path = original_root / rel
            if not path.is_file():
                continue
            digest = _file_digest(path)
            if _blocked_case(case_id, digest, block):
                continue
            role = _original_role(str(row.get("split") or ""))
            if role is None:
                continue
            # The header reader wants the decompressed CSV text. A path is not a header.
            picked = original_alert_type(row, _csv_header(decompressed_csv(path)), book)
            alert = str(picked["alert_type"])
            if alert not in COMBUSTION_ALERTS or alert not in book:
                continue
            pending.append(
                {
                    "id": case_id,
                    "signature": str(row.get("signature") or ""),
                    "action": str(row.get("action") or ""),
                    "split": str(row.get("split") or ""),
                    "role": role,
                    "source": "synthetic_original",
                    "alert_type": alert,
                    "alert_name": str(picked.get("alert_name") or ""),
                    "path": path,
                    "csv_sha256": digest,
                }
            )

        for row in _manifest_rows(profile_root):
            alert = str(row.get("profile") or "")
            if alert not in book or alert == "fuel_gas_heater":
                continue
            case_id = str(row.get("case_id") or "")
            rel = str(row.get("file") or "")
            path = profile_root / rel
            if not path.is_file():
                continue
            digest = _file_digest(path)
            if _blocked_case(case_id, digest, block):
                continue
            role = _profile_role(str(row.get("split") or ""))
            if role is None:
                continue
            pending.append(
                {
                    "id": case_id,
                    "signature": str(row.get("signature") or ""),
                    "action": str(row.get("action") or ""),
                    "split": str(row.get("split") or ""),
                    "role": role,
                    "source": "synthetic_profile",
                    "alert_type": alert,
                    "alert_name": str(row.get("analytic") or ""),
                    "path": path,
                    "csv_sha256": digest,
                }
            )

        # Windows per alert type, then one embedder batch per type. Channel counts differ.
        by_alert: Dict[str, List[Dict[str, Any]]] = {}
        for item in pending:
            by_alert.setdefault(item["alert_type"], []).append(item)
        embedded: List[Dict[str, Any]] = []
        for alert, items in by_alert.items():
            prof = book[alert]
            ready: List[Dict[str, Any]] = []
            width: Optional[int] = None
            for item in items:
                window = _window_one(item["path"], prof)
                if window is None:
                    continue
                channels = int(window["x"].shape[1])
                if width is None:
                    width = channels
                if channels != width:
                    continue
                item["x"] = window["x"]
                item["mask"] = window["mask"]
                item["frame"] = window["frame"]
                ready.append(item)
            if not ready:
                continue
            blocks = np.asarray(
                embedder.embed_channels(
                    np.stack([item["x"] for item in ready]),
                    np.stack([item["mask"] for item in ready]),
                ),
                dtype=np.float32,
            )
            for item, block in zip(ready, blocks):
                item["u"] = np.asarray(block, dtype=np.float32)
                item.pop("x", None)
                item.pop("path", None)
                embedded.append(item)

        present = [item["u"][item["mask"]] for item in embedded if item["role"] == "train" and item["mask"].any()]
        stacked = np.concatenate(present, axis=0) if present else np.zeros((0, int(getattr(embedder, "dim", 48))))
        if stacked.ndim == 2 and len(stacked):
            stacked = stacked[np.isfinite(stacked).all(axis=1)]
        scaler = ChannelScaler.fit(stacked)
        for pid in wanted:
            if pid not in out:
                out[pid] = {"train": [], "val": [], "heldout": [], "scaler": scaler}
        for item in embedded:
            pack = out.get(item["alert_type"])
            if pack is None or pack["scaler"] is not scaler:
                continue
            item["u"] = np.asarray(scaler.transform(item["u"], item["mask"]), dtype=np.float32)
            pack[item["role"]].append(item)
        return out


    def train_profile_bundles(
        settings: Any,
        dataset: Any,
        out: Any,
        *,
        profiles: Optional[Sequence[str]] = None,
        device: str = "cpu",
    ) -> Dict[str, Any]:
        """Fit one shipped bundle per built-in alert type with the channel-independent encoder.

        The train split is the index and the head. The radius is the quantile of
        validation-to-index distances, not leave-one-out on the train rows. The
        shared prior is that same quantile on the distances of every built-in
        pooled together, not the median of their radii. The test split is
        ``heldout.npz``. ``fuel_gas_heater`` is never written. The 14-channel
        bundle is not opened and not rewritten.

        Cases are read from ``dataset/<split>/<profile>/<case>.csv.gz``. A case whose
        channel count differs from the first case of that alert type is skipped.
        """
        import json
        from datetime import datetime
        from pathlib import Path

        from ..config import NOVELTY_QUANTILE
        from ..profiles import channels_hash, compile_channels, load_profiles, resolve_tags
        from ..data import load_csv
        from .dataset import load_manifest
        from .encoder import CIEncoder
        from .features import profile_windows
        from .model import ChannelScaler, channel_weights

        out = Path(out)
        root = Path(dataset)
        _ensure_ci_encoder(settings, out)
        embedder = CIEncoder(path=Path(settings.tspulse_clf_dir), device=device or "cpu")
        if getattr(embedder, "fallback", False):
            raise RuntimeError("refusing to ship a tspulse_ci bundle from the statistical fallback")
        book = load_profiles()
        wanted = list(profiles) if profiles is not None else None
        rows = [row for row in load_manifest(root) if row.get("split") in {"train", "val", "test"}]
        if wanted is not None:
            keep = set(wanted)
            rows = [row for row in rows if row.get("profile") in keep]
        rows = [row for row in rows if row.get("profile") and row.get("profile") != "fuel_gas_heater"]
        by_profile: Dict[str, List[Dict[str, Any]]] = {}
        for row in rows:
            by_profile.setdefault(str(row["profile"]), []).append(row)

        # Raw blocks first. The scaler is fit on present train channels of every profile, then applied.
        raw: Dict[str, List[Dict[str, Any]]] = {}
        weight_of: Dict[str, np.ndarray] = {}
        profile_of: Dict[str, Any] = {}
        present: List[np.ndarray] = []
        for pid, cases in by_profile.items():
            profile = book.get(pid)
            if profile is None:
                print(f"skip {pid}: not a built-in alert type", flush=True)
                continue
            pending: List[Dict[str, Any]] = []
            windows: List[np.ndarray] = []
            masks: List[np.ndarray] = []
            width: Optional[int] = None
            weights = channel_weights(profile, compile_channels(profile))
            print(f"{pid}: windows for {len(cases)} cases", flush=True)
            for index, row in enumerate(cases, start=1):
                path = root / str(row.get("file") or "")
                if not path.is_file():
                    print(f"skip {row.get('case_id')}: missing {path}", flush=True)
                    continue
                case = load_csv(path)
                resolved = resolve_tags(profile, case.df.columns, frame=case.frame_type or None)
                feats = profile_windows(case, profile, resolved)
                mask = np.asarray(feats.mask if feats.mask is not None else np.ones(feats.x.shape[1], dtype=bool), dtype=bool)
                channels = int(feats.x.shape[1])
                if width is None:
                    width = channels
                if channels != width:
                    print(f"skip {row.get('case_id')}: {channels} channels, {pid} is {width}", flush=True)
                    continue
                windows.append(np.asarray(feats.x, dtype=np.float32))
                masks.append(mask)
                pending.append(
                    {
                        "id": str(row.get("case_id") or path.stem),
                        "signature": str(row.get("signature") or ""),
                        "action": str(row.get("action") or ""),
                        "frame": str((feats.meta or {}).get("frame_key") or ""),
                        "split": str(row.get("split") or ""),
                        "source": "synthetic",
                    }
                )
                if index == 1 or index % 25 == 0 or index == len(cases):
                    print(f"  {pid} windows {index}/{len(cases)}", flush=True)
            built: List[Dict[str, Any]] = []
            if pending:
                print(f"  {pid} embedding {len(pending)} cases", flush=True)
                blocks = np.asarray(embedder.embed_channels(np.stack(windows), np.stack(masks)), dtype=np.float32)
                for item, block, mask in zip(pending, blocks, masks):
                    item["u"] = block
                    item["mask"] = mask
                    built.append(item)
                    if item["split"] == "train":
                        present.append(block[mask])
            if not built:
                print(f"skip {pid}: no cases embedded", flush=True)
                continue
            raw[pid] = built
            weight_of[pid] = np.asarray(weights, dtype=np.float32)
            profile_of[pid] = profile

        if not raw:
            raise RuntimeError(f"no alert-type cases embedded from {root}")
        stacked = np.concatenate([chunk for chunk in present if len(chunk)], axis=0) if present else np.zeros((0, 48))
        if stacked.ndim == 2 and len(stacked):
            stacked = stacked[np.isfinite(stacked).all(axis=1)]
        scaler = ChannelScaler.fit(stacked)
        enc_dir = out / "encoder"
        scaler.save(enc_dir / "channel_scaler.npz")

        from .taxonomy import load_taxonomy

        tax = load_taxonomy(getattr(settings, "data_dir", None))
        bundles: Dict[str, Any] = {}
        card_rows: Dict[str, Any] = {}
        pooled: List[List[float]] = []
        for pid, built in raw.items():
            profile = profile_of[pid]
            weights = weight_of[pid]
            scaled: List[Dict[str, Any]] = []
            for item in built:
                vec = scaler.transform(item["u"], item["mask"])
                scaled.append({**item, "u": np.asarray(vec, dtype=np.float32)})
            train_rows = [item for item in scaled if item["split"] == "train"]
            val_rows = [item for item in scaled if item["split"] == "val"]
            test_rows = [item for item in scaled if item["split"] == "test"]
            if not train_rows:
                print(f"skip {pid}: no training rows", flush=True)
                continue
            if weights.shape[0] != int(train_rows[0]["u"].shape[0]):
                weights = np.ones(int(train_rows[0]["u"].shape[0]), dtype=np.float32)
            thresholds = getattr(profile, "thresholds", None) or {}
            quantile = float(thresholds["novelty_quantile"]) if isinstance(thresholds, dict) and thresholds.get("novelty_quantile") is not None else float(NOVELTY_QUANTILE)
            model = _model_from_rows(pid, train_rows, use_head=True, weights=weights, val_rows=val_rows, quantile=quantile)
            pooled.append([float(value) for value in (getattr(model, "val_nearest", []) or [])])
            if hasattr(model, "val_nearest"):
                del model.val_nearest
            val_metrics = _score_profile_rows(model, val_rows, tax)
            bundles[pid] = {
                "model": model,
                "profile": profile,
                "test": test_rows,
                "val": val_metrics,
                "n_train": len(train_rows),
                "n_val": len(val_rows),
                "n_test": len(test_rows),
                "channels": int(train_rows[0]["u"].shape[0]),
            }
            print(
                f"{pid}: tier {model.tier()} train {len(train_rows)} val {len(val_rows)} "
                f"test {len(test_rows)} channels {bundles[pid]['channels']} "
                f"val action {val_metrics.get('action_acc')} signature {val_metrics.get('signature_acc')}",
                flush=True,
            )

        prior = pooled_prior(pooled, float(NOVELTY_QUANTILE))
        (enc_dir / "novelty_prior.json").write_text(json.dumps(prior, indent=2), encoding="utf-8")
        created = datetime.now().isoformat(timespec="seconds")
        for pid, item in bundles.items():
            model = item["model"]
            model.calibration["prior"] = {"n": prior["n"], "radius": prior["radius"], "match": prior["match"]}
            folder = out / "profiles" / pid
            folder.mkdir(parents=True, exist_ok=True)
            if model.head is not None:
                model.head.save(folder)
            model.index.save(folder)
            (folder / "calibration.json").write_text(json.dumps(model.calibration, indent=2), encoding="utf-8")
            test_rows = item["test"]
            if test_rows:
                np.savez_compressed(
                    folder / "heldout.npz",
                    U=np.stack([row["u"] for row in test_rows]).astype(np.float16),
                    mask=np.stack([row["mask"] for row in test_rows]).astype(np.uint8),
                    signature=np.array([row["signature"] for row in test_rows]),
                    case_id=np.array([row["id"] for row in test_rows]),
                    action=np.array([row["action"] for row in test_rows]),
                    frame=np.array([str(row.get("frame") or "") for row in test_rows]),
                    source=np.array([str(row.get("source") or "synthetic") for row in test_rows]),
                )
            profile = item["profile"]
            meta = {
                "profile": pid,
                "profile_rev": int(getattr(profile, "rev", 1) or 1),
                "channels_hash": channels_hash(profile),
                "encoder": "e0000",
                "embedder": "tspulse_ci",
                "tier": model.tier(),
                "classes": list(model.head.classes) if model.head is not None else [],
                "frames": list(model.frames),
                "trigger": "shipped profile bundle (train_profile_bundles)",
                "n_train": item["n_train"],
                "n_val": item["n_val"],
                "n_test": item["n_test"],
                "metrics": {"val": item["val"]},
                "gate": {"status": "pass", "reasons": ["shipped synthetic bundle"]},
                "created": created,
                "promoted_by": "",
            }
            (folder / "meta.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")
            card_rows[pid] = {
                "n_train": item["n_train"],
                "n_val": item["n_val"],
                "n_test": item["n_test"],
                "tier": model.tier(),
                "channels": item["channels"],
                "channels_hash": meta["channels_hash"],
                "val_action_acc": item["val"].get("action_acc"),
                "val_signature_acc": item["val"].get("signature_acc"),
                "embedder": "tspulse_ci",
            }
        card_path = out / "card.json"
        card: Dict[str, Any] = {}
        if card_path.is_file():
            try:
                loaded = json.loads(card_path.read_text(encoding="utf-8"))
            except ValueError:
                loaded = {}
            if isinstance(loaded, dict):
                card = loaded
        card["profiles"] = card_rows
        card_path.write_text(json.dumps(card, indent=2), encoding="utf-8")
        print(f"profile bundles: {len(bundles)} in {out / 'profiles'}  prior radius {prior['radius']}", flush=True)
        return {"profiles": card_rows, "prior": prior}


    def _dataset_label(path: Any) -> str:
        """Folder name only. A home directory must not land in a bundle."""
        text = str(path)
        home = str(Path.home())
        if home and home in text:
            text = text.replace(home, "")
        name = Path(text).name
        return name or "dataset"


    def _manifest_sha256(root: Any) -> str:
        """sha256 of the manifest text. An absent manifest is an empty string."""
        import hashlib

        path = Path(root) / "manifest.jsonl"
        if not path.is_file():
            return ""
        return hashlib.sha256(path.read_bytes()).hexdigest()


    def _bundle_sources(grouped: Dict[str, List[Dict[str, Any]]], original_root: Any, profile_root: Any) -> Dict[str, Any]:
        """Where the rows came from. The acceptance ``test`` split is not a role."""
        roles: Dict[str, int] = {}
        signatures: Dict[str, Dict[str, int]] = {}
        by_source: Dict[str, int] = {}
        for role, rows in grouped.items():
            roles[str(role)] = len(rows)
            counts: Dict[str, int] = {}
            for row in rows:
                sig = str(row.get("signature") or "")
                counts[sig] = counts.get(sig, 0) + 1
                source = str(row.get("source") or "")
                by_source[source] = by_source.get(source, 0) + 1
            signatures[str(role)] = counts
        return {
            "original": _dataset_label(original_root),
            "profile": _dataset_label(profile_root),
            "original_manifest_sha256": _manifest_sha256(original_root),
            "profile_manifest_sha256": _manifest_sha256(profile_root),
            "roles": roles,
            "signatures": signatures,
            "by_source": by_source,
        }


    def _save_alert_bundle(folder: Path, model: Any, held_rows: Sequence[Dict[str, Any]], meta: Dict[str, Any]) -> None:
        """Head, index, calibration, held-out rows and meta for one alert type."""
        import json

        folder.mkdir(parents=True, exist_ok=True)
        if model.head is not None:
            model.head.save(folder)
        model.index.save(folder)
        (folder / "calibration.json").write_text(json.dumps(model.calibration, indent=2), encoding="utf-8")
        if held_rows:
            arrays = {
                "U": np.stack([row["u"] for row in held_rows]).astype(np.float16),
                "mask": np.stack([row["mask"] for row in held_rows]).astype(np.uint8),
                "signature": np.array([row["signature"] for row in held_rows]),
                "case_id": np.array([row["id"] for row in held_rows]),
                "action": np.array([str(row.get("action") or "") for row in held_rows]),
                "frame": np.array([str(row.get("frame") or "") for row in held_rows]),
                "source": np.array([str(row.get("source") or "") for row in held_rows]),
            }
            # The retrain gate scores the served head, which may read the statistical view.
            if all(row.get("s") is not None for row in held_rows):
                arrays["S"] = np.stack([row["s"] for row in held_rows]).astype(np.float16)
            np.savez_compressed(folder / "heldout.npz", **arrays)
        (folder / "meta.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")


    def _saved_case_ids(folder: Path) -> set:
        """Ids in an index and a held-out file. A missing bundle contributes nothing."""
        found: set = set()
        index_text = folder / "index.jsonl"
        if index_text.is_file():
            import json

            for line in index_text.read_text(encoding="utf-8").splitlines():
                if line.strip():
                    found.add(str(json.loads(line).get("id") or ""))
        held = folder / "heldout.npz"
        if held.is_file():
            blob = np.load(held)
            if "case_id" in blob.files:
                for item in blob["case_id"]:
                    text = item.decode("utf-8") if isinstance(item, bytes) else str(item)
                    found.add(text)
        return found


    def _slot_weights(profile: Any, rows: Sequence[Dict[str, Any]]) -> Optional[np.ndarray]:
        """Per-channel distance weights from the alert type's slots (``load`` is 0.5).

        The step-20 trainer and the decider's cold model use these. Without them
        every shipped index weighted the context channel like a process channel.
        None when the rows were embedded on another channel count, so a mismatched
        list never misaligns the weights; the index then stays uniform.
        """
        from ..profiles import compile_channels
        from .model import channel_weights

        weights = channel_weights(profile, compile_channels(profile))
        if rows and int(np.asarray(rows[0]["u"]).shape[0]) != int(weights.shape[0]):
            return None
        return weights


    def _mean_signature(packs: Dict[str, Dict[str, Any]], quantile_of, weights_of=None) -> float:
        """Mean validation signature accuracy across alert types that have a score.

        ``weights_of(pid, rows)`` gives the index weights, so the encoder choice
        scores the same model the trainer ships.
        """
        from .taxonomy import load_taxonomy

        accs: List[float] = []
        for pid, pack in packs.items():
            if not pack["val"]:
                continue
            model = _model_from_rows(
                pid, pack["train"], use_head=True, val_rows=pack["val"], quantile=quantile_of(pid),
                weights=weights_of(pid, pack["train"]) if weights_of is not None else None,
            )
            metrics = _score_profile_rows(model, pack["val"], load_taxonomy(None))
            if metrics.get("signature_acc") is not None:
                accs.append(float(metrics["signature_acc"]))
        if not accs:
            return 0.0
        return float(sum(accs) / len(accs))


    def _rows_for_embedder(settings, original_root, profile_root, pids, embedder) -> Dict[str, Dict[str, Any]]:
        """Train, val and held-out packs for each requested alert type. Each file is embedded once."""
        packs = alert_training_packs(settings, original_root, profile_root, list(pids), embedder)
        return {pid: packs[pid] for pid in pids}


    def _attach_stats(packs: Dict[str, Dict[str, Any]], stats_packs: Dict[str, Dict[str, Any]]) -> None:
        """Give every TS Pulse row its statistical blocks (``s``), matched by id.

        Both passes read the same files through the same windows, so a missing id
        is a bug, not a gap to paper over.
        """
        for pid, pack in packs.items():
            other = stats_packs.get(pid) or {}
            for role in ("train", "val", "heldout"):
                found = {str(row["id"]): row["u"] for row in other.get(role) or []}
                for row in pack.get(role) or []:
                    block = found.get(str(row["id"]))
                    if block is None or np.asarray(block).shape != np.asarray(row["u"]).shape:
                        raise RuntimeError(f"{pid} {role} row {row['id']} has no statistical blocks")
                    row["s"] = np.asarray(block, dtype=np.float32)


    def _install_encoder(chosen: str, settings: Any, out: Path) -> Path:
        """Copy the chosen candidate's weights into ``out/encoder``, replacing what is there.

        The bundles were embedded with exactly these weights, and the decider loads
        this folder. The frozen branch used to copy only into an empty folder, so a
        previous run's fine-tuned weights stayed next to frozen-space bundles.
        ``stats`` has no weights and leaves the folder as it is.
        """
        import shutil

        enc_dir = Path(out) / "encoder"
        enc_dir.mkdir(parents=True, exist_ok=True)
        if chosen == "frozen":
            src = Path(getattr(settings, "tspulse_clf_dir", "") or "")
        elif chosen == "finetuned":
            src = Path(out) / "_candidates" / "finetuned"
        else:
            return enc_dir
        for name in ("config.json", "model.safetensors"):
            if (src / name).is_file():
                shutil.copy2(src / name, enc_dir / name)
        return enc_dir


    def _choose_encoder(scores: Dict[str, Optional[float]]) -> str:
        """Higher validation signature accuracy. A tie or a missing candidate stays frozen."""
        frozen = scores.get("frozen")
        fine = scores.get("finetuned")
        if fine is None:
            return "frozen"
        if frozen is None:
            return "finetuned"
        if float(fine) > float(frozen) + 1e-12:
            return "finetuned"
        return "frozen"


    def train_alert_bundles(
        settings: Any,
        original_root: Any,
        profile_root: Any,
        out: Any,
        device: str = "cpu",
        encoders: Optional[Sequence[str]] = None,
        sidecar: Optional[Path] = None,
        profiles: Optional[Sequence[str]] = None,
    ) -> Dict[str, Any]:
        """Shipped per-alert bundles from both generators.

        Refuses to start when the acceptance side-car is missing or empty. The
        320 case ids are dropped by ``alert_training_rows`` and checked again
        after the files are written. Encoder choice is the mean validation
        signature accuracy of the frozen and fine-tuned candidates. A tie, or a
        fine-tune that did not load, keeps the frozen candidate. The 320 test
        rows are not part of that score. ``stats`` skips both weight folders.
        """
        import json

        from ..config import NOVELTY_QUANTILE, ROOT
        from ..profiles import channels_hash, load_profiles
        from .encoder import StatsEmbedder

        side = Path(sidecar) if sidecar is not None else Path(ROOT) / "eval" / "acceptance_peralert.jsonl"
        if not side.is_file():
            raise FileNotFoundError(f"refusing to train without the acceptance side-car ({side.name})")
        block = acceptance_blocklist(side)
        if not block["ids"]:
            raise FileNotFoundError("refusing to train: the acceptance side-car has no case ids")

        book = load_profiles()
        pids = [str(pid) for pid in (profiles if profiles is not None else book.keys()) if str(pid) in book and not str(pid).startswith("_")]
        out = Path(out)
        out.mkdir(parents=True, exist_ok=True)
        names = [str(item) for item in encoders] if encoders is not None else None
        if names is None:
            names = ["stats"] if str(getattr(settings, "embedder", "") or "stats") == "stats" else ["frozen", "finetuned"]

        def quantile_of(pid: str) -> float:
            thresholds = getattr(book.get(pid), "thresholds", None) or {}
            if isinstance(thresholds, dict) and thresholds.get("novelty_quantile") is not None:
                return float(thresholds["novelty_quantile"])
            return float(NOVELTY_QUANTILE)

        def weights_of(pid: str, rows: Sequence[Dict[str, Any]]) -> Optional[np.ndarray]:
            return _slot_weights(book[pid], rows)

        candidate_rows: Dict[str, Dict[str, Dict[str, Any]]] = {}
        scores: Dict[str, Optional[float]] = {}
        reports: Dict[str, Any] = {}
        if names == ["stats"]:
            packs = _rows_for_embedder(settings, original_root, profile_root, pids, StatsEmbedder())
            candidate_rows["stats"] = packs
            scores["stats"] = _mean_signature(packs, quantile_of, weights_of)
            chosen = "stats"
        else:
            from .encoder import CIEncoder, ci_from_finetuned
            from .labels import legacy_model_dir

            # One statistical pass for every candidate: the heads read both views, and
            # the stats sub-bundles below are built from these same rows.
            stats_packs = _rows_for_embedder(settings, original_root, profile_root, pids, StatsEmbedder())
            work = out / "_candidates"
            if "frozen" in names:
                frozen_dir = Path(getattr(settings, "tspulse_clf_dir", "") or "")
                try:
                    embedder = CIEncoder(path=frozen_dir, device=device, settings=settings)
                    packs = _rows_for_embedder(settings, original_root, profile_root, pids, embedder)
                    _attach_stats(packs, stats_packs)
                    candidate_rows["frozen"] = packs
                    scores["frozen"] = _mean_signature(packs, quantile_of, weights_of)
                    reports["frozen"] = {"available": True, "source": _dataset_label(frozen_dir)}
                except Exception as exc:  # noqa: BLE001 — an unavailable candidate is recorded, not a crash
                    scores["frozen"] = None
                    reports["frozen"] = {"available": False, "reason": type(exc).__name__}
            if "finetuned" in names:
                src = legacy_model_dir(getattr(settings, "e2e_model_dir", out), "encoder")
                dest = work / "finetuned"
                report = ci_from_finetuned(src, dest)
                reports["finetuned"] = {"available": bool(report.get("available")), "source": str(report.get("source") or "")}
                if report.get("available"):
                    embedder = CIEncoder(path=dest, device=device, settings=settings)
                    packs = _rows_for_embedder(settings, original_root, profile_root, pids, embedder)
                    _attach_stats(packs, stats_packs)
                    candidate_rows["finetuned"] = packs
                    scores["finetuned"] = _mean_signature(packs, quantile_of, weights_of)
                else:
                    scores["finetuned"] = None
            chosen = _choose_encoder(scores)
            if chosen not in candidate_rows:
                raise RuntimeError("no encoder candidate produced training rows")

        packs = candidate_rows[chosen]
        scaler = next((pack["scaler"] for pack in packs.values() if pack.get("scaler") is not None), None)
        enc_dir = _install_encoder(chosen, settings, out)
        if scaler is not None:
            scaler.save(enc_dir / "channel_scaler.npz")
            if chosen == "stats":
                # These rows are statistical blocks; the decider reads this file for that space.
                scaler.save(enc_dir / STATS_SCALER_FILE)

        # Fit every alert type first, then pool their validation distances into the
        # prior, then save. Saving inside the first loop stamped each bundle with
        # whatever novelty_prior.json was on disk before this run (the previous
        # encoder's space), because the new prior is only known after the loop.
        pooled: List[List[float]] = []
        written: Dict[str, Any] = {}
        embedder_name = "stats" if chosen == "stats" else "tspulse_ci"
        fitted: Dict[str, Any] = {}
        for pid, pack in packs.items():
            if not pack["train"]:
                continue
            model = _model_from_rows(
                pid, list(pack["train"]), use_head=True, val_rows=pack["val"], quantile=quantile_of(pid),
                weights=weights_of(pid, pack["train"]),
            )
            pooled.append([float(value) for value in (getattr(model, "val_nearest", []) or [])])
            if hasattr(model, "val_nearest"):
                del model.val_nearest
            fitted[pid] = model
        prior = pooled_prior(pooled, float(NOVELTY_QUANTILE), embedder=embedder_name)
        (enc_dir / "novelty_prior.json").write_text(json.dumps(prior, indent=2), encoding="utf-8")
        for pid, model in fitted.items():
            pack = packs[pid]
            train_rows = list(pack["train"])
            model.calibration["prior"] = {key: prior[key] for key in ("n", "radius", "match")}
            profile = book[pid]
            meta = {
                "profile": pid,
                "profile_rev": int(getattr(profile, "rev", 1) or 1),
                "channels_hash": channels_hash(profile),
                "embedder": embedder_name,
                "tier": model.tier(),
                "classes": list(model.head.classes) if model.head is not None else [],
                "frames": list(model.frames),
                "n_train": len(train_rows),
                "n_val": len(pack["val"]),
                "n_heldout": len(pack["heldout"]),
                "gate": {"status": "pass", "reasons": ["shipped alert-type bundle"]},
                "sources": _bundle_sources(
                    {"train": train_rows, "val": list(pack["val"]), "heldout": list(pack["heldout"])},
                    original_root,
                    profile_root,
                ),
            }
            folder = out / "profiles" / pid
            _save_alert_bundle(folder, model, pack["heldout"], meta)
            if chosen == "stats":
                _save_alert_bundle(folder / "stats", model, pack["heldout"], meta)
            written[pid] = {"tier": model.tier(), "n_train": len(train_rows), "n_heldout": len(pack["heldout"])}

        if chosen != "stats":
            stats_packs = {pid: stats_packs[pid] for pid in written}
            stats_fit = next((pack["scaler"] for pack in stats_packs.values() if pack.get("scaler") is not None), None)
            if stats_fit is not None:
                stats_fit.save(enc_dir / STATS_SCALER_FILE)
            # The stats sub-bundles get a prior pooled in the stats space, not the TS Pulse one.
            stats_fitted: Dict[str, Any] = {}
            stats_pooled: List[List[float]] = []
            for pid, pack in stats_packs.items():
                if not pack["train"]:
                    continue
                stats_model = _model_from_rows(
                    pid, pack["train"], use_head=True, val_rows=pack["val"], quantile=quantile_of(pid),
                    weights=weights_of(pid, pack["train"]),
                )
                stats_pooled.append([float(value) for value in (getattr(stats_model, "val_nearest", []) or [])])
                if hasattr(stats_model, "val_nearest"):
                    del stats_model.val_nearest
                stats_fitted[pid] = stats_model
            stats_prior = pooled_prior(stats_pooled, float(NOVELTY_QUANTILE), embedder="stats")
            for pid, stats_model in stats_fitted.items():
                pack = stats_packs[pid]
                stats_model.calibration["prior"] = {key: stats_prior[key] for key in ("n", "radius", "match")}
                stats_profile = book[pid]
                stats_meta = {
                    "profile": pid,
                    "profile_rev": int(getattr(stats_profile, "rev", 1) or 1),
                    "channels_hash": channels_hash(stats_profile),
                    "embedder": "stats",
                    "tier": stats_model.tier(),
                    "classes": list(stats_model.head.classes) if stats_model.head is not None else [],
                    "frames": list(stats_model.frames),
                    "n_train": len(pack["train"]),
                    "n_val": len(pack["val"]),
                    "n_heldout": len(pack["heldout"]),
                    "gate": {"status": "pass", "reasons": ["statistical fallback bundle"]},
                    "sources": _bundle_sources(
                        {"train": list(pack["train"]), "val": list(pack["val"]), "heldout": list(pack["heldout"])},
                        original_root,
                        profile_root,
                    ),
                }
                _save_alert_bundle(out / "profiles" / pid / "stats", stats_model, pack["heldout"], stats_meta)

        note = {
            "embedder": embedder_name,
            "chosen": chosen,
            "device": str(device),
            "candidates": {
                name: {"signature_acc": scores.get(name), **(reports.get(name) or {})}
                for name in scores
            },
            "head_views": sorted(
                {"tspulse_ci+stats" if (model.head is not None and model.head.meta.get("stats_view")) else embedder_name for model in fitted.values()}
            ),
        }
        (enc_dir / "training.json").write_text(json.dumps(note, indent=2), encoding="utf-8")

        banned = set(block["ids"])
        for pid in written:
            for folder in (out / "profiles" / pid, out / "profiles" / pid / "stats"):
                hit = _saved_case_ids(folder) & banned
                if hit:
                    raise RuntimeError(f"{pid} bundle contains {len(hit)} acceptance case ids")
        print(f"alert bundles: {len(written)} chosen {chosen} prior radius {prior.get('radius')}", flush=True)
        return {"profiles": written, "chosen": chosen, "prior": prior, "scores": scores}
# >>>>>>> END sentinel.e2e.train

# =============================================================================
# sentinel.e2e.migrate
# Assign stored labels and cases to alert-type profiles. The legacy logs stay put.
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.migrate sentinel/e2e/migrate.py
if False:  # compiled by exec_section('sentinel.e2e.migrate'); not executed as part of this module
    """Move existing labels and cases onto alert-type profiles.

    The command is ``migrate-profiles``. It also runs once when the engine starts
    in ``profiles`` mode and ``migrations/dynamic_v1.json`` is missing. Legacy mode
    does not run it. Nothing in the legacy label log, ``emb/`` or ``registry/vNNNN``
    is rewritten. A second run only assigns cases the map does not already name,
    and a run with nothing new writes nothing.

    Assignment order, for each latest label and each stored case:

    1. Alert name matches a profile name or keyword (score above 0).
    2. Else the signature belongs to exactly one profile.
    3. Else cases that share a normalised alert name become ``auto_<slug>``.
    4. Else ``general_review``, which keeps today's channel recipe as slots.

    Taught frames become alias keys on the built-in slots they map. A taught alert
    type with no labeled cases becomes an ``alert_<sid>`` stub (no slots, cold).
    """

    # @@future@@ from __future__ import annotations

    import json
    from datetime import datetime
    from pathlib import Path
    from typing import Any, Dict, List, Optional

    MIGRATION_FILE = "dynamic_v1.json"
    _MIGRATING = False
    _MAP_CACHE: Dict[str, Any] = {}


    def migration_path(settings: Any) -> Path:
        """Where the assignment map is stored. It is not the label log."""
        from .labels import e2e_dir

        return e2e_dir(settings) / "migrations" / MIGRATION_FILE


    def _now() -> str:
        return datetime.now().isoformat(timespec="seconds")


    def _read_map(settings: Any) -> Optional[Dict[str, Any]]:
        """The map on disk, or None when this site has not migrated."""
        path = migration_path(settings)
        if not path.is_file():
            return None
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return None
        return data if isinstance(data, dict) else None


    def _cache_put(path: Path, data: Dict[str, Any]) -> None:
        try:
            stamp = path.stat().st_mtime_ns
        except OSError:
            stamp = 0
        _MAP_CACHE[str(path)] = (stamp, data)


    def _map_near(start: Optional[Path]) -> Dict[str, Any]:
        """Find ``migrations/dynamic_v1.json`` by walking up from a data folder.

        The index loader only receives a folder. The map lives next to the rest
        of ``data/e2e``, so a profile index under ``registry/`` still finds it.
        A model folder outside the data dir has no map, and the record is unchanged.
        """
        if start is None:
            return {}
        start = Path(start)
        if start.is_file():
            start = start.parent
        found: Optional[Path] = None
        for i, parent in enumerate([start, *start.parents]):
            candidate = parent / "migrations" / MIGRATION_FILE
            if candidate.is_file():
                found = candidate
                break
            if parent.name == "e2e" or i > 8:
                break
        if found is None:
            return {}
        try:
            stamp = found.stat().st_mtime_ns
        except OSError:
            return {}
        cached = _MAP_CACHE.get(str(found))
        if cached and cached[0] == stamp:
            return cached[1]
        try:
            data = json.loads(found.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return {}
        if not isinstance(data, dict):
            return {}
        _MAP_CACHE[str(found)] = (stamp, data)
        return data


    def migrate_profile_fields(rec: Dict[str, Any], root: Optional[Path] = None) -> Dict[str, Any]:
        """Copy a record and fill ``profile`` / ``profile_rev`` from the migration map.

        The file on disk is left as it was. A record that already names a profile
        keeps that value. A missing map, or a case the map does not mention, is
        returned with the same fields it arrived with.
        """
        if not isinstance(rec, dict):
            return rec
        out = dict(rec)
        if out.get("profile"):
            return out
        cid = str(out.get("case_id") or out.get("id") or "")
        if not cid:
            return out
        data = _map_near(root)
        assigned = (data.get("assignments") or {}).get(cid)
        if not isinstance(assigned, dict):
            return out
        profile = str(assigned.get("profile") or "")
        if not profile:
            return out
        out["profile"] = profile
        out["profile_rev"] = int(assigned.get("rev") or 1)
        return out


    def migration_banner(settings: Any) -> str:
        """The Drop-in line, or "" when this site has no migration map yet."""
        data = _read_map(settings)
        if not data:
            return ""
        return str(data.get("banner") or "")


    def _signature_of(rec: Dict[str, Any]) -> str:
        sig = rec.get("learned_signature")
        if not sig:
            sig = rec.get("signature") or ""
        if isinstance(sig, dict):
            sig = sig.get("learned") or sig.get("signature") or ""
        return str(sig or "")


    def _analytic_of(rec: Dict[str, Any]) -> str:
        return str(rec.get("analytic_entered") or rec.get("analytic") or "")


    def _frame_of(rec: Dict[str, Any]) -> str:
        return str(rec.get("frame_type") or rec.get("frame_key") or rec.get("frame") or "")


    def _csv_for(settings: Any, item: Dict[str, Any]) -> Optional[Path]:
        raw = str(item.get("csv") or "")
        if raw:
            path = Path(raw)
            if path.is_file():
                return path
        alt = Path(settings.cases_dir) / str(item["case_id"]) / "input.csv"
        if alt.is_file():
            return alt
        return None


    def _collect_items(settings: Any) -> Dict[str, Dict[str, Any]]:
        """Latest label per case, plus any stored case the label log does not have.

        A label wins over the case file for the same id. The case still counts
        as a case. Labels carry the csv path the engineer stored.
        """
        from .. import store as case_store
        from .labels import LabelStore

        items: Dict[str, Dict[str, Any]] = {}
        for rec in case_store.list_cases(settings):
            cid = str(rec.get("case_id") or "")
            if not cid:
                continue
            items[cid] = {
                "case_id": cid,
                "analytic": _analytic_of(rec),
                "signature": _signature_of(rec),
                "frame": _frame_of(rec),
                "action": str(rec.get("primary_action") or rec.get("action") or ""),
                "csv": "",
                "is_label": False,
                "is_case": True,
            }
        for cid, lab in LabelStore(settings).latest().items():
            prev = items.get(str(cid), {})
            items[str(cid)] = {
                "case_id": str(cid),
                "analytic": _analytic_of(lab) or prev.get("analytic") or "",
                "signature": _signature_of(lab) or prev.get("signature") or "",
                "frame": _frame_of(lab) or prev.get("frame") or "",
                "action": str(lab.get("action") or prev.get("action") or ""),
                "csv": str(lab.get("csv_path") or ""),
                "is_label": True,
                "is_case": bool(prev.get("is_case")),
            }
        return items


    def _best_name(book: Dict[str, Any], analytic: str) -> Any:
        """The alert type whose canonical name, id or alias is exactly this alert name.

        A keyword is not a name, and tags never choose. A miss returns None so the
        caller can try a signature that one alert type owns, then an auto-created
        alert type, then ``general_review``.
        """
        from ..profiles import alert_type_for_name

        prof = alert_type_for_name(analytic or "", book)
        if prof is None or str(prof.id).startswith("_"):
            return None
        return prof


    def _single_owner(book: Dict[str, Any], signature: str) -> Any:
        """The one profile that lists this signature, or None when it is not unique.

        ``normal`` is on every profile, so it never selects one. ``novel_pattern``
        is not a class.
        """
        if not signature or signature in {"normal", "novel_pattern"}:
            return None
        owners = [prof for prof in book.values() if signature in (prof.signatures or []) and not str(prof.id).startswith("_")]
        if len(owners) == 1:
            return owners[0]
        return None


    def _with_frame_aliases(settings: Any, book: Dict[str, Any]) -> tuple:
        """Copy built-in profiles that gain a taught frame as an alias key.

        Returns the profiles to write and ``{frame: [profile ids]}``. A key that
        is already present is left alone, so a second run does not rewrite the file.
        """
        import copy

        from ..config import load_taught_frames

        frames = load_taught_frames(getattr(settings, "data_dir", None))
        changed: Dict[str, Any] = {}
        added: Dict[str, List[str]] = {}
        for fid, spec in frames.items():
            if not fid or not isinstance(spec, dict):
                continue
            mapping: Dict[str, List[str]] = {}
            for role, tags in (spec.get("roles") or {}).items():
                kept = [str(tag) for tag in tags if str(tag).strip()]
                if kept:
                    mapping[str(role).strip().lower()] = kept
            if spec.get("ring"):
                mapping["ring"] = [str(tag) for tag in spec["ring"] if str(tag).strip()]
            if spec.get("zones"):
                mapping["zones"] = [str(tag) for tag in spec["zones"] if str(tag).strip()]
            if not mapping:
                continue
            for prof in book.values():
                draft = changed.get(prof.id)
                if draft is None:
                    draft = copy.deepcopy(prof)
                touched = False
                for slot in draft.slots:
                    role = str(slot.legacy_role or "")
                    tags = mapping.get(role)
                    if not tags:
                        continue
                    aliases = dict(slot.aliases or {})
                    if fid in aliases:
                        continue
                    aliases[fid] = {"tags": list(tags)}
                    slot.aliases = aliases
                    touched = True
                if not touched:
                    continue
                if prof.id not in changed:
                    draft.rev = int(draft.rev or 1) + 1
                    draft.source = "migration"
                    changed[prof.id] = draft
                added.setdefault(fid, [])
                if prof.id not in added[fid]:
                    added[fid].append(prof.id)
        for pid, prof in changed.items():
            book[pid] = prof
        return changed, added


    def _groups_for(columns: List[str]) -> List[tuple]:
        """Turn one header into slot skeletons: base id, role, legacy role, tags."""
        from ..data import map_roles

        roles, ring, zones = map_roles(columns)
        claimed = set()
        groups = []
        if len(ring) >= 1:
            kind = "ring" if len(ring) >= 2 else "process"
            groups.append(("exh_tc", kind, "ring", list(ring)))
            claimed.update(tag.lower() for tag in ring)
        if len(zones) >= 1:
            kind = "ring" if len(zones) >= 2 and not ring else ("bank" if len(zones) >= 2 else "process")
            groups.append(("exh_zone", kind, "zones", list(zones)))
            claimed.update(tag.lower() for tag in zones)
        if roles.get("load"):
            groups.append(("load", "context", "load", list(roles["load"][:1])))
            claimed.update(tag.lower() for tag in roles["load"][:1])
        for role, tags in roles.items():
            if role == "load" or not tags:
                continue
            if role == "trip":
                kind = "flag"
            elif role in {"vibration", "dynamics"} and len(tags) >= 2:
                kind = "bank"
            else:
                kind = "process"
            groups.append((role, kind, role, list(tags)))
            claimed.update(tag.lower() for tag in tags)
        for col in columns:
            if col.lower() in claimed:
                continue
            groups.append((col, "process", "", [col]))
            claimed.add(col.lower())
        return groups


    def _known(settings: Any) -> set:
        from ..profiles import _known_signatures

        return set(_known_signatures(getattr(settings, "data_dir", None)))


    def _docs_for(settings: Any, names: List[str]) -> List[str]:
        """User documents whose analytics tag is this alert name."""
        from ..analytics import normalise
        from .taxonomy import slug
        from .teach import list_documents

        wanted_slug = {slug(name) for name in names if name}
        wanted_norm = {normalise(name) for name in names if name}
        found = []
        for doc in list_documents(settings):
            tags = list(doc.get("analytics") or [])
            if any(tag in wanted_slug or normalise(str(tag)) in wanted_norm for tag in tags):
                found.append(f"{doc['id']}.md")
        return found


    def _signature_list(settings: Any, signatures: List[str]) -> List[str]:
        known = _known(settings)
        out = ["normal"]
        for sig in signatures:
            if sig and sig not in out and sig in known and sig != "novel_pattern":
                out.append(sig)
        return out


    def _auto_id(name: str, used: set) -> str:
        from .taxonomy import slug

        base = (slug(name) or "alert")[:42]
        pid = f"auto_{base}"[:48]
        n = 2
        while pid in used or len(pid) < 2:
            suffix = f"_{n}"
            pid = (f"auto_{base}")[: 48 - len(suffix)] + suffix
            n += 1
        used.add(pid)
        return pid


    def _columns_by_frame(settings: Any, group: List[Dict[str, Any]]) -> Dict[str, List[str]]:
        from ..data import _TS_NAMES, load_csv

        out: Dict[str, List[str]] = {}
        for item in group:
            path = _csv_for(settings, item)
            if path is None:
                continue
            try:
                case = load_csv(path, frame=item.get("frame") or None)
            except Exception:
                continue
            frame = item.get("frame") or getattr(case, "frame_type", "") or "*"
            bucket = out.setdefault(str(frame or "*"), [])
            for col in case.df.columns:
                text = str(col).strip()
                if text and text.lower() not in _TS_NAMES and text not in bucket:
                    bucket.append(text)
        return out


    def _auto_profile(settings: Any, pid: str, title: str, group: List[Dict[str, Any]]) -> Any:
        """A needs-review profile whose slots are the union of the group's headers."""
        from ..profiles import Profile, Slot, _slot_id

        by_frame = _columns_by_frame(settings, group)
        union: List[str] = []
        seen = set()
        for cols in by_frame.values():
            for col in cols:
                if col.lower() not in seen:
                    seen.add(col.lower())
                    union.append(col)
        names = []
        signatures = []
        for item in group:
            if item.get("analytic") and item["analytic"] not in names:
                names.append(item["analytic"])
            if item.get("signature"):
                signatures.append(item["signature"])
        ids: set = set()
        slots = []
        for base, role, legacy, tags in _groups_for(union):
            sid = _slot_id(str(base).lower().replace(" ", "_"), ids)
            aliases: Dict[str, Any] = {"*": {"tags": list(tags)}}
            for frame, cols in by_frame.items():
                picked = [col for col in cols if col in tags]
                if frame and frame != "*" and picked:
                    aliases[frame] = {"tags": picked}
            slots.append(
                Slot(
                    id=sid,
                    role=role,
                    label=str(base).replace("_", " "),
                    required=False,
                    aliases=aliases,
                    legacy_role=legacy,
                    health=role in {"ring", "bank"},
                    load_fit=bool(role == "process" and legacy in {"fuel", "igv"}),
                )
            )
        if slots:
            prefer = next((slot for slot in slots if slot.role in {"context", "ring"}), slots[0])
            prefer.required = True
        return Profile(
            id=pid,
            name=title,
            description=f"Created from stored cases named {title}.",
            match={"names": names or [title], "keywords": []},
            slots=slots,
            include_other=True,
            signatures=_signature_list(settings, signatures),
            analyzer="generic",
            docs=_docs_for(settings, names or [title]),
            source="migration",
            needs_review=True,
            rev=1,
        )


    def _general_profile(settings: Any, signatures: List[str]) -> Any:
        """Today's 14-channel recipe as slots, so a case with no alert name is not dropped."""
        from ..profiles import Profile, Slot, _ring_alias, _star

        rows = [
            ("load", "context", "unit load", "MW", True, "load", False, False, _star("load")),
            ("exh_tc", "ring", "exhaust temperature", "C", False, "ring", True, False, _ring_alias()),
            ("spread", "process", "exhaust spread", "C", False, "spread", False, False, _star("spread")),
            ("egt_avg", "process", "average exhaust temperature", "C", False, "egt_avg", False, False, _star("egt_avg")),
            ("dyn", "bank", "combustion dynamics", "psi", False, "dynamics", True, False, _star("dynamics")),
            ("vib", "bank", "vibration", "mm/s", False, "vibration", True, False, _star("vibration")),
            ("fuel", "process", "fuel flow", "kg/s", False, "fuel", False, True, _star("fuel")),
            ("igv", "process", "IGV position", "deg", False, "igv", False, True, _star("igv")),
            ("trip", "flag", "trip", "", False, "trip", False, False, _star("trip")),
        ]
        slots = []
        for sid, role, label, unit, required, legacy, health, load_fit, aliases in rows:
            slots.append(
                Slot(
                    id=sid,
                    role=role,
                    label=label,
                    unit=unit,
                    required=required,
                    legacy_role=legacy,
                    health=health,
                    load_fit=bool(load_fit and role == "process"),
                    aliases=aliases,
                )
            )
        return Profile(
            id="general_review",
            name="General review",
            description="Cases with no alert name. Slots follow the channel recipe the 14-channel path already uses.",
            match={"names": [], "keywords": []},
            slots=slots,
            include_other=True,
            signatures=_signature_list(settings, signatures),
            analyzer="generic",
            docs=[],
            source="migration",
            needs_review=True,
            rev=1,
        )


    def _alert_stubs(settings: Any, book: Dict[str, Any], labeled: set) -> List[Any]:
        """Taught alert types that have a document and no labeled case. They stay cold."""
        from ..profiles import Profile
        from .teach import list_documents

        stubs = []
        seen = set()
        for doc in list_documents(settings):
            if str(doc.get("source") or "") != "alert type":
                continue
            for sid in doc.get("signatures") or []:
                sid = str(sid or "")
                if not sid or sid in labeled or sid in seen:
                    continue
                if any(sid in (prof.signatures or []) for prof in book.values()):
                    continue
                pid = f"alert_{sid}"[:48]
                if pid in book or pid in seen:
                    continue
                seen.add(sid)
                stubs.append(
                    Profile(
                        id=pid,
                        name=str(doc.get("title") or sid),
                        description="Taught alert type with no labeled cases yet. Add a sample CSV before this leaves review.",
                        match={"names": [str(doc.get("title") or sid)], "keywords": []},
                        slots=[],
                        include_other=False,
                        signatures=_signature_list(settings, [sid]),
                        analyzer="generic",
                        docs=[f"{doc['id']}.md"],
                        source="migration",
                        needs_review=True,
                        rev=1,
                    )
                )
        return stubs


    def _banner(n_labels: int, n_cases: int) -> str:
        if n_labels == 0 and n_cases == 0:
            return "Alert-type profiles are ready. No stored labels needed a migration."
        return f"Migrated {n_labels} labels and {n_cases} cases into alert-type profiles."


    def _assign(settings: Any, book: Dict[str, Any], items: Dict[str, Dict[str, Any]], already: Dict[str, Any]) -> Dict[str, Any]:
        """Decide a profile for every item the map does not already name."""
        from ..analytics import normalise

        assignments = dict(already)
        fresh: Dict[str, Dict[str, Any]] = {}
        named: Dict[str, List[Dict[str, Any]]] = {}
        general_items: List[Dict[str, Any]] = []
        for cid in sorted(items):
            if cid in assignments:
                continue
            item = items[cid]
            chosen = _best_name(book, item.get("analytic") or "")
            if chosen is not None:
                fresh[cid] = {"profile": chosen.id, "rule": "name", "rev": int(chosen.rev or 1)}
                continue
            owner = _single_owner(book, item.get("signature") or "")
            if owner is not None:
                fresh[cid] = {"profile": owner.id, "rule": "signature", "rev": int(owner.rev or 1)}
                continue
            analytic = item.get("analytic") or ""
            if normalise(analytic):
                named.setdefault(normalise(analytic), []).append(item)
            else:
                general_items.append(item)
        created = []
        used = set(book)
        for key, group in named.items():
            title = next((item["analytic"] for item in group if item.get("analytic")), key)
            pid = _auto_id(title, used)
            prof = _auto_profile(settings, pid, title, group)
            book[pid] = prof
            created.append(prof)
            for item in group:
                fresh[item["case_id"]] = {"profile": pid, "rule": "auto", "rev": 1}
        if general_items:
            if "general_review" in book:
                prof = book["general_review"]
            else:
                prof = _general_profile(settings, [item.get("signature") or "" for item in general_items])
                book[prof.id] = prof
                created.append(prof)
            for item in general_items:
                fresh[item["case_id"]] = {"profile": prof.id, "rule": "general", "rev": int(prof.rev or 1)}
        assignments.update(fresh)
        return {"assignments": assignments, "fresh": fresh, "created": created}


    def _save_profile(settings: Any, prof: Any) -> None:
        from ..profiles import save_profile_file

        dest = Path(settings.profiles_dir) / f"{prof.id}.json"
        save_profile_file(prof, dest, data_dir=getattr(settings, "data_dir", None))


    def _embed_label(settings: Any, item: Dict[str, Any], prof: Any) -> Optional[Dict[str, Any]]:
        """Write ``emb2`` for one label. The returned row is in the active embedder's space.

        Both vectors are stored. A failure here lists the case as not re-embeddable
        and leaves the label log untouched.
        """
        import numpy as np

        from ..data import load_csv
        from ..profiles import channels_hash, compile_channels, resolve_tags
        from .encoder import get_embedder
        from .labels import ProfileEmbeddings, Registry

        path = _csv_for(settings, item)
        if path is None:
            return None
        case = load_csv(path, frame=item.get("frame") or None)
        resolved = resolve_tags(prof, case.df.columns, frame=case.frame_type or item.get("frame") or None)
        from .features import profile_windows

        feats = profile_windows(case, prof, resolved)
        mask = feats.mask if feats.mask is not None else np.ones(feats.x.shape[1], dtype=bool)
        stats_emb = get_embedder("stats")
        stats = np.asarray(stats_emb.embed_channels(feats.x, mask), dtype=np.float32)
        pulse = np.zeros_like(stats)
        try:
            pulse_emb = get_embedder("tspulse_ci", settings=settings)
            if not getattr(pulse_emb, "fallback", False):
                pulse = np.asarray(pulse_emb.embed_channels(feats.x, mask), dtype=np.float32)
        except Exception:
            pulse = np.zeros_like(stats)
        encoder = Registry(settings).current_encoder()
        ProfileEmbeddings(settings).save(
            prof.id,
            item["case_id"],
            pulse,
            stats,
            mask,
            [spec.id for spec in compile_channels(prof, resolved)],
            channels_hash(prof),
            encoder,
            resolved,
        )
        active = str(getattr(settings, "embedder", "stats") or "stats")
        vector = pulse if active == "tspulse_ci" and np.any(pulse) else stats
        if active == "tspulse_ci" and not np.any(pulse):
            return None
        # The index stores the same scaled blocks a later quick retrain would rebuild.
        from .train import _scale_profile_vector

        vector = _scale_profile_vector(settings, np.asarray(vector, dtype=np.float32), mask)
        return {
            "id": item["case_id"],
            "signature": item.get("signature") or "normal",
            "action": item.get("action") or "",
            "frame": str(getattr(resolved, "frame_key", "") or item.get("frame") or ""),
            "u": np.asarray(vector, dtype=np.float32),
            "mask": np.asarray(mask, dtype=bool).reshape(-1),
            "source": "engineer",
            "embedder": active if active == "stats" or np.any(pulse) else "stats",
        }


    def _shipped_index(settings: Any, pid: str) -> bool:
        """True when the shipped bundle already has this alert type's index.

        Migration must not replace that head with a site index that has none.
        Site labels for a shipped alert type wait for the first quick retrain.
        """
        return (Path(getattr(settings, "e2e_model_dir", "")) / "profiles" / pid / "index.npz").is_file()


    def _save_site_index(settings: Any, pid: str, rows: List[Dict[str, Any]], embedder: str) -> None:
        """Index and calibration only. Site-only profiles do not get a head here."""
        if not rows or _shipped_index(settings, pid):
            return
        from .labels import Registry
        from .train import _model_from_rows

        model = _model_from_rows(pid, rows, use_head=False)
        reg = Registry(settings, pid)
        version = reg.register(
            None,
            {
                "profile": pid,
                "trigger": "migrate to alert-type profiles",
                "kind": "profile",
                "encoder": reg.current_encoder(),
                "embedder": embedder,
                "tier": model.tier(),
                "classes": [],
                "gate": {
                    "status": "none",
                    "reasons": ["migration builds the index only; the first quick retrain fits a head"],
                },
                "promoted_by": "",
            },
            activate=True,
        )
        folder = reg.folder(version)
        model.index.save(folder)
        (folder / "calibration.json").write_text(json.dumps(model.calibration, indent=2), encoding="utf-8")


    def _snapshot(settings: Any, action: str) -> None:
        from .teach import TeachRegistry

        TeachRegistry(settings).snapshot(action, action)


    def _new_work(settings: Any, existing: Dict[str, Any], items: Dict[str, Dict[str, Any]], book: Dict[str, Any]) -> bool:
        """True when a case, a taught frame or a stub is not in the map yet."""
        assigned = existing.get("assignments") or {}
        if any(cid not in assigned for cid in items):
            return True
        from ..config import load_taught_frames

        frames = load_taught_frames(getattr(settings, "data_dir", None))
        recorded = existing.get("frame_aliases_added") or {}
        for fid in frames:
            if fid and fid not in recorded:
                # The frame may have been taught after the migration. Confirm the
                # alias is actually missing before treating it as new work.
                for prof in book.values():
                    for slot in prof.slots:
                        if fid not in (slot.aliases or {}) and slot.legacy_role:
                            spec = frames.get(fid) or {}
                            roles = {str(k).lower() for k in (spec.get("roles") or {})}
                            if spec.get("ring"):
                                roles.add("ring")
                            if spec.get("zones"):
                                roles.add("zones")
                            if slot.legacy_role in roles:
                                return True
        labeled = {item.get("signature") or "" for item in items.values() if item.get("is_label")}
        for stub in _alert_stubs(settings, book, labeled):
            if stub.id not in book:
                return True
        return False


    def _merge_frames(previous: Any, added: Any) -> Dict[str, List[str]]:
        """Keep earlier frame aliases and append profiles a later run touched."""
        merged: Dict[str, List[str]] = {}
        for fid, pids in (previous or {}).items():
            merged[str(fid)] = [str(pid) for pid in (pids or [])]
        for fid, pids in (added or {}).items():
            bucket = list(merged.get(str(fid)) or [])
            for pid in pids or []:
                if str(pid) not in bucket:
                    bucket.append(str(pid))
            merged[str(fid)] = bucket
        return merged


    def migrate_profiles(settings: Any, dry_run: bool = False) -> Dict[str, Any]:
        """Assign labels and cases. ``dry_run`` returns the plan and writes nothing.

        The first real run stores a Teach snapshot from before the write, then one
        from after it. Rollback to the first snapshot removes the profiles and the map.
        """
        from ..config import FEATURE_VERSION
        from ..profiles import load_profiles
        from .labels import LabelStore, Registry

        existing = _read_map(settings) or {}
        items = _collect_items(settings)
        book = load_profiles(settings=settings)
        if existing and not dry_run and not _new_work(settings, existing, items, book):
            return existing
        changed, frame_added = _with_frame_aliases(settings, book)
        plan = _assign(settings, book, items, dict(existing.get("assignments") or {}))
        labeled_sigs = {item.get("signature") or "" for item in items.values() if item.get("is_label")}
        stubs = _alert_stubs(settings, book, labeled_sigs)
        for stub in stubs:
            if stub.id not in book:
                book[stub.id] = stub
                plan["created"].append(stub)
        created_ids = [prof.id for prof in plan["created"]]
        # Frame-alias files are overrides, not new alert types.
        n_labels = sum(1 for item in items.values() if item.get("is_label"))
        n_cases = sum(1 for item in items.values() if item.get("is_case"))
        record = {
            "version": 1,
            "time": _now(),
            "feature_version": int(FEATURE_VERSION),
            "encoder": Registry(settings).current_encoder(),
            "assignments": plan["assignments"],
            "created_profiles": sorted(set(list(existing.get("created_profiles") or []) + created_ids)),
            "frame_aliases_added": _merge_frames(existing.get("frame_aliases_added"), frame_added),
            "not_reembeddable": list(existing.get("not_reembeddable") or []),
            "counts": {"labels": n_labels, "cases": n_cases},
            "banner": _banner(n_labels, n_cases),
        }
        if dry_run:
            record["dry_run"] = True
            return record
        first = not existing
        if first:
            _snapshot(settings, "before profile migration")
        for prof in changed.values():
            _save_profile(settings, prof)
        for prof in plan["created"]:
            _save_profile(settings, prof)
        fresh = plan["fresh"]
        not_re = list(record["not_reembeddable"])
        rows: Dict[str, List[Dict[str, Any]]] = {}
        embedder = str(getattr(settings, "embedder", "stats") or "stats")
        for cid, assigned in fresh.items():
            item = items.get(cid)
            if item is None or not item.get("is_label"):
                continue
            prof = book.get(assigned["profile"])
            if prof is None or not prof.slots:
                if _csv_for(settings, item) is None:
                    not_re.append(cid)
                continue
            try:
                row = _embed_label(settings, item, prof)
            except Exception:
                row = None
            if row is None:
                not_re.append(cid)
                continue
            rows.setdefault(assigned["profile"], []).append(row)
            embedder = str(row.get("embedder") or embedder)
        for pid, group in rows.items():
            _save_site_index(settings, pid, group, embedder)
        record["not_reembeddable"] = sorted(set(not_re))
        # load_profiles rewrites this file whenever the folder exists. Write it on the
        # first run too, so a second run with nothing new leaves the same bytes.
        profiles_dir = Path(getattr(settings, "profiles_dir", ""))
        if profiles_dir.is_dir():
            invalid = profiles_dir / "_invalid.json"
            if not invalid.is_file():
                invalid.write_text("[]\n", encoding="utf-8")
        path = migration_path(settings)
        path.parent.mkdir(parents=True, exist_ok=True)
        text = json.dumps(record, indent=2, default=str) + "\n"
        path.write_text(text, encoding="utf-8")
        _cache_put(path, record)
        if first:
            _snapshot(settings, "migrate to alert-type profiles")
        return record


    def ensure_migrated(settings: Any) -> str:
        """Run the migration once, and only when ``e2e_mode`` is ``peralert``.

        Legacy mode returns immediately, so the suite does not write a map while
        the default is still the 14-channel path. A second call is a no-op.
        """
        global _MIGRATING
        if _MIGRATING:
            return ""
        if getattr(settings, "e2e_mode", "legacy") != "peralert":
            return ""
        if migration_path(settings).is_file():
            return migration_banner(settings)
        _MIGRATING = True
        try:
            result = migrate_profiles(settings, dry_run=False)
        finally:
            _MIGRATING = False
        return str(result.get("banner") or "")
# >>>>>>> END sentinel.e2e.migrate


# =============================================================================
# sentinel.e2e.writer
# What the LLM sees on the learned path: evidence, residual, process steps, and the cross-check.
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.writer sentinel/e2e/writer.py
if False:  # compiled by exec_section('sentinel.e2e.writer'); not executed as part of this module
    """LLM report writer for the learned path (Gemma 4 12B by default, via llm_runtime).

    The model gets the classifier output, the top-k similar labeled cases (with the engineers' notes and
    one-sentence "why"), the novelty status, the data excursions, a second independent TS Pulse view
    (reconstruction residuals: onset order, physical sizes, neighbour coherence, load / IGV / fuel), the
    matching process / technical-background sections (knowledge.retrieve_learned, token-capped), the case
    notes and the rule path's shadow result. It returns a JSON object (schema-constrained) with the
    signature, corrective action, urgency, the narrative sections, a residual cross-check verdict and a
    walk through the retrieved process steps.

    Checks before use: valid JSON within the schema enums; the action is named in the rationale;
    numbers in every text field (narrative, concerns, residual reason, process steps) trace back to the
    prompt; a novel pattern is never forced into a class; a changed action (vs the classifier) is
    flagged; the LLM's residual verdict is compared with the deterministic residual cross-check
    (residual.cross_check) and any contradiction lowers confidence and sets needs_human; process steps
    must exist when process knowledge was given and must name steps from it.
    """

    # @@future@@ from __future__ import annotations

    import json
    import re
    from typing import Any, Dict, List, Tuple

    from ..analytics.base import ACTIONS, CAUSES, URGENCY
    from ..knowledge import approx_tokens
    from ..llm import check_output
    from .report import SITE_CHECKS, excursion_text
    from .residual import PATTERN_TEXT, describe
    from .taxonomy import NOVEL
    from .taxonomy import info as sig_info

    SYSTEM = """You are Sentinel GT AI, a gas turbine remote monitoring assistant writing a Tier 2 site report for a Tier 2 remote monitoring engineer, who reviews it before release.
    You receive: the output of a learned time-series classifier (TS Pulse), the most similar engineer-labeled past cases, a novelty check, the largest data excursions, a second independent view of the data (TS Pulse reconstruction residuals per sensor: which channels deviated first, when, by how much, and whether neighbouring sensors followed), the site's process steps for this kind of case, the case notes and the result of an independent rule-based analysis (shadow).
    Decide the signature and corrective action, then write the narrative.
    Rules:
    - Use ONLY facts given. Copy numbers exactly with units. Never write a number that is not in the input. Do not invent values, times or part numbers.
    - Default to the classifier's signature. Change it only if the notes, the similar labeled cases or a clear residual contradiction justify it, and say why in "concerns".
    - If the case is marked NOVEL, set signature to "novel_pattern" and action to "escalate". Never force a novel case into a known class.
    - The primary action must be the action listed for the chosen signature unless the notes clearly require otherwise.
    - Cite the most similar labeled case by its id and distance in "why".
    - Cross-check: compare the RESIDUAL VIEW with the expected residual pattern of the classifier's signature (SIGNATURE CATALOGUE). Set "residual_consistency" to "supports", "contradicts" or "inconclusive" and give the deciding fact in "residual_reason". Example: one TC stepping alone while its neighbours stay flat contradicts cold_spot_hardware and points to tc_sensor_fault.
    - If the residuals contradict the classifier: say so in "concerns" naming the channels; the app lowers confidence and sends the case to a human.
    - "process_steps": walk the PROCESS STEPS given, in order, one entry per step (at most 6): "step" = the step name as written there, "finding" = one short sentence on what this case's data shows for that step, or "not in the data". Empty list if no process steps are given.
    - If the rule-based analysis disagrees, say what it found and why you still prefer your answer (or not) in "why".
    - "concerns": empty string if nothing contradicts the decision; otherwise one or two sentences.
    - When the prompt contains ALERT TYPE AND TAGS, that list is authoritative. Do not reason about a tag shown as missing.
    - Plain professional engineering English. what_happened <= 80 words, why <= 110 words, action_rationale <= 60 words, residual_reason <= 40 words, each step finding <= 25 words.
    Respond with one JSON object only."""

    # Prompt size: the total (system + user) is kept within this many tokens; process knowledge is trimmed
    # first, then the residual detail, then similar-case notes (see build_prompt).
    PROMPT_TOKEN_BUDGET = 3800
    KNOWLEDGE_TOKENS = 700
    MAX_STEPS = 6
    OUTPUT_TOKENS = 1300


    def schema(signatures: List[str]) -> Dict[str, Any]:
        """Function schema."""
        return {
            "type": "object",
            "properties": {
                "signature": {"type": "string", "enum": signatures + [NOVEL]},
                "primary_action": {"type": "string", "enum": list(ACTIONS)},
                "urgency": {"type": "string", "enum": list(URGENCY)},
                "escalate": {"type": "boolean"},
                # No minLength / maxLength / maxItems: llama.cpp expands bounds into huge grammar repetitions
                # ("number of rules ... exceeds sane defaults") and the grammar fails. Lengths and counts are
                # asked for in the prompt and enforced in code (_fit, _steps).
                "what_happened": {"type": "string"},
                "why": {"type": "string"},
                "action_rationale": {"type": "string"},
                "residual_consistency": {"type": "string", "enum": ["supports", "contradicts", "inconclusive"]},
                "residual_reason": {"type": "string"},
                "process_steps": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {"step": {"type": "string"}, "finding": {"type": "string"}},
                        "required": ["step", "finding"],
                        "additionalProperties": False,
                    },
                },
                "concerns": {"type": "string"},
            },
            "required": ["signature", "primary_action", "urgency", "escalate", "what_happened", "why", "action_rationale",
                         "residual_consistency", "residual_reason", "process_steps", "concerns"],
            "additionalProperties": False,
        }


    LIMITS = {"what_happened": 900, "why": 1100, "action_rationale": 700, "concerns": 500, "residual_reason": 400}


    def _fit(text: str, limit: int) -> str:
        """Trim to the limit at a sentence boundary (the grammar no longer bounds lengths)."""
        text = (text or "").strip()
        if len(text) <= limit:
            return text
        cut = text[:limit]
        end = max(cut.rfind(". "), cut.rfind(".\n"))
        return (cut[: end + 1] if end > limit // 2 else cut.rstrip() + "…").strip()


    def _sensor_sort(name: str) -> Tuple[int, str]:
        """Trailing sensor number, so a ring is shown from the first tag to the last."""
        m = re.search(r"(\d+)\D*$", str(name))
        return (int(m.group(1)) if m else 10**9, str(name))


    def _slot_line(slot: Dict[str, Any]) -> str:
        """One alert-type tag line. A ring or bank with several tags is shown as first .. last."""
        tags = list(slot.get("tags") or [])
        role = slot.get("role") or "process"
        bits = [role]
        if slot.get("unit"):
            bits.append(str(slot["unit"]))
        if slot.get("load_fit"):
            bits.append("load-fitted")
        if slot.get("status") != "present" or not tags:
            shown = "not in this file" if slot.get("status") != "masked" else "mostly empty"
            return f"- {slot.get('slot')} ({', '.join(bits)}): {shown}"
        if role in ("ring", "bank") and len(tags) >= 2:
            ordered = sorted(tags, key=_sensor_sort)
            shown = f"{ordered[0]} .. {ordered[-1]} ({len(ordered)} tags)"
        else:
            shown = ", ".join(tags)
        return f"- {slot.get('slot')} ({', '.join(bits)}): {shown} — present"


    def _alert_type_lines(r: Dict[str, Any]) -> List[str]:
        """ALERT TYPE AND TAGS. Empty when the report has no profile, so the legacy prompt is unchanged."""
        profile = r.get("profile") or {}
        slots = list(profile.get("slots") or [])
        if not profile or not slots:
            return []
        learned = r.get("learned") or {}
        n_labels = learned.get("index_size", 0)
        lines = [
            "ALERT TYPE AND TAGS",
            f"Alert type: {profile.get('name')} (profile {profile.get('id')} rev {profile.get('rev')}, "
            f"frame {profile.get('frame_key') or 'auto'}, tier {profile.get('tier')}: {n_labels} labeled cases)",
        ]
        shown = slots
        if len(slots) > 30:
            excursions = learned.get("excursions") or []

            def rank(slot: Dict[str, Any]) -> float:
                sid = str(slot.get("slot") or "")
                best = 0.0
                for row in excursions:
                    channel = str(row.get("channel") or "")
                    if channel == sid or channel.startswith(sid + ":"):
                        best = max(best, abs(float(row.get("score") or 0.0)))
                return best

            present = [slot for slot in slots if slot.get("status") == "present"]
            present.sort(key=rank, reverse=True)
            shown = present[:20]
            lines.extend(_slot_line(slot) for slot in shown)
            extra = len(present) - len(shown)
            if extra > 0:
                lines.append(f"and {extra} more present")
        else:
            lines.extend(_slot_line(slot) for slot in shown)
        others = [str(tag) for tag in (profile.get("other_tags") or [])]
        if others:
            lines.append("Other numeric tags (not in the profile): " + ", ".join(others))
        lines.append("")
        return lines


    def _catalogue_rows(r: Dict[str, Any], taxonomy: Dict[str, Dict[str, Any]]) -> List[Tuple[str, Dict[str, Any]]]:
        """Full taxonomy, or just this alert type's signatures. novel_pattern is added by the caller."""
        names = (r.get("profile") or {}).get("signatures")
        if not names:
            return list(taxonomy.items())
        rows = []
        for name in names:
            if name == NOVEL:
                continue
            rows.append((name, taxonomy.get(name) or {"title": str(name).replace("_", " "), "action": "escalate", "urgency": "prompt"}))
        return rows


    def _catalogue_pattern(signature: str, info: Dict[str, Any], profile: Dict[str, Any]) -> str:
        """residual_expect in slot labels when this alert type defines one; otherwise the legacy sentence."""
        entry = (profile.get("residual_expect") or {}).get(signature) if profile else None
        if entry:
            labels = {slot.get("slot"): slot.get("label") or slot.get("slot") for slot in (profile.get("slots") or [])}

            def names(ids: List[str]) -> str:
                return ", ".join(str(labels.get(sid) or sid) for sid in ids) or "none"

            return f"primary {names(list(entry.get('primary') or []))}; allowed {names(list(entry.get('allowed') or []))}"
        return PATTERN_TEXT.get(signature) or info.get("residual_pattern") or "not defined"


    def _prompt_signature_names(r: Dict[str, Any], taxonomy: Dict[str, Dict[str, Any]]) -> List[str]:
        """Enum for the writer. A profile cuts it to that alert type; legacy keeps the whole taxonomy."""
        names = (r.get("profile") or {}).get("signatures")
        if names:
            return [name for name in names if name != NOVEL]
        return list(taxonomy)


    def _sections(r: Dict[str, Any], taxonomy: Dict[str, Dict[str, Any]], knowledge: List[Dict[str, str]], n_events: int, note_len: int) -> List[str]:
        """Function _sections."""
        L, inp = r["learned"], r["input"]
        rules = r["shadow"].get("rules") or {}
        out: List[str] = []
        w = out.append
        for line in _alert_type_lines(r):
            w(line)
        w("CASE")
        w(f"Analytic raised by Tier 1: \"{r['analytic']['entered']}\"")
        w(f"Unit: {r['case'].get('unit') or 'not stated'}")
        w(f"Engineer notes: \"{(r['case'].get('notes') or 'none').strip()[:600]}\"")
        if r.get("profile"):
            # The slot table above replaces the fixed exhaust-layout line.
            w(f"Data: {inp['rows']} rows from {inp['start']} to {inp['end']}, {inp['interval_minutes'] or '?'} min resolution.")
        else:
            w(f"Data: {inp['rows']} rows from {inp['start']} to {inp['end']}, {inp['interval_minutes'] or '?'} min resolution, "
              f"exhaust layout {L['features'].get('layout')} ({L['features'].get('n_sensors')} sensors).")
        w("")
        w("LARGEST EXCURSIONS (physical units; score = compressed robust z, |score| >= 2 is abnormal)")
        w(excursion_text(L.get("excursions") or [], n=5) or "none: all channels within their normal band")
        w("")
        res = r.get("residual") or {}
        if res and n_events > 0:
            w("RESIDUAL VIEW (second TS Pulse model, independent of the classifier)")
            w(describe(res, n_events=n_events))
            w("")
        w("LEARNED CLASSIFIER (TS Pulse embedding + head)")
        w("Probabilities: " + ", ".join(f"{s} {p:.2f}" for s, p in L["head_probs"].items()))
        w(f"Learned decision: {L['signature']} (basis {L['basis']}, confidence {L['confidence']:.2f})")
        if L["novel"]:
            if L.get("basis") == "residual_novelty":
                w(f"NOVEL: the residuals show abnormal channels that {L.get('residual_novelty_from')} does not explain, and the case is only "
                  f"borderline-known (nearest labeled case distance {L['nearest_distance']:.3f}).")
            elif L.get("nearest_distance") is None or L.get("novelty_threshold") is None:
                w(L.get("note") or "NOVEL: no labeled cases for this alert type yet.")
            else:
                w(f"NOVEL: nearest labeled case distance {L['nearest_distance']:.3f} > novelty threshold {L['novelty_threshold']:.3f}.")
        else:
            w(f"Not novel: nearest labeled case distance {L['nearest_distance']:.3f} <= novelty threshold {L['novelty_threshold']:.3f}.")
        w("")
        w("MOST SIMILAR LABELED CASES")
        for s in (L.get("similar") or [])[:5]:
            note = f"; engineer note: \"{s['note'][:note_len]}\"" if s.get("note") and note_len else ""
            why = f"; engineer why: \"{s['why'][:note_len]}\"" if s.get("why") and note_len else ""
            w(f"- {s['id']} ({s.get('source', '')}): signature {s['signature']}, action {s['action']}, distance {s['distance']:.3f}{note}{why}")
        w("")
        w("RULE-BASED ANALYSIS (shadow, independent)")
        if rules:
            w(f"Action: {rules.get('primary_action')}; cause: {rules.get('cause_title')}; confidence {rules.get('confidence')}")
            w(f"Finding: {rules.get('summary', '')[:400]}")
        else:
            w("not available")
        if r.get("guardrails"):
            w("Guardrails: " + " | ".join(g["message"] for g in r["guardrails"]))
        w("")
        if knowledge:
            w("PROCESS STEPS AND BACKGROUND (site process maps; walk the steps against the data)")
            for k in knowledge:
                w(f"[{k['ref']}]")
                w(k["text"])
            w("")
        w("SIGNATURE CATALOGUE (signature: meaning -> action, urgency; expected residual pattern)")
        profile = r.get("profile") or {}
        for k, v in _catalogue_rows(r, taxonomy):
            pat = _catalogue_pattern(k, v, profile)
            w(f"- {k}: {v['title']} -> {v['action']}, {v['urgency']}; residuals: {pat}")
        w(f"- {NOVEL}: unlike any labeled case -> escalate, prompt")
        w("")
        w("Write the JSON object now.")
        return out


    def build_prompt(r: Dict[str, Any], taxonomy: Dict[str, Dict[str, Any]], budget: int = PROMPT_TOKEN_BUDGET) -> str:
        """User prompt within ``budget`` tokens (with the system prompt): trims knowledge, then residual detail, then notes."""
        kn = [dict(k) for k in (r.get("knowledge") or [])]
        n_events, note_len = 4, 160

        def make() -> str:
            """Function make."""
            return "\n".join(_sections(r, taxonomy, kn, n_events, note_len))

        text = make()
        sys_t = approx_tokens(SYSTEM)
        while sys_t + approx_tokens(text) > budget:
            if kn:
                last = kn[-1]
                if len(last["text"]) > 400:
                    last["text"] = last["text"][: len(last["text"]) // 2].rstrip() + " …"
                else:
                    kn.pop()
            elif n_events > 2:
                n_events -= 1
            elif note_len > 0:
                note_len = 0
            else:
                break
            text = make()
        return text


    def prompt_stats(r: Dict[str, Any], taxonomy: Dict[str, Dict[str, Any]], settings: Any = None) -> Dict[str, Any]:
        """Size of the prompt and of its V2 parts (residual view, process knowledge), in tokens."""
        full = build_prompt(r, taxonomy)
        base = dict(r)
        base["knowledge"] = []
        no_k = build_prompt(base, taxonomy)
        base["residual"] = {}
        no_kr = build_prompt(base, taxonomy)
        if settings is not None:
            from .. import llm_runtime

            def tok(t: str) -> int:
                """Function tok."""
                return int(llm_runtime.count_tokens(settings, t)["tokens"])

            method = llm_runtime.count_tokens(settings, "x")["method"]
        else:
            tok, method = approx_tokens, "estimate (characters / 3.6)"
        t_sys, t_full, t_nok, t_nokr = tok(SYSTEM), tok(full), tok(no_k), tok(no_kr)
        return {"system": t_sys, "user": t_full, "total": t_sys + t_full, "residual_part": t_nok - t_nokr, "knowledge_part": t_full - t_nok,
                "added_v2": t_full - t_nokr, "knowledge_sections": len([ln for ln in full.splitlines() if ln.startswith("[") and "§" in ln]),
                "method": method, "budget": PROMPT_TOKEN_BUDGET}


    def _steps(raw: Any) -> List[Dict[str, str]]:
        """Function _steps."""
        out: List[Dict[str, str]] = []
        for it in raw if isinstance(raw, list) else []:
            if not isinstance(it, dict):
                continue
            step, finding = str(it.get("step") or "").strip(), str(it.get("finding") or "").strip()
            if step and finding:
                out.append({"step": _fit(step, 120), "finding": _fit(finding, 300)})
            if len(out) >= MAX_STEPS:
                break
        return out


    _STOP = {"the", "and", "for", "with", "from", "this", "that", "data", "check", "step", "case", "any"}


    def _steps_match(steps: List[Dict[str, str]], knowledge: List[Dict[str, str]]) -> float:
        """Share of step names that use words from the retrieved process text."""
        words = {t for k in knowledge for t in re.findall(r"[a-z]{4,}", k.get("text", "").lower())} - _STOP
        if not steps:
            return 0.0
        hit = sum(1 for s in steps if set(re.findall(r"[a-z]{4,}", s["step"].lower())) & words)
        return hit / len(steps)


    def write(r: Dict[str, Any], settings: Any, taxonomy: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
        """Function write."""
        from .. import llm_runtime

        user = build_prompt(r, taxonomy)
        sch = schema(_prompt_signature_names(r, taxonomy))
        res = llm_runtime.chat_json(settings, SYSTEM, user, sch, max_tokens=max(int(settings.llm_max_tokens), OUTPUT_TOKENS))
        out: Dict[str, Any] = {"prompt": f"[system]\n{SYSTEM}\n\n[user]\n{user}", "raw": res["text"], "runtime": {k: v for k, v in res.items() if k != "text"}, "ok": False}
        try:
            obj = json.loads(res["text"])
            for key in sch["required"]:
                if key not in obj:
                    raise ValueError(f"missing field {key}")
            if obj["signature"] not in sch["properties"]["signature"]["enum"] or obj["primary_action"] not in ACTIONS or obj["urgency"] not in URGENCY:
                raise ValueError("value outside the allowed enums")
            if obj["residual_consistency"] not in ("supports", "contradicts", "inconclusive"):
                raise ValueError("residual_consistency outside the allowed values")
            for key, limit in LIMITS.items():
                obj[key] = _fit(str(obj.get(key) or ""), limit)
            obj["process_steps"] = _steps(obj.get("process_steps"))
            if min(len(obj["what_happened"]), len(obj["why"]), len(obj["action_rationale"])) < 20:
                raise ValueError("narrative section too short")
        except (ValueError, TypeError, json.JSONDecodeError) as exc:
            out["error"] = f"invalid JSON: {exc}"
            return out
        extra = [obj["concerns"], obj["residual_reason"]] + [f"{s['step']} {s['finding']}" for s in obj["process_steps"]]
        checks, flags = check_output(obj, user, obj["primary_action"], extra=extra)
        kn = r.get("knowledge") or []
        if kn:
            m = _steps_match(obj["process_steps"], kn)
            checks["process steps walked"] = f"{len(obj['process_steps'])} (matching the retrieved process: {m:.0%})"
            if not obj["process_steps"]:
                flags.append("LLM did not walk the retrieved process steps — check the reasoning against the process map.")
            elif m < 0.5:
                flags.append("LLM process steps do not match the retrieved process map — check them.")
        if obj["residual_consistency"] == "contradicts" and not obj["residual_reason"].strip():
            flags.append("LLM reports a residual contradiction without naming the deciding fact.")
        checks["residual cross-check (LLM)"] = obj["residual_consistency"]
        out.update({"ok": True, "obj": obj, "checks": {"json": "valid (schema-constrained)", **checks}, "flags": flags})
        return out


    def lower_confidence(d: Dict[str, Any], low: float, why: str) -> None:
        """Contradiction between the views: confidence drops below the low-confidence line (needs a human)."""
        if "confidence_before_residual" not in d:
            d["confidence_before_residual"] = d["confidence"]
        d["confidence"] = round(min(d["confidence"] * 0.6, max(0.0, low - 0.01)), 2)
        d["confidence_label"] = "High" if d["confidence"] >= 0.75 else ("Medium" if d["confidence"] >= 0.5 else "Low")
        d["confidence_note"] = why


    def apply(r: Dict[str, Any], w: Dict[str, Any], taxonomy: Dict[str, Dict[str, Any]]) -> Tuple[Dict[str, Any], List[str]]:
        """Merge a valid writer result into the report decision; returns (narrative, review flags)."""
        obj, L, d = w["obj"], r["learned"], r["decision"]
        obj = {"residual_consistency": "inconclusive", "residual_reason": "", "process_steps": [], **obj}  # V1-shaped results stay usable
        flags = list(w.get("flags") or [])
        sig, act = obj["signature"], obj["primary_action"]
        if L["novel"] and sig != NOVEL:
            flags.append(f"LLM proposed '{sig}' for a novel pattern — kept as novel (no class is forced).")
            sig, act = NOVEL, "escalate"
        if sig != L["signature"]:
            flags.append(f"LLM changed the signature from {L['signature']} to {sig}: {obj.get('concerns') or 'no reason given'}")
        if act != d["primary_action"]:
            flags.append(f"LLM changed the action from {d['primary_action']} to {act} — confirm before release.")
        # residual cross-check: LLM verdict vs the deterministic check computed at analysis time
        det = (L.get("residual_check") or {}).get("verdict")
        llm_v = obj["residual_consistency"]
        rc = d.setdefault("residual_consistency", {"deterministic": det, "reason": (L.get("residual_check") or {}).get("reason", "")})
        rc["llm"] = llm_v
        rc["llm_reason"] = obj["residual_reason"]
        if llm_v == "contradicts" and det != "contradicts":
            flags.append(f"LLM residual cross-check: the residuals contradict {L['signature']} — {obj['residual_reason'] or 'no reason given'}")
            lower_confidence(d, float(L.get("low_confidence", 0.6)), "LLM residual cross-check contradicts the classifier")
        elif det == "contradicts" and llm_v != "contradicts":
            flags.append(f"LLM residual verdict '{llm_v}' disagrees with the deterministic residual check (contradicts: {rc.get('reason', '')}) — a human must decide.")
        rc["final"] = "contradicts" if "contradicts" in (llm_v, det) else ("supports" if llm_v == det == "supports" else "inconclusive")
        d["classifier_action"] = d.get("classifier_action") or d["primary_action"]
        d["primary_action"] = act
        d["urgency"] = obj["urgency"]
        d["escalate"] = bool(obj["escalate"] or d["escalate"])
        d["source"] = "llm"
        if sig != L["signature"]:
            si = sig_info(sig, taxonomy)
            d["hypothesis"] = si["title"]
            d["llm_signature"] = sig
            d["signature"] = sig
            d["cause"] = si["cause"]
            d["cause_title"] = CAUSES.get(si["cause"], si["cause"])
        concerns = (obj.get("concerns") or "").strip()
        if rc["final"] == "contradicts" and not concerns:
            concerns = obj["residual_reason"] or rc.get("reason", "")
        narrative = {
            "engine": "llm",
            "what_happened": obj["what_happened"].strip(),
            "why": obj["why"].strip(),
            "action_rationale": obj["action_rationale"].strip(),
            "site_instructions": list(SITE_CHECKS.get(sig, SITE_CHECKS[NOVEL])),
            "concerns": concerns,
            "residual_consistency": llm_v,
            "residual_reason": obj["residual_reason"].strip(),
            "process_steps": obj["process_steps"],
            "checks": w.get("checks", {}),
        }
        return narrative, flags


    def knowledge_for(r: Dict[str, Any], taxonomy: Dict[str, Dict[str, Any]], cap: int = KNOWLEDGE_TOKENS, folder: Any = None) -> List[Dict[str, str]]:
        """Process / background sections for this case (analytic + notes + predicted signature + residual pointer)."""
        from ..knowledge import retrieve_learned

        L = r["learned"]
        sig = L["signature"]
        pts = (L.get("residual_check") or {}).get("points_to")
        title = sig_info(sig, taxonomy).get("title", "")
        kw = {"folder": folder} if folder is not None else {}
        return retrieve_learned(r["analytic"]["entered"], r["case"].get("notes") or "", sig, title, token_cap=cap,
                                extra_signatures=[pts] if pts else [], profile=r.get("profile"), **kw)


    __all__ = ["SYSTEM", "schema", "build_prompt", "prompt_stats", "write", "apply", "knowledge_for", "lower_confidence"]
# >>>>>>> END sentinel.e2e.writer

# =============================================================================
# sentinel.e2e.simulate
# Site-adaptation drill used by tests: label, retrain the head, measure the lift.
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.simulate sentinel/e2e/simulate.py
if False:  # compiled by exec_section('sentinel.e2e.simulate'); not executed as part of this module
    """Scripted labeling simulations (used by scripts/eval_e2e.py and the tests).

    ``site_adaptation``  the shipped model meets site-like data (variants + a fault type it has never
                         seen). Cases arrive one by one; for each one the learned prediction is recorded
                         *before* the label (prequential), then the engineer's label is added through the
                         real ``Engine.add_label`` path (index update + retrain every N labels). After
                         every N labels the learned path and the rules are scored on held-out site cases.
    ``cold_start``       no labeled data at all: labels arrive one by one and the head + index are built
                         from scratch, scored on the held-out test split after every N labels.
    """

    # @@future@@ from __future__ import annotations

    import shutil
    import tempfile
    from pathlib import Path
    from typing import Any, Callable, Dict, List, Optional, Sequence

    import numpy as np

    from .model import Calibration, Head, SimilarityIndex, decide, train_head
    from .taxonomy import NOVEL


    def _action(sig: str, tax: Dict[str, Dict[str, Any]], new_actions: Dict[str, str]) -> str:
        """Function _action."""
        if sig == NOVEL:
            return "escalate"
        return new_actions.get(sig) or (tax.get(sig) or {}).get("action", "escalate")


    def site_adaptation(
        settings: Any,
        stream: Sequence[Dict[str, Any]],
        holdout: Sequence[Dict[str, Any]],
        every: int = 5,
        new_signature_actions: Optional[Dict[str, str]] = None,
        log: Callable[[str], None] = lambda m: None,
    ) -> Dict[str, Any]:
        """stream / holdout items: {case_id, emb (raw), signature, action, rules_action}."""
        from ..config import load_settings
        from .engine import Engine

        tmp = Path(tempfile.mkdtemp(prefix="sentinel_sim_"))
        try:
            s = load_settings({"data_dir": tmp, "e2e_model_dir": settings.e2e_model_dir, "e2e_retrain_every": every, "use_llm": False})
            eng = Engine(s)
            new_actions = dict(new_signature_actions or {})
            tax = eng.taxonomy()

            def score() -> Dict[str, float]:
                """Function score."""
                ok_l = ok_r = ok_s = 0
                tax_now = eng.taxonomy()
                for h in holdout:
                    d = eng.decide(eng.scaler(h["emb"])[0])
                    ok_l += _action(d["signature"], tax_now, new_actions) == h["action"]
                    ok_s += d["signature"] == h["signature"]
                    ok_r += h["rules_action"] == h["action"]
                n = len(holdout)
                return {"learned": ok_l / n, "rules": ok_r / n, "learned_signature": ok_s / n}

            curve = [{"labels": 0, **score(), "version": eng.head_version}]
            preq: List[Dict[str, Any]] = []
            for k, item in enumerate(stream, 1):
                eng.labels.save_embedding(item["case_id"], item["emb"])
                d = eng.decide(eng.scaler(item["emb"])[0])
                pred_act = _action(d["signature"], eng.taxonomy(), new_actions)
                preq.append({"n": k, "learned_ok": pred_act == item["action"], "rules_ok": item["rules_action"] == item["action"],
                             "novel": d["novel"], "one_shot": d["one_shot"], "signature": item["signature"]})
                eng.add_label(item["case_id"], item["signature"], item["action"], verdict="good" if d["signature"] == item["signature"] else "not_good",
                              prediction={"signature": d["signature"], "action": pred_act, "rules_action": item["rules_action"]})
                eng.worker.join()
                if k % every == 0 or k == len(stream):
                    sc = score()
                    curve.append({"labels": k, **sc, "version": eng.head_version})
                    log(f"    {k:3d} labels: learned {sc['learned']:.3f}  rules {sc['rules']:.3f}  ({eng.head_version})")
            test_after = eng.heldout_eval()
            return {"curve": curve, "prequential": preq, "heldout_after": test_after, "versions": len(eng.registry.versions())}
        finally:
            shutil.rmtree(tmp, ignore_errors=True)


    def cold_start(
        Z_stream: np.ndarray,
        y_stream: Sequence[str],
        Z_test: np.ndarray,
        y_test: Sequence[str],
        cal: Calibration,
        every: int = 5,
        max_labels: int = 200,
    ) -> List[Dict[str, Any]]:
        """Accuracy on the test split as labels arrive from zero (normalised embeddings)."""
        curve: List[Dict[str, Any]] = []
        idx = SimilarityIndex(dim=Z_stream.shape[1])
        y_test = list(y_test)
        for k in range(1, min(max_labels, len(y_stream)) + 1):
            idx.add(Z_stream[k - 1], {"id": f"s{k}", "signature": y_stream[k - 1], "action": "", "source": "sim"})
            if k % every:
                continue
            labels = [r["signature"] for r in idx.records]
            head = train_head(idx.Z, labels) if len(set(labels)) > 1 else Head(sorted(set(labels)), np.zeros((1, idx.Z.shape[1])), np.zeros(1))
            ok_head = ok_full = 0
            for z, y in zip(Z_test, y_test):
                ok_head += head.predict(z)[0] == y
                ok_full += decide(z, head, idx, cal)["signature"] == y
            curve.append({"labels": k, "classes_seen": len(set(labels)), "head_acc": ok_head / len(y_test), "learned_acc": ok_full / len(y_test)})
        return curve
# >>>>>>> END sentinel.e2e.simulate

