# =============================================================================
# sentinel.pipeline
# Rule path end to end: CSV, notes, analyzer, triage, template or LLM, save.
# =============================================================================
# <<<<<<< SECTION sentinel.pipeline sentinel/pipeline.py
if False:  # compiled by exec_section('sentinel.pipeline'); not executed as part of this module
    """End-to-end case pipeline: CSV + analytic name + notes -> DRAFT Tier 2 report."""

    # @@future@@ from __future__ import annotations

    import time
    from datetime import datetime
    from pathlib import Path
    from typing import Any, Callable, Dict, Optional, Union

    from . import APP_NAME, __version__, analytics, anomaly, knowledge, store
    from .analytics.base import ACTIONS
    from .config import Settings, load_settings
    from .data import load_csv
    from .limits import all_limits
    from .notes import parse_notes
    from .report import bottom_line, template_narrative
    from .triage import decide

    Progress = Callable[[str, float], None]


    def _noop(_msg: str, _frac: float) -> None:
        """Function _noop."""
        return None


    def run_case(
        csv: Union[str, Path, bytes],
        analytic_name: str,
        notes: str = "",
        *,
        settings: Optional[Settings] = None,
        use_llm: Optional[bool] = None,
        source_name: Optional[str] = None,
        progress: Progress = _noop,
        save: bool = True,
        frame: Optional[str] = None,
        layout: Optional[str] = None,
        frame_maps: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Run the rule path.

        ``frame`` is a frame model (6B, 7FA, …), Other / custom, or a frame added from Teach.
        Empty detects the model from the column names. ``layout`` selects a tag layout when the
        frame is Other / custom. ``frame_maps`` replaces the merged table for this run (typed tags).
        """
        t0 = time.monotonic()
        settings = settings or load_settings()
        if use_llm is None:
            use_llm = settings.use_llm

        progress("Loading CSV and checking data quality", 0.02)
        raw = Path(csv).read_bytes() if isinstance(csv, (str, Path)) else bytes(csv)
        name = source_name or (Path(csv).name if isinstance(csv, (str, Path)) else "uploaded.csv")
        from .config import frame_maps_for

        maps = frame_maps if frame_maps is not None else frame_maps_for(settings.data_dir, frame, layout)
        case = load_csv(raw, name=name, frame=frame, frame_maps=maps)
        info = parse_notes(notes)
        res = analytics.resolve(analytic_name)

        progress("Anomaly scan (robust z-score + TS Pulse)", 0.08)
        an = anomaly.scan(case, settings.tspulse_dir, use_tspulse=settings.use_tspulse)

        progress(f"Running {res.analytic} analyzer and signature probes", 0.3)
        probes = analytics.probe_all(case, info, skip=res.analytic if res.known else None)
        findings = analytics.run_analyzer(res, case, info, anomaly=an, probes=probes)

        progress("Looking up similar reviewed cases", 0.38)
        anomalous = [d["channel"] for d in an["zscore"]["channels"][:8]]
        top_cause = findings.top.cause if findings.top else "unknown"
        similar = store.similar_cases(
            settings,
            res.analytic,
            findings.signature,
            top_cause,
            unit=info.unit,
            analytic_norm=analytics.normalise(analytic_name),
            anomalous=anomalous,
        )

        progress("Triage decision (rules)", 0.42)
        decision = decide(res, case, findings, an, probes, similar)

        kn = knowledge.retrieve(res.analytic if res.known else (findings.signature.get("matched_signature") or ""), f"{analytic_name} {findings.summary} {notes}",
                                folder=settings.knowledge_dir, alert_name=analytic_name)
        case_id = store.new_case_id()
        report: Dict[str, Any] = {
            "schema": "sentinel.report/1",
            "app": {"name": APP_NAME, "version": __version__},
            "case_id": case_id,
            "created": datetime.now().isoformat(timespec="seconds"),
            "case": {"unit": info.unit or None, "frame": info.frame, "frame_type": case.frame_type, "notes": notes, "notes_interpreted": info.interpreted()},
            "analytic": {
                "entered": analytic_name,
                "normalised": analytics.normalise(analytic_name),
                "resolved": res.analytic,
                "title": res.title,
                "known": res.known,
                "reason": res.reason,
            },
            "input": {
                "source_name": case.source_name,
                "sha256": case.sha256,
                "rows": case.n,
                "columns": case.quality["columns"],
                "start": case.quality["start"],
                "end": case.quality["end"],
                "interval_minutes": case.interval_minutes,
                "quality": case.quality,
                "roles": case.roles,
            },
            "findings": findings.to_dict(),
            "anomaly": an,
            "cross_check": {k: v.summary for k, v in probes.items() if v.detected},
            "decision": decision.to_dict(),
            "similar_cases": similar,
            "knowledge": kn,
            "review": {"status": "DRAFT", "feedback": None, "history": []},
        }
        from .config import custom_frame_spec

        frame_spec = custom_frame_spec(maps, case.frame_type)
        if frame_spec:  # Other / custom tags for this run, so a later reload maps the same columns
            report["input"]["frame_spec"] = frame_spec
        report["decision"]["action_label"] = ACTIONS.get(decision.primary_action, decision.primary_action)
        narrative = template_narrative(report["findings"], report["decision"])
        extras: Dict[str, str] = {}
        narrative_engine = "template (deterministic, built from analyzer findings)"

        if use_llm and settings.llm_ready():
            progress("Local LLM writing narrative (Gemma 4 12B by default; minutes on CPU)", 0.45)
            from . import llm

            try:
                out = llm.write_narrative(report, settings)
                extras = {"llm_prompt.txt": out["prompt"], "llm_raw.txt": out["raw"]}
                if out.get("ok"):
                    narrative = out["narrative"]
                    narrative_engine = out["engine_desc"]
                    if narrative.get("supports_action") is False:
                        report["decision"]["review_flags"].append(
                            "LLM narrative does not support the decided action"
                            + (f": {narrative['concerns']}" if narrative.get("concerns") else ".")
                        )
                        report["decision"]["needs_human"] = True
                    for msg in out.get("flags", []):
                        report["decision"]["review_flags"].append(msg)
                        report["decision"]["needs_human"] = True
                else:
                    narrative_engine = f"template (LLM output rejected: {out.get('error')})"
                    narrative["checks"] = out.get("checks", {})
            except Exception as exc:  # noqa: BLE001 — the report must still be produced
                narrative_engine = f"template (LLM failed: {exc})"
        elif use_llm:
            from . import llm_runtime

            m = llm_runtime.resolve_model(settings)
            narrative_engine = "template (LLM not available: " + (
                "GGUF not found" if not m["found"] else "llama-cpp-python not installed"
            ) + ")"

        report["narrative"] = narrative
        report["bottom_line"] = bottom_line(report)
        report["audit"] = {
            "thresholds": all_limits()[res.analytic if res.known else "general"],
            "narrative_engine": narrative_engine,
            "analyzer_path": (
                f"built-in analyzer ({res.analytic})" if res.known else
                "generic fallback (no built-in analyzer; generic analyzer + process knowledge)"
            ),
            "frame_type": case.frame_type,
            "settings": {k: v for k, v in settings.describe().items() if k != "sources"},
            "elapsed_s": round(time.monotonic() - t0, 1),
        }
        progress("Saving case", 0.98)
        if save:
            path = store.save_case(settings, report, csv_bytes=raw, extras=extras)
            report["_path"] = str(path)
        progress("Done", 1.0)
        return report
# >>>>>>> END sentinel.pipeline

# =============================================================================
# sentinel.e2e.engine
# Load one version (head, and the encoder that version belongs to) and run decide.
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.engine sentinel/e2e/engine.py
if False:  # compiled by exec_section('sentinel.e2e.engine'); not executed as part of this module
    """The learned-path engine: encoder + scaler + head + similarity index + labels, loaded once.

    Shipped model bundle (``models/e2e``, produced by ``scripts/train_e2e.py``)::

        legacy/encoder/     14-channel TS Pulse (config.json, model.safetensors, classes.json, training.json)
        legacy/base/        14-channel scaler, head, index, calibration, held-out set  -> version v0000
        encoder/            channel-independent TS Pulse plus channel_scaler.npz and novelty_prior.json
        profiles/<pid>/     one built-in alert type, that profile's v0000
        card.json           model card (data, metrics, per-profile rows)

    ``legacy/`` is the old top-level ``encoder/`` and ``base/`` moved without a byte change.
    A tree that has not moved yet is still read from those top-level folders.

    Engineer labels (``data/e2e``) are added to the index immediately and the head retrains in the
    background after every ``e2e_retrain_every`` labels.
    """

    # @@future@@ from __future__ import annotations

    import hashlib
    import json
    import shutil
    import threading
    from pathlib import Path
    from typing import Any, Callable, Dict, List, Optional, Sequence, Tuple

    import numpy as np

    from .encoder import Encoder, finetune, load_encoder
    from .labels import BASE_VERSION, LabelStore, Metrics, Registry, RetrainWorker, e2e_dir, legacy_model_dir
    from .model import (
        Calibration,
        Head,
        ProfileCache,
        ProfileModel,
        Scaler,
        SimilarityIndex,
        condition_vector,
        decide,
        project_embedding,
        train_head,
    )
    from .taxonomy import NOVEL, add_signature, load_taxonomy
    from .train import not_worse, recalibrate, score_heldout

    SITE_WEIGHT = 3.0  # an engineer label counts more than one synthetic case


    class ModelMissing(RuntimeError):
        """Class ModelMissing."""
        pass


    class Engine:
        """Class Engine."""
        def __init__(self, settings: Any):
            """Function __init__."""
            self.settings = settings
            self.mdir = Path(settings.e2e_model_dir)
            base = legacy_model_dir(self.mdir, "base")
            enc = legacy_model_dir(self.mdir, "encoder")
            if not (base / "scaler.npz").is_file() or not (enc / "config.json").is_file():
                raise ModelMissing(f"learned model not found in {self.mdir} — run: python scripts/train_e2e.py")
            self.labels = LabelStore(settings)
            self.metrics = Metrics(settings)
            self.registry = Registry(settings)
            # Alert-type models load on first use. Sixteen is enough for a review session.
            self.profile_cache = ProfileCache()
            self.worker = RetrainWorker()
            self._lock = threading.RLock()
            self.encoder_version = "shipped"
            self._index: Optional[SimilarityIndex] = None
            # Active version may be a fine-tuned bundle (its own encoder, scaler, index
            # and calibration). v0000 and head-only versions use the shipped bundle.
            self._load_bundle(self.registry.current(), initial=True)

        def profile_model(self, profile_id: str, build: Optional[Callable[..., Any]] = None) -> Any:
            """The loaded model for this alert type. ``build`` runs only on a cache miss.

            With no builder, an alert type that has no bundle yet is an empty cold-start model.
            """
            cached = self.profile_cache.get(profile_id)
            if cached is not None:
                return cached
            model = build(profile_id) if build is not None else ProfileModel.empty(profile_id)
            self.profile_cache.put(profile_id, model)
            return model

        # ------------------------------------------------------------------ bundles
        def _encoder_for(self, version: str) -> Tuple[Path, str]:
            """Encoder directory and the version id that owns it (``shipped`` or ``vNNNN``).

            A full retrain stores its encoder in the version folder. A quick update
            does not copy the weights; it records ``encoder_from`` so rollback loads
            the encoder the head was trained on. Older head-only versions have no
            such field and belong to the shipped encoder.
            """
            folder = self.registry.folder(version)
            if version != BASE_VERSION and (folder / "encoder" / "config.json").is_file():
                return folder / "encoder", version
            parent = (self.registry._meta(version) or {}).get("encoder_from") or "shipped"
            if parent != "shipped":
                p = self.registry.folder(parent) / "encoder"
                if (p / "config.json").is_file():
                    return p, parent
            return legacy_model_dir(self.mdir, "encoder"), "shipped"

        def _owner_folder(self, enc_id: str) -> Path:
            """Scaler, base index and held-out embeddings travel with the encoder, not with every head."""
            if enc_id != "shipped":
                folder = self.registry.folder(enc_id)
                if (folder / "scaler.npz").is_file() and (folder / "index.npz").is_file():
                    return folder
            return legacy_model_dir(self.mdir, "base")

        def _encoder_stamp(self) -> str:
            """Function _encoder_stamp."""
            p = Path(self.encoder.path) / "model.safetensors"
            st = p.stat()
            raw = f"{Path(self.encoder.path).resolve()}|{st.st_size}|{int(st.st_mtime)}"
            return hashlib.sha256(raw.encode()).hexdigest()[:16]

        def _marker_path(self) -> Path:
            """Function _marker_path."""
            return e2e_dir(self.settings) / "emb_encoder.txt"

        def _embeddings_match_encoder(self) -> bool:
            """Engineer ``emb/*.npy`` files are raw encoder outputs. A missing marker means they were made by the shipped encoder."""
            f = self._marker_path()
            if not f.is_file():
                return self.encoder_version == "shipped"
            return f.read_text(encoding="utf-8").strip() == self._encoder_stamp()

        def _load_bundle(self, version: str, *, initial: bool = False) -> None:
            """Make ``version`` the in-memory model: head, and the encoder it was trained with.

            Switching encoders re-embeds engineer-labeled cases from their stored CSV.
            Embeddings from the previous encoder would land in the wrong place in the
            index, so they are not reused. The first load of the shipped encoder trusts
            the embeddings already on disk (that is how the app has always started).
            """
            enc_path, enc_id = self._encoder_for(version)
            owner = self._owner_folder(enc_id)
            had = hasattr(self, "encoder")
            changed = (not had) or Path(self.encoder.path).resolve() != Path(enc_path).resolve()
            with self._lock:
                if changed:
                    # A just-written encoder must not be served from the load cache.
                    from .encoder import _CACHE
                    _CACHE.pop(str(Path(enc_path).resolve()), None)
                    self.encoder = load_encoder(enc_path)
                    self.encoder_version = enc_id
                self.scaler = Scaler.load(owner / "scaler.npz")
                self.base_index = SimilarityIndex.load(owner, "index")
                legacy_base = legacy_model_dir(self.mdir, "base")
                cal_path = self.registry.folder(version) / "calibration.json"
                if not cal_path.is_file():
                    cal_path = owner / "calibration.json" if (owner / "calibration.json").is_file() else legacy_base / "calibration.json"
                self.cal = Calibration.load(cal_path)
                held = owner / "heldout.npz"
                if not held.is_file():
                    held = legacy_base / "heldout.npz"
                self.heldout = dict(np.load(held, allow_pickle=False)) if held.is_file() else None
                self.head = Head.load(self.registry.folder(version))
                self.head_version = version
                self._index = None
            reembed = changed and not (initial and self._embeddings_match_encoder())
            if reembed and had:
                self._reembed_site()
            elif reembed and initial and not self._embeddings_match_encoder():
                self._reembed_site()
            else:
                self._load_site_index()

        def _reembed_site(self) -> int:
            """Recompute engineer embeddings with the active encoder. Cases without a CSV are dropped from the index."""
            from ..data import load_csv
            from .features import canonical

            from ..config import frame_maps_for, merged_frame_maps

            rewritten = set()
            idx = SimilarityIndex(dim=self.base_index.Z.shape[1])
            maps = merged_frame_maps(self.settings.data_dir)
            for lab in self.labels.latest().values():
                if lab.get("signature") == NOVEL:
                    continue
                src = Path(lab.get("csv_path") or "")
                if not src.is_file():
                    continue
                # An Other / custom label carries the tags it was analyzed with.
                lab_maps = frame_maps_for(self.settings.data_dir, lab.get("frame_type"), spec=lab["frame_spec"]) if lab.get("frame_spec") else maps
                raw = self.encoder.embed(np.asarray(canonical(load_csv(src, frame=lab.get("frame_type") or None,
                                                                       frame_maps=lab_maps)).x, dtype=np.float32)[None])[0]
                self.labels.save_embedding(lab["case_id"], raw)
                idx.add(self.align(self.scaler(raw)[0], lab.get("frame_type"), spec=lab.get("frame_spec")), self._site_record(lab))
                rewritten.add(lab["case_id"])
            emb_dir = self.labels.emb_dir
            if emb_dir.is_dir():
                for p in emb_dir.glob("*.npy"):
                    if p.stem not in rewritten:
                        p.unlink()
            self._marker_path().parent.mkdir(parents=True, exist_ok=True)
            self._marker_path().write_text(self._encoder_stamp(), encoding="utf-8")
            with self._lock:
                self.site_index = idx
                self._index = None
            return len(rewritten)

        # ------------------------------------------------------------------ state
        def _load_head(self, version: str) -> None:
            """Function _load_head."""
            with self._lock:
                self.head = Head.load(self.registry.folder(version))
                self.head_version = version

        def _site_record(self, lab: Dict[str, Any]) -> Dict[str, Any]:
            """Function _site_record."""
            return {
                "id": lab["case_id"],
                "signature": lab["signature"],
                "action": lab["action"],
                "source": "engineer",
                "verdict": lab.get("verdict"),
                "note": lab.get("note", ""),
                "why": lab.get("why", ""),
                "reviewer": lab.get("reviewer", ""),
                "time": lab.get("time"),
                "file": lab.get("source_name", ""),
                "frame_type": lab.get("frame_type") or "",
                # Other / custom keeps the layout it was analyzed with, so a reload conditions the same slot.
                "frame_spec": lab.get("frame_spec") or None,
            }

        def _case_layout(self, frame: Optional[str] = None, spec: Any = None, layout: Optional[str] = None) -> str:
            """Layout column for this case. A shipped model uses its own layout; a hint cannot override it."""
            from ..config import layout_of

            return layout_of(frame, layout, spec if isinstance(spec, dict) else None, self.settings.data_dir)

        def align(self, z: np.ndarray, frame: Optional[str] = None, layout: Optional[str] = None,
                  spec: Any = None) -> np.ndarray:
            """Append the layout one-hot when the active head was trained with one. A shipped head is unchanged."""
            lay = self._case_layout(frame, spec, layout)
            return project_embedding(np.asarray(z, dtype=np.float32).reshape(-1), frame or "", self.head, layout=lay)

        def _carry_frame(self, head: Head) -> Head:
            """A quick or head-only refit must keep the layout one-hot the index was built with."""
            if self.head.meta.get("uses_frame"):
                head.meta["uses_frame"] = True
                head.meta["frames"] = list(self.head.meta.get("frames") or [])
                if self.head.meta.get("frame_key"):
                    head.meta["frame_key"] = self.head.meta["frame_key"]
            return head

        def _gate(self, before: Dict[str, Any], after: Dict[str, Any], force: bool) -> Tuple[bool, str]:
            """Promotion decision. ``--force`` overrides a failed gate and returns the reason to log."""
            ok = not_worse(before, after)
            if force and not ok:
                return True, "held-out overall accuracy or a frame/alert slice regressed; --force promoted this version"
            return ok, ""

        def _load_site_index(self) -> None:
            """Function _load_site_index."""
            idx = SimilarityIndex(dim=self.base_index.Z.shape[1])
            for lab in self.labels.latest().values():
                if lab["signature"] == NOVEL:
                    continue
                e = self.labels.embedding(lab["case_id"])
                if e is not None:
                    idx.add(self.align(self.scaler(e)[0], lab.get("frame_type"), spec=lab.get("frame_spec")), self._site_record(lab))
            with self._lock:
                self.site_index = idx
                self._index = None

        @property
        def index(self) -> SimilarityIndex:
            """Function index."""
            with self._lock:
                if self._index is None:
                    self._index = self.base_index.merged(self.site_index)
                return self._index

        def taxonomy(self) -> Dict[str, Dict[str, Any]]:
            """Function taxonomy."""
            return load_taxonomy(self.settings.data_dir)

        # ------------------------------------------------------------------ inference
        def embed(self, x: np.ndarray) -> np.ndarray:
            """Function embed."""
            return self.encoder.embed(np.asarray(x, dtype=np.float32)[None])[0]

        def decide(self, z: np.ndarray, exclude: Sequence[str] = (), residual: Optional[Dict[str, Any]] = None,
                   frame: Optional[str] = None, layout: Optional[str] = None, spec: Any = None) -> Dict[str, Any]:
            """Function decide. The layout one-hot and the layout novelty radius; a well-sampled model keeps its own radius."""
            with self._lock:
                head, index = self.head, self.index
            lay = self._case_layout(frame, spec, layout)
            z = project_embedding(z, frame or "", head, layout=lay)
            out = decide(z, head, index, self.cal, exclude=exclude, residual=residual, frame=frame, layout=lay)
            out["head_version"] = self.head_version
            out["index_size"] = len(index)
            out["index_engineer_labels"] = len(self.site_index)
            return out

        def _shown_encoder_path(self) -> str:
            """Path the status page prints. Prefer a repo-relative path with forward slashes."""
            from ..config import ROOT

            path = Path(self.encoder.path)
            try:
                return path.resolve().relative_to(Path(ROOT).resolve()).as_posix()
            except ValueError:
                return str(path)

        def describe(self) -> Dict[str, Any]:
            """Function describe."""
            return {
                "encoder": self.encoder.description,
                "encoder_path": self._shown_encoder_path(),
                "head_version": self.head_version,
                "head_classes": len(self.head.classes),
                "index_size": len(self.index),
                "engineer_labels": len(self.site_index),
                "novelty_threshold": self.cal.novelty_threshold,
                "match_threshold": self.cal.match_threshold,
                "low_confidence": self.cal.low_confidence,
                "residual_novelty": {"enabled": self.cal.residual_novelty, "border": self.cal.novelty_border, "confidence_floor": self.cal.novelty_conf},
                "residual_thresholds": self.cal.residual_thresholds,
            }

        # ------------------------------------------------------------------ learning loop
        def remove_label(self, case_id: str, by: str = "") -> None:
            """Delete an engineer label (tombstone): out of the similarity index now, out of the next retrain."""
            self.labels.delete(case_id, by=by)
            with self._lock:
                self.site_index.remove(case_id)
                self._index = None
            self.metrics.log("label_deleted", case_id=case_id, by=by)

        def reload_labels(self) -> None:
            """Rebuild the engineer part of the similarity index from the label store (after a rollback)."""
            self._load_site_index()

        def labels_since_retrain(self) -> int:
            """Legacy labels since the last legacy retrain or rollback.

            A label or a retrain that names an alert type belongs to that profile's
            own counter and does not move this one.
            """
            ev = self.metrics.events()
            last = max((i for i, e in enumerate(ev) if e["type"] in ("retrain", "rollback") and not e.get("profile")), default=-1)
            return sum(1 for e in ev[last + 1 :] if e["type"] == "label" and not e.get("profile"))

        def add_label(
            self,
            case_id: str,
            signature: str,
            action: str,
            verdict: str = "good",
            note: str = "",
            reviewer: str = "",
            prediction: Optional[Dict[str, Any]] = None,
            extra: Optional[Dict[str, Any]] = None,
            new_signature_title: str = "",
            auto_retrain: bool = True,
            why: str = "",
        ) -> Dict[str, Any]:
            """Store a label, add the case to the similarity index now, maybe retrain in background."""
            tax = self.taxonomy()
            if signature not in tax and signature != NOVEL:
                signature = add_signature(self.settings.data_dir, signature, action, title=new_signature_title)
            emb = self.labels.embedding(case_id)
            if emb is None:
                raise ValueError(f"no embedding stored for case {case_id} (analyze it first)")
            pred = prediction or {}
            lab = self.labels.add(
                {
                    "case_id": case_id,
                    "signature": signature,
                    "action": action,
                    "verdict": verdict,
                    "note": note.strip(),
                    "why": why.strip(),
                    "reviewer": reviewer.strip() or "unspecified",
                    "predicted_signature": pred.get("signature"),
                    "predicted_action": pred.get("action"),
                    "rules_action": pred.get("rules_action"),
                    **(extra or {}),
                }
            )
            if signature != NOVEL:  # "still unknown" confirmations are logged, never learned as a class
                with self._lock:
                    self.site_index.add(
                        self.align(self.scaler(emb)[0], (extra or {}).get("frame_type"), spec=(extra or {}).get("frame_spec")),
                        self._site_record(lab),
                    )
                    self._index = None
            accepted = verdict == "good" and pred.get("signature") == signature and pred.get("action") == action
            self.metrics.log(
                "label",
                case_id=case_id,
                signature=signature,
                action=action,
                verdict=verdict,
                predicted_signature=pred.get("signature"),
                learned_correct=pred.get("action") == action if pred.get("action") else None,
                learned_signature_correct=pred.get("signature") == signature if pred.get("signature") else None,
                rules_correct=pred.get("rules_action") == action if pred.get("rules_action") else None,
                accepted_without_edit=accepted,
                novel=pred.get("signature") == NOVEL,
                new_signature=signature not in tax and signature != NOVEL,
            )
            started = False
            n = self.labels_since_retrain()
            if auto_retrain and n >= max(1, int(self.settings.e2e_retrain_every)):
                started = self.worker.start(self.retrain, trigger=f"auto after {n} new labels")
            return {"label": lab, "retrain_started": started, "labels_since_retrain": n}

        def training_set(self) -> Dict[str, Any]:
            """Function training_set."""
            with self._lock:
                Zb, recb = self.base_index.Z, list(self.base_index.records)
                Zs, recs = self.site_index.Z, list(self.site_index.records)
            Z = np.vstack([Zb, Zs]) if len(recs) else Zb
            y = [r["signature"] for r in recb] + [r["signature"] for r in recs]
            w = np.concatenate([np.ones(len(recb)), np.full(len(recs), SITE_WEIGHT)])
            return {"Z": Z, "y": y, "w": w, "n_synthetic": len(recb), "n_engineer": len(recs)}

        def retrain(self, trigger: str = "manual") -> Dict[str, Any]:
            """Head-only refit used by the label loop. Always activated (the existing behaviour).

            The Teach-page retrain (``train``) is the one that also rebuilds the index,
            recalibrates novelty and can fine-tune the encoder, and that one promotes
            only when held-out accuracy is not worse. This path stays fast so labeling
            does not wait on a calibration pass.
            """
            data = self.training_set()
            head = self._carry_frame(train_head(data["Z"], data["y"], data["w"]))
            ev = self.heldout_eval(head)
            meta = {
                "trigger": trigger,
                "kind": "head",
                "encoder_from": self.encoder_version,
                "n_synthetic": data["n_synthetic"],
                "n_engineer": data["n_engineer"],
                "classes": head.classes,
                "heldout": ev,
            }
            version = self.registry.register(head, meta)
            # Snapshot the calibration this head was trained under, so activating the version later
            # does not snap novelty thresholds back to the shipped file.
            self.cal.save(self.registry.folder(version) / "calibration.json")
            with self._lock:
                self.head, self.head_version = head, version
            self.metrics.log("retrain", version=version, trigger=trigger, n_engineer=data["n_engineer"], **{f"heldout_{k}": v for k, v in ev.items() if not isinstance(v, dict)})
            return {"version": version, **meta}

        def activate(self, version: str) -> None:
            """One-click restore of any saved version, including a fine-tuned encoder."""
            self.registry.activate(version)
            self._load_bundle(version)
            self.metrics.log("rollback", version=version)

        def rollback(self) -> str:
            """Function rollback."""
            v = self.registry.rollback()
            self._load_bundle(v)
            self.metrics.log("rollback", version=v)
            return v

        def heldout_eval(self, head: Optional[Head] = None, cal: Optional[Calibration] = None, index: Optional[SimilarityIndex] = None,
                         heldout: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
            """Learned (head + index + novelty) vs rules on the held-out test split.

            Pass a candidate head / calibration / index / held-out matrix to score a
            model that is not active yet. Novelty rate on this split is the false-novelty
            rate (every test case has a known signature). One-shot accuracy is null when
            the index did not override the head.
            """
            held = self.heldout if heldout is None else heldout
            if held is None:
                return {}
            head = head or self.head
            cal = cal or self.cal
            if index is None:
                with self._lock:
                    index = self.index
            frames = None
            if "frame" in held and len(held["frame"]):
                from ..config import canonical_frame

                frames = [canonical_frame(str(x)) or str(x) for x in held["frame"]]
            elif "case_id" in held and len(held["case_id"]) == len(held["signature"]):
                # The shipped held-out file predates the frame column. Without frames the "before" side has
                # no frame slices, so the gate cannot see a frame regression on the first full retrain.
                frames = self._manifest_frames([str(c) for c in held["case_id"]])
            return score_heldout(held["Z"].astype(np.float32), held["signature"], held["rules_action"], head, index, cal, self.taxonomy(), frames=frames)

        def _manifest_frames(self, case_ids: Sequence[str]) -> Optional[List[str]]:
            """Frame of each held-out case, looked up in the synthetic manifest. None when the manifest
            is missing or does not list every case (then the slice tables simply stay empty)."""
            from ..config import frame_of_row
            from .dataset import load_manifest

            path = Path(self.settings.data_dir) / "e2e" / "dataset" / "manifest.jsonl"
            if not path.is_file():
                return None
            key = (str(path), path.stat().st_mtime_ns, tuple(case_ids))
            cached = getattr(self, "_frames_cache", None)
            if cached is not None and cached[0] == key:
                return cached[1]
            by_id = {r.get("case_id"): r for r in load_manifest(path.parent)}
            frames = [frame_of_row(by_id[c]) for c in case_ids] if all(c in by_id for c in case_ids) else None
            self._frames_cache = (key, frames)
            return frames

        # ------------------------------------------------------------------ Teach-page retrain
        def _progress(self, cb: Optional[Callable[[float, str], None]], frac: float, message: str) -> None:
            """Function _progress."""
            if cb:
                cb(max(0.0, min(1.0, frac)), message)

        def validation_embeddings(self, progress: Optional[Callable[[float, str], None]] = None) -> Optional[Tuple[np.ndarray, List[str]]]:
            """Scaled validation embeddings for novelty recalibration, cached per encoder.

            The shipped encoder's cache is ``models/e2e/base/val.npz`` when present, so a
            quick update does not re-embed 200 cases. Any other encoder gets a cache
            under ``data/e2e/cache``. Returns None when the synthetic dataset is not on disk.
            """
            if self.encoder_version == "shipped":
                shipped = legacy_model_dir(self.mdir, "base") / "val.npz"
                if shipped.is_file():
                    return self._read_val(np.load(shipped, allow_pickle=True))
            cache = e2e_dir(self.settings) / "cache" / f"val_{self._encoder_stamp()}.npz"
            if cache.is_file():
                return self._read_val(np.load(cache, allow_pickle=True))
            root = Path(self.settings.data_dir) / "e2e" / "dataset"
            if not (root / "manifest.jsonl").is_file():
                return None
            self._progress(progress, 0.25, "Embedding the validation split (once per encoder) so the next quick update is seconds")
            from ..config import frame_of_row
            from .dataset import cached_features, load_manifest

            rows = load_manifest(root)
            va = [i for i, r in enumerate(rows) if r.get("split") == "val"]
            if not va:
                return None
            X = cached_features(root, rows, e2e_dir(self.settings) / "cache")
            Z = self.scaler(self.encoder.embed(X[np.array(va)]))
            sig = [rows[i]["signature"] for i in va]
            frames = [frame_of_row(rows[i]) for i in va]
            if self.head.meta.get("uses_frame"):
                Z = np.stack([project_embedding(z, f, self.head) for z, f in zip(Z, frames)])
            cache.parent.mkdir(parents=True, exist_ok=True)
            np.savez_compressed(cache, Z=Z.astype(np.float32), signature=np.array(sig), frame=np.array(frames))
            return Z, sig, frames

        def _read_val(self, d: Any) -> Tuple[Any, ...]:
            """Validation cache. Older files have no frame column; callers accept a 2-tuple or a 3-tuple."""
            Z = d["Z"].astype(np.float32)
            sig = [str(s) for s in d["signature"]]
            names = getattr(d, "files", [])
            if "frame" in names and len(d["frame"]):
                from ..config import canonical_frame

                return Z, sig, [canonical_frame(str(x)) or str(x) for x in d["frame"]]
            return Z, sig

        def _fit_quick(self, Zval: Optional[np.ndarray], yval: Optional[Sequence[str]],
                       frames: Optional[Sequence[str]] = None) -> Tuple[Head, Calibration, Dict[str, Any]]:
            """Head + novelty calibration on the current index. Does not touch ``self``."""
            data = self.training_set()
            head = self._carry_frame(train_head(data["Z"], data["y"], data["w"]))
            with self._lock:
                index = self.index
            cal = recalibrate(self.cal, index, Zval, yval, frames=frames)
            ev = self.heldout_eval(head, cal, index)
            return head, cal, ev

        def _save_version(self, head: Head, meta: Dict[str, Any], cal: Calibration, *, encoder_dir: Optional[Path] = None,
                          scaler: Optional[Scaler] = None, base_index: Optional[SimilarityIndex] = None,
                          heldout: Optional[Dict[str, Any]] = None) -> str:
            """Write a version folder. Not activated — the caller promotes only when it should."""
            version = self.registry.register(head, meta, activate=False)
            folder = self.registry.folder(version)
            cal.save(folder / "calibration.json")
            if encoder_dir is not None and encoder_dir.is_dir():
                dest = folder / "encoder"
                if dest.exists():
                    shutil.rmtree(dest)
                shutil.copytree(encoder_dir, dest)
            if scaler is not None:
                scaler.save(folder / "scaler.npz")
            if base_index is not None:
                base_index.save(folder, "index")
            if heldout is not None:
                payload = {
                    "Z": np.asarray(heldout["Z"]).astype(np.float16),
                    "signature": np.asarray(heldout["signature"]),
                    "rules_action": np.asarray(heldout["rules_action"]),
                    "case_id": np.asarray(heldout["case_id"]) if "case_id" in heldout else np.asarray([]),
                }
                if "frame" in heldout:
                    payload["frame"] = np.asarray(heldout["frame"])
                np.savez_compressed(folder / "heldout.npz", **payload)
            # register() already stamped `created`. Keep it when the caller rewrites the rest of the meta.
            prev = json.loads((folder / "meta.json").read_text(encoding="utf-8"))
            prev.update(meta)
            (folder / "meta.json").write_text(json.dumps(prev, indent=2, default=str), encoding="utf-8")
            return version

        def train(
            self,
            mode: str = "quick",
            device: str = "auto",
            force: bool = False,
            epochs: int = 12,
            trigger: str = "",
            progress: Optional[Callable[[float, str], None]] = None,
        ) -> Dict[str, Any]:
            """Quick or full retrain. Saves a version; promotes it only when held-out accuracy is not worse.

            ``force`` promotes even when the held-out numbers dropped. ``device`` is
            ``auto``, ``gpu`` or ``cpu`` (full retrain only; a quick update does not
            run the encoder). ``progress(frac, message)`` receives 0..1.
            """
            if mode not in ("quick", "full"):
                raise ValueError("mode must be quick or full")
            trigger = trigger or f"{mode} retrain"
            self._progress(progress, 0.02, "Scoring the active model on the held-out split")
            before = self.heldout_eval()
            self.reload_labels()
            if mode == "full":
                return self._train_full(device, force, epochs, trigger, before, progress)
            self._progress(progress, 0.1, "Refitting the classifier head and recalibrating novelty")
            Zval, yval, vframes = None, None, None
            got = self.validation_embeddings(progress)
            if got is not None:
                Zval, yval = got[0], got[1]
                vframes = got[2] if len(got) > 2 else None
            head, cal, after = self._fit_quick(Zval, yval, vframes)
            promoted, reason = self._gate(before, after, bool(force))
            meta = self._version_meta(trigger, "quick", device, force, promoted, before, after, head, encoder_from=self.encoder_version)
            if reason:
                meta["force_reason"] = reason
            version = self._save_version(head, meta, cal)
            if reason:
                print(f"FORCE PROMOTE {version}: {reason}", flush=True)
                self.metrics.log("force_promote", version=version, trigger=trigger, reason=reason)
            if promoted:
                with self._lock:
                    self.head, self.head_version, self.cal = head, version, cal
                self.registry.activate(version)
            self._log_train(version, trigger, after, promoted)
            self._progress(progress, 1.0, f"{version} {'promoted' if promoted else 'saved but not promoted'}")
            return {"version": version, "promoted": promoted, "kind": "quick", "before": before, "after": after, "force": force,
                    "force_reason": reason, **meta}

        def _version_meta(self, trigger, kind, device, force, promoted, before, after, head, encoder_from, finetune_info=None) -> Dict[str, Any]:
            """Function _version_meta."""
            data = self.training_set()
            meta = {
                "trigger": trigger,
                "kind": kind,
                "device": device,
                "force": bool(force),
                "promoted": bool(promoted),
                "encoder_from": encoder_from,
                "n_synthetic": data["n_synthetic"],
                "n_engineer": data["n_engineer"],
                "classes": head.classes,
                "heldout": after,
                "heldout_before": before,
            }
            if finetune_info:
                meta["finetune"] = {"best": finetune_info.get("best"), "device": finetune_info.get("device"), "device_reason": finetune_info.get("device_reason")}
            return meta

        def _log_train(self, version: str, trigger: str, after: Dict[str, Any], promoted: bool) -> None:
            """Function _log_train."""
            data = self.training_set()
            self.metrics.log(
                "retrain", version=version, trigger=trigger, promoted=promoted, n_engineer=data["n_engineer"],
                **{f"heldout_{k}": v for k, v in (after or {}).items() if not isinstance(v, dict)},
            )

        def _train_full(self, device: str, force: bool, epochs: int, trigger: str, before: Dict[str, Any],
                        progress: Optional[Callable[[float, str], None]]) -> Dict[str, Any]:
            """Fine-tune the encoder, then the quick steps, in a staging folder. The active model is untouched until promotion."""
            arrays = self._full_arrays(progress)
            stage = e2e_dir(self.settings) / "jobs" / "encoder_staging"
            if stage.exists():
                shutil.rmtree(stage)

            def ft_progress(frac: float, message: str) -> None:
                # The fine-tune is most of a full retrain; leave the ends for embedding and the head.
                """Function ft_progress."""
                self._progress(progress, 0.05 + 0.70 * frac, message)

            self._progress(progress, 0.05, f"Fine-tuning TS Pulse ({epochs} epochs, device {device})")
            info = finetune(
                self.settings.tspulse_clf_dir, arrays["Xtr"], arrays["ytr"], arrays["Xva"], arrays["yva"], arrays["classes"], stage,
                epochs=epochs, device=device, progress=ft_progress, log_fn=lambda m: print(m, flush=True),
            )
            from .encoder import _CACHE
            _CACHE.pop(str(stage.resolve()), None)
            enc = load_encoder(stage)
            from ..config import conditioning_vocab, layout_of

            self._progress(progress, 0.78, "Embedding labeled cases with the new encoder")
            # The encoder still sees the 14 canonical channels. The layout is a one-hot after
            # the scaler, so one shared TS Pulse serves every model and the index distance
            # moves when two cases use different tag layouts. Models that share a layout
            # (6B with 7EA, 9FA with 7FA) light the same column.
            vocab = conditioning_vocab(self.settings.data_dir)
            Eall = enc.embed(arrays["Xtr"])
            scaler = Scaler.fit(Eall)
            n_syn = len(arrays["train_records"])
            syn_frames = [r.get("frame_type") or "" for r in arrays["train_records"]]
            Zsyn = np.stack([condition_vector(z, f, vocab) for z, f in zip(scaler(Eall[:n_syn]), syn_frames)]) if n_syn else np.zeros((0, 1), np.float32)
            base_index = SimilarityIndex(Zsyn, arrays["train_records"])
            site = SimilarityIndex(dim=base_index.Z.shape[1] if n_syn else len(vocab) + int(Eall.shape[1] if len(Eall) else 0))
            raws: List[Tuple[str, np.ndarray]] = []
            for item, raw in zip(arrays["engineer"], Eall[n_syn:]):
                rec = item["record"]
                spec = rec.get("frame_spec") if isinstance(rec.get("frame_spec"), dict) else None
                lay = layout_of(rec.get("frame_type") or "", spec=spec, data_dir=self.settings.data_dir)
                site.add(condition_vector(scaler(raw)[0], rec.get("frame_type") or "", vocab, layout=lay), rec)
                raws.append((item["case_id"], raw))
            merged = base_index.merged(site)
            y = [r["signature"] for r in merged.records]
            w = np.concatenate([np.ones(len(base_index)), np.full(len(site), SITE_WEIGHT)]) if len(site) else np.ones(len(base_index))
            head = train_head(merged.Z, y, w)
            head.meta["uses_frame"] = True
            head.meta["frame_key"] = "layout"
            head.meta["frames"] = list(vocab)
            self._progress(progress, 0.88, "Recalibrating novelty and scoring the held-out split")
            # A missing layout is a zero one-hot. The vector still has to match the
            # conditioned index, or novelty distances crash (672 vs 672 + number of layouts).
            va_frames = list(arrays.get("va_frames") or [])
            te_frames = list(arrays.get("te_frames") or [])
            Zva = scaler(enc.embed(arrays["Xva"]))
            if len(va_frames) != len(Zva):
                va_frames = [""] * len(Zva)
            if len(Zva):
                Zva = np.stack([condition_vector(z, f, vocab) for z, f in zip(Zva, va_frames)])
            cal = recalibrate(self.cal, merged, Zva, arrays["yva_labels"], frames=va_frames)
            Zte = scaler(enc.embed(arrays["Xte"]))
            if len(te_frames) != len(Zte):
                te_frames = [""] * len(Zte)
            Zte = np.stack([condition_vector(z, f, vocab) for z, f in zip(Zte, te_frames)]) if len(Zte) else Zte
            heldout = {
                "Z": np.asarray(Zte).astype(np.float32),
                "signature": arrays["sig_te"],
                "rules_action": arrays["rules_te"],
                "case_id": arrays["case_te"],
                "frame": np.asarray(te_frames),
            }
            after = score_heldout(heldout["Z"], heldout["signature"], heldout["rules_action"], head, merged, cal, self.taxonomy(), frames=te_frames)
            promoted, reason = self._gate(before, after, bool(force))
            meta = self._version_meta(trigger, "full", info.get("device") or device, force, promoted, before, after, head,
                                      encoder_from="self", finetune_info=info)
            if reason:
                meta["force_reason"] = reason
            version = self._save_version(head, meta, cal, encoder_dir=stage, scaler=scaler, base_index=base_index, heldout=heldout)
            # The version folder now owns the encoder. Point encoder_from at it (not at the staging dir, which is deleted).
            meta["encoder_from"] = version
            folder = self.registry.folder(version)
            prev = json.loads((folder / "meta.json").read_text(encoding="utf-8"))
            prev.update(meta)
            (folder / "meta.json").write_text(json.dumps(prev, indent=2, default=str), encoding="utf-8")
            # Reload from the version folder before deleting the staging dir. On Windows the
            # safetensors file stays mapped while the staging Encoder object is alive.
            _CACHE.pop(str(stage.resolve()), None)
            del enc
            if promoted:
                kept = load_encoder(folder / "encoder")
                self._install_full(version, kept, folder / "encoder", scaler, base_index, site, cal, head, heldout, raws)
            import gc
            gc.collect()
            shutil.rmtree(stage, ignore_errors=True)
            if reason:
                print(f"FORCE PROMOTE {version}: {reason}", flush=True)
                self.metrics.log("force_promote", version=version, trigger=trigger, reason=reason)
            self._log_train(version, trigger, after, promoted)
            self._progress(progress, 1.0, f"{version} {'promoted' if promoted else 'saved but not promoted'}")
            return {"version": version, "promoted": promoted, "kind": "full", "before": before, "after": after, "force": force,
                    "force_reason": reason, "device": info.get("device"), **meta}

        def _install_full(self, version, enc, enc_path, scaler, base_index, site, cal, head, heldout, raws) -> None:
            """Swap the running model to a promoted full retrain and store engineer embeddings in the new space."""
            from .encoder import _CACHE
            _CACHE.pop(str(Path(enc_path).resolve()), None)
            # Drop the staging-dir encoder from the cache; the version folder is the one to keep.
            _CACHE.pop(str(Path(enc.path).resolve()), None)
            enc.path = Path(enc_path)
            _CACHE[str(Path(enc_path).resolve())] = enc
            for cid, raw in raws:
                self.labels.save_embedding(cid, raw)
            with self._lock:
                self.encoder = enc
                self.encoder_version = version
                self.scaler = scaler
                self.base_index = base_index
                self.site_index = site
                self._index = None
                self.cal = cal
                self.head = head
                self.head_version = version
                self.heldout = {k: np.asarray(v) for k, v in heldout.items()}
            self._marker_path().parent.mkdir(parents=True, exist_ok=True)
            self._marker_path().write_text(self._encoder_stamp(), encoding="utf-8")
            self.registry.activate(version)

        def _full_arrays(self, progress: Optional[Callable[[float, str], None]] = None) -> Dict[str, Any]:
            """Canonical windows for a full retrain: synthetic train / val / test plus engineer-labeled CSVs.

            Validation and test stay the synthetic splits, so held-out accuracy is
            comparable with the shipped model. Engineer cases join the training split
            only. A new signature the engineer named becomes a class when at least one
            labeled case carries it.
            """
            from ..config import frame_maps_for, frame_of_row
            from ..data import load_csv
            from .dataset import cached_features, load_manifest
            from .features import canonical
            from .taxonomy import BASE_SIGNATURES

            root = Path(self.settings.data_dir) / "e2e" / "dataset"
            if not (root / "manifest.jsonl").is_file():
                raise FileNotFoundError(
                    f"synthetic dataset not found at {root} — a full retrain needs it "
                    f"(python scripts/generate_scenario_csvs.py --dataset {root})"
                )
            self._progress(progress, 0.03, "Loading canonical windows")
            rows = load_manifest(root)
            X = cached_features(root, rows, e2e_dir(self.settings) / "cache")
            split = np.array([r["split"] for r in rows])
            sig = np.array([r["signature"] for r in rows])
            tr = np.flatnonzero(split == "train")
            va = np.flatnonzero(split == "val")
            te = np.flatnonzero(split == "test")
            if len(tr) == 0 or len(va) == 0 or len(te) == 0:
                raise FileNotFoundError(f"{root} is missing a train, val or test split")
            engineer = []
            extra_sigs = []
            for lab in self.labels.latest().values():
                if lab.get("signature") in (None, NOVEL):
                    continue
                src = Path(lab.get("csv_path") or "")
                if not src.is_file():
                    continue
                engineer.append({
                    "case_id": lab["case_id"],
                    # frame_spec: the Other / custom tags this case was analyzed with (absent otherwise).
                    "x": canonical(load_csv(src, frame=lab.get("frame_type") or None,
                                           frame_maps=frame_maps_for(self.settings.data_dir, lab.get("frame_type"),
                                                                     spec=lab.get("frame_spec")))).x,
                    "record": self._site_record(lab),
                })
                extra_sigs.append(lab["signature"])
            classes = list(BASE_SIGNATURES) + [s for s in sorted(set(extra_sigs)) if s not in BASE_SIGNATURES]

            def _y(indexes: np.ndarray) -> np.ndarray:
                """Function _y."""
                out = []
                for s in sig[indexes]:
                    if s not in classes:
                        raise ValueError(f"signature {s} is in the synthetic split but not in the class list")
                    out.append(classes.index(s))
                return np.array(out, dtype=np.int64)

            Xtr, ytr = X[tr], _y(tr)
            if engineer:
                Xe = np.stack([e["x"] for e in engineer]).astype(np.float32)
                ye = np.array([classes.index(e["record"]["signature"]) for e in engineer], dtype=np.int64)
                Xtr = np.concatenate([Xtr, Xe])
                ytr = np.concatenate([ytr, ye])
            # Score the same held-out cases, in the same order, as the active model, so before/after compare.
            order = list(te)
            sig_te = sig[te]
            case_te = np.array([rows[i]["case_id"] for i in te])
            rules_te = np.array(["escalate"] * len(te))
            if self.heldout is not None and "case_id" in self.heldout and "rules_action" in self.heldout:
                by_id = {rows[i]["case_id"]: int(i) for i in te}
                ids = [str(c) for c in self.heldout["case_id"]]
                if len(ids) == len(self.heldout["rules_action"]) and all(c in by_id for c in ids):
                    order = [by_id[c] for c in ids]
                    case_te = np.array(ids)
                    sig_te = np.array([rows[i]["signature"] for i in order])
                    rules_te = np.asarray(self.heldout["rules_action"])
            train_records = [
                {"id": rows[i]["case_id"], "signature": rows[i]["signature"], "action": rows[i]["action"],
                 "source": "synthetic", "frame_type": frame_of_row(rows[i])}
                for i in tr
            ]
            return {
                "Xtr": Xtr, "ytr": ytr, "Xva": X[va], "yva": _y(va), "yva_labels": list(sig[va]),
                "va_frames": [frame_of_row(rows[i]) for i in va],
                "classes": classes, "train_records": train_records, "engineer": engineer,
                "Xte": X[np.array(order)], "sig_te": sig_te, "rules_te": np.asarray(rules_te), "case_te": case_te,
                "te_frames": [frame_of_row(rows[i]) for i in order],
            }
# >>>>>>> END sentinel.e2e.engine

# =============================================================================
# sentinel.e2e.pipeline
# Learned path end to end: features, decide, rules in shadow, report, save.
# =============================================================================
# <<<<<<< SECTION sentinel.e2e.pipeline sentinel/e2e/pipeline.py
if False:  # compiled by exec_section('sentinel.e2e.pipeline'); not executed as part of this module
    """Learned path end to end: CSV + analytic + notes -> DRAFT Tier 2 report (rules in shadow).

        analyze_case()  learned decision (TS Pulse + head + similarity/novelty), rule path in shadow,
                        guardrails, deterministic narrative; optional LLM report writer
        write_report()  run / re-run the LLM report writer on a saved case
        label_case()    engineer review = label (signature + action + Good/Not good + note): updates
                        the report, the feedback log and the similarity index, may trigger a retrain
    """

    # @@future@@ from __future__ import annotations

    import json
    import time
    from datetime import datetime
    from pathlib import Path
    from typing import Any, Callable, Dict, List, Optional, Union

    from .. import APP_NAME, __version__, store
    from ..analytics import normalise
    from ..analytics.base import ACTIONS, CAUSES
    from ..config import Settings, load_settings, merged_frame_maps
    from ..data import load_csv
    from ..notes import parse_notes
    from . import residual as resid
    from .engine import Engine
    from .features import canonical
    from .report import bottom_line, render_markdown, template_narrative
    from .taxonomy import NOVEL, info as sig_info

    SCHEMA = "sentinel.e2e.report/1"
    Progress = Callable[[str, float], None]
    _ENGINES: Dict[str, Engine] = {}


    def _noop(_m: str, _f: float) -> None:
        """Function _noop."""
        return None


    def get_engine(settings: Settings) -> Engine:
        """Open the learned engine. In peralert mode, migrate stored labels once before the first decision."""
        key = f"{Path(settings.e2e_model_dir).resolve()}|{Path(settings.data_dir).resolve()}"
        if key not in _ENGINES:
            _ENGINES[key] = Engine(settings)
        eng = _ENGINES[key]
        # The cache key does not include e2e_mode. Check the settings on this call.
        # Legacy mode must not write a map. migrate_profiles does not call back here.
        if getattr(settings, "e2e_mode", "legacy") == "peralert" and not getattr(eng, "_migration_done", False):
            from .migrate import ensure_migrated

            eng.migration_banner = ensure_migrated(settings)
            eng._migration_done = True
        return eng


    def _label(c: float) -> str:
        """Function _label."""
        return "High" if c >= 0.75 else ("Medium" if c >= 0.5 else "Low")


    def _guardrails(case: Any, feats: Any, learned_sig: str, rules: Dict[str, Any]) -> List[Dict[str, str]]:
        """Rule / physics checks that the learned answer must not silently override."""
        g: List[Dict[str, str]] = []
        q = case.quality
        if q.get("rows", 0) < 200:
            g.append({"id": "GR-DATA", "message": f"only {q.get('rows')} rows — too short for reliable baselines"})
        if feats.meta.get("layout") == "none":
            g.append({"id": "GR-CHAN", "message": "no exhaust TC ring or zone temperatures found — exhaust signatures cannot be seen"})
        if q.get("flatlined_channels"):
            g.append({"id": "GR-FLAT", "message": "flatlined channels: " + ", ".join(q["flatlined_channels"][:6])})
        trip = any(e["channel"] == "trip" for e in feats.excursions)
        if trip and learned_sig in ("normal", "igv_lvdt_drift", "fuel_control_oscillation"):
            g.append({"id": "GR-TRIP", "message": "a trip is present in the data but the learned signature does not explain a trip"})
        if rules.get("detected") and rules.get("rule_confidence", 0) >= 0.75 and learned_sig == "normal":
            g.append({"id": "GR-RULE", "message": f"the rule path confirms an event with high confidence ({rules.get('summary', '')[:120]})"})
        return g


    def _run_rules(raw: bytes, analytic: str, notes: str, settings: Settings, name: str) -> Dict[str, Any]:
        """Function _run_rules."""
        from ..pipeline import run_case

        s = load_settings({"data_dir": settings.data_dir, "use_llm": False, "use_tspulse": False})
        try:
            r = run_case(raw, analytic, notes, settings=s, source_name=name, save=False)
        except Exception as exc:  # noqa: BLE001 — shadow must never break the learned report
            return {"error": f"{type(exc).__name__}: {exc}"}
        d, f = r["decision"], r["findings"]
        return {
            "primary_action": d["primary_action"],
            "secondary_actions": d["secondary_actions"],
            "cause": d["cause"],
            "cause_title": d["cause_title"],
            "hypothesis": d["hypothesis"],
            "confidence": d["confidence"],
            "rule_confidence": d["confidence"],
            "needs_human": d["needs_human"],
            "review_flags": d["review_flags"][:6],
            "rules_fired": d["rules_fired"],
            "summary": f["summary"],
            "detected": f["detected"],
            "analyzer_version": f["analyzer_version"],
            "analytic_resolved": r["analytic"]["resolved"],
            "analyzer_path": "built-in analyzer" if r["analytic"].get("known") else "generic fallback",
            "urgency": d["urgency"],
            "escalate": d["escalate"],
        }


    def _channel_scaler(engine: Engine, embedder: str = ""):
        """The shared 48-d scaler of the space this vector is in.

        A TS Pulse vector gets ``channel_scaler.npz``. A stats vector gets the
        statistical scaler its bundle was built with (``stats_scaler``), or the
        identity (L2 only) when the encoder folder has none. A missing file must
        not look like a fitted zero-variance scaler.
        """
        import numpy as np

        from .model import ChannelScaler
        from .train import stats_scaler

        identity = ChannelScaler(np.zeros(48, dtype=np.float64), np.ones(48, dtype=np.float64))
        name = embedder or getattr(engine.settings, "embedder", "") or ""
        if name != "tspulse_ci":
            return stats_scaler(engine.settings)
        folder = engine.registry.encoder_folder(engine.registry.current_encoder())
        path = Path(folder) / "channel_scaler.npz"
        if path.is_file():
            return ChannelScaler.load(path)
        return identity


    def _embed_profile_windows(x, mask, settings: Settings):
        """Both embedders. The index uses the one ``settings.embedder`` names.

        ``stats`` is stored even when the channel-independent encoder ran, so a later
        fallback can score the case without embedding it again. A failed ``tspulse_ci``
        load is the statistical vector with ``fallback`` set. ``legacy14`` is not a
        per-channel space and falls back the same way.
        """
        import numpy as np

        from .encoder import get_embedder

        use = np.asarray(mask if mask is not None else np.ones(np.asarray(x).shape[-1], dtype=bool), dtype=bool)
        try:
            active = get_embedder(settings=settings)
            if getattr(active, "name", "") == "legacy14":
                raise RuntimeError(getattr(active, "fallback_reason", "legacy14 is not a per-channel embedder"))
            vectors = np.asarray(active.embed_channels(x, use), dtype=np.float32)
        except Exception as exc:  # noqa: BLE001 — a missing encoder must not stop the report
            active = get_embedder("stats")
            active.fallback = True
            active.fallback_reason = f"TS Pulse unavailable ({type(exc).__name__})"
            vectors = np.asarray(active.embed_channels(x, use), dtype=np.float32)
        fallback = bool(getattr(active, "fallback", False))
        reason = str(getattr(active, "fallback_reason", "") or "")
        if getattr(active, "name", "") == "stats":
            stats_e = vectors
            pulse_e = np.zeros_like(stats_e)
            return stats_e, pulse_e, stats_e, "stats", fallback, reason
        stats_e = np.asarray(get_embedder("stats").embed_channels(x, use), dtype=np.float32)
        return vectors, vectors, stats_e, str(getattr(active, "name", "tspulse_ci")), fallback, reason


    def _profile_model_for(engine: Engine, profile_id: str, channels: int, weights=None, embedder: str = ""):
        """The cached model when its channel count and embedder match. Otherwise an empty cold model.

        A layout change (different channel count) drops the cached index. Those rows
        were embedded on the old channel list and must not be compared with the new one.
        A ``tspulse_ci`` bundle is not used for a ``stats`` vector, or the other way around.
        """
        import numpy as np

        from .model import ProfileModel

        active = embedder or str(getattr(engine.settings, "embedder", "") or "")
        cached = engine.profile_cache.get(profile_id)
        if cached is not None and int(cached.index.channels) == int(channels):
            recorded = str(getattr(cached, "embedder", "") or "")
            if not active or not recorded or recorded == active:
                return cached
        from .train import load_profile_model

        model = load_profile_model(engine.settings, profile_id, channels=int(channels), embedder=active or None)
        if model is None:
            model = ProfileModel.empty(profile_id, channels=int(channels))
            if weights is not None and int(channels):
                model.index.weights = np.asarray(weights, dtype=np.float32).reshape(int(channels))
            model.embedder = active
        elif active and not getattr(model, "embedder", ""):
            model.embedder = active
        engine.profile_cache.put(profile_id, model)
        return model


    def _profile_packet(profile, resolved, case, why: str, dec: Dict[str, Any], embedder_name: str, channels_hash: str, mask) -> Dict[str, Any]:
        """The alert-type block stored on the report. Slot tags are the ones this file resolved."""
        import numpy as np

        present = int(np.count_nonzero(mask)) if mask is not None else 0
        total = int(np.asarray(mask).size) if mask is not None else 0
        sims = dec.get("similar") or []
        if sims and sims[0].get("channels"):
            compared = f"{sims[0].get('common', present)} of {sims[0].get('channels', total)}"
        else:
            compared = f"{present} of {total}"
        claimed: List[str] = []
        slots: List[Dict[str, Any]] = []
        for slot in profile.slots:
            hit = resolved.by_id(slot.id)
            tags = list(hit.tags) if hit is not None else []
            claimed.extend(tags)
            slots.append(
                {
                    "slot": slot.id,
                    "role": slot.role,
                    "label": slot.label or slot.id,
                    "unit": slot.unit or "",
                    "load_fit": bool(slot.load_fit),
                    "tags": tags,
                    "status": hit.status if hit is not None else "missing",
                }
            )
        claimed_set = set(claimed)
        other = [col for col in getattr(case, "numeric_columns", []) if col not in claimed_set]
        req = resolved.coverage()["required"]
        opt = resolved.coverage()["optional"]
        warnings = list(resolved.warnings)
        return {
            "id": profile.id,
            "name": profile.name,
            "rev": int(profile.rev),
            "channels_hash": channels_hash,
            "frame_key": resolved.frame_key,
            "tier": dec.get("tier") or "cold",
            "why": why,
            "analyzer": profile.analyzer or "generic",
            "embedder": embedder_name,
            "slots": slots,
            "signatures": [sig for sig in profile.signatures if sig != NOVEL],
            "residual_expect": {
                sig: {"primary": list((row or {}).get("primary") or []), "allowed": list((row or {}).get("allowed") or [])}
                for sig, row in (profile.residual_expect or {}).items()
            },
            "docs": list(profile.docs or []),
            "other_tags": other,
            "coverage": {"required": f"{req[0]}/{req[1]}", "optional": f"{opt[0]}/{opt[1]}"},
            "warnings": warnings,
            "compared_channels": compared,
        }


    def _ensure_profile_signature(settings: Settings, profile_id: str, signature: str, rev: int):
        """Add a label's signature to the alert type when it is not listed.

        Rev increases by one. The channel list did not change, so stored embeddings stay valid.
        ``_adhoc`` is not a saved alert type. ``novel_pattern`` is never listed.
        """
        if not profile_id or profile_id == "_adhoc" or signature in ("", NOVEL):
            return rev, None
        from ..profiles import load_profiles, save_profile_file

        book = load_profiles(settings=settings)
        prof = book.get(profile_id)
        if prof is None:
            return rev, None
        if signature in prof.signatures:
            return int(prof.rev), None
        prof.signatures = list(prof.signatures) + [signature]
        prof.rev = int(prof.rev) + 1
        prof.source = "file"
        prof.updated = datetime.now().isoformat(timespec="seconds")
        dest = Path(settings.profiles_dir) / f"{profile_id}.json"
        save_profile_file(prof, dest, data_dir=settings.data_dir)
        return prof.rev, f"Added {signature} to alert type {profile_id} (rev {prof.rev}). The channel layout did not change, so this case was not re-embedded."


    def _index_profile_label(engine: Engine, settings: Settings, report: Dict[str, Any], lab: Dict[str, Any]) -> None:
        """Put this label on the alert type's block index now, the same way the legacy path updates its index."""
        import numpy as np

        from .labels import ProfileEmbeddings

        block = report["profile"]
        pid = block["id"]
        stored = ProfileEmbeddings(settings).load(pid, lab["case_id"])
        if stored is None:
            raise ValueError(f"no profile embedding stored for case {lab['case_id']} (analyze it first)")
        name = block.get("embedder") or "stats"
        vec = stored["tspulse"] if name == "tspulse_ci" else stored["stats"]
        if name == "tspulse_ci" and not np.any(vec):
            vec = stored["stats"]
        mask = stored["mask"]
        u = _channel_scaler(engine, name).transform(vec, mask)
        stats_u = _channel_scaler(engine, "stats").transform(stored["stats"], mask) if name == "tspulse_ci" else None
        model = _profile_model_for(engine, pid, int(np.asarray(u).shape[0]), embedder=name)
        model.index.add(
            u,
            mask,
            block.get("frame_key") or "",
            {
                "id": lab["case_id"],
                "signature": lab["signature"],
                "action": lab["action"],
                "source": "engineer",
                "verdict": lab.get("verdict"),
                "note": lab.get("note", ""),
                "why": lab.get("why", ""),
                "reviewer": lab.get("reviewer", ""),
                "time": lab.get("time"),
                "file": lab.get("source_name", ""),
                "frame_type": lab.get("frame_type") or "",
            },
            stats=stats_u,
        )


    def _tag_warnings(profile, resolved) -> List[str]:
        """One line per slot that is missing or masked, plus a coverage line when most are absent.

        The alert type does not change. A missing tag is a problem with this file.
        """
        from ..config import COVERAGE_WARN_FRACTION

        notes: List[str] = []
        present = 0
        total = 0
        for hit in resolved.slots:
            if hit.role == "ignore":
                continue
            total += 1
            if hit.status == "present":
                present += 1
            else:
                notes.append(f"tag {hit.slot_id} of this alert type is not in this file")
        if total and (present / total) < COVERAGE_WARN_FRACTION:
            notes.append(f"this file does not carry most of the {profile.name} tags; check the alert name")
        return notes


    def decide_alert_case(
        case,
        profile,
        resolved,
        settings: Settings,
        engine: Engine,
        *,
        rule_action: Optional[str] = None,
        case_id: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Windows, embed, scale and decide one case on this alert type's model.

        One case at a time, so the app and the acceptance script embed the same
        file the same way. The caller has already selected the alert type. An
        unknown name does not come here, and tags never select a different type.
        """
        import numpy as np

        from ..profiles import channels_hash, compile_channels
        from .features import profile_windows
        from .model import channel_weights

        feats = profile_windows(case, profile, resolved)
        mask = feats.mask if feats.mask is not None else np.ones(feats.x.shape[1], dtype=bool)
        used_e, pulse_e, stats_e, embedder_name, fallback, fallback_reason = _embed_profile_windows(
            feats.x, mask, settings
        )
        weights = channel_weights(profile, compile_channels(profile, resolved))
        chash = channels_hash(profile)
        model = _profile_model_for(engine, profile.id, int(feats.x.shape[1]), weights, embedder=embedder_name)
        scaler = _channel_scaler(engine, embedder_name)
        u = scaler.transform(used_e, mask)
        # The head's second view, scaled the way the bundle's rows were.
        stats_u = _channel_scaler(engine, "stats").transform(stats_e, mask) if embedder_name == "tspulse_ci" else None
        missing_required = any(hit.required and hit.status != "present" for hit in resolved.slots)
        dec = model.decide_profile(
            u,
            mask,
            resolved.frame_key,
            missing_required=missing_required,
            rule_action=rule_action,
            fallback=fallback,
            exclude=[case_id] if case_id else (),
            stats=stats_u,
        )
        if fallback and fallback_reason:
            dec["fallback_reason"] = fallback_reason
        return {
            "feats": feats,
            "mask": mask,
            "pulse_e": pulse_e,
            "stats_e": stats_e,
            "embedder_name": embedder_name,
            "fallback": fallback,
            "fallback_reason": fallback_reason,
            "channels_hash": chash,
            "model": model,
            "decision": dec,
            "missing_required": missing_required,
        }


    def _unknown_name_report(
        *,
        analytic_name: str,
        notes: str,
        raw: bytes,
        name: str,
        case,
        info,
        settings: Settings,
        engine: Engine,
        use_llm: bool,
        run_rules: bool,
        save: bool,
        case_id: Optional[str],
        progress: Progress,
        started: float,
        frame_maps: Optional[Dict[str, Any]],
    ) -> Dict[str, Any]:
        """The learned path does not run. The rule path's action is kept, or escalate.

        Nothing is embedded and no other alert type is tried. The engineer can
        remember the name as an alias, or create an alert type, then label.
        """
        from ..analytics import resolve as resolve_name
        from ..config import custom_frame_spec
        from .writer import knowledge_for

        progress("Unknown alert name; rule path only", 0.35)
        # The keyword table, not the file's tags, decides whether a rule analyzer fired.
        named = resolve_name(analytic_name or "")
        rules = _run_rules(raw, analytic_name, notes, settings, name) if run_rules else {}
        if named.known and named.analytic in {"cold_spot", "combustion_dynamics", "hets_trip"}:
            action = rules.get("primary_action") or "escalate"
        else:
            action = "escalate"
        if action not in ACTIONS:
            action = "escalate"
        flag = (
            f"Unknown alert name {analytic_name!r}. Pick the alert type it belongs to "
            "(the name is remembered), or create a new alert type from this case."
        )
        tax = engine.taxonomy()
        si = sig_info(NOVEL, tax)
        cid = case_id or store.new_case_id()
        learned = {
            "signature": NOVEL,
            "signature_title": si["title"],
            "basis": "unknown_alert_type",
            "novel": True,
            "needs_human": True,
            "confidence": 0.0,
            "note": flag,
            "similar": [],
            "nearest_distance": None,
            "novelty_threshold": None,
            "head_probs": {},
            "head_confidence": 0.0,
            "head_signature": NOVEL,
            "head_version": "none",
            "match_threshold": None,
            "index_size": 0,
            "index_engineer_labels": 0,
            "novelty_threshold_scope": "none",
            "one_shot": False,
            "low_confidence": engine.cal.low_confidence,
            "features": {"layout": "none", "n_sensors": 0, "zoom": "", "missing_roles": []},
            "excursions": [],
            "residual_check": {},
        }
        agree = bool(rules.get("primary_action")) and rules.get("primary_action") == action
        comparison = (
            "Both paths recommend the same action." if agree else
            (f"Rules: {rules.get('primary_action')} ({rules.get('cause_title', '')}); learned: {action} ({si['title']})."
             if rules.get("primary_action") else "Rule path not run.")
        )
        report: Dict[str, Any] = {
            "schema": SCHEMA,
            "mode": "e2e",
            "app": {"name": APP_NAME, "version": __version__},
            "case_id": cid,
            "created": datetime.now().isoformat(timespec="seconds"),
            "case": {"unit": info.unit or None, "frame": info.frame, "frame_type": case.frame_type, "notes": notes, "notes_interpreted": info.interpreted()},
            "analytic": {"entered": analytic_name, "normalised": normalise(analytic_name), "resolved": "e2e", "title": "End-to-end AI", "known": False},
            "input": {
                "source_name": case.source_name,
                "sha256": case.sha256,
                "rows": case.n,
                "columns": case.quality["columns"],
                "start": case.quality["start"],
                "end": case.quality["end"],
                "interval_minutes": case.interval_minutes,
                "quality": case.quality,
                "roles": case.roles,
                "frame_type": case.frame_type,
            },
            "profile": {"id": None, "unknown_name": analytic_name, "selected_by": "unknown", "matched_name": ""},
            "learned": learned,
            "decision": {
                "signature": NOVEL,
                "primary_action": action,
                "classifier_action": si["action"],
                "secondary_actions": [],
                "urgency": si["urgency"],
                "severity": si["severity"],
                "escalate": True,
                "needs_human": True,
                "review_flags": [flag],
                "confidence": 0.0,
                "confidence_label": _label(0.0),
                "cause": si["cause"],
                "cause_title": CAUSES.get(si["cause"], si["cause"]),
                "hypothesis": si["title"],
                "source": "learned",
                "residual_consistency": {"deterministic": "", "reason": "", "points_to": None, "final": ""},
            },
            "shadow": {"rules": rules, "agree": agree, "comparison": comparison},
            "guardrails": [],
            "residual": {"engine": "not_run", "mode": "unknown_alert_type", "channels": [], "events": []},
            "review": {"status": "DRAFT", "feedback": None, "history": []},
        }
        frame_spec = custom_frame_spec(frame_maps, case.frame_type) if frame_maps is not None else None
        if frame_spec:
            report["input"]["frame_spec"] = frame_spec
        report["knowledge"] = knowledge_for(report, tax, folder=settings.knowledge_dir)
        report["narrative"] = template_narrative(report)
        report["audit"] = {
            "encoder": "not run (unknown alert name)",
            "head_version": "none",
            "profile": None,
            "analyzer_path": "rule path only (unknown alert name)",
            "frame_type": case.frame_type,
            "slices": {"by_frame": {}, "by_alert": {}},
            "settings": {k: v for k, v in settings.describe().items() if k != "sources"},
            "narrative_engine": "template (deterministic, built from the learned outputs)",
        }
        extras: Dict[str, str] = {}
        if use_llm:
            extras = _apply_writer(report, settings, tax)
        report["bottom_line"] = bottom_line(report)
        report["audit"]["elapsed_s"] = round(time.monotonic() - started, 1)
        engine.metrics.log(
            "analysis",
            case_id=cid,
            profile="",
            learned_signature=NOVEL,
            learned_action=action,
            rules_action=rules.get("primary_action"),
            agree=agree,
            novel=True,
            confidence=0.0,
            llm=bool(use_llm),
            residual_check="",
            tier="none",
        )
        if save:
            path = save_case(settings, report, raw, extras)
            report["_path"] = str(path)
        progress("Done", 1.0)
        return report


    def _analyze_peralert(
        csv: Union[str, Path, bytes],
        analytic_name: str,
        notes: str,
        *,
        settings: Settings,
        engine: Optional[Engine],
        source_name: Optional[str],
        use_llm: bool,
        run_rules: bool,
        save: bool,
        case_id: Optional[str],
        progress: Progress,
        frame: Optional[str],
        layout: Optional[str],
        frame_maps: Optional[Dict[str, Any]],
        started: float,
        alert_type: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Learned report for one alert type. The 14-channel head is not asked.

        The alert name, or an explicit id, selects the type. Tags never do. An
        unknown name keeps the rule path and does not embed. The decision itself
        is ``decide_alert_case``, one case at a time.
        """
        from ..config import KNN_VOTE_MIN
        from ..profiles import resolve_alert_type, resolve_tags
        from .labels import ProfileEmbeddings, Registry
        from .model import is_synthetic_source

        engine = engine or get_engine(settings)
        raw = Path(csv).read_bytes() if isinstance(csv, (str, Path)) else bytes(csv)
        name = source_name or (Path(csv).name if isinstance(csv, (str, Path)) else "uploaded.csv")
        progress("Loading CSV", 0.05)
        from ..config import frame_maps_for

        maps = frame_maps if frame_maps is not None else frame_maps_for(settings.data_dir, frame, layout)
        case = load_csv(raw, name=name, frame=frame, frame_maps=maps)
        info = parse_notes(notes)
        progress("Alert type, profile windows, channel embedding", 0.15)
        # The name selects the alert type. Tags never choose, and two alert types cannot tie.
        choice = resolve_alert_type(analytic_name, explicit=alert_type, settings=settings)
        if choice.profile is None:
            return _unknown_name_report(
                analytic_name=analytic_name,
                notes=notes,
                raw=raw,
                name=name,
                case=case,
                info=info,
                settings=settings,
                engine=engine,
                use_llm=use_llm,
                run_rules=run_rules,
                save=save,
                case_id=case_id,
                progress=progress,
                started=started,
                frame_maps=maps,
            )
        profile = choice.profile
        resolved = resolve_tags(profile, case, frame=case.frame_type)
        for note in _tag_warnings(profile, resolved):
            if note not in resolved.warnings:
                resolved.warnings.append(note)
        why = f"alert type {profile.id} ({choice.how})"
        progress("Residual view for this alert type", 0.2)
        res = resid.score(case, settings, thresholds=engine.cal.residual_thresholds or None, profile=profile, resolved=resolved)
        progress("Rule path in shadow mode", 0.35)
        rules = _run_rules(raw, analytic_name, notes, settings, name) if run_rules else {}
        rule_action = rules.get("primary_action") or None
        progress("Profile tier: cold, nearest labels, or head", 0.45)
        decided = decide_alert_case(
            case,
            profile,
            resolved,
            settings,
            engine,
            rule_action=rule_action,
            case_id=case_id,
        )
        feats = decided["feats"]
        mask = decided["mask"]
        pulse_e = decided["pulse_e"]
        stats_e = decided["stats_e"]
        embedder_name = decided["embedder_name"]
        fallback = decided["fallback"]
        fallback_reason = decided["fallback_reason"]
        chash = decided["channels_hash"]
        model = decided["model"]
        dec = decided["decision"]
        tax = engine.taxonomy()
        sig = dec["signature"]
        si = sig_info(sig, tax)
        packet = _profile_packet(profile, resolved, case, why, dec, embedder_name, chash, mask)
        packet["selected_by"] = choice.how
        packet["matched_name"] = choice.matched
        xc = resid.cross_check(sig, res, profile)
        radius, match, scope = model.radius_for(resolved.frame_key)
        reg = Registry(settings, profile=profile.id)
        version = reg.current()
        meta = dict(feats.meta)
        meta.setdefault("layout", "profile")
        meta.setdefault("n_sensors", int(feats.x.shape[1]))
        meta.setdefault("missing_roles", [hit.slot_id for hit in resolved.slots if hit.required and hit.status != "present"])
        learned = {
            **{k: v for k, v in dec.items()},
            "signature_title": si["title"],
            "low_confidence": engine.cal.low_confidence,
            "features": meta,
            "excursions": feats.excursions[:8],
            "residual_check": xc,
            "head_probs": dec.get("head_probs") or {},
            "head_confidence": float(dec.get("head_confidence") if dec.get("head_confidence") is not None else dec.get("confidence") or 0.0),
            "head_signature": dec.get("head_signature") or sig,
            "head_version": version if model.head is not None else "none",
            "index_size": len(model.index),
            "index_engineer_labels": sum(1 for rec in model.index.records if not is_synthetic_source(rec.get("source")) and not rec.get("held_out")),
            "novelty_threshold": dec.get("novelty_threshold", radius),
            "match_threshold": dec.get("match_threshold", match),
            "novelty_threshold_scope": dec.get("novelty_threshold_scope", scope),
        }
        action = dec.get("primary_action") or si["action"]
        if action not in ACTIONS:
            action = si["action"]
        agree = bool(rules.get("primary_action")) and rules.get("primary_action") == action
        guard = _guardrails(case, feats, sig, rules)
        flags: List[str] = []
        if dec.get("basis") == "cold_start":
            flags.append(dec.get("note") or "No labeled cases for this alert type yet; label this case to teach it.")
        elif dec.get("novel"):
            nd = learned.get("nearest_distance")
            if nd is None:
                flags.append("Novel pattern. No class forced.")
            else:
                flags.append(
                    f"Novel pattern: nearest labeled case is {float(nd):.3f} away "
                    f"(threshold {float(learned['novelty_threshold']):.3f}). No class forced."
                )
        elif dec.get("beyond_radius"):
            nd = learned.get("nearest_distance")
            far = "no labeled case is close" if nd is None else f"nearest labeled case is {float(nd):.3f} away"
            flags.append(
                f"Unfamiliar case: {far} (threshold {float(learned['novelty_threshold']):.3f}), but the head is "
                f"confident ({float(learned['head_confidence']):.2f}, floor {float(dec.get('confidence_floor') or 0.0):.2f}). "
                "Not called novel; confirm the signature."
            )
        if learned["confidence"] < engine.cal.low_confidence and not dec.get("novel") and dec.get("basis") != "cold_start":
            flags.append(f"Low learned confidence ({learned['confidence']:.2f} < {engine.cal.low_confidence:.2f}).")
        if dec.get("vote_share") is not None and float(dec["vote_share"]) < KNN_VOTE_MIN and not dec.get("novel"):
            flags.append(f"Similar cases do not agree (vote share {float(dec['vote_share']):.2f}).")
        for note in resolved.warnings:
            if note not in flags:
                flags.append(note)
        if dec.get("missing_required"):
            flags.append("A required tag for this alert type is missing or masked.")
        if dec.get("embedder_fallback"):
            flags.append("Statistical fallback embedding and the novelty radius is still the prior; confirm the signature.")
        if rules.get("primary_action") and not agree:
            flags.append(f"Learned path ({action}) and rule path ({rules['primary_action']}) disagree.")
        if rules.get("error"):
            flags.append(f"Rule path (shadow) failed: {rules['error']}")
        if dec.get("one_shot") and dec.get("basis") == "one_shot":
            s0 = (dec.get("similar") or [{}])[0]
            flags.append(f"Decision follows one labeled case ({s0.get('id')}, distance {float(s0.get('distance') or 0):.3f}) — one-shot match, confirm it applies.")
        for g in guard:
            flags.append(f"Guardrail {g['id']}: {g['message']}")
        if xc["verdict"] == "contradicts":
            flags.append(f"Residual cross-check contradicts {sig}: {xc['reason']}" + (f" (points to {xc['points_to']})." if xc.get("points_to") else "."))
        needs_human = bool(flags)
        cid = case_id or store.new_case_id()
        if profile.analyzer and profile.analyzer != "generic":
            analyzer_path = f"built-in analyzer ({profile.analyzer})"
        else:
            analyzer_path = "generic fallback (no built-in analyzer; learned model + process knowledge)"
        ho = (reg._meta(version) or {}).get("heldout") or {}
        slices = {"by_frame": ho.get("by_frame") or {}, "by_alert": ho.get("by_alert") or {}}
        comparison = (
            "Both paths recommend the same action." if agree else
            (f"Rules: {rules.get('primary_action')} ({rules.get('cause_title', '')}); learned: {action} ({si['title']})." if rules.get("primary_action") else "Rule path not run.")
        )
        report: Dict[str, Any] = {
            "schema": SCHEMA,
            "mode": "e2e",
            "app": {"name": APP_NAME, "version": __version__},
            "case_id": cid,
            "created": datetime.now().isoformat(timespec="seconds"),
            "case": {"unit": info.unit or None, "frame": info.frame, "frame_type": case.frame_type, "notes": notes, "notes_interpreted": info.interpreted()},
            "analytic": {"entered": analytic_name, "normalised": normalise(analytic_name), "resolved": "e2e", "title": "End-to-end AI", "known": True},
            "input": {
                "source_name": case.source_name,
                "sha256": case.sha256,
                "rows": case.n,
                "columns": case.quality["columns"],
                "start": case.quality["start"],
                "end": case.quality["end"],
                "interval_minutes": case.interval_minutes,
                "quality": case.quality,
                "roles": case.roles,
                "frame_type": case.frame_type,
            },
            "profile": packet,
            "learned": learned,
            "decision": {
                "signature": sig,
                "primary_action": action,
                "classifier_action": si["action"],
                "secondary_actions": [a for a in si.get("secondary", []) if a in ACTIONS and a != "escalate"],
                "urgency": si["urgency"],
                "severity": si["severity"],
                "escalate": bool(si["escalate"] or "escalate" in si.get("secondary", [])),
                "needs_human": needs_human,
                "review_flags": flags,
                "confidence": round(float(learned["confidence"]), 2),
                "confidence_label": _label(float(learned["confidence"])),
                "cause": si["cause"],
                "cause_title": CAUSES.get(si["cause"], si["cause"]),
                "hypothesis": si["title"],
                "source": "learned",
                "residual_consistency": {"deterministic": xc["verdict"], "reason": xc["reason"], "points_to": xc.get("points_to"), "final": xc["verdict"]},
            },
            "shadow": {"rules": rules, "agree": agree, "comparison": comparison},
            "guardrails": guard,
            "residual": {**{k: v for k, v in res.items() if k != "channels"}, "channels": (res.get("channels") or [])[:12]},
            "review": {"status": "DRAFT", "feedback": None, "history": []},
        }
        from ..config import custom_frame_spec

        frame_spec = custom_frame_spec(maps, case.frame_type)
        if frame_spec:
            report["input"]["frame_spec"] = frame_spec
        if xc["verdict"] == "contradicts":
            from .writer import lower_confidence

            lower_confidence(report["decision"], engine.cal.low_confidence, "the residual view contradicts the classifier")
        from .writer import knowledge_for

        report["knowledge"] = knowledge_for(report, tax, folder=settings.knowledge_dir)
        report["narrative"] = template_narrative(report)
        embedder_line = f"{embedder_name} 48-d per channel"
        if fallback:
            embedder_line = f"statistical fallback ({fallback_reason or 'TS Pulse unavailable'})"
        report["audit"] = {
            "encoder": embedder_line,
            "head_version": learned["head_version"],
            "profile": profile.id,
            "profile_rev": int(profile.rev),
            "channels_hash": chash,
            "profile_tier": dec.get("audit"),
            "calibration": {
                "novelty": learned["novelty_threshold"],
                "match": learned["match_threshold"],
                "low_confidence": engine.cal.low_confidence,
                "scope": learned["novelty_threshold_scope"],
            },
            "residual_engine": res.get("engine"),
            "residual_mode": res.get("mode"),
            "knowledge": [k["ref"] for k in report["knowledge"]],
            "narrative_engine": "template (deterministic, built from the learned outputs)",
            "analyzer_path": analyzer_path,
            "frame_type": case.frame_type,
            "slices": slices,
            "settings": {k: v for k, v in settings.describe().items() if k != "sources"},
        }
        extras: Dict[str, str] = {}
        if use_llm:
            progress("LLM writing the report (Gemma 4 12B; minutes on CPU)", 0.55)
            extras = _apply_writer(report, settings, tax)
        report["bottom_line"] = bottom_line(report)
        report["audit"]["elapsed_s"] = round(time.monotonic() - started, 1)
        progress("Saving case", 0.97)
        ProfileEmbeddings(settings).save(
            profile.id,
            cid,
            pulse_e,
            stats_e,
            mask,
            feats.channel_ids,
            chash,
            engine.registry.current_encoder(),
            resolved.to_dict(),
        )
        engine.metrics.log(
            "analysis",
            case_id=cid,
            profile=profile.id,
            learned_signature=sig,
            learned_action=report["decision"]["primary_action"],
            rules_action=rules.get("primary_action"),
            agree=agree,
            novel=bool(dec.get("novel")),
            confidence=report["decision"]["confidence"],
            llm=bool(use_llm),
            residual_check=xc["verdict"],
            tier=packet["tier"],
        )
        if save:
            path = save_case(settings, report, raw, extras)
            report["_path"] = str(path)
        progress("Done", 1.0)
        return report


    def _label_profile(
        settings: Settings,
        case_id: str,
        signature: str,
        action: Optional[str],
        verdict: Optional[str],
        note: str,
        reviewer: str,
        engine: Engine,
        new_signature_title: str,
        why: str,
        report: Dict[str, Any],
        alert_type: Optional[str] = None,
    ) -> Dict[str, Any]:
        """One engineer label on the alert type that analyzed the case.

        The legacy head is not refit from this label. The block index updates
        immediately. After ``e2e_retrain_every`` new labels of this alert type,
        that profile's quick retrain starts in the background.
        """
        from .taxonomy import add_signature

        block = report.get("profile") or {}
        if not block.get("id"):
            entered = str((report.get("analytic") or {}).get("entered") or "")
            if not alert_type:
                raise ValueError(
                    f"unknown alert name {entered!r}; pick the alert type before labeling this case"
                )
            raise ValueError(
                f"unknown alert name {entered!r}; analyze the case again with alert type {alert_type!r} before labeling"
            )
        d = report["decision"]
        tax = engine.taxonomy()
        if signature == d["signature"] and not action:
            action = d["primary_action"]
        action = action or (tax.get(signature) or {}).get("action") or ("escalate" if signature == NOVEL else None)
        if action not in ACTIONS:
            raise ValueError(f"action must be one of {sorted(ACTIONS)} (signature '{signature}' has no default action)")
        if verdict is None:
            verdict = "good" if (signature == d["signature"] and action == d["primary_action"]) else "not_good"
        verdict = verdict.strip().lower().replace(" ", "_")
        if verdict not in ("good", "not_good"):
            raise ValueError("verdict must be good or not_good")
        created = False
        if signature not in tax and signature != NOVEL:
            signature = add_signature(settings.data_dir, signature, action, title=new_signature_title)
            created = True
            tax = engine.taxonomy()
        rev, profile_note = _ensure_profile_signature(settings, block["id"], signature, int(block.get("rev") or 1))
        pred = {"signature": d["signature"], "action": d["primary_action"], "rules_action": report["shadow"]["rules"].get("primary_action")}
        extra = {
            "analytic": report["analytic"]["entered"],
            "notes": report["case"].get("notes", ""),
            "source_name": report["input"]["source_name"],
            "csv_path": str(store.case_dir(settings, case_id) / "input.csv"),
            "frame_type": report.get("input", {}).get("frame_type") or report.get("case", {}).get("frame_type") or "",
            "profile": block["id"],
            "profile_rev": rev,
            "channels_hash": block.get("channels_hash") or "",
            "frame_key": block.get("frame_key") or "",
        }
        if report.get("input", {}).get("frame_spec"):
            extra["frame_spec"] = report["input"]["frame_spec"]
        lab = engine.labels.add(
            {
                "case_id": case_id,
                "signature": signature,
                "action": action,
                "verdict": verdict,
                "note": note.strip(),
                "why": why.strip(),
                "reviewer": reviewer.strip() or "unspecified",
                "predicted_signature": pred.get("signature"),
                "predicted_action": pred.get("action"),
                "rules_action": pred.get("rules_action"),
                **extra,
            }
        )
        if signature != NOVEL:
            _index_profile_label(engine, settings, report, lab)
        accepted = verdict == "good" and pred.get("signature") == signature and pred.get("action") == action
        engine.metrics.log(
            "label",
            case_id=case_id,
            profile=block["id"],
            signature=signature,
            action=action,
            verdict=verdict,
            predicted_signature=pred.get("signature"),
            learned_correct=pred.get("action") == action if pred.get("action") else None,
            learned_signature_correct=pred.get("signature") == signature if pred.get("signature") else None,
            rules_correct=pred.get("rules_action") == action if pred.get("rules_action") else None,
            accepted_without_edit=accepted,
            novel=pred.get("signature") == NOVEL,
            new_signature=created,
            profile_rev=rev,
        )
        fb = {
            "case_id": case_id,
            "time": lab["time"],
            "reviewer": lab["reviewer"],
            "verdict": verdict,
            "reason": note,
            "note": note,
            "why": why,
            "signature": lab["signature"],
            "action": action,
            "corrected_action": action if action != d["primary_action"] else None,
            "report_action": d["primary_action"],
            "final_action": action,
            "analytic": "e2e",
            "analytic_entered": report["analytic"]["entered"],
            "mode": "e2e",
            "learned_signature": d["signature"],
            "rules_action": pred["rules_action"],
            "confidence": d["confidence"],
            "llm_used": report["narrative"]["engine"] != "template",
            "profile": block["id"],
            "profile_rev": rev,
            "channels_hash": extra["channels_hash"],
            "frame_key": extra["frame_key"],
            "profile_note": profile_note,
        }
        report["review"] = {"status": "APPROVED" if verdict == "good" else "REJECTED", "feedback": fb, "history": report["review"].get("history", []) + [fb]}
        if profile_note:
            report["profile"]["signature_added"] = signature
            report["profile"]["rev"] = rev
        save_case(settings, report)
        settings.feedback_file.parent.mkdir(parents=True, exist_ok=True)
        with settings.feedback_file.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(fb, default=str) + "\n")
        from .train import profile_labels_since_retrain, retrain_profile

        pid = str(block["id"])
        n = profile_labels_since_retrain(settings, pid)
        started = False
        # _adhoc is rebuilt from the header every run. It has no version to train.
        if pid != "_adhoc" and n >= max(1, int(settings.e2e_retrain_every)):
            started = engine.worker.start(retrain_profile, settings, pid, trigger=f"auto after {n} new labels", engine=engine)
        return {"label": lab, "retrain_started": started, "labels_since_retrain": n, "profile_note": profile_note, "feedback": fb}


    def analyze_case(
        csv: Union[str, Path, bytes],
        analytic_name: str,
        notes: str = "",
        *,
        settings: Optional[Settings] = None,
        engine: Optional[Engine] = None,
        source_name: Optional[str] = None,
        use_llm: bool = False,
        run_rules: bool = True,
        save: bool = True,
        case_id: Optional[str] = None,
        progress: Progress = _noop,
        frame: Optional[str] = None,
        layout: Optional[str] = None,
        frame_maps: Optional[Dict[str, Any]] = None,
        alert_type: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Learned-path report.

        ``frame`` is a frame model, Other / custom, or a frame added from Teach. Empty detects one
        from the tags. ``layout`` picks a tag layout for Other / custom. ``frame_maps`` is an
        in-memory overlay (typed tags) and is not written to frames.json.

        ``e2e_mode`` ``peralert`` selects the alert type from the alert name (or from
        ``alert_type``) and decides with that type's model. ``profiles`` is not a mode.
        The default stays ``legacy`` until the acceptance step switches the setting.
        """
        t0 = time.monotonic()
        settings = settings or load_settings()
        if settings.e2e_mode == "peralert":
            return _analyze_peralert(
                csv,
                analytic_name,
                notes,
                settings=settings,
                engine=engine,
                source_name=source_name,
                use_llm=use_llm,
                run_rules=run_rules,
                save=save,
                case_id=case_id,
                progress=progress,
                frame=frame,
                layout=layout,
                frame_maps=frame_maps,
                started=t0,
                alert_type=alert_type,
            )
        engine = engine or get_engine(settings)
        raw = Path(csv).read_bytes() if isinstance(csv, (str, Path)) else bytes(csv)
        name = source_name or (Path(csv).name if isinstance(csv, (str, Path)) else "uploaded.csv")
        progress("Loading CSV", 0.05)
        from ..config import frame_maps_for

        maps = frame_maps if frame_maps is not None else frame_maps_for(settings.data_dir, frame, layout)
        case = load_csv(raw, name=name, frame=frame, frame_maps=maps)
        info = parse_notes(notes)
        progress("Canonical channels + TS Pulse embedding", 0.15)
        feats = canonical(case)
        emb = engine.embed(feats.x)
        z = engine.scaler(emb)[0]
        progress("Residual view (TS Pulse reconstruction per sensor)", 0.2)
        res = resid.score(case, settings, thresholds=engine.cal.residual_thresholds or None)
        progress("Classifier head + similar labeled cases + novelty", 0.25)
        spec = (maps or {}).get(case.frame_type) if isinstance(maps, dict) else None
        dec = engine.decide(z, exclude=[case_id] if case_id else (), residual=resid.summary(res),
                            frame=case.frame_type, layout=layout, spec=spec if isinstance(spec, dict) else None)
        tax = engine.taxonomy()
        sig = dec["signature"]
        si = sig_info(sig, tax)
        progress("Rule path in shadow mode", 0.35)
        rules = _run_rules(raw, analytic_name, notes, settings, name) if run_rules else {}

        xc = resid.cross_check(sig, res)
        learned = {
            **{k: v for k, v in dec.items()},
            "signature_title": si["title"],
            "low_confidence": engine.cal.low_confidence,
            "features": feats.meta,
            "excursions": feats.excursions[:8],
            "residual_check": xc,
        }
        action = si["action"]
        agree = bool(rules.get("primary_action")) and rules.get("primary_action") == action
        guard = _guardrails(case, feats, sig, rules)
        flags: List[str] = []
        if dec["novel"] and dec.get("basis") == "residual_novelty":
            ab = ", ".join(f"{g} {v:.0f}" for g, v in sorted((res.get("groups_abnormal") or {}).items(), key=lambda kv: -kv[1])[:3])
            flags.append(f"Novel pattern (residuals): abnormal channels ({ab}) that {dec.get('residual_novelty_from')} does not explain, and the case is "
                         f"only borderline-known (nearest labeled case {dec['nearest_distance']:.3f}, head confidence {dec['head_confidence']:.2f}). No class forced.")
        elif dec["novel"]:
            flags.append(f"Novel pattern: nearest labeled case is {dec['nearest_distance']:.3f} away (threshold {dec['novelty_threshold']:.3f}). No class forced.")
        if dec["confidence"] < engine.cal.low_confidence and not dec["novel"]:
            flags.append(f"Low learned confidence ({dec['confidence']:.2f} < {engine.cal.low_confidence:.2f}).")
        if rules.get("primary_action") and not agree:
            flags.append(f"Learned path ({action}) and rule path ({rules['primary_action']}) disagree.")
        if rules.get("error"):
            flags.append(f"Rule path (shadow) failed: {rules['error']}")
        if dec["one_shot"]:
            s0 = dec["similar"][0]
            flags.append(f"Decision follows one labeled case ({s0['id']}, distance {s0['distance']:.3f}) — one-shot match, confirm it applies.")
        for g in guard:
            flags.append(f"Guardrail {g['id']}: {g['message']}")
        if xc["verdict"] == "contradicts":
            flags.append(f"Residual cross-check contradicts {sig}: {xc['reason']}" + (f" (points to {xc['points_to']})." if xc.get("points_to") else "."))
        needs_human = bool(flags)
        cid = case_id or store.new_case_id()
        from ..analytics import resolve as resolve_analytic

        named = resolve_analytic(analytic_name)
        if rules.get("analyzer_path"):
            analyzer_path = rules["analyzer_path"]
        else:
            analyzer_path = "built-in analyzer" if named.known else "generic fallback"
        if analyzer_path == "generic fallback":
            analyzer_path = "generic fallback (no built-in analyzer; learned model + process knowledge)"
        elif named.known:
            analyzer_path = f"built-in analyzer ({named.analytic})"
        ho = (engine.registry._meta(engine.head_version) or {}).get("heldout") or {}
        slices = {"by_frame": ho.get("by_frame") or {}, "by_alert": ho.get("by_alert") or {}}
        comparison = (
            "Both paths recommend the same action." if agree else
            (f"Rules: {rules.get('primary_action')} ({rules.get('cause_title', '')}); learned: {action} ({si['title']})." if rules.get("primary_action") else "Rule path not run.")
        )
        report: Dict[str, Any] = {
            "schema": SCHEMA,
            "mode": "e2e",
            "app": {"name": APP_NAME, "version": __version__},
            "case_id": cid,
            "created": datetime.now().isoformat(timespec="seconds"),
            "case": {"unit": info.unit or None, "frame": info.frame, "frame_type": case.frame_type, "notes": notes, "notes_interpreted": info.interpreted()},
            "analytic": {"entered": analytic_name, "normalised": normalise(analytic_name), "resolved": "e2e", "title": "End-to-end AI", "known": True},
            "input": {
                "source_name": case.source_name,
                "sha256": case.sha256,
                "rows": case.n,
                "columns": case.quality["columns"],
                "start": case.quality["start"],
                "end": case.quality["end"],
                "interval_minutes": case.interval_minutes,
                "quality": case.quality,
                "roles": case.roles,
                "frame_type": case.frame_type,
            },
            "learned": learned,
            "decision": {
                "signature": sig,
                "primary_action": action,
                "classifier_action": action,
                "secondary_actions": [a for a in si.get("secondary", []) if a in ACTIONS and a != "escalate"],
                "urgency": si["urgency"],
                "severity": si["severity"],
                "escalate": bool(si["escalate"] or "escalate" in si.get("secondary", [])),
                "needs_human": needs_human,
                "review_flags": flags,
                "confidence": round(float(dec["confidence"]), 2),
                "confidence_label": _label(dec["confidence"]),
                "cause": si["cause"],
                "cause_title": CAUSES.get(si["cause"], si["cause"]),
                "hypothesis": si["title"],
                "source": "learned",
                "residual_consistency": {"deterministic": xc["verdict"], "reason": xc["reason"], "points_to": xc.get("points_to"), "final": xc["verdict"]},
            },
            "shadow": {"rules": rules, "agree": agree, "comparison": comparison},
            "guardrails": guard,
            "residual": {**{k: v for k, v in res.items() if k != "channels"}, "channels": (res.get("channels") or [])[:12]},
            "review": {"status": "DRAFT", "feedback": None, "history": []},
        }
        from ..config import custom_frame_spec

        frame_spec = custom_frame_spec(maps, case.frame_type)
        if frame_spec:  # Other / custom tags for this run; label_case copies them onto the label
            report["input"]["frame_spec"] = frame_spec
        if xc["verdict"] == "contradicts":
            from .writer import lower_confidence

            lower_confidence(report["decision"], engine.cal.low_confidence, "the residual view contradicts the classifier")
        from .writer import knowledge_for

        report["knowledge"] = knowledge_for(report, tax, folder=settings.knowledge_dir)
        report["narrative"] = template_narrative(report)
        report["audit"] = {
            "encoder": engine.encoder.description,
            "head_version": dec["head_version"],
            "calibration": {"novelty": engine.cal.novelty_threshold, "match": engine.cal.match_threshold, "low_confidence": engine.cal.low_confidence,
                            "residual_novelty": {"enabled": engine.cal.residual_novelty, "border": engine.cal.novelty_border, "confidence_floor": engine.cal.novelty_conf}},
            "residual_engine": res.get("engine"),
            "residual_mode": res.get("mode"),
            "knowledge": [k["ref"] for k in report["knowledge"]],
            "narrative_engine": "template (deterministic, built from the learned outputs)",
            "analyzer_path": analyzer_path,
            "frame_type": case.frame_type,
            "slices": slices,
            "settings": {k: v for k, v in settings.describe().items() if k != "sources"},
        }
        extras: Dict[str, str] = {}
        if use_llm:
            progress("LLM writing the report (Gemma 4 12B; minutes on CPU)", 0.45)
            extras = _apply_writer(report, settings, tax)
        report["bottom_line"] = bottom_line(report)
        report["audit"]["elapsed_s"] = round(time.monotonic() - t0, 1)
        progress("Saving case", 0.97)
        engine.labels.save_embedding(cid, emb)
        engine.metrics.log(
            "analysis",
            case_id=cid,
            learned_signature=sig,
            learned_action=report["decision"]["primary_action"],
            rules_action=rules.get("primary_action"),
            agree=agree,
            novel=dec["novel"],
            confidence=report["decision"]["confidence"],
            llm=bool(use_llm),
            residual_check=xc["verdict"],
        )
        if save:
            path = save_case(settings, report, raw, extras)
            report["_path"] = str(path)
        progress("Done", 1.0)
        return report


    def _apply_writer(report: Dict[str, Any], settings: Settings, tax: Dict[str, Dict[str, Any]]) -> Dict[str, str]:
        """Function _apply_writer."""
        from . import writer

        try:
            w = writer.write(report, settings, tax)
        except Exception as exc:  # noqa: BLE001 — template narrative stays
            report["audit"]["narrative_engine"] = f"template (LLM failed: {type(exc).__name__}: {str(exc)[:200]})"
            return {}
        report["audit"]["llm"] = w.get("runtime", {})
        extras = {"llm_prompt.txt": w["prompt"], "llm_raw.txt": w.get("raw", "")}
        if not w.get("ok"):
            report["audit"]["narrative_engine"] = f"template (LLM output rejected: {w.get('error')})"
            return extras
        narrative, flags = writer.apply(report, w, tax)
        report["narrative"] = narrative
        d = report["decision"]
        for fl in flags:
            d["review_flags"].append(fl)
        sh = report["shadow"]
        sh["agree"] = bool(sh["rules"].get("primary_action")) and sh["rules"]["primary_action"] == d["primary_action"]
        if not sh["agree"] and sh["rules"].get("primary_action"):
            msg = f"Learned path ({d['primary_action']}) and rule path ({sh['rules']['primary_action']}) disagree."
            d["review_flags"] = [f for f in d["review_flags"] if "disagree" not in f] + [msg]
        elif sh["agree"]:
            d["review_flags"] = [f for f in d["review_flags"] if "disagree" not in f]
        d["needs_human"] = bool(d["review_flags"])
        rt = w.get("runtime", {})
        report["audit"]["narrative_engine"] = (
            f"{rt.get('model_label')} via llama-cpp-python on {rt.get('device', '?').upper()}"
            f"{' (' + str(rt.get('n_gpu_layers')) + ' layers offloaded)' if rt.get('device') == 'gpu' else ''}, temp 0, seed 42, JSON-schema constrained; "
            f"{rt.get('usage', {}).get('prompt_tokens', '?')} prompt + {rt.get('usage', {}).get('completion_tokens', '?')} generated tokens in "
            f"{(rt.get('load_s') or 0) + (rt.get('gen_s') or 0):.0f} s"
            + (f". Device fallback: {rt['fallback']}" if rt.get("fallback") else "")
        )
        return extras


    def save_case(settings: Settings, report: Dict[str, Any], csv_bytes: Optional[bytes] = None, extras: Optional[Dict[str, str]] = None) -> Path:
        """Function save_case."""
        d = store.case_dir(settings, report["case_id"])
        d.mkdir(parents=True, exist_ok=True)
        (d / "report.json").write_text(json.dumps(report, indent=2, default=str), encoding="utf-8")
        (d / "report.md").write_text(render_markdown(report), encoding="utf-8")
        if csv_bytes is not None:
            (d / "input.csv").write_bytes(csv_bytes)
        for name, text in (extras or {}).items():
            if text:
                (d / name).write_text(text, encoding="utf-8")
        dec, fb = report["decision"], report["review"].get("feedback")
        rec = {
            "case_id": report["case_id"],
            "mode": "e2e",
            "created": report["created"],
            "analytic": "e2e",
            "analytic_entered": report["analytic"]["entered"],
            "analytic_norm": report["analytic"]["normalised"],
            "unit": report["case"].get("unit"),
            "source_name": report["input"]["source_name"],
            "signature": {"learned": dec["signature"]},
            "learned_signature": dec["signature"],
            "rules_action": report["shadow"]["rules"].get("primary_action"),
            "agree": report["shadow"]["agree"],
            "novel": report["learned"]["novel"],
            "cause": dec["cause"],
            "rule_action": report["shadow"]["rules"].get("primary_action"),
            "primary_action": dec["primary_action"],
            "confidence": dec["confidence"],
            "needs_human": dec["needs_human"],
            "status": report["review"]["status"],
            "feedback": fb,
        }
        (d / "case.json").write_text(json.dumps(rec, indent=2, default=str), encoding="utf-8")
        return d


    def write_report(settings: Settings, case_id: str, engine: Optional[Engine] = None) -> Dict[str, Any]:
        """Run the LLM report writer on a saved e2e case (on demand, e.g. after a fast batch drop-in)."""
        engine = engine or get_engine(settings)
        report = store.load_report(settings, case_id)
        report["narrative"] = template_narrative(report)
        t0 = time.monotonic()
        extras = _apply_writer(report, settings, engine.taxonomy())
        report["bottom_line"] = bottom_line(report)
        report["audit"]["elapsed_s"] = round(report["audit"].get("elapsed_s", 0) + time.monotonic() - t0, 1)
        save_case(settings, report, None, extras)
        return report


    def label_case(
        settings: Settings,
        case_id: str,
        signature: str,
        action: Optional[str] = None,
        verdict: Optional[str] = None,
        note: str = "",
        reviewer: str = "",
        engine: Optional[Engine] = None,
        new_signature_title: str = "",
        auto_retrain: bool = True,
        why: str = "",
        alert_type: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Engineer review of an e2e case = one label. Good keeps the draft; a different label = Not good.
        ``why``: one sentence on why this is the right label; retrieved with the case for similar cases.
        An unknown-name case is refused until the engineer analyzes it again with an alert type."""
        engine = engine or get_engine(settings)
        report = store.load_report(settings, case_id)
        if settings.e2e_mode == "peralert":
            return _label_profile(
                settings, case_id, signature, action, verdict, note, reviewer, engine, new_signature_title, why, report,
                alert_type=alert_type,
            )
        d = report["decision"]
        tax = engine.taxonomy()
        if signature == d["signature"] and not action:
            action = d["primary_action"]
        action = action or (tax.get(signature) or {}).get("action") or ("escalate" if signature == NOVEL else None)
        if action not in ACTIONS:
            raise ValueError(f"action must be one of {sorted(ACTIONS)} (signature '{signature}' has no default action)")
        if verdict is None:
            verdict = "good" if (signature == d["signature"] and action == d["primary_action"]) else "not_good"
        verdict = verdict.strip().lower().replace(" ", "_")
        if verdict not in ("good", "not_good"):
            raise ValueError("verdict must be good or not_good")
        pred = {"signature": d["signature"], "action": d["primary_action"], "rules_action": report["shadow"]["rules"].get("primary_action")}
        extra = {"analytic": report["analytic"]["entered"], "notes": report["case"].get("notes", ""), "source_name": report["input"]["source_name"],
                 "csv_path": str(store.case_dir(settings, case_id) / "input.csv"),
                 "frame_type": report.get("input", {}).get("frame_type") or report.get("case", {}).get("frame_type") or ""}
        if report.get("input", {}).get("frame_spec"):
            # Other / custom tags: a retrain or re-embed reloads input.csv with these, not the empty custom row.
            extra["frame_spec"] = report["input"]["frame_spec"]
        res = engine.add_label(
            case_id,
            signature,
            action,
            verdict=verdict,
            note=note,
            reviewer=reviewer,
            prediction=pred,
            extra=extra,
            new_signature_title=new_signature_title,
            auto_retrain=auto_retrain,
            why=why,
        )
        lab = res["label"]
        fb = {
            "case_id": case_id,
            "time": lab["time"],
            "reviewer": lab["reviewer"],
            "verdict": verdict,
            "reason": note,
            "note": note,
            "why": why,
            "signature": lab["signature"],
            "action": action,
            "corrected_action": action if action != d["primary_action"] else None,
            "report_action": d["primary_action"],
            "final_action": action,
            "analytic": "e2e",
            "analytic_entered": report["analytic"]["entered"],
            "mode": "e2e",
            "learned_signature": d["signature"],
            "rules_action": pred["rules_action"],
            "confidence": d["confidence"],
            "llm_used": report["narrative"]["engine"] != "template",
        }
        report["review"] = {"status": "APPROVED" if verdict == "good" else "REJECTED", "feedback": fb, "history": report["review"].get("history", []) + [fb]}
        save_case(settings, report)
        settings.feedback_file.parent.mkdir(parents=True, exist_ok=True)
        with settings.feedback_file.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(fb, default=str) + "\n")
        return {**res, "feedback": fb}


    def reject_case(settings: Settings, case_id: str, note: str = "", reviewer: str = "",
                    engine: Optional[Engine] = None) -> Dict[str, Any]:
        """Engineer rejects the draft without naming the right signature (the UI Reject button).

        Labeling the case with the predicted signature and verdict not_good would still put that
        signature into the similarity index and the next retrain, so a rejection would teach the
        rejected answer. Instead the case is labeled NOVEL ("still unknown") with action escalate.
        NOVEL labels set the review status and are logged, but they never enter the index, a
        re-embed, or a retrain. A later label with the right signature replaces this one.
        """
        return label_case(settings, case_id, NOVEL, "escalate", verdict="not_good", note=note, reviewer=reviewer, engine=engine)
